package arcanum.parser

import arcanum.api.Ability
import arcanum.api.Affected
import arcanum.api.CardType
import arcanum.api.Color
import arcanum.api.ColorRef
import arcanum.api.Cost
import arcanum.api.CostObjects
import arcanum.api.CostPart
import arcanum.api.Destination
import arcanum.api.Effect
import arcanum.api.EventPattern
import arcanum.api.EventRole
import arcanum.api.Instructions
import arcanum.api.ManaCost
import arcanum.api.ManaKind
import arcanum.api.ManaProduction
import arcanum.api.Measure
import arcanum.api.Mechanic
import arcanum.api.Modification
import arcanum.api.ObjectFilter
import arcanum.api.Objects
import arcanum.api.PlayKind
import arcanum.api.PlayerFilter
import arcanum.api.Players
import arcanum.api.RecipientFilter
import arcanum.api.Recipients
import arcanum.api.Step
import arcanum.api.Subtype
import arcanum.api.Supertype
import arcanum.api.TargetKind
import arcanum.api.TargetSlot
import arcanum.api.Value
import arcanum.api.Zone

/**
 * Rules-text lines that aren't keyword lines: activated abilities ("[cost]: [effect]") and the static wordings learned
 * so far. Each wording is one rule; a line no rule reads stays [Ability.Unparsed]. [self] holds the names the card
 * calls itself ("this land", its own name).
 */
internal class Sentences(
    private val self: Set<String>,
    private val isSpell: Boolean = false,
    /** chunks 21, 26: another ability of the card refers to cards "exiled with" it, so its exiling effects keep the exiled
     * cards as card memory (CR 607.2a). */
    private val linkedExile: Boolean = false,
) {
    /** mkm chunk 02: the noun of the card's "any number of target [noun]" ("players"), which "for each target beyond the first" counts. */
    var anyNumberOfTargets: String? = null

    /** chunk 40: parsing an activated ability with X in its cost: X is the announced value (CR 107.3a). */
    private var announcedX = false

    /** The card's name or "this land" / "This land" (a sentence may start with it). */
    private fun isSelf(text: String) = text in self || text.replaceFirstChar { it.lowercase() } in self

    /** Lines that are more than one ability. */
    fun multi(line: String): List<Ability>? {
        mh2Multi(line)?.let { return it } // mh2
        tdmMulti(line)?.let { return it } // tdm
        eoeMulti(line)?.let { return it } // eoe
        eclMulti(line)?.let { return it } // ecl
        sosMulti(line)?.let { return it } // sos
        tmtMulti(line)?.let { return it } // tmt
        mshMulti(line)?.let { return it } // msh
        hobMulti(line)?.let { return it } // hob
        mkmMulti(line)?.let { return it } // mkm
        // inr chunk 09: "Grimgrin enters tapped and doesn't untap during your untap step." (two static abilities, CR 614.1c, 502.3)
        Inr.ENTERS_TAPPED_AND_DOESNT_UNTAP.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val tapped = line("${m.groupValues[1]} enters tapped.")?.takeIf { it !is Ability.Unparsed } ?: return@let
            val untap = line("${m.groupValues[1]} doesn't untap during your untap step.")?.takeIf { it !is Ability.Unparsed } ?: return@let
            return listOf(tapped, untap)
        }
        // inr chunk 07: "This spell costs {1} less to cast if you control a Spirit. It also costs {1} less to cast if you control an enchantment."
        // (two reductions, each applying when its condition holds, CR 601.2f)
        Inr.COSTS_LESS_IF_IT_ALSO_COSTS_LESS_IF.matchEntire(line)?.let { m ->
            val first = line(m.groupValues[1])?.takeIf { it !is Ability.Unparsed } ?: return@let
            val second = line("This spell costs ${m.groupValues[3]} less to cast if ${m.groupValues[4]}.")?.takeIf { it !is Ability.Unparsed } ?: return@let
            return listOf(first, second)
        }
        // fdn chunk 07: "During each of your turns, you may play a land and cast a permanent spell of each permanent type from your graveyard.": one
        // permission each turn for a land and for each permanent type (CR 110.4); a card of several types uses the one its player picks
        if (Fdn.PLAY_LAND_AND_EACH_PERMANENT_TYPE_FROM_GRAVEYARD.matches(line)) {
            fun each(how: PlayKind, type: CardType) = Ability.Static(listOf(Mechanic.MayPlay(Zone.Graveyard, perTurn = 1, how = how, holder = PlayerFilter.You)),
                condition = arcanum.api.Condition.YourTurn, affects = Affected.Objects(Objects.Each(Filters.all(ObjectFilter.Type(type),
                    ObjectFilter.InZone(Zone.Graveyard), ObjectFilter.OwnedBy(PlayerFilter.You)))))
            return listOf(each(PlayKind.Play, CardType.Land)) +
                listOf(CardType.Artifact, CardType.Battle, CardType.Creature, CardType.Enchantment, CardType.Planeswalker).map { each(PlayKind.Cast, it) }
        }
        // fdn chunk 09: "During your turn, you may play cards you don't own with stash counters on them from exile, and mana of any type can be spent
        // to cast those spells.": a permission on those cards and the any-type payment for spells cast from exile you don't own (CR 118.14, 609.4b)
        Fdn.PLAY_NOT_OWNED_WITH_COUNTERS_ANY_TYPE.matchEntire(line)?.let { m ->
            val kind = Counters.kind(m.groupValues[1]) ?: return@let
            val notOwned = ObjectFilter.Not(ObjectFilter.OwnedBy(PlayerFilter.You))
            return listOf(
                Ability.Static(listOf(Mechanic.MayPlay(Zone.Exile, PlayKind.Play, holder = PlayerFilter.You)), condition = arcanum.api.Condition.YourTurn,
                    affects = Affected.Objects(Objects.Each(Filters.all(ObjectFilter.InZone(Zone.Exile), notOwned, ObjectFilter.HasCounter(kind, 1))))),
                Ability.Static(listOf(Mechanic.SpendManaAsAnyColor(onlyFor = Filters.all(ObjectFilter.WasCast(Zone.Exile), notOwned), anyType = true)),
                    condition = arcanum.api.Condition.YourTurn, affects = Affected.Players(Players.You)))
        }
        // fdn chunk 10b: "You can't lose the game and your opponents can't win the game." (CR 104.3b, 104.2b): one static for each side
        if (Fdn.CANT_LOSE_AND_OPPONENTS_CANT_WIN.matches(line)) return listOf(
            Ability.Static(listOf(Mechanic.CantLoseGame), affects = Affected.Players(Players.You)),
            Ability.Static(listOf(Mechanic.CantWinGame), affects = Affected.Players(Players.Each(PlayerFilter.Opponent))))
        // fdn chunk 10a: "Skeletons you control and other Zombies you control get +1/+1 and have deathtouch.": the same static on each group
        Fdn.TWO_GROUPS_YOU_CONTROL_GET.matchEntire(line)?.let { m ->
            return listOf(static("${m.groupValues[1]} ${m.groupValues[3]}") ?: return@let, static("${m.groupValues[2].replaceFirstChar { it.uppercase() }} ${m.groupValues[3]}") ?: return@let)
        }
        // fdn chunk 11b: "As this artifact enters, choose a creature type. This artifact enters with a fellowship counter on it for each creature you control of
        // the chosen type.": two replacement abilities on one line (CR 614.12, 607.2d)
        Fdn.AS_ENTERS_CHOOSE_TYPE_THEN.matchEntire(line)?.let { m ->
            return listOf(line("As ${m.groupValues[1]} enters, choose a creature type.") ?: return@let, line(m.groupValues[2]) ?: return@let)
        }
        // fdn chunk 05: "As long as X, Elenda gets +1/+1 and has menace. Elenda gets an additional +5/+5 as long as Y.": two static abilities on one line
        Fdn.TWO_AS_LONG_AS.matchEntire(line)?.let { m ->
            return listOf(static(m.groupValues[1]) ?: return@let, static(m.groupValues[2]) ?: return@let)
        }
        // dgm: "Whenever an opponent casts a spell during your turn and when this creature dies, [effect]": two trigger conditions,
        // the first only during your turn (CR 603.1)
        Gtc.OPPONENT_CASTS_DURING_YOUR_TURN_AND_DIES.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val first = triggered("Whenever an opponent casts a spell during your turn, ${m.groupValues[2]}") ?: return null
            val second = triggered("When ${m.groupValues[1]} dies, ${m.groupValues[2]}") ?: return null
            return listOf(first, second)
        }
        // gtc chunk 12: "… into their graveyard. X can't be 0." on a spell's line: the instructions and a rule of the card (CR 107.3)
        if (isSpell && line.endsWith(" X can't be 0.") && line != "X can't be 0.") {
            val spell = spell(line.removeSuffix(" X can't be 0.")) ?: return null
            return listOf(spell, Ability.Static(listOf(Mechanic.XAtLeast(1)), affects = Affected.Objects(Objects.Self)))
        }
        // dsk chunk 14: "This land enters tapped. As it enters, choose a color." (two replacement effects, CR 614.1c, 614.12)
        ENTERS_TAPPED_AS_IT_ENTERS.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val tapped = static("${m.groupValues[1]} enters tapped.") ?: return null
            val choose = static("As ${m.groupValues[1].replaceFirstChar { it.lowercase() }} enters, ${m.groupValues[2]}") ?: return null
            return listOf(tapped, choose)
        }
        // dsk chunk 13: a conditional permission to cast it from the graveyard and a counter when it was (CR 614.1c)
        MAY_CAST_SELF_FROM_GRAVEYARD_IF.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) && isSelf(it.groupValues[3]) }?.let { m ->
            val condition = Conditions.condition(m.groupValues[2], self) ?: return null
            val kind = Counters.kind(m.groupValues[4]) ?: return null
            return listOf(
                Ability.Static(listOf(Mechanic.MayPlay(Zone.Graveyard, PlayKind.Cast, holder = PlayerFilter.You)), affects = Affected.Objects(Objects.Self), condition = condition),
                Ability.Static(listOf(Mechanic.Replacement(EventPattern.ZoneChange(ObjectFilter.Is(Objects.Self), to = Zone.Battlefield),
                    modify = listOf(Modification.EntersWithCounters(kind, Value.Fixed(1))))), affects = Affected.Objects(Objects.Self),
                    condition = arcanum.api.Condition.CastFrom(Zone.Graveyard, Objects.Self)),
            )
        }
        // chunk 25: "Any player may cast creature spells with mana value 3 or less without paying their mana costs and as
        // though they had flash." A permission to cast from hand for free (each player for their own cards) and
        // player-wide flash (CR 601.2a, 118.9, 702.8a).
        MAY_CAST_WITHOUT_PAYING.matchEntire(line)?.let { m ->
            val anyPlayer = m.groupValues[1] == "Any player"
            val spells = Filters.noun(m.groupValues[2].replace(" spells", "")) ?: return null
            val owner = if (anyPlayer) PlayerFilter.Is(Players.Holder) else PlayerFilter.You
            val free = Ability.Static(
                listOf(Mechanic.MayPlay(Zone.Hand, withoutPaying = true, holder = if (anyPlayer) PlayerFilter.Any else PlayerFilter.You, how = PlayKind.Cast)),
                affects = arcanum.api.Affected.Objects(Objects.Each(Filters.all(spells, ObjectFilter.InZone(Zone.Hand), ObjectFilter.OwnedBy(owner)))))
            if (m.groupValues[3].isEmpty()) return listOf(free)
            val players = if (anyPlayer) Players.Each(PlayerFilter.Any) else Players.You
            return listOf(free, Ability.Static(listOf(Mechanic.CastAsThoughFlash(spells)), affects = arcanum.api.Affected.Players(players)))
        }
        // chunk 52: "This creature has all activated abilities of the chosen permanent except for loyalty abilities. You may
        // spend mana as though it were mana of any color to activate those abilities." (layer 6, CR 613.1f)
        HAS_ACTIVATED_ABILITIES_OF.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            // dsk chunk 14: "creatures you control that don't have the same name as this creature"
            val of = chosenObjects(m.groupValues[2]) ?: WITHOUT_SAME_NAME.matchEntire(m.groupValues[2])?.takeIf { isSelf(it.groupValues[2]) }?.let {
                Objects.Each(Filters.all(Filters.noun(it.groupValues[1]) ?: return null, ObjectFilter.Not(ObjectFilter.SameNameAs(Objects.Self))))
            } ?: return null
            val gains = Ability.Static(listOf(Mechanic.GainAbilitiesOf(of, exceptLoyalty = m.groupValues[3].isNotEmpty())), affects = Affected.Objects(Objects.Self))
            if (m.groupValues[4].isEmpty()) return listOf(gains)
            return listOf(gains, Ability.Static(listOf(Mechanic.SpendManaAsAnyColor(onlyFor = ObjectFilter.AbilityOf(source = ObjectFilter.Is(Objects.Self)))),
                affects = arcanum.api.Affected.Players(Players.You)))
        }
        // blb chunk 12: "This land enters tapped. As it enters, choose a color." (two abilities on one line)
        Blb.ENTERS_TAPPED_AS_IT_ENTERS.matchEntire(line)?.let { m ->
            val tapped = line(m.groupValues[1] + " enters tapped.") ?: return null
            val choose = line("As " + m.groupValues[1].replaceFirstChar { it.lowercase() } + " enters, " + m.groupValues[2]) ?: return null
            return listOf(tapped, choose)
        }
        // blb chunk 12: "You may play lands and cast spells with mana value 4 or greater from the top of your library." (two
        // permissions, CR 601.2a, 305.1)
        Blb.MAY_PLAY_LANDS_AND_CAST_FROM_TOP.matchEntire(line)?.let { m ->
            fun top(cards: ObjectFilter, how: PlayKind) = Ability.Static(listOf(Mechanic.MayPlay(Zone.Library, how, topOnly = true, holder = PlayerFilter.You)),
                affects = Affected.Objects(Objects.Each(Filters.all(cards, ObjectFilter.InZone(Zone.Library), ObjectFilter.OwnedBy(PlayerFilter.You)))))
            val comparison = if (m.groupValues[2] == "greater") arcanum.api.Comparison.AtLeast else arcanum.api.Comparison.AtMost
            return listOf(top(ObjectFilter.Type(arcanum.api.CardType.Land), PlayKind.Play),
                top(Filters.all(ObjectFilter.Not(ObjectFilter.Type(arcanum.api.CardType.Land)), ObjectFilter.ManaValue(comparison, Value.Fixed(m.groupValues[1].toInt()))), PlayKind.Cast))
        }
        return null
    }

    /** dsk chunk 13: what "that much"/"that many" means after an intervening if that counts something. */
    private var conditionAmount: Value? = null

    /** dsk chunk 13: the amount [condition] counts ("if you sacrificed one or more permanents this turn": how many). */
    private fun amountOf(condition: arcanum.api.Condition): Value? = when (condition) {
        is arcanum.api.Condition.HappenedThisTurn -> Value.EventsThisTurn(condition.event, condition.measure)
        is arcanum.api.Condition.Prime -> condition.value
        is arcanum.api.Condition.And -> condition.all.mapNotNull(::amountOf).lastOrNull()
        else -> null
    }

    /** dsk chunk 11: the card refers to "the discarded card": a discard of its additional cost names it. */
    var discardedCard = false

    /** tla chunk 02: the card is an Aura ("Enchant …"): its spell's target is the enchant slot (CR 303.4a). */
    var enchantSlot = false

    /** tla chunk 04: in an ability another object gives, that object's name ([Objects.Granter]). */
    var granterName: String? = null

    /** chunk 33: what "the exiled card" means on this card (linked abilities, CR 607.2a); null when nothing links. */
    var exiledCard: Objects? = null

    /** chunk 31: what "it" means in the triggered ability being read, and the zone it is in ("you may exile it" in a
     * dies trigger: the new card in the graveyard, CR 400.7). */
    private var triggerIt: Pair<Objects, Zone?>? = null

    /** fdn chunk 01: the ability being read is a state trigger (CR 603.8), which has no event: "it" is this permanent. */
    private var stateTriggerSelf = false

    /** 'You get an emblem with "[quoted]"' (CR 114.2): the emblem's one ability, read with "this emblem" as its self and
     * keeping [quoted] as its printed text (an emblem has only its abilities, CR 114.3: the text is all a player can read
     * of it); null when the ability can't be read. */
    private fun emblem(quoted: String): List<Step>? {
        // inr chunk 01: an ability quoted inside the quoted one is in single quotes; read it as a quoted ability (CR 113.1a)
        val inner = Regex(""" '(.+)'$""").find(quoted)?.takeIf { '"' !in quoted }
        val read = inner?.let { quoted.substring(0, it.range.first) + " \"" + it.groupValues[1] + "\"" } ?: quoted
        val ability = Sentences(setOf("this emblem")).line(read) ?: return null
        return listOf(Step.Do(Effect.CreateEmblem(listOf(with(OracleParser) { ability.withText(quoted) }), players = Players.You)))
    }

    fun line(line: String): Ability? {
        mkmLine(line)?.let { return it } // mkm
        ltrLine(line)?.let { return it } // ltr
        mh2Line(line)?.let { return it } // mh2
        dftLine(line)?.let { return it } // dft
        finLine(line)?.let { return it } // fin
        MechanicWordings.static(line, ::isSelf, OracleParser::keyword) { Sentences(setOf("this creature")).line(it) }?.let { return it }
        mechanicLine(line)?.let { return it }
        // CR 702.55c: "the creature it haunts" triggers in exile
        if (line.contains(" haunts dies")) return MechanicWordings.haunting(triggered(line))
        tdmLine(line)?.let { return it } // tdm
        eoeLine(line)?.let { return it } // eoe
        spmLine(line)?.let { return it } // spm
        tlaLine(line)?.let { return it } // tla
        eclLine(line)?.let { return it } // ecl
        sosLine(line)?.let { return it } // sos
        sosTriggered(line)?.let { return it } // sos
        tmtLine(line)?.let { return it } // tmt
        mshLine(line)?.let { return it } // msh
        hobLine(line)?.let { return it } // hob
        fraLine(line)?.let { return it } // fra
        // chunk 56: a Saga's "I, II — [effect]" is a chapter ability for each listed chapter (CR 714.2b, c)
        CHAPTERS.matchEntire(line)?.let { m ->
            val chapters = m.groupValues[1].split(", ").mapNotNull { ROMAN[it] }
            // fin: "IV — Mega Flare — [effect]": a flavor word after the chapter numbers (CR 207.2d)
            if (chapters.size == m.groupValues[1].split(", ").size)
                return Ability.Triggered(arcanum.api.Trigger.Chapter(chapters), instructions(modeBody(m.groupValues[2])) ?: return null)
        }
        // "Channel — [ability]": an ability word, no rules meaning (CR 207.2c). Keywords with a dash ("Ward—{2}") have
        // no spaces around it.
        ABILITY_WORD.matchEntire(line)?.let { m ->
            val word = m.groupValues[1]
            // Keywords that label an ability (CR 702.142, 702.169, 702.177, 702.178, 702.193): they add rules.
            LABELS[word.lowercase()]?.let { label ->
                return when (val ability = line(m.groupValues[2])) {
                    is Ability.Activated -> ability.copy(label = label)
                    is Ability.Triggered -> ability.copy(label = label)
                    is Ability.Static -> ability.copy(label = label)
                    else -> null
                }
            }
            // chunk 50: flavor words too (CR 207.2d)
            if (!RulesWords.isAbilityOrFlavorWord(word)) return null
            return when (val ability = line(m.groupValues[2])) {
                is Ability.Activated -> ability.copy(abilityWord = word)
                is Ability.Triggered -> ability.copy(abilityWord = word)
                is Ability.Static -> ability.copy(abilityWord = word)
                is Ability.Spell -> ability.copy(abilityWord = word)
                // fin: "Chaosbringer — Equip—Pay 3 life. Activate only once each turn." (a keyword after a flavor word, CR 207.2d)
                is arcanum.api.Keyword -> ability
                else -> null
            }
        }
        return static(line) ?: triggered(line) ?: activated(line) ?: spell(line) ?: fraStaticLate(line) /* fra */ ?: finLate(line) // fin
    }

    // ---- dft: Aetherdrift wordings (regexes in DftWordings.kt), tried first; each reads one wording and falls through

    private fun dftSlot(name: String, filter: ObjectFilter, min: Int = 1, max: Int? = 1) =
        TargetSlot(name, TargetKind.Objects(filter), min = Value.Fixed(min), max = max?.let { Value.Fixed(it) })
    private fun dftUntilEndOfTurn(objects: Objects, mechanics: List<Mechanic>) =
        Step.Do(Effect.ApplyMechanics(mechanics, Affected.Objects(objects), arcanum.api.Duration.EndOfTurn))
    private val dftArtifactCreature = Mechanic.SetTypes(add = listOf(CardType.Artifact, CardType.Creature))
    private fun dftKeywords(text: String): List<Ability>? = text.split(LazyRegexes.AND_LIST).map { OracleParser.keyword(it.trim()) ?: return null }
    private fun dftInYourGraveyard(filter: ObjectFilter) = Filters.all(filter, ObjectFilter.InZone(Zone.Graveyard), ObjectFilter.OwnedBy(PlayerFilter.You))
    /** dft chunk 14: the spell's target "you control" a cost reduction names before the spell is read; [OracleParser] gives it the slot's name. */
    internal val DFT_YOU_CONTROL_TARGET = "dft: target you control"
    /** The subject of a sentence: this object, "it" (this object in its own enters trigger, else what "it" refers to), or "Target …" (a new
     * target slot). */
    private fun dftSubject(subject: String, context: Context): Objects? {
        if (isSelf(subject)) return Objects.Self
        if (subject == "It" || subject == "it") {
            val selfEnters = (context.event as? EventPattern.ZoneChange)?.objects == ObjectFilter.Is(Objects.Self)
            return if (selfEnters || context.it == null) Objects.Self else context.it
        }
        if (subject.startsWith("Target ")) {
            val noun = subject.removePrefix("Target ")
            val name = Filters.slotName(noun)
            context.targets += dftSlot(name, Filters.noun(noun) ?: return null)
            return Objects.Target(name)
        }
        return null
    }

    /** Whole lines. */
    private fun dftLine(line: String): Ability? {
        // dft chunk 01: "During turns other than yours, this Vehicle is an artifact creature." (a static ability with a condition)
        Dft.DURING_OTHER_TURNS.matchEntire(line)?.let { m ->
            val rest = m.groupValues[1].replaceFirstChar { it.uppercase() }
            val inner = dftLine(rest) ?: static(rest) ?: return null
            if (inner !is Ability.Static || inner.condition != null) return null
            return inner.copy(condition = arcanum.api.Condition.Not(arcanum.api.Condition.YourTurn))
        }
        // dft chunk 01: "This Vehicle is an artifact creature." (layer 4, CR 301.7b)
        Dft.IS_AN_ARTIFACT_CREATURE.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            return Ability.Static(listOf(dftArtifactCreature), affects = Affected.Objects(Objects.Self))
        }
        // dft chunk 01: "The Last Ride gets -X/-X, where X is your life total." (layer 7c)
        Dft.GETS_X_WHERE.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val x = Values.value(m.groupValues[4]) ?: return null
            fun signed(sign: String) = if (sign == "-") Value.Times(x, -1) else x
            return Ability.Static(listOf(Mechanic.ModifyPowerToughness(signed(m.groupValues[2]), signed(m.groupValues[3]))), affects = Affected.Objects(Objects.Self))
        }
        // dft chunk 01: "Activated abilities of sources with the chosen name cost {2} more to activate." (the name chosen as it entered,
        // CR 607.2d; CR 601.2f)
        Dft.ABILITIES_OF_CHOSEN_NAME_COST_MORE.matchEntire(line)?.let { m ->
            val what = ObjectFilter.AbilityOf(kind = arcanum.api.AbilityKind.Activated, source = ObjectFilter.RememberedName("name"))
            return Ability.Static(listOf(Mechanic.CostChange(what, arcanum.api.CostChange.More(ManaCost.parse(m.groupValues[1]) ?: return null, Value.Fixed(1)))),
                affects = Affected.Objects(Objects.Self))
        }
        // dft chunk 02: "Each other Vehicle and creature you control enters with an additional +1/+1 counter on it if its mana value is 4 or
        // less. Otherwise, it enters with three additional +1/+1 counters on it." (two replacements by mana value, CR 614.1c)
        Dft.ENTERS_WITH_ADDITIONAL_IF_MV_OTHERWISE.matchEntire(line)?.let { m ->
            val kinds = m.groupValues[1].split(" and ").map { Filters.noun(it) ?: return null }
            val entering = Filters.all(ObjectFilter.Not(ObjectFilter.Is(Objects.Self)), if (kinds.size == 1) kinds.single() else ObjectFilter.Or(kinds),
                ObjectFilter.ControlledBy(PlayerFilter.You))
            val kind = Counters.kind(m.groupValues[2]) ?: return null
            // the same kind both times ("+1/+1 … three additional +1/+1 counters")
            if (m.groupValues[5] != m.groupValues[2]) return null
            val mv = Value.Fixed(m.groupValues[3].toInt())
            fun replacement(comparison: arcanum.api.Comparison, n: Int) = Mechanic.Replacement(EventPattern.ZoneChange(
                Filters.all(entering, ObjectFilter.ManaValue(comparison, mv)), to = Zone.Battlefield), modify = listOf(Modification.EntersWithCounters(kind, Value.Fixed(n))))
            return Ability.Static(listOf(replacement(arcanum.api.Comparison.AtMost, 1),
                replacement(arcanum.api.Comparison.Greater, Numbers.count(m.groupValues[4]) ?: return null)), affects = Affected.Objects(Objects.Self))
        }
        // dft chunk 12: "You may cast this card from your graveyard by paying 2 life and sacrificing an artifact or creature in addition to paying its
        // other costs." (CR 601.2f)
        Dft.MAY_CAST_FROM_GRAVEYARD_BY.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) || it.groupValues[1] == "this card" }?.let { m ->
            val parts = m.groupValues[2].split(" and ").map { gerund ->
                val imperative = when {
                    gerund.startsWith("paying ") -> "Pay " + gerund.removePrefix("paying ")
                    gerund.startsWith("sacrificing ") -> "Sacrifice " + gerund.removePrefix("sacrificing ")
                    gerund.startsWith("discarding ") -> "Discard " + gerund.removePrefix("discarding ")
                    gerund.startsWith("exiling ") -> "Exile " + gerund.removePrefix("exiling ")
                    gerund.startsWith("removing ") -> "Remove " + gerund.removePrefix("removing ") // fdn chunk 08
                    else -> return null
                }
                costPart(imperative) ?: return null
            }.flatten()
            return Ability.Static(listOf(Mechanic.MayPlay(Zone.Graveyard, PlayKind.Cast, holder = PlayerFilter.You, additionalCost = Cost(parts))),
                affects = Affected.Objects(Objects.Self))
        }
        // dft chunk 10: "You may have this creature enter as a copy of an artifact or creature you control." (CR 707.9, 614.1c)
        Dft.MAY_ENTER_AS_COPY.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val of = Filters.noun(m.groupValues[2]) ?: return null
            return Ability.Static(listOf(Mechanic.Replacement(EventPattern.ZoneChange(ObjectFilter.Is(Objects.Self), to = Zone.Battlefield),
                modify = listOf(Modification.EntersAsCopy(of = of, optional = true)))), affects = Affected.Objects(Objects.Self))
        }
        // dft chunk 08: "During your turn, as long as you haven't activated an exhaust ability this turn, you may activate exhaust abilities as
        // though they haven't been activated." (only before beginning to activate one this turn, CR 702.177b)
        Dft.AS_THOUGH_NOT_ACTIVATED.matchEntire(line)?.takeIf { it.groupValues[1] == it.groupValues[2] }?.let { m ->
            val label = LABELS[m.groupValues[1]] ?: return null
            val activated = EventPattern.Activate(ObjectFilter.Any, PlayerFilter.You, manaAbilities = true, label = label)
            return Ability.Static(listOf(Mechanic.AsThoughNotActivated(label)), affects = Affected.Objects(Objects.Each(Filters.all(
                ObjectFilter.Category(arcanum.api.ObjectCategory.Permanent), ObjectFilter.ControlledBy(PlayerFilter.You)))),
                condition = arcanum.api.Condition.And(listOf(arcanum.api.Condition.YourTurn, arcanum.api.Condition.Not(
                    arcanum.api.Condition.HappenedThisTurn(activated, atLeast = 1, measure = Measure.Events)))))
        }
        // dft chunk 08: "Exhaust abilities of other permanents you control cost {2} less to activate." (CR 601.2f, 602.2b)
        Dft.LABEL_ABILITIES_OF_COST_LESS.matchEntire(line)?.let { m ->
            val label = LABELS[m.groupValues[1].lowercase()] ?: return null
            val of = m.groupValues[2]
            val source = if (of.startsWith("other ")) Filters.all(ObjectFilter.Not(ObjectFilter.Is(Objects.Self)), Filters.noun(of.removePrefix("other ")) ?: return null)
                else Filters.noun(of) ?: return null
            return Ability.Static(listOf(Mechanic.CostChange(ObjectFilter.AbilityOf(source = source, label = label),
                arcanum.api.CostChange.Less(ManaCost.parse(m.groupValues[3]) ?: return null, Value.Fixed(1)))), affects = Affected.Objects(Objects.Self))
        }
        // dft chunk 09: "This spell costs {2} less to cast if it targets a permanent with mana value 1." (CR 601.2f)
        Dft.COSTS_LESS_IF_TARGETS_MV.matchEntire(line)?.takeIf { isSpell }?.let { m ->
            val filter = Filters.all(Filters.noun(m.groupValues[2]) ?: return null, ObjectFilter.ManaValue(arcanum.api.Comparison.Equal, Value.Fixed(m.groupValues[3].toInt())))
            return Ability.Static(listOf(Mechanic.CostChange(ObjectFilter.Is(Objects.Self), arcanum.api.CostChange.Less(ManaCost.parse(m.groupValues[1]) ?: return null, Value.Fixed(1)))),
                affects = Affected.Objects(Objects.Self), condition = arcanum.api.Condition.ObjectMatches(Objects.Target(Filters.slotName(m.groupValues[2])), filter))
        }
        // dft chunk 07: "Hazoret can't attack or block unless you have max speed." (the restrictions while the condition doesn't hold)
        Dft.CANT_ATTACK_OR_BLOCK_UNLESS.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val condition = Conditions.condition(m.groupValues[2], self) ?: return null
            return Ability.Static(listOf(Mechanic.CantAttack(), Mechanic.CantBlock(ObjectFilter.Any)), affects = Affected.Objects(Objects.Self),
                condition = (condition as? arcanum.api.Condition.Not)?.condition ?: arcanum.api.Condition.Not(condition))
        }
        // dft chunk 16: "As long as The Aetherspark is attached to a creature, The Aetherspark can't be attacked and has "…"" (CR 508.1b; layer 6)
        Dft.ATTACHED_CANT_BE_ATTACKED_AND_HAS.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) && isSelf(it.groupValues[2]) }?.let { m ->
            val granted = Sentences(self + setOf("this creature")).line(m.groupValues[3]) ?: return null
            if (granted is Ability.Unparsed) return null
            return Ability.Static(listOf(Mechanic.CantBeAttacked, Mechanic.GainAbilities(listOf(granted))), affects = Affected.Objects(Objects.Self),
                condition = arcanum.api.Condition.ObjectMatches(Objects.AttachedTo(Objects.Self), ObjectFilter.Type(CardType.Creature)))
        }
        // dft chunk 14: "Each creature that's attacking one of your opponents has trample." (attacking a player who is an opponent)
        Dft.EACH_ATTACKING_AN_OPPONENT_HAS.matchEntire(line)?.let { m ->
            val keywords = dftKeywords(m.groupValues[2]) ?: return null
            val attacking = Filters.all(Filters.noun(m.groupValues[1]) ?: return null, ObjectFilter.HasStatus(arcanum.api.Status.Attacking),
                ObjectFilter.ThisTurn(EventPattern.Attack(ObjectFilter.Any, target = RecipientFilter(players = PlayerFilter.Opponent))))
            return Ability.Static(listOf(Mechanic.GainAbilities(keywords)), affects = Affected.Objects(Objects.Each(attacking)))
        }
        // dft chunk 14: "This spell costs {1} less to cast if it targets a Mount or Vehicle you control." (the spell's target you control, CR 601.2f)
        Dft.COSTS_LESS_IF_TARGETS_YOU_CONTROL.matchEntire(line)?.takeIf { isSpell }?.let { m ->
            val filter = Filters.all(Filters.noun(m.groupValues[2]) ?: return null, ObjectFilter.ControlledBy(PlayerFilter.You))
            return Ability.Static(listOf(Mechanic.CostChange(ObjectFilter.Is(Objects.Self), arcanum.api.CostChange.Less(ManaCost.parse(m.groupValues[1]) ?: return null, Value.Fixed(1)))),
                affects = Affected.Objects(Objects.Self), condition = arcanum.api.Condition.ObjectMatches(Objects.Target(DFT_YOU_CONTROL_TARGET), filter))
        }
        // dft chunk 14: "Creatures you control have base power and toughness 6/6 and are Oozes in addition to their other types." (layers 7b, 4)
        Dft.HAVE_BASE_PT_AND_ARE_IN_ADDITION.matchEntire(line)?.let { m ->
            val affected = Filters.noun(m.groupValues[1].replaceFirstChar { it.lowercase() }) ?: return null
            if (m.groupValues[4] !in RulesWords.subtypes) return null
            return Ability.Static(listOf(Mechanic.SetPowerToughness(Value.Fixed(m.groupValues[2].toInt()), Value.Fixed(m.groupValues[3].toInt())),
                Mechanic.SetTypes(addSubtypes = listOf(arcanum.api.SubtypeRef.Literal(Subtype(m.groupValues[4]))))), affects = Affected.Objects(Objects.Each(affected)))
        }
        // dft chunk 15: "As Mimeoplasm enters, exile up to X creature cards from your graveyard. It enters with three +1/+1 counters on it for each
        // creature card exiled this way." (as it enters, CR 614.12; the cards kept as it, CR 607.2a)
        Dft.AS_ENTERS_EXILE_UP_TO_X_COUNTERS_FOR_EACH.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val filter = Filters.noun(m.groupValues[2]) ?: return null
            val kind = Counters.kind(m.groupValues[4]) ?: return null
            val n = Numbers.count(m.groupValues[3]) ?: return null
            val exile = CostPart.Exile(CostObjects.Choose(filter, count = Value.CastX(Objects.Self), upTo = true), from = Zone.Graveyard, postBind = "exiled", remember = EXILED_WITH)
            return Ability.Static(listOf(Mechanic.Replacement(EventPattern.ZoneChange(ObjectFilter.Is(Objects.Self), to = Zone.Battlefield), modify = listOf(
                Modification.AsEnters(listOf(Step.Pay(Cost(listOf(exile)), payer = Players.You, mandatory = true, bind = "paid"),
                    Step.Modify(Modification.EntersWithCounters(kind, Value.Times(Value.Count(Objects.Bound("exiled")), n)))))))), affects = Affected.Objects(Objects.Self))
        }
        // dft chunk 07: "Other creatures you control get +X/+0, where X is your speed." (layer 7c, the speed as it is now)
        Dft.GET_X_WHERE.matchEntire(line)?.let { m ->
            val subject = m.groupValues[1]
            val filter = if (subject.startsWith("Other ")) Filters.all(ObjectFilter.Not(ObjectFilter.Is(Objects.Self)),
                Filters.noun(subject.removePrefix("Other ")) ?: return null) else Filters.noun(subject.replaceFirstChar { it.lowercase() }) ?: return null
            val x = Values.value(m.groupValues[3]) ?: return null
            return Ability.Static(listOf(Mechanic.ModifyPowerToughness(x, Value.Fixed(m.groupValues[2].toInt()))), affects = Affected.Objects(Objects.Each(filter)))
        }
        // dft chunk 07: "Noncreature spells you cast cost {X} less to cast, where X is your speed." (the reduction as {1} X times, CR 601.2f)
        Dft.COST_X_LESS_WHERE.matchEntire(line)?.let { m ->
            val x = Values.value(m.groupValues[2]) ?: return null
            val one = static("${m.groupValues[1]} cost {1} less to cast.") as? Ability.Static ?: return null
            val change = one.mechanics.singleOrNull() as? Mechanic.CostChange ?: return null
            val less = change.change as? arcanum.api.CostChange.Less ?: return null
            return one.copy(mechanics = listOf(change.copy(change = less.copy(times = x))))
        }
        // dft chunk 05: "This creature saddles Mounts and crews Vehicles as though its power were 2 greater." / "… using its toughness rather than its
        // power." (what it counts for as it is tapped to pay those costs, CR 702.171a, 702.122a)
        Dft.SADDLES_AND_CREWS_AS_THOUGH_GREATER.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val n = m.groupValues[2].toInt()
            return Ability.Static(listOf(Mechanic.PowerGreaterFor(arcanum.api.Keyword.Saddle.Kind, n), Mechanic.PowerGreaterFor(arcanum.api.Keyword.Crew.Kind, n)),
                affects = Affected.Objects(Objects.Self))
        }
        Dft.SADDLES_AND_CREWS_USING_TOUGHNESS.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            return Ability.Static(listOf(Mechanic.UsesToughnessFor(arcanum.api.Keyword.Saddle.Kind), Mechanic.UsesToughnessFor(arcanum.api.Keyword.Crew.Kind)),
                affects = Affected.Objects(Objects.Self))
        }
        // dft chunk 02: "Vehicle creatures you control are the chosen creature type in addition to their other types." (the type chosen as it
        // entered, CR 607.2d; layer 4)
        Dft.ARE_THE_CHOSEN_TYPE_IN_ADDITION.matchEntire(line)?.let { m ->
            val affected = Filters.noun(m.groupValues[1]) ?: return null
            return Ability.Static(listOf(Mechanic.SetTypes(addSubtypes = listOf(arcanum.api.SubtypeRef.Remembered("type")))), affects = Affected.Objects(Objects.Each(affected)))
        }
        return null
    }

    /** Cost parts. */
    private fun dftCostPart(text: String): List<CostPart>? {
        // dft chunk 16: "Sacrifice one or more artifacts": X of them, announced as it is activated, X at least 1 (CR 107.3a); the sacrificed ones
        // named for "for each artifact sacrificed this way"
        Dft.SACRIFICE_ONE_OR_MORE.matchEntire(text)?.let { m ->
            val filter = Filters.noun(m.groupValues[1]) ?: return null
            return listOf(CostPart.Sacrifice(CostObjects.Choose(filter, count = Value.Announced("X")), preBind = SACRIFICED))
        }
        // dft chunk 01: "Tap three other untapped creatures you control"
        Dft.TAP_N_OTHER_UNTAPPED.matchEntire(text)?.let { m ->
            val n = Numbers.count(m.groupValues[1]) ?: return null
            val filter = Filters.noun(m.groupValues[2]) ?: return null
            return listOf(CostPart.TapObjects(CostObjects.Choose(Filters.all(ObjectFilter.Not(ObjectFilter.Is(Objects.Self)), filter), count = Value.Fixed(n))))
        }
        return null
    }

    /** Trigger events, with a condition checked as it would trigger. */
    private fun dftTrigger(text: String): Pair<arcanum.api.Trigger.On, arcanum.api.Condition?>? {
        // dft chunk 02: "you activate an exhaust ability" (mana abilities too, CR 702.177a)
        if (text == "you activate an exhaust ability") return arcanum.api.Trigger.On(EventPattern.Activate(ObjectFilter.Any, PlayerFilter.You, manaAbilities = true,
            label = arcanum.api.AbilityLabel.Exhaust)) to null
        // dft chunk 12: "a player casts a spell they don't own" (its owner isn't its controller, the caster)
        if (text == "a player casts a spell they don't own") return arcanum.api.Trigger.On(EventPattern.Cast(ObjectFilter.Not(ObjectFilter.OwnedBy(
            PlayerFilter.Is(Players.ControllerOf(Objects.Tested)))), PlayerFilter.Any)) to null
        // dft chunk 12: "a creature deals combat damage to one of your opponents"
        if (text == "a creature deals combat damage to one of your opponents") return arcanum.api.Trigger.On(EventPattern.Damage(ObjectFilter.Type(CardType.Creature),
            RecipientFilter(players = PlayerFilter.Opponent), combat = true)) to null
        // dft chunk 15: "one or more cards are put into exile from graveyards and/or the battlefield during your turn" (once for the batch)
        if (Dft.CARDS_PUT_INTO_EXILE_FROM_DURING_YOUR_TURN.matches(text)) {
            val card = ObjectFilter.Category(arcanum.api.ObjectCategory.Card)
            return arcanum.api.Trigger.On(listOf(EventPattern.ZoneChange(card, from = Zone.Graveyard, to = Zone.Exile),
                EventPattern.ZoneChange(card, from = Zone.Battlefield, to = Zone.Exile)), oneOrMore = true) to arcanum.api.Condition.YourTurn
        }
        // dft chunk 10: "you cycle this card" (CR 702.29c: from whatever zone it ends up in)
        if (text == "you cycle this card") return arcanum.api.Trigger.On(EventPattern.Cycle(ObjectFilter.Is(Objects.Self), PlayerFilter.You)) to null
        // dft chunk 08: "one or more creatures attack you" (once for the batch, CR 508.3d)
        Dft.ONE_OR_MORE_ATTACK_YOU.matchEntire(text)?.let { m ->
            val filter = Filters.noun(m.groupValues[1]) ?: return null
            return arcanum.api.Trigger.On(EventPattern.Attack(filter, target = RecipientFilter(players = PlayerFilter.You)), oneOrMore = true) to null
        }
        // dft chunk 04: "this creature attacks while saddled": it attacks while it is saddled (CR 702.171b)
        val saddledSelf = Filters.all(ObjectFilter.Is(Objects.Self), DftPhrases.SADDLED)
        Dft.ATTACKS_WHILE_SADDLED.matchEntire(text)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            return arcanum.api.Trigger.On(EventPattern.Attack(saddledSelf)) to null
        }
        // dft chunk 04: "this creature enters and whenever it attacks while saddled" (one ability, two events, CR 603.2)
        Dft.ENTERS_AND_WHENEVER_IT_ATTACKS_WHILE_SADDLED.matchEntire(text)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            return arcanum.api.Trigger.On(listOf(EventPattern.ZoneChange(ObjectFilter.Is(Objects.Self), to = Zone.Battlefield), EventPattern.Attack(saddledSelf))) to null
        }
        // dft chunk 05: "this creature saddles a Mount or crews a Vehicle during your main phase": tapped to pay a saddle or crew cost (CR 702.171c,
        // 702.122b), checked as it would trigger
        Dft.SADDLES_OR_CREWS_DURING_YOUR_MAIN_PHASE.matchEntire(text)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            val main = arcanum.api.Condition.And(listOf(arcanum.api.Condition.YourTurn, arcanum.api.Condition.Or(listOf(
                arcanum.api.Condition.StepIs(arcanum.api.TurnStep.PrecombatMain), arcanum.api.Condition.StepIs(arcanum.api.TurnStep.PostcombatMain)))))
            return arcanum.api.Trigger.On(listOf(EventPattern.Tap(ObjectFilter.Is(Objects.Self), forCost = arcanum.api.Keyword.Saddle.Kind),
                EventPattern.Tap(ObjectFilter.Is(Objects.Self), forCost = arcanum.api.Keyword.Crew.Kind))) to main
        }
        return null
    }

    /** Wordings of several sentences, read as a whole. */
    private fun dftWhole(text: String, context: Context): List<Step>? {
        // dft chunk 01: "For each player, destroy up to one target creature that player controls. If a creature you controlled was destroyed
        // this way, …" (one target for each player, CR 601.2c; the destroyed creatures as they last existed, CR 608.2h)
        Dft.FOR_EACH_PLAYER_DESTROY_UP_TO_ONE.matchEntire(text)?.let { m ->
            val noun = Filters.noun(m.groupValues[1]) ?: return null
            val name = Filters.slotName(m.groupValues[1])
            context.targets += dftSlot(name, Filters.all(noun, ObjectFilter.ControlledBy(PlayerFilter.Is(Players.SlotPlayer))), min = 0).copy(perPlayer = PlayerFilter.Any)
            val yours = Filters.all(Filters.noun(m.groupValues[2]) ?: return null, ObjectFilter.ControlledBy(PlayerFilter.You))
            val then = effect(m.groupValues[3].replaceFirstChar { it.uppercase() }, context) ?: return null
            return listOf(Step.Do(Effect.Destroy(Objects.Target(name), preBind = "destroyed")),
                Step.If(arcanum.api.Condition.Compare(Value.Count(Objects.Where(Objects.Bound("destroyed"), yours)), arcanum.api.Comparison.AtLeast, Value.Fixed(1)),
                    then = then))
        }
        // dft chunk 01: "Gain control of target creature an opponent controls for as long as you control this Vehicle. That creature can't attack or
        // block for as long as you control this Vehicle." (layer 2; the restriction for the same duration)
        Dft.GAIN_CONTROL_AS_LONG_AS_CANT_ATTACK_OR_BLOCK.matchEntire(text)?.takeIf { isSelf(it.groupValues[2]) && isSelf(it.groupValues[3]) }?.let { m ->
            val name = Filters.slotName(m.groupValues[1])
            context.targets += dftSlot(name, Filters.noun(m.groupValues[1]) ?: return null)
            val asLong = arcanum.api.Duration.AsLongAs(arcanum.api.Condition.ObjectMatches(Objects.Self, ObjectFilter.ControlledBy(PlayerFilter.You)))
            val it = Affected.Objects(Objects.Target(name))
            return listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.ControlledBy(Players.You)), it, asLong)),
                Step.Do(Effect.ApplyMechanics(listOf(Mechanic.CantAttack(), Mechanic.CantBlock(ObjectFilter.Any)), it, asLong)))
        }
        // dft chunk 08: "When you next activate an exhaust ability that isn't a mana ability this turn, copy it. You may choose new targets for the
        // copy." (a delayed trigger for this turn, CR 603.7; the copy, CR 707.10)
        if (Dft.NEXT_EXHAUST_COPY_IT.matches(text)) return listOf(Step.Do(Effect.CreateDelayedTrigger(
            arcanum.api.Trigger.On(EventPattern.Activate(ObjectFilter.Any, PlayerFilter.You, label = arcanum.api.AbilityLabel.Exhaust)),
            Instructions(steps = listOf(Step.Do(Effect.CopySpell(Objects.EventObject(EventRole.Object), Players.You, newTargets = true)))),
            duration = arcanum.api.Duration.EndOfTurn)))
        // dft chunk 09: "Reveal cards from the top of your library until you reveal two land cards. Put those land cards onto the battlefield tapped and
        // the rest on the bottom of your library in a random order. …" (CR 701.20)
        Dft.REVEAL_UNTIL_TWO_PUT_REST_BOTTOM.matchEntire(text)?.let { m ->
            val n = Numbers.count(m.groupValues[1]) ?: return null
            val filter = Filters.noun(m.groupValues[2]) ?: return null
            val rest = effect(m.groupValues[4], context) ?: return null
            return listOf(Step.Do(Effect.RevealUntil(filter, Players.You, Value.Fixed(n), reveal = true, foundBind = "found", restBind = "rest")),
                Step.Do(Effect.Move(Objects.Bound("found"), Destination(Zone.Battlefield, tapped = m.groupValues[3].isNotEmpty()))),
                Step.Do(Effect.Move(Objects.Bound("rest"), Destination(Zone.Library, libraryPosition = -1, randomOrder = true)))) + rest
        }
        // dft chunk 09: "Put X +1/+1 counters on Sita Varma. Then you may have the base power and toughness of each other creature you control become
        // equal to Sita Varma's power until end of turn." (its power as this resolves, CR 611.2c)
        Dft.PUT_X_COUNTERS_THEN_MAY_BASE_PT.matchEntire(text)?.takeIf { isSelf(it.groupValues[2]) && isSelf(it.groupValues[3]) }?.let { m ->
            val kind = Counters.kind(m.groupValues[1]) ?: return null
            val power = Value.Of(arcanum.api.NumericProperty.Power, Objects.Self, arcanum.api.Combine.Single)
            return listOf(Step.Do(Effect.PutCounters(Objects.Self, kind, Value.Announced("X"))),
                Step.May(listOf(dftUntilEndOfTurn(Objects.Each(Filters.all(ObjectFilter.Not(ObjectFilter.Is(Objects.Self)), ObjectFilter.Type(CardType.Creature),
                    ObjectFilter.ControlledBy(PlayerFilter.You))), listOf(Mechanic.SetPowerToughness(power, power)))), player = Players.You))
        }
        // dft chunk 07: "You may pay {1}. If you do, copy it." in a cast trigger: the copy keeps the spell's targets (CR 707.10, no new targets)
        Dft.MAY_PAY_IF_YOU_DO_COPY_IT.matchEntire(text)?.takeIf { context.event is EventPattern.Cast }?.let { m ->
            return listOf(Step.Pay(Cost.mana(ManaCost.parse(m.groupValues[1]) ?: return null), payer = Players.You, bind = "paid"),
                Step.If(arcanum.api.Condition.Did("paid"), then = listOf(Step.Do(Effect.CopySpell(Objects.EventObject(EventRole.Object), Players.You, newTargets = false)))))
        }
        // dft chunk 06: "Return target creature or Vehicle an opponent controls to its owner's hand. If that opponent's speed is greater than each
        // other player's speed, reduce that opponent's speed by 1. This effect can't reduce their speed below 1." (the target's controller, CR 702.179)
        Dft.RETURN_THEN_REDUCE_SPEED.matchEntire(text)?.let { m ->
            val name = Filters.slotName(m.groupValues[1])
            context.targets += dftSlot(name, Filters.noun(m.groupValues[1]) ?: return null)
            val that = Players.ControllerOf(Objects.Target(name))
            val others = Value.GreatestFor(Players.Each(PlayerFilter.Not(PlayerFilter.Is(that))), Value.Speed(Players.Tested))
            return listOf(Step.Do(Effect.Move(Objects.Target(name), Destination(Zone.Hand))),
                Step.If(arcanum.api.Condition.Compare(Value.Speed(that), arcanum.api.Comparison.Greater, others), then = listOf(
                    Step.Do(Effect.ReduceSpeed(that, Value.Fixed(Numbers.count(m.groupValues[2]) ?: return null), atLeast = m.groupValues[3].toInt())))))
        }
        // dft chunk 06: "Each opponent sacrifices a creature or Vehicle of their choice. Each opponent who can't discards a card." (each opponent's
        // sacrifice is a mandatory payment, so "can't" is known per opponent, CR 118.12; all at once, CR 101.4)
        Dft.EACH_OPPONENT_SACRIFICES_WHO_CANT_DISCARDS.matchEntire(text)?.let { m ->
            val filter = Filters.noun(m.groupValues[1]) ?: return null
            val opponent = Players.Bound("opponent")
            return listOf(Step.ForEach(arcanum.api.Each.Players(Players.Each(PlayerFilter.Opponent)), bind = "opponent", together = true, steps = listOf(
                Step.Pay(Cost(listOf(CostPart.Sacrifice(CostObjects.Choose(filter, count = Value.Fixed(1))))), payer = opponent, mandatory = true, bind = "sacrificed"),
                Step.If(arcanum.api.Condition.CouldNot("sacrificed"), then = listOf(Step.Do(Effect.Discard(opponent, Value.Fixed(1), ObjectFilter.Any)))))))
        }
        // dft chunk 16: "Attach The Aetherspark to up to one target creature you control. Put a +1/+1 counter on that creature." (CR 701.3)
        Dft.ATTACH_TO_UP_TO_ONE_PUT_COUNTER.matchEntire(text)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val name = Filters.slotName(m.groupValues[2])
            context.targets += dftSlot(name, Filters.noun(m.groupValues[2]) ?: return null, min = 0)
            val kind = Counters.kind(m.groupValues[3]) ?: return null
            return listOf(Step.Do(Effect.Attach(Objects.Self, Recipients(objects = Objects.Target(name)))),
                Step.Do(Effect.PutCounters(Objects.Target(name), kind, Value.Fixed(1))))
        }
        // dft chunk 16: "Choose a color. Target player adds three mana of the chosen color for each artifact sacrificed this way." (CR 106.1)
        Dft.CHOOSE_COLOR_TARGET_PLAYER_ADDS_FOR_EACH_SACRIFICED.matchEntire(text)?.let { m ->
            val player = context.targetPlayer()
            val n = Numbers.count(m.groupValues[1]) ?: return null
            return listOf(Step.Choose(arcanum.api.Choice.Color(), bind = "color", chooser = Players.You),
                Step.Do(Effect.AddMana(ManaProduction(ManaKind.Choose(Value.Times(Value.Count(Objects.Bound(SACRIFICED)), n),
                    colors = listOf(ColorRef.Chosen("color")))), player)))
        }
        // dft chunk 14: "You may search your library and/or graveyard for a creature card with no abilities, reveal it, and put it into your hand. If you
        // search your library this way, shuffle." (no shuffle without searching the library, CR 701.23)
        Dft.MAY_SEARCH_LIBRARY_AND_OR_GRAVEYARD_REVEAL_HAND.matchEntire(text)?.let { m ->
            val filter = Filters.noun(m.groupValues[1]) ?: return null
            return listOf(Step.May(listOf(
                Step.Do(Effect.Search(Players.You, filter, max = Value.Fixed(1), reveal = true, zones = listOf(Zone.Library, Zone.Graveyard), bind = "found", searcher = Players.You)),
                Step.Do(Effect.Move(Objects.Bound("found"), Destination(Zone.Hand))),
                Step.If(arcanum.api.Condition.Searched("found", Zone.Library), then = listOf(Step.Do(Effect.Shuffle(Players.You))))), player = Players.You))
        }
        // dft chunk 14: "You may put a creature or Vehicle card from your hand onto the battlefield. If you put an artifact onto the battlefield this way,
        // put two +1/+1 counters on it."
        Dft.MAY_PUT_FROM_HAND_IF_ARTIFACT_COUNTERS.matchEntire(text)?.let { m ->
            val filter = Filters.all(Filters.noun(m.groupValues[1]) ?: return null, ObjectFilter.InZone(Zone.Hand), ObjectFilter.OwnedBy(PlayerFilter.You))
            val kind = Counters.kind(m.groupValues[3]) ?: return null
            val put = Objects.Bound("put")
            return listOf(Step.Choose(arcanum.api.Choice.Objects(filter, min = Value.Fixed(0), max = Value.Fixed(1)), bind = "chosen", chooser = Players.You),
                Step.Do(Effect.Move(Objects.Bound("chosen"), Destination(Zone.Battlefield), postBind = "put")),
                Step.If(arcanum.api.Condition.ObjectMatches(put, ObjectFilter.Type(CardType.Artifact)), then = listOf(
                    Step.Do(Effect.PutCounters(put, kind, Value.Fixed(Numbers.count(m.groupValues[2]) ?: return null))))))
        }
        // dft chunk 15: "Put target creature card with mana value 4 or less from a graveyard onto the battlefield under your control with a finality
        // counter on it. That creature gains menace, deathtouch, and haste. At the beginning of your next end step, exile that creature." (CR 603.7)
        Dft.PUT_FROM_GRAVEYARD_FINALITY_GAINS_EXILE_NEXT_END.matchEntire(text)?.let { m ->
            context.targets += dftSlot("card", Filters.all(Filters.noun(m.groupValues[1]) ?: return null, ObjectFilter.InZone(Zone.Graveyard)))
            val keywords = dftKeywords(m.groupValues[2]) ?: return null
            val returned = Objects.Bound("returned")
            return listOf(Step.Do(Effect.Move(Objects.Target("card"), Destination(Zone.Battlefield, controller = Players.You,
                    counters = listOf(arcanum.api.CountersToPut(arcanum.api.CounterKind.Finality, Value.Fixed(1)))), postBind = "returned")),
                Step.Do(Effect.ApplyMechanics(listOf(Mechanic.GainAbilities(keywords)), Affected.Objects(returned), arcanum.api.Duration.Indefinitely)),
                Step.Do(Effect.CreateDelayedTrigger(arcanum.api.Trigger.On(EventPattern.StepBegins(arcanum.api.TurnStep.End, PlayerFilter.You)),
                    Instructions(steps = listOf(Step.Do(Effect.Move(returned, Destination(Zone.Exile))))))))
        }
        // dft chunk 15: "Choose target opponent. Create …. Then the chosen player loses X life and you gain X life." (X defined by "where X is")
        Dft.CHOOSE_TARGET_OPPONENT_CREATE_THEN_DRAIN_X.matchEntire(text)?.let { m ->
            val opponent = context.targetOpponent()
            val create = effect(m.groupValues[1], context) ?: return null
            return create + listOf(Step.Do(Effect.LoseLife(opponent, Value.Announced("X"))), Step.Do(Effect.GainLife(Players.You, Value.Announced("X"))))
        }
        // dft chunk 15: "Look at target player's hand. You may choose a card from it. If you do, that player discards that card, then draws a card."
        if (Dft.LOOK_AT_HAND_MAY_CHOOSE_DISCARDS_DRAWS.matches(text)) {
            val player = context.targetPlayer()
            return listOf(Step.Do(Effect.LookAt(Objects.Each(Filters.all(ObjectFilter.InZone(Zone.Hand), ObjectFilter.OwnedBy(PlayerFilter.Is(player)))), Players.You, bind = "seen")),
                Step.Choose(arcanum.api.Choice.Objects(ObjectFilter.Any, Value.Fixed(0), Value.Fixed(1), from = Objects.Bound("seen")), bind = "chosen", chooser = Players.You),
                Step.If(arcanum.api.Condition.NonEmpty("chosen"), then = listOf(
                    Step.Do(Effect.Discard(player, Value.Fixed(1), ObjectFilter.Any, objects = Objects.Bound("chosen"))),
                    Step.Do(Effect.Draw(player, Value.Fixed(1))))))
        }
        // dft chunk 15: "Target creature gets +2/+0 until end of turn for each card discarded this way. Whenever that creature deals combat damage to a
        // player this turn, you draw a card." (CR 603.7b: a delayed trigger for the rest of the turn)
        Dft.GETS_FOR_EACH_DISCARDED_THEN_WHENEVER_DAMAGE.matchEntire(text)?.takeIf { context.event is EventPattern.Discard }?.let { m ->
            context.targets += dftSlot("creature", ObjectFilter.Type(CardType.Creature))
            val target = Objects.Target("creature")
            return listOf(dftUntilEndOfTurn(target, listOf(Mechanic.ModifyPowerToughness(Value.Times(Value.Count(Objects.EventObject(EventRole.After)), m.groupValues[1].toInt()),
                    Value.Fixed(0)))),
                Step.Do(Effect.CreateDelayedTrigger(arcanum.api.Trigger.On(EventPattern.Damage(ObjectFilter.Is(target), RecipientFilter(players = PlayerFilter.Any), combat = true)),
                    Instructions(steps = listOf(Step.Do(Effect.Draw(Players.You, Value.Fixed(1))))), duration = arcanum.api.Duration.EndOfTurn, repeats = true)))
        }
        // dft chunk 12: "Target creature card in your graveyard gains embalm until end of turn. The embalm cost is equal to its mana cost." (CR 702.128a)
        Dft.GAINS_EMBALM_COST_ITS_MANA_COST.matchEntire(text)?.let { m ->
            val name = Filters.slotName(m.groupValues[1])
            val noun = m.groupValues[1].removeSuffix(" in your graveyard")
            val filter = if (noun != m.groupValues[1]) dftInYourGraveyard(Filters.noun(noun) ?: return null) else Filters.noun(noun) ?: return null
            context.targets += dftSlot(name, filter)
            return listOf(dftUntilEndOfTurn(Objects.Target(name), listOf(Mechanic.GainAbilities(listOf(arcanum.api.Keyword.Embalm(Cost(listOf(CostPart.ItsManaCost))))))))
        }
        // dft chunk 12: "Its controller looks at the top card of that opponent's library and exiles it face down. They may play that card for as long as
        // it remains exiled. Mana of any type can be spent to cast a spell this way." (the damaging creature's controller, CR 406.3)
        if (Dft.LOOKS_AT_TOP_EXILES_FACE_DOWN_MAY_PLAY.matches(text) && context.event is EventPattern.Damage) {
            // the creature named now, so the permission (an effect that lasts) knows whose it is (CR 611.2c)
            val controller = Players.ControllerOf(Objects.Bound("creature"))
            return listOf(Step.Bind(Objects.EventObject(EventRole.Source), "creature"),
                Step.Do(Effect.LookAt(Objects.LibraryCards(Players.EventPlayer, Value.Fixed(1), fromTop = true), controller, bind = "looked")),
                Step.Do(Effect.Move(Objects.Bound("looked"), Destination(Zone.Exile, faceDown = true), postBind = "exiled")),
                Step.Do(Effect.ApplyMechanics(listOf(Mechanic.MayPlay(Zone.Exile, PlayKind.Play, holder = PlayerFilter.Is(controller), manaAsAnyColor = true)),
                    Affected.Objects(Objects.Bound("exiled")), arcanum.api.Duration.Indefinitely)))
        }
        // dft chunk 12: "Choose target creature, planeswalker, or Vehicle. Mill two cards, then destroy the chosen permanent if its mana value is less than
        // or equal to the number of cards in your graveyard." (compared as it resolves, after the mill)
        Dft.CHOOSE_TARGET_MILL_DESTROY_IF_MV.matchEntire(text)?.let { m ->
            val name = Filters.slotName(m.groupValues[1])
            context.targets += dftSlot(name, Filters.noun(m.groupValues[1]) ?: return null)
            val graveyard = Value.Count(Objects.Each(Filters.all(ObjectFilter.InZone(Zone.Graveyard), ObjectFilter.OwnedBy(PlayerFilter.You))))
            return listOf(Step.Do(Effect.Mill(Players.You, Value.Fixed(Numbers.count(m.groupValues[2]) ?: return null))),
                Step.If(arcanum.api.Condition.ObjectMatches(Objects.Target(name), ObjectFilter.ManaValue(arcanum.api.Comparison.AtMost, graveyard)),
                    then = listOf(Step.Do(Effect.Destroy(Objects.Target(name))))))
        }
        // dft chunk 13: "Choose target artifact card in your graveyard. You may sacrifice an artifact. If you do, return the chosen card to the
        // battlefield." (CR 118.12)
        Dft.CHOOSE_TARGET_MAY_SACRIFICE_RETURN_CHOSEN.matchEntire(text)?.let { m ->
            val name = Filters.slotName(m.groupValues[1])
            val noun = m.groupValues[1].removeSuffix(" in your graveyard")
            val filter = if (noun != m.groupValues[1]) dftInYourGraveyard(Filters.noun(noun) ?: return null) else Filters.noun(noun) ?: return null
            context.targets += dftSlot(name, filter)
            val sacrifice = costPart("Sacrifice an " + m.groupValues[2]) ?: costPart("Sacrifice a " + m.groupValues[2]) ?: return null
            return listOf(Step.Pay(Cost(sacrifice), payer = Players.You, bind = "paid"),
                Step.If(arcanum.api.Condition.Did("paid"), then = listOf(Step.Do(Effect.Move(Objects.Target(name), Destination(Zone.Battlefield))))))
        }
        // dft chunk 03: "Choose up to one target Vehicle you control. Until end of turn, it becomes …" (the rest about that target)
        Dft.CHOOSE_UP_TO_ONE_TARGET_THEN.matchEntire(text)?.takeIf {
            it.groupValues[2].startsWith("Until end of turn, it ") || Dft.UNTIL_EOT_SADDLED_IF_MOUNT_CREATURE_IF_VEHICLE.matches(it.groupValues[2])
        }?.let { m ->
            val name = Filters.slotName(m.groupValues[1])
            context.targets += dftSlot(name, Filters.noun(m.groupValues[1]) ?: return null, min = 0)
            val target = Objects.Target(name)
            context.it = target
            // "Until end of turn, that permanent becomes saddled if it's a Mount and becomes an artifact creature if it's a Vehicle." (CR 702.171b)
            if (Dft.UNTIL_EOT_SADDLED_IF_MOUNT_CREATURE_IF_VEHICLE.matches(m.groupValues[2])) return listOf(
                Step.If(arcanum.api.Condition.ObjectMatches(target, Filters.noun("Mount") ?: return null), then = listOf(Step.Do(Effect.Mark(target, arcanum.api.ObjectMark.Saddled)))),
                Step.If(arcanum.api.Condition.ObjectMatches(target, Filters.noun("Vehicle") ?: return null), then = listOf(dftUntilEndOfTurn(target, listOf(dftArtifactCreature)))))
            val slots = context.targets.size
            effect(m.groupValues[2], context)?.takeIf { context.targets.size == slots }?.let { return it }
            while (context.targets.size > slots - 1) context.targets.removeAt(context.targets.lastIndex)
            return null
        }
        // dft chunk 03: "Return target artifact card from your graveyard to the battlefield. If it's a Vehicle, it becomes an artifact creature." (for good)
        Dft.RETURN_TARGET_IF_IT_BECOMES.matchEntire(text)?.let { m ->
            context.targets += dftSlot("card", dftInYourGraveyard(Filters.noun(m.groupValues[1]) ?: return null))
            val returned = Objects.Bound("returned")
            return listOf(Step.Do(Effect.Move(Objects.Target("card"), Destination(Zone.Battlefield), postBind = "returned")),
                Step.If(arcanum.api.Condition.ObjectMatches(returned, Filters.noun(m.groupValues[2]) ?: return null), then = listOf(
                    Step.Do(Effect.ApplyMechanics(listOf(dftArtifactCreature), Affected.Objects(returned), arcanum.api.Duration.Indefinitely)))))
        }
        // dft chunk 03: "Return all Mount and Vehicle cards from your graveyard to the battlefield. Sacrifice them at the beginning of the next end
        // step." (a delayed trigger, CR 603.7)
        Dft.RETURN_ALL_THEN_SACRIFICE_THEM.matchEntire(text)?.let { m ->
            val kinds = m.groupValues[1].split(" and ").map { Filters.noun(it) ?: return null }
            val returned = Objects.Bound("returned")
            return listOf(Step.Do(Effect.Move(Objects.Each(dftInYourGraveyard(if (kinds.size == 1) kinds.single() else ObjectFilter.Or(kinds))), Destination(Zone.Battlefield),
                    postBind = "returned")),
                Step.Do(Effect.CreateDelayedTrigger(arcanum.api.Trigger.On(EventPattern.StepBegins(arcanum.api.TurnStep.End, PlayerFilter.Any)),
                    Instructions(steps = listOf(Step.Do(Effect.Sacrifice(returned)))))))
        }
        // dft chunk 05: "Create X 1/1 colorless Pilot creature tokens. The tokens have "…"" (X defined by "where X is", CR 107.3c; CR 111.4)
        Dft.CREATE_X_TOKENS_THEY_HAVE.matchEntire(text)?.let { m ->
            val token = Tokens.defined("a " + m.groupValues[1] + " token") ?: return null
            val granted = Sentences(setOf("this token", "this creature")).line(m.groupValues[2]) ?: return null
            return listOf(Step.Do(Effect.CreateToken(token.copy(face = token.face.copy(abilities = listOf(granted))), Value.Announced("X"), Players.You)))
        }
        // dft chunk 02: "You may search your library for an artifact card and reveal it. Put it onto the battlefield if its mana value is 2 or less.
        // Otherwise, put it into your hand. If you search your library this way, shuffle." (no search, no shuffle, CR 701.23)
        Dft.MAY_SEARCH_REVEAL_PUT_IF_MV_OTHERWISE.matchEntire(text)?.let { m ->
            val found = Objects.Bound("found")
            return listOf(Step.May(listOf(
                Step.Do(Effect.Search(Players.You, Filters.noun(m.groupValues[1]) ?: return null, max = Value.Fixed(1), reveal = true, zones = listOf(Zone.Library),
                    bind = "found", searcher = Players.You)),
                Step.If(arcanum.api.Condition.ObjectMatches(found, ObjectFilter.ManaValue(arcanum.api.Comparison.AtMost, Value.Fixed(m.groupValues[2].toInt()))),
                    then = listOf(Step.Do(Effect.Move(found, Destination(Zone.Battlefield)))), otherwise = listOf(Step.Do(Effect.Move(found, Destination(Zone.Hand))))),
                Step.Do(Effect.Shuffle(Players.You))), player = Players.You))
        }
        return null
    }

    /** Sentences that change the steps before them. */
    private fun dftModify(sentence: String, steps: List<Step>, context: Context): List<Step>? {
        // dft chunk 07: "That token attacks this combat if able." after creating a token (a requirement this combat, CR 508.1d)
        if (Dft.THAT_TOKEN_ATTACKS_THIS_COMBAT.matches(sentence)) {
            val create = ((steps.lastOrNull() as? Step.Do)?.effect as? Effect.CreateToken)?.takeIf { it.bind == null } ?: return null
            return steps.dropLast(1) + Step.Do(create.copy(bind = "token")) + Step.Do(Effect.ApplyMechanics(listOf(Mechanic.MustAttack()),
                Affected.Objects(Objects.Bound("token")), arcanum.api.Duration.EndOfCombat))
        }
        return null
    }

    /** One sentence. */
    private fun dftEffect(sentence: String, context: Context): List<Step>? {
        // dft chunk 01: "Until end of turn, this Vehicle becomes an artifact creature and gains flying." (CR 301.7b, 613.1d, f)
        Dft.UNTIL_EOT_BECOMES_ARTIFACT_CREATURE_AND_GAINS.matchEntire(sentence)?.let { m ->
            val objects = dftSubject(m.groupValues[1], context) ?: return null
            val keywords = dftKeywords(m.groupValues[2]) ?: return null
            context.it = objects
            return listOf(dftUntilEndOfTurn(objects, listOf(dftArtifactCreature, Mechanic.GainAbilities(keywords))))
        }
        // dft chunk 15: "For each opponent, put up to one target nonland permanent that player controls into its owner's library third from the top."
        Dft.FOR_EACH_OPPONENT_PUT_THIRD_FROM_TOP.matchEntire(sentence)?.let { m ->
            val position = (Numbers.ordinal(m.groupValues[2]) ?: return null) - 1
            context.targets += dftSlot(Filters.slotName(m.groupValues[1]), Filters.all(Filters.noun(m.groupValues[1]) ?: return null,
                ObjectFilter.ControlledBy(PlayerFilter.Is(Players.SlotPlayer))), min = 0).copy(perPlayer = PlayerFilter.Opponent)
            return listOf(Step.Do(Effect.Move(Objects.Target(Filters.slotName(m.groupValues[1])), Destination(Zone.Library, libraryPosition = position))))
        }
        // dft chunk 16: "put that many loyalty counters on The Aetherspark." after damage: as many as the damage dealt
        Dft.PUT_THAT_MANY_COUNTERS_ON.matchEntire(sentence)?.takeIf { context.event is EventPattern.Damage && isSelf(it.groupValues[2]) }?.let { m ->
            return listOf(Step.Do(Effect.PutCounters(Objects.Self, Counters.kind(m.groupValues[1]) ?: return null, Value.EventAmount)))
        }
        // dft chunk 16: "Destroy another target artifact." (not this one)
        Dft.DESTROY_ANOTHER_TARGET.matchEntire(sentence)?.let { m ->
            val filter = Filters.all(ObjectFilter.Not(ObjectFilter.Is(Objects.Self)), Filters.noun(m.groupValues[1]) ?: return null)
            val name = Filters.slotName(m.groupValues[1])
            context.targets += dftSlot(name, filter)
            return listOf(Step.Do(Effect.Destroy(Objects.Target(name))))
        }
        // dft chunk 14: "Untap enchanted permanent."
        if (Dft.UNTAP_ENCHANTED_PERMANENT.matches(sentence)) return listOf(Step.Do(Effect.Untap(Objects.AttachedTo(Objects.Self))))
        // dft chunk 14: "Return up to one target creature card, up to one target Mount card, up to one target Vehicle card, and up to one target
        // creature card with no abilities from your graveyard to your hand." (a target for each, CR 115.3)
        Dft.RETURN_UP_TO_ONE_EACH_TO_HAND.matchEntire(sentence)?.let { m ->
            val items = m.groupValues[1].split(LazyRegexes.AND_LIST).map { it.removePrefix("up to one target ").ifEmpty { return null } }
            if (items.size < 2 || m.groupValues[1].split("up to one target ").size - 1 != items.size) return null
            val slots = items.map { item ->
                dftSlot(item, dftInYourGraveyard(Filters.noun(item.replace(" card", "")) ?: return null), min = 0)
            }
            context.targets += slots
            return listOf(Step.Do(Effect.Move(Objects.Union(slots.map { Objects.Target(it.name) }), Destination(Zone.Hand))))
        }
        // dft chunk 15: "Mimeoplasm becomes a copy of target creature card exiled with it, except it's 0/0 and has this ability." (CR 707.9b; the
        // cards it exiled as it entered, CR 607.2a)
        Dft.BECOMES_COPY_OF_EXILED_WITH_EXCEPT.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            context.targets += dftSlot("card", Filters.all(Filters.noun(m.groupValues[2]) ?: return null, ObjectFilter.Is(Objects.Remembered(EXILED_WITH))))
            return listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.CopyOf(Objects.Target("card"), except = listOf(
                arcanum.api.CopyException.PowerToughness(m.groupValues[3].toInt(), m.groupValues[4].toInt()), arcanum.api.CopyException.ThisAbility))),
                Affected.Objects(Objects.Self), arcanum.api.Duration.Indefinitely)))
        }
        // dft chunk 12: "That player creates a Treasure token." (the player of the event)
        Dft.THAT_PLAYER_CREATES.matchEntire(sentence)?.takeIf { context.event is EventPattern.Cast }?.let { m ->
            val (count, token) = Tokens.spec(m.groupValues[1]) ?: return null
            return listOf(Step.Do(Effect.CreateToken(token, Value.Fixed(count), Players.EventPlayer)))
        }
        // dft chunk 13: "After this main phase, there are two additional combat phases." (each right after the one before, CR 500.8)
        Dft.AFTER_THIS_MAIN_PHASE_COMBATS.matchEntire(sentence)?.let { m ->
            return listOf(Step.Repeat(Value.Fixed(Numbers.count(m.groupValues[1]) ?: return null), listOf(Step.Do(Effect.ExtraCombat()))))
        }
        // dft chunk 13: "At the beginning of each combat this turn, untap all creatures that attacked this turn." (CR 603.7b: every combat this turn)
        Dft.EACH_COMBAT_THIS_TURN_UNTAP_ATTACKED.matchEntire(sentence)?.let { m ->
            val kind = Filters.noun(m.groupValues[1]) ?: return null
            val attacked = Filters.all(kind, ObjectFilter.ThisTurn(EventPattern.Attack(ObjectFilter.Any)))
            return listOf(Step.Do(Effect.CreateDelayedTrigger(arcanum.api.Trigger.On(EventPattern.StepBegins(arcanum.api.TurnStep.BeginningOfCombat, PlayerFilter.Any)),
                Instructions(steps = listOf(Step.Do(Effect.Untap(Objects.Each(attacked))))), duration = arcanum.api.Duration.EndOfTurn, repeats = true)))
        }
        // dft chunk 10: "Exchange control of target artifact or creature you control and target artifact or creature an opponent controls." (CR 701.12)
        Dft.EXCHANGE_CONTROL_OF_TARGETS.matchEntire(sentence)?.let { m ->
            val first = context.target(Filters.slotName(m.groupValues[1]), Filters.noun(m.groupValues[1]) ?: return null)
            val second = context.target(Filters.slotName(m.groupValues[2]), Filters.noun(m.groupValues[2]) ?: return null)
            return listOf(Step.Do(Effect.ExchangeControl(first, second)))
        }
        // dft chunk 10: "All creatures and Vehicles lose indestructible until end of turn, then destroy all creatures and Vehicles." (CR 613.1f first)
        Dft.ALL_LOSE_THEN_DESTROY_ALL.matchEntire(sentence)?.takeIf { it.groupValues[1] == it.groupValues[3] }?.let { m ->
            val kinds = m.groupValues[1].split(" and ").map { Filters.noun(it) ?: return null }
            val all = Objects.Each(if (kinds.size == 1) kinds.single() else ObjectFilter.Or(kinds))
            val keyword = OracleParser.keyword(m.groupValues[2]) ?: return null
            return listOf(dftUntilEndOfTurn(all, listOf(Mechanic.LoseAbilities(keyword.kind))), Step.Do(Effect.Destroy(all)))
        }
        // dft chunk 10: "create X 1/1 colorless Pilot creature tokens with "…"" (X read by the ability, CR 107.3)
        Dft.CREATE_X_TOKENS_WITH_QUOTED.matchEntire(sentence)?.let { m ->
            val token = Tokens.defined("a " + m.groupValues[1] + " token") ?: return null
            val granted = Sentences(setOf("this token", "this creature")).line(m.groupValues[2]) ?: return null
            return listOf(Step.Do(Effect.CreateToken(token.copy(face = token.face.copy(abilities = listOf(granted))), Value.Announced("X"), Players.You)))
        }
        // dft chunk 11: "this creature deals that much damage to each opponent." after discarding one or more cards: one for each card
        Dft.DEALS_THAT_MUCH_TO_EACH_OPPONENT.matchEntire(sentence)?.takeIf { context.event is EventPattern.Discard }?.let { m ->
            val source = dftSubject(m.groupValues[1], context)?.takeIf { it !is Objects.Target } ?: return null
            return listOf(Step.Do(Effect.DealDamage(Recipients(players = Players.Each(PlayerFilter.Opponent)), Value.Count(Objects.EventObject(EventRole.After)), source)))
        }
        // dft chunk 08: "those creatures get -1/-0 until end of turn." after one or more creatures attack: the attackers of the batch
        Dft.THOSE_CREATURES_GET_UNTIL_EOT.matchEntire(sentence)?.takeIf { context.event is EventPattern.Attack }?.let { m ->
            return listOf(dftUntilEndOfTurn(Objects.EventObject(EventRole.Object), listOf(Mechanic.ModifyPowerToughness(
                Value.Fixed(m.groupValues[1].toInt()), Value.Fixed(m.groupValues[2].toInt())))))
        }
        // dft chunk 08: "this creature deals 4 damage to them." (the player of the event)
        Dft.DEALS_DAMAGE_TO_THEM.matchEntire(sentence)?.takeIf { context.event is EventPattern.Cast }?.let { m ->
            val source = dftSubject(m.groupValues[1], context)?.takeIf { it !is Objects.Target } ?: return null
            return listOf(Step.Do(Effect.DealDamage(Recipients(players = Players.EventPlayer), Value.Fixed(m.groupValues[2].toInt()), source)))
        }
        // dft chunk 08: "Any number of target players each mill two cards." / "… each mill cards equal to the number of cards in their graveyard."
        Dft.ANY_NUMBER_OF_TARGET_PLAYERS_EACH_MILL.matchEntire(sentence)?.let { m ->
            context.targets += TargetSlot("players", TargetKind.Players(PlayerFilter.Any), min = Value.Fixed(0), max = null)
            return listOf(Step.Do(Effect.Mill(Players.Target("players"), Value.Fixed(Numbers.count(m.groupValues[1]) ?: return null))))
        }
        if (Dft.ANY_NUMBER_OF_TARGET_PLAYERS_EACH_MILL_GRAVEYARD.matches(sentence)) {
            context.targets += TargetSlot("players", TargetKind.Players(PlayerFilter.Any), min = Value.Fixed(0), max = null)
            val player = Players.Bound("player")
            return listOf(Step.ForEach(arcanum.api.Each.Players(Players.Target("players")), bind = "player", together = true, steps = listOf(
                Step.Do(Effect.Mill(player, Value.Count(Objects.Each(Filters.all(ObjectFilter.InZone(Zone.Graveyard), ObjectFilter.OwnedBy(PlayerFilter.Is(player))))))))))
        }
        // dft chunk 09: "Put any number of permanent cards from your hand onto the battlefield."
        Dft.PUT_ANY_NUMBER_FROM_HAND.matchEntire(sentence)?.let { m ->
            val filter = Filters.all(Filters.noun(m.groupValues[1] + " card") ?: return null, ObjectFilter.InZone(Zone.Hand), ObjectFilter.OwnedBy(PlayerFilter.You))
            return listOf(Step.Choose(arcanum.api.Choice.Objects(filter, min = Value.Fixed(0), max = null), bind = "chosen", chooser = Players.You),
                Step.Do(Effect.Move(Objects.Bound("chosen"), Destination(Zone.Battlefield, tapped = m.groupValues[2].isNotEmpty()))))
        }
        // dft chunk 07: "It deals 2 damage to each player who doesn't have max speed." (speed below 4, none counting as 0, CR 702.179e, f)
        Dft.DEALS_TO_EACH_PLAYER_WITHOUT_MAX_SPEED.matchEntire(sentence)?.let { m ->
            val source = dftSubject(m.groupValues[1], context)?.takeIf { it !is Objects.Target } ?: return null
            val without = PlayerFilter.Where(arcanum.api.Condition.Compare(Value.Speed(Players.Tested), arcanum.api.Comparison.Less, Value.Fixed(4)))
            return listOf(Step.Do(Effect.DealDamage(Recipients(players = Players.Each(without)), Value.Fixed(m.groupValues[2].toInt()), source)))
        }
        // dft chunk 07: "Creatures and Vehicles you control gain haste until end of turn." (those then, CR 611.2c)
        Dft.A_AND_B_YOU_CONTROL_GAIN_UNTIL_EOT.matchEntire(sentence)?.let { m ->
            val kinds = listOf(m.groupValues[1], m.groupValues[2]).map { Filters.noun(it.replaceFirstChar { c -> c.lowercase() }) ?: Filters.noun(it) ?: return null }
            val keywords = dftKeywords(m.groupValues[3]) ?: return null
            return listOf(dftUntilEndOfTurn(Objects.Each(Filters.all(ObjectFilter.Or(kinds), ObjectFilter.ControlledBy(PlayerFilter.You))), listOf(Mechanic.GainAbilities(keywords))))
        }
        // dft chunk 05: "That Mount or Vehicle gains flying until end of turn." after saddling or crewing: the permanent whose cost it paid
        Dft.THAT_MOUNT_OR_VEHICLE.matchEntire(sentence)?.takeIf { (context.event as? EventPattern.Tap)?.forCost != null }?.let { m ->
            context.it = Objects.EventObject(EventRole.Source)
            return effect("It " + m.groupValues[1], context)
        }
        // dft chunk 03: "Create a 3/2 colorless Vehicle artifact token with crew 1." (an artifact, a creature only once crewed, CR 301.7)
        Dft.CREATE_VEHICLE_TOKEN.matchEntire(sentence)?.let { m ->
            val token = arcanum.api.TokenSpec.Defined(arcanum.api.FaceDefinition("Vehicle Token", colorIndicator = emptyList(), types = listOf(CardType.Artifact),
                subtypes = listOf(Subtype("Vehicle")), power = arcanum.api.PrintedNumber.Fixed(m.groupValues[1].toInt()),
                toughness = arcanum.api.PrintedNumber.Fixed(m.groupValues[2].toInt()), abilities = listOf(arcanum.api.Keyword.Crew(m.groupValues[3].toInt()))))
            return listOf(Step.Do(Effect.CreateToken(token, Value.Fixed(1), Players.You)))
        }
        // dft chunk 03: "Vehicles you control become artifact creatures until end of turn." (the Vehicles then, CR 611.2c)
        Dft.BECOME_ARTIFACT_CREATURES_UNTIL_EOT.matchEntire(sentence)?.let { m ->
            val filter = Filters.noun(m.groupValues[1]) ?: return null
            return listOf(dftUntilEndOfTurn(Objects.Each(filter), listOf(dftArtifactCreature)))
        }
        // dft chunk 03: "it becomes saddled until end of turn." (the entering Mount), "Target Mount you control becomes saddled until end of turn."
        // (CR 702.171b: saddled until end of turn)
        Dft.BECOMES_SADDLED_UNTIL_EOT.matchEntire(sentence)?.let { m ->
            val objects = dftSubject(m.groupValues[1], context) ?: return null
            return listOf(Step.Do(Effect.Mark(objects, arcanum.api.ObjectMark.Saddled)))
        }
        // dft chunk 02: "This Vehicle becomes an artifact creature." (for good, CR 611.2a) / "… until end of turn."; "it" in an enters
        // trigger of this Vehicle is this Vehicle, in another's the entering one
        Dft.BECOMES_AN_ARTIFACT_CREATURE.matchEntire(sentence)?.let { m ->
            val objects = dftSubject(m.groupValues[1], context) ?: return@let
            context.it = objects
            val duration = if (m.groupValues[2].isEmpty()) arcanum.api.Duration.Indefinitely else arcanum.api.Duration.EndOfTurn
            return listOf(Step.Do(Effect.ApplyMechanics(listOf(dftArtifactCreature), Affected.Objects(objects), duration)))
        }
        // dft chunk 02: "Distribute two +1/+1 counters among one or two other target Vehicles and/or creatures you control." (divided as the
        // targets are chosen, CR 601.2d)
        Dft.DISTRIBUTE_AMONG_ONE_OR_TWO.matchEntire(sentence)?.takeIf { it.groupValues[5].contains(" and/or ") }?.let { m ->
            val amount = Numbers.count(m.groupValues[1]) ?: return null
            val kind = Counters.kind(m.groupValues[2]) ?: return null
            val noun = Filters.noun(m.groupValues[5]) ?: return null
            val filter = if (m.groupValues[4].isEmpty()) noun else Filters.all(ObjectFilter.Not(ObjectFilter.Is(Objects.Self)), noun)
            context.targets += dftSlot("permanents", filter, min = 1, max = Numbers.count(m.groupValues[3]) ?: return null).copy(divided = Value.Fixed(amount))
            return listOf(Step.Do(Effect.PutCounters(Objects.Target("permanents"), kind, Value.DividedShare)))
        }
        // dft chunk 01: "Return a creature or Vehicle card from your graveyard to your hand." (chosen as it resolves, not targeted)
        Dft.RETURN_A_CARD_FROM_YOUR_GRAVEYARD.matchEntire(sentence)?.let { m ->
            val filter = dftInYourGraveyard(Filters.noun(m.groupValues[1]) ?: return null)
            return listOf(Step.Choose(arcanum.api.Choice.Objects(filter, min = Value.Fixed(1), max = Value.Fixed(1)), bind = "chosen", chooser = Players.You),
                Step.Do(Effect.Move(Objects.Bound("chosen"), Destination(Zone.Hand))))
        }
        // dft chunk 01: "Return up to one target artifact card from your graveyard to the battlefield."
        Dft.RETURN_UP_TO_ONE_TARGET_TO_BATTLEFIELD.matchEntire(sentence)?.let { m ->
            val filter = dftInYourGraveyard(Filters.noun(m.groupValues[1]) ?: return null)
            context.targets += dftSlot("card", filter, min = 0)
            return listOf(Step.Do(Effect.Move(Objects.Target("card"), Destination(Zone.Battlefield))))
        }
        // dft chunk 01: "Create that many tapped 2/2 black Zombie creature tokens." after discarding one or more cards: one per card
        // fdn chunk 08: "create that many 1/1 green Elf Warrior creature tokens" after other events: the event's amount (damage dealt, CR 120.3)
        Dft.CREATE_THAT_MANY.matchEntire(sentence)?.takeIf { context.event != null }?.let { m ->
            val (_, token) = Tokens.spec("two " + m.groupValues[2]) ?: return null
            val count = if (context.event is EventPattern.Discard) Value.Count(Objects.EventObject(EventRole.After)) else Value.EventAmount
            return listOf(Step.Do(Effect.CreateToken(token, count, Players.You, tapped = m.groupValues[1].isNotEmpty())))
        }
        return null
    }

    // ---- Mechanics the engine plays since its lanes 1–4 ([MechanicWordings]); each rule reads one wording and falls through

    /** Whole lines: exert as it attacks, actions any time you could mulligan, starting hand sizes. */
    private fun mechanicLine(line: String): Ability? {
        // CR 701.43d, 508.1g: "You may exert this creature as it attacks. When you do, [effect]": an optional cost of attacking with it, and a
        // reflexive trigger once it is paid (CR 603.12, 607.2h); "it" in the effect is this creature, as in its attack trigger
        MechanicWordings.MAY_EXERT_AS_ATTACKS.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val then = m.groupValues[2].takeIf { it.isNotEmpty() }?.let { effect ->
                (triggered("Whenever ${m.groupValues[1]} attacks, $effect") as? Ability.Triggered)?.instructions ?: return null
            }
            return Ability.Static(listOf(Mechanic.AsAttacks(Cost(listOf(CostPart.Action(arcanum.api.KeywordAction.Exert(Objects.Self)))), then)),
                affects = Affected.Objects(Objects.Self))
        }
        // CR 103.5b: "Any time you could mulligan and this card is in your hand, you may [effect]": an action in the hand
        MechanicWordings.ANY_TIME_YOU_COULD_MULLIGAN.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val action = instructions(m.groupValues[2].replaceFirstChar { it.uppercase() }) ?: return null
            return Ability.Static(listOf(Mechanic.WhenYouCouldMulligan(action)), affects = Affected.Objects(Objects.Self), functionsIn = listOf(Zone.Hand))
        }
        // CR 103.5: "Your starting hand size is increased by one." (a conspiracy's, in the command zone, CR 905.4)
        MechanicWordings.STARTING_HAND_SIZE.matchEntire(line)?.let { m ->
            val n = Numbers.count(m.groupValues[2]) ?: return null
            return Ability.Static(listOf(Mechanic.StartingHandSize(if (m.groupValues[1] == "increased") n else -n)), affects = Affected.Players(Players.You),
                functionsIn = listOf(Zone.Command))
        }
        return null
    }

    /** The objects a static ability of this mechanic group affects: this object, the one it enchants or equips, or each of a kind. */
    private fun mechanicAffected(subject: String): Objects? {
        if (isSelf(subject)) return Objects.Self
        if (subject == "Enchanted creature" || subject == "Equipped creature" || subject == "enchanted creature" || subject == "equipped creature")
            return Objects.AttachedTo(Objects.Self)
        return Objects.Each(Filters.noun(subject.replaceFirstChar { it.lowercase() }) ?: return null)
    }

    /** Static abilities, also inside "As long as …": costs to attack and block, copy effects. */
    private fun mechanicStatic(line: String): Ability? {
        // CR 508.1d, h: "Creatures can't attack you unless their controller pays {2} for each creature they control that's attacking you."
        MechanicWordings.CANT_ATTACK_YOU_UNLESS_PAYS_EACH_ATTACKING.matchEntire(line)?.let { m ->
            val attackers = mechanicAffected(m.groupValues[1]) ?: return null
            val walkers = m.groupValues[2].takeIf { it.isNotEmpty() }?.let { Objects.Each(Filters.noun(it) ?: return null) }
            val mana = ManaCost.parse(m.groupValues[3]) ?: return null
            val x = m.groupValues[4].takeIf { it.isNotEmpty() }?.let { Values.value(it) ?: return null }
            return Ability.Static(listOf(Mechanic.AttackCost(Cost(listOf(CostPart.Mana(mana, x = x))), target = Recipients(objects = walkers, players = Players.You))),
                affects = Affected.Objects(attackers))
        }
        // CR 508.1d, 509.1d: "Enchanted creature can't attack unless its controller pays {3}." / "… can't attack or block unless …"
        MechanicWordings.CANT_ATTACK_UNLESS_ITS_CONTROLLER_PAYS.matchEntire(line)?.let { m ->
            val objects = mechanicAffected(m.groupValues[1]) ?: return null
            val cost = Cost.mana(ManaCost.parse(m.groupValues[3]) ?: return null)
            val mechanics = when (m.groupValues[2]) {
                "attack" -> listOf(Mechanic.AttackCost(cost))
                "block" -> listOf(Mechanic.BlockCost(cost))
                else -> listOf(Mechanic.AttackCost(cost), Mechanic.BlockCost(cost))
            }
            return Ability.Static(mechanics, affects = Affected.Objects(objects))
        }
        // CR 508.1h, 509.1d: "This creature can't attack unless you sacrifice a land." (a cost other than mana, paid as it is declared)
        MechanicWordings.SELF_CANT_ATTACK_UNLESS_YOU.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val cost = cost(m.groupValues[3].replaceFirstChar { it.uppercase() }) ?: return null
            val mechanic = if (m.groupValues[2] == "attack") Mechanic.AttackCost(cost) else Mechanic.BlockCost(cost)
            return Ability.Static(listOf(mechanic), affects = Affected.Objects(Objects.Self))
        }
        // CR 508.1h: "Black creatures can't attack unless their controller sacrifices a land of their choice for each black creature they
        // control that's attacking." (the cost for each attacker)
        MechanicWordings.CANT_ATTACK_UNLESS_CONTROLLER_SACRIFICES.matchEntire(line)?.takeIf {
            it.groupValues[1].replaceFirstChar { c -> c.lowercase() } == it.groupValues[3] + "s"
        }?.let { m ->
            val attackers = mechanicAffected(m.groupValues[1]) ?: return null
            val cost = cost("Sacrifice ${m.groupValues[2]}") ?: return null
            return Ability.Static(listOf(Mechanic.AttackCost(cost)), affects = Affected.Objects(attackers))
        }
        // CR 509.1d: "Creatures can't block unless their controller pays {1} for each of those creatures."
        MechanicWordings.CANT_BLOCK_UNLESS_PAYS.matchEntire(line)?.let { m ->
            val blockers = mechanicAffected(m.groupValues[1]) ?: return null
            val cost = PAY_LIFE.matchEntire("Pay " + m.groupValues[2])?.let { Cost(listOf(CostPart.PayLife(Value.Fixed(it.groupValues[1].toInt())))) }
                ?: Cost.mana(ManaCost.parse(m.groupValues[2]) ?: return null)
            return Ability.Static(listOf(Mechanic.BlockCost(cost)), affects = Affected.Objects(blockers))
        }
        // CR 613.2a, 707.2: "Enchanted creature is a copy of the chosen creature." (the creature chosen as this Aura entered, CR 607.2d),
        // "Other creatures you control are copies of enchanted creature."
        MechanicWordings.IS_A_COPY_OF.matchEntire(line)?.let { m ->
            val affected = when {
                m.groupValues[1].startsWith("Other ") -> Objects.Each(Filters.all(ObjectFilter.Not(ObjectFilter.Is(Objects.Self)),
                    Filters.noun(m.groupValues[1].removePrefix("Other ")) ?: return null))
                else -> mechanicAffected(m.groupValues[1]) ?: return null
            }
            val of = when (m.groupValues[2]) {
                "the chosen creature", "the chosen permanent", "the chosen artifact" -> Objects.Remembered(CHOSEN)
                "enchanted creature", "equipped creature", "enchanted permanent" -> Objects.AttachedTo(Objects.Self)
                else -> return null
            }
            return Ability.Static(listOf(Mechanic.CopyOf(of)), affects = Affected.Objects(affected))
        }
        return null
    }

    /** Cost parts: "Exert this creature" (CR 701.43a, b). */
    private fun mechanicCostPart(text: String): List<CostPart>? {
        MechanicWordings.EXERT_COST.matchEntire(text)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            return listOf(CostPart.Action(arcanum.api.KeywordAction.Exert(Objects.Self)))
        }
        return null
    }

    /** The number a keyword action names: N, or X announced with the costs (an activated ability's or a spell's, CR 107.3a). */
    private fun mechanicCount(text: String): Value? = when (text) {
        "X" -> if (isSpell || announcedX) Value.Announced(name = "X") else null
        "card" -> Value.Fixed(1)
        "two cards" -> Value.Fixed(2)
        "three cards" -> Value.Fixed(3)
        else -> text.toIntOrNull()?.let { Value.Fixed(it) }
    }

    /** The objects a keyword action's subject or object names: this object, "it", "that creature", a target, "each/all …". */
    private fun mechanicObjects(subject: String, context: Context): Objects? {
        if (subject == "That creature" || subject == "that creature") return context.that ?: context.it
        // "it" after a sentence with an object target is that target ("target creature gains … . It explores.")
        if (subject == "it" || subject == "It")
            context.targets.lastOrNull()?.takeIf { it.what is TargetKind.Objects }?.let { return Objects.Target(it.name) }
        MechanicWordings.ALL_NOUN.matchEntire(subject)?.let { return Objects.Each(Filters.noun(it.groupValues[1]) ?: return null) }
        return tdmObjects(subject, context)
    }

    /** dungeons: the dungeon cards' room effects (CR 309.4c) that no other rule reads; each falls through when it can't read. */
    private fun dungeonEffect(sentence: String, context: Context): List<Step>? {
        // "Draw three cards and reveal them." ("them": the cards drawn, as they are in the hand)
        MechanicWordings.DRAW_AND_REVEAL.matchEntire(sentence)?.let { m ->
            val n = Numbers.count(m.groupValues[1]) ?: return null
            context.them = Objects.Bound("drawn")
            return listOf(Step.Do(Effect.Draw(Players.You, Value.Fixed(n), postBind = "drawn")), Step.Do(Effect.Reveal(Objects.Bound("drawn"))))
        }
        // "You may cast one of them without paying its mana cost." (CR 601.2, 608.2g: cast while the ability resolves; a land
        // can't be cast)
        if (MechanicWordings.MAY_CAST_ONE_OF_THEM_FREE.matches(sentence)) {
            val them = context.them ?: return null
            return listOf(
                Step.Choose(arcanum.api.Choice.Objects(ObjectFilter.Not(ObjectFilter.Type(CardType.Land)), Value.Fixed(0), Value.Fixed(1), from = them),
                    bind = "toCast", chooser = Players.You),
                Step.Do(Effect.Cast(Objects.Bound("toCast"), PlayKind.Cast, withoutPaying = true, caster = Players.You)))
        }
        // "Put a creature card from among them onto the battlefield with three +1/+1 counters on it." (after "Reveal the top ten
        // cards of your library.": one of them if there is one, CR 609.3; "it" afterwards is that permanent, CR 400.7)
        MechanicWordings.PUT_ONE_FROM_AMONG_ONTO_BATTLEFIELD.matchEntire(sentence)?.let { m ->
            val seen = context.seen ?: return null
            val filter = Filters.noun(m.groupValues[1]) ?: return null
            val counters = if (m.groupValues[2].isEmpty()) emptyList() else listOf(arcanum.api.CountersToPut(
                Counters.kind(m.groupValues[3]) ?: return null, Value.Fixed(Numbers.count(m.groupValues[2]) ?: return null)))
            context.picked = "chosen"
            context.it = Objects.Bound("put")
            return listOf(
                Step.Choose(arcanum.api.Choice.Objects(filter, Value.Fixed(1), Value.Fixed(1), from = Objects.Bound(seen)), bind = "chosen", chooser = Players.You),
                Step.Do(Effect.Move(Objects.Bound("chosen"), Destination(Zone.Battlefield, counters = counters), postBind = "put")))
        }
        // "Sacrifice a creature, an artifact, and a land." (one of each, sacrificed at once, CR 701.21a): three different permanents,
        // an artifact creature counting as one of them only (each choice excludes the ones before it)
        MechanicWordings.SACRIFICE_LIST.matchEntire(sentence)?.let { m ->
            val nouns = m.groupValues[1].split(LazyRegexes.AND_LIST).map { it.removeArticle() }
            val binds = nouns.indices.map { "sacrificed${it + 1}" }
            val chooses = nouns.zip(binds).mapIndexed { n, (noun, bind) ->
                val earlier = binds.take(n).map { ObjectFilter.Not(ObjectFilter.Is(Objects.Bound(it))) }
                Step.Choose(arcanum.api.Choice.Objects(Filters.all(Filters.noun(noun) ?: return null, ObjectFilter.ControlledBy(PlayerFilter.You), *earlier.toTypedArray()),
                    Value.Fixed(1), Value.Fixed(1)), bind = bind, chooser = Players.You)
            }
            return chooses + Step.Do(Effect.Sacrifice(Objects.Union(binds.map { Objects.Bound(it) })))
        }
        // "Discard a card and sacrifice a creature, an artifact, and a land." (the discard, then the sacrifice)
        MechanicWordings.DISCARD_AND_SACRIFICE.matchEntire(sentence)?.let { m ->
            val first = effect(m.groupValues[1] + ".", context) ?: return null
            val second = effect(m.groupValues[2].replaceFirstChar { it.uppercase() } + ".", context) ?: return null
            return first + second
        }
        return null
    }

    /** Effect sentences: the keyword actions (CR 701) the engine does, and the exiled hand redrawn. */
    private fun mechanicEffect(sentence: String, context: Context): List<Step>? {
        fun action(action: arcanum.api.KeywordAction) = listOf(Step.Do(Effect.Action(action)))
        when (sentence) {
            // CR 701.48a
            "Learn." -> return action(arcanum.api.KeywordAction.Learn)
            // CR 701.56a
            "Time travel." -> return action(arcanum.api.KeywordAction.TimeTravel)
        }
        // CR 701.44a: "When this creature enters, it explores.", "Target creature you control explores."
        MechanicWordings.EXPLORES.matchEntire(sentence)?.let { m ->
            return action(arcanum.api.KeywordAction.Explore(mechanicObjects(m.groupValues[1], context) ?: return null))
        }
        // CR 701.37a: "Monstrosity 3." (an activated ability's: this permanent)
        MechanicWordings.MONSTROSITY.matchEntire(sentence)?.let { m -> return action(arcanum.api.KeywordAction.Monstrosity(mechanicCount(m.groupValues[1]) ?: return null)) }
        // CR 701.46a
        MechanicWordings.ADAPT.matchEntire(sentence)?.let { m -> return action(arcanum.api.KeywordAction.Adapt(mechanicCount(m.groupValues[1]) ?: return null)) }
        // CR 701.39a, b: up to N other target creatures (a permanent's), up to N target creatures (an instant's or sorcery's)
        MechanicWordings.SUPPORT.matchEntire(sentence)?.let { m ->
            val count = mechanicCount(m.groupValues[1]) ?: return null
            val creature = ObjectFilter.Type(CardType.Creature)
            val name = context.name("supported")
            context.targets += TargetSlot(name, TargetKind.Objects(if (isSpell) creature else Filters.all(ObjectFilter.Not(ObjectFilter.Is(Objects.Self)), creature)),
                min = Value.Fixed(0), max = count)
            return action(arcanum.api.KeywordAction.Support(count, name))
        }
        // CR 701.57a
        MechanicWordings.DISCOVER.matchEntire(sentence)?.let { m -> return action(arcanum.api.KeywordAction.Discover(mechanicCount(m.groupValues[1]) ?: return null)) }
        // CR 701.40a: "Manifest the top card of your library."
        MechanicWordings.MANIFEST_TOP.matchEntire(sentence)?.let { m -> return action(arcanum.api.KeywordAction.Manifest(mechanicCount(m.groupValues[1]) ?: return null)) }
        // CR 701.58a: "Cloak the top card of your library."
        MechanicWordings.CLOAK_TOP.matchEntire(sentence)?.let { m -> return action(arcanum.api.KeywordAction.Cloak(mechanicCount(m.groupValues[1]) ?: return null)) }
        // CR 701.15a: "Goad target creature.", "Goad it.", "Goad all creatures your opponents control."
        MechanicWordings.GOAD.matchEntire(sentence)?.let { m ->
            // "goad it" after another effect: the object that effect named (its target), never this permanent by default
            val objects = (if (m.groupValues[1] == "it") mechanicObjects("it", context)?.takeIf { it != Objects.Self } ?: context.it?.takeIf { it != Objects.Self }
                else mechanicObjects(m.groupValues[1], context)) ?: return null
            return action(arcanum.api.KeywordAction.Goad(objects))
        }
        // "Exile all the cards from your hand, then draw that many cards."
        if (MechanicWordings.EXILE_HAND_DRAW_THAT_MANY.matches(sentence)) {
            return listOf(
                Step.Do(Effect.Move(Objects.Each(Filters.all(ObjectFilter.InZone(Zone.Hand), ObjectFilter.OwnedBy(PlayerFilter.You))), Destination(Zone.Exile), postBind = "exiled")),
                Step.Do(Effect.Draw(Players.You, Value.Count(Objects.Bound("exiled")))))
        }
        return null
    }

    /**
     * "Threshold — Add {B}{B}{B}{B}{B} instead if there are seven or more cards in your graveyard.": the spell's last
     * step happens only if the condition is false; the new one if it is true (a conditional "instead", written as If).
     */
    fun insteadOf(line: String, spell: Ability.Spell): Ability.Spell? {
        // sos chunk 05: "Infusion — If you gained life this turn, destroy all creatures instead.": the paragraph before happens only if the
        // condition is false (a conditional "instead" of the spell's own text)
        SOS_IF_INSTEAD_LINE.matchEntire(line)?.let { s ->
            if (s.groupValues[1].isNotEmpty() && !RulesWords.isAbilityOrFlavorWord(s.groupValues[1])) return null
            val condition = Conditions.condition(s.groupValues[2], self) ?: return null
            // inr chunk 07: "create five of those tokens instead" (the token the paragraph before creates, another number)
            Inr.CREATE_N_OF_THOSE_TOKENS.matchEntire(s.groupValues[3])?.let { t ->
                val usual = spell.instructions.steps.singleOrNull() as? Step.Do ?: return null
                val create = usual.effect as? Effect.CreateToken ?: return null
                val n = Numbers.count(t.groupValues[1]) ?: return null
                return spell.copy(abilityWord = s.groupValues[1].ifEmpty { null }, instructions = spell.instructions.copy(
                    steps = listOf(Step.If(condition, then = listOf(Step.Do(create.copy(count = Value.Fixed(n)))), otherwise = listOf(usual)))))
            }
            val replacement = instructions(s.groupValues[3].replaceFirstChar { it.uppercase() } + ".", spell.instructions.targets)
                ?.takeIf { it.targets == spell.instructions.targets } ?: return null
            return spell.copy(abilityWord = s.groupValues[1].ifEmpty { null }, instructions = spell.instructions.copy(
                steps = listOf(Step.If(condition, then = replacement.steps, otherwise = spell.instructions.steps))))
        }
        val m = INSTEAD_IF.matchEntire(line) ?: return null
        if (m.groupValues[1].isNotEmpty() && !RulesWords.isAbilityOrFlavorWord(m.groupValues[1])) return null
        val condition = Conditions.condition(m.groupValues[3], self) ?: return null
        val steps = spell.instructions.steps
        if (steps.isEmpty()) return null
        val last = steps.last()
        // "[This] deals 4 damage instead": the same damage to the same recipients, another amount.
        val damage = SELF_DEALS_N.matchEntire(m.groupValues[2])?.takeIf { isSelf(it.groupValues[1]) }?.let { d ->
            val previous = ((last as? Step.Do)?.effect as? Effect.DealDamage) ?: return null
            listOf(Step.Do(previous.copy(amount = Value.Fixed(d.groupValues[2].toInt()))))
        }
        val replacement = damage ?: instructions(m.groupValues[2] + ".", spell.instructions.targets)?.takeIf { it.targets == spell.instructions.targets }?.steps
            ?: return null
        return spell.copy(
            abilityWord = m.groupValues[1].ifEmpty { null },
            instructions = spell.instructions.copy(steps = steps.dropLast(1) + Step.If(condition, then = replacement, otherwise = listOf(last))),
        )
    }

    /**
     * dsk chunk 07: a later paragraph of an instant or sorcery that refers to the earlier paragraphs' targets ("that
     * creature", "the creature you control"), read with them: one spell ability (CR 113.3a). Its ability word, if any, is
     * dropped with the paragraph joined. Null when it can't be read that way.
     */
    fun continuation(line: String, previous: Instructions): Instructions? {
        val text = ABILITY_WORD.matchEntire(line)?.takeIf { RulesWords.isAbilityOrFlavorWord(it.groupValues[1]) }?.groupValues?.get(2) ?: line
        val read = instructions(text, seedTargets = previous.targets) ?: return null
        return previous.copy(targets = read.targets, steps = previous.steps + read.steps, replacements = previous.replacements + read.replacements,
            announced = (previous.announced + read.announced).distinct())
    }

    /** dsk chunk 07: "Delirium — If [condition], instead [instructions].": the whole spell is replaced when it holds. */
    fun insteadAll(line: String, spell: Ability.Spell): Ability.Spell? {
        val m = IF_INSTEAD_ALL.matchEntire(line) ?: return null
        if (m.groupValues[1].isNotEmpty() && !RulesWords.isAbilityOrFlavorWord(m.groupValues[1])) return null
        val condition = Conditions.condition(m.groupValues[2], self) ?: return null
        val replacement = instructions(m.groupValues[3].replaceFirstChar { it.uppercase() })?.takeIf { it.targets.isEmpty() } ?: return null
        return spell.copy(abilityWord = m.groupValues[1].ifEmpty { null }, instructions = spell.instructions.copy(
            steps = listOf(Step.If(condition, then = replacement.steps, otherwise = spell.instructions.steps))))
    }

    /** dsk chunk 07: "Delirium — Choose one. If [condition], choose one or more instead." with its modes (CR 700.2). */
    fun modesWithMaxIf(header: String, modeLines: List<String>): Ability.Spell? {
        val m = CHOOSE_MAX_IF.matchEntire(header) ?: return null
        if (m.groupValues[1].isNotEmpty() && !RulesWords.isAbilityOrFlavorWord(m.groupValues[1])) return null
        val n = Numbers.count(m.groupValues[2]) ?: return null
        // ltr chunk 11: "as you cast this spell": the modes are chosen as it is cast (CR 601.2b)
        val condition = Conditions.condition(m.groupValues[3].removeSuffix(" as you cast this spell"), self) ?: return null
        val options = modeLines.map { arcanum.api.Mode(instructions(modeBody(it)) ?: return null, text = it) }
        if (options.isEmpty()) return null
        val maxIf = when (m.groupValues[5]) { "one or more" -> options.size; "both" -> 2; else -> Numbers.count(m.groupValues[5]) ?: return null }
        return Ability.Spell(Instructions(modes = arcanum.api.Modes(options, min = n, max = n, maxIf = condition, maxIfCount = maxIf,
            upToMaxIf = m.groupValues[5] == "one or more" || m.groupValues[4].isNotEmpty(), chooser = Players.You)),
            abilityWord = m.groupValues[1].ifEmpty { null })
    }

    /** dsk chunk 12: "[cost]: Choose one —" with its modes: a modal activated ability (CR 700.2). */
    fun modalActivated(costText: String, choose: MatchResult, modeLines: List<String>): Ability.Activated? {
        val cost = cost(costText) ?: return null
        val modes = modes(choose, modeLines) ?: return null
        return Ability.Activated(cost, Instructions(modes = modes),
            arcanum.api.ActivationRules(timing = arcanum.api.Timing.Any, activatedBy = PlayerFilter.You))
    }

    /** msh: a mode's text without its flavor word ("• Solar Beam — [effect]", CR 207.2d). */
    private fun modeBody(line: String): String =
        ABILITY_WORD.matchEntire(line)?.takeIf { RulesWords.isAbilityOrFlavorWord(it.groupValues[1]) }?.groupValues?.get(2) ?: line

    /** "Choose one —" with its modes; "Choose three. You may choose the same mode more than once." (CR 700.2) */
    fun modes(choose: MatchResult, modeLines: List<String>): arcanum.api.Modes? {
        val n = Numbers.count(choose.groupValues[1]) ?: return null
        val options = modeLines.map { arcanum.api.Mode(instructions(modeBody(it)) ?: return null, text = it) }
        if (options.isEmpty()) return null
        // "Choose one or more —" / "Choose one or both —": up to every mode, each at most once.
        val max = if (choose.groupValues[2].isNotEmpty()) options.size else n
        return arcanum.api.Modes(options, min = n, max = max, repeatable = choose.value.contains("same mode"), chooser = Players.You)
    }

    /** The instructions of an instant or sorcery (CR 113.3a). */
    private fun spell(line: String): Ability? = if (isSpell) instructions(line)?.let { Ability.Spell(otherThanTheTarget(it)) } else null

    /** hob backfill: in a spell with one object target, "put a counter on each other creature you control" is other than
     * that target ("Put a +1/+1 counter on target creature you control. If …, also put a +1/+1 counter on each other
     * creature you control."); "other" can't mean other than the spell, which is never on the battlefield. */
    private fun otherThanTheTarget(instructions: Instructions): Instructions {
        val slot = instructions.targets.singleOrNull()?.takeIf { it.what is arcanum.api.TargetKind.Objects } ?: return instructions
        fun read(step: Step): Step = when (step) {
            is Step.If -> step.copy(then = step.then.map { read(it) }, otherwise = step.otherwise.map { read(it) })
            else -> otherThanTarget(step, Objects.Target(slot.name))
        }
        return instructions.copy(steps = instructions.steps.map { read(it) })
    }

    /** "As this land enters, you may pay 2 life. If you don't, it enters tapped." (CR 614.12, 118.12a) */
    private fun static(line: String): Ability? {
        mechanicStatic(line)?.let { return it }
        ltrStatic(line)?.let { return it } // ltr
        mh2Static(line)?.let { return it } // mh2
        tdmStatic(line)?.let { return it } // tdm
        eoeStatic(line)?.let { return it } // eoe
        spmStatic(line)?.let { return it } // spm
        tlaStatic(line)?.let { return it } // tla
        eclStatic(line)?.let { return it } // ecl
        sosStatic(line)?.let { return it } // sos
        tmtStatic(line)?.let { return it } // tmt
        mshStatic(line)?.let { return it } // msh
        hobStatic(line)?.let { return it } // hob
        fraStatic(line)?.let { return it } // fra
        gtcStatic(line)?.let { return it } // gtc
        blbStatic(line)?.let { return it }
        blbGapsStatic(line)?.let { return it } // blb gaps
        blbGaps2Static(line)?.let { return it } // blb gaps 2
        rtrStatic(line)?.let { return it } // rtr
        // dsk chunk 02: "You have no maximum hand size[ and don't lose the game for having 0 or less life]." (CR 402.2, 704.5a)
        NO_MAXIMUM_HAND_SIZE.matchEntire(line)?.let { m ->
            val mechanics = listOf(Mechanic.NoMaximumHandSize) + listOfNotNull(Mechanic.NoLossForZeroLife.takeIf { m.groupValues[1].isNotEmpty() })
            return Ability.Static(mechanics, affects = Affected.Players(Players.You))
        }
        // dsk chunk 02: "[Once each turn, ]you may pay {0} rather than pay the mana cost for a spell you cast from exile." An
        // alternative cost (CR 118.9) for the spells its controller casts (from exile, or from anywhere; dsk gaps: the spell
        // cast from a zone, CR 601.2a, not the card in that zone)
        ALTERNATIVE_COST_FOR_SPELLS.matchEntire(line)?.let { m ->
            // mkm chunk 03: "You may collect evidence 10 rather than pay the mana cost for spells you cast." (CR 701.59a)
            val cost = if (m.groupValues[3].isNotEmpty()) Cost(costPart(m.groupValues[3].replaceFirstChar { it.uppercase() }) ?: return null)
                else Cost.mana(ManaCost.parse(m.groupValues[2]) ?: return null)
            val cast = if (m.groupValues[5].isEmpty()) ObjectFilter.WasCast() else ObjectFilter.WasCast(Zone.Exile)
            // inr chunk 09: "for Zombie creature spells you cast": only spells of that kind (the card as the spell it would be, CR 601.2a)
            val kind = m.groupValues[4].takeIf { it.isNotEmpty() }?.let { Filters.noun(it) ?: return null }
            val cards = if (kind == null) cast else Filters.all(kind, cast)
            return Ability.Static(listOf(Mechanic.AlternativeCost(cost = cost, perTurn = 1.takeIf { m.groupValues[1].isNotEmpty() })),
                affects = Affected.Objects(Objects.Each(cards)))
        }
        // dsk chunk 13: "This permanent is a 3/4 Ninja creature and has hexproof." (layers 4, 7b and 6)
        SELF_IS_PT_CREATURE.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val subtypes = m.groupValues[4].split(' ').filter { it.isNotEmpty() }.map { arcanum.api.SubtypeRef.Literal(Subtype(it.takeIf { s -> s in RulesWords.subtypes } ?: return null)) }
            val keywords = m.groupValues[5].takeIf { it.isNotEmpty() }?.split(LazyRegexes.AND_LIST)?.map { OracleParser.keyword(it) ?: return null }
            return Ability.Static(listOfNotNull(
                Mechanic.SetTypes(add = listOf(CardType.Creature), addSubtypes = subtypes),
                Mechanic.SetPowerToughness(Value.Fixed(m.groupValues[2].toInt()), Value.Fixed(m.groupValues[3].toInt())),
                keywords?.let { Mechanic.GainAbilities(it) },
            ), affects = Affected.Objects(Objects.Self))
        }
        // dsk chunk 11: "This creature must be blocked if able." (CR 509.1c)
        MUST_BE_BLOCKED.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { return Ability.Static(listOf(Mechanic.MustBeBlocked), affects = Affected.Objects(Objects.Self)) }
        // dsk chunk 11: "This creature has first strike during your turn."
        HAS_KEYWORDS_DURING_YOUR_TURN.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            return Ability.Static(listOf(Mechanic.GainAbilities(keywords(m.groupValues[2]) ?: return null)), affects = Affected.Objects(Objects.Self),
                condition = arcanum.api.Condition.YourTurn)
        }
        // dsk chunk 11: "Equipped creature gets +X/+0, where X is the number of rev counters on this Equipment."
        ATTACHED_GETS_X_COUNTERS.matchEntire(line)?.takeIf { isSelf(it.groupValues[4]) }?.let { m ->
            val x = Value.Of(arcanum.api.NumericProperty.Counters(Counters.kind(m.groupValues[3]) ?: return null), Objects.Self, arcanum.api.Combine.Single)
            fun part(text: String) = if (text == "+X") x else Value.Fixed(text.toInt())
            return Ability.Static(listOf(Mechanic.ModifyPowerToughness(part(m.groupValues[1]), part(m.groupValues[2]))),
                affects = Affected.Objects(Objects.AttachedTo(Objects.Self)))
        }
        // dsk chunk 10: "Enchanted player can't gain life." (CR 303.4m)
        if (line == "Enchanted player can't gain life.") return Ability.Static(listOf(Mechanic.CantGainLife), affects = Affected.Players(Players.AttachedTo(Objects.Self)))
        // dsk chunk 10: "Creatures your opponents control can be the targets of spells and abilities as though they didn't have
        // hexproof. Ward abilities of those creatures don't trigger." (CR 702.11b, 702.21a)
        TARGETABLE_DESPITE_HEXPROOF.matchEntire(line)?.let { m ->
            val affected = Filters.noun(m.groupValues[1].replaceFirstChar { it.lowercase() }) ?: return null
            val mechanics = listOf<Mechanic>(Mechanic.TargetableDespiteHexproof()) + listOfNotNull(Mechanic.WardDoesntTrigger.takeIf { m.groupValues[2].isNotEmpty() })
            return Ability.Static(mechanics, affects = Affected.Objects(Objects.Each(affected)))
        }
        // dsk chunk 10: "If a card you didn't control would be put into an opponent's graveyard from anywhere, exile it instead."
        // The exiled cards stay linked to this object when another ability refers to them (CR 607.2a)
        CARD_YOU_DIDNT_CONTROL_EXILE_INSTEAD.matchEntire(line)?.let {
            val card = Filters.all(ObjectFilter.Category(arcanum.api.ObjectCategory.Card), ObjectFilter.Not(ObjectFilter.ControlledBy(PlayerFilter.You)),
                ObjectFilter.OwnedBy(PlayerFilter.Opponent))
            val exile = Step.Do(Effect.Move(Objects.EventObject(EventRole.Before), Destination(Zone.Exile), postBind = "exiled"))
            return Ability.Static(listOf(Mechanic.Replacement(EventPattern.ZoneChange(card, to = Zone.Graveyard),
                instead = Instructions(steps = listOf(exile) + remembered(Objects.Bound("exiled"))))), affects = Affected.Objects(Objects.Self))
        }
        // dsk chunk 10: "During your turn, you may play cards exiled with Valgavoth. If you cast a spell this way, pay life equal to
        // its mana value rather than pay its mana cost." (CR 118.9)
        PLAY_EXILED_WITH_FOR_LIFE.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            return Ability.Static(listOf(Mechanic.MayPlay(Zone.Exile, PlayKind.Play, holder = PlayerFilter.You,
                cost = Cost(listOf(CostPart.PayLife(Value.Of(arcanum.api.NumericProperty.ManaValue, Objects.Affected, arcanum.api.Combine.Single)))))),
                affects = Affected.Objects(Objects.Remembered(EXILED_WITH)), condition = arcanum.api.Condition.YourTurn)
        }
        // dsk chunk 09: "You control enchanted creature." (layer 2, CR 613.1b)
        if (line == "You control enchanted creature.") return Ability.Static(listOf(Mechanic.ControlledBy(Players.You)), affects = Affected.Objects(Objects.AttachedTo(Objects.Self)))
        // dsk chunk 09: "This spell costs {3} less to cast if it targets a tapped creature." (CR 601.2f: the spell's target slot,
        // named as the spell names it)
        SELF_COSTS_LESS_IF_IT_TARGETS.matchEntire(line)?.let { m ->
            val mana = ManaCost.parse(m.groupValues[1]) ?: return null
            val noun = m.groupValues[2]
            val words = noun.split(' ')
            val kind = Filters.noun(words.last()) ?: return null
            val quality = Filters.noun(words.dropLast(1).joinToString(" ").ifEmpty { return null }) ?: return null
            if (kind == quality) return null
            return Ability.Static(listOf(Mechanic.CostChange(ObjectFilter.Is(Objects.Self), arcanum.api.CostChange.Less(mana, Value.Fixed(1)))),
                affects = Affected.Objects(Objects.Self), condition = arcanum.api.Condition.ObjectMatches(Objects.Target(Filters.slotName(words.last())), quality))
        }
        // dsk chunk 09: "This token can't attack or block alone." (CR 506.5)
        CANT_ATTACK_OR_BLOCK_ALONE.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            return Ability.Static(listOf(Mechanic.CantAttackAlone, Mechanic.CantBlockAlone), affects = Affected.Objects(Objects.Self))
        }
        // dsk chunk 09: "If a source you control would deal damage to an opponent, prevent that damage and each opponent mills that
        // many cards.": a prevention effect with an additional effect (CR 615.5; dsk gaps: not a replacement)
        if (line == "If a source you control would deal damage to an opponent, prevent that damage and each opponent mills that many cards.") {
            return Ability.Static(listOf(Mechanic.Prevention(EventPattern.Damage(ObjectFilter.ControlledBy(PlayerFilter.You), RecipientFilter(players = PlayerFilter.Opponent)),
                additional = Instructions(steps = listOf(Step.Do(Effect.Mill(Players.Each(PlayerFilter.Opponent), Value.EventAmount)))))), affects = Affected.Objects(Objects.Self))
        }
        // dsk chunk 08: "If this card is in your opening hand, you may begin the game with it on the battlefield." (CR 103.6a)
        if (line == "If this card is in your opening hand, you may begin the game with it on the battlefield.")
            return Ability.Static(listOf(Mechanic.MayBeginOnBattlefield), affects = Affected.Objects(Objects.Self), functionsIn = listOf(Zone.Hand))
        // dsk chunk 08: "If you would gain life, you gain that much life plus 1 instead." (CR 614.1a)
        GAIN_THAT_MUCH_PLUS.matchEntire(line)?.let { m ->
            return Ability.Static(listOf(Mechanic.Replacement(EventPattern.GainLife(PlayerFilter.You),
                modify = listOf(Modification.AddAmount(Value.Fixed(m.groupValues[1].toInt()))))), affects = Affected.Objects(Objects.Self))
        }
        // dsk chunk 08: "If a card would be put into an opponent's graveyard from anywhere, exile it instead." (CR 614.1a)
        WOULD_BE_PUT_INTO_GRAVEYARD_EXILE_INSTEAD.matchEntire(line)?.let { m ->
            val owner = Filters.noun(m.groupValues[1]) ?: return null
            val whose = if (m.groupValues[2] == "an opponent's") PlayerFilter.Opponent else PlayerFilter.You
            return Ability.Static(listOf(Mechanic.Replacement(EventPattern.ZoneChange(Filters.all(owner, ObjectFilter.OwnedBy(whose)), to = Zone.Graveyard),
                modify = listOf(Modification.ChangeDestination(Destination(Zone.Exile))))), affects = Affected.Objects(Objects.Self))
        }
        // dsk chunk 08: "Creatures you control are the chosen type in addition to their other types. The same is true for
        // creature spells you control and creature cards you own that aren't on the battlefield." (CR 607.2d)
        if (line == "Creatures you control are the chosen type in addition to their other types. The same is true for creature spells you control and creature cards you own that aren't on the battlefield.") {
            val creature = ObjectFilter.Type(CardType.Creature)
            val yours = ObjectFilter.ControlledBy(PlayerFilter.You)
            return Ability.Static(listOf(Mechanic.SetTypes(addSubtypes = listOf(arcanum.api.SubtypeRef.Remembered(CHOSEN_TYPE)))), affects = Affected.Objects(Objects.Union(listOf(
                Objects.Each(Filters.all(creature, yours)),
                Objects.Each(Filters.all(creature, ObjectFilter.Category(arcanum.api.ObjectCategory.Spell), yours)),
                Objects.Each(Filters.all(creature, ObjectFilter.OwnedBy(PlayerFilter.You),
                    ObjectFilter.Or(EVERY_ZONE.filter { it != Zone.Battlefield && it != Zone.Stack }.map { ObjectFilter.InZone(it) })))))))
        }
        // dsk chunk 07: "This spell costs {2} less to cast as long as …" (CR 601.2f)
        SELF_COSTS_LESS_AS_LONG_AS.matchEntire(line)?.let { m ->
            val mana = ManaCost.parse(m.groupValues[1]) ?: return null
            return Ability.Static(listOf(Mechanic.CostChange(ObjectFilter.Is(Objects.Self), arcanum.api.CostChange.Less(mana, Value.Fixed(1)))),
                affects = Affected.Objects(Objects.Self), condition = Conditions.condition(m.groupValues[2], self) ?: return null)
        }
        // dsk chunk 07: "This creature can't attack or block unless …"
        CANT_ATTACK_OR_BLOCK_UNLESS.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            return Ability.Static(listOf(Mechanic.CantAttack(), Mechanic.CantBlock(ObjectFilter.Any)), affects = Affected.Objects(Objects.Self),
                condition = arcanum.api.Condition.Not(Conditions.condition(m.groupValues[2], self) ?: return null))
        }
        // dsk chunk 07: "Each opponent's maximum hand size is equal to seven minus the number of those card types." (after a
        // delirium condition: the card types among cards in your graveyard)
        MAXIMUM_HAND_SIZE_MINUS_CARD_TYPES.matchEntire(line)?.let { m ->
            val n = Numbers.count(m.groupValues[1]) ?: return null
            return Ability.Static(listOf(Mechanic.MaximumHandSize(Value.Difference(Value.Fixed(n),
                Values.value("the number of card types among cards in your graveyard")!!))), affects = Affected.Players(Players.Each(PlayerFilter.Opponent)))
        }
        // dsk chunk 07: "If a source you control would deal noncombat damage to a permanent or player while …, it deals double
        // that damage instead." (CR 614.1a)
        WOULD_DEAL_DOUBLE.matchEntire(line)?.let { m ->
            val combat = when (m.groupValues[1]) { "noncombat " -> false; "combat " -> true; else -> null }
            val permanent = ObjectFilter.Category(arcanum.api.ObjectCategory.Permanent)
            // fdn chunk 04: "an opponent or a permanent an opponent controls"
            val recipients = if (m.groupValues[2].startsWith("an opponent"))
                RecipientFilter(objects = Filters.all(permanent, ObjectFilter.ControlledBy(PlayerFilter.Opponent)), players = PlayerFilter.Opponent)
            else RecipientFilter(objects = permanent, players = PlayerFilter.Any)
            return Ability.Static(listOf(Mechanic.Replacement(EventPattern.Damage(ObjectFilter.ControlledBy(PlayerFilter.You), recipients, combat = combat),
                modify = listOf(Modification.MultiplyAmount(2)))), affects = Affected.Objects(Objects.Self),
                condition = m.groupValues[3].takeIf { it.isNotEmpty() }?.let { Conditions.condition(it, self) ?: return null })
        }
        // dsk chunk 06: "You may look at face-down creatures your opponents control any time."
        MAY_LOOK_AT_ANY_TIME.matchEntire(line)?.let { m ->
            Filters.noun(m.groupValues[1])?.let { return Ability.Static(listOf(Mechanic.MayLookAt(Objects.Each(it))), affects = Affected.Players(Players.You)) }
        }
        // dsk chunk 05: "Enchanted creature loses all abilities and is a Toy artifact creature with base power and toughness 0/2 in
        // addition to its other types." (layers 4, 6, 7b, CR 613.1d, f, 613.4b)
        LOSES_ALL_AND_IS.matchEntire(line)?.let { m ->
            val affected = attachedSubject(m.groupValues[1]) ?: return null
            val add = mutableListOf<CardType>()
            val subtypes = mutableListOf<arcanum.api.SubtypeRef>()
            for (word in m.groupValues[2].split(' ')) {
                val type = Filters.CARD_TYPES[word]
                when {
                    type != null -> add += type
                    word in RulesWords.subtypes -> subtypes += arcanum.api.SubtypeRef.Literal(Subtype(word))
                    else -> return null
                }
            }
            return Ability.Static(listOf(Mechanic.LoseAbilities(), Mechanic.SetTypes(add = add, addSubtypes = subtypes),
                Mechanic.SetPowerToughness(Value.Fixed(m.groupValues[3].toInt()), Value.Fixed(m.groupValues[4].toInt()))), affects = Affected.Objects(affected))
        }
        // dsk chunk 05: "As long as enchanted creature is face down, it can't be turned face up."
        FACE_DOWN_CANT_BE_TURNED_FACE_UP.matchEntire(line)?.let { m ->
            val affected = attachedSubject(m.groupValues[1]) ?: return null
            return Ability.Static(listOf(Mechanic.CantBeTurnedFaceUp), affects = Affected.Objects(affected),
                condition = arcanum.api.Condition.ObjectMatches(affected, ObjectFilter.HasStatus(arcanum.api.Status.FaceDown)))
        }
        // dsk chunk 05: "Enchanted creature doesn't untap during its controller's untap step."
        DOESNT_UNTAP_DURING_CONTROLLERS.matchEntire(line)?.let { m ->
            return Ability.Static(listOf(Mechanic.DoesntUntap), affects = Affected.Objects(attachedSubject(m.groupValues[1]) ?: return null))
        }
        // dsk chunk 04: "This creature can't be blocked by Glimmers." (CR 509.1b)
        CANT_BE_BLOCKED_BY.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            return Ability.Static(listOf(Mechanic.CantBeBlockedBy(Filters.noun(m.groupValues[2]) ?: return null)), affects = Affected.Objects(Objects.Self))
        }
        // dsk chunk 03: "Unlock costs you pay cost {1} less." (the unlock special action, CR 709.5e)
        UNLOCK_COSTS_LESS.matchEntire(line)?.let { m ->
            val mana = ManaCost.parse(m.groupValues[1]) ?: return null
            return Ability.Static(listOf(Mechanic.CostChange(Filters.all(ObjectFilter.AbilityOf(kind = arcanum.api.AbilityKind.Unlock), ObjectFilter.ControlledBy(PlayerFilter.You)),
                change = arcanum.api.CostChange.Less(mana, Value.Fixed(1)))), affects = Affected.Objects(Objects.Self))
        }
        // dsk chunk 01: "Untap each creature you control during each other player's untap step." (CR 502.3)
        UNTAP_DURING_OTHER_UNTAP_STEPS.matchEntire(line)?.let { m ->
            return Ability.Static(listOf(Mechanic.UntapsDuringOtherUntapSteps), affects = Affected.Objects(Objects.Each(Filters.noun(m.groupValues[1]) ?: return null)))
        }
        // dsk chunk 01: "Creatures you control have base power and toughness each equal to the number of creatures you control."
        // (layer 7b, CR 613.4b)
        HAVE_BASE_PT_EQUAL_TO_NUMBER.matchEntire(line)?.let { m ->
            val affected = Filters.noun(m.groupValues[1].replaceFirstChar { it.lowercase() }) ?: return null
            val count = Value.Count(Filters.objects(m.groupValues[2]) ?: return null)
            return Ability.Static(listOf(Mechanic.SetPowerToughness(count, count)), affects = Affected.Objects(Objects.Each(affected)))
        }
        // dsk chunk 01: "If a triggered ability of a permanent you control triggers, that ability triggers an additional time."
        // (CR 603.2d)
