        Tla.PUT_KEYWORD_COUNTER.tla(sentence)?.takeIf { isSelf(it.groupValues[2]) }?.let { m ->
            return listOf(Step.Do(Effect.PutCounters(Objects.Self, Counters.kind(m.groupValues[1]) ?: return null, Value.Fixed(1))))
        }
