    }

    // ---- tla end

    // ---- tmt: Teenage Mutant Ninja Turtles wordings (the set's parser tests, sets/tmt/TmtChunk*Test.kt); regexes in [Tmt]

    private fun tmtSlot(name: String, filter: ObjectFilter, min: Int = 1, max: Int? = 1) =
        TargetSlot(name, TargetKind.Objects(filter), min = Value.Fixed(min), max = max?.let { Value.Fixed(it) })
    private fun tmtNewSlotName(context: Context, base: String) = if (context.targets.none { it.name == base }) base else nextTargetName(base, context.targets.map { it.name })
    private fun tmtKeywords(text: String): List<Ability>? = text.split(LazyRegexes.AND_OR_LIST).map { OracleParser.keyword(it.trim()) ?: return null }
    private fun tmtSentence(text: String) = text.replaceFirstChar { it.uppercase() }.let { if (it.endsWith(".")) it else "$it." }
    private val tmtSneakPaid get() = arcanum.api.Condition.Paid(arcanum.api.Keyword.Sneak.Kind, times = 1, of = Objects.Self)
    private val tmtP1P1 get() = arcanum.api.CounterKind.PowerToughness(1, 1)
    private fun tmtUntilEndOfTurn(objects: Objects, vararg mechanics: Mechanic) =
        Step.Do(Effect.ApplyMechanics(mechanics.toList(), Affected.Objects(objects), arcanum.api.Duration.EndOfTurn))
    private fun tmtSelfName(text: String) = isSelf(text) || text in self

    /** tmt chunk 01: a line with a plural name's verbs ("Don & Raph attack", "The Neutrinos get +1/+0") read as singular. */
    private fun tmtSingular(line: String): String? {
        var out = line
        for (name in self.filter { it.contains(" & ") || it.startsWith("The ") }.sortedByDescending { it.length }) {
            out = Regex(Regex.escape(name) + """ (attack|deal|enter|get|gain|block|have)\b(?: or (attack|block)\b)?""").replace(out) { m ->
                val second = m.groupValues[2].takeIf { it.isNotEmpty() }?.let { " or ${it}s" } ?: ""
                "$name ${if (m.groupValues[1] == "have") "has" else m.groupValues[1] + "s"}$second"
            }
        }
        return out.takeIf { it != line }
    }

    /** tmt: whole lines, tried first in [line]. */
    private fun tmtLine(line: String): Ability? {
        tmtSingular(line)?.let { return line(it) }
        // tmt chunk 01: "Equip—Sacrifice another nonland permanent. Activate only once each turn." (CR 702.6a, 602.5b)
        Tmt.EQUIP_COST.matchEntire(line)?.let { m ->
            return arcanum.api.Keyword.Equip(cost(m.groupValues[1]) ?: return null, perTurn = 1.takeIf { m.groupValues[2].isNotEmpty() })
        }
        // tmt chunk 01: "Kicker—Sacrifice an artifact or creature." (CR 702.33a)
        Tmt.KICKER_COST.matchEntire(line)?.let { m -> return arcanum.api.Keyword.Kicker(listOf(cost(m.groupValues[1]) ?: return null)) }
        // tmt chunk 05: "Creature cards in your graveyard have sneak {3}{B}." (layer 6)
        Tmt.CARDS_HAVE_SNEAK.matchEntire(line)?.let { m ->
            val sneak = arcanum.api.Keyword.Sneak(Cost.mana(ManaCost.parse(m.groupValues[1]) ?: return null))
            return Ability.Static(listOf(Mechanic.GainAbilities(listOf(sneak))), affects = Affected.Objects(Objects.Each(Filters.all(
                ObjectFilter.Type(CardType.Creature), ObjectFilter.InZone(Zone.Graveyard), ObjectFilter.OwnedBy(PlayerFilter.You)))))
        }
        // tmt chunk 05: "You may cast creature spells from your graveyard using their sneak abilities." (CR 601.2a, 702.190a)
        if (Tmt.CAST_USING_SNEAK.matches(line)) {
            return Ability.Static(listOf(Mechanic.MayPlay(Zone.Graveyard, PlayKind.Cast, holder = PlayerFilter.You, viaAlternative = arcanum.api.Keyword.Sneak.Kind)),
                affects = Affected.Objects(Objects.Each(Filters.all(ObjectFilter.Type(CardType.Creature), ObjectFilter.InZone(Zone.Graveyard),
                    ObjectFilter.OwnedBy(PlayerFilter.You)))))
        }
        // tmt chunk 05: "During your turn, you may cast creature spells with power or toughness 1 or less from your graveyard. If you cast
        // a spell this way, that creature enters with a finality counter on it." (CR 122.1h)
        Tmt.DURING_YOUR_TURN_CAST_FROM_GRAVEYARD_FINALITY.matchEntire(line)?.let { m ->
            val n = Value.Fixed(m.groupValues[2].toInt())
            val cards = Filters.all(Filters.noun(m.groupValues[1]) ?: return null, ObjectFilter.Or(listOf(ObjectFilter.Power(arcanum.api.Comparison.AtMost, n),
                ObjectFilter.Toughness(arcanum.api.Comparison.AtMost, n))), ObjectFilter.InZone(Zone.Graveyard), ObjectFilter.OwnedBy(PlayerFilter.You))
            val finality = Mechanic.Replacement(EventPattern.ZoneChange(ObjectFilter.Is(Objects.Affected), to = Zone.Battlefield),
                modify = listOf(Modification.EntersWithCounters(arcanum.api.CounterKind.Named("finality"), Value.Fixed(1))))
            return Ability.Static(listOf(Mechanic.MayPlay(Zone.Graveyard, PlayKind.Cast, holder = PlayerFilter.You, spellGets = listOf(finality))),
                affects = Affected.Objects(Objects.Each(cards)), condition = arcanum.api.Condition.YourTurn)
        }
        // tmt chunk 06: "You may play lands and cast Mutant, Ninja, or Turtle spells from the top of your library. If you cast a creature
        // spell this way, that creature enters with an additional +1/+1 counter on it." (two permissions, CR 601.2a, 305.1)
        Tmt.MAY_PLAY_LANDS_AND_CAST_FROM_TOP.matchEntire(line)?.let { m ->
            val spells = Filters.noun(m.groupValues[1]) ?: return null
            val counter = Mechanic.Replacement(EventPattern.ZoneChange(Filters.all(ObjectFilter.Is(Objects.Affected), ObjectFilter.Type(CardType.Creature)), to = Zone.Battlefield),
                modify = listOf(Modification.EntersWithCounters(tmtP1P1, Value.Fixed(1))))
            fun top(cards: ObjectFilter, how: PlayKind, gets: List<Mechanic>) = Ability.Static(listOf(Mechanic.MayPlay(Zone.Library, how, topOnly = true,
                holder = PlayerFilter.You, spellGets = gets)), affects = Affected.Objects(Objects.Each(Filters.all(cards, ObjectFilter.InZone(Zone.Library),
                ObjectFilter.OwnedBy(PlayerFilter.You)))))
            return null.also { tmtTwo = listOf(top(ObjectFilter.Type(CardType.Land), PlayKind.Play, emptyList()), top(spells, PlayKind.Cast, listOf(counter))) }
        }
        return null
    }

    /** tmt: a line read as two abilities by [tmtMulti]. */
    private var tmtTwo: List<Ability>? = null

    /** tmt: lines that are more than one ability. */
    private fun tmtMulti(line: String): List<Ability>? {
        tmtTwo = null
        tmtLine(line)
        return tmtTwo.also { tmtTwo = null }
    }

    /** tmt: static abilities, tried first in [static]. */
    private fun tmtStatic(line: String): Ability? {
        // tmt chunk 04: "This creature can't be blocked by creatures with greater power." (power compared as blockers are declared, CR 509.1b)
        Tmt.GREATER_POWER.matchEntire(line)?.takeIf { tmtSelfName(it.groupValues[1]) }?.let {
            return Ability.Static(listOf(Mechanic.CantBeBlockedBy(Filters.all(ObjectFilter.Type(CardType.Creature), ObjectFilter.Power(arcanum.api.Comparison.Greater,
                Value.Of(arcanum.api.NumericProperty.Power, Objects.Self, arcanum.api.Combine.Single))))), affects = Affected.Objects(Objects.Self))
        }
        // tmt chunk 04: "This creature can't attack unless you control another artifact."
        Tmt.CANT_ATTACK_UNLESS_CONTROL.matchEntire(line)?.takeIf { tmtSelfName(it.groupValues[1]) }?.let { m ->
            val condition = Conditions.condition("you control " + m.groupValues[2], self) ?: return null
            return Ability.Static(listOf(Mechanic.CantAttack()), affects = Affected.Objects(Objects.Self), condition = arcanum.api.Condition.Not(condition))
        }
        // tmt chunk 04: "Enchanted creature is a Turtle with base power and toughness 0/1. It can't attack and loses all abilities." (layers
        // 4, 6, 7b; a creature type that replaces its other creature types, CR 205.1b)
        Tmt.ENCHANTED_IS_SUBTYPE_BASE_PT.matchEntire(line)?.let { m ->
            val subtype = m.groupValues[1].takeIf { it in RulesWords.subtypes } ?: return null
            return Ability.Static(listOf(
                Mechanic.SetTypes(addSubtypes = listOf(arcanum.api.SubtypeRef.Literal(Subtype(subtype))), replaceSubtypes = true),
                Mechanic.SetPowerToughness(Value.Fixed(m.groupValues[2].toInt()), Value.Fixed(m.groupValues[3].toInt())),
                Mechanic.CantAttack(),
                Mechanic.LoseAbilities(),
            ), affects = Affected.Objects(Objects.AttachedTo(Objects.Self)))
        }
        // tmt chunk 06: "Activated abilities of artifact tokens you control cost {1} less to activate." (CR 602.2b, 601.2f)
        // mkm chunk 02: "… This effect can't reduce the mana in that cost to less than one mana."
        Tmt.ACTIVATED_ABILITIES_COST_LESS.matchEntire(line)?.let { m ->
            val sources = Filters.noun(m.groupValues[1]) ?: return null
            return Ability.Static(listOf(Mechanic.CostChange(ObjectFilter.AbilityOf(kind = arcanum.api.AbilityKind.Activated, source = sources),
                arcanum.api.CostChange.Less(ManaCost.parse(m.groupValues[2]) ?: return null, Value.Fixed(1)), minimum = if (m.groupValues[3].isEmpty()) 0 else 1)),
                affects = Affected.Objects(Objects.Self))
        }
        return null
    }

    /** tmt: trigger events, tried first in [trigger]. */
    private fun tmtTrigger(events: String): arcanum.api.Trigger.On? {
        // tmt chunk 03: "Kitsune enters or deals combat damage to a player" (one ability with two events)
        Tmt.ENTERS_OR_DEALS_COMBAT_DAMAGE.matchEntire(events)?.takeIf { tmtSelfName(it.groupValues[1]) }?.let {
            return arcanum.api.Trigger.On(listOf(EventPattern.ZoneChange(ObjectFilter.Is(Objects.Self), to = Zone.Battlefield),
                EventPattern.Damage(ObjectFilter.Is(Objects.Self), RecipientFilter(players = PlayerFilter.Any), combat = true)))
        }
        // tmt chunk 06: "you put a counter on a creature you control" (of any kind; one event per counter put, CR 122.6)
        Tmt.YOU_PUT_A_COUNTER_ON.matchEntire(events)?.let { m ->
            val filter = Filters.noun(m.groupValues[1].removeArticle()) ?: return null
            return arcanum.api.Trigger.On(EventPattern.CountersPut(filter, null, causedBy = ObjectFilter.ControlledBy(PlayerFilter.You)))
        }
        // tmt chunk 06: "one or more of your opponents are attacked" (once for the declaration, CR 508.3d)
        if (Tmt.OPPONENTS_ARE_ATTACKED.matches(events))
            return arcanum.api.Trigger.On(EventPattern.Attack(ObjectFilter.Any, target = RecipientFilter(players = PlayerFilter.Opponent)), oneOrMore = true)
        return null
    }

    /** tmt: texts of several sentences read as a whole, tried first. */
    private fun tmtWhole(text: String, context: Context): List<Step>? {
        // tmt: the sentence rules that read two sentences
        tmtEffect(text, context)?.let { return it }
        // tmt chunk 03: "Exile up to one other target creature. At the beginning of the next end step, you may pay {3}{B}. If you don't,
        // return that card to the battlefield under its owner's control." (CR 603.7, 118.12)
        Tmt.NEXT_END_STEP_MAY_PAY.matchEntire(text)?.let { m ->
            val read = instructions("${m.groupValues[1]}. At the beginning of the next end step, ${m.groupValues[3]}", seedTargets = context.targets.toList(),
                event = context.event) ?: return null
            val at = read.steps.indexOfLast { (it as? Step.Do)?.effect is Effect.CreateDelayedTrigger }.takeIf { it >= 0 } ?: return null
            val delayed = (read.steps[at] as Step.Do).effect as Effect.CreateDelayedTrigger
            val pay = Step.Pay(Cost.mana(ManaCost.parse(m.groupValues[2]) ?: return null), payer = Players.You, bind = "paid")
            val paid = delayed.copy(instructions = delayed.instructions.copy(steps = listOf(pay,
                Step.If(arcanum.api.Condition.Not(arcanum.api.Condition.Did("paid")), then = delayed.instructions.steps))))
            context.targets.clear(); context.targets += read.targets
            return read.steps.toMutableList().also { it[at] = Step.Do(paid) }
        }
        // tmt chunk 06: "Whenever a creature you control attacks alone this turn, put three +1/+1 counters on it. It gains trample, lifelink, and
        // indestructible until end of turn." (a delayed trigger for the rest of the turn with all its sentences, CR 603.7c)
        Tmt.WHENEVER_THIS_TURN.matchEntire(text)?.let { m ->
            val (trigger, onlyIf) = trigger(m.groupValues[1]) ?: return null
            if (onlyIf != null) return null
            val read = instructions(m.groupValues[2], event = trigger.events.first()) ?: return null
            return listOf(Step.Do(Effect.CreateDelayedTrigger(trigger, read, duration = arcanum.api.Duration.EndOfTurn, repeats = true)))
        }
        // tmt chunk 02: "Choose target creature an opponent controls. Exile that creature until this creature leaves the battlefield. If this
        // creature's sneak cost was paid, instead exile the chosen creature." (CR 610.3)
        Tmt.SNEAK_INSTEAD_EXILE.matchEntire(text)?.let { m ->
            val noun = Tmt.CHOOSE_TARGET.matchEntire(m.groupValues[1])?.groupValues?.get(1) ?: return null
            if (!tmtSelfName(m.groupValues[2])) return null
            val condition = Conditions.condition(m.groupValues[3], self) ?: return null
            val name = tmtNewSlotName(context, Filters.slotName(noun))
            context.targets += tmtSlot(name, Filters.noun(noun) ?: return null)
            val target = Objects.Target(name)
            return listOf(Step.If(condition, then = listOf(Step.Do(Effect.Move(target, Destination(Zone.Exile)))),
                otherwise = listOf(Step.Do(Effect.Move(target, Destination(Zone.Exile), untilLeaves = Objects.Self)))))
        }
        // tmt chunk 04: "Gain control of all artifacts your opponents control until end of turn. Untap them. They gain haste until end of turn."
        // (the set is locked as the effect begins, CR 611.2c)
        Tmt.GAIN_CONTROL_OF_ALL_UNTIL_EOT.matchEntire(text)?.let { m ->
            val filter = Filters.noun(m.groupValues[1]) ?: return null
            val keyword = OracleParser.keyword(m.groupValues[2]) ?: return null
            val them = Objects.Bound("them")
            return listOf(Step.Bind(Objects.Each(filter), "them"),
                tmtUntilEndOfTurn(them, Mechanic.ControlledBy(Players.You)),
                Step.Do(Effect.Untap(them)),
                tmtUntilEndOfTurn(them, Mechanic.GainAbilities(listOf(keyword))))
        }
        // tmt chunk 04: "You may put a card from your hand on the bottom of your library. If you do, draw a card."
        Tmt.MAY_PUT_FROM_HAND_ON_BOTTOM_DRAW.find(text)?.takeIf { it.range.last == text.lastIndex }?.let { m ->
            val before = text.substring(0, m.range.first).trim()
            val first = if (before.isEmpty()) emptyList() else (tmtRead(before, context) ?: return null)
            return first + listOf(
                Step.Pay(steps = listOf(Step.Choose(arcanum.api.Choice.Objects(ObjectFilter.Any, Value.Fixed(1), Value.Fixed(1),
                    from = Objects.Each(Filters.all(ObjectFilter.InZone(Zone.Hand), ObjectFilter.OwnedBy(PlayerFilter.You)))), bind = "put", chooser = Players.You),
                    Step.Do(Effect.Move(Objects.Bound("put"), Destination(Zone.Library, libraryPosition = -1)))), payer = Players.You, bind = "bottom"),
                Step.If(arcanum.api.Condition.Did("bottom"), then = listOf(Step.Do(Effect.Draw(Players.You, Value.Fixed(1))))))
        }
        // tmt chunk 06: "You may search your library for a Food card, reveal it, put it into your hand, then shuffle. If you don't put a card
        // into your hand this way, create a Food token."
        Tmt.MAY_SEARCH_IF_YOU_DONT_PUT.matchEntire(text)?.let { m ->
            val filter = Filters.noun(m.groupValues[1] + " card") ?: return null
            val otherwise = effect(tmtSentence(m.groupValues[2]), context) ?: return null
            return listOf(Step.May(listOf(
                Step.Do(Effect.Search(Players.You, filter, max = Value.Fixed(1), reveal = true, zones = listOf(Zone.Library), bind = "found", searcher = Players.You)),
                Step.Do(Effect.Move(Objects.Bound("found"), Destination(Zone.Hand))),
                Step.Do(Effect.Shuffle(Players.You))), player = Players.You),
                Step.If(arcanum.api.Condition.Not(arcanum.api.Condition.NonEmpty("found")), then = otherwise))
        }
        // tmt chunk 06: "You may remove a counter from her. When you do, destroy target artifact or enchantment that player controls." (CR 603.12)
        Tmt.MAY_REMOVE_COUNTER_WHEN_YOU_DO.matchEntire(text)?.let { m ->
            if (!tmtSelfName(m.groupValues[1]) && m.groupValues[1] !in setOf("her", "him", "it", "them")) return null
            val reflexive = instructions(tmtSentence(m.groupValues[2]), event = context.event) ?: return null
            return listOf(Step.Pay(Cost(listOf(CostPart.RemoveCounters(null, Value.Fixed(1), CostObjects.Self))), payer = Players.You, bind = "removed"),
                Step.If(arcanum.api.Condition.Did("removed"), then = listOf(Step.Do(Effect.ReflexiveTrigger(reflexive)))))
        }
        // tmt chunk 06: "Look at the top eight cards of your library. Put up to two creature cards with total mana value 6 or less from among them
        // onto the battlefield and the rest on the bottom of your library in a random order."
        Tmt.LOOK_PUT_TOTAL_MANA_VALUE.matchEntire(text)?.let { m ->
            val n = Numbers.count(m.groupValues[1]) ?: return null
            val max = Numbers.count(m.groupValues[2]) ?: return null
            val filter = Filters.noun(m.groupValues[3].removeSuffix("s").replace("cards", "card")) ?: return null
            return listOf(Step.Do(Effect.LookAt(Objects.LibraryCards(Players.You, Value.Fixed(n), fromTop = true), Players.You, bind = "seen")),
                Step.Choose(arcanum.api.Choice.Objects(filter, Value.Fixed(0), Value.Fixed(max), from = Objects.Bound("seen"),
                    totalAtMost = arcanum.api.Choice.TotalLimit(arcanum.api.NumericProperty.ManaValue, Value.Fixed(m.groupValues[4].toInt()))),
                    bind = "chosen", chooser = Players.You),
                Step.Do(Effect.Move(Objects.Bound("chosen"), Destination(Zone.Battlefield))),
                Step.Do(Effect.Move(Objects.Except(Objects.Bound("seen"), Objects.Bound("chosen")), Destination(Zone.Library, libraryPosition = -1, randomOrder = true))))
        }
        // tmt chunk 06: "Attach it to target creature you control. When you do, equipped creature fights up to one target creature an opponent
        // controls." (CR 603.12, 701.14)
        Tmt.ATTACH_WHEN_YOU_DO_FIGHTS.matchEntire(text)?.let { m ->
            val name = tmtNewSlotName(context, Filters.slotName(m.groupValues[1]))
            context.targets += tmtSlot(name, Filters.noun(m.groupValues[1]) ?: return null)
            val other = Filters.noun(m.groupValues[2]) ?: return null
            val reflexive = Instructions(targets = listOf(tmtSlot("other " + Filters.slotName(m.groupValues[2]), other, min = 0)),
                steps = listOf(Step.Do(Effect.Fight(Objects.AttachedTo(Objects.Self), Objects.Target("other " + Filters.slotName(m.groupValues[2]))))))
            return listOf(Step.Do(Effect.Attach(Objects.Self, Recipients(objects = Objects.Target(name)))), Step.Do(Effect.ReflexiveTrigger(reflexive)))
        }
        // tmt chunk 07: "Choose target artifact card in your graveyard. Return it to the battlefield if it's an artifact creature card.
        // Otherwise, return it to the battlefield and it's a 3/3 Robot artifact creature with flying." (CR 611.2e)
        Tmt.RETURN_IF_ARTIFACT_CREATURE_OTHERWISE.matchEntire(text)?.let { m ->
            val name = tmtNewSlotName(context, Filters.slotName(m.groupValues[1]))
            context.targets += tmtSlot(name, Filters.noun(m.groupValues[1]) ?: return null)
            val target = Objects.Target(name)
            val subtype = m.groupValues[4].takeIf { it in RulesWords.subtypes } ?: return null
            val keywords = tmtKeywords(m.groupValues[5]) ?: return null
            val becomes = listOf(Mechanic.SetTypes(add = listOf(CardType.Artifact, CardType.Creature), addSubtypes = listOf(arcanum.api.SubtypeRef.Literal(Subtype(subtype)))),
                Mechanic.SetPowerToughness(Value.Fixed(m.groupValues[2].toInt()), Value.Fixed(m.groupValues[3].toInt())), Mechanic.GainAbilities(keywords))
            return listOf(Step.If(arcanum.api.Condition.ObjectMatches(target, Filters.all(ObjectFilter.Type(CardType.Artifact), ObjectFilter.Type(CardType.Creature))),
                then = listOf(Step.Do(Effect.Move(target, Destination(Zone.Battlefield)))),
                otherwise = listOf(Step.Do(Effect.Move(target, Destination(Zone.Battlefield, entersAs = becomes))))))
        }
        // tmt chunk 07: "Untap one or two target attacking creatures. After this phase, there is an additional combat phase." (CR 500.8)
        Tmt.UNTAP_ONE_OR_TWO_ADDITIONAL_COMBAT.matchEntire(text)?.let { m ->
            context.targets += tmtSlot("creatures", Filters.noun(m.groupValues[1].replace("creatures", "creature")) ?: return null, min = 1, max = 2)
            return listOf(Step.Do(Effect.Untap(Objects.Target("creatures"))), Step.Do(Effect.ExtraCombat()))
        }
        // tmt chunk 07: "Reveal cards from the top of your library until you reveal a creature card. Put that card onto the battlefield tapped
        // and attacking and the rest on the bottom of your library in a random order." (CR 508.4)
        Tmt.REVEAL_UNTIL_TAPPED_ATTACKING.matchEntire(text)?.let { m ->
            val filter = Filters.noun(m.groupValues[1] + " card") ?: return null
            return listOf(Step.Do(Effect.RevealUntil(filter, Players.You, Value.Fixed(1), reveal = true, foundBind = "found", restBind = "rest")),
                Step.Do(Effect.Move(Objects.Bound("found"), Destination(Zone.Battlefield, tapped = true, attacking = arcanum.api.AttackTarget.Chosen))),
                Step.Do(Effect.Move(Objects.Bound("rest"), Destination(Zone.Library, libraryPosition = -1, randomOrder = true))))
        }
        // tmt chunk 08: "Create a token that's a copy of another target artifact you control. That token gains haste. Sacrifice it at the
        // beginning of the next end step." (CR 603.7)
        Tmt.TOKEN_COPY_GAINS_HASTE_SACRIFICE.matchEntire(text)?.let { m ->
            val noun = m.groupValues[1].removePrefix("another ").removePrefix("target ")
            val another = m.groupValues[1].startsWith("another ")
            val filter = Filters.noun(noun.removePrefix("target ")) ?: return null
            val name = tmtNewSlotName(context, Filters.slotName(noun.removePrefix("target ")))
            context.targets += tmtSlot(name, if (another) Filters.all(ObjectFilter.Not(ObjectFilter.Is(Objects.Self)), filter) else filter)
            return listOf(Step.Do(Effect.CreateToken(arcanum.api.TokenSpec.CopyOf(Objects.Target(name)), Value.Fixed(1), Players.You, bind = "token")),
                Step.Do(Effect.ApplyMechanics(listOf(Mechanic.GainAbilities(listOf(arcanum.api.Keyword.Haste))), Affected.Objects(Objects.Bound("token")),
                    arcanum.api.Duration.Indefinitely)),
                Step.Do(Effect.CreateDelayedTrigger(arcanum.api.Trigger.On(EventPattern.StepBegins(arcanum.api.TurnStep.End, PlayerFilter.Any)),
                    Instructions(steps = listOf(Step.Do(Effect.Sacrifice(Objects.Bound("token"))))))))
        }
        // tmt chunk 08: "Return a creature card exiled with this land to the battlefield under your control. Return each other card exiled
        // with this land to its owner's hand." (CR 607.2a)
        Tmt.RETURN_EXILED_WITH_CREATURE_AND_OTHERS.matchEntire(text)?.let { m ->
            if (!tmtSelfName(m.groupValues[2]) || !tmtSelfName(m.groupValues[3])) return null
            val exiled = Objects.Where(Objects.Remembered(EXILED_WITH), ObjectFilter.InZone(Zone.Exile))
            return listOf(Step.Choose(arcanum.api.Choice.Objects(Filters.noun(m.groupValues[1]) ?: return null, Value.Fixed(1), Value.Fixed(1), from = exiled),
                bind = "chosen", chooser = Players.You),
                Step.Do(Effect.Move(Objects.Bound("chosen"), Destination(Zone.Battlefield, controller = Players.You))),
                Step.Do(Effect.Move(Objects.Except(exiled, Objects.Bound("chosen")), Destination(Zone.Hand))))
        }
        // tmt chunk 03: "Search your library and/or outside the game for exactly four legendary creature cards you own with different names,
        // then reveal those cards. An opponent chooses two of them. Put the chosen cards into your hand and shuffle the rest into your library."
        Tmt.SEARCH_AND_OR_OUTSIDE.matchEntire(text)?.let { m ->
            val n = Numbers.count(m.groupValues[1]) ?: return null
            val chosen = Numbers.count(m.groupValues[3]) ?: return null
            val filter = Filters.all(Filters.noun(m.groupValues[2].removeSuffix("s").replace("cards", "card")) ?: return null, ObjectFilter.OwnedBy(PlayerFilter.You))
            return listOf(Step.Do(Effect.Search(Players.You, filter, max = Value.Fixed(n), reveal = true, zones = listOf(Zone.Library, Zone.Outside),
                    differentNames = true, bind = "found", searcher = Players.You)),
                Step.Choose(arcanum.api.Choice.Objects(ObjectFilter.Any, Value.Fixed(chosen), Value.Fixed(chosen), from = Objects.Bound("found")),
                    bind = "chosen", chooser = Players.Each(PlayerFilter.Opponent)),
                Step.Do(Effect.Move(Objects.Bound("chosen"), Destination(Zone.Hand))),
                Step.Do(Effect.Move(Objects.Except(Objects.Bound("found"), Objects.Bound("chosen")), Destination(Zone.Library))),
                Step.Do(Effect.Shuffle(Players.You)))
        }
        return null
    }

    /** tmt chunk 04: "to activate an ability", "cast an artifact spell" (CR 106.6). */
    private fun tmtSpendUse(use: String): ObjectFilter? {
        val u = use.removePrefix("to ")
        if (u == "activate an ability" || u == "activate abilities") return ObjectFilter.AbilityOf(kind = arcanum.api.AbilityKind.Activated)
        LazyRegexes.CAST_A_WORD_SPELL.matchEntire(u)?.let { m ->
            return Filters.all(ObjectFilter.Category(arcanum.api.ObjectCategory.Spell), Filters.noun(m.groupValues[1]) ?: return null)
        }
        return null
    }

    /** tmt chunk 11: the steps with their last token creation naming the token, if only steps about that token follow it. */
    private fun tmtCreatedToken(steps: List<Step>): Pair<List<Step>, Objects>? {
        val at = steps.indexOfLast { (it as? Step.Do)?.effect is Effect.CreateToken }.takeIf { it >= 0 } ?: return null
        val create = (steps[at] as Step.Do).effect as Effect.CreateToken
        // one defined token ("create a 2/2 red Mutant creature token"); copies have their own rules
        if (create.token !is arcanum.api.TokenSpec.Defined || create.count != Value.Fixed(1)) return null
        val name = create.bind ?: "token"
        val about = Objects.Bound(name)
        val after = steps.drop(at + 1)
        if (!after.all { step -> val e = (step as? Step.Do)?.effect
                (e is Effect.ApplyMechanics && e.affects == Affected.Objects(about)) || e is Effect.CreateDelayedTrigger }) return null
        return steps.toMutableList().also { it[at] = Step.Do(create.copy(bind = name)) } to about
    }

    /** tmt: [text] read as instructions with the context's targets. */
    private fun tmtRead(text: String, context: Context): List<Step>? {
        val read = instructions(text, seedTargets = context.targets.toList(), event = context.event) ?: return null
        context.targets.clear(); context.targets += read.targets
        return read.steps
    }

    /** tmt: sentences that change the steps before them, tried first in [modify]. */
    private fun tmtModify(sentence: String, steps: List<Step>, context: Context): List<Step>? {
        // tmt chunk 11: "It gains haste until end of turn." / "Destroy it at the beginning of the next end step." right after creating a
        // token: "it" is that token (CR 111.1)
        Tmt.IT_GAINS_UNTIL_EOT.matchEntire(sentence)?.let { m ->
            val (before, token) = tmtCreatedToken(steps) ?: return@let
            val keywords = tmtKeywords(m.groupValues[1]) ?: return null
            return before + tmtUntilEndOfTurn(token, Mechanic.GainAbilities(keywords))
        }
        Tmt.ACT_ON_IT_NEXT_END_STEP.matchEntire(sentence)?.let { m ->
            val (before, token) = tmtCreatedToken(steps) ?: return@let
            val effect = if (m.groupValues[1] == "Destroy") Effect.Destroy(token) else Effect.Sacrifice(token)
            return before + Step.Do(Effect.CreateDelayedTrigger(arcanum.api.Trigger.On(EventPattern.StepBegins(arcanum.api.TurnStep.End, PlayerFilter.Any)),
                Instructions(steps = listOf(Step.Do(effect)))))
        }
        // tmt chunk 01: "If it isn't a creature, it becomes a 0/0 Robot creature in addition to its other types." after putting counters on
        // it: the object the counters were put on (layers 4 and 7b, indefinitely, CR 611.2a)
        Tmt.IF_IT_ISNT_CREATURE_BECOMES.matchEntire(sentence)?.let { m ->
            val it = ((steps.lastOrNull() as? Step.Do)?.effect as? Effect.PutCounters)?.objects ?: return null
            val subtypes = m.groupValues[3].split(' ').map { arcanum.api.SubtypeRef.Literal(Subtype(it.takeIf { s -> s in RulesWords.subtypes } ?: return null)) }
            return steps + Step.If(arcanum.api.Condition.ObjectMatches(it, ObjectFilter.Not(ObjectFilter.Type(CardType.Creature))), then = listOf(
                Step.Do(Effect.ApplyMechanics(listOf(Mechanic.SetTypes(add = listOf(CardType.Creature), addSubtypes = subtypes),
                    Mechanic.SetPowerToughness(Value.Fixed(m.groupValues[1].toInt()), Value.Fixed(m.groupValues[2].toInt()))),
                    Affected.Objects(it), arcanum.api.Duration.Indefinitely))))
        }
        // tmt chunk 02: "If this spell's sneak cost was paid, they enter tapped and attacking." after creating tokens (CR 508.4)
        Tmt.SNEAK_THEY_ENTER_TAPPED_AND_ATTACKING.matchEntire(sentence)?.let { m ->
            val condition = Conditions.condition(m.groupValues[1] + " was paid", self) ?: return null
            val create = (steps.lastOrNull() as? Step.Do)?.effect as? Effect.CreateToken ?: return null
            return steps.dropLast(1) + Step.If(condition, then = listOf(Step.Do(create.copy(tapped = true, attacking = arcanum.api.AttackTarget.Chosen))),
                otherwise = listOf(steps.last()))
        }
        // tmt chunk 02: "If her sneak cost was paid this turn, instead return that card to the battlefield."
        Tmt.IF_INSTEAD_RETURN_TO_BATTLEFIELD.matchEntire(sentence)?.let { m ->
            val condition = Conditions.condition(m.groupValues[1], self) ?: return null
            val move = (steps.lastOrNull() as? Step.Do)?.effect as? Effect.Move ?: return null
            return steps.dropLast(1) + Step.If(condition, then = listOf(Step.Do(move.copy(to = Destination(Zone.Battlefield)))), otherwise = listOf(steps.last()))
        }
        // tmt chunk 04: "If this spell was kicked, that creature gets -5/-5 until end of turn instead." (CR 702.33d)
        Tmt.KICKED_INSTEAD.matchEntire(sentence)?.let { m ->
            val last = (steps.lastOrNull() as? Step.Do)?.effect as? Effect.ApplyMechanics ?: return null
            val kicked = arcanum.api.Condition.Paid(arcanum.api.Keyword.Kicker.Kind, times = 1, of = Objects.Self)
            val pt = Mechanic.ModifyPowerToughness(Value.Fixed(m.groupValues[1].toInt()), Value.Fixed(m.groupValues[2].toInt()))
            return steps.dropLast(1) + Step.If(kicked, then = listOf(Step.Do(last.copy(mechanics = listOf(pt)))), otherwise = listOf(steps.last()))
        }
        // tmt chunk 07: "Then if you control five or more Ninjas, that player loses half their life, rounded up." (CR 107.1a)
        Tmt.THEN_IF_CONTROL_LOSES_HALF.matchEntire(sentence)?.let { m ->
            val n = Numbers.count(m.groupValues[1]) ?: return null
            val filter = Filters.noun(m.groupValues[2] + " you control") ?: return null
            val player = Players.EventPlayer
            return steps + Step.If(arcanum.api.Condition.Exists(filter, atLeast = n), then = listOf(Step.Do(Effect.LoseLife(player,
                Value.Half(Value.LifeOf(player), roundUp = m.groupValues[3] == "up")))))
        }
        // tmt chunk 07: "If its mana value was 4 or less, create a Food token." after destroying a target (as it last existed, CR 608.2h)
        Tmt.IF_ITS_MANA_VALUE_WAS.matchEntire(sentence)?.let { m ->
            val target = context.targets.lastOrNull()?.takeIf { it.what is TargetKind.Objects }?.let { Objects.Target(it.name) } ?: return null
            val comparison = if (m.groupValues[2] == "less") arcanum.api.Comparison.AtMost else arcanum.api.Comparison.AtLeast
            val then = effect(tmtSentence(m.groupValues[3]), context) ?: return null
            return steps + Step.If(arcanum.api.Condition.ObjectMatches(target, ObjectFilter.ManaValue(comparison, Value.Fixed(m.groupValues[1].toInt()))), then = then)
        }
        // tmt chunk 08: "Then if that creature is a Mutant, Ninja, or Turtle, double the number of +1/+1 counters on it." (CR 701.10e)
        Tmt.THEN_IF_DOUBLE_COUNTERS.matchEntire(sentence)?.let { m ->
            val target = context.targets.lastOrNull()?.takeIf { it.what is TargetKind.Objects }?.let { Objects.Target(it.name) } ?: return null
            val filter = Filters.noun(m.groupValues[1]) ?: return null
            return steps + Step.If(arcanum.api.Condition.ObjectMatches(target, filter), then = listOf(Step.Do(Effect.Action(
                arcanum.api.KeywordAction.Double(arcanum.api.Doubled.Counters(target, tmtP1P1))))))
        }
        return null
    }

    /** tmt: effect sentences, tried first in [effectRules]. */
    private fun tmtEffect(sentence: String, context: Context): List<Step>? {
        // tmt chunk 02: "Return one or two target creature cards each with mana value 3 or less from your graveyard to the battlefield."
        Tmt.RETURN_ONE_OR_TWO_FROM_GRAVEYARD.matchEntire(sentence)?.let { m ->
            val filter = Filters.noun("${m.groupValues[1]} card${m.groupValues[2]} in your graveyard") ?: return null
            context.targets += tmtSlot(tmtNewSlotName(context, "cards"), filter, min = 1, max = 2)
            val zone = if (m.groupValues[3] == "battlefield") Zone.Battlefield else Zone.Hand
            return listOf(Step.Do(Effect.Move(Objects.Target(context.targets.last().name), Destination(zone))))
        }
        // tmt chunk 07: "Go Ninja Go deals damage equal to the greatest power among creatures you control to target creature an opponent controls."
        Tmt.DEALS_DAMAGE_EQUAL_TO_TARGET.matchEntire(sentence)?.takeIf { tmtSelfName(it.groupValues[1]) }?.let { m ->
            val amount = Values.value(m.groupValues[2], exiledCard) ?: return null
            val name = tmtNewSlotName(context, Filters.slotName(m.groupValues[3]))
            context.targets += tmtSlot(name, Filters.noun(m.groupValues[3]) ?: return null)
            return listOf(Step.Do(Effect.DealDamage(Recipients(objects = Objects.Target(name)), amount, Objects.Self)))
        }
        // tmt chunk 02: "You may put a creature card and/or a land card from your hand onto the battlefield." (one of each at most)
        Tmt.MAY_PUT_AND_OR_FROM_HAND.matchEntire(sentence)?.let { m ->
            val hand = Objects.Each(Filters.all(ObjectFilter.InZone(Zone.Hand), ObjectFilter.OwnedBy(PlayerFilter.You)))
            fun choose(noun: String): Step? = Step.Choose(arcanum.api.Choice.Objects(Filters.all(Filters.noun(noun) ?: return null,
                ObjectFilter.Category(arcanum.api.ObjectCategory.Card)), Value.Fixed(0), Value.Fixed(1), from = hand), bind = noun, chooser = Players.You)
            return listOf(choose(m.groupValues[1]) ?: return null, choose(m.groupValues[2]) ?: return null,
                Step.Do(Effect.Move(Objects.Union(listOf(Objects.Bound(m.groupValues[1]), Objects.Bound(m.groupValues[2]))), Destination(Zone.Battlefield))))
        }
        // tmt chunk 14: "Exile target creature you own." (linked to "exiled with this land", CR 607.2a)
        Tmt.EXILE_TARGET_YOU_OWN.matchEntire(sentence)?.let { m ->
            val name = tmtNewSlotName(context, Filters.slotName(m.groupValues[1]))
            context.targets += tmtSlot(name, Filters.noun(m.groupValues[1] + " you own") ?: return null)
            val exile = Step.Do(Effect.Move(Objects.Target(name), Destination(Zone.Exile), postBind = "exiled"))
            return if (linkedExile) listOf(exile, Step.Do(Effect.Remember(EXILED_WITH, Objects.Bound("exiled")))) else listOf(exile)
        }
        // tmt chunk 03: "Exile enchanted creature."
        Tmt.VERB_ATTACHED.matchEntire(sentence)?.let { m ->
            val attached = Objects.AttachedTo(Objects.Self)
            return listOf(Step.Do(when (m.groupValues[1]) { "Exile" -> Effect.Move(attached, Destination(Zone.Exile)); "Destroy" -> Effect.Destroy(attached); else -> Effect.Tap(attached) }))
        }
        // tmt chunk 04: "Return it to the battlefield tapped under its owner's control." (it: the card that died, CR 400.7)
        Tmt.RETURN_IT_TAPPED_UNDER_OWNER.matchEntire(sentence)?.let {
            val it = context.it ?: return null
            return listOf(Step.Do(Effect.Move(it, Destination(Zone.Battlefield, tapped = true, controller = Players.OwnerOf(it)))))
        }
        // tmt chunk 04: "Put target creature card from your graveyard on top of your library."
        Tmt.PUT_TARGET_FROM_GRAVEYARD_ON_TOP.matchEntire(sentence)?.let { m ->
            val name = tmtNewSlotName(context, Filters.slotName(m.groupValues[1]))
            context.targets += tmtSlot(name, Filters.noun(m.groupValues[1] + " in your graveyard") ?: return null)
            return listOf(Step.Do(Effect.Move(Objects.Target(name), Destination(Zone.Library, libraryPosition = 0))))
        }
        // tmt chunk 06: "Up to one target attacking creature gets +X/+X until end of turn" (X defined by "where X is", CR 107.3c)
        Tmt.UP_TO_ONE_TARGET_GETS.matchEntire(sentence)?.let { m ->
            fun amount(text: String): Value? = when {
                text.endsWith("X") -> if (text.startsWith("-")) null else Value.Announced("X")
                else -> text.removePrefix("+").toIntOrNull()?.let { Value.Fixed(it) }
            }
            val name = tmtNewSlotName(context, Filters.slotName(m.groupValues[1]))
            context.targets += tmtSlot(name, Filters.noun(m.groupValues[1]) ?: return null, min = 0)
            return listOf(tmtUntilEndOfTurn(Objects.Target(name), Mechanic.ModifyPowerToughness(amount(m.groupValues[2]) ?: return null, amount(m.groupValues[3]) ?: return null)))
        }
        // tmt chunk 07: "Put three +1/+1 counters on up to one other target artifact or creature."
        Tmt.PUT_COUNTERS_ON_UP_TO_ONE.matchEntire(sentence)?.let { m ->
            val n = Numbers.count(m.groupValues[1]) ?: return null
            val kind = Counters.kind(m.groupValues[2]) ?: return null
            val noun = Filters.noun(m.groupValues[4]) ?: return null
            val filter = if (m.groupValues[3].isEmpty()) noun else Filters.all(ObjectFilter.Not(ObjectFilter.Is(Objects.Self)), noun)
            val name = tmtNewSlotName(context, Filters.slotName(m.groupValues[4]))
            context.targets += tmtSlot(name, filter, min = 0)
            return listOf(Step.Do(Effect.PutCounters(Objects.Target(name), kind, Value.Fixed(n))))
        }
        // tmt chunk 05: "Exile target creature card from your graveyard. Create a token that's a copy of it, except it isn't legendary and is
        // a Mutant in addition to its other types." (CR 707.9b; the card exiled, CR 400.7, linked to the Saga's later chapters, CR 607.2a)
        Tmt.EXILE_THEN_COPY_IT.matchEntire(sentence)?.let { m ->
            val subtype = m.groupValues[2].takeIf { it in RulesWords.subtypes } ?: return null
            val noun = m.groupValues[1].replace(" from your graveyard", " in your graveyard")
            val name = tmtNewSlotName(context, Filters.slotName(noun))
            context.targets += tmtSlot(name, Filters.noun(noun) ?: return null)
            return listOf(Step.Do(Effect.Move(Objects.Target(name), Destination(Zone.Exile), postBind = "exiled"))) +
                (if (linkedExile) listOf(Step.Do(Effect.Remember(EXILED_WITH, Objects.Bound("exiled")))) else emptyList()) +
                tmtCopyExcept(Objects.Bound("exiled"), subtype)
        }
        // tmt chunk 07: "Search your library for up to two basic land cards, put them onto the battlefield tapped, then shuffle."
        Tmt.SEARCH_UP_TO_PUT_THEM_TAPPED.matchEntire(sentence)?.let { m ->
            val n = Numbers.count(m.groupValues[1]) ?: return null
            val filter = Filters.noun(m.groupValues[2] + " card") ?: return null
            return listOf(Step.Do(Effect.Search(Players.You, filter, max = Value.Fixed(n), zones = listOf(Zone.Library), bind = "found", searcher = Players.You)),
                Step.Do(Effect.Move(Objects.Bound("found"), Destination(Zone.Battlefield, tapped = m.groupValues[3].isNotEmpty()))),
                Step.Do(Effect.Shuffle(Players.You)))
        }
        // tmt chunk 04: "Add that much {R}." (the damage dealt, CR 120.3)
        Tmt.ADD_THAT_MUCH.matchEntire(sentence)?.let { m ->
            return listOf(Step.Do(Effect.AddMana(ManaProduction(ManaKind.Fixed(ManaCost.parse(m.groupValues[1]) ?: return null, times = Value.EventAmount)), Players.You)))
        }
        // tmt chunk 03: "You create a 1/1 black Ninja creature token." ("you" after another subject)
        Tmt.YOU_CREATE.matchEntire(sentence)?.let { m -> return effect("Create " + m.groupValues[1], context) }
        // tmt chunk 03: "Mill two cards, draw two cards, then discard two cards."
        Tmt.MILL_DRAW_THEN_DISCARD.matchEntire(sentence)?.let { m ->
            return listOf(Step.Do(Effect.Mill(Players.You, Value.Fixed(Numbers.count(m.groupValues[1]) ?: return null))),
                Step.Do(Effect.Draw(Players.You, Value.Fixed(Numbers.count(m.groupValues[2]) ?: return null))),
                Step.Do(Effect.Discard(Players.You, Value.Fixed(Numbers.count(m.groupValues[3]) ?: return null), ObjectFilter.Any)))
        }
        // tmt chunk 04: "You may attach this Equipment to it." (it: the creature that entered)
        Tmt.MAY_ATTACH_TO_IT.matchEntire(sentence)?.takeIf { tmtSelfName(it.groupValues[1]) }?.let {
            val it = context.it ?: return null
            return listOf(Step.May(listOf(Step.Do(Effect.Attach(Objects.Self, Recipients(objects = it)))), player = Players.You))
        }
        // tmt chunk 04: "Target opponent mills half their library, rounded up." (CR 107.1a)
        Tmt.MILLS_HALF_LIBRARY.matchEntire(sentence)?.let { m ->
            val players = when (m.groupValues[1]) {
                "Target opponent" -> { context.targets += TargetSlot("opponent", TargetKind.Players(PlayerFilter.Opponent), min = Value.Fixed(1), max = Value.Fixed(1)); Players.Target("opponent") }
                "Target player" -> { context.targets += TargetSlot("player", TargetKind.Players(PlayerFilter.Any), min = Value.Fixed(1), max = Value.Fixed(1)); Players.Target("player") }
                else -> Players.Each(PlayerFilter.Opponent)
            }
            val library = if (players is Players.Each) Players.Affected else players
            val size = Value.Count(Objects.Each(Filters.all(ObjectFilter.InZone(Zone.Library), ObjectFilter.OwnedBy(PlayerFilter.Is(library)))))
            return listOf(Step.Do(Effect.Mill(players, Value.Half(size, roundUp = m.groupValues[2] == "up"))))
        }
        // tmt chunk 04: "Draw cards equal to the difference." after "if you have fewer than four cards in hand" (CR 603.4)
        if (Tmt.DRAW_EQUAL_TO_DIFFERENCE.matches(sentence)) {
            val condition = tmtLastIf as? arcanum.api.Condition.Compare ?: return null
            return listOf(Step.Do(Effect.Draw(Players.You, Value.Difference(condition.right, condition.left))))
        }
        // tmt chunk 04: "Until end of turn, target artifact or creature becomes an artifact creature with base power and toughness 4/5."
        // (layers 4 and 7b; an Equipment stops being attached, CR 301.5c)
        Tmt.BECOMES_ARTIFACT_CREATURE_BASE.matchEntire(sentence)?.let { m ->
            val name = tmtNewSlotName(context, Filters.slotName(m.groupValues[1]))
            context.targets += tmtSlot(name, Filters.noun(m.groupValues[1]) ?: return null)
            return listOf(tmtUntilEndOfTurn(Objects.Target(name), Mechanic.SetTypes(add = listOf(CardType.Artifact, CardType.Creature)),
                Mechanic.SetPowerToughness(Value.Fixed(m.groupValues[2].toInt()), Value.Fixed(m.groupValues[3].toInt()))))
        }
        // tmt chunk 04: "Until end of turn, Mondo Gecko becomes the color of your choice and gains hexproof from that color." (CR 702.11d)
        Tmt.BECOMES_COLOR_OF_CHOICE_HEXPROOF.matchEntire(sentence)?.takeIf { tmtSelfName(it.groupValues[1]) }?.let {
            val color = arcanum.api.ColorRef.Chosen("color")
            return listOf(Step.Choose(arcanum.api.Choice.Color(), bind = "color", chooser = Players.You),
                tmtUntilEndOfTurn(Objects.Self, Mechanic.SetColors(listOf(color)),
                    Mechanic.GainAbilities(listOf(arcanum.api.Keyword.HexproofFrom(ObjectFilter.OfColor(color))))))
        }
        // tmt chunk 04: 'Until end of turn, target creature gains deathtouch and "When this creature dies, return it to the battlefield tapped
        // under its owner's control."' (CR 113.2c)
        Tmt.UNTIL_EOT_GAINS_AND_QUOTED.matchEntire(sentence)?.let { m ->
            val keywords = tmtKeywords(m.groupValues[3]) ?: return null
            val granted = Sentences(setOf("this creature")).line(m.groupValues[4]) ?: return null
            val name = tmtNewSlotName(context, Filters.slotName(m.groupValues[2]))
            val noun = Filters.noun(m.groupValues[2]) ?: return null
            // fdn chunk 07: "another target Goblin you control" (not this creature)
            context.targets += tmtSlot(name, if (m.groupValues[1].isEmpty()) noun else Filters.all(ObjectFilter.Not(ObjectFilter.Is(Objects.Self)), noun))
            return listOf(tmtUntilEndOfTurn(Objects.Target(name), Mechanic.GainAbilities(keywords + granted)))
        }
        // tmt chunk 04: "Return target creature card and all other cards with the same name as that card from your graveyard to the
        // battlefield tapped."
        Tmt.RETURN_TARGET_AND_SAME_NAME.matchEntire(sentence)?.let { m ->
            val noun = m.groupValues[1] + " in your graveyard"
            val name = tmtNewSlotName(context, Filters.slotName(m.groupValues[1]))
            context.targets += tmtSlot(name, Filters.noun(noun) ?: return null)
            val target = Objects.Target(name)
            val others = Objects.Each(Filters.all(ObjectFilter.Not(ObjectFilter.Is(target)), ObjectFilter.SameNameAs(target), ObjectFilter.InZone(Zone.Graveyard),
                ObjectFilter.OwnedBy(PlayerFilter.You)))
            return listOf(Step.Do(Effect.Move(Objects.Union(listOf(target, others)), Destination(Zone.Battlefield, tapped = m.groupValues[2].isNotEmpty()))))
        }
        // tmt chunk 04: "Put up to one target creature card from that player's graveyard onto the battlefield under your control. It enters
        // tapped and attacking that player." (CR 508.4)
        Tmt.PUT_FROM_THAT_PLAYERS_GRAVEYARD.matchEntire(sentence)?.let { m ->
            val filter = Filters.all(Filters.noun(m.groupValues[1]) ?: return null, ObjectFilter.InZone(Zone.Graveyard),
                ObjectFilter.OwnedBy(PlayerFilter.Is(Players.EventPlayer)))
            val name = tmtNewSlotName(context, Filters.slotName(m.groupValues[1]))
            context.targets += tmtSlot(name, filter, min = 0)
            return listOf(Step.Do(Effect.Move(Objects.Target(name), Destination(Zone.Battlefield, tapped = true, controller = Players.You,
                attacking = arcanum.api.AttackTarget.These(Recipients(players = Players.EventPlayer))))))
        }
        // tmt chunk 04: "Destroy target creature or enchantment. If an enchantment was destroyed this way, you lose 2 life."
        Tmt.DESTROY_IF_TYPE_DESTROYED.matchEntire(sentence)?.let { m ->
            val name = tmtNewSlotName(context, Filters.slotName(m.groupValues[1]))
            context.targets += tmtSlot(name, Filters.noun(m.groupValues[1]) ?: return null)
            val type = Filters.noun(m.groupValues[2]) ?: return null
            val then = effect(tmtSentence(m.groupValues[3]), context) ?: return null
            return listOf(Step.Do(Effect.Destroy(Objects.Target(name), postBind = "destroyed")),
                Step.If(arcanum.api.Condition.Compare(Value.Count(Objects.Where(Objects.Bound("destroyed"), type)), arcanum.api.Comparison.AtLeast, Value.Fixed(1)), then = then))
        }
        // tmt chunk 04: "You gain life equal to its toughness." (the creature that died, as it last existed, CR 603.10a)
        Tmt.GAIN_LIFE_EQUAL_TO_ITS.matchEntire(sentence)?.let { m ->
            val event = context.event as? EventPattern.ZoneChange
            val it = (if (event?.from == Zone.Battlefield) Objects.EventObject(EventRole.Before) else context.it) ?: return null
            val property = if (m.groupValues[1] == "power") arcanum.api.NumericProperty.Power else arcanum.api.NumericProperty.Toughness
            return listOf(Step.Do(Effect.GainLife(Players.You, Value.Of(property, it, arcanum.api.Combine.Single))))
        }
        // tmt chunk 04: "At the beginning of your next upkeep, discard three cards at random." (CR 603.7)
        Tmt.NEXT_UPKEEP_DISCARD_RANDOM.matchEntire(sentence)?.let { m ->
            val n = Numbers.count(m.groupValues[1]) ?: return null
            return listOf(Step.Do(Effect.CreateDelayedTrigger(arcanum.api.Trigger.On(EventPattern.StepBegins(arcanum.api.TurnStep.Upkeep, PlayerFilter.You)),
                Instructions(steps = listOf(Step.Do(Effect.Discard(Players.You, Value.Fixed(n), ObjectFilter.Any, random = true)))))))
        }
        // tmt chunk 04: "It deals 4 damage to any target and 3 damage to you."
        Tmt.DEALS_TO_ANY_AND_TO_YOU.matchEntire(sentence)?.let { m ->
            if (!tmtSelfName(m.groupValues[1]) && m.groupValues[1] != "It" && m.groupValues[1] != "it") return null
            context.anyTarget()
            return listOf(Step.Do(Effect.DealDamage(Recipients(target = "any"), Value.Fixed(m.groupValues[2].toInt()), Objects.Self)),
                Step.Do(Effect.DealDamage(Recipients(players = Players.You), Value.Fixed(m.groupValues[3].toInt()), Objects.Self)))
        }
        // tmt chunk 04: "Until end of turn, you may play a card exiled with Raphael." (one card, CR 607.2a)
        Tmt.UNTIL_EOT_MAY_PLAY_EXILED_WITH.matchEntire(sentence.replaceFirstChar { it.lowercase() })?.takeIf { tmtSelfName(it.groupValues[1]) }?.let {
            return listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.MayPlay(Zone.Exile, PlayKind.Play, holder = PlayerFilter.You, perTurn = 1)),
                Affected.Objects(Objects.Where(Objects.Remembered(EXILED_WITH), ObjectFilter.InZone(Zone.Exile))), arcanum.api.Duration.EndOfTurn)))
        }
        // tmt chunk 05: "Each player creates a Food token."
        Tmt.EACH_PLAYER_CREATES.matchEntire(sentence)?.let { m ->
            val (count, token) = Tokens.spec(m.groupValues[1]) ?: return null
            return listOf(Step.Do(Effect.CreateToken(token, Value.Fixed(count), Players.Each(PlayerFilter.Any))))
        }
        // tmt chunk 05: "Sacrifice a permanent unless you discard a card." (CR 118.12a)
        Tmt.SACRIFICE_UNLESS_DISCARD.matchEntire(sentence)?.let { m ->
            val sacrifice = effect("Sacrifice a ${m.groupValues[1]}.", context) ?: return null
            return listOf(Step.Pay(cost("Discard a card") ?: return null, payer = Players.You, bind = "paid"),
                Step.If(arcanum.api.Condition.Not(arcanum.api.Condition.Did("paid")), then = sacrifice))
        }
        // tmt chunk 07: "Exile up to one target artifact you control and up to one target creature you control. Then return them to the
        // battlefield under their owners' control." (CR 400.7)
        Tmt.EXILE_TWO_THEN_RETURN_THEM.matchEntire(sentence)?.let { m ->
            val a = tmtNewSlotName(context, Filters.slotName(m.groupValues[1]))
            context.targets += tmtSlot(a, Filters.noun(m.groupValues[1]) ?: return null, min = 0)
            val b = tmtNewSlotName(context, Filters.slotName(m.groupValues[2]))
            context.targets += tmtSlot(b, Filters.noun(m.groupValues[2]) ?: return null, min = 0)
            return listOf(Step.Do(Effect.Move(Objects.Union(listOf(Objects.Target(a), Objects.Target(b))), Destination(Zone.Exile), postBind = "exiled")),
                Step.Do(Effect.Move(Objects.Bound("exiled"), Destination(Zone.Battlefield, controller = Players.OwnerOf(Objects.Bound("exiled"))))))
        }
        // tmt chunk 07: "The next noncreature spell you cast this turn has affinity for artifacts." (CR 702.41a)
        Tmt.NEXT_SPELL_HAS.matchEntire(sentence.replaceFirstChar { it.lowercase() })?.let { m ->
            val spells = Filters.all(Filters.noun(m.groupValues[1] + " spell") ?: return null, ObjectFilter.ControlledBy(PlayerFilter.You))
            val keyword = OracleParser.keyword(m.groupValues[2].replaceFirstChar { it.uppercase() }) ?: return null
            return listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.GainAbilities(listOf(keyword))), Affected.NextSpells(spells, 1), arcanum.api.Duration.EndOfTurn)))
        }
        // tmt chunk 07: "Exile target creature you control, then return it to the battlefield under its owner's control.", "Exile up to one
        // target creature you own, then return it to the battlefield under your control tapped and attacking." (CR 400.7, 508.4)
        Tmt.EXILE_THEN_RETURN.matchEntire(sentence)?.let { m ->
            val name = tmtNewSlotName(context, Filters.slotName(m.groupValues[2].removeSuffix(" you own")))
            context.targets += tmtSlot(name, Filters.noun(m.groupValues[2]) ?: return null, min = if (m.groupValues[1].isEmpty()) 1 else 0)
            val controller = if (m.groupValues[3] == "your") Players.You else Players.OwnerOf(Objects.Bound("exiled"))
            val attacking = m.groupValues[4].isNotEmpty()
            return listOf(Step.Do(Effect.Move(Objects.Target(name), Destination(Zone.Exile), postBind = "exiled")),
                Step.Do(Effect.Move(Objects.Bound("exiled"), Destination(Zone.Battlefield, controller = controller, tapped = attacking,
                    attacking = arcanum.api.AttackTarget.Chosen.takeIf { attacking }))))
        }
        // tmt chunk 07: "Each opponent exiles cards from the top of their library until they exile a nonland card." (CR 607.2a)
        Tmt.EXILE_UNTIL_NONLAND.matchEntire(sentence)?.let { m ->
            val filter = Filters.noun(m.groupValues[1] + " card") ?: return null
            return listOf(Step.ForEach(arcanum.api.Each.Players(Players.Each(PlayerFilter.Opponent)), bind = "player", together = true, steps = listOf(
                Step.Do(Effect.RevealUntil(filter, Players.Bound("player"), Value.Fixed(1), reveal = false, into = Zone.Exile, foundBind = "found", restBind = "rest")),
                Step.Do(Effect.Remember(EXILED_WITH, Objects.Union(listOf(Objects.Bound("found"), Objects.Bound("rest"))))))))
        }
        // tmt chunk 07: "You may cast a card exiled with Krang & Shredder without paying its mana cost." (CR 607.2a, 601.2a)
        Tmt.MAY_CAST_EXILED_WITH_FREE.matchEntire(sentence)?.takeIf { tmtSelfName(it.groupValues[1]) }?.let {
            return listOf(Step.Choose(arcanum.api.Choice.Objects(ObjectFilter.Any, Value.Fixed(0), Value.Fixed(1),
                from = Objects.Where(Objects.Remembered(EXILED_WITH), ObjectFilter.InZone(Zone.Exile))), bind = "toCast", chooser = Players.You),
                Step.Do(Effect.Cast(Objects.Bound("toCast"), PlayKind.Cast, withoutPaying = true, caster = Players.You)))
        }
        // tmt chunk 07: "You may put a card you own from outside the game into your hand." (CR 400.11a)
        if (Tmt.FROM_OUTSIDE_THE_GAME.matches(sentence)) {
            return listOf(Step.Choose(arcanum.api.Choice.Objects(ObjectFilter.Any, Value.Fixed(0), Value.Fixed(1),
                from = Objects.Each(Filters.all(ObjectFilter.InZone(Zone.Outside), ObjectFilter.OwnedBy(PlayerFilter.You)))), bind = "chosen", chooser = Players.You),
                Step.Do(Effect.Move(Objects.Bound("chosen"), Destination(Zone.Hand))))
        }
        // tmt chunk 08: "Target player gains 3 life and draws a card."
        Tmt.TARGET_PLAYER_GAINS_AND_DRAWS.matchEntire(sentence)?.let { m ->
            val name = if (context.targets.none { it.name == "player" }) "player" else nextTargetName("player", context.targets.map { it.name })
            context.targets += TargetSlot(name, TargetKind.Players(PlayerFilter.Any), min = Value.Fixed(1), max = Value.Fixed(1))
            return listOf(Step.Do(Effect.GainLife(Players.Target(name), Value.Fixed(m.groupValues[1].toInt()))),
                Step.Do(Effect.Draw(Players.Target(name), Value.Fixed(Numbers.count(m.groupValues[2]) ?: return null))))
        }
        // tmt chunk 08: "Each of your opponents discards a card."
        Tmt.EACH_OF_YOUR_OPPONENTS.matchEntire(sentence)?.let { m -> return effect("Each opponent " + m.groupValues[1], context) }
        // tmt chunk 08: "Create a Mutagen token for each +1/+1 counter on it." (the creature that left, as it last existed, CR 603.10a)
        Tmt.TOKEN_FOR_EACH_COUNTER_ON_IT.matchEntire(sentence)?.let { m ->
            val event = context.event as? EventPattern.ZoneChange
            val it = (if (event?.from == Zone.Battlefield) Objects.EventObject(EventRole.Before) else context.it) ?: return null
            if (m.groupValues[1] !in arcanum.api.PredefinedTokens.names) return null
            return listOf(Step.Do(Effect.CreateToken(arcanum.api.TokenSpec.Predefined(m.groupValues[1]),
                Value.Of(arcanum.api.NumericProperty.Counters(tmtP1P1), it, arcanum.api.Combine.Single), Players.You)))
        }
        // tmt chunk 03: "Draw a card for each card type among spells you've cast this turn." (each spell as it was cast)
        if (Tmt.CARD_TYPES_AMONG_SPELLS_CAST.matches(sentence))
            return listOf(Step.Do(Effect.Draw(Players.You, Value.EventsThisTurn(EventPattern.Cast(ObjectFilter.Any, PlayerFilter.You),
                arcanum.api.Measure.Distinct(arcanum.api.SharedQuality.CardType)))))
        // tmt chunk 03: "You may exchange control of two other target creatures controlled by different players." (CR 701.12a)
        Tmt.EXCHANGE_CONTROL_DIFFERENT_PLAYERS.matchEntire(sentence)?.let { m ->
            val filter = Filters.all(Filters.noun(m.groupValues[1].removeSuffix("s")) ?: return null, ObjectFilter.Not(ObjectFilter.Is(Objects.Self)))
            context.targets += tmtSlot("creature", filter)
            context.targets += tmtSlot("other creature", Filters.all(filter, ObjectFilter.Not(ObjectFilter.ControlledBy(PlayerFilter.Is(
                Players.ControllerOf(Objects.Target("creature"))))))).copy(distinctFrom = listOf("creature"))
            return listOf(Step.May(listOf(Step.Do(Effect.ExchangeControl(Objects.Target("creature"), Objects.Target("other creature")))), player = Players.You))
        }
        // tmt chunk 03: "Each player may shuffle their hand and graveyard into their library, then each player who does draws seven cards."
        Tmt.SHUFFLE_HAND_AND_GRAVEYARD_DRAW.matchEntire(sentence)?.let { m ->
            val n = Numbers.count(m.groupValues[1]) ?: return null
            val player = Players.Bound("player")
            val cards = Objects.Each(Filters.all(ObjectFilter.OwnedBy(PlayerFilter.Is(player)), ObjectFilter.Or(listOf(ObjectFilter.InZone(Zone.Hand), ObjectFilter.InZone(Zone.Graveyard)))))
            return listOf(Step.ForEach(arcanum.api.Each.Players(Players.Each(PlayerFilter.Any)), bind = "player", together = true, steps = listOf(
                Step.Pay(steps = listOf(Step.Do(Effect.Move(cards, Destination(Zone.Library))), Step.Do(Effect.Shuffle(player))), payer = player, bind = "shuffled"),
                Step.If(arcanum.api.Condition.Did("shuffled"), then = listOf(Step.Do(Effect.Draw(player, Value.Fixed(n))))))))
        }
        // tmt chunk 05: "You may pay life equal to its power. If you do, put that many +1/+1 counters on it."
        if (Tmt.PAY_LIFE_EQUAL_TO_POWER_COUNTERS.matches(sentence)) {
            val it = context.it ?: return null
            val power = Value.Of(arcanum.api.NumericProperty.Power, it, arcanum.api.Combine.Single)
            return listOf(Step.Pay(Cost(listOf(CostPart.PayLife(power))), payer = Players.You, bind = "paid"),
                Step.If(arcanum.api.Condition.Did("paid"), then = listOf(Step.Do(Effect.PutCounters(it, tmtP1P1, power)))))
        }
        // tmt chunk 05: "Create a token that's a copy of it, except it isn't legendary and is a Mutant in addition to its other types." (CR 707.9b)
        Tmt.CLONING_COPY_EXCEPT.matchEntire(sentence)?.let { m ->
            val subtype = m.groupValues[2].takeIf { it in RulesWords.subtypes } ?: return null
            val of = if (m.groupValues[1] == "it") (tmtLastBound(context) ?: return null) else {
                return listOf(Step.Choose(arcanum.api.Choice.Objects(ObjectFilter.Any, Value.Fixed(1), Value.Fixed(1),
                    from = Objects.Where(Objects.Remembered(EXILED_WITH), ObjectFilter.InZone(Zone.Exile))), bind = "chosen", chooser = Players.You),
                    tmtCopyExcept(Objects.Bound("chosen"), subtype))
            }
            return listOf(tmtCopyExcept(of, subtype))
        }
        return null
    }

    private fun tmtCopyExcept(of: Objects, subtype: String): Step = Step.Do(Effect.CreateToken(arcanum.api.TokenSpec.CopyOf(of, except = listOf(
        arcanum.api.CopyException.Types(removeSupertypes = listOf(Supertype.Legendary), addSubtypes = listOf(arcanum.api.SubtypeRef.Literal(Subtype(subtype)))))),
        Value.Fixed(1), Players.You))

    private fun tmtLastBound(context: Context): Objects? = context.targets.lastOrNull()?.let { Objects.Target(it.name) }

    /** tmt chunk 04: the intervening "if" of the trigger being read ("if you have fewer than four cards in hand"). */
    private var tmtLastIf: arcanum.api.Condition? = null

    // ---- msh: Marvel Super Heroes wordings (the set's parser tests, sets/msh/MshChunk*Test.kt); regexes in [Msh]

    private val mshSelfOnly get() = Affected.Objects(Objects.Self)
    private fun mshN(word: String): Int? = Numbers.count(word)
    private fun mshSlot(name: String, filter: ObjectFilter, min: Int = 1, max: Int? = 1) =
        TargetSlot(name, TargetKind.Objects(filter), min = Value.Fixed(min), max = max?.let { Value.Fixed(it) })
    private fun mshUntilEndOfTurn(objects: Objects, vararg mechanics: Mechanic) =
        Step.Do(Effect.ApplyMechanics(mechanics.toList(), Affected.Objects(objects), arcanum.api.Duration.EndOfTurn))
    private fun mshKeywords(text: String): List<Ability>? = text.split(LazyRegexes.AND_LIST).map { OracleParser.keyword(it.trim()) ?: return null }
    private fun mshCap(text: String) = text.replaceFirstChar { it.uppercase() }
    private fun mshSentence(text: String) = mshCap(text).let { if (it.endsWith(".")) it else "$it." }
    private fun mshLastTarget(context: Context): Objects? = context.targets.lastOrNull()?.takeIf { it.what is TargetKind.Objects }?.let { Objects.Target(it.name) }
    private fun mshNewSlotName(context: Context, base: String) = if (context.targets.none { it.name == base }) base else nextTargetName(base, context.targets.map { it.name })
    private val mshP1P1 get() = arcanum.api.CounterKind.PowerToughness(1, 1)
    private fun mshPower(of: Objects) = Value.Of(arcanum.api.NumericProperty.Power, of, arcanum.api.Combine.Single)
    private fun mshToughness(of: Objects) = Value.Of(arcanum.api.NumericProperty.Toughness, of, arcanum.api.Combine.Single)
    private fun mshManaValue(of: Objects) = Value.Of(arcanum.api.NumericProperty.ManaValue, of, arcanum.api.Combine.Single)
    private val mshAnyTargetFilter get() = ObjectFilter.Or(listOf(ObjectFilter.Type(CardType.Creature), ObjectFilter.Type(CardType.Planeswalker), ObjectFilter.Type(CardType.Battle)))

    /** msh: the objects a subject names: this object, "it" (this object in its own trigger), a target, "each …". */
    private fun mshObjects(subject: String, context: Context): Objects? {
        val s = subject.removePrefix("Then ").removePrefix("then ")
        if (s == "it" || s == "It") {
            // in this object's own trigger ("When this creature enters, it connives", "Whenever Kang attacks, he connives")
            val event = context.event
            if (event is EventPattern.ZoneChange && event.objects == ObjectFilter.Is(Objects.Self) && event.to == Zone.Battlefield) return Objects.Self
            if (event is EventPattern.Attack && event.attacker == ObjectFilter.Is(Objects.Self)) return Objects.Self
        }
        MSH_UP_TO_ONE_TARGET.matchEntire(s)?.let { m ->
            val noun = m.groupValues[1]
            val slotName = mshNewSlotName(context, Filters.slotName(noun))
            context.targets += mshSlot(slotName, Filters.noun(noun) ?: return null, min = 0)
            return Objects.Target(slotName)
        }
        if (s == "enchanted creature" || s == "Enchanted creature" || s == "equipped creature" || s == "Equipped creature") return Objects.AttachedTo(Objects.Self)
        // CR 701.54e: "your Ring-bearer" (at most one creature)
        if (s == "your Ring-bearer" || s == "Your Ring-bearer") return Objects.Each(MechanicWordings.yourRingBearer)
        return fraObjects(s, context)
    }

    private fun mshConnive(objects: Objects): Step = Step.Do(Effect.Action(arcanum.api.KeywordAction.Connive(objects, count = Value.Fixed(1))))

    /** msh: "The Void, a legendary 5/5 black Horror Villain creature token with flying, indestructible, and "…"" (CR 111.4). */
    private fun mshNamedToken(text: String): arcanum.api.TokenSpec.Defined? {
        val m = Msh.NAMED_LEGENDARY_TOKEN.matchEntire(text) ?: return null
        val name = m.groupValues[1]
        val colors = if (m.groupValues[4] == "colorless") emptyList() else m.groupValues[4].split(" and ").map { Tokens.color(it) ?: return null }
        val (types, subtypes) = typesAndSubtypes(m.groupValues[5]) ?: return null
        val abilities = mshTokenAbilities(m.groupValues[6], setOf(name, "this token", "this creature")) ?: return null
        return arcanum.api.TokenSpec.Defined(arcanum.api.FaceDefinition(name = name, colorIndicator = colors, supertypes = listOf(Supertype.Legendary),
            types = types + CardType.Creature, subtypes = subtypes.map { (it as arcanum.api.SubtypeRef.Literal).subtype },
            power = arcanum.api.PrintedNumber.Fixed(m.groupValues[2].toInt()), toughness = arcanum.api.PrintedNumber.Fixed(m.groupValues[3].toInt()),
            abilities = abilities))
    }

    /** msh: a token's "with …": keywords and quoted abilities ("flying, indestructible, and "…""). */
    private fun mshTokenAbilities(with: String, names: Set<String>): List<Ability>? {
        if (with.isEmpty()) return emptyList()
        val quoted = LazyRegexes.QUOTED.findAll(with).map { it.groupValues[1] }.toList()
        val rest = with.replace(LazyRegexes.AND_QUOTED, "").trim().removeSuffix(",").removeSuffix(" and").trim()
        val keywords = if (rest.isEmpty()) emptyList() else mshKeywords(rest.removeSuffix(","))?.takeIf { it.isNotEmpty() } ?: return null
        val inner = Sentences(names)
        return keywords + quoted.map { q -> inner.multi(mshSentence(q))?.singleOrNull() ?: inner.line(mshSentence(q)) ?: return null }
    }

    /** msh: "a 1/1 red Alien creature token with haste and "This token attacks each combat if able."" (CR 111.4). */
    private fun mshToken(text: String): Pair<Int, arcanum.api.TokenSpec>? {
        Tokens.spec(text)?.let { return it }
        val m = Msh.COUNTED_TOKEN_WITH.matchEntire(text) ?: return null
        val count = Numbers.count(m.groupValues[1]) ?: return null
        val token = Tokens.defined("a " + m.groupValues[2] + " token") ?: return null
        val abilities = mshTokenAbilities(m.groupValues[3], setOf("this token", "this creature")) ?: return null
        return count to token.copy(face = token.face.copy(abilities = abilities))
    }

    /** msh: whole lines read before the other rules. */
    private fun mshLine(line: String): Ability? {
        mshLine2(line)?.let { return it }
        // msh chunk 03: "∞ — [ability]": as long as this permanent is harnessed, it has the ability (CR 702.186b)
        Msh.INFINITY.matchEntire(line)?.let { m ->
            return when (val ability = line(m.groupValues[1])) {
                is Ability.Activated -> ability.copy(label = arcanum.api.AbilityLabel.Infinity)
                is Ability.Triggered -> ability.copy(label = arcanum.api.AbilityLabel.Infinity)
                is Ability.Static -> ability.copy(label = arcanum.api.AbilityLabel.Infinity)
                else -> null
            }
        }
        // msh chunk 05: "Whenever you cast a noncreature spell with one or more blue mana symbols in its mana cost, create that many 1/1
        // blue Merfolk creature tokens." (CR 107.4: hybrid symbols count)
        Msh.CAST_WITH_MANA_SYMBOLS_CREATE_THAT_MANY.matchEntire(line)?.let { m ->
            val color = Tokens.color(m.groupValues[2]) ?: return null
            val kind = Filters.noun(m.groupValues[1] + " spell") ?: return null
            val symbols = MshPhrases.manaSymbols(color, Objects.Tested)
            val spell = Filters.all(kind, ObjectFilter.Where(arcanum.api.Condition.Compare(symbols, arcanum.api.Comparison.AtLeast, Value.Fixed(1))))
            val token = Tokens.defined("a " + m.groupValues[3] + " token") ?: return null
            return Ability.Triggered(arcanum.api.Trigger.On(EventPattern.Cast(spell, PlayerFilter.You)), Instructions(steps = listOf(
                Step.Do(Effect.CreateToken(token, MshPhrases.manaSymbols(color, Objects.EventObject(EventRole.Object)), Players.You)))))
        }
        // msh chunk 06: "Equip worthy {1}" (CR 702.6a; worthy: legendary, not a Villain, red and/or white, CR 700.16)
        Msh.EQUIP_WORTHY.matchEntire(line)?.let { m ->
            return arcanum.api.Keyword.Equip(Cost.mana(ManaCost.parse(m.groupValues[1]) ?: return null), onto = MshPhrases.worthy)
        }
        return null
    }

    /** msh: static abilities, tried first in [static]. */
    private fun mshStatic(line: String): Ability? {
        mshStatic2(line)?.let { return it }
        // msh chunk 01: "Your opponents can't cast spells during your turn."
        if (Msh.OPPONENTS_CANT_CAST_DURING_YOUR_TURN.matches(line))
            return Ability.Static(listOf(Mechanic.CantCast(ObjectFilter.Any)), affects = Affected.Players(Players.Each(PlayerFilter.Opponent)),
                condition = arcanum.api.Condition.YourTurn)
        // msh chunk 04: "As long as an opponent has cast a spell this turn, you may cast spells as though they had flash." (CR 702.8a)
        Msh.AS_LONG_AS_MAY_CAST_AS_FLASH.matchEntire(line)?.let { m ->
            val condition = Conditions.condition(m.groupValues[1], self) ?: return null
            return Ability.Static(listOf(Mechanic.CastAsThoughFlash(ObjectFilter.Any)), affects = Affected.Players(Players.You), condition = condition)
        }
        // msh chunk 02: "If a creature you control would connive, instead you draw a card, then that creature connives." (CR 614.1a)
        Msh.WOULD_CONNIVE_INSTEAD_DRAW.matchEntire(line)?.let { m ->
            val filter = Filters.noun(m.groupValues[1].removeArticle()) ?: return null
            return Ability.Static(listOf(Mechanic.Replacement(EventPattern.Connive(filter), instead = Instructions(steps = listOf(
                Step.Do(Effect.Draw(Players.You, Value.Fixed(1))), mshConnive(Objects.EventObject(EventRole.Object)))))), affects = mshSelfOnly)
        }
        // msh chunk 04: "Stature can't be blocked if her power is 1 or less."
        Msh.CANT_BE_BLOCKED_IF.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val condition = Conditions.condition(m.groupValues[2], self) ?: Conditions.condition(ungendered(m.groupValues[2], self), self) ?: return null
            return Ability.Static(listOf(Mechanic.CantBeBlocked), affects = mshSelfOnly, condition = condition)
        }
        // msh chunk 06: "Enchanted creature gets +2/+2, has first strike and vigilance, and is a legendary Soldier in addition to its other
        // types." (layers 4, 6, 7c)
        Msh.ENCHANTED_GETS_HAS_AND_IS.matchEntire(line)?.let { m ->
            val keywords = mshKeywords(m.groupValues[3]) ?: return null
            val subtype = m.groupValues[5].takeIf { it in RulesWords.subtypes } ?: return null
            return Ability.Static(listOf(
                Mechanic.ModifyPowerToughness(Value.Fixed(m.groupValues[1].toInt()), Value.Fixed(m.groupValues[2].toInt())),
                Mechanic.GainAbilities(keywords),
                Mechanic.SetTypes(addSubtypes = listOf(arcanum.api.SubtypeRef.Literal(Subtype(subtype))),
                    addSupertypes = if (m.groupValues[4].isNotEmpty()) listOf(Supertype.Legendary) else emptyList()),
            ), affects = Affected.Objects(Objects.AttachedTo(Objects.Self)))
        }
        // msh chunk 06: "Enchanted creature loses all abilities and can't become untapped."
        if (Msh.ENCHANTED_LOSES_ALL_CANT_UNTAP.matches(line))
            return Ability.Static(listOf(Mechanic.LoseAbilities(), Mechanic.CantBecomeUntapped), affects = Affected.Objects(Objects.AttachedTo(Objects.Self)))
        // msh chunk 05: "Each creature you control that you've put one or more +1/+1 counters on this turn has hexproof."
        Msh.EACH_YOUVE_PUT_COUNTERS_ON_HAS.matchEntire(line)?.let { m ->
            val filter = Filters.noun(m.groupValues[1]) ?: return null
            val kind = Counters.kind(m.groupValues[2]) ?: return null
            val keywords = mshKeywords(m.groupValues[3]) ?: return null
            val counted = ObjectFilter.ThisTurn(EventPattern.CountersPut(ObjectFilter.Any, kind, causedBy = ObjectFilter.ControlledBy(PlayerFilter.You)), role = EventRole.Object)
            return Ability.Static(listOf(Mechanic.GainAbilities(keywords)), affects = Affected.Objects(Objects.Each(Filters.all(filter, counted))))
        }
        // msh chunk 06: "Double all damage equipped creature would deal." (CR 614.1a)
        if (Msh.DOUBLE_DAMAGE_EQUIPPED_WOULD_DEAL.matches(line))
            return Ability.Static(listOf(Mechanic.Replacement(EventPattern.Damage(ObjectFilter.Is(Objects.AttachedTo(Objects.Self)), RecipientFilter()),
                modify = listOf(Modification.MultiplyAmount(2)))), affects = mshSelfOnly)
        // msh chunk 07: "Instant and sorcery spells you cast with mana value 4 or greater cost {X} less to cast, where X is The Scarlet
        // Witch's power." (CR 601.2f)
        Msh.SPELLS_WITH_MANA_VALUE_COST_X_LESS_POWER.matchEntire(line)?.takeIf { isSelf(it.groupValues[3]) }?.let { m ->
            val spells = Filters.noun(m.groupValues[1].replaceFirstChar { it.lowercase() }) ?: return null
            return Ability.Static(listOf(Mechanic.CostChange(Filters.all(spells, ObjectFilter.ManaValue(arcanum.api.Comparison.AtLeast, Value.Fixed(m.groupValues[2].toInt()))),
                arcanum.api.CostChange.Less(ManaCost.parse("{1}")!!, mshPower(Objects.Self)))), affects = mshSelfOnly)
        }
        // msh chunk 01: "Each power-up ability of permanents you control can be activated an additional time." (CR 702.193a)
        Msh.LABEL_ADDITIONAL_TIME.matchEntire(line)?.let { m ->
            val objects = Filters.noun(m.groupValues[1]) ?: return null
            return Ability.Static(listOf(Mechanic.LabelAdditionalUses(arcanum.api.AbilityLabel.PowerUp, 1)), affects = Affected.Objects(Objects.Each(objects)))
        }
        // msh chunk 01: "Power-up abilities of other creatures you control cost {3} less to activate." (CR 601.2f, 602.2b)
        Msh.POWER_UP_ABILITIES_COST_LESS.matchEntire(line)?.let { m ->
            val sources = Filters.noun(m.groupValues[1]) ?: return null
            return Ability.Static(listOf(Mechanic.CostChange(ObjectFilter.AbilityOf(source = sources, label = arcanum.api.AbilityLabel.PowerUp),
                arcanum.api.CostChange.Less(ManaCost.parse(m.groupValues[2]) ?: return null, Value.Fixed(1)))), affects = mshSelfOnly)
        }
        // msh chunk 05: "If you would put one or more counters on a permanent you control, put that many plus one of each of those kinds of
        // counters on that permanent instead." (CR 614.1a)
        Msh.COUNTERS_PLUS_ONE.matchEntire(line)?.let { m ->
            val filter = Filters.noun(m.groupValues[1].removeArticle()) ?: return null
            return Ability.Static(listOf(Mechanic.Replacement(EventPattern.CountersPut(filter, null, causedBy = ObjectFilter.ControlledBy(PlayerFilter.You)),
                modify = listOf(Modification.AddAmount(Value.Fixed(1))))), affects = mshSelfOnly)
        }
        // msh chunk 08: "You may activate abilities of creatures you control as though those creatures had haste." (CR 302.6)
        Msh.ACTIVATE_AS_THOUGH_HASTE.matchEntire(line)?.let { m ->
            val objects = Filters.noun(m.groupValues[1]) ?: return null
            return Ability.Static(listOf(Mechanic.AbilitiesIgnoreSummoningSickness), affects = Affected.Objects(Objects.Each(objects)))
        }
        // msh chunk 08: "As long as there are two or more creature cards in your graveyard, this creature gets +2/+2 and is all creature
        // types." (layers 4 and 7c)
        Msh.AS_LONG_AS_GETS_AND_ALL_TYPES.matchEntire(line)?.takeIf { isSelf(it.groupValues[2]) }?.let { m ->
            val condition = Conditions.condition(m.groupValues[1], self) ?: return null
            return Ability.Static(listOf(Mechanic.ModifyPowerToughness(Value.Fixed(m.groupValues[3].toInt()), Value.Fixed(m.groupValues[4].toInt())),
                Mechanic.AllCreatureTypes), affects = mshSelfOnly, condition = condition)
        }
        // msh chunk 09: "Prevent all damage that would be dealt to Black Panther." (CR 615.1)
        Msh.PREVENT_ALL_DAMAGE_TO_SELF.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            return Ability.Static(listOf(Mechanic.Prevention(EventPattern.Damage(ObjectFilter.Any, RecipientFilter(objects = ObjectFilter.Is(Objects.Self))))), affects = mshSelfOnly)
        }
        // msh chunk 09: "Creatures with flying can't attack you or block creatures you control." (CR 508.1c, 509.1b)
        Msh.CANT_ATTACK_YOU_OR_BLOCK.matchEntire(line)?.let { m ->
            val objects = Filters.noun(m.groupValues[1]) ?: Filters.noun(m.groupValues[1].replaceFirstChar { it.lowercase() }) ?: return null
            val attackers = Filters.noun(m.groupValues[2]) ?: return null
            return Ability.Static(listOf(Mechanic.CantAttack(target = arcanum.api.Recipients(players = Players.You)), Mechanic.CantBlock(attackers)),
                affects = Affected.Objects(Objects.Each(objects)))
        }
        // msh chunk 10: "Your maximum hand size is ten." (CR 402.2)
        Msh.MAXIMUM_HAND_SIZE_IS.matchEntire(line)?.let { m ->
            return Ability.Static(listOf(Mechanic.MaximumHandSize(Value.Fixed(mshN(m.groupValues[1]) ?: return null))), affects = Affected.Players(Players.You))
        }
        // msh chunk 09: "If damage would be dealt to Wolverine, instead that damage is dealt, but all other damage already dealt to him is
        // healed." (CR 614.1a, 701.69a)
        Msh.DAMAGE_DEALT_OTHER_HEALED.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            return Ability.Static(listOf(Mechanic.Replacement(EventPattern.Damage(ObjectFilter.Any, RecipientFilter(objects = ObjectFilter.Is(Objects.Self))),
                modify = listOf(Modification.HealsOtherDamage))), affects = mshSelfOnly)
        }
        // msh chunk 07: "If a source you control would deal noncombat damage to an opponent or a permanent an opponent controls, instead it
        // deals that much damage plus X, where X is Hawkeye's power." (CR 614.1a)
        Msh.NONCOMBAT_DAMAGE_PLUS_POWER.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            return Ability.Static(listOf(Mechanic.Replacement(EventPattern.Damage(ObjectFilter.ControlledBy(PlayerFilter.You),
                RecipientFilter(objects = Filters.all(ObjectFilter.Category(arcanum.api.ObjectCategory.Permanent), ObjectFilter.ControlledBy(PlayerFilter.Opponent)),
                    players = PlayerFilter.Opponent), combat = false),
                modify = listOf(Modification.AddAmount(mshPower(Objects.Self))))), affects = mshSelfOnly)
        }
        // msh chunk 07: "If Quicksilver, Brash Blur is in your opening hand, you may begin the game with him on the battlefield." (CR 103.6a)
        Msh.OPENING_HAND_BEGIN.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            return Ability.Static(listOf(Mechanic.MayBeginOnBattlefield), affects = mshSelfOnly, functionsIn = listOf(Zone.Hand))
        }
        // msh chunk 10: "Winter Soldier gets +2/+0 for each Equipment attached to him."
        Msh.GETS_FOR_EACH_ATTACHED.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val count = Value.Count(Objects.Each(Filters.all(Filters.noun(m.groupValues[4]) ?: return null, ObjectFilter.Attached(to = Objects.Self))))
            fun times(n: Int) = if (n == 0) Value.Fixed(0) else if (n == 1) count else Value.Times(count, n)
            return Ability.Static(listOf(Mechanic.ModifyPowerToughness(times(m.groupValues[2].toInt()), times(m.groupValues[3].toInt()))), affects = mshSelfOnly)
        }
        return null
    }

    /** msh: lines that are two abilities. */
    private fun mshMulti(line: String): List<Ability>? {
        // msh chunk 04: "As long as Captain America has a shield counter on him, you and other Heroes you control have hexproof."
        // (a player with hexproof can't be the target of spells or abilities their opponents control, CR 702.11c)
        Msh.AS_LONG_AS_YOU_AND_HAVE.matchEntire(line)?.let { m ->
            val condition = Conditions.condition(m.groupValues[1], self) ?: Conditions.condition(ungendered(m.groupValues[1], self), self) ?: return null
            val others = Filters.noun(m.groupValues[2]) ?: return null
            return listOf(
                Ability.Static(listOf(Mechanic.CantBeTargeted(by = ObjectFilter.ControlledBy(PlayerFilter.Opponent))), affects = Affected.Players(Players.You),
                    condition = condition),
                Ability.Static(listOf(Mechanic.GainAbilities(listOf(arcanum.api.Keyword.Hexproof))), affects = Affected.Objects(Objects.Each(others)),
                    condition = condition))
        }
        return null
    }

    /** msh: trigger events, tried first in [trigger]. */
    private fun mshTrigger(events: String): arcanum.api.Trigger.On? {
        // msh chunk 01: "Agent Maria Hill becomes tapped to pay a teamwork cost" (CR 702.194a)
        Msh.BECOMES_TAPPED_TO_PAY_TEAMWORK.matchEntire(events)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            return arcanum.api.Trigger.On(EventPattern.Tap(ObjectFilter.Is(Objects.Self), forCost = arcanum.api.Keyword.Teamwork.Kind))
        }
        // msh chunk 05: "you cast a spell that targets a creature you control", "… an instant or sorcery spell that targets an artifact or
        // land", "… a spell that targets one or more creatures"
        Msh.YOU_CAST_SPELL_THAT_TARGETS.matchEntire(events)?.let { m ->
            val kind = m.groupValues[1].trim().takeIf { it.isNotEmpty() }?.let { Filters.noun("$it spell") ?: return null }
            val noun = m.groupValues[2]
            val targeted = Filters.noun(noun) ?: Filters.noun(noun.removeSuffix("s")) ?: return null
            val spell = ObjectFilter.Targets(objects = Objects.Each(targeted))
            return arcanum.api.Trigger.On(EventPattern.Cast(if (kind == null) spell else Filters.all(kind, spell), PlayerFilter.You))
        }
        // inr chunk 09: "a player casts an instant or sorcery spell that targets only this creature" (CR 115.7)
        Inr.PLAYER_CASTS_SPELL_THAT_TARGETS_ONLY.matchEntire(events)?.takeIf { isSelf(it.groupValues[2]) }?.let { m ->
            return arcanum.api.Trigger.On(EventPattern.Cast(Filters.all(Filters.noun(m.groupValues[1] + " spell") ?: return null,
                ObjectFilter.SingleTarget(ObjectFilter.Is(Objects.Self))), PlayerFilter.Any))
        }
        // msh chunk 05: "a player casts a spell that targets Speedball"
        Msh.PLAYER_CASTS_SPELL_THAT_TARGETS.matchEntire(events)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            return arcanum.api.Trigger.On(EventPattern.Cast(ObjectFilter.Targets(objects = Objects.Self), PlayerFilter.Any))
        }
        // msh chunk 03: "the fourth plan counter is put on this enchantment" (the event that puts it, CR 122.6)
        Msh.NTH_COUNTER_PUT_ON.matchEntire(events)?.takeIf { isSelf(it.groupValues[3]) }?.let { m ->
            val nth = Numbers.ordinal(m.groupValues[1]) ?: return null
            return arcanum.api.Trigger.On(EventPattern.CountersPut(ObjectFilter.Is(Objects.Self), Counters.kind(m.groupValues[2]) ?: return null, reaching = nth))
        }
        // msh chunk 05: "you put one or more +1/+1 counters on one or more other Heroes you control" (once for the batch, by your spells
        // and abilities)
        Msh.YOU_PUT_ONE_OR_MORE_ON_ONE_OR_MORE.matchEntire(events)?.let { m ->
            val kind = Counters.kind(m.groupValues[1]) ?: return null
            val filter = Filters.noun(m.groupValues[2]) ?: return null
            return arcanum.api.Trigger.On(EventPattern.CountersPut(filter, kind, causedBy = ObjectFilter.ControlledBy(PlayerFilter.You)), oneOrMore = true)
        }
        // msh chunk 05: "you put a +1/+1 counter on another creature" (one event per counter put, CR 122.6)
        Msh.YOU_PUT_A_COUNTER_ON.matchEntire(events)?.let { m ->
            val kind = Counters.kind(m.groupValues[1]) ?: return null
            val filter = Filters.noun(m.groupValues[2].removeArticle()) ?: return null
            return arcanum.api.Trigger.On(EventPattern.CountersPut(filter, kind, causedBy = ObjectFilter.ControlledBy(PlayerFilter.You)))
        }
        // msh chunk 05: "another nonland permanent you control is returned to its owner's hand"
        Msh.IS_RETURNED_TO_HAND.matchEntire(events)?.let { m ->
            val filter = Filters.noun(m.groupValues[1].removeArticle()) ?: return null
            return arcanum.api.Trigger.On(EventPattern.ZoneChange(filter, from = Zone.Battlefield, to = Zone.Hand))
        }
        // msh chunk 05: "a player or permanent becomes the target of an ability you control" (CR 115.1)
        Msh.PLAYER_OR_PERMANENT_BECOMES_TARGET_OF_ABILITY.matchEntire(events)?.let {
            return arcanum.api.Trigger.On(EventPattern.BecomesTarget(ObjectFilter.Category(arcanum.api.ObjectCategory.Permanent),
                by = Filters.all(ObjectFilter.Category(arcanum.api.ObjectCategory.StackAbility), ObjectFilter.ControlledBy(PlayerFilter.You)), players = PlayerFilter.Any))
        }
        // msh chunk 05: "one or more creatures you control become tapped" (once for the batch)
        Msh.ONE_OR_MORE_BECOME_TAPPED.matchEntire(events)?.let { m ->
            return arcanum.api.Trigger.On(EventPattern.Tap(Filters.noun(m.groupValues[1]) ?: return null), oneOrMore = true)
        }
        // msh chunk 05: "a creature you control becomes tapped", "Hawkeye becomes tapped"
        Msh.BECOMES_TAPPED.matchEntire(events)?.let { m ->
            val filter = if (isSelf(m.groupValues[1])) ObjectFilter.Is(Objects.Self) else Filters.noun(m.groupValues[1].removeArticle()) ?: return null
            return arcanum.api.Trigger.On(EventPattern.Tap(filter))
        }
        // msh chunk 02: "you cast a black spell from your hand"
        Msh.YOU_CAST_FROM_YOUR_HAND.matchEntire(events)?.let { m ->
            return arcanum.api.Trigger.On(EventPattern.Cast(Filters.noun(m.groupValues[1] + " spell") ?: return null, PlayerFilter.You, from = Zone.Hand))
        }
        // msh chunk 06: "enchanted creature attacks or blocks"
        if (events == "enchanted creature attacks or blocks") {
            val enchanted = ObjectFilter.Is(Objects.AttachedTo(Objects.Self))
            return arcanum.api.Trigger.On(listOf(EventPattern.Attack(enchanted), EventPattern.Block(enchanted, attacker = ObjectFilter.Any)))
        }
        // msh chunk 09: "a player draws their second card each turn" (that player's second draw this turn)
        Msh.PLAYER_DRAWS_NTH.matchEntire(events)?.let { m ->
            return arcanum.api.Trigger.On(listOf(EventPattern.Draw(PlayerFilter.Any)), nthThisTurn = Numbers.ordinal(m.groupValues[1]) ?: return null)
        }
        // msh chunk 08: "one or more Heroes you control deal damage to a player" (one trigger per player dealt damage)
        Msh.ONE_OR_MORE_DEAL_DAMAGE_TO_A_PLAYER.matchEntire(events)?.let { m ->
            return arcanum.api.Trigger.On(listOf(EventPattern.Damage(Filters.noun(m.groupValues[1]) ?: return null, RecipientFilter(players = PlayerFilter.Any))),
                oneOrMore = true, batchPerPlayer = true)
        }
        // msh chunk 06: "the beginning of the upkeep of enchanted creature's controller"
        if (events == "the beginning of the upkeep of enchanted creature's controller")
            return arcanum.api.Trigger.On(EventPattern.StepBegins(arcanum.api.TurnStep.Upkeep, PlayerFilter.Is(Players.ControllerOf(Objects.AttachedTo(Objects.Self)))))
        return null
    }

    /** msh: sentences that change the steps before them, tried first in [modify]. */
    private fun mshModify(sentence: String, steps: List<Step>, context: Context): List<Step>? {
        mshModify2(sentence, steps, context)?.let { return it }
        val teamwork = MshPhrases.teamwork
        // msh chunk 01: "If this spell was cast using teamwork, instead [effect]." replaces the sentence before; each version's targets
        // are chosen only when it is the one that happens (CR 702.194c)
        Msh.TEAMWORK_INSTEAD.matchEntire(sentence)?.let { m ->
            val (targetsFrom, stepsFrom) = context.previous ?: return null
            val before = context.targets.size
            context.altNames = "teamwork"
            val then = try {
                effect(mshSentence(m.groupValues[1]), context) ?: m.groupValues[1].split(" and ").takeIf { it.size == 2 }?.let { parts ->
                    val first = effect(mshSentence(parts[0]), context) ?: return@let null
                    first + (effect(mshSentence(parts[1]), context) ?: return@let null)
                }
            } finally { context.altNames = null } ?: return null
            for (i in targetsFrom until before) context.targets[i] = context.targets[i].copy(onlyIf = arcanum.api.Condition.Not(teamwork))
            for (i in before until context.targets.size) context.targets[i] = context.targets[i].copy(onlyIf = teamwork)
            return steps.take(stepsFrom) + Step.If(teamwork, then = then, otherwise = steps.drop(stepsFrom))
        }
        // msh chunk 01: "If this spell was cast using teamwork, it deals 4 damage to that creature instead."
        Msh.TEAMWORK_IT_DEALS_INSTEAD.matchEntire(sentence)?.let { m ->
            val damage = (steps.lastOrNull() as? Step.Do)?.effect as? Effect.DealDamage ?: return null
            return steps.dropLast(1) + Step.If(teamwork, then = listOf(Step.Do(damage.copy(amount = Value.Fixed(m.groupValues[1].toInt())))),
                otherwise = listOf(steps.last()))
        }
        // msh chunk 01: "If this spell was cast using teamwork, it also deals 2 damage to that creature's controller." (as it last
        // existed if it has left, CR 608.2h)
        Msh.TEAMWORK_ALSO_DEALS_TO_CONTROLLER.matchEntire(sentence)?.let { m ->
            val target = mshLastTarget(context) ?: return null
            return steps + Step.If(teamwork, then = listOf(Step.Do(Effect.DealDamage(arcanum.api.Recipients(players = Players.ControllerOf(target)),
                Value.Fixed(m.groupValues[1].toInt()), Objects.Self))))
        }
        // msh chunk 01: "If this spell was cast using teamwork, that creature also gains trample until end of turn."
        Msh.TEAMWORK_ALSO_GAINS.matchEntire(sentence)?.let { m ->
            val target = mshLastTarget(context) ?: return null
            val keywords = mshKeywords(m.groupValues[1]) ?: return null
            return steps + Step.If(teamwork, then = listOf(mshUntilEndOfTurn(target, Mechanic.GainAbilities(keywords))))
        }
        // msh chunk 08: "If that creature is another Hero, put two +1/+1 counters on it instead." after putting one on a target
        Msh.IF_THAT_CREATURE_IS_COUNTERS_INSTEAD.matchEntire(sentence)?.let { m ->
            val put = (steps.lastOrNull() as? Step.Do)?.effect as? Effect.PutCounters ?: return null
            val target = mshLastTarget(context) ?: return null
            val kind = Filters.noun(m.groupValues[1]) ?: return null
            val amount = mshN(m.groupValues[2]) ?: return null
            return steps.dropLast(1) + Step.If(arcanum.api.Condition.ObjectMatches(target, kind),
                then = listOf(Step.Do(put.copy(amount = Value.Fixed(amount)))), otherwise = listOf(steps.last()))
        }
        // msh chunk 05: "Attach it to U.S.Agent." after creating a token
        Msh.ATTACH_IT_TO.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            val index = steps.indexOfLast { ((it as? Step.Do)?.effect as? Effect.CreateToken) != null }.takeIf { it >= 0 } ?: return null
            val create = (steps[index] as Step.Do).effect as Effect.CreateToken
            return steps.toMutableList().also { it[index] = Step.Do(create.copy(bind = "token")) } +
                Step.Do(Effect.Attach(Objects.Bound("token"), arcanum.api.Recipients(objects = Objects.Self)))
        }
        // msh chunk 04: "If it's attacking, untap it and there is an additional combat phase after this phase." (CR 500.8)
        if (Msh.IF_ATTACKING_UNTAP_EXTRA_COMBAT.matches(sentence))
            return steps + Step.If(arcanum.api.Condition.ObjectMatches(Objects.Self, ObjectFilter.HasStatus(arcanum.api.Status.Attacking)),
                then = listOf(Step.Do(Effect.Untap(Objects.Self)), Step.Do(Effect.ExtraCombat())))
        return null
    }

    /** msh: wordings of several sentences, read as a whole first. */
    private fun mshWhole(text: String, context: Context): List<Step>? {
        mshWhole2(text, context)?.let { return it }
        mshWhole3(text, context)?.let { return it }
        val teamwork = MshPhrases.teamwork
        // msh chunk 01: "Counter target spell unless its controller pays {2}. Counter that spell unless its controller pays {4} instead if
        // this spell was cast using teamwork." (CR 118.12a)
        Msh.COUNTER_UNLESS_PAYS_INSTEAD_IF_TEAMWORK.matchEntire(text)?.let { m ->
            context.targets += mshSlot("spell", ObjectFilter.Category(arcanum.api.ObjectCategory.Spell))
            val spell = Objects.Target("spell")
            fun unless(cost: String): List<Step>? = listOf(
                Step.Pay(Cost.mana(ManaCost.parse(cost) ?: return null), payer = Players.ControllerOf(spell), bind = "paid"),
                Step.If(arcanum.api.Condition.Not(arcanum.api.Condition.Did("paid")), then = listOf(Step.Do(Effect.Counter(spell)))))
            return listOf(Step.If(teamwork, then = unless(m.groupValues[2]) ?: return null, otherwise = unless(m.groupValues[1]) ?: return null))
        }
        // msh chunk 01: "Choose target creature card in your graveyard with mana value 4 or less. If this spell was cast using teamwork,
        // instead choose target creature card in your graveyard. Return the chosen card to the battlefield." (CR 702.194c)
        Msh.CHOOSE_TARGET_TEAMWORK_INSTEAD_RETURN.matchEntire(text)?.let { m ->
            val first = Filters.noun(m.groupValues[1]) ?: return null
            val second = Filters.noun(m.groupValues[2]) ?: return null
            context.targets += mshSlot("card", first).copy(onlyIf = arcanum.api.Condition.Not(teamwork))
            context.targets += mshSlot("teamwork card", second).copy(onlyIf = teamwork)
            return listOf(Step.Do(Effect.Move(Objects.Union(listOf(Objects.Target("card"), Objects.Target("teamwork card"))), Destination(Zone.Battlefield))))
        }
        // msh chunk 01: "Reveal the top eight cards of your library. You may put a creature card from among them onto the battlefield. If
        // this spell was cast using teamwork, put any number of creature cards from among them onto the battlefield instead. Put the rest
        // into your graveyard."
        Msh.REVEAL_PUT_FROM_AMONG_TEAMWORK.matchEntire(text)?.let { m ->
            val n = mshN(m.groupValues[1]) ?: return null
            val one = Filters.noun(m.groupValues[2]) ?: return null
            val many = Filters.noun(m.groupValues[3]) ?: Filters.noun(m.groupValues[3].replace("cards", "card")) ?: return null
            val revealed = Objects.Bound("revealed")
            fun put(filter: ObjectFilter, max: Value?) = listOf(
                Step.Choose(arcanum.api.Choice.Objects(filter, Value.Fixed(0), max, from = revealed), bind = "chosen", chooser = Players.You),
                Step.Do(Effect.Move(Objects.Bound("chosen"), Destination(Zone.Battlefield))))
            return listOf(
                Step.Do(Effect.Reveal(Objects.LibraryCards(Players.You, Value.Fixed(n), fromTop = true), bind = "revealed")),
                Step.If(teamwork, then = put(many, null), otherwise = put(one, Value.Fixed(1))),
                Step.Do(Effect.Move(Objects.Except(revealed, Objects.Bound("chosen")), Destination(Zone.Graveyard))))
        }
        // msh chunk 08: "Choose target permanent card in your graveyard that was put there from anywhere this turn. Return it to your hand."
        Msh.CHOOSE_TARGET_RETURN_TO_HAND.matchEntire(text)?.let { m ->
            val target = context.target(Filters.slotName(m.groupValues[1]), Filters.noun(m.groupValues[1]) ?: return null)
            return listOf(Step.Do(Effect.Move(target, Destination(Zone.Hand))))
        }
        // msh chunk 01: "You may put a Hero creature card with mana value 3 or less from your hand onto the battlefield. If you don't, draw a
        // card."
        Msh.MAY_PUT_FROM_HAND_IF_YOU_DONT.matchEntire(text)?.let { m ->
            val filter = Filters.all(Filters.noun(m.groupValues[1]) ?: return null, ObjectFilter.InZone(Zone.Hand), ObjectFilter.OwnedBy(PlayerFilter.You))
            val otherwise = effect(mshSentence(m.groupValues[2]), context) ?: return null
            return listOf(
                Step.Choose(arcanum.api.Choice.Objects(filter, Value.Fixed(0), Value.Fixed(1)), bind = "chosen", chooser = Players.You),
                Step.Do(Effect.Move(Objects.Bound("chosen"), Destination(Zone.Battlefield))),
                Step.If(arcanum.api.Condition.Not(arcanum.api.Condition.NonEmpty("chosen")), then = otherwise))
        }
        // msh chunk 05: "Copy target activated or triggered ability you control from a creature source. You may choose new targets for the
        // copy." (CR 707.10)
        Msh.COPY_TARGET_ABILITY.matchEntire(text)?.let { m ->
            val source = Filters.noun(m.groupValues[1]) ?: return null
            context.targets += mshSlot("ability", Filters.all(ObjectFilter.Or(listOf(
                ObjectFilter.AbilityOf(kind = arcanum.api.AbilityKind.Activated, source = source),
                ObjectFilter.AbilityOf(kind = arcanum.api.AbilityKind.Triggered, source = source))), ObjectFilter.ControlledBy(PlayerFilter.You)))
            return listOf(Step.Do(Effect.CopySpell(Objects.Target("ability"), Players.You, newTargets = true)))
        }
        // msh chunk 02: "The owner of target creature an opponent controls puts it into their library second from the top or on the bottom.
        // Then up to one target creature you control connives."
        Msh.OWNER_PUTS_SECOND_OR_BOTTOM.matchEntire(text)?.let { m ->
            val target = context.target(Filters.slotName(m.groupValues[1]), Filters.noun(m.groupValues[1]) ?: return null)
            val then = effect(mshSentence(m.groupValues[2]), context) ?: return null
            return listOf(
                Step.Choose(arcanum.api.Choice.Option(listOf("second from the top", "on the bottom")), bind = "position", chooser = Players.OwnerOf(target)),
                Step.If(arcanum.api.Condition.Chose("position", "second from the top"),
                    then = listOf(Step.Do(Effect.Move(target, Destination(Zone.Library, libraryPosition = 1)))),
                    otherwise = listOf(Step.Do(Effect.Move(target, Destination(Zone.Library, libraryPosition = -1)))))) + then
        }
        // msh chunk 07: "Exile all the cards from your hand, then draw that many cards. Until the end of your next turn, you may play cards
        // exiled this way."
        if (Msh.EXILE_HAND_DRAW_PLAY.matches(text)) {
            val exiled = Objects.Bound("exiled")
            return listOf(
                Step.Do(Effect.Move(Objects.Each(Filters.all(ObjectFilter.InZone(Zone.Hand), ObjectFilter.OwnedBy(PlayerFilter.You))), Destination(Zone.Exile), postBind = "exiled")),
                Step.Do(Effect.Draw(Players.You, Value.Count(exiled))),
                Step.Do(Effect.ApplyMechanics(listOf(Mechanic.MayPlay(Zone.Exile, PlayKind.Play, holder = PlayerFilter.You)), Affected.Objects(exiled),
                    arcanum.api.Duration.UntilEndOfYourNextTurn)))
        }
        // msh chunk 07: "When you next cast an instant or sorcery spell with mana value less than or equal to Loki's power this turn, copy
        // that spell. You may choose new targets for the copy." (a delayed trigger, CR 603.7)
        Msh.WHEN_YOU_NEXT_CAST_COPY.matchEntire(text)?.takeIf { isSelf(it.groupValues[2]) }?.let { m ->
            val spells = Filters.all(Filters.noun(m.groupValues[1] + " spell") ?: return null,
                ObjectFilter.ManaValue(arcanum.api.Comparison.AtMost, mshPower(Objects.Self)))
            return listOf(Step.Do(Effect.CreateDelayedTrigger(arcanum.api.Trigger.On(EventPattern.Cast(spells, PlayerFilter.You)),
                Instructions(steps = listOf(Step.Do(Effect.CopySpell(Objects.EventObject(EventRole.Object), Players.You, newTargets = true)))),
                duration = arcanum.api.Duration.EndOfTurn)))
        }
        // msh chunk 07: "When this Aura enters, …" is a line; "Exile target …, then return …" below
        // msh chunk 06: "Exile up to one target creature other than enchanted creature until this Aura leaves the battlefield. Enchanted
        // creature becomes a copy of that creature until this Aura leaves the battlefield." (CR 610.3, layer 1)
        Msh.EXILE_UNTIL_LEAVES_ENCHANTED_BECOMES_COPY.matchEntire(text)?.takeIf { isSelf(it.groupValues[2]) && isSelf(it.groupValues[3]) }?.let { m ->
            val noun = m.groupValues[1]
            val filter = Filters.all(Filters.noun(noun) ?: return null, ObjectFilter.Not(ObjectFilter.Is(Objects.AttachedTo(Objects.Self))))
            context.targets += mshSlot("creature", filter, min = 0)
            return listOf(
                Step.Do(Effect.Move(Objects.Target("creature"), Destination(Zone.Exile), untilLeaves = Objects.Self, postBind = "exiled")),
                Step.Do(Effect.ApplyMechanics(listOf(Mechanic.CopyOf(Objects.Bound("exiled"))), Affected.Objects(Objects.AttachedTo(Objects.Self)),
                    arcanum.api.Duration.UntilLeaves(Objects.Self))))
        }
        return null
    }

    /** msh: effect sentences, tried first in [effectRules]. */
    private fun mshEffect(sentence: String, context: Context): List<Step>? {
        mshEffect2(sentence, context)?.let { return it }
        mshEffect3(sentence, context)?.let { return it }
        // msh chunk 01: "Put a +1/+1 counter and an indestructible counter on Captain Marvel."
        Msh.PUT_COUNTER_AND_COUNTER_ON.matchEntire(sentence)?.let { m ->
            val objects = mshObjects(m.groupValues[3], context) ?: return null
            return listOf(Step.Do(Effect.PutCounters(objects, Counters.kind(m.groupValues[1]) ?: return null, Value.Fixed(1))),
                Step.Do(Effect.PutCounters(objects, Counters.kind(m.groupValues[2]) ?: return null, Value.Fixed(1))))
        }
        // msh chunk 02: "it connives", "Target creature you control connives", "Then up to one target creature you control connives"
        // (CR 701.50a)
        Msh.CONNIVES.matchEntire(sentence)?.let { m -> mshObjects(m.groupValues[1], context)?.let { return listOf(mshConnive(it)) } }
        // msh chunk 02: "you may have it connive"
        Msh.MAY_HAVE_IT_CONNIVE.matchEntire(sentence)?.let {
            val objects = context.it ?: context.that ?: return null
            return listOf(Step.May(listOf(mshConnive(objects)), player = Players.You))
        }
        // msh chunk 05: "you may have The Sensational She-Hulk deal that much damage to any target"
        Msh.MAY_HAVE_DEAL_THAT_MUCH.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            context.anyTarget()
            return listOf(Step.May(listOf(Step.Do(Effect.DealDamage(arcanum.api.Recipients(target = "any"), Value.EventAmount, Objects.Self))), player = Players.You))
        }
        // msh chunk 03: "Harness The Mind Stone." (CR 701.64a)
        Msh.HARNESS.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            return listOf(Step.Do(Effect.Mark(Objects.Self, arcanum.api.ObjectMark.Harnessed)))
        }
        // msh chunk 03: "exile up to one other target nonland permanent you control, then return that card to the battlefield under its
        // owner's control" (the card in exile is a new object, CR 400.7)
        Msh.EXILE_THEN_RETURN.matchEntire(sentence)?.let { m ->
            val noun = m.groupValues[3]
            var filter = Filters.noun(noun) ?: return null
            if (m.groupValues[2].isNotEmpty()) filter = Filters.all(ObjectFilter.Not(ObjectFilter.Is(Objects.Self)), filter)
            val name = mshNewSlotName(context, Filters.slotName(noun))
            context.targets += mshSlot(name, filter, min = if (m.groupValues[1].isEmpty()) 1 else 0)
            return listOf(Step.Do(Effect.Move(Objects.Target(name), Destination(Zone.Exile), postBind = "exiled")),
                Step.Do(Effect.Move(Objects.Bound("exiled"), Destination(Zone.Battlefield, tapped = m.groupValues[4].isNotEmpty(),
                    controller = Players.OwnerOf(Objects.Bound("exiled"))))))
        }
        // msh chunk 06: "Target player investigates." (the player investigates, CR 701.16a)
        if (sentence == "Target player investigates.") {
            val player = context.targetPlayer()
            return listOf(Step.ForEach(arcanum.api.Each.Players(player), "player", listOf(Step.Do(Effect.Action(arcanum.api.KeywordAction.Investigate(Value.Fixed(1))))),
                together = true))
        }
        // msh chunk 03: "sacrifice it, draw a card, and put a +1/+1 counter on each creature you control", "sacrifice it and create three …"
        Msh.SACRIFICE_IT_AND.matchEntire(sentence)?.let { m ->
            val rest = m.groupValues[1]
            val then = effect(mshSentence(rest), context)
                ?: rest.split(", and ").takeIf { it.size == 2 }?.let { parts ->
                    parts[0].split(", ").map { effect(mshSentence(it), context) ?: return null }.flatten() + (effect(mshSentence(parts[1]), context) ?: return null)
                } ?: return null
            return listOf(Step.Do(Effect.Sacrifice(Objects.Self))) + then
        }
        if (sentence == "Sacrifice it." && (context.event as? EventPattern.CountersPut)?.objects == ObjectFilter.Is(Objects.Self))
            return listOf(Step.Do(Effect.Sacrifice(Objects.Self)))
        // msh chunk 03: "[effect] and put a plan counter on this enchantment", "put a +1/+1 counter on target creature you control and a plan
        // counter on this enchantment"
        Msh.AND_COUNTER_ON_SELF.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[3]) }?.let { m ->
            val first = effect(mshSentence(m.groupValues[1]), context) ?: return null
            return first + Step.Do(Effect.PutCounters(Objects.Self, Counters.kind(m.groupValues[2]) ?: return null, Value.Fixed(1)))
        }
        // msh chunk 08: "target opponent creates The Void, a legendary 5/5 …", "create Redwing, a legendary 1/1 …"
        Msh.CREATES_NAMED_TOKEN.matchEntire(sentence)?.let { m ->
            val token = mshNamedToken(m.groupValues[2]) ?: return null
            val controller = when (m.groupValues[1].lowercase()) {
                "target opponent creates" -> context.targetOpponent()
                "target player creates" -> context.targetPlayer()
                "create", "you create" -> Players.You
                else -> return null
            }
            return listOf(Step.Do(Effect.CreateToken(token, Value.Fixed(1), controller)))
        }
        // msh chunk 06: "attach any number of target Equipment you control to it" (CR 701.3)
        Msh.ATTACH_ANY_NUMBER_TO_IT.matchEntire(sentence)?.let { m ->
            val to = context.it ?: return null
            val name = Filters.slotName(m.groupValues[1])
            context.targets += mshSlot(name, Filters.noun(m.groupValues[1]) ?: return null, min = 0, max = null)
            return listOf(Step.Do(Effect.Attach(Objects.Target(name), arcanum.api.Recipients(objects = to))))
        }
        // msh chunk 07: "Target player creates a 6/5 blue Leviathan creature token with hexproof."
        Msh.TARGET_PLAYER_CREATES.matchEntire(sentence)?.let { m ->
            val (count, token) = mshToken(m.groupValues[1]) ?: return null
            return listOf(Step.Do(Effect.CreateToken(token, Value.Fixed(count), context.targetPlayer())))
        }
        // msh chunk 07: "Return one or two target nonland permanents to their owners' hands."
        Msh.RETURN_ONE_OR_TWO.matchEntire(sentence)?.let { m ->
            val noun = m.groupValues[1]
            val filter = Filters.noun(noun) ?: Filters.noun(noun.removeSuffix("s")) ?: return null
            val name = Filters.slotName(noun.removeSuffix("s"))
            context.targets += TargetSlot(name, TargetKind.Objects(filter), min = Value.Fixed(1), max = Value.Fixed(2))
            return listOf(Step.Do(Effect.Move(Objects.Target(name), Destination(Zone.Hand))))
        }
        return null
    }

    /** msh: more effect sentences. */
    private fun mshEffect2(sentence: String, context: Context): List<Step>? {
        // msh chunk 05: "Until end of turn, target artifact or creature becomes an artifact creature with base power and toughness 4/4 and
        // gains flying." (layers 4, 6, 7b)
        Msh.UNTIL_EOT_TARGET_BECOMES_ARTIFACT_CREATURE.matchEntire(sentence)?.let { m ->
            val target = context.target(Filters.slotName(m.groupValues[1]), Filters.noun(m.groupValues[1]) ?: return null)
            val keywords = mshKeywords(m.groupValues[4]) ?: return null
            return listOf(mshUntilEndOfTurn(target, Mechanic.SetTypes(add = listOf(CardType.Artifact, CardType.Creature)),
                Mechanic.SetPowerToughness(Value.Fixed(m.groupValues[2].toInt()), Value.Fixed(m.groupValues[3].toInt())), Mechanic.GainAbilities(keywords)))
        }
        // msh chunk 08: "Until end of turn, Reptil becomes a Dinosaur Hero with base power and toughness 3/5 and gains reach and vigilance."
        // (its creature types replaced, CR 205.1b)
        Msh.UNTIL_EOT_SELF_BECOMES_SUBTYPES.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val subtypes = m.groupValues[2].split(' ').map { arcanum.api.SubtypeRef.Literal(Subtype(it.takeIf { s -> s in RulesWords.subtypes } ?: return null)) }
            val keywords = mshKeywords(m.groupValues[5]) ?: return null
            return listOf(mshUntilEndOfTurn(Objects.Self, Mechanic.SetTypes(addSubtypes = subtypes, replaceSubtypes = true),
                Mechanic.SetPowerToughness(Value.Fixed(m.groupValues[3].toInt()), Value.Fixed(m.groupValues[4].toInt())), Mechanic.GainAbilities(keywords)))
        }
        // msh chunk 05: "For each nontoken creature you control, create a token that's a copy of that creature, except it isn't legendary."
        // (CR 707.9b)
        Msh.FOR_EACH_CREATE_COPY_NOT_LEGENDARY.matchEntire(sentence)?.let { m ->
            val filter = Filters.noun(m.groupValues[1]) ?: return null
            // inr chunk 09: "For each token you control, create a token that's a copy of that permanent." (CR 707.2)
            val bind = m.groupValues[2]
            val except = if (m.groupValues[3].isEmpty()) emptyList() else listOf(arcanum.api.CopyException.Types(removeSupertypes = listOf(Supertype.Legendary)))
            return listOf(Step.ForEach(arcanum.api.Each.Objects(Objects.Each(filter)), bind, listOf(Step.Do(Effect.CreateToken(
                arcanum.api.TokenSpec.CopyOf(Objects.Bound(bind), except = except), Value.Fixed(1), Players.You)))))
        }
        // msh chunk 05: "Target artifact you control becomes a copy of a second target artifact you control until end of turn, except it
        // isn't legendary." (layer 1, CR 707.9b)
        Msh.TARGET_BECOMES_COPY_OF_SECOND.matchEntire(sentence)?.let { m ->
            val filter = Filters.noun(m.groupValues[1]) ?: return null
            val name = Filters.slotName(m.groupValues[1])
            context.targets += mshSlot(name, filter)
            context.targets += mshSlot("second $name", Filters.noun(m.groupValues[2]) ?: return null).copy(distinctFrom = listOf(name))
            return listOf(mshUntilEndOfTurn(Objects.Target(name), Mechanic.CopyOf(Objects.Target("second $name"),
                except = listOf(arcanum.api.CopyException.Types(removeSupertypes = listOf(Supertype.Legendary))))))
        }
        // msh chunk 05: "you may put an artifact card from your hand onto the battlefield. If it's an Equipment, attach it to The
        // Invincible Iron Man." (CR 701.3)
        Msh.MAY_PUT_FROM_HAND_IF_EQUIPMENT_ATTACH.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[3]) }?.let { m ->
            val filter = Filters.all(Filters.noun(m.groupValues[1]) ?: return null, ObjectFilter.InZone(Zone.Hand), ObjectFilter.OwnedBy(PlayerFilter.You))
            val kind = Filters.noun(m.groupValues[2]) ?: return null
            return listOf(
                Step.Choose(arcanum.api.Choice.Objects(filter, Value.Fixed(0), Value.Fixed(1)), bind = "chosen", chooser = Players.You),
                Step.Do(Effect.Move(Objects.Bound("chosen"), Destination(Zone.Battlefield), postBind = "put")),
                Step.If(arcanum.api.Condition.ObjectMatches(Objects.Bound("put"), kind),
                    then = listOf(Step.Do(Effect.Attach(Objects.Bound("put"), arcanum.api.Recipients(objects = Objects.Self))))))
        }
        // msh chunk 07: "Return that card to the battlefield under its owner's control at the beginning of the next end step." after exiling
        // a target (a delayed trigger, CR 603.7)
        return null
    }

    /** msh: cost parts, tried first in [costPart]. */
    private fun mshCostPart(text: String): List<CostPart>? {
        // msh chunk 06: "Sacrifice an Equipment attached to Ronin"
        Msh.SACRIFICE_ATTACHED_TO_SELF.matchEntire(text)?.takeIf { isSelf(it.groupValues[2]) }?.let { m ->
            return listOf(CostPart.Sacrifice(CostObjects.Choose(Filters.all(Filters.noun(m.groupValues[1]) ?: return null,
                ObjectFilter.Attached(to = Objects.Self)), count = Value.Fixed(1))))
        }
        // msh chunk 02: "Exile any number of black cards from your graveyard with fifteen or more black mana symbols among their mana costs"
        // (CR 107.4: hybrid symbols count)
        Msh.EXILE_BLACK_CARDS_SYMBOLS.matchEntire(text)?.let { m ->
            val color = Tokens.color(m.groupValues[1]) ?: return null
            if (Tokens.color(m.groupValues[3]) != color) return null
            return listOf(CostPart.Exile(CostObjects.Choose(Filters.all(ObjectFilter.OfColor(arcanum.api.ColorRef.Literal(color)), ObjectFilter.Category(arcanum.api.ObjectCategory.Card)),
                count = null, total = arcanum.api.Total(arcanum.api.NumericProperty.ManaSymbols(color), Value.Fixed(mshN(m.groupValues[2]) ?: return null))),
                from = Zone.Graveyard, postBind = "exiled"))
        }
        // msh chunk 08: "Remove any number of +1/+1 counters from The Astonishing Ant-Man" (the number announced, CR 601.2f)
        Msh.REMOVE_ANY_NUMBER_OF_COUNTERS.matchEntire(text)?.takeIf { isSelf(it.groupValues[2]) }?.let { m ->
            return listOf(CostPart.RemoveCounters(Counters.kind(m.groupValues[1]) ?: return null, Value.Announced("X"), CostObjects.Self))
        }
        // msh chunk 10: "Get five poison counters" (ward, CR 702.21a)
        Msh.GET_COUNTERS.matchEntire(text)?.let { m ->
            return listOf(CostPart.GetCounters(Counters.kind(m.groupValues[2]) ?: return null, Value.Fixed(mshN(m.groupValues[1]) ?: return null)))
        }
        // msh chunk 07: "Sacrifice an artifact or discard a nonland card", "Discard a card or pay {2}" (one of two costs)
        Msh.COST_OR_COST.matchEntire(text)?.let { m ->
            val first = cost(mshCap(m.groupValues[1])) ?: return null
            val second = cost(mshCap(m.groupValues[2])) ?: return null
            return listOf(CostPart.OneOf(listOf(first, second)))
        }
        // msh chunk 06: "Tap it" (on resolution, in its own trigger: this permanent)
        if (text == "Tap it" || text == "tap it") return listOf(CostPart.TapSelf)
        return null
    }

    // ---- msh: batch 3

    private fun mshTargetYourGraveyard(noun: String): ObjectFilter? = (Filters.noun(noun) ?: Filters.noun(noun.removeSuffix(" card").let { "$it card" }))
        ?.let { Filters.all(it, ObjectFilter.InZone(Zone.Graveyard), ObjectFilter.OwnedBy(PlayerFilter.You)) }

    /** msh: "[the creature] deals damage … to any other target": any target but this object (CR 115.4). */
    private fun mshAnyOtherTarget(context: Context): Recipients {
        context.targets += TargetSlot("any", TargetKind.Either(Filters.all(mshAnyTargetFilter, ObjectFilter.Not(ObjectFilter.Is(Objects.Self))), PlayerFilter.Any),
            min = Value.Fixed(1), max = Value.Fixed(1))
        return Recipients(target = "any")
    }

    /** msh: "creature on the battlefield or creature card in a graveyard", "artifact, non-Aura enchantment, or land". */
    private fun mshCopyCandidates(phrase: String): ObjectFilter? {
        if (phrase == "creature on the battlefield or creature card in a graveyard") return ObjectFilter.Or(listOf(
            Filters.all(ObjectFilter.Type(CardType.Creature), ObjectFilter.InZone(Zone.Battlefield)),
            Filters.all(ObjectFilter.Type(CardType.Creature), ObjectFilter.Category(arcanum.api.ObjectCategory.Card), ObjectFilter.InZone(Zone.Graveyard))))
        return Filters.noun(phrase)
    }

    /** msh: "Add one mana of any color. Spend this mana only to cast a Hero spell or to activate an ability of a Hero source." */
    private fun mshSpendUse(use: String): ObjectFilter? {
        val u = use.removePrefix("to ")
        if (u == "activate equip abilities") return ObjectFilter.AbilityOf(kind = arcanum.api.AbilityKind.Activated, keyword = arcanum.api.Keyword.Equip.Kind)
        LazyRegexes.ACTIVATE_ABILITIES_OF_SOURCES.matchEntire(u)?.let { m ->
            return ObjectFilter.AbilityOf(kind = arcanum.api.AbilityKind.Activated, source = Filters.noun(m.groupValues[1] + m.groupValues[2]) ?: return null)
        }
        if (u != use) LazyRegexes.CAST_SPELLS.matchEntire(u)?.let { m ->
            return Filters.all(ObjectFilter.Category(arcanum.api.ObjectCategory.Spell), Filters.noun(m.groupValues[1]) ?: return null)
        }
        return null
    }

    /** msh: values. */
    private fun mshValue(text: String): Value? {
        Msh.THE_NUMBER_ATTACHED_TO.matchEntire(text)?.takeIf { it.groupValues[2].isEmpty() || isSelf(it.groupValues[2]) }?.let { m ->
            return Value.Count(Objects.Each(Filters.all(Filters.noun(m.groupValues[1]) ?: return null, ObjectFilter.Attached(to = Objects.Self))))
        }
        if (text == "the number of +1/+1 counters on it" || text == "the number of +1/+1 counters on him" || text == "the number of +1/+1 counters on her")
            return Value.Of(arcanum.api.NumericProperty.Counters(mshP1P1), Objects.Self, arcanum.api.Combine.Single)
        if (text == "its power" || text == "his power" || text == "her power") return mshPower(Objects.Self)
        return null
    }

    /** msh: conditions about a trigger's object. */
    private fun mshCondition(text: String): arcanum.api.Condition? {
        // msh chunk 08: "it has greater power or toughness than Hulkling" (the creature that entered)
        // mkm chunk 02: also "its power is greater than this creature's power or its toughness is greater than this creature's toughness"
        Msh.HAS_GREATER_POWER_OR_TOUGHNESS.matchEntire(text)?.takeIf { isSelf(it.groupValues[1].ifEmpty { it.groupValues[2] }) }?.let {
            val it = Objects.EventObject(EventRole.After)
            return arcanum.api.Condition.Or(listOf(
                arcanum.api.Condition.Compare(mshPower(it), arcanum.api.Comparison.Greater, mshPower(Objects.Self)),
                arcanum.api.Condition.Compare(mshToughness(it), arcanum.api.Comparison.Greater, mshToughness(Objects.Self))))
        }
        // msh chunk 09: "it's the first time that creature has become tapped this turn" (CR 603.4)
        if (Msh.FIRST_TIME_TAPPED_THIS_TURN.matches(text)) {
            val tapped = EventPattern.Tap(ObjectFilter.Is(Objects.EventObject(EventRole.Object)))
            return arcanum.api.Condition.And(listOf(arcanum.api.Condition.HappenedThisTurn(tapped, atLeast = 1, measure = arcanum.api.Measure.Events),
                arcanum.api.Condition.Not(arcanum.api.Condition.HappenedThisTurn(tapped, atLeast = 2, measure = arcanum.api.Measure.Events))))
        }
        return null
    }

    /** msh: modal triggered abilities whose number of modes is a value ("choose up to X —", "choose up to that many —"). */
    private fun mshModalTrigger(header: String, modeLines: List<String>): Ability? {
        fun options(): List<arcanum.api.Mode>? = modeLines.map { arcanum.api.Mode(instructions(modeBody(it)) ?: return null, text = it) }
        // msh chunk 09: "When The Ruinous Wrecking Crew enters, choose up to X —" (X as it was cast, CR 107.3m)
        Msh.ENTERS_CHOOSE_UP_TO_X.matchEntire(header)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            val modes = options() ?: return null
            return Ability.Triggered(arcanum.api.Trigger.On(EventPattern.ZoneChange(ObjectFilter.Is(Objects.Self), to = Zone.Battlefield)),
                Instructions(modes = arcanum.api.Modes(modes, min = 0, max = modes.size, chooser = Players.You, maxCount = Value.CastX(of = Objects.Self))))
        }
        // msh chunk 07: "Whenever Hawkeye becomes tapped, you may pay {1} up to three times. When you do, choose up to that many —": the
        // number of times is chosen, then paid as one cost; the reflexive trigger's modes are as many (CR 603.12, 700.2)
        Msh.PAY_UP_TO_TIMES_CHOOSE_THAT_MANY.matchEntire(header)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val times = mshN(m.groupValues[3]) ?: return null
            val modes = options() ?: return null
            val n = Value.Bound("times")
            return Ability.Triggered(arcanum.api.Trigger.On(EventPattern.Tap(ObjectFilter.Is(Objects.Self))), Instructions(steps = listOf(
                Step.Choose(arcanum.api.Choice.Number(Value.Fixed(1), Value.Fixed(times)), bind = "times", chooser = Players.You),
                Step.Pay(Cost(listOf(CostPart.Mana(ManaCost.parse(m.groupValues[2]) ?: return null, times = n))), payer = Players.You, bind = "paid"),
                Step.If(arcanum.api.Condition.Did("paid"), then = listOf(Step.Do(Effect.ReflexiveTrigger(Instructions(modes = arcanum.api.Modes(modes, min = 0,
                    max = times, chooser = Players.You, maxCount = n)))))))))
        }
        return null
    }

    /** msh: "Choose up to two. Return those cards from your graveyard to your hand." with "• Target artifact card." modes: each mode is
     * a target; the step after the modes returns every target chosen (CR 700.2). */
    fun mshModes(header: String, modeLines: List<String>): Ability? {
        val m = Msh.CHOOSE_UP_TO_RETURN_THOSE.matchEntire(header) ?: return null
        val n = mshN(m.groupValues[1]) ?: return null
        val names = mutableListOf<String>()
        val options = modeLines.map { line ->
            val t = LazyRegexes.TARGET_SENTENCE.matchEntire(line) ?: return null
            val noun = t.groupValues[1]
            // msh backfill: each mode's own slot ("artifact card", "creature card"), so the step after the modes reads every
            // chosen target (one shared name kept only the first mode's)
            val name = noun
            names += name
            arcanum.api.Mode(Instructions(targets = listOf(mshSlot(name, mshTargetYourGraveyard(noun) ?: return null))), text = line)
        }
        return Ability.Spell(Instructions(modes = arcanum.api.Modes(options, min = 0, max = n, chooser = Players.You),
            steps = listOf(Step.Do(Effect.Move(Objects.Union(names.map { Objects.Target(it) }), Destination(Zone.Hand))))))
    }

    private fun mshLine2(line: String): Ability? {
        // msh chunk 10: "At the beginning of your end step, if you have fewer than ten cards in hand, draw cards equal to the difference."
        Msh.FEWER_THAN_DRAW_DIFFERENCE.matchEntire(line)?.let { m ->
            val n = mshN(m.groupValues[1]) ?: return null
            return Ability.Triggered(arcanum.api.Trigger.On(EventPattern.StepBegins(arcanum.api.TurnStep.End, PlayerFilter.You)),
                Instructions(steps = listOf(Step.Do(Effect.Draw(Players.You, Value.Difference(Value.Fixed(n), Value.HandSize(Players.You)))))),
                interveningIf = arcanum.api.Condition.Compare(Value.HandSize(Players.You), arcanum.api.Comparison.Less, Value.Fixed(n)))
        }
        return null
    }

    private fun mshStatic2(line: String): Ability? {
        // msh chunk 02: "Villain spells you cast cost {1} less to cast." (CR 601.2f)
        Msh.SPELLS_YOU_CAST_COST_LESS.matchEntire(line)?.let { m ->
            val spells = Filters.noun(m.groupValues[1].replaceFirstChar { it.lowercase() }) ?: Filters.noun(m.groupValues[1]) ?: return null
            return Ability.Static(listOf(Mechanic.CostChange(spells, arcanum.api.CostChange.Less(ManaCost.parse(m.groupValues[2]) ?: return null, Value.Fixed(1)))),
                affects = mshSelfOnly)
        }
        // msh chunk 05: "Ms. Marvel's base power is equal to the number of cards in your hand." (layer 7b; granted, so not
        // characteristic-defining)
        Msh.BASE_POWER_EQUAL_TO.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val value = Values.value(m.groupValues[2]) ?: return null
            return Ability.Static(listOf(Mechanic.SetPowerToughness(value, null)), affects = mshSelfOnly)
        }
        return null
    }

    private fun mshModify2(sentence: String, steps: List<Step>, context: Context): List<Step>? {
        // msh chunk 02: "That creature is a Hero in addition to its other types." after returning it to the battlefield (as it enters,
        // CR 611.2e)
        Msh.IS_A_IN_ADDITION.matchEntire(sentence)?.let { m ->
            val index = steps.indexOfLast { ((it as? Step.Do)?.effect as? Effect.Move)?.to?.zone == Zone.Battlefield }.takeIf { it >= 0 } ?: return null
            val move = (steps[index] as Step.Do).effect as Effect.Move
            val subtype = m.groupValues[1].takeIf { it in RulesWords.subtypes } ?: return null
            return steps.toMutableList().also { it[index] = Step.Do(move.copy(to = move.to.copy(entersAs = move.to.entersAs +
                Mechanic.SetTypes(addSubtypes = listOf(arcanum.api.SubtypeRef.Literal(Subtype(subtype))))))) }
        }
        // msh chunk 08: "It loses all abilities and gains haste." after returning it to the battlefield (for as long as it stays, CR 611.2a)
        Msh.LOSES_ALL_ABILITIES_AND_GAINS.matchEntire(sentence)?.let { m ->
            val index = steps.indexOfLast { ((it as? Step.Do)?.effect as? Effect.Move)?.to?.zone == Zone.Battlefield }.takeIf { it >= 0 } ?: return null
            val move = (steps[index] as Step.Do).effect as Effect.Move
            val keywords = mshKeywords(m.groupValues[1]) ?: return null
            return steps.toMutableList().also { it[index] = Step.Do(move.copy(postBind = "returned")) } +
                Step.Do(Effect.ApplyMechanics(listOf(Mechanic.LoseAbilities(), Mechanic.GainAbilities(keywords)), Affected.Objects(Objects.Bound("returned")),
                    arcanum.api.Duration.Indefinitely))
        }
        // msh chunk 07: "During that turn, power-up abilities can't be activated." after taking an extra turn: from that turn's upkeep (no
        // player gets priority in its untap step, CR 502.4) to its end
        if (Msh.DURING_THAT_TURN_CANT_ACTIVATE.matches(sentence)) {
            if (((steps.lastOrNull() as? Step.Do)?.effect as? Effect.ExtraTurn) == null) return null
            return steps + Step.Do(Effect.CreateDelayedTrigger(arcanum.api.Trigger.On(EventPattern.StepBegins(arcanum.api.TurnStep.Upkeep, PlayerFilter.You)),
                Instructions(steps = listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.CantActivate(ObjectFilter.AbilityOf(label = arcanum.api.AbilityLabel.PowerUp))),
                    Affected.Players(Players.Each(PlayerFilter.Any)), arcanum.api.Duration.EndOfTurn))))))
        }
        // msh chunk 08: "You may put a permanent card from among the milled cards into your hand." after milling (the cards in the graveyard,
        // CR 400.7)
        Msh.MAY_PUT_FROM_AMONG_MILLED.matchEntire(sentence)?.let { m ->
            val index = steps.indexOfLast { ((it as? Step.Do)?.effect as? Effect.Mill) != null }.takeIf { it >= 0 } ?: return null
            val mill = (steps[index] as Step.Do).effect as Effect.Mill
            val filter = Filters.noun(m.groupValues[1]) ?: return null
            return steps.toMutableList().also { it[index] = Step.Do(mill.copy(postBind = "milled")) } + listOf(
                Step.Choose(arcanum.api.Choice.Objects(filter, Value.Fixed(0), Value.Fixed(1), from = Objects.Bound("milled")), bind = "chosen", chooser = Players.You),
                Step.Do(Effect.Move(Objects.Bound("chosen"), Destination(Zone.Hand))))
        }
        // msh chunk 09: "That creature can't become untapped for as long as you control Spider-Woman." after tapping a target
        Msh.CANT_BECOME_UNTAPPED_AS_LONG_AS_CONTROL.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            val target = mshLastTarget(context) ?: return null
            return steps + Step.Do(Effect.ApplyMechanics(listOf(Mechanic.CantBecomeUntapped), Affected.Objects(target),
                arcanum.api.Duration.AsLongAs(arcanum.api.Condition.ObjectMatches(Objects.Self, ObjectFilter.ControlledBy(PlayerFilter.You)))))
        }
        // msh chunk 09: "You may choose new targets for that spell." (the spell of a cast trigger, CR 115.7)
        if (Msh.MAY_CHOOSE_NEW_TARGETS_FOR_THAT_SPELL.matches(sentence) && context.event is EventPattern.Cast)
            return steps + Step.Do(Effect.ChangeTargets(Objects.EventObject(EventRole.Object), Players.You, optional = true))
        return null
    }

    private fun fdnValue(text: String, event: EventPattern?): Value? =
        // fdn chunk 06: "where X is the mana value of that spell" in a cast trigger (the spell, or as it last existed: CR 603.4, 608.2h)
        if (event is EventPattern.Cast && text == "the mana value of that spell") Value.Of(arcanum.api.NumericProperty.ManaValue, Objects.EventObject(EventRole.Object), arcanum.api.Combine.Single)
        else null

    private fun fdnWhole(text: String, context: Context): List<Step>? {
        // fdn chunk 27: Exsanguinate: the life each opponent actually lost (CR 119.3, 119.4) is what you gain, so the loss is bound
        Fdn.EACH_OPPONENT_LOSES_X_GAIN_LOST.matchEntire(text)?.let {
            return listOf(Step.Do(Effect.LoseLife(Players.Each(PlayerFilter.Opponent), Value.Announced("X"), bind = "lost")),
                Step.Do(Effect.GainLife(Players.You, Value.Bound("lost"))))
        }
        // fdn chunk 11b: Finale of Revelation: with X of 10 or more, the whole spell is a different version (CR 608.2e "instead", 107.3m)
        Fdn.SHUFFLE_GRAVEYARD_INSTEAD_IF_X.matchEntire(text)?.let { m ->
            val untap = instructions(m.groupValues[2].replaceFirstChar { it.uppercase() } + ".")?.takeIf { it.targets.isEmpty() }?.steps ?: return@let
            val draw = Step.Do(Effect.Draw(Players.You, Value.Announced(name = "X")))
            return listOf(Step.If(arcanum.api.Condition.Compare(Value.Announced(name = "X"), arcanum.api.Comparison.AtLeast, Value.Fixed(m.groupValues[1].toInt())),
                then = listOf(
                    Step.Do(Effect.Move(Objects.Each(Filters.all(ObjectFilter.InZone(Zone.Graveyard), ObjectFilter.OwnedBy(PlayerFilter.You))), Destination(Zone.Library))),
                    Step.Do(Effect.Shuffle(Players.You)), draw) + untap +
                    Step.Do(Effect.ApplyMechanics(listOf(Mechanic.NoMaximumHandSize), Affected.Players(Players.You), arcanum.api.Duration.Indefinitely)),
                otherwise = listOf(draw)))
        }
        // fdn chunk 11a: Loot: look at the top N, you may reveal a creature card with mana value at most the number of lands you control from
        // among them and put it onto the battlefield, the rest on the bottom in a random order (CR 701.20, 400.7)
        Fdn.LOOK_REVEAL_MV_AT_MOST_COUNT_PUT_REST_BOTTOM.matchEntire(text)?.let { m ->
            val n = Numbers.count(m.groupValues[1]) ?: return@let
            val count = Value.Count(Objects.Each(Filters.noun(m.groupValues[3]) ?: return@let))
            val filter = Filters.all(Filters.noun(m.groupValues[2]) ?: return@let, ObjectFilter.ManaValue(arcanum.api.Comparison.AtMost, count))
            val seen = Objects.Bound("seen")
            return listOf(
                Step.Do(Effect.LookAt(Objects.LibraryCards(Players.You, Value.Fixed(n), fromTop = true), Players.You, bind = "seen")),
                Step.Choose(arcanum.api.Choice.Objects(filter, Value.Fixed(0), Value.Fixed(1), from = seen), bind = "chosen", chooser = Players.You),
                Step.Do(Effect.Reveal(Objects.Bound("chosen"))),
                Step.Do(Effect.Move(Objects.Bound("chosen"), Destination(Zone.Battlefield))),
                Step.Do(Effect.Move(Objects.Except(seen, Objects.Bound("chosen")), Destination(Zone.Library, libraryPosition = -1, randomOrder = true))))
        }
        // fdn chunk 11a: Genesis Wave: reveal the top X, put any number of permanent cards with mana value X or less from among them onto the
        // battlefield, the rest revealed cards into the graveyard (CR 701.20a, 400.7)
        Fdn.REVEAL_X_PUT_ANY_NUMBER_MV_X_REST_GRAVEYARD.matchEntire(text)?.let { m ->
            val filter = Filters.all(Filters.noun(m.groupValues[1]) ?: return@let,
                ObjectFilter.ManaValue(arcanum.api.Comparison.AtMost, Value.Announced(name = "X")))
            val revealed = Objects.Bound("revealed")
            return listOf(
                Step.Do(Effect.Reveal(Objects.LibraryCards(Players.You, Value.Announced(name = "X"), fromTop = true), bind = "revealed")),
                Step.Choose(arcanum.api.Choice.Objects(filter, Value.Fixed(0), null, from = revealed), bind = "chosen", chooser = Players.You),
                Step.Do(Effect.Move(Objects.Bound("chosen"), Destination(Zone.Battlefield))),
                Step.Do(Effect.Move(Objects.Except(revealed, Objects.Bound("chosen")), Destination(Zone.Graveyard))))
        }
        // fdn chunk 10b: "This land becomes a 3/3 creature with vigilance and all creature types. It's still a land." (for good, CR 611.2a; layers 4 and 7b)
        Fdn.SELF_BECOMES_CREATURE_WITH_ALL_TYPES.matchEntire(text)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val keywords = keywords(m.groupValues[4]) ?: return@let
            return listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.SetTypes(add = listOf(CardType.Creature)), Mechanic.AllCreatureTypes,
                Mechanic.SetPowerToughness(Value.Fixed(m.groupValues[2].toInt()), Value.Fixed(m.groupValues[3].toInt())), Mechanic.GainAbilities(keywords)),
                Affected.Objects(Objects.Self), arcanum.api.Duration.Indefinitely)))
        }
        // fdn chunk 09: "Destroy all creatures. You gain 1 life for each creature destroyed this way." (the count is of those destroyed, CR 608.2c)
        Fdn.DESTROY_ALL_GAIN_FOR_EACH.matchEntire(text)?.let { m ->
            val filter = Filters.noun(m.groupValues[1]) ?: return@let
            return listOf(Step.Do(Effect.Destroy(Objects.Each(filter), postBind = "destroyed")),
                Step.Do(Effect.GainLife(Players.You, Value.Times(Value.Count(Objects.Bound("destroyed")), m.groupValues[2].toInt()))))
        }
        // fdn chunk 09: Abyssal Harvester: "Exile target creature card from a graveyard that was put there this turn. Create a token that's a copy of it,
        // except it's a Nightmare in addition to its other types. Then exile all other Nightmare tokens you control." (CR 707.2, 111.1; the new token stays)
        Fdn.EXILE_PUT_THERE_THIS_TURN_COPY_EXCEPT_SUBTYPE_EXILE_OTHERS.matchEntire(text)?.let { m ->
            val subtype = m.groupValues[2].takeIf { it in RulesWords.subtypes } ?: return@let
            val name = Filters.slotName(m.groupValues[1])
            context.targets += TargetSlot(name, TargetKind.Objects(Filters.all(Filters.noun(m.groupValues[1]) ?: return@let, ObjectFilter.InZone(Zone.Graveyard),
                ObjectFilter.ThisTurn(EventPattern.ZoneChange(ObjectFilter.Any, to = Zone.Graveyard), role = EventRole.After))), min = Value.Fixed(1), max = Value.Fixed(1))
            val others = Filters.all(Filters.noun("$subtype tokens you control") ?: return@let, ObjectFilter.Not(ObjectFilter.Is(Objects.Bound("token"))))
            return listOf(Step.Do(Effect.Move(Objects.Target(name), Destination(Zone.Exile), postBind = "exiled")),
                Step.Do(Effect.CreateToken(arcanum.api.TokenSpec.CopyOf(Objects.Bound("exiled"), except = listOf(
                    arcanum.api.CopyException.Types(addSubtypes = listOf(arcanum.api.SubtypeRef.Literal(Subtype(subtype)))))), Value.Fixed(1), Players.You, bind = "token")),
                Step.Do(Effect.Move(Objects.Each(others), Destination(Zone.Exile))))
        }
        // fdn chunk 09: "Put a +1/+1 counter on target creature you control. Then that creature deals damage equal to its power to target
        // creature an opponent controls." reads like the tdm ", then it deals" wording (CR 608.2c)
        if (text.contains(". Then that creature deals damage equal to its power to target ")) Tdm.COUNTER_THEN_DEALS_DAMAGE_EQUAL_POWER.matchEntire(text)?.let { return tdmEffect(text, context) }
        // fdn chunk 08: "Goblin Negotiation deals X damage to target creature. Create a number of 1/1 red Goblin creature tokens equal to the
        // amount of excess damage dealt to that creature this way." (CR 120.4a)
        Fdn.DEALS_DAMAGE_CREATE_EXCESS.matchEntire(text)?.let { m ->
            val damage = effect(m.groupValues[1], context) ?: return@let
            val deal = (damage.singleOrNull() as? Step.Do)?.effect as? Effect.DealDamage ?: return@let
            if (deal.bind != null) return@let
            val (_, token) = Tokens.spec("a " + m.groupValues[2]) ?: return@let
            return listOf(Step.Do(deal.copy(bind = "damage")), Step.Do(Effect.CreateToken(token, count = Value.Excess("damage"), controller = Players.You)))
        }
        // fdn chunk 08: "Whenever you cast an instant or sorcery spell, copy it for each other instant and sorcery spell you've cast before it
        // this turn. You may choose new targets for the copies." (as storm counts, CR 702.40a, 707.10)
        Fdn.COPY_FOR_EACH_SPELL_CAST_BEFORE.matchEntire(text)?.takeIf { context.event is EventPattern.Cast }?.let { m ->
            // the kind only: every one counted was a spell (judged as it was cast, CR 608.2h)
            val spells = Filters.noun(m.groupValues[1].replace(" and ", " or ")) ?: return@let
            val spell = Objects.EventObject(EventRole.Object)
            return listOf(Step.Repeat(Value.SpellsCastBefore(spell, spells = spells, caster = PlayerFilter.You),
                listOf(Step.Do(Effect.CopySpell(spell, controller = Players.You, newTargets = true)))))
        }
        // fdn chunk 07: "Exile up to two target cards from a single graveyard. If at least one creature card was exiled this way, …": what the
        // exile moved is counted after it (CR 608.2c)
        Fdn.EXILE_IF_AT_LEAST_ONE_EXILED.matchEntire(text)?.let { m ->
            val exile = effect(m.groupValues[1], context) ?: return@let
            val move = (exile.lastOrNull() as? Step.Do)?.effect as? Effect.Move ?: return@let
            if (move.to.zone != Zone.Exile || move.postBind != null) return@let
            val kind = Filters.noun(m.groupValues[2]) ?: return@let
            val then = effect(m.groupValues[3].replaceFirstChar { c -> c.uppercase() }, context) ?: return@let
            return exile.dropLast(1) + Step.Do(move.copy(postBind = "exiled")) +
                Step.If(arcanum.api.Condition.Compare(Value.Count(Objects.Where(Objects.Bound("exiled"), kind)), arcanum.api.Comparison.AtLeast, Value.Fixed(1)), then = then)
        }
        // fdn chunk 02: "put a +1/+1 counter on it. Then if it has three or more +1/+1 counters on it, sacrifice this Aura.": both "it"s are what the
        // ability is about (the attacking creature), not this permanent (CR 608.2c)
        Fdn.COUNTER_ON_IT_THEN_IF_IT_HAS.matchEntire(text)?.let { m ->
            val it = context.it?.takeIf { it != Objects.Self } ?: return@let
            val kind = Counters.kind(m.groupValues[1]) ?: return@let
            if (Counters.kind(m.groupValues[3]) != kind) return@let
            val then = effect(m.groupValues[4].replaceFirstChar { c -> c.uppercase() }, context) ?: return@let
            return listOf(Step.Do(Effect.PutCounters(it, kind, Value.Fixed(1))),
                Step.If(arcanum.api.Condition.ObjectMatches(it, ObjectFilter.HasCounter(kind, atLeast = Numbers.count(m.groupValues[2]) ?: return@let)), then = then))
        }
        // fdn chunk 01: "Exile it. If you do, you gain 4 life.": whether it was exiled decides (gone before it resolves, it can't be, CR 400.7)
        Fdn.EXILE_IT_IF_YOU_DO.matchEntire(text)?.let { m ->
            val it = context.it ?: return null
            val then = effect(m.groupValues[1].replaceFirstChar { c -> c.uppercase() }, context) ?: return null
            return listOf(Step.Do(Effect.Move(it, Destination(Zone.Exile), postBind = "exiled")),
                Step.If(arcanum.api.Condition.Compare(Value.Count(Objects.Bound("exiled")), arcanum.api.Comparison.AtLeast, Value.Fixed(1)), then = then))
        }
        return null
    }

    // ---- mkm

    /** mkm: sentences that change or read the steps before them. */
    private fun mkmModify(sentence: String, steps: List<Step>, context: Context): List<Step>? {
        // mkm chunk 03: "Until end of turn, target artifact or creature becomes an artifact creature with base power and toughness 4/3. If evidence
        // was collected, it has base power and toughness 1/1 until end of turn instead." (one or the other, CR 613.4b, 701.59c)
        Mkm.IF_HAS_BASE_PT_INSTEAD.matchEntire(sentence)?.let { m ->
            val condition = Conditions.condition(m.groupValues[1], self) ?: return null
            val apply = (steps.lastOrNull() as? Step.Do)?.effect as? Effect.ApplyMechanics ?: return null
            if (apply.mechanics.none { it is Mechanic.SetPowerToughness }) return null
            val pt = Mechanic.SetPowerToughness(Value.Fixed(m.groupValues[2].toInt()), Value.Fixed(m.groupValues[3].toInt()))
            val instead = apply.copy(mechanics = apply.mechanics.map { if (it is Mechanic.SetPowerToughness) pt else it })
            return steps.dropLast(1) + Step.If(condition, then = listOf(Step.Do(instead)), otherwise = listOf(Step.Do(apply)))
        }
        // mkm chunk 02: "Creatures your opponents control get -2/-0 until end of turn. If any of them are suspected, they're no longer suspected."
        // (those of the group that have the mark lose it, CR 701.60a)
        Mkm.IF_ANY_OF_THEM_NO_LONGER.matchEntire(sentence)?.let { m ->
            val mark = ActionWordings.mark(m.groupValues[1]) ?: return null
            val apply = (steps.lastOrNull() as? Step.Do)?.effect as? Effect.ApplyMechanics ?: return null
            val group = (apply.affects as? Affected.Objects)?.objects ?: return null
            return steps + Step.Do(Effect.Mark(group, mark, remove = true))
        }
        // mkm chunk 02: "Torch the Witness deals twice X damage to target creature. If excess damage was dealt to that creature this way,
        // investigate." (the damage over lethal, CR 120.4a)
        Mkm.IF_EXCESS_DAMAGE_THIS_WAY.matchEntire(sentence)?.let { m ->
            val damage = (steps.lastOrNull() as? Step.Do)?.effect as? Effect.DealDamage ?: return null
            val targets = context.targets.size
            val then = effect(m.groupValues[1].replaceFirstChar { it.uppercase() }, context)?.takeIf { context.targets.size == targets } ?: return null
            val bind = damage.bind ?: "damage"
            return steps.dropLast(1) + Step.Do(damage.copy(bind = bind)) +
                Step.If(arcanum.api.Condition.Compare(Value.Excess(bind), arcanum.api.Comparison.Greater, Value.Fixed(0)), then = then)
        }
        // mkm chunk 01: "Target opponent gains control of any number of target permanents you control. Draw a card for each one they gained
        // control of this way." (those of the targets that player controls afterwards, CR 608.2c)
        if (Mkm.DRAW_FOR_EACH_THEY_GAINED_CONTROL.matches(sentence)) {
            val give = (steps.lastOrNull() as? Step.Do)?.effect as? Effect.ApplyMechanics ?: return null
            val control = give.mechanics.singleOrNull() as? Mechanic.ControlledBy ?: return null
            val objects = (give.affects as? Affected.Objects)?.objects ?: return null
            return steps + Step.Do(Effect.Draw(Players.You, Value.Count(Objects.Where(objects, ObjectFilter.ControlledBy(PlayerFilter.Is(control.players))))))
        }
        return null
    }

    /** mkm: trigger events with a condition checked as they would trigger. */
    private fun mkmTrigger(text: String): Pair<arcanum.api.Trigger.On, arcanum.api.Condition?>? {
        // mkm chunk 04: "one or more creatures you control and/or creature cards in your graveyard are put into exile" (CR 603.2c)
        Mkm.PUT_INTO_EXILE_FROM_BATTLEFIELD_AND_OR_GRAVEYARD.matchEntire(text)?.let { m ->
            val onBattlefield = Filters.noun(m.groupValues[1] + " you control") ?: return null
            val inGraveyard = Filters.all(Filters.noun(m.groupValues[2] + " card") ?: return null, ObjectFilter.OwnedBy(PlayerFilter.You))
            return arcanum.api.Trigger.On(listOf(EventPattern.ZoneChange(onBattlefield, from = Zone.Battlefield, to = Zone.Exile),
                EventPattern.ZoneChange(inGraveyard, from = Zone.Graveyard, to = Zone.Exile)), oneOrMore = true) to null
        }
        // mkm chunk 02: "this creature is dealt 3 or more damage" (the damage dealt to it at once, from any sources: one trigger, CR 603.2c)
        Mkm.IS_DEALT_N_OR_MORE_DAMAGE.matchEntire(text)?.let { m ->
            val events = Events.events(m.groupValues[1] + " is dealt damage", self) ?: return null
            return arcanum.api.Trigger.On(events, oneOrMore = true) to
                arcanum.api.Condition.Compare(Value.EventAmount, arcanum.api.Comparison.AtLeast, Value.Fixed(m.groupValues[2].toInt()))
        }
        return null
    }

    /** mkm: wordings of several sentences read as one. */
    private fun mkmWhole(text: String, context: Context): List<Step>? {
        // mkm chunk 05: "you may suspect one of the other creatures. If you do, this creature is no longer suspected." after a batch trigger
        // ("one or more other creatures you control enter"): zero or one of the creatures that entered, chosen as it resolves (CR 701.60a)
        Mkm.MAY_SUSPECT_ONE_OF_THE_OTHER.matchEntire(text)?.let { m ->
            if (context.event == null) return@let
            val filter = Filters.noun(m.groupValues[1]) ?: return@let
            val then = effect(m.groupValues[2].replaceFirstChar { it.uppercase() }, context) ?: return@let
            return listOf(Step.Choose(arcanum.api.Choice.Objects(filter, Value.Fixed(0), Value.Fixed(1), from = Objects.EventObject(arcanum.api.EventRole.After)),
                    bind = "chosen", chooser = Players.You),
                Step.Do(Effect.Mark(Objects.Bound("chosen"), arcanum.api.ObjectMark.Suspected)),
                Step.If(arcanum.api.Condition.NonEmpty("chosen"), then = then))
        }
        // mkm chunk 04: "You may choose a creature card from among them. Until end of turn, target token you control becomes a copy of it, except it
        // has flying." after a batch trigger (the target is chosen as the ability goes on the stack, the card as it resolves; CR 707.2, 707.9a)
        Mkm.MAY_CHOOSE_FROM_AMONG_THEM_TARGET_BECOMES_COPY.matchEntire(text)?.let { m ->
            val chosen = Filters.noun(m.groupValues[1]) ?: return null
            val target = context.target(Filters.slotName(m.groupValues[2]), Filters.noun(m.groupValues[2]) ?: return null)
            val keyword = OracleParser.keyword(m.groupValues[3].replaceFirstChar { it.uppercase() }) ?: return null
            return listOf(Step.Choose(arcanum.api.Choice.Objects(chosen, Value.Fixed(0), Value.Fixed(1), from = Objects.EventObject(arcanum.api.EventRole.After)),
                    bind = "chosen", chooser = Players.You),
                Step.If(arcanum.api.Condition.NonEmpty("chosen"), then = listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.CopyOf(Objects.Bound("chosen"),
                    except = listOf(arcanum.api.CopyException.AddAbilities(listOf(keyword))))), Affected.Objects(target), arcanum.api.Duration.EndOfTurn)))))
        }
        // mkm chunk 03: "… If evidence was collected, exile a card from an opponent's graveyard. Then search its owner's graveyard, hand, and library
        // for any number of cards with that name and exile them. That player shuffles, then draws a card for each card exiled from their hand this
        // way." (the card is chosen as it resolves, not targeted; CR 701.23a, 701.59c)
        Mkm.IF_EXILE_FROM_OPPONENTS_GRAVEYARD_SEARCH_NAME.matchEntire(text)?.let { m ->
            val first = effect(m.groupValues[1], context) ?: return null
            val condition = Conditions.condition(m.groupValues[2], self) ?: return null
            val owner = Players.OwnerOf(Objects.Bound("exiled"))
            val zones = listOf(Zone.Graveyard, Zone.Hand, Zone.Library)
            val all = Value.Count(Objects.Each(Filters.all(ObjectFilter.OwnedBy(PlayerFilter.Is(owner)), ObjectFilter.Or(zones.map { ObjectFilter.InZone(it) }))))
            return first + Step.If(condition, then = listOf(
                Step.Choose(arcanum.api.Choice.Objects(Filters.all(ObjectFilter.InZone(Zone.Graveyard), ObjectFilter.OwnedBy(PlayerFilter.Opponent)),
                    Value.Fixed(1), Value.Fixed(1)), bind = "chosen", chooser = Players.You),
                Step.Do(Effect.Move(Objects.Bound("chosen"), Destination(Zone.Exile), postBind = "exiled")),
                Step.Do(Effect.Search(owner, ObjectFilter.SameNameAs(Objects.Bound("exiled")), max = all, zones = zones, bind = "found", searcher = Players.You)),
                Step.Bind(Objects.Where(Objects.Bound("found"), ObjectFilter.InZone(Zone.Hand)), "fromHand"),
                Step.Do(Effect.Move(Objects.Bound("found"), Destination(Zone.Exile))),
                Step.Do(Effect.Shuffle(owner)),
                Step.Do(Effect.Draw(owner, Value.Count(Objects.Bound("fromHand"))))))
        }
        // mkm chunk 03: "Search your library for a basic land card. If evidence was collected, instead search your library for a creature or land
        // card. Reveal that card, put it into your hand, then shuffle." (one search or the other, CR 701.23, 701.59c)
        Mkm.SEARCH_IF_INSTEAD_SEARCH.matchEntire(text)?.let { m ->
            val condition = Conditions.condition(m.groupValues[2], self) ?: return null
            val otherwise = effect("Search your library for ${m.groupValues[1]}, reveal it, ${m.groupValues[4]}.", context) ?: return null
            val then = effect("Search your library for ${m.groupValues[3]}, reveal it, ${m.groupValues[4]}.", context) ?: return null
            return listOf(Step.If(condition, then = then, otherwise = otherwise))
        }
        return null
    }

    /** mkm: lines of several abilities. */
    private fun mkmMulti(line: String): List<Ability>? {
        // mkm chunk 06: "Solved — [abilities]": a label on each ability a line of several makes (CR 702.169a)
        ABILITY_WORD.matchEntire(line)?.let { m ->
            val label = LABELS[m.groupValues[1].lowercase()] ?: return@let
            return (multi(m.groupValues[2]) ?: finMulti(m.groupValues[2]))?.map { ability ->
                when (ability) {
                    is Ability.Activated -> ability.copy(label = label)
                    is Ability.Triggered -> ability.copy(label = label)
                    is Ability.Static -> ability.copy(label = label)
                    else -> return null
                }
            } ?: return null
        }
        // mkm chunk 06: "You may look at the top card of your library any time, and you may play lands and cast creature and enchantment spells from
        // the top of your library.": each permission read as a line of its own
        Mkm.YOU_MAY_AND_YOU_MAY.matchEntire(line)?.let { m ->
            fun part(text: String) = multi(text) ?: line(text)?.takeIf { it !is Ability.Unparsed }?.let { listOf(it) } ?: finMulti(text)
            return (part("${m.groupValues[1]}.") ?: return@let) + (part("You may ${m.groupValues[2]}") ?: return@let)
        }
        // mkm chunk 03: "As an additional cost to cast this spell, you may collect evidence 6. This spell costs {2} less to cast if evidence was
        // collected." (the cost, then a rule of the spell linked to it, CR 601.2f, 701.59c)
        Mkm.ADDITIONAL_COST_THEN_THIS_SPELL.matchEntire(line)?.let { m ->
            val cost = line(m.groupValues[1])?.takeIf { it !is Ability.Unparsed } ?: return null
            val rule = line(m.groupValues[2])?.takeIf { it !is Ability.Unparsed } ?: return null
            return listOf(cost, rule)
        }
        return null
    }

    /** mkm: single-sentence effects, tried first. */
    private fun mkmEffect(sentence: String, context: Context): List<Step>? {
        // mkm chunk 06: "Creature cards in your graveyard gain "You may cast this card from your graveyard" until end of turn." (the cards there as it
        // resolves, CR 611.2c; the ability works in the graveyard, CR 113.6f)
        Mkm.CARDS_IN_YOUR_GRAVEYARD_GAIN_QUOTED.matchEntire(sentence)?.let { m ->
            val cards = Filters.noun(m.groupValues[1].replaceFirstChar { it.lowercase() }) ?: return@let
            val quoted = m.groupValues[2].let { if (it.endsWith(".")) it else "$it." }
            val granted = Sentences(setOf("this card", "This card")).line(quoted)?.takeIf { it !is Ability.Unparsed } ?: return@let
            return listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.GainAbilities(listOf(granted))), Affected.Objects(Objects.Each(
                Filters.all(cards, ObjectFilter.InZone(Zone.Graveyard), ObjectFilter.OwnedBy(PlayerFilter.You)))), arcanum.api.Duration.EndOfTurn)))
        }
        // mkm chunk 06: "create a 2/1 black Skeleton creature token and suspect it": "it" is the token just created (CR 111.1), not this object
        Mkm.CREATE_TOKEN_AND_IT.matchEntire(sentence)?.let { m ->
            val steps = effect(m.groupValues[1] + ".", context) ?: return@let
            val create = (steps.singleOrNull() as? Step.Do)?.effect as? Effect.CreateToken ?: return@let
            if (create.count != Value.Fixed(1)) return@let
            val bind = create.bind ?: "token"
            val saved = context.it
            context.it = Objects.Bound(bind)
            val then = effect(m.groupValues[2].replaceFirstChar { it.uppercase() } + ".", context)
            if (then == null) { context.it = saved; return@let }
            return listOf(Step.Do(create.copy(bind = bind))) + then
        }
        // mkm chunk 05: "Suspect it.", "suspect this creature" (CR 701.60a)
        Mkm.SUSPECT_OBJECTS.matchEntire(sentence)?.let { m ->
            val objects = (if (m.groupValues[1] == "them") context.them else fraObjects(m.groupValues[1], context)) ?: return@let
            return listOf(Step.Do(Effect.Mark(objects, arcanum.api.ObjectMark.Suspected)))
        }
        // mkm chunk 05: "All suspected creatures are no longer suspected.", "this creature is no longer suspected." (CR 701.60a)
        Mkm.NO_LONGER.matchEntire(sentence)?.let { m ->
            val mark = ActionWordings.mark(m.groupValues[2]) ?: return@let
            val subject = m.groupValues[1]
            val objects = if (subject.startsWith("All ") || subject.startsWith("all ")) Objects.Each(Filters.noun(subject.substringAfter(' ')) ?: return@let)
                else fraObjects(subject, context) ?: return@let
            return listOf(Step.Do(Effect.Mark(objects, mark, remove = true)))
        }
        // mkm chunk 05: "If it's suspected, exile it." about the object the sentences before named (a target chosen before, CR 608.2b)
        Mkm.IF_IT_IS_MARKED.matchEntire(sentence)?.let { m ->
            val mark = ActionWordings.mark(m.groupValues[3]) ?: return@let
            val objects = fraObjects(m.groupValues[1], context) ?: return@let
            val then = effect(m.groupValues[4].replaceFirstChar { it.uppercase() }, context) ?: return@let
            // an "Otherwise, …" after it is about the same object, whatever the first branch did to it
            context.it = objects
            val marked = arcanum.api.Condition.ObjectMatches(objects, ObjectFilter.HasStatus(arcanum.api.Status.Marked(mark)))
            return listOf(Step.If(if (m.groupValues[2].isEmpty()) marked else arcanum.api.Condition.Not(marked), then = then))
        }
        // mkm chunk 04: "Exile a card from a graveyard." (not targeted: the controller chooses one in any graveyard as it resolves)
        if (Mkm.EXILE_A_CARD_FROM_A_GRAVEYARD.matches(sentence))
            return listOf(Step.Choose(arcanum.api.Choice.Objects(ObjectFilter.And(listOf(ObjectFilter.Category(arcanum.api.ObjectCategory.Card), ObjectFilter.InZone(Zone.Graveyard))),
                    Value.Fixed(1), Value.Fixed(1)), bind = "chosen", chooser = Players.You),
                Step.Do(Effect.Move(Objects.Bound("chosen"), Destination(Zone.Exile))))
        // mkm chunk 03: "If this creature is a Detective, it becomes a legendary creature named Mileva, the Stalwart, it has base power and
        // toughness 5/5, and it gains "…"" (for good, CR 611.2a; layers 3, 4, 6 and 7b; "becomes a legendary creature" sets its card type,
        // CR 205.1a, and keeps its subtypes)
        Mkm.IF_IS_BECOMES_LEGENDARY_NAMED.matchEntire(sentence)?.let { m ->
            val subject = m.groupValues[3]
            if (!isSelf(subject) && !(subject == "it" && m.groupValues[1].isNotEmpty())) return@let
            if (m.groupValues[1].isNotEmpty() && !isSelf(m.groupValues[1])) return@let
            val granted = Sentences(setOf("this creature", m.groupValues[4])).line(m.groupValues[7])?.takeIf { it !is Ability.Unparsed } ?: return null
            val becomes = Step.Do(Effect.ApplyMechanics(listOf(
                Mechanic.SetTypes(add = listOf(CardType.Creature), addSupertypes = listOf(arcanum.api.Supertype.Legendary), replaceTypes = true),
                Mechanic.SetName(m.groupValues[4]),
                Mechanic.SetPowerToughness(Value.Fixed(m.groupValues[5].toInt()), Value.Fixed(m.groupValues[6].toInt())),
                Mechanic.GainAbilities(listOf(granted))), Affected.Objects(Objects.Self), arcanum.api.Duration.Indefinitely))
            if (m.groupValues[1].isEmpty()) return listOf(becomes)
            val type = m.groupValues[2].takeIf { it in RulesWords.subtypes } ?: return@let
            return listOf(Step.If(arcanum.api.Condition.ObjectMatches(Objects.Self, ObjectFilter.Sub(Subtype(type))), then = listOf(becomes)))
        }
        // mkm chunk 03: "you may cast an instant or sorcery spell from among cards exiled with it" (one of the cards its abilities exiled, cast
        // as this resolves, CR 607.2a, 608.2g); "that spell" afterwards is it
        Mkm.MAY_CAST_FROM_AMONG_EXILED_WITH.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[2]) || it.groupValues[2] == "it" }?.let { m ->
            val kind = Filters.noun(m.groupValues[1]) ?: return null
            val card = Filters.all(kind, ObjectFilter.InZone(Zone.Exile), ObjectFilter.Is(Objects.Remembered(EXILED_WITH)))
            return listOf(Step.Choose(arcanum.api.Choice.Objects(card, Value.Fixed(0), Value.Fixed(1)), bind = "toCast", chooser = Players.You),
                Step.Do(Effect.Cast(Objects.Bound("toCast"), PlayKind.Cast, bind = "cast", caster = Players.You)))
        }
        // mkm chunk 03: "If that spell would be put into a graveyard, put it on the bottom of its owner's library instead." (the spell cast this
        // way, CR 614.1a)
        if (Mkm.IF_THAT_SPELL_WOULD_GRAVEYARD_BOTTOM.matches(sentence)) {
            return listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.Replacement(EventPattern.ZoneChange(ObjectFilter.Is(Objects.Bound("cast")), to = Zone.Graveyard),
                modify = listOf(Modification.ChangeDestination(Destination(Zone.Library, libraryPosition = -1))))), affects = null, duration = arcanum.api.Duration.Indefinitely)))
        }
        // mkm chunk 03: "When this creature dies, you may exile it and collect evidence 4. If you do, return this card to the battlefield tapped."
        // (one cost of two parts, CR 118.12; "this card" is then the exiled card, CR 400.7)
        Mkm.MAY_EXILE_IT_AND_IF_YOU_DO.matchEntire(sentence)?.let { m ->
            val dies = context.event as? EventPattern.ZoneChange ?: return null
            if (dies.to != Zone.Graveyard) return null
            val more = costPart(m.groupValues[1].replaceFirstChar { it.uppercase() }) ?: return null
            val exile = CostPart.Exile(CostObjects.These(Objects.EventObject(arcanum.api.EventRole.After)), from = Zone.Graveyard, postBind = "exiled")
            context.it = Objects.Bound("exiled")
            val then = effect(m.groupValues[2].replaceFirstChar { it.uppercase() }.replace("this card", "it"), context) ?: return null
            return listOf(Step.Pay(Cost(listOf(exile) + more), bind = "paid", payer = Players.You), Step.If(arcanum.api.Condition.Did("paid"), then = then))
        }
        // mkm chunk 03: "Collect evidence 4." as an effect ("you may collect evidence 4", CR 701.59a)
        Mkm.COLLECT_EVIDENCE.matchEntire(sentence)?.let { m ->
            return listOf(Step.Do(Effect.Action(arcanum.api.KeywordAction.CollectEvidence(Value.Fixed(m.groupValues[1].toInt())))))
        }
        // mkm chunk 02: "you may have Lazav become a copy of a creature card exiled with it until end of turn." (one chosen as it resolves, of
        // the cards its abilities exiled, CR 607.2a, 707.2)
        Mkm.MAY_HAVE_BECOME_COPY_OF_EXILED_WITH.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[1]) && (isSelf(it.groupValues[3]) || it.groupValues[3] == "it") }?.let { m ->
            val filter = Filters.all(Filters.noun(m.groupValues[2]) ?: return null, ObjectFilter.InZone(Zone.Exile), ObjectFilter.Is(Objects.Remembered(EXILED_WITH)))
            // "you may have it become a copy of one": a choice of zero or one card
            return listOf(Step.Choose(arcanum.api.Choice.Objects(filter, Value.Fixed(0), Value.Fixed(1)), bind = "copied", chooser = Players.You),
                Step.If(arcanum.api.Condition.NonEmpty("copied"), then = listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.CopyOf(Objects.Bound("copied"))),
                    Affected.Objects(Objects.Self), arcanum.api.Duration.EndOfTurn)))))
        }
        // mkm chunk 02: "Each player who controls the most creatures investigates." (each of them, at once, CR 101.4, 701.16a)
        Mkm.EACH_PLAYER_WHO_INVESTIGATES.matchEntire(sentence)?.let { m ->
            val players = mkmPlayersWho(m.groupValues[1], m.groupValues[2]) ?: return null
            return listOf(Step.ForEach(arcanum.api.Each.Players(Players.Each(players)), "player",
                listOf(Step.Do(Effect.Action(arcanum.api.KeywordAction.Investigate(Value.Fixed(1))))), together = true))
        }
        // mkm chunk 02: "investigate for each opponent who lost life this turn" (CR 701.16a)
        Mkm.INVESTIGATE_FOR_EACH.matchEntire(sentence)?.let { m ->
            val each = m.groupValues[1]
            val count = Mkm.PLAYER_WHO.matchEntire(each)?.let { w -> mkmPlayersWho(w.groupValues[1], w.groupValues[2])?.let { Value.CountPlayers(Players.Each(it)) } }
                ?: Filters.objects(each, self)?.let { Value.Count(it) } ?: return null
            return listOf(Step.Do(Effect.Action(arcanum.api.KeywordAction.Investigate(count))))
        }
        // mkm chunk 02: "Choose any number of target players." (the sentences after it read them as "those players")
        Mkm.CHOOSE_ANY_NUMBER_OF_TARGET.matchEntire(sentence)?.let { m ->
            val name = m.groupValues[1]
            if (context.targets.any { it.name == name }) return null
            context.targets += TargetSlot(name, TargetKind.Players(if (name == "opponents") PlayerFilter.Opponent else PlayerFilter.Any), min = Value.Fixed(0), max = null)
            context.lastPlayer = Players.Target(name)
            return emptyList()
        }
        // mkm chunk 02: "Investigate X times, where X is the total number of creatures those players control." (the chosen players)
        Mkm.INVESTIGATE_X_TIMES_THOSE_PLAYERS_CONTROL.matchEntire(sentence)?.let { m ->
            val those = context.targets.lastOrNull { it.what is TargetKind.Players && it.max == null }?.let { Players.Target(it.name) } ?: return null
            val noun = m.groupValues[1].let { Filters.noun(it) ?: Filters.noun(it.removeSuffix("s")) } ?: return null
            val count = Value.Count(Objects.Each(Filters.all(noun, ObjectFilter.ControlledBy(PlayerFilter.Is(those)))))
            return listOf(Step.Do(Effect.Action(arcanum.api.KeywordAction.Investigate(count))))
        }
        // mkm chunk 02: "you may cast a spell from each opponent's graveyard without paying its mana cost" (at most one card of each opponent's,
        // all chosen first, then cast as this resolves, CR 608.2g, 601.2); "a spell cast this way" afterwards is each of them
        Mkm.MAY_CAST_FROM_EACH_OPPONENTS_GRAVEYARD_FREE.matchEntire(sentence)?.let { m ->
            val kind = if (m.groupValues[1] == "spell") ObjectFilter.Not(ObjectFilter.Type(CardType.Land))
                else Filters.noun(m.groupValues[1].removeSuffix(" spell")) ?: return null
            val opponent = Players.Bound("opponent")
            val card = Filters.all(kind, ObjectFilter.InZone(Zone.Graveyard), ObjectFilter.OwnedBy(PlayerFilter.Is(opponent)))
            return listOf(Step.ForEach(arcanum.api.Each.Players(Players.Each(PlayerFilter.Opponent)), "opponent", listOf(
                Step.Choose(arcanum.api.Choice.Objects(card, Value.Fixed(0), Value.Fixed(1)), bind = "toCast", chooser = Players.You),
                Step.Do(Effect.Cast(Objects.Bound("toCast"), PlayKind.Cast, withoutPaying = true, bind = "cast", caster = Players.You))), together = true))
        }
        // mkm chunk 02: "Tap up to two target creatures and put a stun counter on each of them." (one sentence)
        Sos.TAP_UP_TO_PUT_STUN_ON_EACH.matchEntire(sentence)?.let { m -> return tapUpToStun(m, context) }
        return null
    }

    /** sos chunk 04: "Tap up to two target creatures. Put a stun counter on each of them."; mkm chunk 02: also "… creatures and put a stun
     * counter on each of them." */
    private fun tapUpToStun(m: MatchResult, context: Context): List<Step>? {
        val n = Numbers.count(m.groupValues[1]) ?: return null
        val noun = m.groupValues[2]
        val filter = Filters.noun(noun) ?: Filters.noun(noun.removeSuffix("s")) ?: return null
        val name = Filters.slotName(noun.removeSuffix("s"))
        context.targets += sosSlot(name, filter, min = 0, max = n)
        return listOf(Step.Do(Effect.Tap(Objects.Target(name))), Step.Do(Effect.PutCounters(Objects.Target(name), arcanum.api.CounterKind.Stun, Value.Fixed(1))))
    }

    /** mkm chunk 02: "player who [clause]", "opponent who [clause]" ("controls the most creatures", "lost life this turn", "has more cards in
     * hand than you"), each player tested as [Players.Tested]. */
    private fun mkmPlayersWho(noun: String, clause: String): PlayerFilter? {
        val who = when {
            clause == "lost life this turn" -> PlayerFilter.ThisTurn(EventPattern.LoseLife(PlayerFilter.Any))
            clause == "has more cards in hand than you" -> PlayerFilter.Where(arcanum.api.Condition.Compare(
                Value.HandSize(Players.Tested), arcanum.api.Comparison.Greater, Value.HandSize(Players.You)))
            // "controls the most creatures": as many as any player controls (a tie: each of them)
            clause.startsWith("controls the most ") -> {
                val what = clause.removePrefix("controls the most ")
                val filter = Filters.noun(what) ?: Filters.noun(what.removeSuffix("s")) ?: return null
                val count = Value.Count(Objects.Each(Filters.all(filter, ObjectFilter.ControlledBy(PlayerFilter.Is(Players.Tested)))))
                PlayerFilter.Where(arcanum.api.Condition.Compare(count, arcanum.api.Comparison.AtLeast, Value.GreatestFor(Players.Each(PlayerFilter.Any), count)))
            }
            else -> return null
        }
        return when (noun) { "player" -> who; "opponent" -> PlayerFilter.And(listOf(PlayerFilter.Opponent, who)); else -> null }
    }

    /** mkm: whole lines, tried in [line]. */
    private fun mkmLine(line: String): Ability? {
        // mkm chunk 06: "This Case is a 4/4 Gorgon creature with deathtouch and lifelink in addition to its other types." (CR 205.1b, 613.1d, f, 613.4b)
        Mkm.IS_PT_CREATURE_WITH_IN_ADDITION.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val subtypes = m.groupValues[4].trim().split(' ').filter { it.isNotEmpty() }
                .map { if (it in RulesWords.subtypes) arcanum.api.SubtypeRef.Literal(Subtype(it)) else return null }
            val gains = m.groupValues[5].takeIf { it.isNotEmpty() }?.let { listOf(Mechanic.GainAbilities(keywords(it) ?: return null)) }.orEmpty()
            return Ability.Static(listOf(Mechanic.SetTypes(add = listOf(CardType.Creature), addSubtypes = subtypes),
                Mechanic.SetPowerToughness(Value.Fixed(m.groupValues[2].toInt()), Value.Fixed(m.groupValues[3].toInt()))) + gains, affects = Affected.Objects(Objects.Self))
        }
        // mkm chunk 03: "You may choose not to untap this creature during your untap step." (CR 502.3)
        Mkm.MAY_CHOOSE_NOT_TO_UNTAP.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            return Ability.Static(listOf(Mechanic.MayChooseNotToUntap), affects = Affected.Objects(Objects.Self))
        }
        // mkm chunk 02: "To solve — You control three or more artifacts." (CR 719.3a: "At the beginning of your end step, if [condition] and this
        // Case is not solved, this Case becomes solved.")
        Mkm.TO_SOLVE.matchEntire(line)?.let { m ->
            val condition = Conditions.condition(m.groupValues[1].replaceFirstChar { it.lowercase() }, self) ?: return null
            val solved = arcanum.api.Condition.ObjectMatches(Objects.Self, ObjectFilter.HasStatus(arcanum.api.Status.Marked(arcanum.api.ObjectMark.Solved)))
            return Ability.Triggered(arcanum.api.Trigger.On(EventPattern.StepBegins(arcanum.api.TurnStep.End, PlayerFilter.You)),
                Instructions(steps = listOf(Step.Do(Effect.Mark(Objects.Self, arcanum.api.ObjectMark.Solved)))),
                interveningIf = arcanum.api.Condition.And(listOf(condition, arcanum.api.Condition.Not(solved))))
        }
        // mkm chunk 02: "This spell costs {W}{U} more to cast for each target beyond the first." (the card's "any number of target …", CR 601.2f)
        Mkm.MORE_FOR_EACH_TARGET_BEYOND_THE_FIRST.matchEntire(line)?.let { m ->
            val noun = anyNumberOfTargets ?: return null
            val chosen = if (noun == "players" || noun == "opponents") Value.CountPlayers(Players.Target(noun)) else Value.Count(Objects.Target(noun))
            return Ability.Static(listOf(Mechanic.CostChange(ObjectFilter.Is(Objects.Self), arcanum.api.CostChange.More(ManaCost.parse(m.groupValues[1]) ?: return null,
                Value.Max(listOf(Value.Fixed(0), Value.Difference(chosen, Value.Fixed(1))))))), affects = Affected.Objects(Objects.Self))
        }
        // mkm chunk 01: "Disguise {5}{R}. This cost is reduced by {1} for each instant and sorcery card in your graveyard." (a reduction of the
        // special action's cost, CR 118.7)
        Mkm.DISGUISE_REDUCED_FOR_EACH.matchEntire(line)?.let { m ->
            val cost = ManaCost.parse(m.groupValues[1]) ?: return null
            val per = ManaCost.parse(m.groupValues[2]) ?: return null
            val count = Filters.objects(m.groupValues[3], self)?.let { Value.Count(it) } ?: return null
            return arcanum.api.Keyword.Disguise(Cost.mana(cost), costChange = arcanum.api.CostChange.Less(per, count))
        }
        // mkm chunk 01: "As this creature is turned face up, put four +1/+1 counters on it." (CR 614.1e); "As this creature enters or is turned
        // face up, put X +1/+1 counters on it, where X is …" (also as it enters: counters it enters with, CR 614.1c, 614.12)
        Mkm.AS_ENTERS_OR_TURNED_FACE_UP.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            // "it" is this creature, as in a state trigger
            stateTriggerSelf = true
            val read = try { instructions(m.groupValues[3].replaceFirstChar { it.uppercase() }, itZone = Zone.Battlefield) } finally { stateTriggerSelf = false }
            val steps = read?.takeIf { it.targets.isEmpty() }?.steps ?: return null
            val faceUp = Mechanic.Replacement(EventPattern.TurnedFaceUp(ObjectFilter.Is(Objects.Self)), modify = listOf(Modification.AsTurnedFaceUp(steps)))
            if (m.groupValues[2].isEmpty()) return Ability.Static(listOf(faceUp), affects = Affected.Objects(Objects.Self))
            val put = (steps.singleOrNull() as? Step.Do)?.effect as? Effect.PutCounters
            val entering = if (put != null && put.objects == Objects.Self) Modification.EntersWithCounters(put.kind, put.amount) else Modification.AsEnters(steps)
            return Ability.Static(listOf(Mechanic.Replacement(EventPattern.ZoneChange(ObjectFilter.Is(Objects.Self), to = Zone.Battlefield),
                modify = listOf(entering)), faceUp), affects = Affected.Objects(Objects.Self))
        }
        return null
    }

    // ---- inr

    /** inr: single-sentence effects. */
    private fun inrEffect(sentence: String, context: Context): List<Step>? {
        // inr chunk 09: "For each creature, its controller sacrifices it unless they pay X life." (each controller decides for each of their
        // creatures in turn order, then those not paid for are sacrificed at once, CR 101.4, 118.12a, 119.4)
        Inr.FOR_EACH_CONTROLLER_SACRIFICES_UNLESS_PAYS_LIFE.matchEntire(sentence)?.let { m ->
            val noun = m.groupValues[1]
            val bind = Filters.slotName(noun)
            val each = Objects.Bound(bind)
            val amount = if (m.groupValues[2] == "X") Value.Announced(name = "X") else Value.Fixed(m.groupValues[2].toInt())
            return listOf(Step.ForEach(arcanum.api.Each.Objects(Objects.Each(Filters.noun(noun) ?: return null)), bind, together = true,
                steps = unlessPays(Players.ControllerOf(each), Cost(listOf(CostPart.PayLife(amount))), listOf(Step.Do(Effect.Sacrifice(each))))))
        }
        // inr chunk 08: "any opponent may have it deal 4 damage to them." (each opponent in turn order until one does, CR 101.4; "If a player
        // does, …" reads the outcome)
        Inr.ANY_OPPONENT_MAY_HAVE_DEAL_TO_THEM.matchEntire(sentence)?.takeIf { (it.groupValues[1] == "it" && context.event != null) || isSelf(it.groupValues[1]) }?.let { m ->
            return listOf(Step.Pay(steps = listOf(Step.Do(Effect.DealDamage(arcanum.api.Recipients(players = Players.Bound("payer")),
                Value.Fixed(m.groupValues[2].toInt()), Objects.Self))), payer = Players.Each(PlayerFilter.Opponent), bind = "had", payerBind = "payer"))
        }
        // inr chunk 08: "you may have it deal 4 damage to target creature with flying", "you may have this artifact become a 3/3 white Angel artifact
        // creature with flying until end of turn" (the same effect, if its controller chooses it, CR 608.2d)
        Inr.YOU_MAY_HAVE_SELF.matchEntire(sentence)?.takeIf { ((it.groupValues[1] == "it" && context.event != null) || isSelf(it.groupValues[1])) &&
            !it.groupValues[3].startsWith("that much") }?.let { m ->
            val subject = m.groupValues[1].replaceFirstChar { it.uppercase() }
            effect("$subject ${m.groupValues[2]}s ${m.groupValues[3]}.", context)?.let { return listOf(Step.May(it, player = Players.You)) }
        }
        // inr chunk 08: "Each creature you control that's a Wolf or a Werewolf deals damage equal to its power to that creature." (each one the
        // source of its own damage, all dealt at once, CR 120.3)
        Inr.EACH_DEALS_POWER_TO_THAT.matchEntire(sentence)?.let { m ->
            val filter = Filters.noun(m.groupValues[1])
            val to = if (m.groupValues[3] == "that creature") context.targets.lastOrNull { it.what is TargetKind.Objects }?.let { Objects.Target(it.name) }
                else m.groupValues[3].removePrefix("target ").let { noun -> Filters.noun(noun)?.let { context.target(Filters.slotName(noun), it) } }
            if (filter != null && to != null) {
                val each = Objects.Bound("source")
                val amount = m.groupValues[2].takeIf { it.isNotEmpty() }?.let { Value.Fixed(it.toInt()) }
                    ?: Value.Of(arcanum.api.NumericProperty.Power, each, arcanum.api.Combine.Single)
                return listOf(Step.ForEach(arcanum.api.Each.Objects(Objects.Each(filter)), bind = "source", together = true, steps = listOf(
                    Step.Do(Effect.DealDamage(arcanum.api.Recipients(objects = to), amount, each)))))
            }
        }
        // inr chunk 08: "Exchange target opponent's life total with this creature's toughness." (CR 701.12g)
        Inr.EXCHANGE_LIFE_WITH_SELF_PT.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[2]) }?.let { m ->
            val player = when (m.groupValues[1]) {
                "target opponent's" -> context.targetOpponent()
                "target player's" -> context.targetPlayer()
                else -> Players.You
            }
            val property = if (m.groupValues[3] == "power") arcanum.api.NumericProperty.Power else arcanum.api.NumericProperty.Toughness
            return listOf(Step.Do(Effect.ExchangeLifeWithStat(player, Objects.Self, property)))
        }
        // inr chunk 08: "If it's red, you may cast it this turn." (the card exiled just before, checked as the ability resolves)
        Inr.IF_ITS_COLOR.matchEntire(sentence)?.let { m ->
            val it = context.it
            val color = Tokens.color(m.groupValues[1])
            if (it != null && color != null) effect(m.groupValues[2].replaceFirstChar { c -> c.uppercase() }, context)?.let { then ->
                return listOf(Step.If(arcanum.api.Condition.ObjectMatches(it, ObjectFilter.OfColor(color)), then = then))
            }
        }
        // inr chunk 08: "You may cast red spells from among them this turn." (the cards exiled just before; only as spells of that colour, CR 601.2a)
        Inr.MAY_CAST_COLOR_SPELLS_FROM_AMONG_THEM.matchEntire(sentence)?.let { m ->
            val them = context.them as? Objects.Bound
            val color = Tokens.color(m.groupValues[1])
            if (them != null && color != null) return listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.MayPlay(Zone.Exile, arcanum.api.PlayKind.Cast,
                resultingSpell = ObjectFilter.OfColor(color), holder = PlayerFilter.You)), Affected.Objects(them), arcanum.api.Duration.EndOfTurn)))
        }
        // inr chunk 08: "you may exile another target creature." (linked to "the exiled card" of a later ability, CR 607.2a)
        Inr.EXILE_ANOTHER_TARGET.matchEntire(sentence)?.let { m ->
            Filters.noun(m.groupValues[1])?.let { filter -> return exile(context.target(Filters.slotName(m.groupValues[1]), Filters.all(context.another(), filter))) }
        }
        // inr chunk 07: "Exile all other spells and counter all abilities." (every ability on the Stack, CR 113.1c, 701.6a)
        Inr.AND_COUNTER_ALL_ABILITIES.matchEntire(sentence)?.let { m ->
            val first = effect(m.groupValues[1] + ".", context) ?: return null
            return first + Step.Do(Effect.Counter(Objects.Each(ObjectFilter.Category(arcanum.api.ObjectCategory.StackAbility))))
        }
        // inr chunk 07: "Each player with exactly 13 life loses the game" (CR 104.3e)
        Inr.EACH_PLAYER_WITH_LIFE_LOSES.matchEntire(sentence)?.let { m ->
            val filter = if (m.groupValues[1].isNotEmpty()) PlayerFilter.Life(arcanum.api.Comparison.Equal, Value.Fixed(m.groupValues[1].toInt()))
                else PlayerFilter.Life(if (m.groupValues[3] == "less") arcanum.api.Comparison.AtMost else arcanum.api.Comparison.AtLeast, Value.Fixed(m.groupValues[2].toInt()))
            return listOf(Step.Do(Effect.LoseGame(Players.Each(filter))))
        }
        // inr chunk 07: "create a token that's a copy of that creature" (the creature the trigger or an earlier sentence named, CR 707.2) and
        // "…, except it's 1/1, it's a Spirit in addition to its other types, and it has flying" (CR 707.9b)
        Inr.CREATE_COPY_OF_THAT.matchEntire(sentence)?.let { m ->
            val of = context.it ?: return null
            val except = m.groupValues[1].takeIf { it.isNotEmpty() }?.let { copyExceptions(it) ?: return null }.orEmpty()
            return listOf(Step.Do(Effect.CreateToken(arcanum.api.TokenSpec.CopyOf(of, except), count = Value.Fixed(1), controller = Players.You)))
        }
        // inr chunk 07: "Create a black Zombie creature token with power equal to that card's power and toughness equal to that card's toughness."
        // (CR 111.4: the values are fixed as it is created)
        Inr.CREATE_TOKEN_PT_EQUAL_TO_THAT_CARDS.matchEntire(sentence)?.let { m ->
            val of = context.it ?: return null
            val token = Tokens.defined("a X/X ${m.groupValues[1]} token") ?: return null
            return listOf(Step.Do(Effect.CreateToken(token.copy(power = Value.Of(arcanum.api.NumericProperty.Power, of, arcanum.api.Combine.Single),
                toughness = Value.Of(arcanum.api.NumericProperty.Toughness, of, arcanum.api.Combine.Single)), Value.Fixed(1), Players.You)))
        }
        // inr chunk 06: "Creatures your opponents control attack this turn if able." (a requirement, CR 508.1d)
        Inr.CREATURES_ATTACK_THIS_TURN_IF_ABLE.matchEntire(sentence)?.let { m ->
            val group = Filters.noun(m.groupValues[1].replaceFirstChar { it.lowercase() }) ?: return null
            return listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.MustAttack()), Affected.Objects(Objects.Each(group)), arcanum.api.Duration.EndOfTurn)))
        }
        // inr chunk 04: "You choose from it a nonland card with mana value 3 or less and a card with mana value 4 or greater." (one choice each,
        // from the revealed hand, CR 701.9; the player then discards "those cards")
        Inr.YOU_CHOOSE_FROM_IT_A_AND_B.matchEntire(sentence)?.let { m ->
            val from = context.revealed ?: return null
            val first = Filters.noun(m.groupValues[1].removeArticle() + m.groupValues[2]) ?: return null
            val second = Filters.noun(m.groupValues[3].removeArticle() + m.groupValues[4]) ?: return null
            context.chosen += listOf("chosen", "chosenSecond")
            return listOf(
                Step.Choose(arcanum.api.Choice.Objects(first, Value.Fixed(1), Value.Fixed(1), from = from), bind = "chosen", chooser = Players.You),
                Step.Choose(arcanum.api.Choice.Objects(second, Value.Fixed(1), Value.Fixed(1), from = from), bind = "chosenSecond", chooser = Players.You))
        }
        // inr chunk 04: "That player discards those cards." (the cards chosen just before)
        if (sentence == "That player discards those cards.") {
            val player = context.player ?: return null
            val cards = context.chosen.takeLast(2).takeIf { it.size == 2 }?.map { Objects.Bound(it) } ?: return null
            return listOf(Step.Do(Effect.Discard(player, objects = Objects.Union(cards), count = Value.Fixed(2), filter = ObjectFilter.Any)))
        }
        // inr chunk 01: "add {R} at the beginning of your next main phase this turn." (a delayed trigger that triggers once, this turn, CR 603.7b)
        Inr.ADD_AT_NEXT_MAIN_PHASE_THIS_TURN.matchEntire(sentence)?.let { m ->
            val mana = ManaCost.parse(m.groupValues[1]) ?: return null
            return listOf(Step.Do(Effect.CreateDelayedTrigger(
                arcanum.api.Trigger.On(listOf(EventPattern.StepBegins(arcanum.api.TurnStep.PrecombatMain, PlayerFilter.You),
                    EventPattern.StepBegins(arcanum.api.TurnStep.PostcombatMain, PlayerFilter.You))),
                Instructions(steps = listOf(Step.Do(Effect.AddMana(ManaProduction(ManaKind.Fixed(mana)), players = Players.You)))),
                duration = arcanum.api.Duration.EndOfTurn)))
        }
        // inr chunk 01: "That creature deals damage equal to its power to him." (the earlier creature target; "him" is this planeswalker)
        Inr.THAT_CREATURE_DEALS_POWER_TO_SELF.matchEntire(sentence)?.let {
            val creature = context.targets.lastOrNull { it.what is TargetKind.Objects }?.let { Objects.Target(it.name) } ?: return null
            return listOf(Step.Do(Effect.DealDamage(arcanum.api.Recipients(objects = Objects.Self),
                Value.Of(arcanum.api.NumericProperty.Power, creature, arcanum.api.Combine.Single), creature)))
        }
        // inr chunk 01: "it deals 2 damage to target opponent or planeswalker and 2 damage to up to one target creature that player or that
        // planeswalker's controller controls." (CR 115.1: the second target depends on the first)
        Inr.DEALS_TO_OPPONENT_OR_PW_AND_UP_TO_ONE_CREATURE_THAT_PLAYER_CONTROLS.matchEntire(sentence)?.let { m ->
            if (!isSelf(m.groupValues[1]) && m.groupValues[1] != "it") return null
            val first = rtrTarget(m.groupValues[3], context) ?: return null
            val name = first.target ?: return null
            val controller = PlayerFilter.Or(listOf(PlayerFilter.Is(Players.Target(name)), PlayerFilter.Is(Players.ControllerOf(Objects.Target(name)))))
            context.targets += TargetSlot("creature", TargetKind.Objects(Filters.all(ObjectFilter.Type(CardType.Creature), ObjectFilter.ControlledBy(controller))),
                min = Value.Fixed(0), max = Value.Fixed(1))
            return listOf(Step.Do(Effect.DealDamage(first, Value.Fixed(m.groupValues[2].toInt()), Objects.Self)),
                Step.Do(Effect.DealDamage(arcanum.api.Recipients(objects = Objects.Target("creature")), Value.Fixed(m.groupValues[4].toInt()), Objects.Self)))
        }
        return null
    }

    /** inr: whole multi-sentence effects. */
    private fun inrWhole(text: String, context: Context): List<Step>? {
        // inr chunk 09: "that player copies that spell for each other creature they control that the spell could target. Each copy targets a
        // different one of those creatures." (the caster, CR 707.10d)
        Inr.THAT_PLAYER_COPIES_FOR_EACH_COULD_TARGET.matchEntire(text)?.takeIf { context.event is EventPattern.Cast }?.let { m ->
            val noun = Filters.noun(m.groupValues[2]) ?: return null
            val theirs = Filters.all(*listOfNotNull(context.another().takeIf { m.groupValues[1].isNotEmpty() }, noun,
                ObjectFilter.ControlledBy(PlayerFilter.Is(Players.EventPlayer))).toTypedArray())
            return listOf(Step.Do(Effect.CopySpell(Objects.EventObject(EventRole.Object), controller = Players.EventPlayer, newTargets = false,
                forEachCouldTarget = Objects.Each(theirs))))
        }
        // inr chunk 09: "Separate all permanents target player controls into two piles. That player sacrifices all permanents in the pile of their
        // choice." (you separate, that player chooses, CR 700.3)
        Inr.SEPARATE_PERMANENTS_INTO_PILES_SACRIFICE_CHOSEN.matchEntire(text)?.let { m ->
            val player = if (m.groupValues[1] == "opponent") context.targetOpponent() else context.targetPlayer()
            return listOf(Step.Do(Effect.SeparatePiles(Objects.Each(Filters.all(ObjectFilter.Category(arcanum.api.ObjectCategory.Permanent),
                ObjectFilter.ControlledBy(PlayerFilter.Is(player)))), separator = Players.You, chooser = player, chosenBind = "chosen pile")),
                Step.Do(Effect.Sacrifice(Objects.Bound("chosen pile"))))
        }
        // inr chunk 09: "Search your library for a creature card with mana value X or less[, where X is …]. Put that card onto the battlefield, then
        // shuffle." (one search, the card put where it says, CR 701.23a), then the sentences after it
        Inr.SEARCH_THEN_PUT_THAT_CARD.matchEntire(text)?.let { m ->
            val search = effect("Search your library for ${m.groupValues[1]}, put it ${m.groupValues[2]}, then shuffle.", context) ?: return null
            val rest = m.groupValues[3].takeIf { it.isNotEmpty() }?.let { r -> sentences(r).map { effect(it, context) ?: return null }.flatten() }.orEmpty()
            return search + rest
        }
        // inr chunk 08: "Return target nonland permanent to its owner's hand. Then that player discards a card if you control a Zombie." (that player
        // is the owner; the condition is checked as the spell resolves)
        Inr.RETURN_THEN_THAT_PLAYER_DISCARDS_IF.matchEntire(text)?.let { m ->
            val condition = m.groupValues[2].takeIf { it.isNotEmpty() }?.let { Conditions.condition(it, self) ?: return null }
            val noun = m.groupValues[1]
            val target = context.target(Filters.slotName(noun), Filters.noun(noun) ?: return null)
            val discard = Step.Do(Effect.Discard(Players.OwnerOf(target), Value.Fixed(1), filter = ObjectFilter.Any))
            return listOf(Step.Do(Effect.Move(target, Destination(Zone.Hand))), condition?.let { Step.If(it, then = listOf(discard)) } ?: discard)
        }
        // inr chunk 07: "creatures you control gain first strike until end of turn if a creature you control has first strike. The same is true for
        // flying, deathtouch, …" (each keyword checked as the ability resolves, CR 608.2h, 611.2c)
        Inr.GAIN_IF_ONE_HAS_SAME_FOR.matchEntire(text)?.let { m ->
            val group = Filters.noun(m.groupValues[1].lowercase()) ?: return null
            val names = listOf(m.groupValues[2]) + m.groupValues[4].split(LazyRegexes.AND_LIST)
            return names.map { name ->
                val keyword = OracleParser.keyword(name) as? arcanum.api.Keyword ?: return null
                Step.If(arcanum.api.Condition.Exists(Filters.all(Filters.noun(m.groupValues[3].removeArticle()) ?: return null, ObjectFilter.HasKeyword(keyword.kind)), atLeast = 1),
                    then = listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.GainAbilities(listOf(keyword))), Affected.Objects(Objects.Each(group)),
                        arcanum.api.Duration.EndOfTurn))))
            }
        }
        // inr chunk 07: "Choose up to two target creatures. Until your next turn, whenever either of those creatures deals combat damage, you draw a
        // card." (a delayed trigger about the targets, CR 603.7c)
        Inr.CHOOSE_TARGETS_UNTIL_NEXT_TURN_WHENEVER_DEALS.matchEntire(text)?.let { m ->
            val n = Numbers.count(m.groupValues[1]) ?: return null
            val noun = m.groupValues[2]
            val filter = Filters.noun(noun) ?: return null
            val name = Filters.slotName(noun)
            val (trigger, onlyIf) = trigger("a creature deals ${m.groupValues[3]}") ?: return null
            val event = trigger.events.singleOrNull() as? EventPattern.Damage ?: return null
            if (onlyIf != null) return null
            val theirs = event.copy(source = ObjectFilter.Is(Objects.Target(name)))
            val then = instructions(m.groupValues[4], event = theirs, that = Objects.EventObject(EventRole.Source)) ?: return null
            context.targets += TargetSlot(name, TargetKind.Objects(filter), min = Value.Fixed(0), max = Value.Fixed(n))
            return listOf(Step.Do(Effect.CreateDelayedTrigger(trigger.copy(events = listOf(theirs)), then,
                duration = arcanum.api.Duration.UntilYourNextTurn, repeats = true)))
        }
        // inr chunk 07: "you gain control of target opponent during that player's next turn. After that turn, that player takes an extra turn."
        // (CR 723.1, 500.7)
        Inr.CONTROL_NEXT_TURN_THEN_EXTRA_TURN.matchEntire(text)?.let { m ->
            val slot = if (m.groupValues[1] == "opponent") context.targetOpponent() else context.targetPlayer()
            return listOf(Step.Do(Effect.ControlNextTurn(slot, Players.You, thenExtraTurn = true)))
        }
        // inr chunk 07: "You may put a land card from your hand onto the battlefield tapped. If you do, draw a card and repeat this process."
        // (the whole process again while the player does it, CR 608.2c)
        Inr.MAY_PUT_IF_YOU_DO_REPEAT.matchEntire(text)?.let { m ->
            val put = effect(m.groupValues[1] + ".", context) ?: return null
            // "if you do": a card was chosen and put there (nothing to put is not doing it, CR 608.2c)
            val chosen = (put.firstOrNull() as? Step.Choose)?.bind ?: return null
            val then = effect(m.groupValues[2].replaceFirstChar { it.uppercase() } + ".", context) ?: return null
            val did = arcanum.api.Condition.NonEmpty(chosen)
            return listOf(Step.RepeatWhile(put + Step.If(did, then = then), did))
        }
        // inr chunk 06: "Mill a card. If an instant or sorcery card was milled this way, transform this creature." (CR 701.17a, 701.27a)
        Inr.MILL_IF_MILLED_TRANSFORM.matchEntire(text)?.let { m ->
            val kind = Filters.noun(m.groupValues[2] + " card") ?: return null
            return listOf(Step.Do(Effect.Mill(Players.You, Value.Fixed(Numbers.count(m.groupValues[1]) ?: return null), postBind = "milled")),
                Step.If(arcanum.api.Condition.ObjectMatches(Objects.Bound("milled"), kind), then = listOf(Step.Do(Effect.Transform(Objects.Self)))))
        }
        // inr chunk 03: "Look at the top X cards of your library, where X is the amount of mana spent to cast this spell. Put two of them into
        // your hand and the rest on the bottom of your library in a random order." (CR 107.3, 601.2h)
        Inr.LOOK_TOP_X_PUT_N_REST_BOTTOM_RANDOM.matchEntire(text)?.let { m ->
            val keep = Numbers.count(m.groupValues[1]) ?: return null
            return sosLookPut(Value.Announced(name = "X"), keep, sosBottomRandom) // X by "where X is" (read as announced here)
        }
        // inr chunk 01: "Sacrifice a creature. If you do, search your library for …" (did only if a creature was sacrificed, CR 701.21a)
        Inr.SACRIFICE_A_IF_YOU_DO.matchEntire(text)?.let { m ->
            // "that creature" in the rest is the sacrificed one as it last existed on the battlefield (CR 608.2h); "the sacrificed ..." isn't read here
            val namesIt = Inr.NAMES_THE_SACRIFICED.containsMatchIn(m.groupValues[2])
            if (namesIt && "the sacrificed" in m.groupValues[2]) return null
            val sacrifice = effect(m.groupValues[1] + ".", context) ?: return null
            if (sacrifice.count { it is Step.Do && it.effect is Effect.Sacrifice } != 1) return null
            val bound = sacrifice.map {
                if (it is Step.Do && it.effect is Effect.Sacrifice) Step.Do((it.effect as Effect.Sacrifice).copy(postBind = "sacrificed",
                    preBind = if (namesIt) "sacrificed creature" else null)) else it
            }
            val then = instructions(m.groupValues[2].replaceFirstChar { c -> c.uppercase() },
                that = if (namesIt) Objects.Bound("sacrificed creature") else null)?.takeIf { it.targets.isEmpty() }?.steps ?: return null
            return bound + Step.If(arcanum.api.Condition.Compare(Value.Count(Objects.Bound("sacrificed")), arcanum.api.Comparison.AtLeast, Value.Fixed(1)), then = then)
        }
        // inr chunk 01: "Look at the top two cards of your library. Put one of them into your graveyard."
        Inr.LOOK_TOP_N_PUT_ONE_INTO_GRAVEYARD.matchEntire(text)?.let { m ->
            val n = Numbers.count(m.groupValues[1]) ?: return null
            return listOf(Step.Do(Effect.LookAt(Objects.LibraryCards(Players.You, Value.Fixed(n), fromTop = true), Players.You, bind = "looked")),
                Step.Choose(arcanum.api.Choice.Objects(ObjectFilter.Any, Value.Fixed(1), Value.Fixed(1), from = Objects.Bound("looked")), bind = "chosen", chooser = Players.You),
                Step.Do(Effect.Move(Objects.Bound("chosen"), Destination(Zone.Graveyard))))
        }
        return null
    }

    // ---- inr end

    private fun mshWhole2(text: String, context: Context): List<Step>? {
        // msh chunk 05: "you may put an artifact card from your hand onto the battlefield. If it's an Equipment, attach it to …"
        Msh.MAY_PUT_FROM_HAND_IF_EQUIPMENT_ATTACH.matchEntire(text)?.let { return mshEffect2(text, context) }
        // msh chunk 02: "Exile another target nonland, nontoken permanent. Return that card to the battlefield under its owner's control at
        // the beginning of the next end step." (a delayed trigger, CR 603.7)
        Msh.EXILE_RETURN_AT_NEXT_END_STEP.matchEntire(text)?.let { m ->
            var filter = Filters.noun(m.groupValues[2]) ?: return null
            if (m.groupValues[1].isNotEmpty()) filter = Filters.all(ObjectFilter.Not(ObjectFilter.Is(Objects.Self)), filter)
            val target = context.target(Filters.slotName(m.groupValues[2].removeSuffix(" you own")), filter)
            val exiled = Objects.Bound("exiled")
            // fdn chunk 01: "Exile another target creature you own. Return it to the battlefield under your control at …"
            val controller = if (m.groupValues[3] == "your") Players.You else Players.OwnerOf(exiled)
            return listOf(Step.Do(Effect.Move(target, Destination(Zone.Exile), postBind = "exiled")),
                Step.Do(Effect.CreateDelayedTrigger(arcanum.api.Trigger.On(EventPattern.StepBegins(arcanum.api.TurnStep.End, PlayerFilter.Any)),
                    Instructions(steps = listOf(Step.Do(Effect.Move(exiled, Destination(Zone.Battlefield, controller = controller))))))))
        }
        // msh chunk 06: "Add {U}. This mana can't be spent to cast a nonartifact spell." (CR 106.6)
        Msh.ADD_MANA_CANT_BE_SPENT.matchEntire(text)?.let { m ->
            val kind = mana(m.groupValues[1]) ?: return null
            val spells = Filters.all(ObjectFilter.Category(arcanum.api.ObjectCategory.Spell), Filters.noun(m.groupValues[2]) ?: return null)
            return listOf(Step.Do(Effect.AddMana(ManaProduction(kind, restriction = ObjectFilter.Not(spells)), Players.You)))
        }
        // msh chunk 02: "Target player reveals a number of cards from their hand equal to one plus the number of creature cards in your
        // graveyard. You choose one of them. That player discards that card." (the player chooses which to reveal)
        Msh.REVEALS_NUMBER_YOU_CHOOSE_DISCARDS.matchEntire(text)?.let { m ->
            val player = context.targetPlayer()
            val count = Value.Sum(listOf(Value.Fixed(1), Values.value(m.groupValues[1]) ?: return null))
            return listOf(
                Step.Choose(arcanum.api.Choice.Objects(handOf(player), count, count), bind = "revealed", chooser = player),
                Step.Do(Effect.Reveal(Objects.Bound("revealed"))),
                Step.Choose(arcanum.api.Choice.Objects(ObjectFilter.Any, Value.Fixed(1), Value.Fixed(1), from = Objects.Bound("revealed")), bind = "chosen", chooser = Players.You),
                Step.Do(Effect.Discard(player, Value.Fixed(1), ObjectFilter.Any, objects = Objects.Bound("chosen"))))
        }
        // msh chunk 02: "Gain control of target creature until end of turn. If you control a Villain with greater mana value than that
        // creature, gain control of that creature until the end of your next turn instead. Untap that creature. It gains haste until end of
        // turn."
        Msh.GAIN_CONTROL_VILLAIN_INSTEAD.matchEntire(text)?.let { m ->
            val target = context.target(Filters.slotName(m.groupValues[1]), Filters.noun(m.groupValues[1]) ?: return null)
            val villain = Filters.all(Filters.noun(m.groupValues[2]) ?: return null, ObjectFilter.ControlledBy(PlayerFilter.You),
                ObjectFilter.ManaValue(arcanum.api.Comparison.Greater, mshManaValue(target)))
            val keywords = mshKeywords(m.groupValues[3]) ?: return null
            fun control(duration: arcanum.api.Duration) = Step.Do(Effect.ApplyMechanics(listOf(Mechanic.ControlledBy(Players.You)), Affected.Objects(target), duration))
            return listOf(Step.If(arcanum.api.Condition.Exists(villain, atLeast = 1), then = listOf(control(arcanum.api.Duration.UntilEndOfYourNextTurn)),
                otherwise = listOf(control(arcanum.api.Duration.EndOfTurn))),
                Step.Do(Effect.Untap(target)), mshUntilEndOfTurn(target, Mechanic.GainAbilities(keywords)))
        }
        // msh chunk 07: "Copy it X times. You may choose new targets for the copies." (in this spell's cast trigger, CR 707.10)
        if (Msh.COPY_IT_X_TIMES.matches(text))
            return listOf(Step.Repeat(Value.CastX(of = Objects.Self), listOf(Step.Do(Effect.CopySpell(Objects.Self, Players.You, newTargets = true)))))
        // msh chunk 07: "Exile target Equipment, instant, or sorcery card from your graveyard. Until the end of your next turn, you may play
        // that card."
        Msh.EXILE_FROM_GRAVEYARD_PLAY_UNTIL_NEXT_TURN.matchEntire(text)?.let { m ->
            val target = context.target(Filters.slotName(m.groupValues[1]), mshTargetYourGraveyard(m.groupValues[1]) ?: return null)
            return listOf(Step.Do(Effect.Move(target, Destination(Zone.Exile), postBind = "exiled")),
                Step.Do(Effect.ApplyMechanics(listOf(Mechanic.MayPlay(Zone.Exile, PlayKind.Play, holder = PlayerFilter.You)), Affected.Objects(Objects.Bound("exiled")),
                    arcanum.api.Duration.UntilEndOfYourNextTurn)))
        }
        // msh chunk 09: "Choose target creature you control. Until end of turn, double its power and toughness and it gains trample."
        // (doubling: +X/+X where X is its power and toughness, CR 701.10b)
        Msh.CHOOSE_TARGET_DOUBLE_PT_GAINS.matchEntire(text)?.let { m ->
            val target = context.target(Filters.slotName(m.groupValues[1]), Filters.noun(m.groupValues[1]) ?: return null)
            val keywords = mshKeywords(m.groupValues[2]) ?: return null
            return listOf(mshUntilEndOfTurn(target, Mechanic.ModifyPowerToughness(mshPower(target), mshToughness(target)), Mechanic.GainAbilities(keywords)))
        }
        // msh chunk 08: "Choose up to that many target creatures you control. Put a +1/+1 counter on each of them." (that much life gained)
        Msh.CHOOSE_UP_TO_THAT_MANY_TARGETS_COUNTER.matchEntire(text)?.let { m ->
            val noun = m.groupValues[1]
            val filter = Filters.noun(noun) ?: Filters.noun(noun.replace("creatures", "creature")) ?: return null
            val name = Filters.slotName(noun.replace("creatures", "creature"))
            context.targets += TargetSlot(name, TargetKind.Objects(filter), min = Value.Fixed(0), max = Value.EventAmount)
            return listOf(Step.Do(Effect.PutCounters(Objects.Target(name), Counters.kind(m.groupValues[2]) ?: return null, Value.Fixed(1))))
        }
        // msh chunk 08: "Remove a counter from a creature you control. If you do, draw a card."
        Msh.REMOVE_A_COUNTER_IF_YOU_DO.matchEntire(text)?.let { m ->
            val filter = Filters.noun(m.groupValues[1].removeArticle()) ?: return null
            val then = instructions(mshCap(m.groupValues[2]))?.steps ?: return null
            return listOf(Step.Pay(Cost(listOf(CostPart.RemoveCounters(null, Value.Fixed(1), CostObjects.Choose(filter, count = Value.Fixed(1))))), payer = Players.You,
                mandatory = true, bind = "paid"), Step.If(arcanum.api.Condition.Did("paid"), then = then))
        }
        // msh chunk 10: "You may draw a card for each artifact you control. If you do, each opponent draws a card."
        Msh.MAY_DRAW_FOR_EACH_IF_YOU_DO.matchEntire(text)?.let { m ->
            val count = Value.Count(Filters.objects(m.groupValues[1]) ?: return null)
            val then = instructions(mshCap(m.groupValues[2]))?.steps ?: return null
            return listOf(Step.Pay(steps = listOf(Step.Do(Effect.Draw(Players.You, count))), payer = Players.You, bind = "paid"),
                Step.If(arcanum.api.Condition.Did("paid"), then = then))
        }
        // msh chunk 09: "Choose target opponent and up to one target creature they control. They reveal their hand. You may exile a nonland
        // card from their hand or the chosen creature until Cloak and Dagger leave the battlefield." (CR 610.3)
        Msh.CHOOSE_OPPONENT_AND_CREATURE_EXILE_UNTIL.matchEntire(text)?.takeIf { isSelf(it.groupValues[3]) }?.let { m ->
            val opponent = context.targetOpponent()
            context.targets += mshSlot("creature", Filters.all(Filters.noun(m.groupValues[1]) ?: return null, ObjectFilter.ControlledBy(PlayerFilter.Is(opponent))), min = 0)
            val cards = Filters.all(Filters.noun(m.groupValues[2]) ?: return null, ObjectFilter.InZone(Zone.Hand), ObjectFilter.OwnedBy(PlayerFilter.Is(opponent)))
            return listOf(
                Step.Do(Effect.Reveal(Objects.Each(handOf(opponent)))),
                Step.Choose(arcanum.api.Choice.Objects(ObjectFilter.Any, Value.Fixed(0), Value.Fixed(1),
                    from = Objects.Union(listOf(Objects.Each(cards), Objects.Target("creature")))), bind = "chosen", chooser = Players.You),
                Step.Do(Effect.Move(Objects.Bound("chosen"), Destination(Zone.Exile), untilLeaves = Objects.Self)))
        }
        // msh chunk 09: "You may exile the top card of your library. If that card is a Hero card, Daredevil gets +2/+1 until end of turn.
        // You may play that card this turn."
        Msh.MAY_EXILE_TOP_IF_HERO_PLAY.matchEntire(text)?.takeIf { isSelf(it.groupValues[2]) }?.let { m ->
            val exiled = Objects.Bound("exiled")
            return listOf(
                Step.May(listOf(Step.Do(Effect.Move(Objects.LibraryCards(Players.You, Value.Fixed(1), fromTop = true), Destination(Zone.Exile), postBind = "exiled"))), player = Players.You),
                Step.If(arcanum.api.Condition.ObjectMatches(exiled, Filters.noun(m.groupValues[1]) ?: return null), then = listOf(mshUntilEndOfTurn(Objects.Self,
                    Mechanic.ModifyPowerToughness(Value.Fixed(m.groupValues[3].toInt()), Value.Fixed(m.groupValues[4].toInt()))))),
                Step.Do(Effect.ApplyMechanics(listOf(Mechanic.MayPlay(Zone.Exile, PlayKind.Play, holder = PlayerFilter.You)), Affected.Objects(exiled), arcanum.api.Duration.EndOfTurn)))
        }
        return null
    }

    private fun mshWhole3(text: String, context: Context): List<Step>? {
        // msh chunk 10: "Search your library and/or graveyard for an artifact creature card with mana value X or less and put it onto the
        // battlefield with X additional +1/+1 counters on it. If X is 4 or greater, it gains haste until end of turn. If you search your
        // library this way, shuffle."
        Msh.SEARCH_LIBRARY_AND_GRAVEYARD_X_COUNTERS.matchEntire(text)?.let { m ->
            val x = Value.Announced("X")
            val filter = Filters.all(Filters.noun(m.groupValues[1]) ?: return null, ObjectFilter.ManaValue(arcanum.api.Comparison.AtMost, x))
            val keywords = mshKeywords(m.groupValues[4]) ?: return null
            return listOf(
                Step.Do(Effect.Search(Players.You, filter, max = Value.Fixed(1), zones = listOf(Zone.Library, Zone.Graveyard), bind = "found", searcher = Players.You)),
                Step.Do(Effect.Move(Objects.Bound("found"), Destination(Zone.Battlefield, counters = listOf(arcanum.api.CountersToPut(Counters.kind(m.groupValues[2]) ?: return null, x))),
                    postBind = "put")),
                Step.If(arcanum.api.Condition.Compare(x, arcanum.api.Comparison.AtLeast, Value.Fixed(m.groupValues[3].toInt())),
                    then = listOf(mshUntilEndOfTurn(Objects.Bound("put"), Mechanic.GainAbilities(keywords)))),
                Step.If(arcanum.api.Condition.Searched("found", Zone.Library), then = listOf(Step.Do(Effect.Shuffle(Players.You)))))
        }
        // msh chunk 10: "Return this card from your graveyard to the battlefield with a finality counter on him. Then you may attach an
        // Equipment you control to him."
        Msh.RETURN_SELF_WITH_COUNTER_MAY_ATTACH.matchEntire(text)?.let { m ->
            val equipment = Filters.all(Filters.noun(m.groupValues[2].removeSuffix(" you control")) ?: return null, ObjectFilter.ControlledBy(PlayerFilter.You))
            return listOf(
                Step.Do(Effect.Move(Objects.Self, Destination(Zone.Battlefield, counters = listOf(arcanum.api.CountersToPut(Counters.kind(m.groupValues[1]) ?: return null,
                    Value.Fixed(1)))), postBind = "returned")),
                Step.Choose(arcanum.api.Choice.Objects(equipment, Value.Fixed(0), Value.Fixed(1)), bind = "equipment", chooser = Players.You),
                Step.Do(Effect.Attach(Objects.Bound("equipment"), Recipients(objects = Objects.Bound("returned")))))
        }
        // msh chunk 10: "Exile all creatures. Each player may put any number of creature cards from their hand onto the battlefield. Then put
        // all cards exiled this way into their owners' hands. Exile Worlds Within Worlds."
        Msh.EXILE_ALL_EACH_PLAYER_PUTS_RETURN.matchEntire(text)?.takeIf { isSelf(it.groupValues[3]) }?.let { m ->
            val all = Filters.noun(m.groupValues[1].removeSuffix("s")) ?: Filters.noun(m.groupValues[1]) ?: return null
            val cards = Filters.noun(m.groupValues[2].replace("cards", "card")) ?: return null
            val player = Players.Bound("player")
            val inHand = Filters.all(cards, ObjectFilter.InZone(Zone.Hand), ObjectFilter.OwnedBy(PlayerFilter.Is(player)))
            return listOf(
                Step.Do(Effect.Move(Objects.Each(all), Destination(Zone.Exile), postBind = "exiled")),
                Step.ForEach(arcanum.api.Each.Players(Players.Each(PlayerFilter.Any)), "player", listOf(
                    Step.Choose(arcanum.api.Choice.Objects(inHand, Value.Fixed(0), null), bind = "chosen", chooser = player),
                    Step.Do(Effect.Move(Objects.Bound("chosen"), Destination(Zone.Battlefield)))), together = true),
                Step.Do(Effect.Move(Objects.Bound("exiled"), Destination(Zone.Hand))),
                Step.Do(Effect.Move(Objects.Self, Destination(Zone.Exile))))
        }
        // msh chunk 10: "Look at the top six cards of your library. You may cast a spell from among them with mana value less than or equal
        // to the greatest power among attacking creatures you control without paying its mana cost. Put the rest on the bottom of your
        // library in a random order."
        Msh.LOOK_CAST_GREATEST_POWER_REST_BOTTOM.matchEntire(text)?.let { m ->
            val n = mshN(m.groupValues[1]) ?: return null
            val greatest = Value.Of(arcanum.api.NumericProperty.Power, Filters.objects(m.groupValues[2]) ?: return null, arcanum.api.Combine.Greatest)
            val seen = Objects.Bound("seen")
            return listOf(
                Step.Do(Effect.LookAt(Objects.LibraryCards(Players.You, Value.Fixed(n), fromTop = true), Players.You, bind = "seen")),
                Step.Choose(arcanum.api.Choice.Objects(ObjectFilter.And(listOf(ObjectFilter.Not(ObjectFilter.Type(CardType.Land)),
                    ObjectFilter.ManaValue(arcanum.api.Comparison.AtMost, greatest))), Value.Fixed(0), Value.Fixed(1), from = seen), bind = "chosen", chooser = Players.You),
                Step.Do(Effect.Cast(Objects.Bound("chosen"), PlayKind.Cast, withoutPaying = true, caster = Players.You)),
                Step.Do(Effect.Move(Objects.Except(seen, Objects.Bound("chosen")), Destination(Zone.Library, libraryPosition = -1, randomOrder = true))))
        }
        // msh chunk 10: "Choose another target creature. If that creature has haste and Super-Adaptoid doesn't, put a haste counter on
        // Super-Adaptoid. Do the same for flying, first strike, …, and vigilance." (keyword counters, CR 122.1b)
        Msh.ADAPTOID.matchEntire(text)?.takeIf { isSelf(it.groupValues[2]) }?.let { m ->
            val target = context.target("creature", Filters.all(ObjectFilter.Not(ObjectFilter.Is(Objects.Self)), ObjectFilter.Type(CardType.Creature)))
            val words = listOf(m.groupValues[1]) + m.groupValues[3].split(LazyRegexes.AND_LIST)
            return words.map { word ->
                val keyword = OracleParser.keyword(mshCap(word.trim())) ?: return null
                val has = ObjectFilter.HasKeyword(keyword.kind)
                Step.If(arcanum.api.Condition.And(listOf(arcanum.api.Condition.ObjectMatches(target, has), arcanum.api.Condition.Not(arcanum.api.Condition.ObjectMatches(Objects.Self, has)))),
                    then = listOf(Step.Do(Effect.PutCounters(Objects.Self, arcanum.api.CounterKind.Keyword(keyword.kind), Value.Fixed(1)))))
            }
        }
        // msh chunk 10: "You may pay {2}. If you do, create a token that's a copy of it. If the token isn't a creature, it becomes a 2/2
        // Robot Villain creature in addition to its other types." (the entered artifact, CR 707.2)
        Msh.PAY_CREATE_COPY_IF_NOT_CREATURE.matchEntire(text)?.let { m ->
            val token = Objects.Bound("token")
            val subtypes = m.groupValues[4].split(' ').map { arcanum.api.SubtypeRef.Literal(Subtype(it.takeIf { s -> s in RulesWords.subtypes } ?: return null)) }
            return listOf(
                Step.Pay(Cost.mana(ManaCost.parse(m.groupValues[1]) ?: return null), payer = Players.You, bind = "paid"),
                Step.If(arcanum.api.Condition.Did("paid"), then = listOf(
                    Step.Do(Effect.CreateToken(arcanum.api.TokenSpec.CopyOf(Objects.EventObject(EventRole.After)), Value.Fixed(1), Players.You, bind = "token")),
                    Step.If(arcanum.api.Condition.Not(arcanum.api.Condition.ObjectMatches(token, ObjectFilter.Type(CardType.Creature))), then = listOf(
                        Step.Do(Effect.ApplyMechanics(listOf(Mechanic.SetTypes(add = listOf(CardType.Creature), addSubtypes = subtypes),
                            Mechanic.SetPowerToughness(Value.Fixed(m.groupValues[2].toInt()), Value.Fixed(m.groupValues[3].toInt()))),
                            Affected.Objects(token), arcanum.api.Duration.Indefinitely)))))))
        }
        // msh chunk 10: "Look at the top three cards of your library. You may reveal a Hero card from among them and put it into your hand.
        // Put the rest on the bottom of your library in any order."
        Msh.LOOK_REVEAL_AND_PUT_REST_ANY_ORDER.matchEntire(text)?.let { m ->
            val n = mshN(m.groupValues[1]) ?: return null
            val seen = Objects.Bound("seen")
            return listOf(
                Step.Do(Effect.LookAt(Objects.LibraryCards(Players.You, Value.Fixed(n), fromTop = true), Players.You, bind = "seen")),
                Step.Choose(arcanum.api.Choice.Objects(Filters.noun(m.groupValues[2]) ?: return null, Value.Fixed(0), Value.Fixed(1), from = seen), bind = "chosen", chooser = Players.You),
                Step.Do(Effect.Reveal(Objects.Bound("chosen"))),
                Step.Do(Effect.Move(Objects.Bound("chosen"), Destination(Zone.Hand))),
                Step.Do(Effect.Move(Objects.Except(seen, Objects.Bound("chosen")), Destination(Zone.Library, libraryPosition = -1))))
        }
        // msh chunk 01: "Put two +1/+1 counters on Nick Fury, then look at the top seven cards of your library. You may put a Hero,
        // Equipment, or Vehicle card from among them onto the battlefield. If it's a double-faced card, you may transform it. Put the rest
        // on the bottom of your library in a random order." (transforming only a double-faced card, CR 701.27c)
        Msh.COUNTERS_THEN_LOOK_PUT_TRANSFORM.matchEntire(text)?.takeIf { isSelf(it.groupValues[3]) }?.let { m ->
            val n = mshN(m.groupValues[4]) ?: return null
            val seen = Objects.Bound("seen")
            return listOf(
                Step.Do(Effect.PutCounters(Objects.Self, Counters.kind(m.groupValues[2]) ?: return null, Value.Fixed(mshN(m.groupValues[1]) ?: return null))),
                Step.Do(Effect.LookAt(Objects.LibraryCards(Players.You, Value.Fixed(n), fromTop = true), Players.You, bind = "seen")),
                Step.Choose(arcanum.api.Choice.Objects(Filters.noun(m.groupValues[5]) ?: return null, Value.Fixed(0), Value.Fixed(1), from = seen), bind = "chosen", chooser = Players.You),
                Step.Do(Effect.Move(Objects.Bound("chosen"), Destination(Zone.Battlefield), postBind = "put")),
                Step.May(listOf(Step.Do(Effect.Transform(Objects.Bound("put")))), player = Players.You),
                Step.Do(Effect.Move(Objects.Except(seen, Objects.Bound("chosen")), Destination(Zone.Library, libraryPosition = -1, randomOrder = true))))
        }
        // msh chunk 05: "Draw a card. Until end of turn, Ms. Marvel gains "Ms. Marvel's base power is equal to the number of cards in your
        // hand.""
        Msh.DRAW_THEN_GAINS_QUOTED.matchEntire(text.removeSuffix("."))?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val granted = line(mshSentence(m.groupValues[2])) ?: return null
            return listOf(Step.Do(Effect.Draw(Players.You, Value.Fixed(1))), mshUntilEndOfTurn(Objects.Self, Mechanic.GainAbilities(listOf(granted))))
        }
        // msh chunk 02: "Copy those exiled cards. You may cast up to three of the copies without paying their mana costs." (CR 707.12)
        Msh.BOAST_COPY_CAST.matchEntire(text)?.let { m ->
            val n = mshN(m.groupValues[1]) ?: return null
            return listOf(
                Step.Do(Effect.CopyCard(Objects.Bound("exiled"), Players.You, bind = "copies")),
                Step.Choose(arcanum.api.Choice.Objects(ObjectFilter.Any, Value.Fixed(0), Value.Fixed(n), from = Objects.Bound("copies")), bind = "chosen", chooser = Players.You),
                Step.ForEach(arcanum.api.Each.Objects(Objects.Bound("chosen")), bind = "copy", steps = listOf(
                    Step.Do(Effect.Cast(Objects.Bound("copy"), PlayKind.Cast, withoutPaying = true, caster = Players.You)))))
        }
        // msh chunk 02: "That player exiles cards from the top of their library until they exile a nonland card. You may put a +1/+1 counter
        // on Black Widow. If you don't, you may cast the exiled nonland card until end of turn and mana of any type can be spent to cast
        // that spell."
        Msh.EXILES_UNTIL_NONLAND_MAY_COUNTER_OR_CAST.matchEntire(text)?.takeIf { isSelf(it.groupValues[3]) }?.let { m ->
            val found = Objects.Bound("found")
            return listOf(
                Step.Do(Effect.RevealUntil(Filters.noun(m.groupValues[1]) ?: return null, Players.EventPlayer, Value.Fixed(1), reveal = true, into = Zone.Exile, foundBind = "found")),
                Step.Pay(steps = listOf(Step.Do(Effect.PutCounters(Objects.Self, Counters.kind(m.groupValues[2]) ?: return null, Value.Fixed(1)))), payer = Players.You, bind = "paid"),
                Step.If(arcanum.api.Condition.Not(arcanum.api.Condition.Did("paid")), then = listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.MayPlay(Zone.Exile,
                    PlayKind.Cast, holder = PlayerFilter.You, manaAsAnyColor = true)), Affected.Objects(found), arcanum.api.Duration.EndOfTurn)))))
        }
        // msh chunk 03: "Target opponent exiles the top five cards of their library. You may cast up to two spells from among the exiled
        // cards without paying their mana costs." (CR 608.2g)
        Msh.OPPONENT_EXILES_TOP_MAY_CAST_UP_TO.matchEntire(text)?.let { m ->
            val opponent = context.targetOpponent()
            val n = mshN(m.groupValues[1]) ?: return null
            val upTo = mshN(m.groupValues[2]) ?: return null
            return listOf(
                Step.Do(Effect.Move(Objects.LibraryCards(opponent, Value.Fixed(n), fromTop = true), Destination(Zone.Exile), postBind = "exiled")),
                Step.Choose(arcanum.api.Choice.Objects(ObjectFilter.Not(ObjectFilter.Type(CardType.Land)), Value.Fixed(0), Value.Fixed(upTo), from = Objects.Bound("exiled")),
                    bind = "chosen", chooser = Players.You),
                Step.ForEach(arcanum.api.Each.Objects(Objects.Bound("chosen")), bind = "card", steps = listOf(
                    Step.Do(Effect.Cast(Objects.Bound("card"), PlayKind.Cast, withoutPaying = true, caster = Players.You)))))
        }
        return null
    }

    private fun mshEffect3(sentence: String, context: Context): List<Step>? {
        mshEffect4(sentence, context)?.let { return it }
        // msh chunk 10: "each opponent draws a card"
        LazyRegexes.EACH_OPPONENT_DRAWS.matchEntire(sentence)?.let { m ->
            return listOf(Step.Do(Effect.Draw(Players.Each(PlayerFilter.Opponent), Value.Fixed(mshN(m.groupValues[1]) ?: return null))))
        }
        // msh chunk 03: "you control target opponent during their next turn" (CR 723)
        if (Msh.CONTROL_OPPONENT_NEXT_TURN.matches(sentence)) return listOf(Step.Do(Effect.ControlNextTurn(context.targetOpponent(), Players.You)))
        // msh chunk 10: "Artifact spells you cast this turn cost {1} less to cast." (a rule change for the turn, CR 611.2c)
        Msh.SPELLS_YOU_CAST_THIS_TURN_COST_LESS.matchEntire(sentence)?.let { m ->
            val spells = Filters.noun(m.groupValues[1].replaceFirstChar { it.lowercase() }) ?: return null
            return listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.CostChange(spells, arcanum.api.CostChange.Less(ManaCost.parse(m.groupValues[2]) ?: return null,
                Value.Fixed(1)))), null, arcanum.api.Duration.EndOfTurn)))
        }
        // msh chunk 07: "Take an extra turn after this one." (CR 500.7)
        if (Msh.TAKE_EXTRA_TURN.matches(sentence)) return listOf(Step.Do(Effect.ExtraTurn(Players.You)))
        // msh chunk 04: "Put X +1/+1 counters on Stature." (X as announced, CR 107.3a)
        Msh.PUT_X_COUNTERS_ON.matchEntire(sentence)?.let { m ->
            val objects = mshObjects(m.groupValues[2], context) ?: return null
            return listOf(Step.Do(Effect.PutCounters(objects, Counters.kind(m.groupValues[1]) ?: return null, Value.Announced("X"))))
        }
        // msh chunk 02: "Create a 2/1 black Villain creature token with menace, then creatures you control get +1/+0 until end of turn."
        Msh.CREATE_THEN.matchEntire(sentence)?.let { m ->
            val first = effect(mshSentence(m.groupValues[1]), context) ?: return null
            return first + (effect(mshSentence(m.groupValues[2]), context) ?: return null)
        }
        // msh chunk 07: "Draw a card for each card you've discarded this turn."
        if (Msh.DRAW_FOR_EACH_DISCARDED.matches(sentence))
            return listOf(Step.Do(Effect.Draw(Players.You, Value.EventsThisTurn(EventPattern.Discard(ObjectFilter.Any, PlayerFilter.You), arcanum.api.Measure.Objects))))
        // msh chunk 09: "it fights up to one other target creature", "Target creature you control fights up to one other target creature."
        Msh.FIGHTS_UP_TO_ONE_OTHER.matchEntire(sentence)?.let { m ->
            val first = mshObjects(m.groupValues[1], context) ?: return null
            val firstSlot = (first as? Objects.Target)?.slot
            val name = mshNewSlotName(context, Filters.slotName(m.groupValues[2]))
            val filter = Filters.noun(m.groupValues[2]) ?: return null
            context.targets += if (firstSlot == null) mshSlot(name, Filters.all(ObjectFilter.Not(ObjectFilter.Is(Objects.Self)), filter), min = 0)
                else mshSlot(name, filter, min = 0).copy(distinctFrom = listOf(firstSlot))
            return listOf(Step.Do(Effect.Fight(first, Objects.Target(name))))
        }
        // msh chunk 06: "that player draws a card" at the beginning of a player's upkeep (the active player)
        Msh.THAT_PLAYER_DRAWS.matchEntire(sentence)?.takeIf { context.event is EventPattern.StepBegins }?.let { m ->
            return listOf(Step.Do(Effect.Draw(Players.Active, Value.Fixed(mshN(m.groupValues[1]) ?: return null))))
        }
        // msh chunk 02: "return target creature card from your graveyard to the battlefield tapped and attacking with a finality counter on
        // it" (put onto the battlefield attacking, not declared, CR 508.4)
        Msh.RETURN_TAPPED_AND_ATTACKING_WITH_COUNTER.matchEntire(sentence)?.let { m ->
            val target = context.target(Filters.slotName(m.groupValues[1].removeSuffix(" from your graveyard")),
                mshTargetYourGraveyard(m.groupValues[1].removeSuffix(" from your graveyard")) ?: return null)
            return listOf(Step.Do(Effect.Move(target, Destination(Zone.Battlefield, tapped = true, attacking = arcanum.api.AttackTarget.Chosen,
                counters = listOf(arcanum.api.CountersToPut(Counters.kind(m.groupValues[2]) ?: return null, Value.Fixed(1)))))))
        }
        // msh chunk 02: "attach up to one target Equipment you control to target creature you control" (CR 701.3)
        Msh.ATTACH_UP_TO_ONE_TO_TARGET.matchEntire(sentence)?.let { m ->
            val equipment = Filters.slotName(m.groupValues[1])
            context.targets += mshSlot(equipment, Filters.noun(m.groupValues[1]) ?: return null, min = 0)
            val creature = context.target(Filters.slotName(m.groupValues[2]), Filters.noun(m.groupValues[2]) ?: return null)
            return listOf(Step.Do(Effect.Attach(Objects.Target(equipment), Recipients(objects = creature))))
        }
        // msh chunk 03: "it deals 7 damage divided as you choose among one or two targets" (CR 601.2d)
        Msh.DEALS_DIVIDED_ONE_OR_TWO.matchEntire(sentence)?.let { m ->
            val source = if (m.groupValues[1] == "it" || m.groupValues[1] == "It" || isSelf(m.groupValues[1])) Objects.Self else return null
            context.anyTarget()
            context.targets[context.targets.lastIndex] = context.targets.last().copy(max = Value.Fixed(2), divided = Value.Fixed(m.groupValues[2].toInt()))
            return listOf(Step.Do(Effect.DealDamage(Recipients(target = "any"), Value.DividedShare, source)))
        }
        // msh chunk 07: 'Iron Fist gains "{T}: Iron Fist deals damage equal to his power to any other target" until end of turn.'
        Msh.GAINS_QUOTED_UNTIL_EOT.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val quoted = mshSentence(ungendered(m.groupValues[2], self))
            val granted = line(quoted) ?: return null
            return listOf(mshUntilEndOfTurn(Objects.Self, Mechanic.GainAbilities(listOf(granted))))
        }
        // msh chunk 07: "Iron Fist deals damage equal to his power to any other target", "he deals damage equal to the number of +1/+1
        // counters on him to any other target"
        Msh.DEALS_DAMAGE_EQUAL_TO_ANY_OTHER.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[1]) || it.groupValues[1].lowercase() in setOf("it", "he", "she") }?.let { m ->
            val amount = mshValue(m.groupValues[2]) ?: Values.value(m.groupValues[2]) ?: return null
            return listOf(Step.Do(Effect.DealDamage(mshAnyOtherTarget(context), amount, Objects.Self)))
        }
        // msh chunk 07: "target creature with haste can't be blocked this turn except by creatures with haste" (CR 509.1b)
        Msh.CANT_BE_BLOCKED_EXCEPT_BY.matchEntire(sentence)?.let { m ->
            val target = context.target(Filters.slotName(m.groupValues[1]), Filters.noun(m.groupValues[1]) ?: return null)
            return listOf(mshUntilEndOfTurn(target, Mechanic.CanBeBlockedOnlyBy(Filters.noun(m.groupValues[2]) ?: return null)))
        }
        // msh chunk 06: "enchanted creature gains first strike until end of turn"
        Msh.ATTACHED_GAINS.matchEntire(sentence)?.let { m ->
            return listOf(mshUntilEndOfTurn(Objects.AttachedTo(Objects.Self), Mechanic.GainAbilities(mshKeywords(m.groupValues[1]) ?: return null)))
        }
        // msh chunk 07: "Thor deals damage equal to that spell's mana value to any target." (the spell of the cast trigger, as it is now or
        // last existed, CR 608.2h)
        Msh.DEALS_DAMAGE_EQUAL_SPELL_MANA_VALUE.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            context.anyTarget()
            return listOf(Step.Do(Effect.DealDamage(Recipients(target = "any"), mshManaValue(Objects.EventObject(EventRole.Object)), Objects.Self)))
        }
        // msh chunk 08: "create a Food token or a Treasure token" (the player chooses which)
        Msh.CREATE_TOKEN_OR_TOKEN.matchEntire(sentence)?.let { m ->
            val (a, b) = m.groupValues[1] to m.groupValues[2]
            if (a !in arcanum.api.PredefinedTokens.names || b !in arcanum.api.PredefinedTokens.names) return null
            fun create(name: String) = Step.Do(Effect.CreateToken(arcanum.api.TokenSpec.Predefined(name), Value.Fixed(1), Players.You))
            return listOf(Step.Choose(arcanum.api.Choice.Option(listOf(a, b)), bind = "token", chooser = Players.You),
                Step.If(arcanum.api.Condition.Chose("token", a), then = listOf(create(a)), otherwise = listOf(create(b))))
        }
        // msh chunk 08: "Double target creature's power and toughness until end of turn." (+X/+X, CR 701.10b)
        Msh.DOUBLE_TARGET_PT.matchEntire(sentence)?.let { m ->
            val target = context.target(Filters.slotName(m.groupValues[1]), Filters.noun(m.groupValues[1]) ?: return null)
            return listOf(mshUntilEndOfTurn(target, Mechanic.ModifyPowerToughness(mshPower(target), mshToughness(target))))
        }
        return null
    }

    private fun mshEffect4(sentence: String, context: Context): List<Step>? {
        // msh chunk 19: "tap target creature defending player controls" when the equipped creature attacks: the player it attacks
        if (sentence == "Tap target creature defending player controls." &&
            (context.event as? EventPattern.Attack)?.attacker == ObjectFilter.Is(Objects.AttachedTo(Objects.Self))) {
            val target = context.target("creature", Filters.all(ObjectFilter.Type(CardType.Creature),
                ObjectFilter.ControlledBy(PlayerFilter.Is(Players.DefendingPlayerOf(Objects.AttachedTo(Objects.Self))))))
            return listOf(Step.Do(Effect.Tap(target)))
        }
        // msh chunk 13: "it deals 1 damage to each opponent" in a trigger on the equipped creature: that creature deals it (CR 120.1)
        LazyRegexes.IT_DEALS_DAMAGE_TO_EACH_OPPONENT.matchEntire(sentence)?.let { m ->
            val attached = ObjectFilter.Is(Objects.AttachedTo(Objects.Self))
            val about = when (val event = context.event) {
                is EventPattern.Tap -> event.objects
                is EventPattern.Attack -> event.attacker
                else -> null
            }
            if (about == attached) return listOf(Step.Do(Effect.DealDamage(arcanum.api.Recipients(players = Players.Each(PlayerFilter.Opponent)),
                Value.Fixed(m.groupValues[1].toInt()), Objects.EventObject(EventRole.Object))))
        }
        // msh chunk 08: "For each kind of counter on target permanent or player, give that permanent or player another counter of that kind."
        Msh.ONE_MORE_OF_EACH_KIND.matchEntire(sentence)?.let { m ->
            if (m.groupValues[1] != "permanent or player") return null
            context.targets += TargetSlot("target", TargetKind.Either(ObjectFilter.Category(arcanum.api.ObjectCategory.Permanent), PlayerFilter.Any),
                min = Value.Fixed(1), max = Value.Fixed(1))
            return listOf(Step.Do(Effect.OneMoreCounterOfEachKind(Recipients(target = "target"))))
        }
        // msh chunk 08: "Target player gains 2 life, then searches their library for a basic land card, puts it onto the battlefield tapped,
        // then shuffles." (that player does it all, CR 701.23)
        Msh.TARGET_PLAYER_GAINS_SEARCHES.matchEntire(sentence)?.let { m ->
            val player = context.targetPlayer()
            val each = Players.Bound("player")
            return listOf(Step.ForEach(arcanum.api.Each.Players(player), "player", listOf(
                Step.Do(Effect.GainLife(each, Value.Fixed(m.groupValues[1].toInt()))),
                Step.Do(Effect.Search(each, Filters.noun(m.groupValues[2]) ?: return null, max = Value.Fixed(1), zones = listOf(Zone.Library), bind = "found", searcher = each)),
                Step.Do(Effect.Move(Objects.Bound("found"), Destination(Zone.Battlefield, tapped = true))),
                Step.Do(Effect.Shuffle(each))), together = true))
        }
        // msh chunk 08: "Put a +1/+1 counter on up to one target creature."
        Msh.PUT_COUNTER_ON_UP_TO_ONE.matchEntire(sentence)?.let { m ->
            val name = mshNewSlotName(context, Filters.slotName(m.groupValues[2]))
            context.targets += mshSlot(name, Filters.noun(m.groupValues[2]) ?: return null, min = 0)
            return listOf(Step.Do(Effect.PutCounters(Objects.Target(name), Counters.kind(m.groupValues[1]) ?: return null, Value.Fixed(1))))
        }
        // msh chunk 09: "The next red or green creature spell you cast this turn can be cast without paying its mana cost." (CR 611.2f;
        // an alternative cost of {0} for that spell, CR 118.9)
        Msh.NEXT_SPELL_WITHOUT_PAYING.matchEntire(sentence)?.let { m ->
            val spells = Filters.all(Filters.noun(m.groupValues[1] + " spell") ?: return null, ObjectFilter.ControlledBy(PlayerFilter.You))
            return listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.AlternativeCost(cost = Cost.mana(ManaCost.parse("{0}")!!))),
                Affected.NextSpells(spells, 1), arcanum.api.Duration.EndOfTurn)))
        }
        // msh chunk 09: "At the beginning of your first main phase, until your next turn, Absorbing Man becomes a copy of up to one target
        // artifact, non-Aura enchantment, or land, except his name is Absorbing Man, he's a legendary 4/4 Human Villain creature in addition to
        // his other types, and he has vigilance." (layer 1 with exceptions, CR 707.9b)
        Msh.BECOMES_COPY_EXCEPT_PT_IN_ADDITION.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val subtypes = m.groupValues[6].split(' ').map { arcanum.api.SubtypeRef.Literal(Subtype(it.takeIf { s -> s in RulesWords.subtypes } ?: return null)) }
            val keywords = mshKeywords(m.groupValues[7]) ?: return null
            context.targets += mshSlot("target", mshCopyCandidates(m.groupValues[2]) ?: return null, min = 0)
            return listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.CopyOf(Objects.Target("target"), except = listOf(
                arcanum.api.CopyException.Name(m.groupValues[3]),
                arcanum.api.CopyException.Types(add = listOf(CardType.Creature), addSubtypes = subtypes, addSupertypes = listOf(Supertype.Legendary)),
                arcanum.api.CopyException.PowerToughness(m.groupValues[4].toInt(), m.groupValues[5].toInt()),
                arcanum.api.CopyException.AddAbilities(keywords)))), Affected.Objects(Objects.Self), arcanum.api.Duration.UntilYourNextTurn)))
        }
        Msh.BECOMES_COPY_EXCEPT_REPLACED.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val subtypes = m.groupValues[4].split(' ').map { arcanum.api.SubtypeRef.Literal(Subtype(it.takeIf { s -> s in RulesWords.subtypes } ?: return null)) }
            context.targets += mshSlot("target", mshCopyCandidates(m.groupValues[2]) ?: return null, min = 0)
            return listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.CopyOf(Objects.Target("target"), except = listOf(
                arcanum.api.CopyException.Name(m.groupValues[3]),
                arcanum.api.CopyException.Types(add = listOf(CardType.Creature), addSubtypes = subtypes, addSupertypes = listOf(Supertype.Legendary),
                    replaceSubtypes = true)))), Affected.Objects(Objects.Self), arcanum.api.Duration.UntilYourNextTurn)))
        }
        // msh chunk 09: 'create a 1/1 red Alien creature token with haste and "This token attacks each combat if able."'
        LazyRegexes.CREATE_TOKENS_WITH.matchEntire(sentence)?.takeIf { Tokens.spec(it.groupValues[1]) == null }?.let { m ->
            val (count, token) = mshToken(m.groupValues[1]) ?: return@let
            return listOf(Step.Do(Effect.CreateToken(token, Value.Fixed(count), Players.You, bind = "token")))
        }
        // msh chunk 09: "Put a +1/+1 counter on it for each invasion counter on this enchantment, then put an invasion counter on this
        // enchantment." (it: the token just created)
        Msh.PUT_COUNTER_ON_IT_FOR_EACH_THEN.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[3]) && isSelf(it.groupValues[5]) }?.let { m ->
            val token = Objects.Bound("token")
            return listOf(
                Step.Do(Effect.PutCounters(token, Counters.kind(m.groupValues[1]) ?: return null,
                    Value.Of(arcanum.api.NumericProperty.Counters(Counters.kind(m.groupValues[2]) ?: return null), Objects.Self, arcanum.api.Combine.Single))),
                Step.Do(Effect.PutCounters(Objects.Self, Counters.kind(m.groupValues[4]) ?: return null, Value.Fixed(1))))
        }
        // msh chunk 08: "Create that many 1/1 green Insect creature tokens." (the number of counters removed, announced, CR 601.2f)
        Msh.CREATE_THAT_MANY.matchEntire(sentence)?.takeIf { announcedX }?.let { m -> // msh: X announced by "Remove any number of" too
            val token = Tokens.defined("a " + m.groupValues[1] + " token") ?: return null
            return listOf(Step.Do(Effect.CreateToken(token, Value.Announced("X"), Players.You)))
        }
        // msh chunk 09: "This Saga deals 2 damage to each non-Villain creature and each opponent."
        Msh.DEALS_TO_EACH_AND_EACH_OPPONENT.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            return listOf(Step.Do(Effect.DealDamage(Recipients(objects = Objects.Each(Filters.noun(m.groupValues[3]) ?: return null), players = Players.Each(PlayerFilter.Opponent)),
                Value.Fixed(m.groupValues[2].toInt()), Objects.Self)))
        }
        // msh chunk 09: "Create a Treasure token for each Villain you control."
        Msh.CREATE_TOKEN_FOR_EACH.matchEntire(sentence)?.let { m ->
            if (m.groupValues[1] !in arcanum.api.PredefinedTokens.names) return null
            return listOf(Step.Do(Effect.CreateToken(arcanum.api.TokenSpec.Predefined(m.groupValues[1]), Value.Count(Filters.objects(m.groupValues[2]) ?: return null), Players.You)))
        }
        // msh chunk 09: "until end of turn, creatures you control with toughness greater than their power assign combat damage equal to their
        // toughness rather than their power" (CR 510.1c)
        Msh.ASSIGN_DAMAGE_BY_TOUGHNESS.matchEntire(sentence)?.let { m ->
            val noun = m.groupValues[1].replace("creatures", "creature").replace("their power", "its power")
            return listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.AssignsDamageByToughness), Affected.Objects(Filters.objects(noun) ?: return null),
                arcanum.api.Duration.EndOfTurn)))
        }
        // msh chunk 09: "until end of turn, Moon Girl and Devil Dinosaur's base power and toughness become 6/6 and they gain trample"
        Msh.BASE_PT_BECOME_THEY_GAIN.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            return listOf(mshUntilEndOfTurn(Objects.Self, Mechanic.SetPowerToughness(Value.Fixed(m.groupValues[2].toInt()), Value.Fixed(m.groupValues[3].toInt())),
                Mechanic.GainAbilities(mshKeywords(m.groupValues[4]) ?: return null)))
        }
        // msh chunk 09: "those creatures gain flying until end of turn" (the creatures the cast spell targets)
        Msh.THOSE_CREATURES_GAIN.matchEntire(sentence)?.takeIf { context.event is EventPattern.Cast }?.let { m ->
            val targeted = Filters.all(ObjectFilter.Type(CardType.Creature), ObjectFilter.TargetedBy(Objects.EventObject(EventRole.Object)))
            return listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.GainAbilities(mshKeywords(m.groupValues[1]) ?: return null)), Affected.Objects(Objects.Each(targeted)),
                arcanum.api.Duration.EndOfTurn)))
        }
        // msh chunk 09: "Gain control of up to two target creatures with total mana value 6 or less for as long as this Saga remains on the
        // battlefield."
        Msh.GAIN_CONTROL_TOTAL_MANA_VALUE.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[4]) }?.let { m ->
            val noun = m.groupValues[2]
            val filter = Filters.noun(noun) ?: Filters.noun(noun.replace("creatures", "creature")) ?: return null
            val name = Filters.slotName(noun.replace("creatures", "creature"))
            context.targets += TargetSlot(name, TargetKind.Objects(filter), min = Value.Fixed(0), max = Value.Fixed(mshN(m.groupValues[1]) ?: return null),
                totalAtMost = arcanum.api.Choice.TotalLimit(arcanum.api.NumericProperty.ManaValue, Value.Fixed(m.groupValues[3].toInt())))
            return listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.ControlledBy(Players.You)), Affected.Objects(Objects.Target(name)),
                arcanum.api.Duration.UntilLeaves(Objects.Self))))
        }
        // msh chunk 09: "Choose odd or even." / "Destroy each other creature with mana value of the chosen quality." (zero is even)
        if (Msh.CHOOSE_ODD_OR_EVEN.matches(sentence))
            return listOf(Step.Choose(arcanum.api.Choice.Option(listOf("odd", "even")), bind = "quality", chooser = Players.You))
        Msh.DESTROY_EACH_OF_CHOSEN_QUALITY.matchEntire(sentence)?.let { m ->
            val odd = arcanum.api.Condition.Odd(mshManaValue(Objects.Tested))
            val quality = ObjectFilter.Where(arcanum.api.Condition.Or(listOf(
                arcanum.api.Condition.And(listOf(arcanum.api.Condition.Chose("quality", "odd"), odd)),
                arcanum.api.Condition.And(listOf(arcanum.api.Condition.Chose("quality", "even"), arcanum.api.Condition.Not(odd))))))
            return listOf(Step.Do(Effect.Destroy(Objects.Each(Filters.all(Filters.noun(m.groupValues[1]) ?: return null, quality)))))
        }
        // msh chunk 10: '{2}: If this Equipment isn't a creature, it becomes a 0/0 Construct Hero artifact creature with flying and "This
        // creature gets +1/+1 for each artifact you control" until end of turn.'
        Msh.IF_NOT_CREATURE_BECOMES.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val subtypes = m.groupValues[4].split(' ').map { arcanum.api.SubtypeRef.Literal(Subtype(it.takeIf { s -> s in RulesWords.subtypes } ?: return null)) }
            val quoted = Sentences(setOf("this creature", "This creature")).line(mshSentence(m.groupValues[6])) ?: return null
            val keyword = OracleParser.keyword(mshCap(m.groupValues[5])) ?: return null
            return listOf(Step.If(arcanum.api.Condition.Not(arcanum.api.Condition.ObjectMatches(Objects.Self, ObjectFilter.Type(CardType.Creature))), then = listOf(
                mshUntilEndOfTurn(Objects.Self, Mechanic.SetTypes(add = listOf(CardType.Artifact, CardType.Creature), addSubtypes = subtypes),
                    Mechanic.SetPowerToughness(Value.Fixed(m.groupValues[2].toInt()), Value.Fixed(m.groupValues[3].toInt())), Mechanic.GainAbilities(listOf(keyword, quoted))))))
        }
        return null
    }
    // ---- msh end
    // ---- sos: Secrets of Strixhaven
    private fun sosSlot(name: String, filter: ObjectFilter, min: Int = 1, max: Int? = 1) =
        TargetSlot(name, TargetKind.Objects(filter), min = Value.Fixed(min), max = max?.let { Value.Fixed(it) })
    private fun sosSentence(text: String) = text.replaceFirstChar { it.uppercase() }.let { if (it.endsWith(".")) it else "$it." }
    private fun sosUntilEndOfTurn(objects: Objects, vararg mechanics: Mechanic) =
        Step.Do(Effect.ApplyMechanics(mechanics.toList(), Affected.Objects(objects), arcanum.api.Duration.EndOfTurn))
    private fun sosPower(of: Objects) = Value.Of(arcanum.api.NumericProperty.Power, of, arcanum.api.Combine.Single)
    private val sosSelfOnly get() = Affected.Objects(Objects.Self)
    private val sosP1P1 get() = arcanum.api.CounterKind.PowerToughness(1, 1)
    private fun sosYourGraveyard(filter: ObjectFilter) = Filters.all(filter, ObjectFilter.InZone(Zone.Graveyard), ObjectFilter.OwnedBy(PlayerFilter.You))
    private fun sosKeywords(text: String): List<Ability>? = text.split(LazyRegexes.AND_LIST).map { OracleParser.keyword(it.trim()) ?: return null }
    /** A condition only the sos wordings read ("five or more mana was spent to cast that spell"), so the general rules aren't shadowed. */
    private fun sosCondition(text: String): arcanum.api.Condition? = SosPhrases.condition(text, self)
    /** The steps of "look at the top [n] cards; put [keep] into your hand and the rest [rest]" (CR 401.4: the rest in any or a random order). */
    private fun sosLookPut(count: Value, keep: Int, rest: Destination, keepFilter: ObjectFilter = ObjectFilter.Any): List<Step> = listOf(
        Step.Do(Effect.LookAt(Objects.LibraryCards(Players.You, count, fromTop = true), Players.You, bind = "looked")),
        Step.Choose(arcanum.api.Choice.Objects(keepFilter, Value.Fixed(keep), Value.Fixed(keep), from = Objects.Bound("looked")), bind = "chosen", chooser = Players.You),
        Step.Do(Effect.Move(Objects.Bound("chosen"), Destination(Zone.Hand))),
        Step.Do(Effect.Move(Objects.Except(Objects.Bound("looked"), Objects.Bound("chosen")), rest)))
    private val sosBottomAnyOrder get() = Destination(Zone.Library, libraryPosition = -1)
    private val sosBottomRandom get() = Destination(Zone.Library, libraryPosition = -1, randomOrder = true)

    /** sos: values that name this card ("1 plus the number of cards named Ancestral Anger in your graveyard"). */
    private fun sosValue(text: String, event: EventPattern?): Value? {
        // sos chunk 01: "the number of colors of mana spent to cast it" in a cast trigger: the spell cast
        if (text == "the number of colors of mana spent to cast it" && event is EventPattern.Cast)
            return Value.ManaSpent(distinctColors = true, of = Objects.EventObject(EventRole.Object))
        Sos.PLUS_NAMED_IN_GRAVEYARD.matchEntire(text)?.takeIf { isSelf(it.groupValues[2]) }?.let { m ->
            return Value.Sum(listOf(Value.Fixed(m.groupValues[1].toInt()),
                Value.Count(Objects.Each(sosYourGraveyard(ObjectFilter.Named(m.groupValues[2]))))))
        }
        return null
    }

    /** sos: whole lines read before the other rules. */
    private fun sosLine(line: String): Ability? {
        // sos chunk 01: "This creature enters with a +1/+1 counter on it for each color of mana spent to cast it." (converge, CR 614.1c)
        Sos.ENTERS_WITH_COUNTER_FOR_EACH_COLOR.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val kind = Counters.kind(m.groupValues[2]) ?: return null
            return Ability.Static(listOf(Mechanic.Replacement(EventPattern.ZoneChange(ObjectFilter.Is(Objects.Self), to = Zone.Battlefield),
                modify = listOf(Modification.EntersWithCounters(kind, Value.ManaSpent(distinctColors = true, of = Objects.Self))))), affects = sosSelfOnly)
        }
        // sos chunk 13: "Grandeur — Discard another card named Page, Loose Leaf: [effect]" (an ability word; the name holds a comma)
        Sos.GRANDEUR.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val named = Filters.all(ObjectFilter.Named(m.groupValues[1]), ObjectFilter.Not(ObjectFilter.Is(Objects.Self)))
            val instructions = instructions(m.groupValues[2]) ?: return null
            return Ability.Activated(Cost(listOf(CostPart.Discard(CostObjects.Choose(named, Value.Fixed(1))))), instructions,
                arcanum.api.ActivationRules(timing = arcanum.api.Timing.Any, activatedBy = PlayerFilter.You), abilityWord = "Grandeur")
        }
        // sos chunk 13: 'Lands you control have "{T}: Add two mana of any one color. Spend this mana only to cast instant and sorcery spells."'
        Sos.LANDS_HAVE_QUOTED.matchEntire(line)?.let { m ->
            val objects = Filters.noun(m.groupValues[1].replaceFirstChar { it.lowercase() }) ?: return null
            val granted = sosQuotedAbility(m.groupValues[2]) ?: return null
            return Ability.Static(listOf(Mechanic.GainAbilities(listOf(granted))), affects = Affected.Objects(Objects.Each(objects)))
        }
        // sos chunk 11: "When this land enters, choose a land card name." (kept on it for its other abilities, CR 607.2a)
        Sos.WHEN_ENTERS_CHOOSE_CARD_NAME.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val filter = Filters.noun(m.groupValues[2] + " card") ?: return null
            return Ability.Triggered(arcanum.api.Trigger.On(EventPattern.ZoneChange(ObjectFilter.Is(Objects.Self), to = Zone.Battlefield)), Instructions(steps = listOf(
                Step.Choose(arcanum.api.Choice.CardName(filter), bind = CHOSEN_NAME, remember = true, chooser = Players.You))))
        }
        // sos chunk 11: 'Lands with the chosen name have "{T}: Add {C}."' (the name chosen as it entered, CR 607.2a)
        Sos.LANDS_WITH_CHOSEN_NAME_HAVE.matchEntire(line)?.let { m ->
            val objects = Filters.noun(m.groupValues[1].replaceFirstChar { it.lowercase() }.removeSuffix("s")) ?: return null
            val granted = sosQuotedAbility(m.groupValues[2]) ?: return null
            return Ability.Static(listOf(Mechanic.GainAbilities(listOf(granted))),
                affects = Affected.Objects(Objects.Each(Filters.all(objects, ObjectFilter.RememberedName(CHOSEN_NAME)))))
        }
        return null
    }

    /** sos: a quoted ability given to other objects ('"{T}: Add {C}."'). */
    private fun sosQuotedAbility(text: String): Ability? {
        val inner = Sentences(setOf("this land", "this creature", "this permanent"))
        // sos chunk 13: "{T}: Add two mana of any one color. Spend this mana only to cast instant and sorcery spells." (CR 106.6)
        if (Sos.ADD_TWO_MANA_ANY_ONE_COLOR_SPEND_ONLY.matches(text))
            return Ability.Activated(Cost(listOf(CostPart.TapSelf)), Instructions(steps = listOf(Step.Do(Effect.AddMana(ManaProduction(
                ManaKind.Choose(amount = Value.Fixed(2)), restriction = Filters.all(ObjectFilter.Category(arcanum.api.ObjectCategory.Spell),
                    ObjectFilter.Or(listOf(ObjectFilter.Type(CardType.Instant), ObjectFilter.Type(CardType.Sorcery))))), Players.You)))),
                arcanum.api.ActivationRules(timing = arcanum.api.Timing.Any, activatedBy = PlayerFilter.You))
        return inner.multi(text)?.singleOrNull() ?: inner.line(text)
    }

    /** sos: static abilities, tried first in [static]. */
    private fun sosStatic(line: String): Ability? {
        // sos chunk 10: "This spell can't be copied." (CR 707.10)
        if (Sos.CANT_BE_COPIED.matches(line)) return Ability.Static(listOf(Mechanic.CantBeCopied), affects = sosSelfOnly)
        // sos chunk 10: "Instant and sorcery spells you cast from your hand have cascade.", "Each instant and sorcery spell you cast has casualty 1.",
        // "Instant and sorcery spells you cast have storm." (a spell has them from the moment it is cast, CR 601.2a, 702.85a)
        Sos.SPELLS_HAVE_KEYWORD.matchEntire(line)?.let { m ->
            val keywords = sosKeywords(m.groupValues[2]) ?: return null
            val spells = Filters.all(ObjectFilter.Or(listOf(ObjectFilter.Type(CardType.Instant), ObjectFilter.Type(CardType.Sorcery))),
                ObjectFilter.Category(arcanum.api.ObjectCategory.Spell), ObjectFilter.ControlledBy(PlayerFilter.You))
            val cast = if (m.groupValues[1].endsWith("from your hand")) Filters.all(spells, ObjectFilter.WasCast(from = Zone.Hand)) else spells
            return Ability.Static(listOf(Mechanic.GainAbilities(keywords)), affects = Affected.Objects(Objects.Each(cast)))
        }
        // sos chunk 10: "Each instant and sorcery card in your hand has miracle {2}." (CR 702.94a)
        Sos.CARDS_IN_HAND_HAVE_KEYWORD.matchEntire(line)?.let { m ->
            val cards = Filters.noun(m.groupValues[1] + " card") ?: return null
            val keywords = sosKeywords(m.groupValues[2]) ?: return null
            return Ability.Static(listOf(Mechanic.GainAbilities(keywords)), affects = Affected.Objects(Objects.Each(
                Filters.all(cards, ObjectFilter.InZone(Zone.Hand), ObjectFilter.OwnedBy(PlayerFilter.You)))))
        }
        // sos chunk 10: "Once during each of your turns, you may cast an instant or sorcery spell from your hand without paying its mana
        // cost." (CR 601.2a, 118.9)
        Sos.ONCE_EACH_TURN_CAST_FREE.matchEntire(line)?.let { m ->
            val cards = Filters.noun(m.groupValues[1].removeSuffix(" spell") + " card") ?: return null
            return Ability.Static(listOf(Mechanic.MayPlay(Zone.Hand, PlayKind.Cast, withoutPaying = true, perTurn = 1, holder = PlayerFilter.You)),
                affects = Affected.Objects(Objects.Each(Filters.all(cards, ObjectFilter.InZone(Zone.Hand), ObjectFilter.OwnedBy(PlayerFilter.You)))),
                condition = arcanum.api.Condition.YourTurn)
        }
        // sos chunk 09: "As long as there are five or more growth counters on this enchantment, creatures you control get +3/+3."
        Sos.AS_LONG_AS_N_COUNTERS_GROUP_GETS.matchEntire(line)?.takeIf { isSelf(it.groupValues[3]) }?.let { m ->
            val n = Numbers.count(m.groupValues[1]) ?: return null
            val kind = Counters.kind(m.groupValues[2]) ?: arcanum.api.CounterKind.Named(m.groupValues[2])
            val group = Filters.noun(m.groupValues[4]) ?: return null
            return Ability.Static(listOf(Mechanic.ModifyPowerToughness(ptChange(m.groupValues[5]) ?: return null, ptChange(m.groupValues[6]) ?: return null)),
                affects = Affected.Objects(Objects.Each(group)), condition = arcanum.api.Condition.ObjectMatches(Objects.Self, ObjectFilter.HasCounter(kind, atLeast = n)))
        }
        // sos chunk 08: "As an additional cost to cast this spell, pay X life." (X announced as it is cast, CR 601.2b, 107.3)
        if (line == "As an additional cost to cast this spell, pay X life.")
            return Ability.Static(listOf(Mechanic.AdditionalCost(cost = Cost(listOf(CostPart.PayLife(Value.Announced(name = "X")))))), affects = sosSelfOnly)
        return null
    }

    /** sos: lines that are two abilities. */
    private fun sosMulti(line: String): List<Ability>? {
        // sos chunk 04: "This creature enters with a number of stun counters on it equal to three minus X. If X is 2 or less, it enters
        // tapped." (two replacements, CR 614.1c; X is the X it was cast with, CR 107.3m)
        Sos.ENTERS_WITH_STUN_THREE_MINUS_X.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val n = Numbers.count(m.groupValues[2]) ?: return null
            val enters = EventPattern.ZoneChange(ObjectFilter.Is(Objects.Self), to = Zone.Battlefield)
            val x = Value.CastX(of = Objects.Self)
            return listOf(
                Ability.Static(listOf(Mechanic.Replacement(enters, modify = listOf(Modification.EntersWithCounters(arcanum.api.CounterKind.Stun,
                    Value.Max(listOf(Value.Fixed(0), Value.Difference(Value.Fixed(n), x))))))), affects = sosSelfOnly),
                Ability.Static(listOf(Mechanic.Replacement(enters, modify = listOf(Modification.EntersTapped))), affects = sosSelfOnly,
                    condition = arcanum.api.Condition.Compare(x, arcanum.api.Comparison.AtMost, Value.Fixed(m.groupValues[3].toInt()))))
        }
        return null
    }

    /** sos: trigger events, tried first in [trigger]. */
    private fun sosTrigger(events: String): arcanum.api.Trigger.On? {
        // sos chunk 10: "you cast a spell with {X} in its mana cost" (CR 107.3)
        if (Sos.CAST_SPELL_WITH_X.matches(events)) return arcanum.api.Trigger.On(EventPattern.Cast(ObjectFilter.XInManaCost, PlayerFilter.You))
        // sos chunk 10: "you cast a spell you don't own" (CR 108.3)
        if (Sos.CAST_SPELL_YOU_DONT_OWN.matches(events))
            return arcanum.api.Trigger.On(EventPattern.Cast(ObjectFilter.Not(ObjectFilter.OwnedBy(PlayerFilter.You)), PlayerFilter.You))
        return null
    }

    /** sos: sentences that change the steps before them, tried first in [modify]. */
    private fun sosModify(sentence: String, steps: List<Step>, context: Context): List<Step>? {
        // sos chunk 02: "If five or more mana was spent to cast that spell, this creature gets +2/+2 until end of turn instead." (opus): the
        // sentence before happens only if the condition is false
        Sos.IF_INSTEAD.matchEntire(sentence)?.let { m ->
            val condition = sosCondition(m.groupValues[1]) ?: return@let
            val (_, stepsFrom) = context.previous ?: return@let
            val then = effect(sosSentence(m.groupValues[2]), context) ?: return null
            return steps.take(stepsFrom) + Step.If(condition, then = then, otherwise = steps.drop(stepsFrom))
        }
        // sos chunk 01: "If you draw one or more cards this way, discard two cards." after "you may draw X cards"
        Sos.IF_DREW_THIS_WAY.matchEntire(sentence)?.let { m ->
            val last = steps.lastOrNull() as? Step.May ?: return null
            val draw = (last.steps.singleOrNull() as? Step.Do)?.effect as? Effect.Draw ?: return null
            val then = effect(sosSentence(m.groupValues[1]), context) ?: return null
            return steps.dropLast(1) + last.copy(steps = listOf(Step.Do(draw.copy(postBind = "drawn")))) +
                Step.If(arcanum.api.Condition.NonEmpty("drawn"), then = then)
        }
        // sos chunk 01: "Put X +1/+1 counters on each of them and you gain X life." after creating tokens
        Sos.CREATE_TOKENS_PUT_X_ON_EACH_AND_GAIN.matchEntire(sentence)?.let { m ->
            val index = steps.indexOfLast { ((it as? Step.Do)?.effect as? Effect.CreateToken) != null }.takeIf { it >= 0 } ?: return null
            val create = (steps[index] as Step.Do).effect as Effect.CreateToken
            val kind = Counters.kind(m.groupValues[1]) ?: return null
            val x = Value.Announced(name = "X")
            return steps.toMutableList().also { it[index] = Step.Do(create.copy(bind = "tokens")) } +
                Step.Do(Effect.PutCounters(Objects.Bound("tokens"), kind, x)) + Step.Do(Effect.GainLife(Players.You, x))
        }
        // sos chunk 11: "It's still a land." after "if this land isn't a creature, it becomes …": a reminder (CR 205.1b)
        if (sentence == "It's still a land." && ((steps.lastOrNull() as? Step.If)?.then?.singleOrNull() as? Step.Do)?.effect is Effect.ApplyMechanics) return steps.toList()
        // fdn chunk 10a: "Return that card to the battlefield … It has flying and is an Angel in addition to its other types.": the returned
        // permanent is a new object (CR 400.7), so the type and ability stay on it for good (layers 4 and 6)
        Fdn.IT_HAS_AND_IS_IN_ADDITION.matchEntire(sentence)?.let { m ->
            val move = (steps.lastOrNull() as? Step.Do)?.effect as? Effect.Move ?: return@let
            if (move.to.zone != Zone.Battlefield) return@let
            val keywords = m.groupValues[1].split(LazyRegexes.AND_LIST).map { OracleParser.keyword(it) ?: return null }
            val subtypes = m.groupValues[2].trim().split(' ').map { if (it in RulesWords.subtypes) arcanum.api.SubtypeRef.Literal(Subtype(it)) else return null }
            val bind = move.postBind ?: "returned"
            return steps.dropLast(1) + Step.Do(move.copy(postBind = bind)) + Step.Do(Effect.ApplyMechanics(listOf(Mechanic.GainAbilities(keywords),
                Mechanic.SetTypes(addSubtypes = subtypes)), Affected.Objects(Objects.Bound(bind)), arcanum.api.Duration.Indefinitely))
        }
        // fdn chunk 11b: "It's a Demon in addition to its other types." after the same Move (no keywords)
        Fdn.ITS_A_IN_ADDITION.matchEntire(sentence)?.let { m ->
            val move = (steps.lastOrNull() as? Step.Do)?.effect as? Effect.Move ?: return@let
            if (move.to.zone != Zone.Battlefield) return@let
            val subtypes = m.groupValues[1].trim().split(' ').map { if (it in RulesWords.subtypes) arcanum.api.SubtypeRef.Literal(Subtype(it)) else return null }
            val bind = move.postBind ?: "returned"
            return steps.dropLast(1) + Step.Do(move.copy(postBind = bind)) + Step.Do(Effect.ApplyMechanics(listOf(Mechanic.SetTypes(addSubtypes = subtypes)),
                Affected.Objects(Objects.Bound(bind)), arcanum.api.Duration.Indefinitely))
        }
        // fdn chunk 10a: the same after "Then you may have it become a 0/0 Elemental creature until end of turn."
        if (sentence == "It's still a land." && (((steps.lastOrNull() as? Step.May)?.steps?.singleOrNull() as? Step.Do)?.effect as? Effect.ApplyMechanics)?.mechanics?.any { it is Mechanic.SetTypes } == true)
            return steps.toList()
        // sos chunk 13: "Create a 3/3 … token with flying. It gains haste until end of turn." ("it" is the token)
        Sos.IT_GAINS_UNTIL_EOT.matchEntire(sentence)?.let { m ->
            val create = (steps.lastOrNull() as? Step.Do)?.effect as? Effect.CreateToken ?: return@let
            val keywords = sosKeywords(m.groupValues[1]) ?: return@let
            val bind = create.bind ?: "token"
            return steps.dropLast(1) + Step.Do(create.copy(bind = bind)) + sosUntilEndOfTurn(Objects.Bound(bind), Mechanic.GainAbilities(keywords))
        }
        // sos chunk 04: "Put a stun counter on each of them." after tapping them
        Sos.PUT_COUNTER_ON_EACH_OF_THEM.matchEntire(sentence)?.let { m ->
            val tap = (steps.lastOrNull() as? Step.Do)?.effect as? Effect.Tap ?: return@let
            return steps + Step.Do(Effect.PutCounters(tap.objects, Counters.kind(m.groupValues[1]) ?: return null, Value.Fixed(1)))
        }
        // sos chunk 09: "Put X +1/+1 counters on it." after creating a token
        Sos.PUT_X_COUNTERS_ON_IT.matchEntire(sentence)?.let { m ->
            val index = steps.indexOfLast { ((it as? Step.Do)?.effect as? Effect.CreateToken) != null }.takeIf { it >= 0 && it == steps.lastIndex } ?: return@let
            val create = (steps[index] as Step.Do).effect as Effect.CreateToken
            val kind = Counters.kind(m.groupValues[2]) ?: return null
            val amount = if (m.groupValues[1] == "X") Value.Announced(name = "X") else Value.Fixed(Numbers.count(m.groupValues[1]) ?: return null)
            return steps.dropLast(1) + Step.Do(create.copy(bind = "token")) + Step.Do(Effect.PutCounters(Objects.Bound("token"), kind, amount))
        }
        return null
    }

    /** sos chunk 10: 'Copy target creature spell you control. The copy gains haste and "At the beginning of the end step, sacrifice this
     * token."' (the copy becomes a token, CR 707.10f, 111.13; what it gains stays with the permanent, CR 400.7d) */
    private fun sosCopyGains(text: String, context: Context): List<Step>? {
        val m = Sos.COPY_TARGET_SPELL_GAINS.matchEntire(text) ?: return null
        val filter = Filters.all(ObjectFilter.Category(arcanum.api.ObjectCategory.Spell), Filters.noun(m.groupValues[1]) ?: return null,
            ObjectFilter.ControlledBy(PlayerFilter.You))
        val keyword = OracleParser.keyword(m.groupValues[2].replaceFirstChar { it.uppercase() }) ?: return null
        val granted = Sentences(setOf("this token", "this creature")).line(sosSentence(m.groupValues[3])) ?: return null
        context.targets += sosSlot("spell", filter)
        return listOf(Step.Do(Effect.CopySpell(Objects.Target("spell"), Players.You, newTargets = false, bind = "copy")),
            Step.Do(Effect.SpellGets(Objects.Bound("copy"), listOf(Mechanic.GainAbilities(listOf(keyword, granted))))))
    }

    /** sos chunk 12: "When this creature enters, choose up to one —" with its modes (CR 700.2, 603.3c: none chosen, it's removed). */
    private fun sosModalTrigger(header: String, modeLines: List<String>): Ability? {
        val m = SOS_CHOOSE_UP_TO_TRIGGER.matchEntire(header) ?: return null
        val (trigger, onlyIf) = trigger(m.groupValues[1]) ?: return null
        val n = Numbers.count(m.groupValues[2]) ?: return null
        val options = modeLines.map { arcanum.api.Mode(instructions(modeBody(it), that = that(trigger)) ?: return null, text = it) }
        if (options.isEmpty()) return null
        return Ability.Triggered(trigger, Instructions(modes = arcanum.api.Modes(options, min = 0, max = n, chooser = Players.You)), triggersOnlyIf = onlyIf)
    }

    /** sos: wordings of several sentences, read as a whole first. */
    private fun sosWhole(text: String, context: Context): List<Step>? {
        sosCopyGains(text, context)?.let { return it }
        // sos chunk 01: "Archaic's Agony deals X damage to target creature, …. Exile cards from the top of your library equal to the excess
        // damage dealt to that creature this way. You may play those cards until the end of your next turn." (CR 120.4a)
        Sos.EXCESS_EXILE_TOP_PLAY_UNTIL_NEXT_TURN.matchEntire(text)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val target = context.target(Filters.slotName(m.groupValues[2]), Filters.noun(m.groupValues[2]) ?: return null)
            return listOf(
                Step.Do(Effect.DealDamage(Recipients(objects = target), Value.Announced(name = "X"), Objects.Self, bind = "damage")),
                Step.Do(Effect.Move(Objects.LibraryCards(Players.You, Value.Excess("damage"), fromTop = true), Destination(Zone.Exile), postBind = "exiled")),
                Step.Do(Effect.ApplyMechanics(listOf(Mechanic.MayPlay(Zone.Exile, PlayKind.Play, holder = PlayerFilter.You)), Affected.Objects(Objects.Bound("exiled")),
                    arcanum.api.Duration.UntilEndOfYourNextTurn)))
        }
        // sos chunk 02: "If five or more mana was spent to cast that spell, exile the top card of your library. You may play that card until
        // the end of your next turn." (the part after the opus condition)
        Sos.IF_EXILE_TOP_PLAY_UNTIL_NEXT_TURN.matchEntire(text)?.let { m ->
            val condition = sosCondition(m.groupValues[2]) ?: return null
            val before = if (m.groupValues[1].isEmpty()) emptyList() else effect(m.groupValues[1], context) ?: return null
            return before + listOf(Step.If(condition, then = listOf(
                Step.Do(Effect.Move(Objects.LibraryCards(Players.You, Value.Fixed(1), fromTop = true), Destination(Zone.Exile), postBind = "exiled")),
                Step.Do(Effect.ApplyMechanics(listOf(Mechanic.MayPlay(Zone.Exile, PlayKind.Play, holder = PlayerFilter.You)), Affected.Objects(Objects.Bound("exiled")),
                    arcanum.api.Duration.UntilEndOfYourNextTurn)))))
        }
        // sos chunk 03: "Exile cards from the top of your library until you exile cards with total mana value 4 or greater. You may cast any
        // number of spells from among them without paying their mana costs."
        Sos.EXILE_UNTIL_TOTAL_MANA_VALUE_CAST_ANY.matchEntire(text)?.let { m ->
            return listOf(
                Step.Do(Effect.RevealUntil(ObjectFilter.Any, Players.You, count = Value.Fixed(0), reveal = true, into = Zone.Exile, foundBind = "exiled",
                    totalAtLeast = arcanum.api.Total(arcanum.api.NumericProperty.ManaValue, Value.Fixed(m.groupValues[1].toInt())))),
                Step.ForEach(arcanum.api.Each.Objects(Objects.Bound("exiled")), "card", listOf(Step.May(listOf(Step.Do(Effect.Cast(Objects.Bound("card"),
                    PlayKind.Cast, withoutPaying = true, caster = Players.You))), player = Players.You))))
        }
        // sos chunk 04: "Tap target creature. If it's your turn, put a stun counter on it." (CR 122.1d)
        Sos.TAP_IF_YOUR_TURN_STUN.matchEntire(text)?.let { m ->
            val target = context.target(Filters.slotName(m.groupValues[1]), Filters.noun(m.groupValues[1]) ?: return null)
            return listOf(Step.Do(Effect.Tap(target)), Step.If(arcanum.api.Condition.YourTurn, then = listOf(
                Step.Do(Effect.PutCounters(target, arcanum.api.CounterKind.Stun, Value.Fixed(1))))))
        }
        // sos chunk 04: "Tap target creature. Put twice X stun counters on it."
        Sos.TAP_PUT_TWICE_X_STUN.matchEntire(text)?.let { m ->
            val target = context.target(Filters.slotName(m.groupValues[1]), Filters.noun(m.groupValues[1]) ?: return null)
            return listOf(Step.Do(Effect.Tap(target)), Step.Do(Effect.PutCounters(target, arcanum.api.CounterKind.Stun, Value.Times(Value.Announced(name = "X"), 2))))
        }
        // sos chunk 04: "Tap up to two target creatures. Put a stun counter on each of them."
        Sos.TAP_UP_TO_PUT_STUN_ON_EACH.matchEntire(text)?.let { m -> return tapUpToStun(m, context) }
        // sos chunk 05: "Look at the top four cards of your library. You may reveal a creature or land card from among them and put it into your
        // hand. If you gained life this turn, you may instead reveal two creature and/or land cards from among them and put them into your
        // hand. Put the rest on the bottom of your library in a random order."
        Sos.LOOK_REVEAL_ONE_OR_IF_TWO.matchEntire(text)?.let { m ->
            val n = Numbers.count(m.groupValues[1]) ?: return null
            val one = Filters.noun(m.groupValues[2]) ?: return null
            val condition = Conditions.condition(m.groupValues[3], self) ?: return null
            val two = Numbers.count(m.groupValues[4]) ?: return null
            val many = Filters.noun(m.groupValues[5]) ?: return null
            val looked = Objects.Bound("looked")
            fun reveal(filter: ObjectFilter, max: Int) = listOf(
                Step.Choose(arcanum.api.Choice.Objects(filter, Value.Fixed(0), Value.Fixed(max), from = looked), bind = "chosen", chooser = Players.You),
                Step.Do(Effect.Reveal(Objects.Bound("chosen"))),
                Step.Do(Effect.Move(Objects.Bound("chosen"), Destination(Zone.Hand))))
            return listOf(
                Step.Do(Effect.LookAt(Objects.LibraryCards(Players.You, Value.Fixed(n), fromTop = true), Players.You, bind = "looked")),
                Step.If(condition, then = reveal(many, two), otherwise = reveal(one, 1)),
                Step.Do(Effect.Move(Objects.Except(looked, Objects.Bound("chosen")), sosBottomRandom)))
        }
        // sos chunk 06: "Look at the top three cards of your library. Put one of them into your hand and the rest on the bottom of your
        // library in any order. If there is an instant card and a sorcery card in your graveyard, instead put two of them into your hand …"
        Sos.LOOK_PUT_ONE_OR_TWO_IF.matchEntire(text)?.let { m ->
            val n = Numbers.count(m.groupValues[1]) ?: return null
            val condition = Conditions.condition(m.groupValues[2], self) ?: return null
            val looked = Objects.Bound("looked")
            fun put(keep: Int) = listOf(
                Step.Choose(arcanum.api.Choice.Objects(ObjectFilter.Any, Value.Fixed(keep), Value.Fixed(keep), from = looked), bind = "chosen", chooser = Players.You),
                Step.Do(Effect.Move(Objects.Bound("chosen"), Destination(Zone.Hand))))
            return listOf(
                Step.Do(Effect.LookAt(Objects.LibraryCards(Players.You, Value.Fixed(n), fromTop = true), Players.You, bind = "looked")),
                Step.If(condition, then = put(2), otherwise = put(1)),
                Step.Do(Effect.Move(Objects.Except(looked, Objects.Bound("chosen")), sosBottomAnyOrder)))
        }
        // sos chunk 06: "look at the top X cards of your library. Put one of them into your hand and the rest on the bottom of your library in
        // a random order." (X of the spell cast, in a cast trigger: CR 107.3a)
        Sos.LOOK_TOP_X_PUT_ONE_REST_BOTTOM_RANDOM.matchEntire(text)?.let {
            val x = if (context.event is EventPattern.Cast) Value.CastX(of = Objects.EventObject(EventRole.Object)) else Value.Announced(name = "X")
            return sosLookPut(x, 1, sosBottomRandom)
        }
        // sos chunk 06: "look at the top X cards of your library, …. Put one of those cards into your hand and the rest into your graveyard."
        // (X defined by "where X is", so read as announced here)
        Sos.LOOK_TOP_X_PUT_ONE_REST_GRAVEYARD.matchEntire(text)?.let {
            return sosLookPut(Value.Announced(name = "X"), 1, Destination(Zone.Graveyard))
        }
        // sos chunk 06: "Look at the top two cards of your library. Put one of them into your hand and the other on the bottom of your
        // library" / "… into your graveyard."
        Sos.LOOK_TOP_N_PUT_ONE_OTHER.matchEntire(text)?.let { m ->
            val n = Numbers.count(m.groupValues[1]) ?: return null
            val rest = if (m.groupValues[2] == "into your graveyard") Destination(Zone.Graveyard) else sosBottomAnyOrder
            return sosLookPut(Value.Fixed(n), 1, rest)
        }
        // sos chunk 06: "Look at the top five cards of your library. You may reveal up to two creature and/or land cards from among them, then
        // put the rest on the bottom of your library in a random order. Put all land cards revealed this way onto the battlefield tapped and
        // put all creature cards revealed this way into your hand."
        Sos.LOOK_REVEAL_UP_TO_LANDS_BATTLEFIELD_CREATURES_HAND.matchEntire(text)?.let { m ->
            val n = Numbers.count(m.groupValues[1]) ?: return null
            val max = Numbers.count(m.groupValues[2]) ?: return null
            val filter = Filters.noun(m.groupValues[3]) ?: return null
            val looked = Objects.Bound("looked")
            val chosen = Objects.Bound("chosen")
            return listOf(
                Step.Do(Effect.LookAt(Objects.LibraryCards(Players.You, Value.Fixed(n), fromTop = true), Players.You, bind = "looked")),
                Step.Choose(arcanum.api.Choice.Objects(filter, Value.Fixed(0), Value.Fixed(max), from = looked), bind = "chosen", chooser = Players.You),
                Step.Do(Effect.Reveal(chosen)),
                Step.Do(Effect.Move(Objects.Except(looked, chosen), sosBottomRandom)),
                Step.Do(Effect.Move(Objects.Where(chosen, ObjectFilter.Type(CardType.Land)), Destination(Zone.Battlefield, tapped = true))),
                Step.Do(Effect.Move(Objects.Where(chosen, ObjectFilter.Type(CardType.Creature)), Destination(Zone.Hand))))
        }
        // sos chunk 06: "look at the top five cards of your library. You may reveal a land card or a card with {X} in its mana cost from among
        // them and put it into your hand. Put the rest on the bottom of your library in a random order."
        Sos.LOOK_REVEAL_LAND_OR_X.matchEntire(text)?.let { m ->
            val n = Numbers.count(m.groupValues[1]) ?: return null
            val looked = Objects.Bound("looked")
            val chosen = Objects.Bound("chosen")
            return listOf(
                Step.Do(Effect.LookAt(Objects.LibraryCards(Players.You, Value.Fixed(n), fromTop = true), Players.You, bind = "looked")),
                Step.Choose(arcanum.api.Choice.Objects(ObjectFilter.Or(listOf(ObjectFilter.Type(CardType.Land), ObjectFilter.XInManaCost)), Value.Fixed(0),
                    Value.Fixed(1), from = looked), bind = "chosen", chooser = Players.You),
                Step.Do(Effect.Reveal(chosen)),
                Step.Do(Effect.Move(chosen, Destination(Zone.Hand))),
                Step.Do(Effect.Move(Objects.Except(looked, chosen), sosBottomRandom)))
        }
        // sos chunk 13: "Reveal cards from the top of your library until you reveal an instant or sorcery card. Put that card into your hand
        // and the rest on the bottom of your library in a random order." (CR 701.20)
        Sos.REVEAL_UNTIL_PUT_HAND_REST_BOTTOM.matchEntire(text)?.let { m ->
            val filter = Filters.noun(m.groupValues[1]) ?: return null
            return listOf(
                Step.Do(Effect.RevealUntil(filter, Players.You, count = Value.Fixed(1), reveal = true, foundBind = "found", restBind = "rest")),
                Step.Do(Effect.Move(Objects.Bound("found"), Destination(Zone.Hand))),
                Step.Do(Effect.Move(Objects.Bound("rest"), sosBottomRandom)))
        }
        // sos chunk 06: "Mill seven cards. Then put a creature card from among them onto the battlefield."
        Sos.MILL_PUT_FROM_AMONG_ONTO_BATTLEFIELD.matchEntire(text)?.let { m ->
            val n = Numbers.count(m.groupValues[1]) ?: return null
            val filter = Filters.noun(m.groupValues[2]) ?: return null
            return listOf(
                Step.Do(Effect.Mill(Players.You, Value.Fixed(n), postBind = "milled")),
                Step.Choose(arcanum.api.Choice.Objects(filter, Value.Fixed(1), Value.Fixed(1), from = Objects.Bound("milled")), bind = "chosen", chooser = Players.You),
                Step.Do(Effect.Move(Objects.Bound("chosen"), Destination(Zone.Battlefield))))
        }
        // sos chunk 06: "Mill a card. You may play that card this turn."
        if (Sos.MILL_MAY_PLAY_THIS_TURN.matches(text)) return listOf(
            Step.Do(Effect.Mill(Players.You, Value.Fixed(1), postBind = "milled")),
            Step.Do(Effect.ApplyMechanics(listOf(Mechanic.MayPlay(Zone.Graveyard, PlayKind.Play, holder = PlayerFilter.You)), Affected.Objects(Objects.Bound("milled")),
                arcanum.api.Duration.EndOfTurn)))
        // sos chunk 08: "exile target noncreature, nonland card from your graveyard. Until the end of your next turn, you may cast that card."
        Sos.EXILE_TARGET_MAY_CAST_UNTIL_NEXT_TURN.matchEntire(text)?.let { m ->
            val target = context.target(Filters.slotName(m.groupValues[1]), sosYourGraveyard(Filters.noun(m.groupValues[1]) ?: return null))
            return listOf(
                Step.Do(Effect.Move(target, Destination(Zone.Exile), postBind = "exiled")),
                Step.Do(Effect.ApplyMechanics(listOf(Mechanic.MayPlay(Zone.Exile, PlayKind.Cast, holder = PlayerFilter.You)), Affected.Objects(Objects.Bound("exiled")),
                    arcanum.api.Duration.UntilEndOfYourNextTurn)))
        }
        // sos chunk 08: "Exile target nonland permanent and the top card of your library. For each of those cards, its owner may play it until
        // the end of their next turn."
        Sos.EXILE_TARGET_AND_TOP_EACH_OWNER_MAY_PLAY.matchEntire(text)?.let { m ->
            val target = context.target(Filters.slotName(m.groupValues[1]), Filters.noun(m.groupValues[1]) ?: return null)
            val card = Objects.Bound("card")
            return listOf(
                Step.Do(Effect.Move(Objects.Union(listOf(target, Objects.LibraryCards(Players.You, Value.Fixed(1), fromTop = true))), Destination(Zone.Exile),
                    postBind = "exiled")),
                Step.ForEach(arcanum.api.Each.Objects(Objects.Bound("exiled")), "card", listOf(Step.Do(Effect.ApplyMechanics(
                    listOf(Mechanic.MayPlay(Zone.Exile, PlayKind.Play, holder = PlayerFilter.Is(Players.OwnerOf(card)))), Affected.Objects(card),
                    arcanum.api.Duration.UntilEndOfNextTurnOf(Players.OwnerOf(card)))))))
        }
        // sos chunk 08: "Exile target instant or sorcery card from an opponent's graveyard. You may cast it this turn, and mana of any type can
        // be spent to cast that spell. If that spell would be put into a graveyard, exile it instead."
        Sos.EXILE_FROM_OPPONENT_GRAVEYARD_MAY_CAST.matchEntire(text)?.let { m ->
            val target = context.target(Filters.slotName(m.groupValues[1]), Filters.all(Filters.noun(m.groupValues[1]) ?: return null,
                ObjectFilter.InZone(Zone.Graveyard), ObjectFilter.OwnedBy(PlayerFilter.Opponent)))
            return listOf(
                Step.Do(Effect.Move(target, Destination(Zone.Exile), postBind = "exiled")),
                Step.Do(Effect.ApplyMechanics(listOf(Mechanic.MayPlay(Zone.Exile, PlayKind.Cast, manaAsAnyColor = true, holder = PlayerFilter.You,
                    then = Destination(Zone.Exile), thenInsteadOf = Zone.Graveyard)), Affected.Objects(Objects.Bound("exiled")), arcanum.api.Duration.EndOfTurn)))
        }
        // sos chunk 08: "Put target creature card from a graveyard onto the battlefield under your control. You lose life equal to that card's
        // mana value." (its mana value as it last existed in the graveyard, CR 608.2h)
        Sos.PUT_TARGET_FROM_A_GRAVEYARD_LOSE_LIFE.matchEntire(text)?.let { m ->
            val target = context.target(Filters.slotName(m.groupValues[1]), Filters.all(Filters.noun(m.groupValues[1]) ?: return null, ObjectFilter.InZone(Zone.Graveyard)))
            return listOf(
                Step.Do(Effect.Move(target, Destination(Zone.Battlefield, controller = Players.You), preBind = "card")),
                Step.Do(Effect.LoseLife(Players.You, Value.Of(arcanum.api.NumericProperty.ManaValue, Objects.Bound("card"), arcanum.api.Combine.Single))))
        }
        // sos chunk 07: "Target player discards two cards. Put up to one land card discarded this way onto the battlefield tapped under your
        // control."
        Sos.DISCARDS_PUT_LAND_ONTO_BATTLEFIELD.matchEntire(text)?.let { m ->
            val n = Numbers.count(m.groupValues[1]) ?: return null
            val player = context.targetPlayer()
            return listOf(
                Step.Do(Effect.Discard(player, Value.Fixed(n), ObjectFilter.Any, postBind = "discarded")),
                Step.Choose(arcanum.api.Choice.Objects(ObjectFilter.Type(CardType.Land), Value.Fixed(0), Value.Fixed(1), from = Objects.Bound("discarded")),
                    bind = "chosen", chooser = Players.You),
                Step.Do(Effect.Move(Objects.Bound("chosen"), Destination(Zone.Battlefield, tapped = true, controller = Players.You))))
        }
        // sos chunk 07: "Each player loses half their life, then discards half the cards in their hand, then sacrifices half the permanents
        // they control of their choice. Round down each time." (CR 107.1a: rounded down)
        if (Sos.EACH_PLAYER_LOSES_HALF.matches(text)) {
            val player = Players.Bound("player")
            val permanents = Filters.all(ObjectFilter.Category(arcanum.api.ObjectCategory.Permanent), ObjectFilter.ControlledBy(PlayerFilter.Is(player)))
            return listOf(Step.ForEach(arcanum.api.Each.Players(Players.Each(PlayerFilter.Any)), "player", listOf(
                Step.Do(Effect.LoseLife(player, Value.Half(Value.LifeOf(player), roundUp = false))),
                Step.Do(Effect.Discard(player, Value.Half(Value.HandSize(player), roundUp = false), ObjectFilter.Any)),
                Step.Choose(arcanum.api.Choice.Objects(permanents, Value.Half(Value.Count(Objects.Each(permanents)), roundUp = false),
                    Value.Half(Value.Count(Objects.Each(permanents)), roundUp = false)), bind = "sacrificed", chooser = player),
                Step.Do(Effect.Sacrifice(Objects.Bound("sacrificed")))), together = true))
        }
        // sos chunk 13: "Flip five coins. Target opponent skips their next X turns, where X is the number of coins that came up heads."
        // (each heads is one more turn skipped)
        Sos.FLIP_COINS_SKIP_TURNS.matchEntire(text)?.let { m ->
            val n = Numbers.count(m.groupValues[1]) ?: return null
            val opponent = context.targetOpponent()
            return listOf(Step.Repeat(Value.Fixed(n), listOf(Step.Do(Effect.FlipCoin(Players.You, bind = "flip")),
                Step.If(arcanum.api.Condition.WonFlip("flip"), then = listOf(Step.Do(Effect.SkipNextTurn(opponent)))))))
        }
        // sos chunk 13: "Counter target spell. If you control a Wizard, add an amount of {C} equal to the amount of mana spent to cast that
        // spell at the beginning of your next main phase." (a delayed trigger, CR 603.7; the amount fixed as it is created)
        Sos.COUNTER_ADD_C_NEXT_MAIN.matchEntire(text)?.let { m ->
            val wizard = Filters.noun(m.groupValues[1] + " you control") ?: return null
            context.targets += sosSlot("spell", ObjectFilter.Category(arcanum.api.ObjectCategory.Spell))
            val spell = Objects.Target("spell")
            return listOf(Step.Do(Effect.Counter(spell)),
                Step.If(arcanum.api.Condition.Exists(wizard, atLeast = 1), then = listOf(Step.Do(Effect.CreateDelayedTrigger(
                    arcanum.api.Trigger.On(listOf(EventPattern.StepBegins(arcanum.api.TurnStep.PrecombatMain, PlayerFilter.You),
                        EventPattern.StepBegins(arcanum.api.TurnStep.PostcombatMain, PlayerFilter.You))),
                    Instructions(steps = listOf(Step.Do(Effect.AddMana(ManaProduction(ManaKind.Fixed(ManaCost.parse("{C}")!!, times = Value.ManaSpent(of = spell))),
                        Players.You)))))))))
        }
        // sos chunk 13: "Sacrifice two lands. Search your library for four basic land cards, put them onto the battlefield tapped, then
        // shuffle."
        Sos.SACRIFICE_LANDS_SEARCH_BASICS.matchEntire(text)?.let { m ->
            val sacrifice = Numbers.count(m.groupValues[1]) ?: return null
            val search = Numbers.count(m.groupValues[2]) ?: return null
            val lands = Filters.all(ObjectFilter.Type(CardType.Land), ObjectFilter.ControlledBy(PlayerFilter.You))
            return listOf(
                Step.Choose(arcanum.api.Choice.Objects(lands, Value.Fixed(sacrifice), Value.Fixed(sacrifice)), bind = "sacrificed", chooser = Players.You),
                Step.Do(Effect.Sacrifice(Objects.Bound("sacrificed"))),
                Step.Do(Effect.Search(Players.You, Filters.noun("basic land card") ?: return null, max = Value.Fixed(search), zones = listOf(Zone.Library),
                    bind = "found", searcher = Players.You)),
                Step.Do(Effect.Move(Objects.Bound("found"), Destination(Zone.Battlefield, tapped = true))),
                Step.Do(Effect.Shuffle(Players.You)))
        }
        // sos chunk 13: "Target creature you control gets +1/+0 until end of turn if you've cast another instant or sorcery spell this turn.
        // Then it deals damage equal to its power to up to one target creature an opponent controls."
        Sos.TARGET_GETS_IF_CAST_ANOTHER_THEN_DEALS.matchEntire(text)?.let { m ->
            val target = context.target(Filters.slotName(m.groupValues[1]), Filters.noun(m.groupValues[1]) ?: return null)
            val spells = Filters.noun(m.groupValues[4] + " spell") ?: return null
            val other = context.target(Filters.slotName(m.groupValues[5]), Filters.noun(m.groupValues[5]) ?: return null)
            context.targets[context.targets.lastIndex] = context.targets.last().copy(min = Value.Fixed(0))
            val another = arcanum.api.Condition.HappenedThisTurn(EventPattern.Cast(Filters.all(spells, ObjectFilter.Not(ObjectFilter.Is(Objects.Self))), PlayerFilter.You),
                atLeast = 1, measure = arcanum.api.Measure.Events)
            return listOf(
                Step.If(another, then = listOf(sosUntilEndOfTurn(target, Mechanic.ModifyPowerToughness(ptChange(m.groupValues[2]) ?: return null,
                    ptChange(m.groupValues[3]) ?: return null)))),
                Step.Do(Effect.DealDamage(Recipients(objects = other), sosPower(target), target)))
        }
        // sos chunk 11: "Create a token that's a copy of target non-Aura permanent you control, except it's a 0/0 Fractal creature in addition
        // to its other types. Put six +1/+1 counters on it." (CR 707.9b)
        Sos.COPY_EXCEPT_FRACTAL_PUT_COUNTERS.matchEntire(text)?.let { m ->
            val target = context.target(Filters.slotName(m.groupValues[1]), Filters.noun(m.groupValues[1]) ?: return null)
            val subtype = m.groupValues[2].takeIf { it in RulesWords.subtypes } ?: return null
            val n = Numbers.count(m.groupValues[3]) ?: return null
            val kind = Counters.kind(m.groupValues[4]) ?: return null
            return listOf(
                Step.Do(Effect.CreateToken(arcanum.api.TokenSpec.CopyOf(target, except = listOf(
                    arcanum.api.CopyException.PowerToughness(0, 0),
                    arcanum.api.CopyException.Types(add = listOf(CardType.Creature), addSubtypes = listOf(arcanum.api.SubtypeRef.Literal(Subtype(subtype)))))),
                    Value.Fixed(1), Players.You, bind = "token")),
                Step.Do(Effect.PutCounters(Objects.Bound("token"), kind, Value.Fixed(n))))
        }
        return null
    }

    /** sos: effect sentences, tried first in [effectRules]. */
    private fun sosEffect(sentence: String, context: Context): List<Step>? {
        // "Look at the top two cards …. Put one of them …" arrives as one sentence (see [sentences])
        if (sentence.contains(". ")) sosWhole(sentence, context)?.let { return it }
        // sos chunk 04: "Create a 0/0 green and blue Fractal creature token and put X +1/+1 counters on it" ("it" is the token)
        Sos.CREATE_TOKEN_AND_PUT_COUNTERS_ON_IT.matchEntire(sentence)?.let { m ->
            val (count, token) = Tokens.spec(m.groupValues[1] + " token") ?: return@let
            if (count != 1) return@let
            val kind = Counters.kind(m.groupValues[3]) ?: return null
            val amount = if (m.groupValues[2] == "X") Value.Announced(name = "X") else Value.Fixed(Numbers.count(m.groupValues[2]) ?: return null)
            return listOf(Step.Do(Effect.CreateToken(token, Value.Fixed(1), Players.You, bind = "token")),
                Step.Do(Effect.PutCounters(Objects.Bound("token"), kind, amount)))
        }
        // sos chunk 01: "put a +1/+1 counter on another target creature you control"
        Sos.ANOTHER_TARGET_COUNTER.matchEntire(sentence)?.let { m ->
            val kind = Counters.kind(m.groupValues[1]) ?: return null
            val target = context.target(Filters.slotName(m.groupValues[2]), Filters.all(context.another(), Filters.noun(m.groupValues[2]) ?: return null))
            return listOf(Step.Do(Effect.PutCounters(target, kind, Value.Fixed(1))))
        }
        // sos chunk 02: "that player mills ten cards" (the target player)
        Sos.THAT_PLAYER_MILLS.matchEntire(sentence)?.let { m ->
            val slot = context.targets.lastOrNull { it.what is TargetKind.Players } ?: return null
            return listOf(Step.Do(Effect.Mill(Players.Target(slot.name), Value.Fixed(Numbers.count(m.groupValues[1]) ?: return null))))
        }
        // sos chunk 05: "that creature's controller loses 3 life" (as it last existed if it has left, CR 608.2h)
        Sos.THAT_CREATURES_CONTROLLER_LOSES.matchEntire(sentence)?.let { m ->
            val slot = context.targets.lastOrNull { it.what is TargetKind.Objects } ?: return null
            return listOf(Step.Do(Effect.LoseLife(Players.ControllerOf(Objects.Target(slot.name)), Value.Fixed(m.groupValues[1].toInt()))))
        }
        // sos chunk 01: "creatures you control get +1/+0 until end of turn for each color of mana spent to cast that spell"
        Sos.GROUP_GETS_FOR_EACH_COLOR_SPENT.matchEntire(sentence)?.let { m ->
            val filter = Filters.noun(m.groupValues[1].replaceFirstChar { it.lowercase() }) ?: return null
            val colors = Value.ManaSpent(distinctColors = true, of = Objects.EventObject(EventRole.Object))
            fun per(n: String) = (ptChange(n) as? Value.Fixed)?.value?.let { v -> if (v == 0) Value.Fixed(0) else if (v == 1) colors else Value.Times(colors, v) }
            return listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.ModifyPowerToughness(per(m.groupValues[2]) ?: return null, per(m.groupValues[3]) ?: return null)),
                Affected.Objects(Objects.Each(filter)), arcanum.api.Duration.EndOfTurn)))
        }
        // sos chunk 12: "Steal the Show deals damage equal to the number of instant and sorcery cards in your graveyard to target creature or
        // planeswalker."
        Sos.DEALS_DAMAGE_EQUAL_TO_TARGET.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val amount = SosPhrases.value(m.groupValues[2]) ?: return@let
            val target = context.target(Filters.slotName(m.groupValues[3]), Filters.noun(m.groupValues[3]) ?: return null)
            return listOf(Step.Do(Effect.DealDamage(Recipients(objects = target), amount, Objects.Self)))
        }
        sosCopyGains(sentence, context)?.let { return it }
        // sos chunk 01: "That creature enters with X additional +1/+1 counters on it." after a creature spell is cast (CR 400.7d)
        Sos.CREATURE_SPELL_ENTERS_WITH_X_MORE.matchEntire(sentence)?.let { m ->
            if (context.event !is EventPattern.Cast) return null
            val kind = Counters.kind(m.groupValues[1]) ?: return null
            val spell = Objects.EventObject(EventRole.Object)
            return listOf(Step.Do(Effect.SpellGets(spell, listOf(Mechanic.Replacement(EventPattern.ZoneChange(ObjectFilter.Is(Objects.Affected), to = Zone.Battlefield),
                modify = listOf(Modification.EntersWithCounters(kind, Value.Announced(name = "X"))))))))
        }
        // sos chunk 02: "Then discard a card unless five or more mana was spent to cast that spell." (opus)
        Sos.UNLESS_CONDITION.matchEntire(sentence)?.let { m ->
            val condition = sosCondition(m.groupValues[2]) ?: return@let
            val then = effect(sosSentence(m.groupValues[1]), context) ?: return null
            return listOf(Step.If(arcanum.api.Condition.Not(condition), then = then))
        }
        // sos chunk 02/05: "If five or more mana was spent to cast that spell, this creature also gains double strike until end of turn.",
        // "If you gained life this turn, that creature's controller loses 3 life."
        Sos.IF_THEN.matchEntire(sentence)?.takeIf { !sentence.endsWith(" instead.") }?.let { m ->
            val condition = sosCondition(m.groupValues[1]) ?: return@let
            val then = effect(sosSentence(m.groupValues[2].replace(" also ", " ")), context) ?: return@let
            return listOf(Step.If(condition, then = then))
        }
        // sos chunk 02: "add an amount of {R} equal to this creature's power"
        Sos.ADD_AMOUNT_EQUAL_TO_POWER.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[2]) }?.let { m ->
            return listOf(Step.Do(Effect.AddMana(ManaProduction(ManaKind.Fixed(ManaCost.parse(m.groupValues[1]) ?: return null, times = sosPower(Objects.Self))), Players.You)))
        }
        // sos chunk 03: "Exile Divergent Equation." (the resolving spell exiles itself; it isn't put into the graveyard, CR 608.2n)
        Sos.EXILE_SELF.matchEntire(sentence)?.takeIf { isSpell && isSelf(it.groupValues[1]) }?.let {
            return listOf(Step.Do(Effect.Move(Objects.Self, Destination(Zone.Exile))))
        }
        // sos chunk 03: "You have no maximum hand size for the rest of the game." (CR 402.2)
        if (Sos.YOU_HAVE_NO_MAXIMUM_HAND_SIZE_REST_OF_GAME.matches(sentence))
            return listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.NoMaximumHandSize), Affected.Players(Players.You), arcanum.api.Duration.Indefinitely)))
        // sos chunk 03: "Return all instant and sorcery cards from your graveyard to your hand."
        Sos.RETURN_ALL_FROM_GRAVEYARD_TO_HAND.matchEntire(sentence)?.let { m ->
            val filter = Filters.noun(m.groupValues[1]) ?: Filters.noun(m.groupValues[1].replace(" cards", " card")) ?: return null
            return listOf(Step.Do(Effect.Move(Objects.Each(sosYourGraveyard(filter)), Destination(Zone.Hand))))
        }
        // sos chunk 03: "Return up to X target instant and/or sorcery cards from your graveyard to your hand."
        Sos.RETURN_UP_TO_X_TARGET.matchEntire(sentence)?.let { m ->
            val filter = Filters.noun(m.groupValues[1]) ?: return null
            val name = Filters.slotName(m.groupValues[1].removeSuffix("s"))
            context.targets += TargetSlot(name, TargetKind.Objects(sosYourGraveyard(filter)), min = Value.Fixed(0), max = Value.Announced(name = "X"))
            return listOf(Step.Do(Effect.Move(Objects.Target(name), Destination(Zone.Hand))))
        }
        // sos chunk 03: "Target player creates a token that's a copy of target creature you control." (CR 707.2)
        Sos.TARGET_PLAYER_CREATES_COPY_OF_TARGET.matchEntire(sentence)?.let { m ->
            val player = context.targetPlayer()
            val target = context.target(Filters.slotName(m.groupValues[1]), Filters.noun(m.groupValues[1]) ?: return null)
            return listOf(Step.Do(Effect.CreateToken(arcanum.api.TokenSpec.CopyOf(target), Value.Fixed(1), player)))
        }
        // sos chunk 07: "Discard your hand, then draw cards equal to the number of cards in target opponent's hand."
        if (Sos.DISCARD_HAND_DRAW_EQUAL_OPPONENT_HAND.matches(sentence)) {
            val opponent = context.targetOpponent()
            return listOf(Step.Do(Effect.Discard(Players.You, Value.Fixed(1), ObjectFilter.Any, objects = Objects.Each(handOf(Players.You)))),
                Step.Do(Effect.Draw(Players.You, Value.HandSize(opponent))))
        }
        // sos chunk 07: "Discard your hand, then draw cards equal to the number of cards discarded this way."
        // inr chunk 05: "Target player discards all the cards in their hand, then draws that many cards."
        Sos.DISCARD_HAND_DRAW_EQUAL_DISCARDED.matchEntire(sentence)?.let { m ->
            val player = if (m.groupValues[1] == "Discard your hand") Players.You else context.targetPlayer()
            return listOf(Step.Do(Effect.Discard(player, Value.Fixed(1), ObjectFilter.Any, objects = Objects.Each(handOf(player)), postBind = "discarded")),
                Step.Do(Effect.Draw(player, Value.Count(Objects.Bound("discarded")))))
        }
        // sos chunk 07: "Target player discards any number of cards, then draws that many cards.", "discard any number of cards, then draw that
        // many cards plus one"
        Sos.DISCARD_ANY_NUMBER_DRAW_THAT_MANY.matchEntire(sentence)?.let { m ->
            val player = if (m.groupValues[1] == "Target player discards") context.targetPlayer() else Players.You
            val drawn = Value.Count(Objects.Bound("discarded"))
            return listOf(
                Step.Choose(arcanum.api.Choice.Objects(handOf(player), Value.Fixed(0), null), bind = "chosen", chooser = player),
                Step.Do(Effect.Discard(player, Value.Fixed(1), ObjectFilter.Any, objects = Objects.Bound("chosen"), postBind = "discarded")),
                Step.Do(Effect.Draw(player, if (m.groupValues[2].isEmpty()) drawn else Value.Sum(listOf(drawn, Value.Fixed(1))))))
        }
        // sos chunk 07: "Any number of target players each discard a card."
        if (Sos.ANY_NUMBER_OF_TARGET_PLAYERS_EACH_DISCARD.matches(sentence)) {
            context.targets += TargetSlot("players", TargetKind.Players(PlayerFilter.Any), min = Value.Fixed(0), max = null)
            return listOf(Step.Do(Effect.Discard(Players.Target("players"), Value.Fixed(1), ObjectFilter.Any)))
        }
        // sos chunk 07: "Target opponent exiles a creature or planeswalker they control with the greatest mana value among creatures and
        // planeswalkers they control." (that player chooses among those tied, CR 608.2d)
        Sos.TARGET_OPPONENT_EXILES_GREATEST.matchEntire(sentence)?.let { m ->
            val opponent = context.targetOpponent()
            val theirs = ObjectFilter.ControlledBy(PlayerFilter.Is(opponent))
            val kind = Filters.noun(m.groupValues[1]) ?: return null
            val among = Filters.noun(m.groupValues[2].replace(" and ", " or ").replace("creatures", "creature").replace("planeswalkers", "planeswalker")) ?: return null
            val greatest = Value.Of(arcanum.api.NumericProperty.ManaValue, Objects.Each(Filters.all(among, theirs)), arcanum.api.Combine.Greatest)
            return listOf(
                Step.Choose(arcanum.api.Choice.Objects(Filters.all(kind, theirs, ObjectFilter.ManaValue(arcanum.api.Comparison.Equal, greatest)), Value.Fixed(1),
                    Value.Fixed(1)), bind = "chosen", chooser = opponent),
                Step.Do(Effect.Move(Objects.Bound("chosen"), Destination(Zone.Exile))))
        }
        // sos chunk 08: "Exile target creature you control, then return that card to the battlefield under its owner's control with a +1/+1
        // counter on it." (CR 400.7, 122.6)
        Sos.EXILE_THEN_RETURN_WITH_COUNTER.matchEntire(sentence)?.let { m ->
            val target = context.target(Filters.slotName(m.groupValues[1]), Filters.noun(m.groupValues[1]) ?: return null)
            val kind = Counters.kind(m.groupValues[2]) ?: return null
            return listOf(Step.Do(Effect.Move(target, Destination(Zone.Exile), postBind = "exiled")),
                Step.Do(Effect.Move(Objects.Bound("exiled"), Destination(Zone.Battlefield, controller = Players.OwnerOf(Objects.Bound("exiled")),
                    counters = listOf(arcanum.api.CountersToPut(kind, Value.Fixed(1)))))))
        }
        // sos chunk 08: "Return each artifact and creature card with mana value X from your graveyard to the battlefield."
        Sos.RETURN_EACH_WITH_MANA_VALUE_X.matchEntire(sentence)?.takeIf { it.groupValues[1].contains(" and ") }?.let { m ->
            val kinds = m.groupValues[1].removeSuffix(" card").split(" and ").map { Filters.noun(it) ?: return null }
            return listOf(Step.Do(Effect.Move(Objects.Each(sosYourGraveyard(Filters.all(ObjectFilter.Or(kinds),
                ObjectFilter.ManaValue(arcanum.api.Comparison.Equal, Value.Announced(name = "X"))))), Destination(Zone.Battlefield))))
        }
        // sos chunk 08: "Destroy all artifacts and creatures with mana value X or less."
        Sos.DESTROY_ALL_WITH_MANA_VALUE_X_OR_LESS.matchEntire(sentence)?.let { m ->
            val kinds = m.groupValues[1].split(" and ").map { Filters.noun(it.removeSuffix("s")) ?: return null }
            return listOf(Step.Do(Effect.Destroy(Objects.Each(Filters.all(ObjectFilter.Or(kinds),
                ObjectFilter.ManaValue(arcanum.api.Comparison.AtMost, Value.Announced(name = "X")))))))
        }
        // sos chunk 06: "Search your library for a creature card, reveal it, put it into your hand or graveyard, then shuffle."
        Sos.SEARCH_PUT_HAND_OR_GRAVEYARD.matchEntire(sentence)?.let { m ->
            val filter = Filters.noun(m.groupValues[1]) ?: return null
            val found = Objects.Bound("found")
            return listOf(
                Step.Do(Effect.Search(Players.You, filter, max = Value.Fixed(1), reveal = true, zones = listOf(Zone.Library), bind = "found", searcher = Players.You)),
                Step.Choose(arcanum.api.Choice.Option(listOf("hand", "graveyard")), bind = "where", chooser = Players.You),
                Step.If(arcanum.api.Condition.Chose("where", "hand"), then = listOf(Step.Do(Effect.Move(found, Destination(Zone.Hand)))),
                    otherwise = listOf(Step.Do(Effect.Move(found, Destination(Zone.Graveyard))))),
                Step.Do(Effect.Shuffle(Players.You)))
        }
        // sos chunk 09: "Put a +1/+1 counter on target creature you control, then double the number of +1/+1 counters on that creature."
        // (CR 701.10e)
        Sos.PUT_COUNTER_THEN_DOUBLE.matchEntire(sentence)?.let { m ->
            val kind = Counters.kind(m.groupValues[1]) ?: return null
            val target = context.target(Filters.slotName(m.groupValues[2]), Filters.noun(m.groupValues[2]) ?: return null)
            return listOf(Step.Do(Effect.PutCounters(target, kind, Value.Fixed(1))),
                Step.Do(Effect.Action(arcanum.api.KeywordAction.Double(arcanum.api.Doubled.Counters(target, Counters.kind(m.groupValues[3]) ?: return null)))))
        }
        // sos chunk 09: "create a 0/0 green and blue Fractal creature token, then put this creature's counters on that token" (counters it had
        // as it last existed, CR 608.2h)
        Sos.CREATE_TOKEN_PUT_COUNTERS_OF_SELF.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[2]) }?.let { m ->
            val (count, token) = Tokens.spec(m.groupValues[1] + " token") ?: return null
            return listOf(Step.Do(Effect.CreateToken(token, Value.Fixed(count), Players.You, bind = "token")),
                Step.Do(Effect.PutCountersOf(Objects.Bound("token"), of = if (context.selfDied()) Objects.EventObject(EventRole.Before) else Objects.Self)))
        }
        // sos chunk 10: "you may sacrifice an artifact. If you do, copy that spell and you may choose new targets for the copy."
        Sos.CAST_TRIGGER_MAY_SACRIFICE_COPY.matchEntire(sentence)?.let { m ->
            if (context.event !is EventPattern.Cast) return null
            val filter = Filters.noun(m.groupValues[1]) ?: return null
            return listOf(Step.Pay(Cost(listOf(CostPart.Sacrifice(CostObjects.Choose(filter, Value.Fixed(1))))), payer = Players.You, bind = "paid"),
                Step.If(arcanum.api.Condition.Did("paid"), then = listOf(Step.Do(Effect.CopySpell(Objects.EventObject(EventRole.Object), Players.You, newTargets = true)))))
        }
        // sos chunk 12: "One or two target creatures each get +2/+2 until end of turn."
        Sos.ONE_OR_TWO_TARGET_EACH_GET.matchEntire(sentence)?.let { m ->
            val noun = m.groupValues[1]
            val filter = Filters.noun(noun) ?: Filters.noun(noun.removeSuffix("s")) ?: return null
            val name = Filters.slotName(noun.removeSuffix("s"))
            context.targets += sosSlot(name, filter, min = 1, max = 2)
            return listOf(sosUntilEndOfTurn(Objects.Target(name), Mechanic.ModifyPowerToughness(ptChange(m.groupValues[2]) ?: return null, ptChange(m.groupValues[3]) ?: return null)))
        }
        // sos chunk 12: "Prismari Charm deals 1 damage to each of one or two targets." (CR 115.4: any target)
        Sos.DEALS_DAMAGE_TO_EACH_OF_ONE_OR_TWO.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            context.targets += TargetSlot("any", TargetKind.Either(ObjectFilter.Or(listOf(ObjectFilter.Type(CardType.Creature), ObjectFilter.Type(CardType.Planeswalker),
                ObjectFilter.Type(CardType.Battle))), PlayerFilter.Any), min = Value.Fixed(1), max = Value.Fixed(2))
            return listOf(Step.Do(Effect.DealDamage(Recipients(target = "any"), Value.Fixed(m.groupValues[2].toInt()), Objects.Self)))
        }
        // sos chunk 12: 'Until end of turn, any number of target creatures you control each get +1/+0 and gain "When this creature dies, draw a
        // card."'
        Sos.ANY_NUMBER_TARGET_EACH_GET_AND_GAIN.matchEntire(sentence)?.let { m ->
            val noun = m.groupValues[1]
            val filter = Filters.noun(noun) ?: Filters.noun(noun.replace("creatures", "creature")) ?: return null
            val name = Filters.slotName(noun.replace("creatures", "creature"))
            val granted = Sentences(setOf("this creature")).line(sosSentence(m.groupValues[4])) ?: return null
            context.targets += sosSlot(name, filter, min = 0, max = null)
            return listOf(sosUntilEndOfTurn(Objects.Target(name), Mechanic.ModifyPowerToughness(ptChange(m.groupValues[2]) ?: return null, ptChange(m.groupValues[3]) ?: return null),
                Mechanic.GainAbilities(listOf(granted))))
        }
        // sos chunk 12: 'Until end of turn, creatures you control get +2/+2 and gain menace and "Whenever this creature attacks, you gain 1 life."'
        Sos.GROUP_GETS_GAINS_KEYWORD_AND_QUOTED.matchEntire(sentence)?.let { m ->
            val filter = Filters.noun(m.groupValues[1]) ?: return null
            val keyword = OracleParser.keyword(m.groupValues[4]) ?: return null
            val granted = Sentences(setOf("this creature")).line(sosSentence(m.groupValues[5])) ?: return null
            return listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.ModifyPowerToughness(ptChange(m.groupValues[2]) ?: return null, ptChange(m.groupValues[3]) ?: return null),
                Mechanic.GainAbilities(listOf(keyword, granted))), Affected.Objects(Objects.Each(filter)), arcanum.api.Duration.EndOfTurn)))
        }
        // sos chunk 11: "Until end of turn, target creature becomes a green and blue Fractal with base power and toughness each equal to X plus
        // 1." (it loses its other colours and creature types: layers 4, 5, 7b)
        Sos.UNTIL_EOT_BECOMES_FRACTAL_X_PLUS.matchEntire(sentence)?.let { m ->
            val target = context.target(Filters.slotName(m.groupValues[1]), Filters.noun(m.groupValues[1]) ?: return null)
            val colors = listOf(m.groupValues[2], m.groupValues[3]).map { arcanum.api.ColorRef.Literal(Tokens.color(it) ?: return null) }
            val subtype = m.groupValues[4].takeIf { it in RulesWords.subtypes } ?: return null
            val pt = Value.Sum(listOf(Value.Announced(name = "X"), Value.Fixed(m.groupValues[5].toInt())))
            return listOf(sosUntilEndOfTurn(target, Mechanic.SetColors(colors),
                Mechanic.SetTypes(addSubtypes = listOf(arcanum.api.SubtypeRef.Literal(Subtype(subtype))), replaceSubtypes = true),
                Mechanic.SetPowerToughness(pt, pt)))
        }
        // sos chunk 11: '{5}: If this land isn't a creature, it becomes a 2/4 Wizard creature with "…" It's still a land.' (for good: no
        // duration is stated, CR 611.2a)
        Sos.IF_NOT_CREATURE_BECOMES.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val subtype = m.groupValues[4].takeIf { it in RulesWords.subtypes } ?: return null
            val granted = Sentences(setOf("this creature")).line(sosSentence(m.groupValues[5])) ?: return null
            return listOf(Step.If(arcanum.api.Condition.Not(arcanum.api.Condition.ObjectMatches(Objects.Self, ObjectFilter.Type(CardType.Creature))), then = listOf(
                Step.Do(Effect.ApplyMechanics(listOf(Mechanic.SetTypes(add = listOf(CardType.Creature), addSubtypes = listOf(arcanum.api.SubtypeRef.Literal(Subtype(subtype)))),
                    Mechanic.SetPowerToughness(Value.Fixed(m.groupValues[2].toInt()), Value.Fixed(m.groupValues[3].toInt())), Mechanic.GainAbilities(listOf(granted))),
                    sosSelfOnly, arcanum.api.Duration.Indefinitely)))))
        }
        // sos chunk 13: "Target player draws 2ˣ cards." (2⁰ = 1)
        if (Sos.DRAWS_TWO_TO_THE_X.matches(sentence)) {
            val player = context.targetPlayer()
            return listOf(Step.Do(Effect.Draw(player, Value.Exponential(2, Value.Announced(name = "X")))))
        }
        // sos chunk 05: "target creature an opponent controls gets -4/-4 until end of turn if you gained life this turn"
        Sos.TARGET_GETS_UNTIL_EOT_IF.matchEntire(sentence)?.let { m ->
            val condition = sosCondition(m.groupValues[2]) ?: Conditions.condition(m.groupValues[2], self)?.takeIf { m.groupValues[2] == "you gained life this turn" } ?: return@let
            val then = effect(sosSentence(m.groupValues[1] + " until end of turn"), context) ?: return null
            return listOf(Step.If(condition, then = then))
        }
        // sos chunk 05: "put two +1/+1 counters on it if you gained life this turn"
        Sos.PUT_COUNTERS_ON_IT_IF.matchEntire(sentence)?.let { m ->
            val condition = Conditions.condition(m.groupValues[3], self) ?: return null
            val then = effect(sosSentence("put ${m.groupValues[1]} ${m.groupValues[2]} counter${if (m.groupValues[1] == "a") "" else "s"} on it"), context) ?: return null
            return listOf(Step.If(condition, then = then))
        }
        // sos chunk 05: "return up to one target creature card with mana value X or less from your graveyard to the battlefield" (X defined by
        // "where X is")
        Sos.RETURN_UP_TO_ONE_MANA_VALUE_X.matchEntire(sentence)?.let { m ->
            val filter = sosYourGraveyard(Filters.all(Filters.noun(m.groupValues[1]) ?: return null,
                ObjectFilter.ManaValue(arcanum.api.Comparison.AtMost, Value.Announced(name = "X"))))
            val name = Filters.slotName(m.groupValues[1])
            context.targets += sosSlot(name, filter, min = 0)
            return listOf(Step.Do(Effect.Move(Objects.Target(name), Destination(Zone.Battlefield))))
        }
        // sos chunk 07: "Target player discards X cards." (converge's X)
        if (Sos.TARGET_PLAYER_DISCARDS_X.matches(sentence)) {
            val player = context.targetPlayer()
            return listOf(Step.Do(Effect.Discard(player, Value.Announced(name = "X"), ObjectFilter.Any)))
        }
        return null
    }

    /** sos: wordings tried after every other rule found nothing ("A, B, and C." as three sentences). */
    private fun sosLateEffect(sentence: String, context: Context): List<Step>? {
        // sos chunk 05: "If you gained life this turn, that creature's controller loses 3 life.", "Sacrifice a permanent unless you gained
        // life this turn." with any condition the shared phrases read
        Sos.IF_THEN.matchEntire(sentence)?.takeIf { !sentence.endsWith(" instead.") }?.let { m ->
            val condition = Conditions.condition(m.groupValues[1], self) ?: return@let
            val then = effect(sosSentence(m.groupValues[2]), context) ?: return@let
            return listOf(Step.If(condition, then = then))
        }
        Sos.UNLESS_CONDITION.matchEntire(sentence)?.takeIf { !it.groupValues[2].contains(" pays ") }?.let { m ->
            val condition = Conditions.condition(m.groupValues[2], self) ?: return@let
            val then = effect(sosSentence(m.groupValues[1]), context) ?: return@let
            return listOf(Step.If(arcanum.api.Condition.Not(condition), then = then))
        }
        // sos chunk 01: "Target player draws X cards, Together as One deals X damage to any target, and you gain X life."
        Sos.A_B_AND_C.matchEntire(sentence)?.let { m ->
            val parts = listOf(m.groupValues[1], m.groupValues[2], m.groupValues[3])
            return parts.flatMap { effect(sosSentence(it), context) ?: return null }
        }
        return null
    }

    /** sos: the triggers and activations of a few cards, read whole first. */
    private fun sosTriggered(line: String): Ability? {
        // sos chunk 05: "When you cast this spell, copy it if you gained life this turn. You may choose new targets for the copy." (CR 707.10)
        Sos.WHEN_YOU_CAST_COPY_IF.matchEntire(line)?.let { m ->
            val condition = Conditions.condition(m.groupValues[1], self) ?: return null
            return Ability.Triggered(arcanum.api.Trigger.On(EventPattern.Cast(ObjectFilter.Is(Objects.Self), PlayerFilter.You)),
                Instructions(steps = listOf(Step.If(condition, then = listOf(Step.Do(Effect.CopySpell(Objects.Self, Players.You, newTargets = true)))))),
                functionsIn = listOf(Zone.Stack))
        }
        // sos chunk 05: "When you cast this spell while you control a creature, you may copy this spell." (checked only as it triggers)
        Sos.WHEN_YOU_CAST_WHILE_MAY_COPY.matchEntire(line)?.let { m ->
            val condition = Conditions.condition(m.groupValues[1], self) ?: return null
            return Ability.Triggered(arcanum.api.Trigger.On(EventPattern.Cast(ObjectFilter.Is(Objects.Self), PlayerFilter.You)),
                Instructions(steps = listOf(Step.May(listOf(Step.Do(Effect.CopySpell(Objects.Self, Players.You, newTargets = true))), player = Players.You))),
                triggersOnlyIf = condition, functionsIn = listOf(Zone.Stack))
        }
        // sos chunk 09: "At the beginning of combat on your turn, you may pay {X}. When you do, move X +1/+1 counters from this creature onto
        // another target creature." (X chosen as the cost is paid; the reflexive trigger's target chosen then, CR 603.12)
        Sos.MOVE_X_COUNTERS_ONTO_ANOTHER.matchEntire(line)?.takeIf { isSelf(it.groupValues[2]) }?.let { m ->
            val kind = Counters.kind(m.groupValues[1]) ?: return null
            val filter = Filters.all(ObjectFilter.Not(ObjectFilter.Is(Objects.Self)), Filters.noun(m.groupValues[3]) ?: return null)
            val reflexive = Instructions(targets = listOf(sosSlot("creature", filter)),
                steps = listOf(Step.Do(Effect.MoveCounters(Objects.Self, Objects.Target("creature"), kind, Value.Bound("X")))))
            val steps = listOf(
                Step.Choose(arcanum.api.Choice.Number(Value.Fixed(0)), bind = "X", chooser = Players.You),
                Step.Pay(Cost(listOf(CostPart.Mana(ManaCost.parse("{X}")!!, x = Value.Bound("X")))), payer = Players.You, bind = "paid"),
                Step.If(arcanum.api.Condition.Did("paid"), then = listOf(Step.Do(Effect.ReflexiveTrigger(reflexive)))))
            return Ability.Triggered(arcanum.api.Trigger.On(EventPattern.StepBegins(arcanum.api.TurnStep.BeginningOfCombat, PlayerFilter.You)),
                Instructions(steps = steps))
        }
        return null
    }
    // ---- sos end

    // ---- spm: Marvel's Spider-Man wordings (the set's parser tests, sets/spm/SpmChunk*Test.kt); regexes in [Spm], phrases in [SpmPhrases].
    // Tried first, each rule reading one wording and falling through when it can't.

    private val spmSelfOnly get() = Affected.Objects(Objects.Self)
    private val spmP1P1 get() = arcanum.api.CounterKind.PowerToughness(1, 1)
    private fun spmN(word: String): Int? = Numbers.count(word)
    private fun spmCap(text: String) = text.replaceFirstChar { it.uppercase() }
    private fun spmSlot(name: String, filter: ObjectFilter, min: Int = 1, max: Int? = 1) =
        TargetSlot(name, TargetKind.Objects(filter), min = Value.Fixed(min), max = max?.let { Value.Fixed(it) })
    private fun spmNewSlotName(context: Context, base: String) = if (context.targets.none { it.name == base }) base else nextTargetName(base, context.targets.map { it.name })
    private fun spmApply(objects: Objects, duration: arcanum.api.Duration, vararg mechanics: Mechanic) =
        Step.Do(Effect.ApplyMechanics(mechanics.toList(), Affected.Objects(objects), duration))
    private fun spmPower(of: Objects) = Value.Of(arcanum.api.NumericProperty.Power, of, arcanum.api.Combine.Single)
    private fun spmSubtypes(words: String): List<arcanum.api.SubtypeRef>? =
        words.trim().split(' ').map { w -> w.takeIf { it in RulesWords.subtypes }?.let { arcanum.api.SubtypeRef.Literal(Subtype(it)) } ?: return null }
    private val spmNotLegendary get() = arcanum.api.CopyException.Types(removeSupertypes = listOf(Supertype.Legendary))
    private val spmEntersSelf get() = EventPattern.ZoneChange(ObjectFilter.Is(Objects.Self), to = Zone.Battlefield)
    private fun spmPronoun(text: String) = text == "it" || text == "he" || text == "she" || text == "they" || text == "It" || text == "He" || text == "She"
    /** The card's own name or "it"/"he" in its own trigger. */
    private fun spmSelfOrPronoun(text: String) = isSelf(text) || spmPronoun(text)

    /** spm: whole lines read before the other rules. */
    private fun spmLine(line: String): Ability? {
        // spm chunk 08: "Whenever Spider-Slayer deals damage to a Spider, destroy that creature." (the creature dealt damage, CR 120.3)
        Spm.DEALS_DAMAGE_TO_SUBTYPE_DESTROY.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val subtypes = m.groupValues[2].split(" or ").map { it.takeIf { it in RulesWords.subtypes } ?: return null }
            val filter = subtypes.map { ObjectFilter.Sub(Subtype(it)) }.let { if (it.size == 1) it[0] else ObjectFilter.Or(it) } // ltr chunk 01
            return Ability.Triggered(arcanum.api.Trigger.On(EventPattern.Damage(ObjectFilter.Is(Objects.Self),
                arcanum.api.RecipientFilter(objects = filter))),
                Instructions(steps = listOf(Step.Do(Effect.Destroy(Objects.EventObject(EventRole.Object))))))
        }
        // spm chunk 08: "At the beginning of each player's first main phase, that player may put a +1/+1 counter on this creature. If they do,
        // they add {C} for each counter on it." (CR 505.1: the precombat main phase; the mana goes to that player)
        Spm.EACH_PLAYERS_MAIN_MAY_COUNTER_ADD_C.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            return Ability.Triggered(arcanum.api.Trigger.On(EventPattern.StepBegins(arcanum.api.TurnStep.PrecombatMain, PlayerFilter.Any)), Instructions(steps = listOf(
                Step.Pay(steps = listOf(Step.Do(Effect.PutCounters(Objects.Self, spmP1P1, Value.Fixed(1)))), payer = Players.EventPlayer, bind = "paid"),
                Step.If(arcanum.api.Condition.Did("paid"), then = listOf(Step.Do(Effect.AddMana(ManaProduction(ManaKind.Fixed(ManaCost.parse("{C}")!!,
                    times = Value.Of(arcanum.api.NumericProperty.Counters(null), Objects.Self, arcanum.api.Combine.Single))), Players.EventPlayer)))))))
        }
        // spm chunk 05: "{3}{G}{G}: Return this card and target land card from your graveyard to the battlefield tapped." (it works in the
        // graveyard, CR 113.6m)
        if (line.contains(": ")) {
            val costText = line.substringBefore(": ")
            val body = line.substringAfter(": ")
            Spm.RETURN_SELF_AND_TARGET_FROM_GRAVEYARD.matchEntire(body)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
                val cost = cost(costText) ?: return null
                val filter = Filters.all(Filters.noun(m.groupValues[2]) ?: return null, ObjectFilter.InZone(Zone.Graveyard), ObjectFilter.OwnedBy(PlayerFilter.You))
                val name = Filters.slotName(m.groupValues[2])
                return Ability.Activated(cost, Instructions(targets = listOf(spmSlot(name, filter)), steps = listOf(Step.Do(Effect.Move(
                    Objects.Union(listOf(Objects.Self, Objects.Target(name))), Destination(Zone.Battlefield, tapped = m.groupValues[3].isNotEmpty()))))),
                    arcanum.api.ActivationRules(timing = arcanum.api.Timing.Any, activatedBy = PlayerFilter.You), functionsIn = listOf(Zone.Graveyard))
            }
            // spm chunk 05: "{2}, Return a tapped creature you control to its owner's hand: Put this card from your hand onto the battlefield.
            // Activate only as a sorcery." (it works in the hand, CR 113.6m)
            val sorcery = body.endsWith(" Activate only as a sorcery.")
            Spm.PUT_SELF_FROM_HAND_ONTO_BATTLEFIELD.matchEntire(body.removeSuffix(" Activate only as a sorcery."))?.takeIf { isSelf(it.groupValues[1]) }?.let {
                val cost = cost(costText) ?: return null
                return Ability.Activated(cost, Instructions(steps = listOf(Step.Do(Effect.Move(Objects.Self, Destination(Zone.Battlefield))))),
                    arcanum.api.ActivationRules(timing = if (sorcery) arcanum.api.Timing.Sorcery else arcanum.api.Timing.Any, activatedBy = PlayerFilter.You),
                    functionsIn = listOf(Zone.Hand))
            }
        }
        return null
    }

    /** spm: static abilities, tried first in [static]. */
    private fun spmStatic(line: String): Ability? {
        // spm chunk 01: "Each legendary spell you cast that's one or more colors has web-slinging {G}{W}{U}." (CR 702.188a: an alternative
        // cost of those spells as they are cast, CR 601.2b)
        Spm.SPELLS_HAVE_WEB_SLINGING.matchEntire(line)?.let { m ->
            val cost = ManaCost.parse(m.groupValues[2]) ?: return null
            return Ability.Static(listOf(Mechanic.GainAbilities(listOf(arcanum.api.Keyword.WebSlinging(Cost.mana(cost))))), affects = Affected.Objects(Objects.Each(
                Filters.all(ObjectFilter.Category(arcanum.api.ObjectCategory.Spell), ObjectFilter.Super(Supertype.Legendary), ObjectFilter.Not(ObjectFilter.Colorless),
                    ObjectFilter.ControlledBy(PlayerFilter.You), ObjectFilter.WasCast()))))
        }
        // spm chunk 01: "If Scarlet Spider was cast using web-slinging, he enters with X +1/+1 counters on him, where X is the mana value of the
        // returned creature." (CR 614.1c; the creature returned to pay the cost, as it last existed, CR 608.2h)
        Spm.ENTERS_WITH_X_IF_WEB_SLINGING.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            return Ability.Static(listOf(Mechanic.Replacement(spmEntersSelf, modify = listOf(Modification.EntersWithCounters(spmP1P1,
                Value.Of(arcanum.api.NumericProperty.ManaValue, Objects.Bound(arcanum.api.KeywordExpansions.WEB_SLINGING_RETURNED), arcanum.api.Combine.Single))))),
                affects = spmSelfOnly, condition = arcanum.api.Condition.Paid(arcanum.api.Keyword.WebSlinging.Kind, times = 1, of = Objects.Self))
        }
        // spm chunk 01: "Each nonland card in your graveyard has mayhem. The mayhem cost is equal to its mana cost." (CR 702.187b)
        Spm.CARDS_IN_GRAVEYARD_HAVE_MAYHEM.matchEntire(line)?.let { m ->
            val cards = Filters.noun(m.groupValues[1]) ?: return null
            return Ability.Static(listOf(Mechanic.GainAbilities(listOf(arcanum.api.Keyword.Mayhem(Cost(listOf(CostPart.ItsManaCost)))))),
                affects = Affected.Objects(Objects.Each(Filters.all(cards, ObjectFilter.InZone(Zone.Graveyard), ObjectFilter.OwnedBy(PlayerFilter.You)))))
        }
        // spm chunk 01: "Spells you cast from your graveyard cost {2} less to cast." (CR 601.2f)
        Spm.SPELLS_CAST_FROM_COST_LESS.matchEntire(line)?.let { m ->
            val zone = when (m.groupValues[1]) { "graveyard" -> Zone.Graveyard; "hand" -> Zone.Hand; else -> Zone.Exile }
            return Ability.Static(listOf(Mechanic.CostChange(Filters.all(ObjectFilter.Category(arcanum.api.ObjectCategory.Spell), ObjectFilter.ControlledBy(PlayerFilter.You),
                ObjectFilter.WasCast(zone)), arcanum.api.CostChange.Less(ManaCost.parse(m.groupValues[2]) ?: return null, Value.Fixed(1)))), affects = spmSelfOnly)
        }
        // spm chunk 02: "This creature has flying as long as it's modified." (CR 700.9)
        Spm.HAS_KEYWORD_AS_LONG_AS_MODIFIED.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            return Ability.Static(listOf(Mechanic.GainAbilities(keywords(m.groupValues[2]) ?: return null)), affects = spmSelfOnly,
                condition = arcanum.api.Condition.ObjectMatches(Objects.Self, ObjectFilter.Modified))
        }
        // spm chunk 03: "Enchanted creature is a Citizen with base power and toughness 1/1. It has defender and loses all other abilities."
        // (layers 4, 6, 7b; a creature type replaces the others, CR 205.1b; it loses its abilities, then gains defender, CR 613.7)
        Spm.ENCHANTED_IS_SUBTYPE_BASE_PT_HAS_LOSES.matchEntire(line)?.let { m ->
            val subtype = m.groupValues[1].takeIf { it in RulesWords.subtypes } ?: return null
            return Ability.Static(listOf(Mechanic.SetTypes(addSubtypes = listOf(arcanum.api.SubtypeRef.Literal(Subtype(subtype))), replaceSubtypes = true),
                Mechanic.SetPowerToughness(Value.Fixed(m.groupValues[2].toInt()), Value.Fixed(m.groupValues[3].toInt())),
                Mechanic.LoseAbilities(), Mechanic.GainAbilities(keywords(m.groupValues[4]) ?: return null)), affects = Affected.Objects(Objects.AttachedTo(Objects.Self)))
        }
        // spm chunk 03: "As long as there are eight or more cards in your graveyard, Doc Ock has base power and toughness 8/8." (layer 7b)
        Spm.AS_LONG_AS_BASE_PT.matchEntire(line)?.takeIf { isSelf(it.groupValues[2]) }?.let { m ->
            val condition = conditionWithAnd(m.groupValues[1]) ?: return null
            return Ability.Static(listOf(Mechanic.SetPowerToughness(Value.Fixed(m.groupValues[3].toInt()), Value.Fixed(m.groupValues[4].toInt()))),
                affects = spmSelfOnly, condition = condition)
        }
        // spm chunk 03: "Equipped creature gets +2/+2 and is a Spider Hero in addition to its other types." (layers 4, 7c)
        Spm.EQUIPPED_GETS_AND_IS_IN_ADDITION.matchEntire(line)?.let { m ->
            return Ability.Static(listOf(Mechanic.ModifyPowerToughness(ptChange(m.groupValues[1]) ?: return null, ptChange(m.groupValues[2]) ?: return null),
                Mechanic.SetTypes(addSubtypes = spmSubtypes(m.groupValues[3]) ?: return null)), affects = Affected.Objects(Objects.AttachedTo(Objects.Self)))
        }
        // spm chunk 04: "You may have Chameleon enter as a copy of a creature you control, except his name is Chameleon, Master of Disguise."
        // (CR 707.9b: the name is part of the copy)
        Spm.MAY_ENTER_AS_COPY_EXCEPT_NAME.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val of = Filters.noun(m.groupValues[2]) ?: return null
            return Ability.Static(listOf(Mechanic.Replacement(spmEntersSelf, modify = listOf(Modification.EntersAsCopy(of,
                listOf(arcanum.api.CopyException.Name(m.groupValues[3])), optional = true)))), affects = spmSelfOnly)
        }
        // spm chunk 04: "You may have Superior Spider-Man enter as a copy of any creature card in a graveyard, except his name is Superior
        // Spider-Man and he's a 4/4 Spider Human Hero in addition to his other types. When you do, exile that card." (CR 707.9b, 603.12: the
        // card copied, exiled by a trigger linked to the replacement)
        Spm.MAY_ENTER_AS_COPY_OF_CARD_IN_GRAVEYARD.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val of = Filters.all(Filters.noun(m.groupValues[2]) ?: return null, ObjectFilter.InZone(Zone.Graveyard))
            val except = listOf(arcanum.api.CopyException.Name(m.groupValues[3]),
                arcanum.api.CopyException.PowerToughness(m.groupValues[4].toInt(), m.groupValues[5].toInt()),
                arcanum.api.CopyException.Types(addSubtypes = spmSubtypes(m.groupValues[6]) ?: return null))
            return Ability.Static(listOf(Mechanic.Replacement(spmEntersSelf, modify = listOf(Modification.EntersAsCopy(of, except, optional = true, bind = "copied")),
                whenApplied = Instructions(steps = listOf(Step.Do(Effect.Move(Objects.Bound("copied"), Destination(Zone.Exile))))))), affects = spmSelfOnly)
        }
        // spm chunk 05: "You may cast this card from your graveyard by discarding a card in addition to paying its other costs." (CR 601.2f)
        Spm.MAY_CAST_FROM_GRAVEYARD_BY_DISCARDING.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            return Ability.Static(listOf(Mechanic.MayPlay(Zone.Graveyard, PlayKind.Cast, holder = PlayerFilter.You,
                additionalCost = Cost(costPart("Discard a card") ?: return null))), affects = spmSelfOnly)
        }
        // spm chunk 05: "You may cast Spider spells and noncreature spells from the top of your library." (CR 601.2a)
        Spm.MAY_CAST_TWO_KINDS_FROM_TOP.matchEntire(line)?.let { m ->
            val kinds = listOf(m.groupValues[1], m.groupValues[2]).map { Filters.noun(it) ?: return null }
            return Ability.Static(listOf(Mechanic.MayPlay(Zone.Library, PlayKind.Cast, topOnly = true, holder = PlayerFilter.You)),
                affects = Affected.Objects(Objects.Each(Filters.all(ObjectFilter.Or(kinds), ObjectFilter.InZone(Zone.Library), ObjectFilter.OwnedBy(PlayerFilter.You)))))
        }
        // spm chunk 07: "Enchanted creature gets +2/+2 for each Aura and Equipment attached to it." (counted continuously, layer 7c)
        Spm.ATTACHED_GETS_FOR_EACH_ATTACHED.matchEntire(line)?.let { m ->
            val count = Value.Count(Objects.AttachmentsOf(Objects.AttachedTo(Objects.Self), ObjectFilter.Or(listOf(
                ObjectFilter.Sub(Subtype("Aura")), ObjectFilter.Sub(Subtype("Equipment"))))))
            fun per(n: Int): Value = when (n) { 0 -> Value.Fixed(0); 1 -> count; else -> Value.Times(count, n) }
            return Ability.Static(listOf(Mechanic.ModifyPowerToughness(per(m.groupValues[1].toInt()), per(m.groupValues[2].toInt()))),
                affects = Affected.Objects(Objects.AttachedTo(Objects.Self)))
        }
        // spm chunk 07: "All damage that would be dealt to you is dealt to enchanted creature instead." (CR 614.1a)
        if (Spm.ALL_DAMAGE_TO_YOU_TO_ENCHANTED.matches(line))
            return Ability.Static(listOf(Mechanic.Replacement(EventPattern.Damage(ObjectFilter.Any, arcanum.api.RecipientFilter(players = PlayerFilter.You)),
                modify = listOf(Modification.ChangeRecipient(arcanum.api.Recipients(objects = Objects.AttachedTo(Objects.Self)))))), affects = spmSelfOnly)
        // spm chunk 07: "If damage would be dealt to Anti-Venom, prevent that damage and put that many +1/+1 counters on him." (CR 615.5)
        Spm.PREVENT_DAMAGE_PUT_THAT_MANY_COUNTERS.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            return Ability.Static(listOf(Mechanic.Prevention(EventPattern.Damage(ObjectFilter.Any, arcanum.api.RecipientFilter(objects = ObjectFilter.Is(Objects.Self))),
                additional = Instructions(steps = listOf(Step.Do(Effect.PutCounters(Objects.Self, Counters.kind(m.groupValues[2]) ?: return null, Value.EventAmount)))))),
                affects = spmSelfOnly)
        }
        // spm chunk 07: "As Arachne enters, look at an opponent's hand, then choose a card type other than creature." (CR 614.12, 607.2d)
        Spm.LOOK_AT_OPPONENTS_HAND_CHOOSE_CARD_TYPE.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            // fdn chunk 08: "then choose any card name" (CR 201.3)
            if (m.groupValues[2].isEmpty()) return Ability.Static(listOf(Mechanic.Replacement(spmEntersSelf, modify = listOf(Modification.AsEnters(listOf(
                Step.Choose(arcanum.api.Choice.Player(PlayerFilter.Opponent), bind = "opponent", chooser = Players.You),
                Step.Do(Effect.LookAt(Objects.Each(Filters.all(ObjectFilter.InZone(Zone.Hand), ObjectFilter.OwnedBy(PlayerFilter.Is(Players.Bound("opponent"))))), Players.You)),
                Step.Choose(arcanum.api.Choice.CardName(ObjectFilter.Any), bind = CHOSEN_NAME, chooser = Players.You, remember = true)))))), affects = spmSelfOnly)
            val other = Filters.CARD_TYPES[m.groupValues[2]] ?: return null
            val among = listOf(CardType.Artifact, CardType.Battle, CardType.Creature, CardType.Enchantment, CardType.Instant, CardType.Kindred, CardType.Land,
                CardType.Planeswalker, CardType.Sorcery).filter { it != other }
            return Ability.Static(listOf(Mechanic.Replacement(spmEntersSelf, modify = listOf(Modification.AsEnters(listOf(
                Step.Choose(arcanum.api.Choice.Player(PlayerFilter.Opponent), bind = "opponent", chooser = Players.You),
                Step.Do(Effect.LookAt(Objects.Each(Filters.all(ObjectFilter.InZone(Zone.Hand), ObjectFilter.OwnedBy(PlayerFilter.Is(Players.Bound("opponent"))))), Players.You)),
                Step.Choose(arcanum.api.Choice.CardType(among), bind = CHOSEN_TYPE, chooser = Players.You, remember = true)))))), affects = spmSelfOnly)
        }
        // spm chunk 07: "Spells of the chosen type cost {1} more to cast." (CR 601.2f; the type chosen as it entered)
        Spm.SPELLS_OF_CHOSEN_TYPE_COST_MORE.matchEntire(line)?.let { m ->
            return Ability.Static(listOf(Mechanic.CostChange(Filters.all(ObjectFilter.Category(arcanum.api.ObjectCategory.Spell),
                ObjectFilter.Type(arcanum.api.CardTypeRef.Remembered(CHOSEN_TYPE))), arcanum.api.CostChange.More(ManaCost.parse(m.groupValues[1]) ?: return null, Value.Fixed(1)))),
                affects = spmSelfOnly)
        }
        // spm chunk 08: "You can't cast Spider-Man 2099 during your first, second, or third turns of the game." (CR 601.3)
        Spm.CANT_CAST_DURING_FIRST_TURNS.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            return Ability.Static(listOf(Mechanic.CastRestriction(condition = arcanum.api.Condition.Not(arcanum.api.Condition.And(listOf(arcanum.api.Condition.YourTurn,
                arcanum.api.Condition.Compare(Value.TurnsTaken(Players.You), arcanum.api.Comparison.AtMost, Value.Fixed(3))))))), affects = spmSelfOnly)
        }
        // spm chunk 08: 'The "legend rule" doesn't apply to Spiders you control.' (CR 704.5j)
        Spm.LEGEND_RULE_DOESNT_APPLY_TO.matchEntire(line)?.let { m ->
            val filter = Filters.noun(m.groupValues[1]) ?: SpmPhrases.pluralSubtype(m.groupValues[1])?.let { ObjectFilter.Sub(it) } ?: return null
            return Ability.Static(listOf(Mechanic.LegendRuleDoesntApply), affects = Affected.Objects(Objects.Each(Filters.all(filter, ObjectFilter.ControlledBy(PlayerFilter.You)))))
        }
        // spm chunk 07: "This spell costs {1} less to cast if it targets a Spider." (CR 601.2f: the spell's creature target)
        Spm.COSTS_LESS_IF_IT_TARGETS_SUBTYPE.matchEntire(line)?.let { m ->
            val subtype = m.groupValues[2].takeIf { it in RulesWords.subtypes } ?: return null
            return Ability.Static(listOf(Mechanic.CostChange(ObjectFilter.Is(Objects.Self), arcanum.api.CostChange.Less(ManaCost.parse(m.groupValues[1]) ?: return null, Value.Fixed(1)))),
                affects = spmSelfOnly, condition = arcanum.api.Condition.ObjectMatches(Objects.Target("creature"), ObjectFilter.Sub(Subtype(subtype))))
        }
        // spm chunk 08: "You don't lose unspent red mana as steps and phases end." (CR 500.4, 106.4)
        Spm.DONT_LOSE_UNSPENT_MANA.matchEntire(line)?.let { m ->
            val color = Tokens.color(m.groupValues[1]) ?: return null
            return Ability.Static(listOf(Mechanic.KeepsUnspentMana(listOf(color))), affects = Affected.Players(Players.You))
        }
        // spm chunk 08: "Spells and abilities can't be countered." (CR 701.6)
        if (Spm.SPELLS_AND_ABILITIES_CANT_BE_COUNTERED.matches(line))
            return Ability.Static(listOf(Mechanic.CantBeCountered), affects = Affected.Objects(Objects.Each(ObjectFilter.Or(listOf(
                ObjectFilter.Category(arcanum.api.ObjectCategory.Spell), ObjectFilter.Category(arcanum.api.ObjectCategory.StackAbility))))))
        // spm chunk 08: "As this land enters, choose a basic land type. Then you may pay 2 life. If you don't, it enters tapped." (CR 614.12)
        Spm.CHOOSE_BASIC_LAND_TYPE_THEN_MAY_PAY_LIFE.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            return Ability.Static(listOf(Mechanic.Replacement(spmEntersSelf, modify = listOf(Modification.AsEnters(
                listOf(Step.Choose(arcanum.api.Choice.BasicLandType, bind = CHOSEN_TYPE, chooser = Players.You, remember = true)) +
                    unlessPays(Players.You, Cost(listOf(CostPart.PayLife(Value.Fixed(m.groupValues[2].toInt())))), listOf(Step.Modify(Modification.EntersTapped))))))),
                affects = spmSelfOnly)
        }
        // spm chunk 08: "This land is the chosen type." (layer 4; it had no land types, so the type is added, CR 305.7)
        Spm.IS_THE_CHOSEN_TYPE.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            return Ability.Static(listOf(Mechanic.SetTypes(addSubtypes = listOf(arcanum.api.SubtypeRef.Remembered(CHOSEN_TYPE)))), affects = spmSelfOnly)
        }
        // spm chunk 08: "Other Spiders, Boars, Bats, …, and Wolves you control get +1/+1." (each permanent of any of those creature types)
        Spm.OTHER_PLURAL_LIST_GET.matchEntire(line)?.let { m ->
            val types = m.groupValues[1].split(LazyRegexes.AND_LIST).map { SpmPhrases.pluralSubtype(it.trim()) ?: return null }
            return Ability.Static(listOf(Mechanic.ModifyPowerToughness(ptChange(m.groupValues[2]) ?: return null, ptChange(m.groupValues[3]) ?: return null)),
                affects = Affected.Objects(Objects.Each(Filters.all(ObjectFilter.Not(ObjectFilter.Is(Objects.Self)), ObjectFilter.Or(types.map { ObjectFilter.Sub(it) }),
                    ObjectFilter.ControlledBy(PlayerFilter.You)))))
        }
        return null
    }

    /** spm: trigger events (with a condition checked as it would trigger), tried first in [trigger]. */
    private fun spmTrigger(text: String): Pair<arcanum.api.Trigger.On, arcanum.api.Condition?>? {
        SpmPhrases.events(text)?.let { return arcanum.api.Trigger.On(it) to null }
        // spm chunk 04: "you cast a creature spell with mana value equal to Jackal's power" (its power as the spell is cast)
        CAST_MV_EQUAL_TO_POWER.matchEntire(text)?.takeIf { isSelf(it.groupValues[2]) }?.let { m ->
            val spell = Filters.noun(m.groupValues[1] + " spell") ?: return null
            return arcanum.api.Trigger.On(EventPattern.Cast(Filters.all(spell, ObjectFilter.ManaValue(arcanum.api.Comparison.Equal, spmPower(Objects.Self))), PlayerFilter.You)) to null
        }
        // spm chunk 03: "you draw your first or second card each turn" (CR 121.2: each card drawn is a draw)
        if (text == "you draw your first or second card each turn")
            return arcanum.api.Trigger.On(listOf(EventPattern.Draw(PlayerFilter.You)), nthThisTurn = 2, throughNth = true) to null
        // spm chunk 07: "you attack with two or more Spiders" (once for the attack, CR 508.1)
        ATTACK_WITH_N_OR_MORE.matchEntire(text)?.let { m ->
            val n = spmN(m.groupValues[1])?.takeIf { it >= 2 } ?: return null
            val noun = SpmPhrases.pluralSubtype(m.groupValues[2])?.let { ObjectFilter.Sub(it) } ?: Filters.noun(m.groupValues[2].removeSuffix("s")) ?: return null
            return arcanum.api.Trigger.On(listOf(EventPattern.Attack(Filters.all(noun, ObjectFilter.ControlledBy(PlayerFilter.You)))), oneOrMore = true, atLeast = n) to null
        }
        // spm chunk 07: "Spinneret and Spiderling deals 4 or more damage" (the damage it deals at once, to any recipients)
        DEALS_N_OR_MORE_DAMAGE.matchEntire(text)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            return arcanum.api.Trigger.On(listOf(EventPattern.Damage(ObjectFilter.Is(Objects.Self), arcanum.api.RecipientFilter())), oneOrMore = true) to
                arcanum.api.Condition.Compare(Value.EventAmount, arcanum.api.Comparison.AtLeast, Value.Fixed(m.groupValues[2].toInt()))
        }
        // spm chunk 08: "this land enters from a graveyard"
        ENTERS_FROM_A.matchEntire(text)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val zone = when (m.groupValues[2]) { "graveyard" -> Zone.Graveyard; "exile" -> Zone.Exile; else -> return null }
            return arcanum.api.Trigger.On(EventPattern.ZoneChange(ObjectFilter.Is(Objects.Self), from = zone, to = Zone.Battlefield)) to null
        }
        // spm chunk 06: "a creature an opponent controls with the greatest power among creatures that player controls dies" (its power as it
        // last existed against the creatures an opponent still controls; in a two-player game, that player's)
        if (text == "a creature an opponent controls with the greatest power among creatures that player controls dies") {
            val theirs = Filters.all(ObjectFilter.Type(CardType.Creature), ObjectFilter.ControlledBy(PlayerFilter.Opponent))
            return arcanum.api.Trigger.On(EventPattern.ZoneChange(Filters.all(theirs, ObjectFilter.Power(arcanum.api.Comparison.AtLeast,
                Value.Of(arcanum.api.NumericProperty.Power, Objects.Each(theirs), arcanum.api.Combine.Greatest))), from = Zone.Battlefield, to = Zone.Graveyard)) to null
        }
        return null
    }

    /** spm: a triggered ability with modes, "choose one or both —" (CR 700.2). */
    private fun spmModalTrigger(header: String, modeLines: List<String>): Ability? {
        val m = WHENEVER.matchEntire(header) ?: return null
        if (!Spm.CHOOSE_ONE_OR_BOTH_MODES.matches(m.groupValues[3])) return null
        val (trigger, onlyIf) = trigger(m.groupValues[2]) ?: return null
        val options = spmDistinctSlots(modeLines.map { arcanum.api.Mode(instructions(modeBody(it), that = that(trigger)) ?: return null, text = it) })
        if (options.size != 2) return null
        return Ability.Triggered(trigger, Instructions(modes = arcanum.api.Modes(options, min = 1, max = 2, chooser = Players.You)), triggersOnlyIf = onlyIf)
    }

    /** spm chunk 04: modes that may all be chosen keep their targets apart: a slot named as an earlier mode's gets the next name
     * ("Tap target creature" and "Untap target creature": "creature" and "second creature", CR 700.2, 601.2c). */
    private fun spmDistinctSlots(options: List<arcanum.api.Mode>): List<arcanum.api.Mode> {
        val taken = mutableListOf<String>()
        return options.map { mode ->
            var instructions = mode.instructions
            instructions.targets.forEach { slot ->
                if (slot.name in taken) {
                    val renamed = nextTargetName(slot.name, taken + instructions.targets.map { it.name })
                    instructions = instructions.copy(targets = instructions.targets.map { if (it.name == slot.name) it.copy(name = renamed) else it },
                        steps = instructions.steps.map { renameTargetSlot(it, slot.name, renamed) })
                    taken += renamed
                } else taken += slot.name
            }
            mode.copy(instructions = instructions)
        }
    }

    /** spm: "Spend this mana only to cast spells from exile." (CR 106.6) */
    private fun spmSpendUse(use: String): ObjectFilter? = when (use) {
        "cast spells from exile" -> Filters.all(ObjectFilter.Category(arcanum.api.ObjectCategory.Spell), ObjectFilter.WasCast(Zone.Exile))
        else -> null
    }

    /** spm: sentences that change the steps before them. */
    private fun spmModify(sentence: String, steps: List<Step>, context: Context): List<Step>? {
        // spm chunk 01: "If this spell's mayhem cost was paid, creatures your opponents control get -2/-2 until end of turn instead." (CR 607.2i)
        Spm.IF_COST_PAID_INSTEAD.matchEntire(sentence)?.let { m ->
            val kind = arcanum.api.KeywordKind.all.firstOrNull { it.text.lowercase() == m.groupValues[1] } ?: return null
            val last = steps.lastOrNull() ?: return null
            val instead = effect(spmCap(m.groupValues[2]) + ".", context) ?: return null
            return steps.dropLast(1) + Step.If(arcanum.api.Condition.Paid(kind, times = 1, of = Objects.Self), then = instead, otherwise = listOf(last))
        }
        // spm chunk 07: "When excess damage is dealt to the creature an opponent controls this way, destroy up to one target noncreature artifact
        // with mana value 3 or less." (after a fight: the damage dealt to the second creature, CR 120.4a; a reflexive trigger, CR 603.12)
        Spm.WHEN_EXCESS_DAMAGE_THIS_WAY_DESTROY.matchEntire(sentence)?.let { m ->
            val fight = (steps.lastOrNull() as? Step.Do)?.effect as? Effect.Fight ?: return null
            val destroyed = Filters.noun(m.groupValues[2]) ?: return null
            val name = Filters.slotName(m.groupValues[2])
            val reflexive = Instructions(targets = listOf(spmSlot(name, destroyed, min = 0)), steps = listOf(Step.Do(Effect.Destroy(Objects.Target(name)))))
            return steps.dropLast(1) + Step.Do(fight.copy(bind = "fight")) + Step.If(arcanum.api.Condition.Compare(Value.Excess("fight"),
                arcanum.api.Comparison.Greater, Value.Fixed(0)), then = listOf(Step.Do(Effect.ReflexiveTrigger(reflexive))))
        }
        // spm chunk 07: "If it's a Spider, you gain 2 life." (the target, as the spell resolves)
        Spm.IF_ITS_A.matchEntire(sentence)?.let { m ->
            // inr chunk 16: a sentence before has said which object "it" is (the card returned from exile, CR 400.7)
            val it = context.it ?: context.targets.lastOrNull()?.takeIf { it.what is TargetKind.Objects }?.let { Objects.Target(it.name) } ?: return null
            val subtype = m.groupValues[1].takeIf { s -> s in RulesWords.subtypes } ?: return null
            val then = effect(spmCap(m.groupValues[2]), context) ?: return null
            return steps + Step.If(arcanum.api.Condition.ObjectMatches(it, ObjectFilter.Sub(Subtype(subtype))), then = then)
        }
        // spm chunk 03: "It becomes a legendary Spider Hero in addition to its other types." (indefinitely, layer 4)
        Spm.IT_BECOMES_TYPES_IN_ADDITION.matchEntire(sentence)?.let { m ->
            val it = context.targets.lastOrNull()?.takeIf { it.what is TargetKind.Objects }?.let { Objects.Target(it.name) } ?: return null
            return steps + spmApply(it, arcanum.api.Duration.Indefinitely, Mechanic.SetTypes(addSubtypes = spmSubtypes(m.groupValues[2]) ?: return null,
                addSupertypes = if (m.groupValues[1].isNotEmpty()) listOf(Supertype.Legendary) else emptyList()))
        }
        // spm chunk 03: "He gains hexproof and becomes colorless until end of turn." (after a counter is put on this object)
        Spm.GAINS_AND_BECOMES_COLORLESS.matchEntire(sentence)?.let { m ->
            val put = (steps.lastOrNull() as? Step.Do)?.effect as? Effect.PutCounters ?: return null
            return steps + spmApply(put.objects, arcanum.api.Duration.EndOfTurn, Mechanic.GainAbilities(keywords(m.groupValues[1]) ?: return null),
                Mechanic.SetColors(emptyList()))
        }
        // spm chunk 03: 'Until your next turn, he becomes a land and gains "{T}: Add {U}."' (after "untap Hydro-Man"; CR 205.1b: no longer a
        // creature, layer 4; the ability, layer 6)
        Spm.BECOMES_LAND_AND_GAINS.matchEntire(sentence)?.let { m ->
            val untap = (steps.lastOrNull() as? Step.Do)?.effect as? Effect.Untap ?: return null
            val granted = Sentences(setOf("this land", "this creature")).line(m.groupValues[1]) ?: return null
            return steps + spmApply(untap.objects, arcanum.api.Duration.UntilYourNextTurn, Mechanic.SetTypes(add = listOf(CardType.Land), replaceTypes = true),
                Mechanic.GainAbilities(listOf(granted)))
        }
        // spm chunk 06: "It gains this card's other abilities." (after a counter is put on the target; written out by [OracleParser] with the
        // face's other abilities, CR 113.10)
        if (sentence == "It gains this card's other abilities.") {
            val put = (steps.lastOrNull() as? Step.Do)?.effect as? Effect.PutCounters ?: return null
            return steps + spmApply(put.objects, arcanum.api.Duration.Indefinitely, Mechanic.GainAbilities(emptyList()))
        }
        // spm chunk 06: "You may play that card for as long as you control this creature." (after exiling a card)
        Spm.MAY_PLAY_THAT_CARD_AS_LONG_AS_YOU_CONTROL.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            val moved = (steps.lastOrNull() as? Step.Do)?.effect as? Effect.Move ?: return null
            val card = moved.postBind?.let { Objects.Bound(it) } ?: return null
            return steps + Step.Do(Effect.ApplyMechanics(listOf(Mechanic.MayPlay(Zone.Exile, PlayKind.Play, holder = PlayerFilter.You)), Affected.Objects(card),
                arcanum.api.Duration.AsLongAs(arcanum.api.Condition.ObjectMatches(Objects.Self, ObjectFilter.ControlledBy(PlayerFilter.You)))))
        }
        // spm chunk 07: 'It gains "This creature attacks each combat if able" and "When this creature deals combat damage to a player, sacrifice
        // it."' (the card returned to the battlefield, indefinitely, layer 6)
        Spm.GAINS_QUOTED_AND_QUOTED.matchEntire(sentence)?.let { m ->
            val moved = (steps.lastOrNull() as? Step.Do)?.effect as? Effect.Move ?: return null
            if (moved.to.zone != Zone.Battlefield) return null
            val inner = Sentences(setOf("this creature"))
            val abilities = listOf(m.groupValues[1], m.groupValues[2]).map { q -> val t = (if (q.endsWith(".")) q else "$q.").replace(", sacrifice it.", ", sacrifice this creature."); inner.line(t) ?: return null }
            val bound = moved.postBind ?: "returned"
            return steps.dropLast(1) + Step.Do(moved.copy(postBind = bound)) +
                spmApply(Objects.Bound(bound), arcanum.api.Duration.Indefinitely, Mechanic.GainAbilities(abilities))
        }
        return null
    }

    /** spm: texts of several sentences read as a whole, tried first in [read]. */
    private fun spmWhole(text: String, context: Context): List<Step>? {
        // spm chunk 06: "Create a 3/3 blue Illusion Villain creature token for each nontoken Villain you control. Exile those tokens when
        // Mysterio leaves the battlefield." (a delayed trigger, CR 603.7)
        Spm.CREATE_FOR_EACH_EXILE_WHEN_LEAVES.matchEntire(text)?.takeIf { isSelf(it.groupValues[3]) }?.let { m ->
            val token = Tokens.defined(m.groupValues[1]) ?: return null
            val count = Value.Count(Filters.objects(m.groupValues[2]) ?: return null)
            return listOf(Step.Do(Effect.CreateToken(token, count, Players.You, bind = "tokens")),
                Step.Do(Effect.CreateDelayedTrigger(arcanum.api.Trigger.On(EventPattern.ZoneChange(ObjectFilter.Is(Objects.Self), from = Zone.Battlefield)),
                    Instructions(steps = listOf(Step.Do(Effect.Move(Objects.Bound("tokens"), Destination(Zone.Exile))))))))
        }
        // spm chunk 04: "Choose a card name. Whenever a creature with the chosen name deals combat damage to a player this turn, draw a card."
        // (CR 603.7b: a delayed trigger that triggers each time)
        Spm.CHOOSE_NAME_DAMAGE_TRIGGER_THIS_TURN.matchEntire(text)?.let { m ->
            val then = Sentences(self).instructions(spmCap(m.groupValues[2])) ?: return null
            return listOf(Step.Choose(arcanum.api.Choice.CardName(ObjectFilter.Any), bind = "name", chooser = Players.You),
                Step.Do(Effect.CreateDelayedTrigger(arcanum.api.Trigger.On(EventPattern.Damage(Filters.all(ObjectFilter.Type(CardType.Creature), ObjectFilter.ChosenName("name")),
                    arcanum.api.RecipientFilter(players = PlayerFilter.Any), combat = true)), then, duration = arcanum.api.Duration.EndOfTurn, repeats = true)))
        }
        // spm chunk 04: "you may copy it. If you do, you may choose new targets for the copy. If the copy is a permanent spell, it gains haste."
        // (CR 707.10, 707.10c: a copy of a permanent spell becomes a token; haste for the spell and the permanent, CR 400.7d)
        if (Spm.MAY_COPY_FROM_ELSEWHERE_HASTE.matches(text)) {
            val copy = Objects.Bound("copy")
            return listOf(Step.Pay(steps = listOf(Step.Do(Effect.CopySpell(Objects.EventObject(EventRole.Object), Players.You, newTargets = true, bind = "copy"))),
                payer = Players.You, bind = "paid"),
                Step.If(arcanum.api.Condition.And(listOf(arcanum.api.Condition.Did("paid"), arcanum.api.Condition.ObjectMatches(copy, Filters.noun("permanent card")!!))),
                    then = listOf(Step.Do(Effect.SpellGets(copy, listOf(Mechanic.GainAbilities(listOf(arcanum.api.Keyword.Haste))))))))
        }
        // spm chunk 05: "Look at the top five cards of your library. You may reveal up to two creature cards from among them and put them into
        // your hand. Put the rest on the bottom of your library in a random order."
        Spm.LOOK_TOP_N_MAY_REVEAL_UP_TO_PUT_HAND.matchEntire(text)?.let { m ->
            val seen = spmN(m.groupValues[1]) ?: return null
            val most = spmN(m.groupValues[2]) ?: return null
            val filter = Filters.noun(m.groupValues[3]) ?: Filters.noun(m.groupValues[3].removeSuffix("s")) ?: return null
            return listOf(
                Step.Do(Effect.LookAt(Objects.LibraryCards(Players.You, Value.Fixed(seen), fromTop = true), bind = "seen", players = Players.You)),
                Step.Choose(arcanum.api.Choice.Objects(filter, Value.Fixed(0), Value.Fixed(most), from = Objects.Bound("seen")), bind = "revealed", chooser = Players.You),
                Step.Do(Effect.Reveal(Objects.Bound("revealed"))),
                Step.Do(Effect.Move(Objects.Bound("revealed"), Destination(Zone.Hand))),
                Step.Do(Effect.Move(Objects.Except(Objects.Bound("seen"), Objects.Bound("revealed")), Destination(Zone.Library, libraryPosition = -1, randomOrder = true))))
        }
        // spm chunk 05: "Look at the top five cards of your library. You may put a creature card from among them onto the battlefield. Put the
        // rest on the bottom of your library in a random order."
        // (the names tla gives the same wording)
        Spm.LOOK_TOP_N_MAY_PUT_ONTO_BATTLEFIELD.matchEntire(text)?.let { m ->
            val seen = spmN(m.groupValues[1]) ?: return null
            val filter = Filters.noun(m.groupValues[2]) ?: return null
            return listOf(
                Step.Do(Effect.LookAt(Objects.LibraryCards(Players.You, Value.Fixed(seen), fromTop = true), bind = "looked", players = Players.You)),
                Step.Choose(arcanum.api.Choice.Objects(filter, Value.Fixed(0), Value.Fixed(1), from = Objects.Bound("looked")), bind = "chosen", chooser = Players.You),
                Step.Do(Effect.Move(Objects.Bound("chosen"), Destination(Zone.Battlefield))),
                Step.Do(Effect.Move(Objects.Except(Objects.Bound("looked"), Objects.Bound("chosen")), Destination(Zone.Library, libraryPosition = -1, randomOrder = true))))
        }
        // spm chunk 05: "look at that many cards from the top of your library. Put one of them into your hand and the rest into your
        // graveyard." (the damage dealt)
        if (Spm.LOOK_THAT_MANY_ONE_HAND_REST_GRAVEYARD.matches(text) && context.event is EventPattern.Damage)
            return listOf(
                Step.Do(Effect.LookAt(Objects.LibraryCards(Players.You, Value.EventAmount, fromTop = true), bind = "seen", players = Players.You)),
                Step.Choose(arcanum.api.Choice.Objects(ObjectFilter.Any, Value.Fixed(1), Value.Fixed(1), from = Objects.Bound("seen")), bind = "kept", chooser = Players.You),
                Step.Do(Effect.Move(Objects.Bound("kept"), Destination(Zone.Hand))),
                Step.Do(Effect.Move(Objects.Except(Objects.Bound("seen"), Objects.Bound("kept")), Destination(Zone.Graveyard))))
        // spm chunk 06: "look at the top nine cards of target opponent's library, exile two of them face down, then put the rest on the bottom
        // of their library in a random order. You may play the exiled cards for as long as they remain exiled. Mana of any type can be spent to
        // cast spells this way." (CR 406.3; the permission and the mana rule go with those cards, CR 601.2a, 609.4b)
        Spm.BLACK_CAT.matchEntire(text)?.let { m ->
            val seen = spmN(m.groupValues[1]) ?: return null
            val n = spmN(m.groupValues[2]) ?: return null
            val opponent = context.targetOpponent()
            val playerOf = (opponent as? Players.Target) ?: return null
            return listOf(
                Step.Do(Effect.LookAt(Objects.LibraryCards(playerOf, Value.Fixed(seen), fromTop = true), bind = "seen", players = Players.You)),
                Step.Choose(arcanum.api.Choice.Objects(ObjectFilter.Any, Value.Fixed(n), Value.Fixed(n), from = Objects.Bound("seen")), bind = "chosen", chooser = Players.You),
                Step.Do(Effect.Move(Objects.Bound("chosen"), Destination(Zone.Exile, faceDown = true), postBind = "exiled")),
                Step.Do(Effect.Move(Objects.Except(Objects.Bound("seen"), Objects.Bound("chosen")), Destination(Zone.Library, libraryPosition = -1, randomOrder = true))),
                Step.Do(Effect.ApplyMechanics(listOf(Mechanic.MayPlay(Zone.Exile, PlayKind.Play, holder = PlayerFilter.You, manaAsAnyColor = true)),
                    Affected.Objects(Objects.Bound("exiled")), arcanum.api.Duration.Indefinitely)))
        }
        // spm chunk 06: "you may sacrifice another creature. If you do, draw X cards, then you may put a permanent card with mana value X or
        // less from your hand onto the battlefield, where X is the sacrificed creature's mana value." (its last known information, CR 608.2h)
        Spm.MAY_SACRIFICE_DRAW_X_PUT_PERMANENT.matchEntire(text)?.let { m ->
            val filter = Filters.noun(m.groupValues[1]) ?: return null
            val x = Value.Of(arcanum.api.NumericProperty.ManaValue, Objects.Bound(SACRIFICED), arcanum.api.Combine.Single)
            return listOf(
                Step.Pay(Cost(listOf(CostPart.Sacrifice(CostObjects.Choose(Filters.all(ObjectFilter.Type(CardType.Creature), ObjectFilter.ControlledBy(PlayerFilter.You),
                    ObjectFilter.Not(ObjectFilter.Is(Objects.Self))), Value.Fixed(1)), preBind = SACRIFICED))), payer = Players.You, bind = "paid"),
                Step.If(arcanum.api.Condition.Did("paid"), then = listOf(
                    Step.Do(Effect.Draw(Players.You, x)),
                    Step.Choose(arcanum.api.Choice.Objects(Filters.all(filter, ObjectFilter.InZone(Zone.Hand), ObjectFilter.OwnedBy(PlayerFilter.You),
                        ObjectFilter.ManaValue(arcanum.api.Comparison.AtMost, x)), Value.Fixed(0), Value.Fixed(1)), bind = "chosen", chooser = Players.You),
                    Step.Do(Effect.Move(Objects.Bound("chosen"), Destination(Zone.Battlefield))))))
        }
        // spm chunk 06: "until end of turn, you may look at the top card of your library any time and you may play cards from the top of your
        // library. If you cast a spell this way, pay life equal to its mana value rather than pay its mana cost." (CR 118.9, 305.1)
        if (Spm.GWENOM.matches(text)) {
            val top = Filters.all(ObjectFilter.InZone(Zone.Library), ObjectFilter.OwnedBy(PlayerFilter.You))
            val eot = arcanum.api.Duration.EndOfTurn
            return listOf(
                Step.Do(Effect.ApplyMechanics(listOf(Mechanic.MayLookAt(Objects.LibraryCards(Players.You, Value.Fixed(1), fromTop = true))), Affected.Players(Players.You), eot)),
                Step.Do(Effect.ApplyMechanics(listOf(Mechanic.MayPlay(Zone.Library, PlayKind.Play, topOnly = true, holder = PlayerFilter.You)),
                    Affected.Objects(Objects.Each(Filters.all(ObjectFilter.Type(CardType.Land), top))), eot)),
                Step.Do(Effect.ApplyMechanics(listOf(Mechanic.MayPlay(Zone.Library, PlayKind.Cast, topOnly = true, holder = PlayerFilter.You,
                    cost = Cost(listOf(CostPart.PayLife(Value.Of(arcanum.api.NumericProperty.ManaValue, Objects.Affected, arcanum.api.Combine.Single)))))),
                    Affected.Objects(Objects.Each(Filters.all(ObjectFilter.Not(ObjectFilter.Type(CardType.Land)), top))), eot)))
        }
        // spm chunk 06: "Two target players each reveal the top card of their library. They each lose life equal to the mana value of the card
        // revealed by the other player. Then they each put the card they revealed into their hand." (a library holds only its owner's cards,
        // CR 400.3)
        Spm.PARKER_LUCK.matchEntire(text)?.let { m ->
            val n = spmN(m.groupValues[1]) ?: return null
            context.targets += TargetSlot("players", TargetKind.Players(PlayerFilter.Any), min = Value.Fixed(n), max = Value.Fixed(n))
            val players = Players.Target("players")
            val revealed = Objects.Bound("revealed")
            return listOf(
                Step.Do(Effect.Reveal(Objects.LibraryCards(players, Value.Fixed(1), fromTop = true), bind = "revealed")),
                Step.ForEach(arcanum.api.Each.Players(players), bind = "player", together = true, steps = listOf(
                    Step.Do(Effect.LoseLife(Players.Bound("player"), Value.Of(arcanum.api.NumericProperty.ManaValue,
                        Objects.Where(revealed, ObjectFilter.Not(ObjectFilter.OwnedBy(PlayerFilter.Is(Players.Bound("player"))))), arcanum.api.Combine.Total))))),
                Step.Do(Effect.Move(revealed, Destination(Zone.Hand))))
        }
        // spm chunk 06: "Each player may discard a card. Each player who doesn't loses 3 life." (CR 101.4)
        Spm.EACH_PLAYER_MAY_DISCARD_WHO_DOESNT_LOSES.matchEntire(text)?.let { m ->
            return listOf(Step.ForEach(arcanum.api.Each.Players(Players.Each(PlayerFilter.Any)), bind = "player", together = true, steps = listOf(
                Step.Pay(Cost(costPart("Discard a card") ?: return null), payer = Players.Bound("player"), bind = "paid"),
                Step.If(arcanum.api.Condition.Not(arcanum.api.Condition.Did("paid")), then = listOf(
                    Step.Do(Effect.LoseLife(Players.Bound("player"), Value.Fixed(m.groupValues[1].toInt()))))))))
        }
        // spm chunk 06: "Put a +1/+1 counter on it. Then surveil X, where X is the number of counters on it." (the attacking creature)
        if (Spm.PUT_COUNTER_THEN_SURVEIL_COUNTERS_ON_IT.matches(text)) {
            val it = context.it ?: return null
            return listOf(Step.Do(Effect.PutCounters(it, spmP1P1, Value.Fixed(1))),
                Step.Do(Effect.Surveil(Players.You, Value.Of(arcanum.api.NumericProperty.Counters(null), it, arcanum.api.Combine.Single))))
        }
        // spm chunk 06: "Exile X target artifacts and/or creatures. Return the exiled cards to the battlefield under their owners' control at the
        // beginning of the next end step." (CR 603.7)
        Spm.EXILE_X_TARGETS_RETURN_NEXT_END_STEP.matchEntire(text)?.let { m ->
            val filter = Filters.noun(m.groupValues[1]) ?: Filters.noun(m.groupValues[1].replace("s and/or ", " or ").removeSuffix("s")) ?: return null
            context.targets += TargetSlot("targets", TargetKind.Objects(filter), min = Value.Announced("X"), max = Value.Announced("X"))
            return listOf(Step.Do(Effect.Move(Objects.Target("targets"), Destination(Zone.Exile), postBind = "exiled")),
                Step.Do(Effect.CreateDelayedTrigger(arcanum.api.Trigger.On(EventPattern.StepBegins(arcanum.api.TurnStep.End, PlayerFilter.Any)), Instructions(steps = listOf(
                    Step.Do(Effect.Move(Objects.Bound("exiled"), Destination(Zone.Battlefield, controller = Players.OwnerOf(Objects.Bound("exiled"))))))))))
        }
        // spm chunk 06: "you may exchange life totals with target opponent. If you lost life this way, draw that many cards." (CR 701.12c:
        // after the exchange, the difference is what you lost)
        if (Spm.MAY_EXCHANGE_LIFE_DRAW_LOST.matches(text)) {
            val opponent = context.targetOpponent()
            val lost = Value.Difference(Value.LifeOf(opponent), Value.LifeOf(Players.You))
            return listOf(Step.Pay(steps = listOf(Step.Do(Effect.ExchangeLife(Players.You, opponent))), payer = Players.You, bind = "paid"),
                Step.If(arcanum.api.Condition.And(listOf(arcanum.api.Condition.Did("paid"), arcanum.api.Condition.Compare(lost, arcanum.api.Comparison.Greater, Value.Fixed(0)))),
                    then = listOf(Step.Do(Effect.Draw(Players.You, lost)))))
        }
        // spm chunk 06: "you may exile the top card of your library. If you do, you may play that card until you exile another card with this
        // creature." (the card is kept as this object's card memory; the permission ends when another replaces it, CR 607.2a)
        Spm.SUPERIOR_FOES.matchEntire(text)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            return listOf(Step.Pay(steps = listOf(Step.Do(Effect.Move(Objects.LibraryCards(Players.You, Value.Fixed(1), fromTop = true), Destination(Zone.Exile),
                postBind = "exiled"))), payer = Players.You, bind = "paid"),
                Step.If(arcanum.api.Condition.Did("paid"), then = listOf(
                    Step.Do(Effect.Remember(EXILED_WITH, Objects.Bound("exiled"), replace = true)),
                    Step.Do(Effect.ApplyMechanics(listOf(Mechanic.MayPlay(Zone.Exile, PlayKind.Play, holder = PlayerFilter.You)), Affected.Objects(Objects.Bound("exiled")),
                        arcanum.api.Duration.AsLongAs(arcanum.api.Condition.ObjectMatches(Objects.Bound("exiled"), ObjectFilter.Is(Objects.Remembered(EXILED_WITH)))))))))
        }
        // spm chunk 06: "Put him on the bottom of his owner's library. If you do, return the exiled cards to their owners' hands." (the card in
        // the graveyard; the cards its enters ability exiled, CR 607.2a)
        if (Spm.PUT_SELF_ON_BOTTOM_IF_YOU_DO_RETURN_EXILED.matches(text) && context.event is EventPattern.ZoneChange) {
            // CR 608.2c: "if you do" asks whether it was put there (the card may have left the graveyard meanwhile), not whether the step was tried
            // CR 608.2c: "if you do" asks whether it was put there (the card may have left the graveyard meanwhile), not whether the step was tried
            return listOf(Step.Do(Effect.Move(Objects.EventObject(EventRole.After), Destination(Zone.Library, libraryPosition = -1), postBind = "bottomed")),
                Step.If(arcanum.api.Condition.NonEmpty("bottomed"), then = listOf(Step.Do(Effect.Move(Objects.Remembered(EXILED_WITH), Destination(Zone.Hand))))))
        }
        // spm chunk 07: "Target creature deals damage equal to its power to itself. If that creature is attacking, Wisecrack deals 2 damage to
        // that creature's controller."
        Spm.TARGET_DEALS_DAMAGE_TO_ITSELF_IF_ATTACKING.matchEntire(text)?.takeIf { isSelf(it.groupValues[2]) }?.let { m ->
            val name = spmNewSlotName(context, Filters.slotName(m.groupValues[1]))
            context.targets += spmSlot(name, Filters.noun(m.groupValues[1]) ?: return null)
            val t = Objects.Target(name)
            return listOf(Step.Do(Effect.DealDamage(arcanum.api.Recipients(objects = t), spmPower(t), source = t)),
                Step.If(arcanum.api.Condition.ObjectMatches(t, ObjectFilter.HasStatus(arcanum.api.Status.Attacking)), then = listOf(
                    Step.Do(Effect.DealDamage(arcanum.api.Recipients(players = Players.ControllerOf(t)), Value.Fixed(m.groupValues[3].toInt()), source = Objects.Self)))))
        }
        // spm chunk 06: "You may pay {X}. When you do, he deals X damage to target player." (X chosen as the cost is paid, CR 107.3a; a
        // reflexive trigger, CR 603.12)
        PAY_X_WHEN_YOU_DO.matchEntire(text)?.let { m ->
            val reflexive = instructions(spmCap(m.groupValues[1]), event = context.event)?.withX(Value.Bound("X")) ?: return null
            return listOf(Step.Choose(arcanum.api.Choice.Number(Value.Fixed(0)), bind = "X", chooser = Players.You),
                Step.Pay(Cost(listOf(CostPart.Mana(ManaCost.parse("{X}")!!, x = Value.Bound("X")))), payer = Players.You, bind = "paid"),
                Step.If(arcanum.api.Condition.Did("paid"), then = listOf(Step.Do(Effect.ReflexiveTrigger(reflexive)))))
        }
        // spm chunk 08: "Copy target activated or triggered ability you control. You may choose new targets for the copy." (CR 707.10)
        if (text == "Copy target activated or triggered ability you control. You may choose new targets for the copy.") {
            context.targets += spmSlot("ability", Filters.all(ObjectFilter.Or(listOf(ObjectFilter.AbilityOf(kind = arcanum.api.AbilityKind.Activated),
                ObjectFilter.AbilityOf(kind = arcanum.api.AbilityKind.Triggered))), ObjectFilter.ControlledBy(PlayerFilter.You)))
            return listOf(Step.Do(Effect.CopySpell(Objects.Target("ability"), Players.You, newTargets = true)))
        }
        return null
    }

    /** spm: effect sentences, tried first in [effect]. */
    private fun spmEffect(sentence: String, context: Context): List<Step>? {
        // spm chunk 02: "put its +1/+1 counters on target creature you control" (this creature as it last existed, CR 603.10a)
        Spm.PUT_ITS_COUNTERS_ON_TARGET.matchEntire(sentence)?.let { m ->
            val event = context.event as? EventPattern.ZoneChange ?: return null
            if (event.objects != ObjectFilter.Is(Objects.Self) || event.from != Zone.Battlefield) return null
            val kind = Counters.kind(m.groupValues[1]) ?: return null
            val name = spmNewSlotName(context, Filters.slotName(m.groupValues[2]))
            context.targets += spmSlot(name, Filters.noun(m.groupValues[2]) ?: return null)
            return listOf(Step.Do(Effect.PutCounters(Objects.Target(name), kind,
                Value.Of(arcanum.api.NumericProperty.Counters(kind), Objects.EventObject(EventRole.Before), arcanum.api.Combine.Single))))
        }
        // spm chunk 03: "Until end of turn, target creature you control becomes a Citizen with base power and toughness 1/1 and gains hexproof."
        // (layers 4, 6, 7b; the creature type replaces the others, CR 205.1b)
        Spm.UNTIL_EOT_BECOMES_SUBTYPE_BASE_PT_GAINS.matchEntire(sentence)?.let { m ->
            val subtype = m.groupValues[2].takeIf { it in RulesWords.subtypes } ?: return null
            val name = spmNewSlotName(context, Filters.slotName(m.groupValues[1]))
            context.targets += spmSlot(name, Filters.noun(m.groupValues[1]) ?: return null)
            return listOf(spmApply(Objects.Target(name), arcanum.api.Duration.EndOfTurn,
                Mechanic.SetTypes(addSubtypes = listOf(arcanum.api.SubtypeRef.Literal(Subtype(subtype))), replaceSubtypes = true),
                Mechanic.SetPowerToughness(Value.Fixed(m.groupValues[3].toInt()), Value.Fixed(m.groupValues[4].toInt())),
                Mechanic.GainAbilities(keywords(m.groupValues[5]) ?: return null)))
        }
        // spm chunk 03: "up to one other target creature loses all abilities and becomes a green Lizard creature with base power and toughness
        // 4/4." (indefinitely; layers 4, 5, 6, 7b, CR 205.1b)
        Spm.LOSES_ALL_BECOMES_COLOR_CREATURE.matchEntire(sentence)?.let { m ->
            val objects = spmTargetSubject(m.groupValues[1], context) ?: return null
            val subtype = m.groupValues[3].takeIf { it in RulesWords.subtypes } ?: return null
            return listOf(spmApply(objects, arcanum.api.Duration.Indefinitely, Mechanic.LoseAbilities(),
                Mechanic.SetColors(listOf(ColorRef.Literal(Tokens.color(m.groupValues[2]) ?: return null))),
                Mechanic.SetTypes(add = listOf(CardType.Creature), addSubtypes = listOf(arcanum.api.SubtypeRef.Literal(Subtype(subtype))), replaceTypes = true, replaceSubtypes = true),
                Mechanic.SetPowerToughness(Value.Fixed(m.groupValues[4].toInt()), Value.Fixed(m.groupValues[5].toInt()))))
        }
        // spm chunk 03: "target non-Equipment artifact you control becomes an artifact creature with base power and toughness 3/3 until end of
        // turn." (layers 4, 7b)
        Spm.BECOMES_ARTIFACT_CREATURE_BASE_PT_UNTIL_EOT.matchEntire(sentence)?.let { m ->
            val objects = spmTargetSubject(m.groupValues[1], context) ?: return null
            return listOf(spmApply(objects, arcanum.api.Duration.EndOfTurn, Mechanic.SetTypes(add = listOf(CardType.Artifact, CardType.Creature)),
                Mechanic.SetPowerToughness(Value.Fixed(m.groupValues[2].toInt()), Value.Fixed(m.groupValues[3].toInt()))))
        }
        // spm chunk 03: "Until end of turn, target creature you control gets +3/+1 and becomes a Dinosaur in addition to its other types."
        Spm.UNTIL_EOT_GETS_AND_BECOMES_IN_ADDITION.matchEntire(sentence)?.let { m ->
            val subtype = m.groupValues[4].takeIf { it in RulesWords.subtypes } ?: return null
            val name = spmNewSlotName(context, Filters.slotName(m.groupValues[1]))
            context.targets += spmSlot(name, Filters.noun(m.groupValues[1]) ?: return null)
            return listOf(spmApply(Objects.Target(name), arcanum.api.Duration.EndOfTurn,
                Mechanic.ModifyPowerToughness(ptChange(m.groupValues[2]) ?: return null, ptChange(m.groupValues[3]) ?: return null),
                Mechanic.SetTypes(addSubtypes = listOf(arcanum.api.SubtypeRef.Literal(Subtype(subtype))))))
        }
        // spm chunk 04: "When you next cast a creature spell this turn, copy it, except the copy isn't legendary." (CR 603.7, 707.10)
        Spm.NEXT_CREATURE_SPELL_COPY_NOT_LEGENDARY.matchEntire(sentence)?.let { m ->
            val spells = Filters.noun(m.groupValues[1] + " spell") ?: return null
            return listOf(Step.Do(Effect.CreateDelayedTrigger(arcanum.api.Trigger.On(EventPattern.Cast(spells, PlayerFilter.You)),
                Instructions(steps = listOf(Step.Do(Effect.CopySpell(Objects.EventObject(EventRole.Object), Players.You, newTargets = false, except = listOf(spmNotLegendary))))),
                duration = arcanum.api.Duration.EndOfTurn)))
        }
        // spm chunk 04: "copy that spell, except the copy isn't legendary." (CR 707.10, 707.9b)
        if (Spm.COPY_THAT_SPELL_NOT_LEGENDARY.matches(sentence) && context.event is EventPattern.Cast)
            return listOf(Step.Do(Effect.CopySpell(Objects.EventObject(EventRole.Object), Players.You, newTargets = false, except = listOf(spmNotLegendary))))
        // spm chunk 04: "create a token that's a copy of it, except it isn't legendary." (the creature that dealt the damage, CR 707.9b)
        if (Spm.CREATE_TOKEN_COPY_NOT_LEGENDARY.matches(sentence)) {
            val it = context.it ?: return null
            return listOf(Step.Do(Effect.CreateToken(arcanum.api.TokenSpec.CopyOf(it, except = listOf(spmNotLegendary)), Value.Fixed(1), Players.You)))
        }
        // spm chunk 05: "Return up to six target creature cards with different names from your graveyard to the battlefield." (CR 601.2c)
        Spm.RETURN_UP_TO_DIFFERENT_NAMES.matchEntire(sentence)?.let { m ->
            val n = spmN(m.groupValues[1]) ?: return null
            val noun = m.groupValues[2].removeSuffix("s")
            val filter = Filters.all(Filters.noun(noun) ?: return null, ObjectFilter.InZone(Zone.Graveyard), ObjectFilter.OwnedBy(PlayerFilter.You))
            val name = spmNewSlotName(context, Filters.slotName(noun))
            context.targets += spmSlot(name, filter, min = 0, max = n).copy(distinct = arcanum.api.SharedQuality.Name)
            return listOf(Step.Do(Effect.Move(Objects.Target(name), Destination(Zone.Battlefield))))
        }
        // spm chunk 05: "You may cast an artifact spell from your hand with mana value less than or equal to the number of ingenuity counters on
        // Lady Octopus without paying its mana cost." (CR 118.9)
        Spm.MAY_CAST_FROM_HAND_MV_AT_MOST_FREE.matchEntire(sentence)?.let { m ->
            val cards = Filters.noun(m.groupValues[1] + " card") ?: return null
            val most = spmValue(m.groupValues[2]) ?: return null
            return listOf(Step.Choose(arcanum.api.Choice.Objects(Filters.all(cards, ObjectFilter.InZone(Zone.Hand), ObjectFilter.OwnedBy(PlayerFilter.You),
                ObjectFilter.ManaValue(arcanum.api.Comparison.AtMost, most)), Value.Fixed(0), Value.Fixed(1)), bind = "chosen", chooser = Players.You),
                Step.Do(Effect.Cast(Objects.Bound("chosen"), PlayKind.Cast, withoutPaying = true, caster = Players.You)))
        }
        // spm chunk 07: "create a 2/1 green Spider creature token with reach, then you gain 1 life for each Spider you control." (two steps)
        Spm.CREATE_THEN_YOU.matchEntire(sentence)?.let { m ->
            val create = effect("Create ${m.groupValues[1]}.", context) ?: return null
            val then = effect("You ${m.groupValues[2]}", context) ?: return null
            return create + then
        }
        // spm chunk 06: "Target opponent loses life equal to the number of creatures they control." (counted as it resolves)
        Spm.TARGET_OPPONENT_LOSES_FOR_THEIR.matchEntire(sentence)?.let { m ->
            val opponent = context.targetOpponent()
            val noun = Filters.noun(m.groupValues[1].removeSuffix("s")) ?: return null
            return listOf(Step.Do(Effect.LoseLife(opponent, Value.Count(Objects.Each(Filters.all(noun, ObjectFilter.ControlledBy(PlayerFilter.Is(opponent))))))))
        }
        // spm chunk 06: "he deals 2 damage to target creature and 2 damage to that creature's controller."
        Spm.DEALS_TO_TARGET_AND_ITS_CONTROLLER.matchEntire(sentence)?.takeIf { spmSelfOrPronoun(it.groupValues[1]) }?.let { m ->
            val name = spmNewSlotName(context, Filters.slotName(m.groupValues[3]))
            context.targets += spmSlot(name, Filters.noun(m.groupValues[3]) ?: return null)
            val t = Objects.Target(name)
            return listOf(Step.Do(Effect.DealDamage(arcanum.api.Recipients(objects = t), Value.Fixed(m.groupValues[2].toInt()), source = Objects.Self)),
                Step.Do(Effect.DealDamage(arcanum.api.Recipients(players = Players.ControllerOf(t)), Value.Fixed(m.groupValues[4].toInt()), source = Objects.Self)))
        }
        // spm chunk 06: "Exile any number of target players' graveyards." (CR 115.1)
        if (Spm.EXILE_ANY_NUMBER_TARGET_GRAVEYARDS.matches(sentence)) {
            context.targets += TargetSlot("players", TargetKind.Players(PlayerFilter.Any), min = Value.Fixed(0), max = null)
            return listOf(Step.Do(Effect.Move(Objects.Each(Filters.all(ObjectFilter.InZone(Zone.Graveyard), ObjectFilter.OwnedBy(PlayerFilter.Is(Players.Target("players"))))),
                Destination(Zone.Exile))))
        }
        // spm chunk 06: "exile up to one target nonland permanent and up to one target nonland permanent card from a graveyard." (kept for "the
        // exiled cards", CR 607.2a)
        Spm.EXILE_UP_TO_ONE_AND_UP_TO_ONE.matchEntire(sentence)?.let { m ->
            val names = listOf(m.groupValues[1], m.groupValues[2]).map { noun ->
                val name = spmNewSlotName(context, Filters.slotName(noun))
                context.targets += spmSlot(name, Filters.noun(noun) ?: return null, min = 0)
                name
            }
            val exiled = Objects.Union(names.map { Objects.Target(it) })
            return if (exiledCard != null) listOf(Step.Do(Effect.Move(exiled, Destination(Zone.Exile), postBind = "exiled")),
                Step.Do(Effect.Remember(EXILED_WITH, Objects.Bound("exiled"))))
            else listOf(Step.Do(Effect.Move(exiled, Destination(Zone.Exile))))
        }
        // spm chunk 07: "up to one target creature gains first strike and vigilance until end of turn."
        Spm.UP_TO_ONE_TARGET_GAINS.matchEntire(sentence)?.let { m ->
            val name = spmNewSlotName(context, Filters.slotName(m.groupValues[1]))
            val gains = keywords(m.groupValues[2]) ?: return null
            context.targets += spmSlot(name, Filters.noun(m.groupValues[1]) ?: return null, min = 0)
            return listOf(spmApply(Objects.Target(name), arcanum.api.Duration.EndOfTurn, Mechanic.GainAbilities(gains)))
        }
        // spm chunk 07: "One or two target creatures each get +1/+0 and gain first strike until end of turn."
        Spm.ONE_OR_TWO_EACH_GET_AND_GAIN.matchEntire(sentence)?.let { m ->
            val noun = m.groupValues[2].removeSuffix("s")
            val name = spmNewSlotName(context, Filters.slotName(m.groupValues[2]))
            context.targets += spmSlot(name, Filters.noun(noun) ?: Filters.noun(m.groupValues[2]) ?: return null, min = 1, max = 2)
            return listOf(spmApply(Objects.Target(name), arcanum.api.Duration.EndOfTurn,
                Mechanic.ModifyPowerToughness(ptChange(m.groupValues[3]) ?: return null, ptChange(m.groupValues[4]) ?: return null),
                Mechanic.GainAbilities(keywords(m.groupValues[5]) ?: return null)))
        }
        // spm chunk 07: "One or two target creatures you control each get +1/+0 until end of turn. They each deal damage …": "they" are the
        // earlier targets (read by the dsk rule)
        if (sentence.startsWith("They each deal damage equal to their power to ") && context.them == null)
            context.them = context.targets.lastOrNull()?.takeIf { it.what is TargetKind.Objects }?.let { Objects.Target(it.name) }
        // spm chunk 07: "suspect up to one target creature." (CR 701.60a)
        Spm.SUSPECT.matchEntire(sentence)?.let { m ->
            // mkm chunk 04: "suspect up to one other target creature you control": "other" leaves this object out
            val name = spmNewSlotName(context, Filters.slotName(m.groupValues[3]))
            val noun = Filters.noun(m.groupValues[3]) ?: return null
            val filter = if (m.groupValues[2].isEmpty()) noun else Filters.all(ObjectFilter.Not(ObjectFilter.Is(Objects.Self)), noun)
            context.targets += spmSlot(name, filter, min = if (m.groupValues[1].isEmpty()) 1 else 0)
            return listOf(Step.Do(Effect.Mark(Objects.Target(name), arcanum.api.ObjectMark.Suspected)))
        }
        // spm chunk 07: "double the number of each kind of counter on each Spider and legendary creature you control." (CR 701.10e)
        Spm.DOUBLE_EACH_KIND_ON_EACH.matchEntire(sentence)?.let { m ->
            val filter = spmSpiderAndLegendary(m.groupValues[1]) ?: Filters.noun(m.groupValues[1]) ?: return null
            return listOf(Step.Do(Effect.Action(arcanum.api.KeywordAction.Double(arcanum.api.Doubled.Counters(Objects.Each(filter), null)))))
        }
        // spm chunk 08: "Counter target instant spell, sorcery spell, or triggered ability." (CR 701.6)
        if (Spm.COUNTER_TARGET_SPELLS_OR_TRIGGERED.matches(sentence)) {
            val spell = ObjectFilter.Category(arcanum.api.ObjectCategory.Spell)
            context.targets += spmSlot("spell or ability", ObjectFilter.Or(listOf(Filters.all(ObjectFilter.Type(CardType.Instant), spell),
                Filters.all(ObjectFilter.Type(CardType.Sorcery), spell), ObjectFilter.AbilityOf(kind = arcanum.api.AbilityKind.Triggered))))
            return listOf(Step.Do(Effect.Counter(Objects.Target("spell or ability"))))
        }
        // spm chunk 08: "Until your next turn, each creature attacks each combat if able and attacks a player other than you if able." (two
        // requirements, CR 508.1d)
        if (Spm.MAXIMUM_CARNAGE.matches(sentence))
            return listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.MustAttack(), Mechanic.MustAttack(arcanum.api.Recipients(players = Players.Each(PlayerFilter.Not(PlayerFilter.You))))),
                Affected.Objects(Objects.Each(ObjectFilter.Type(CardType.Creature))), arcanum.api.Duration.UntilYourNextTurn)))
        return null
    }

    /** spm: a target named as the subject of a sentence ("up to one other target creature", "target non-Equipment artifact you control"). */
    private fun spmTargetSubject(subject: String, context: Context): Objects? {
        val upTo = subject.startsWith("up to one ") || subject.startsWith("Up to one ")
        val rest = subject.removePrefix("up to one ").removePrefix("Up to one ")
        val noun = when {
            rest.startsWith("other target ") -> "other " + rest.removePrefix("other target ")
            rest.startsWith("target ") -> rest.removePrefix("target ")
            rest.startsWith("Target ") -> rest.removePrefix("Target ")
            else -> return null
        }
        val filter = Filters.noun(noun) ?: return null
        val name = spmNewSlotName(context, Filters.slotName(noun.removePrefix("other ")))
        context.targets += spmSlot(name, filter, min = if (upTo) 0 else 1)
        return Objects.Target(name)
    }

    /** spm chunk 07: "Spider and legendary creature you control": each permanent that's either (a Spider, or a legendary creature). */
    private fun spmSpiderAndLegendary(phrase: String): ObjectFilter? {
        val m = LazyRegexes.WORD_AND_LEGENDARY_CREATURE.matchEntire(phrase) ?: return null
        val subtype = m.groupValues[1].takeIf { it in RulesWords.subtypes } ?: return null
        return Filters.all(ObjectFilter.Or(listOf(ObjectFilter.Sub(Subtype(subtype)), Filters.all(ObjectFilter.Super(Supertype.Legendary), ObjectFilter.Type(CardType.Creature)))),
            ObjectFilter.ControlledBy(PlayerFilter.You))
    }

    /** spm: "the number of ingenuity counters on Lady Octopus". */
    private fun spmValue(text: String): Value? {
        COUNTERS_ON_SELF.matchEntire(text)?.takeIf { isSelf(it.groupValues[2]) }?.let { m ->
            val kind = Counters.kind(m.groupValues[1]) ?: arcanum.api.CounterKind.Named(m.groupValues[1])
            return Value.Of(arcanum.api.NumericProperty.Counters(kind), Objects.Self, arcanum.api.Combine.Single)
        }
        return Values.value(text)
    }

    // ---- ecl: Lorwyn Eclipsed (tried first; each rule reads one wording and falls through when it can't)

    private val eclSelfOnly get() = Affected.Objects(Objects.Self)
    private val eclM1M1 get() = arcanum.api.CounterKind.PowerToughness(-1, -1)
    private fun eclN(word: String): Int? = Numbers.count(word)
    private fun eclSlot(name: String, filter: ObjectFilter, min: Int = 1, max: Int? = 1) =
        TargetSlot(name, TargetKind.Objects(filter), min = Value.Fixed(min), max = max?.let { Value.Fixed(it) })
    private fun eclUntilEndOfTurn(objects: Objects, vararg mechanics: Mechanic) =
        Step.Do(Effect.ApplyMechanics(mechanics.toList(), Affected.Objects(objects), arcanum.api.Duration.EndOfTurn))
    private fun eclPt(p: Int, t: Int): Mechanic = Mechanic.ModifyPowerToughness(Value.Fixed(p), Value.Fixed(t))
    private fun eclNewSlotName(context: Context, base: String) = if (context.targets.none { it.name == base }) base else nextTargetName(base, context.targets.map { it.name })
    private fun eclCap(text: String) = text.replaceFirstChar { it.uppercase() }
    /** ecl chunk 13: a creature type in the plural ("Elementals", "Elves") as a subtype filter. */
    private fun eclPluralSubtype(plural: String): ObjectFilter? = listOf(plural.removeSuffix("s"), plural.removeSuffix("es"),
        plural.replace(LazyRegexes.VES_END, "f"), plural).firstOrNull { it in RulesWords.subtypes }?.let { ObjectFilter.Sub(Subtype(it)) }

    /** ecl chunk 01: "blight N" (CR 701.68a) by [players], naming the creature "blighted" (701.68c). */
    private fun eclBlight(players: Players, count: Value): arcanum.api.KeywordAction.Blight = arcanum.api.KeywordAction.Blight(players, count)
    private fun eclBlightCost(count: Value): CostPart = CostPart.Action(eclBlight(Players.You, count), bind = "blighted")

    /** ecl: whole lines read before the other rules. */
    private fun eclLine(line: String): Ability? {
        eclLine2(line)?.let { return it }
        // ecl chunk 03: "Vivid — {T}: For each color among permanents you control, add one mana of that color." (CR 106.1)
        if (line == "{T}: For each color among permanents you control, add one mana of that color.")
            return Ability.Activated(Cost(listOf(CostPart.TapSelf)), Instructions(steps = listOf(Step.Do(Effect.AddMana(ManaProduction(
                ManaKind.EachColorAmong(Objects.Each(Filters.all(ObjectFilter.Category(arcanum.api.ObjectCategory.Permanent), ObjectFilter.ControlledBy(PlayerFilter.You))))),
                Players.You)))), arcanum.api.ActivationRules(timing = arcanum.api.Timing.Any, activatedBy = PlayerFilter.You))
        return null
    }

    /** ecl: static abilities, tried first in [static]. */
    private fun eclStatic(line: String): Ability? {
        eclStatic2(line)?.let { return it }
        eclStatic3(line)?.let { return it }
        // ecl chunk 02: "As an additional cost to cast this spell, behold a Kithkin and exile it." (CR 701.4a: a Kithkin you control or a
        // Kithkin card from your hand, exiled; kept with this card for "the exiled card", CR 607.2a)
        Ecl.ADDITIONAL_BEHOLD_AND_EXILE.matchEntire(line)?.let { m ->
            val filter = Filters.noun(m.groupValues[1]) ?: return null
            val remember = EXILED_WITH.takeIf { exiledCard != null }
            fun from(zone: Zone) = Cost(listOf(CostPart.Exile(CostObjects.Choose(filter, count = Value.Fixed(1)), from = zone, remember = remember)))
            return Ability.Static(listOf(Mechanic.AdditionalCost(cost = Cost(listOf(CostPart.OneOf(listOf(from(Zone.Battlefield), from(Zone.Hand))))))),
                affects = eclSelfOnly)
        }
        // ecl chunk 13: "As an additional cost to cast this spell, blight X. X can't be greater than the greatest toughness among creatures you
        // control." (X chosen as the cost is paid, CR 107.3a, 601.2f)
        Ecl.ADDITIONAL_BLIGHT_X.matchEntire(line)?.let { m ->
            val most = Values.value(m.groupValues[1]) ?: return null
            return Ability.Static(listOf(Mechanic.AdditionalCost(cost = Cost(listOf(eclBlightCost(Value.CastX(of = Objects.Self))))), Mechanic.XAtMost(most)),
                affects = eclSelfOnly)
        }
        // ecl chunk 14: "As an additional cost to cast this spell, you may choose a creature type and behold two creatures of that type."
        Ecl.ADDITIONAL_MAY_CHOOSE_TYPE_BEHOLD.matchEntire(line)?.let { m ->
            val n = eclN(m.groupValues[1]) ?: return null
            val ofType = Filters.all(ObjectFilter.Type(CardType.Creature), ObjectFilter.Sub(arcanum.api.SubtypeRef.Chosen("type")))
            return Ability.Static(listOf(Mechanic.AdditionalCost(cost = Cost(listOf(CostPart.Choose(arcanum.api.Choice.CreatureType, bind = "type"),
                CostPart.Action(arcanum.api.KeywordAction.Behold(ofType, Value.Fixed(n)), bind = "beheld"))), optional = true)), affects = eclSelfOnly)
        }
        // ecl chunk 01: "As an additional cost to cast this spell, you may blight 1." (an optional additional cost, CR 601.2b, f)
        Ecl.ADDITIONAL_MAY.matchEntire(line)?.let { m ->
            val parts = costPart(eclCap(m.groupValues[1])) ?: return@let
            return Ability.Static(listOf(Mechanic.AdditionalCost(cost = Cost(parts), optional = true)), affects = eclSelfOnly)
        }
        // ecl chunk 03: "This spell costs {1} less to cast for each color among permanents you control." (CR 601.2f)
        Ecl.COSTS_LESS_FOR_EACH_COLOR.matchEntire(line)?.let { m ->
            return Ability.Static(listOf(Mechanic.CostChange(ObjectFilter.Is(Objects.Self), arcanum.api.CostChange.Less(ManaCost.parse(m.groupValues[1]) ?: return null,
                EclPhrases.colorsAmongPermanents))), affects = eclSelfOnly)
        }
        // ecl chunk 11: "This spell costs {X} less to cast, where X is the greatest mana value among Elementals you control."
        Ecl.COSTS_X_LESS_WHERE.matchEntire(line)?.let { m ->
            return Ability.Static(listOf(Mechanic.CostChange(ObjectFilter.Is(Objects.Self), arcanum.api.CostChange.Less(ManaCost.parse("{1}")!!,
                Values.value(m.groupValues[1]) ?: return null))), affects = eclSelfOnly)
        }
        // ecl chunk 10: "As long as equipped creature's toughness is greater than its power, it assigns combat damage equal to its toughness
        // rather than its power." (CR 510.1c)
        if (Ecl.AS_LONG_AS_EQUIPPED_TOUGHNESS_GREATER.matches(line)) {
            val equipped = Objects.AttachedTo(Objects.Self)
            return Ability.Static(listOf(Mechanic.AssignsDamageByToughness), affects = Affected.Objects(equipped),
                condition = arcanum.api.Condition.Compare(Value.Of(arcanum.api.NumericProperty.Toughness, equipped, arcanum.api.Combine.Single),
                    arcanum.api.Comparison.Greater, Value.Of(arcanum.api.NumericProperty.Power, equipped, arcanum.api.Combine.Single)))
        }
        // ecl chunk 11: "This creature has hexproof as long as it's untapped."
        Ecl.HEXPROOF_AS_LONG_AS_UNTAPPED.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            return Ability.Static(listOf(Mechanic.GainAbilities(listOf(OracleParser.keyword(m.groupValues[2]) ?: return null))), affects = eclSelfOnly,
                condition = arcanum.api.Condition.ObjectMatches(Objects.Self, ObjectFilter.Not(ObjectFilter.HasStatus(arcanum.api.Status.Tapped))))
        }
        // ecl chunk 11: "Enchanted creature loses all abilities and is a colorless Noggle with base power and toughness 1/1." (layers 4, 5, 6, 7b)
        // fdn chunk 02: "… is a black Skeleton creature with …", "… is a green and white Citizen creature with … 1/1 named [name]." ("creature" is
        // set as the card type, so the others go; a name set by an effect, CR 612.8; a creature type replacing the others, CR 205.1b)
        Ecl.ENCHANTED_LOSES_ALL_COLORED_BASE.matchEntire(line)?.let { m ->
            val colors = m.groupValues[1].takeIf { it != "colorless" }?.split(" and ")?.map { ColorRef.Literal(Tokens.color(it) ?: return null) }.orEmpty()
            val subtype = m.groupValues[2].takeIf { it in RulesWords.subtypes } ?: return null
            val isCreature = m.groupValues[3].isNotEmpty()
            return Ability.Static(listOfNotNull(m.groupValues[6].takeIf { it.isNotEmpty() }?.let { Mechanic.SetName(it) }) + listOf(Mechanic.LoseAbilities(), Mechanic.SetColors(colors),
                Mechanic.SetTypes(add = if (isCreature) listOf(CardType.Creature) else emptyList(), addSubtypes = listOf(arcanum.api.SubtypeRef.Literal(Subtype(subtype))),
                    replaceTypes = isCreature, replaceSubtypes = true),
                Mechanic.SetPowerToughness(Value.Fixed(m.groupValues[4].toInt()), Value.Fixed(m.groupValues[5].toInt()))),
                affects = Affected.Objects(Objects.AttachedTo(Objects.Self)))
        }
        // ecl chunk 13: "Spells you control can't be countered."
        if (line == "Spells you control can't be countered.")
            return Ability.Static(listOf(Mechanic.CantBeCountered), affects = Affected.Objects(Objects.Each(Filters.all(ObjectFilter.Category(arcanum.api.ObjectCategory.Spell),
                ObjectFilter.ControlledBy(PlayerFilter.You)))))
        // ecl chunk 13: 'Other creatures you control have "Ward—Pay 2 life."' (a keyword in quotes)
        Ecl.HAVE_QUOTED_KEYWORD.matchEntire(line)?.let { m ->
            val filter = Filters.noun(m.groupValues[1]) ?: Filters.noun(m.groupValues[1].replaceFirstChar { it.lowercase() }) ?: return@let
            val keyword = OracleParser.keyword(m.groupValues[2]) ?: OracleParser.keyword(m.groupValues[2].removeSuffix(".")) ?: return@let
            return Ability.Static(listOf(Mechanic.GainAbilities(listOf(keyword))), affects = Affected.Objects(Objects.Each(filter)))
        }
        // ecl chunk 13: "All creatures have haste."
        Ecl.ALL_HAVE.matchEntire(line)?.let { m ->
            val filter = Filters.noun(m.groupValues[1].removeSuffix("s")) ?: return@let
            val keywords = keywords(m.groupValues[2]) ?: return@let
            return Ability.Static(listOf(Mechanic.GainAbilities(keywords)), affects = Affected.Objects(Objects.Each(filter)))
        }
        // ecl chunk 12: "Players can't draw cards or gain life."
        if (Ecl.PLAYERS_CANT_DRAW_OR_GAIN.matches(line))
            return Ability.Static(listOf(Mechanic.MaxDrawsPerTurn(0), Mechanic.CantGainLife), affects = Affected.Players(Players.Each(PlayerFilter.Any)))
        // ecl chunk 12: "During your turn, you may cast creature spells from among cards you own exiled with this creature by removing three
        // counters from among creatures you control in addition to paying their other costs." (CR 601.2f)
        Ecl.CAST_FROM_EXILED_WITH_REMOVING_COUNTERS.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val n = eclN(m.groupValues[2]) ?: return null
            val cards = Filters.all(ObjectFilter.Type(CardType.Creature), ObjectFilter.InZone(Zone.Exile), ObjectFilter.OwnedBy(PlayerFilter.You),
                ObjectFilter.Is(Objects.Remembered(EXILED_WITH)))
            return Ability.Static(listOf(Mechanic.MayPlay(Zone.Exile, PlayKind.Cast, holder = PlayerFilter.You, additionalCost = Cost(listOf(
                CostPart.RemoveCounters(null, Value.Fixed(n), CostObjects.Choose(Filters.all(ObjectFilter.Type(CardType.Creature), ObjectFilter.ControlledBy(PlayerFilter.You)), count = null),
                    distributed = true))))), affects = Affected.Objects(Objects.Each(cards)), condition = arcanum.api.Condition.YourTurn)
        }
        return null
    }

    /** ecl: lines that are two abilities. */
    private fun eclMulti(line: String): List<Ability>? = eclMulti2(line)

    /** ecl: trigger events (with a condition checked as it would trigger), tried first in [trigger]. */
    private fun eclTrigger(text: String): Pair<arcanum.api.Trigger.On, arcanum.api.Condition?>? {
        // ecl chunk 11: "you cast a spell during an opponent's turn" (in a two-player game every other turn is an opponent's, CR 102.3)
        if (Ecl.CAST_DURING_OPPONENTS_TURN.matches(text))
            return arcanum.api.Trigger.On(EventPattern.Cast(ObjectFilter.Any, PlayerFilter.You)) to arcanum.api.Condition.Not(arcanum.api.Condition.YourTurn)
        // ecl chunk 04: "this creature becomes tapped while it has a -1/-1 counter on it", "another creature you control enters while this
        // creature has a -1/-1 counter on it": checked as it would trigger (CR 603.2)
        Ecl.ENTERS_WHILE_HAS_COUNTER.matchEntire(text)?.let { m ->
            val subject = m.groupValues[2]
            if (subject != "it" && !isSelf(subject)) return@let
            val kind = Counters.kind(m.groupValues[3]) ?: return null
            val (inner, onlyIf) = trigger(m.groupValues[1]) ?: return null
            if (onlyIf != null) return null
            return inner to arcanum.api.Condition.ObjectMatches(Objects.Self, ObjectFilter.HasCounter(kind, atLeast = 1))
        }
        return null
    }

    /** ecl: cost parts, tried first in [costPart]. */
    private fun eclCostPart(text: String): List<CostPart>? {
        // ecl chunk 01: "Blight 2" (CR 701.68a); "blight X" names the X chosen as it is paid (CR 107.3a)
        Ecl.BLIGHT.matchEntire(text)?.let { m ->
            val count = if (m.groupValues[1] == "X") Value.Announced(name = "X") else Value.Fixed(m.groupValues[1].toInt())
            return listOf(eclBlightCost(count))
        }
        // ecl chunk 04: "Remove a counter from this creature", "Remove two counters from this creature" (any kinds, CR 122.8)
        Ecl.REMOVE_COUNTERS_FROM_SELF.matchEntire(text)?.takeIf { isSelf(it.groupValues[2]) }?.let { m ->
            val n = if (m.groupValues[1] == "a") 1 else eclN(m.groupValues[1]) ?: return null
            return listOf(CostPart.RemoveCounters(null, Value.Fixed(n), from = CostObjects.Self))
        }
        // ecl chunk 14: "Exile this enchantment" (from the battlefield)
        if (text.startsWith("Exile ") && isSelf(text.removePrefix("Exile ")) && text != "Exile this card")
            return listOf(CostPart.Exile(CostObjects.Self, from = Zone.Battlefield))
        // ecl chunk 13: "Behold three Elementals" (CR 701.4a)
        Ecl.BEHOLD_COUNT.matchEntire(text)?.let { m ->
            val n = eclN(m.groupValues[1]) ?: return null
            val filter = Filters.noun(m.groupValues[2]) ?: eclPluralSubtype(m.groupValues[2]) ?: return null
            return listOf(CostPart.Action(arcanum.api.KeywordAction.Behold(filter, Value.Fixed(n)), bind = "beheld"))
        }
        return null
    }

    /** ecl: effect sentences, tried first in [effect]. */
    private fun eclEffect(sentence: String, context: Context): List<Step>? {
        eclEffect2(sentence, context)?.let { return it }
        eclEffect3(sentence, context)?.let { return it }
        // ecl chunk 01: "Target opponent blights 2.", "each opponent blights 1." (CR 701.68a)
        Ecl.PLAYERS_BLIGHT.matchEntire(sentence)?.let { m ->
            val players = when (m.groupValues[1].lowercase()) {
                "target opponent" -> context.targetOpponent()
                "each opponent" -> Players.Each(PlayerFilter.Opponent)
                else -> Players.Each(PlayerFilter.Any)
            }
            return listOf(Step.Do(Effect.Action(eclBlight(players, Value.Fixed(m.groupValues[2].toInt())), bind = "blighted")))
        }
        // ecl chunk 01: "Blight 1." (mandatory; nothing happens without a creature, CR 701.68b)
        Ecl.BLIGHT_SENTENCE.matchEntire(sentence)?.let { m ->
            return listOf(Step.Do(Effect.Action(eclBlight(Players.You, Value.Fixed(m.groupValues[1].toInt())), bind = "blighted")))
        }
        // ecl chunk 12: "Then if it isn't your main phase, blight 2."
        Ecl.IF_NOT_MAIN_PHASE_BLIGHT.matchEntire(sentence)?.let { m ->
            val condition = Conditions.condition("it isn't your main phase", self) ?: return null
            return listOf(Step.If(condition, then = listOf(Step.Do(Effect.Action(eclBlight(Players.You, Value.Fixed(m.groupValues[1].toInt())), bind = "blighted")))))
        }
        // ecl chunk 12: "You may blight 2. If you don't, you lose 3 life." (CR 118.12)
        Ecl.MAY_BLIGHT_IF_YOU_DONT.matchEntire(sentence)?.let { m ->
            val then = effect(eclCap(m.groupValues[2]), context) ?: return null
            return listOf(Step.Pay(Cost(listOf(eclBlightCost(Value.Fixed(m.groupValues[1].toInt())))), payer = Players.You, bind = "paid"),
                Step.If(arcanum.api.Condition.Not(arcanum.api.Condition.Did("paid")), then = then))
        }
        // ecl chunk 15: "You may pay {2}. If you don't, blight 2."
        Ecl.MAY_PAY_IF_YOU_DONT_BLIGHT.matchEntire(sentence)?.let { m ->
            val cost = ManaCost.parse(m.groupValues[1]) ?: return null
            return listOf(Step.Pay(Cost.mana(cost), payer = Players.You, bind = "paid"),
                Step.If(arcanum.api.Condition.Not(arcanum.api.Condition.Did("paid")),
                    then = listOf(Step.Do(Effect.Action(eclBlight(Players.You, Value.Fixed(m.groupValues[2].toInt())), bind = "blighted")))))
        }
        // ecl chunk 04: "remove a -1/-1 counter from this creature", "… from it"
        Ecl.REMOVE_A_COUNTER_FROM.matchEntire(sentence)?.let { m ->
            val subject = m.groupValues[2]
            val objects = if (subject == "it" || isSelf(subject)) Objects.Self else return@let
            return listOf(Step.Do(Effect.RemoveCounters(objects, Counters.kind(m.groupValues[1]) ?: return null, Value.Fixed(1))))
        }
        // ecl chunk 04: "You may remove a counter from this creature. When you do, …" (a reflexive trigger, CR 603.12)
        Ecl.MAY_REMOVE_COUNTER_WHEN_YOU_DO.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val reflexive = instructions(eclCap(m.groupValues[2])) ?: return null
            return listOf(Step.Pay(Cost(listOf(CostPart.RemoveCounters(null, Value.Fixed(1), from = CostObjects.Self))), payer = Players.You, bind = "paid"),
                Step.If(arcanum.api.Condition.Did("paid"), then = listOf(Step.Do(Effect.ReflexiveTrigger(reflexive)))))
        }
        // ecl chunk 10: "Remove any number of counters from target creature you control." (the player chooses how many of each kind)
        Ecl.REMOVE_ANY_NUMBER_OF_COUNTERS_FROM.matchEntire(sentence)?.let { m ->
            val noun = m.groupValues[1].removePrefix("target ")
            if (!m.groupValues[1].startsWith("target ")) return@let
            val target = context.target(Filters.slotName(noun), Filters.noun(noun) ?: return null)
            return listOf(Step.Choose(arcanum.api.Choice.Number(Value.Fixed(0), Value.Of(arcanum.api.NumericProperty.Counters(null), target, arcanum.api.Combine.Single)),
                bind = "removed", chooser = Players.You),
                Step.Do(Effect.RemoveCounters(target, null, Value.Bound("removed"))))
        }
        // ecl chunk 12: "Remove all counters from target creature."
        Ecl.REMOVE_ALL_COUNTERS_FROM.matchEntire(sentence)?.let { m ->
            if (!m.groupValues[1].startsWith("target ")) return@let
            val noun = m.groupValues[1].removePrefix("target ")
            val target = context.target(Filters.slotName(noun), Filters.noun(noun) ?: return null)
            return listOf(Step.Do(Effect.RemoveCounters(target, null, Value.Of(arcanum.api.NumericProperty.Counters(null), target, arcanum.api.Combine.Single))))
        }
        // ecl chunk 10: "each creature target opponent controls loses all abilities, becomes a Coward in addition to its other types, and has
        // base power and toughness 1/1." (indefinitely; layers 4, 6, 7b, CR 611.2c locks in the creatures)
        Ecl.EACH_CREATURE_TARGET_OPPONENT_LOSES.matchEntire(sentence)?.let { m ->
            val subtype = m.groupValues[1].takeIf { it in RulesWords.subtypes } ?: return null
            val opponent = context.targetOpponent()
            return listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.LoseAbilities(),
                Mechanic.SetTypes(addSubtypes = listOf(arcanum.api.SubtypeRef.Literal(Subtype(subtype)))),
                Mechanic.SetPowerToughness(Value.Fixed(m.groupValues[2].toInt()), Value.Fixed(m.groupValues[3].toInt()))),
                Affected.Objects(Objects.Each(Filters.all(ObjectFilter.Type(CardType.Creature), ObjectFilter.ControlledBy(PlayerFilter.Is(opponent))))),
                arcanum.api.Duration.Indefinitely)))
        }
        // ecl chunk 10: "exile up to two target cards from graveyards."
        Ecl.EXILE_UP_TO_N_TARGET_CARDS_FROM_GRAVEYARDS.matchEntire(sentence)?.let { m ->
            val n = eclN(m.groupValues[1]) ?: return null
            val name = eclNewSlotName(context, "cards")
            context.targets += eclSlot(name, EclPhrases.noun("cards from graveyards")!!, min = 0, max = n)
            return listOf(Step.Do(Effect.Move(Objects.Target(name), Destination(Zone.Exile))))
        }
        // ecl chunk 10: "Look at the top X cards of your library, where X is your life total. You may put any number of nonland permanent
        // cards with mana value 3 or less from among them onto the battlefield. Then shuffle."
        Ecl.LOOK_TOP_X_PUT_ANY_NUMBER.matchEntire(sentence)?.let { m ->
            val filter = Filters.noun(m.groupValues[1]) ?: return null
            return listOf(Step.Do(Effect.LookAt(Objects.LibraryCards(Players.You, Value.Announced(name = "X"), fromTop = true), Players.You, bind = "seen")),
                Step.Choose(arcanum.api.Choice.Objects(filter, Value.Fixed(0), null, from = Objects.Bound("seen")), bind = "chosen", chooser = Players.You),
                Step.Do(Effect.Move(Objects.Bound("chosen"), Destination(Zone.Battlefield))),
                Step.Do(Effect.Shuffle(Players.You)))
        }
        // ecl chunk 10: "you may put a creature card with mana value X or less from your hand onto the battlefield tapped and attacking"
        Ecl.MAY_PUT_FROM_HAND_TAPPED_ATTACKING.matchEntire(sentence)?.let { m ->
            val filter = Filters.noun(m.groupValues[1]) ?: return null
            return listOf(Step.Choose(arcanum.api.Choice.Objects(Filters.all(filter, ObjectFilter.InZone(Zone.Hand), ObjectFilter.OwnedBy(PlayerFilter.You)),
                Value.Fixed(0), Value.Fixed(1)), bind = "chosen", chooser = Players.You),
                Step.Do(Effect.Move(Objects.Bound("chosen"), Destination(Zone.Battlefield, tapped = true, attacking = arcanum.api.AttackTarget.Chosen))))
        }
        // ecl chunk 10: "Until your next turn, prevent all damage that would be dealt to you."
        if (Ecl.UNTIL_YOUR_NEXT_TURN_PREVENT_TO_YOU.matches(sentence))
            return listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.Prevention(EventPattern.Damage(ObjectFilter.Any, RecipientFilter(players = PlayerFilter.You)))),
                null, arcanum.api.Duration.UntilYourNextTurn)))
        // ecl chunk 10: "Exile Morningtide's Light." (the resolving spell, CR 608.2n)
        Ecl.EXILE_SELF.matchEntire(sentence)?.takeIf { isSpell && isSelf(it.groupValues[1]) }?.let {
            return listOf(Step.Do(Effect.Move(Objects.Self, Destination(Zone.Exile))))
        }
        return null
    }

    /** ecl: texts of several sentences read as a whole, tried first. */
    private fun eclWhole(text: String, context: Context): List<Step>? {
        eclWhole2(text, context)?.let { return it }
        eclWhole3(text, context)?.let { return it }
        // ecl chunk 10: "Exile any number of target creatures. At the beginning of the next end step, return those cards to the battlefield
        // tapped under their owners' control." (CR 603.7)
        Ecl.EXILE_ANY_NUMBER_RETURN_NEXT_END.matchEntire(text)?.let { m ->
            val name = eclNewSlotName(context, m.groupValues[1])
            context.targets += eclSlot(name, Filters.noun("creature")!!, min = 0, max = null)
            return listOf(Step.Do(Effect.Move(Objects.Target(name), Destination(Zone.Exile), postBind = "exiled")),
                Step.Do(Effect.CreateDelayedTrigger(arcanum.api.Trigger.On(EventPattern.StepBegins(arcanum.api.TurnStep.End, PlayerFilter.Any)), Instructions(steps = listOf(
                    Step.Do(Effect.Move(Objects.Bound("exiled"), Destination(Zone.Battlefield, tapped = true, controller = Players.OwnerOf(Objects.Bound("exiled"))))))))))
        }
        // ecl chunk 10: "For each player, you choose a creature that player controls. Then each player sacrifices all other creatures they
        // control that don't share a creature type with the chosen creature they control." (CR 608.2e)
        if (Ecl.FOR_EACH_PLAYER_CHOOSE_SACRIFICE_NOT_SHARING.matches(text)) {
            val theirs = Filters.all(ObjectFilter.Type(CardType.Creature), ObjectFilter.ControlledBy(PlayerFilter.Is(Players.Bound("player"))))
            return listOf(Step.ForEach(arcanum.api.Each.Players(Players.Each(PlayerFilter.Any)), "player", together = true, steps = listOf(
                Step.Choose(arcanum.api.Choice.Objects(theirs, Value.Fixed(1), Value.Fixed(1)), bind = "chosen", chooser = Players.You),
                Step.Do(Effect.Sacrifice(Objects.Each(Filters.all(theirs, ObjectFilter.Not(ObjectFilter.Is(Objects.Bound("chosen"))),
                    ObjectFilter.Not(ObjectFilter.Shares(arcanum.api.SharedQuality.CreatureType, Objects.Bound("chosen"))))))))))
        }
        return null
    }

    /** ecl: sentences that change the steps before them. */
    private fun eclModify(sentence: String, steps: List<Step>, context: Context): List<Step>? {
        // ecl chunk 01: "It deals 4 damage to that creature instead if this spell's additional cost was paid." (the damage before, another amount)
        Ecl.IT_DEALS_INSTEAD_IF.matchEntire(sentence)?.let { m ->
            val previous = (steps.lastOrNull() as? Step.Do)?.effect as? Effect.DealDamage ?: return null
            val condition = Conditions.condition(m.groupValues[2], self) ?: return null
            return steps.dropLast(1) + Step.If(condition, then = listOf(Step.Do(previous.copy(amount = Value.Fixed(m.groupValues[1].toInt())))),
                otherwise = listOf(steps.last()))
        }
        return null
    }

    private val ECL_HARVESTED = "harvested"

    /** ecl: a face name with a comma ("Brigid, Clachan's Heart") read in "transforms into [name]": the line is read with a comma-free alias
     * of the name, then the alias is put back (the names in [ObjectFilter.Named]). */
    private fun eclTransformsIntoName(line: String): Ability? {
        val name = self.filter { it.contains(", ") && line.contains("transforms into $it") }.maxByOrNull { it.length } ?: return null
        val alias = name.replace(", ", " ")
        val parsed = Sentences(self + alias, isSpell, linkedExile).line(line.replace("transforms into $name", "transforms into $alias")) ?: return null
        val json = kotlinx.serialization.json.Json
        val text = json.encodeToString(Ability.serializer(), parsed).replace("\"$alias\"", kotlinx.serialization.json.JsonPrimitive(name).toString())
        return json.decodeFromString(Ability.serializer(), text)
    }

    /** ecl: "[it] has [keywords and quoted abilities]" in a copy's exceptions ("except it has haste and "At the beginning of the end step,
     * sacrifice this token."", CR 707.9b). */
    private fun eclCopyExceptions(text: String): List<arcanum.api.CopyException>? {
        val m = Ecl.EXCEPT_IT_HAS.matchEntire(text) ?: return null
        val abilities = eclKeywordsAndQuoted(m.groupValues[1], setOf("this token", "this creature")) ?: return null
        return listOf(arcanum.api.CopyException.AddAbilities(abilities))
    }

    /** ecl: keywords and quoted abilities ("haste and "…"", ""…""). */
    private fun eclKeywordsAndQuoted(text: String, names: Set<String>): List<Ability>? {
        val quoted = LazyRegexes.QUOTED.findAll(text).map { it.groupValues[1] }.toList()
        val rest = text.replace(LazyRegexes.AND_QUOTED, "").trim().removeSuffix(",").removeSuffix(" and").trim()
        val keywords = if (rest.isEmpty()) emptyList() else keywords(rest) ?: return null
        val inner = Sentences(names)
        return keywords + quoted.map { q -> val s = if (q.endsWith(".")) q else "$q."; inner.line(s) ?: return null }
    }

    private fun eclLine2(line: String): Ability? {
        eclTransformsIntoName(line)?.let { return it }
        // ecl chunk 12: "At the beginning of each player's draw step, that player loses 3 life, searches their library for a card, puts it into
        // their hand, then shuffles." (the active player, CR 102.1)
        Ecl.EACH_DRAW_STEP_LOSES_SEARCHES.matchEntire(line)?.let { m ->
            val active = Players.Active
            return Ability.Triggered(arcanum.api.Trigger.On(EventPattern.StepBegins(arcanum.api.TurnStep.Draw, PlayerFilter.Any)), Instructions(steps = listOf(
                Step.Do(Effect.LoseLife(active, Value.Fixed(m.groupValues[1].toInt()))),
                Step.Do(Effect.Search(active, ObjectFilter.Category(arcanum.api.ObjectCategory.Card), max = Value.Fixed(1), zones = listOf(Zone.Library), bind = "found", searcher = active)),
                Step.Do(Effect.Move(Objects.Bound("found"), Destination(Zone.Hand))),
                Step.Do(Effect.Shuffle(active)))))
        }
        // ecl chunk 12: "When this creature dies, if it had a -1/-1 counter on it, return it to the battlefield under its owner's control and
        // it loses all abilities." (the card returns as a new object without its abilities, CR 400.7, 611.2e)
        Ecl.DIES_IF_HAD_COUNTER_RETURN_LOSES.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val kind = Counters.kind(m.groupValues[2]) ?: return null
            val card = Objects.EventObject(EventRole.After)
            return Ability.Triggered(arcanum.api.Trigger.On(EventPattern.ZoneChange(ObjectFilter.Is(Objects.Self), from = Zone.Battlefield, to = Zone.Graveyard)),
                Instructions(steps = listOf(Step.Do(Effect.Move(card, Destination(Zone.Battlefield, controller = Players.OwnerOf(card),
                    entersAs = listOf(Mechanic.LoseAbilities())))))),
                interveningIf = arcanum.api.Condition.ObjectMatches(Objects.EventObject(EventRole.Before), ObjectFilter.HasCounter(kind, atLeast = 1)))
        }
        // ecl chunk 12: "Whenever one or more other creatures you control enter, if they entered or were cast from a graveyard, create a token
        // that's a copy of one of them. This ability triggers only once each turn." (only those creatures count, CR 603.4)
        if (Ecl.ENTERED_OR_CAST_FROM_GRAVEYARD.matches(line)) {
            val others = Filters.all(ObjectFilter.Not(ObjectFilter.Is(Objects.Self)), ObjectFilter.Type(CardType.Creature), ObjectFilter.ControlledBy(PlayerFilter.You))
            return Ability.Triggered(arcanum.api.Trigger.On(listOf(EventPattern.ZoneChange(others, from = Zone.Graveyard, to = Zone.Battlefield),
                EventPattern.ZoneChange(Filters.all(others, ObjectFilter.WasCast(Zone.Graveyard)), from = Zone.Stack, to = Zone.Battlefield)), oneOrMore = true),
                Instructions(steps = listOf(
                    Step.Choose(arcanum.api.Choice.Objects(ObjectFilter.Any, Value.Fixed(1), Value.Fixed(1), from = Objects.EventObject(EventRole.After)), bind = "chosen", chooser = Players.You),
                    Step.Do(Effect.CreateToken(arcanum.api.TokenSpec.CopyOf(Objects.Bound("chosen")), Value.Fixed(1), Players.You)))), perTurn = 1)
        }
        // ecl chunk 15: "Whenever a creature you control attacks or blocks, it gets +X/+X until end of turn, where X is the difference between its
        // power and toughness." (the larger less the smaller, as the ability resolves)
        Ecl.ATTACKS_OR_BLOCKS_DIFFERENCE.matchEntire(line)?.let { m ->
            val filter = Filters.noun(m.groupValues[1].removeArticle()) ?: return null
            val it = Objects.EventObject(EventRole.Object)
            val p = Value.Of(arcanum.api.NumericProperty.Power, it, arcanum.api.Combine.Single)
            val t = Value.Of(arcanum.api.NumericProperty.Toughness, it, arcanum.api.Combine.Single)
            val x = Value.Difference(Value.Max(listOf(p, t)), Value.Min(listOf(p, t)))
            return Ability.Triggered(arcanum.api.Trigger.On(listOf(EventPattern.Attack(filter), EventPattern.Block(filter, attacker = ObjectFilter.Any))),
                Instructions(steps = listOf(eclUntilEndOfTurn(it, Mechanic.ModifyPowerToughness(x, x)))))
        }
        // ecl chunk 13: "Whenever you cast an instant or sorcery spell from your hand, exile that card with a dream counter on it instead of putting it
        // into your graveyard as it resolves." (a replacement the spell gets, CR 614.1a)
        if (line.startsWith("Whenever you cast ")) Ecl.EXILE_WITH_DREAM_COUNTER_INSTEAD.find(line)?.let { m ->
            val (trigger, _) = trigger(line.removePrefix("Whenever ").substringBefore(", exile that card")) ?: return null
            val kind = Counters.kind(m.groupValues[1]) ?: return null
            return Ability.Triggered(trigger, Instructions(steps = listOf(Step.Do(Effect.SpellGets(Objects.EventObject(EventRole.Object), listOf(
                Mechanic.Replacement(EventPattern.ZoneChange(ObjectFilter.Is(Objects.Affected), from = Zone.Stack, to = Zone.Graveyard, resolving = true),
                    modify = listOf(Modification.ChangeDestination(Destination(Zone.Exile, counters = listOf(arcanum.api.CountersToPut(kind, Value.Fixed(1)))))))))))))
        }
        return null
    }

    /** ecl: "[cast/activate] … of the chosen type" uses of mana (CR 106.6). */
    private fun eclSpendUse(use: String): ObjectFilter? = when (use) {
        "cast a spell of the chosen type" -> Filters.all(ObjectFilter.Category(arcanum.api.ObjectCategory.Spell), ObjectFilter.Sub(arcanum.api.SubtypeRef.Remembered("type")))
        "activate an ability of a source of the chosen type" -> ObjectFilter.AbilityOf(source = ObjectFilter.Sub(arcanum.api.SubtypeRef.Remembered("type")))
        // ecl chunk 15: "cast spells with mana value 4 or greater"
        "cast spells with mana value 4 or greater" -> Filters.all(ObjectFilter.Category(arcanum.api.ObjectCategory.Spell), ObjectFilter.ManaValue(arcanum.api.Comparison.AtLeast, Value.Fixed(4)))
        else -> null
    }

    private fun eclMulti2(line: String): List<Ability>? {
        // ecl chunk 11: "Enchanted creature can't become untapped and can't have counters put on it." (a rule for the creature, and a replacement
        // of this Aura, CR 614.1a)
        if (Ecl.CANT_BECOME_UNTAPPED_AND_NO_COUNTERS.matches(line)) {
            val enchanted = Objects.AttachedTo(Objects.Self)
            return listOf(Ability.Static(listOf(Mechanic.CantBecomeUntapped), affects = Affected.Objects(enchanted)),
                Ability.Static(listOf(Mechanic.Replacement(EventPattern.CountersPut(ObjectFilter.Is(enchanted), null), modify = listOf(Modification.Skip))),
                    affects = eclSelfOnly))
        }
        return null
    }

    private fun eclEffect3(sentence: String, context: Context): List<Step>? {
        if (sentence == "Proliferate.") return listOf(Step.Do(Effect.Action(arcanum.api.KeywordAction.Proliferate)))
        // ecl chunk 02: "Whenever another Elemental you control enters, it deals damage equal to its power to each opponent." ("it": the creature
        // that entered, the source of the damage)
        if (sentence == "It deals damage equal to its power to each opponent.") (context.event as? EventPattern.ZoneChange)
            ?.takeIf { it.to == Zone.Battlefield && it.objects != ObjectFilter.Is(Objects.Self) }?.let {
                val entered = Objects.EventObject(EventRole.After)
                return listOf(Step.Do(Effect.DealDamage(Recipients(players = Players.Each(PlayerFilter.Opponent)),
                    Value.Of(arcanum.api.NumericProperty.Power, entered, arcanum.api.Combine.Single), entered)))
            }
        // ecl chunk 07: "Add two mana of any one color. Spend this mana only to cast spells with mana value 4 or greater." (CR 106.1b, 106.6)
        Ecl.ADD_N_ANY_ONE_COLOR_SPEND_ONLY.matchEntire(sentence)?.let { m ->
            val n = eclN(m.groupValues[1]) ?: return null
            return listOf(Step.Do(Effect.AddMana(ManaProduction(ManaKind.Choose(Value.Fixed(n)), restriction = eclSpendUse(m.groupValues[2]) ?: spendOnlyTo(m.groupValues[2]) ?: return null), Players.You)))
        }
        // ecl chunk 15: "Until your next end step, you may play those cards." (the cards just exiled, CR 601.2a, 305.1)
        if (sentence == "Until your next end step, you may play those cards.") {
            val exiled = context.it?.takeIf { it == Objects.Bound("exiled") } ?: return null
            return listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.MayPlay(Zone.Exile, PlayKind.Play, holder = PlayerFilter.You)), Affected.Objects(exiled),
                arcanum.api.Duration.UntilStep(arcanum.api.TurnStep.End, PlayerFilter.You))))
        }
        // ecl chunk 14: "Mill four cards, then you may return a permanent card from among them to your hand." (one sentence)
        if (Ecl.MILL_THEN_MAY_PUT_FROM_AMONG.matches(sentence)) return eclWhole2(sentence, context)
        // ecl chunk 11: "Whenever a creature you control deals combat damage to a player or planeswalker this turn, draw a card." (a delayed
        // trigger for the rest of the turn, CR 603.7c)
        if (Ecl.DELAYED_COMBAT_DAMAGE_DRAW.matches(sentence)) {
            val yours = Filters.all(ObjectFilter.Type(CardType.Creature), ObjectFilter.ControlledBy(PlayerFilter.You))
            return listOf(Step.Do(Effect.CreateDelayedTrigger(arcanum.api.Trigger.On(EventPattern.Damage(yours, RecipientFilter(objects = ObjectFilter.Type(CardType.Planeswalker),
                players = PlayerFilter.Any), combat = true)), Instructions(steps = listOf(Step.Do(Effect.Draw(Players.You, Value.Fixed(1))))),
                duration = arcanum.api.Duration.EndOfTurn, repeats = true)))
        }
        // ecl chunk 01: "It deals 4 damage to that creature instead if this spell's additional cost was paid." is read by [eclModify]
        // ecl chunk 12: "target creature you control gets +X/+0 until end of turn and up to one target creature an opponent controls gets -0/-X until
        // end of turn"
        Ecl.GETS_X_AND_UP_TO_ONE_GETS.matchEntire(sentence)?.let { m ->
            val first = context.target(Filters.slotName(m.groupValues[1]), Filters.noun(m.groupValues[1]) ?: return null)
            val name = eclNewSlotName(context, Filters.slotName(m.groupValues[2]))
            context.targets += eclSlot(name, Filters.noun(m.groupValues[2]) ?: return null, min = 0)
            val x = Value.Announced(name = "X")
            return listOf(eclUntilEndOfTurn(first, Mechanic.ModifyPowerToughness(x, Value.Fixed(0))),
                eclUntilEndOfTurn(Objects.Target(name), Mechanic.ModifyPowerToughness(Value.Fixed(0), Value.Times(x, -1))))
        }
        // ecl chunk 15: "This creature becomes a Kithkin Scout with base power and toughness 2/3.", "If this creature is a Scout, it becomes a Kithkin
        // Soldier with base power and toughness 4/5." (for good; the new creature types replace its old ones, CR 205.1a)
        Ecl.BECOMES_SUBTYPES_BASE_PT.matchEntire(sentence)?.let { m ->
            val subject = m.groupValues[3]
            if (!isSelf(subject) && !(subject == "it" && m.groupValues[1].isNotEmpty())) return@let
            if (m.groupValues[1].isNotEmpty() && !isSelf(m.groupValues[1])) return@let
            val subtypes = m.groupValues[4].split(' ').map { arcanum.api.SubtypeRef.Literal(Subtype(it.takeIf { s -> s in RulesWords.subtypes } ?: return@let)) }
            val mechanics = mutableListOf<Mechanic>(Mechanic.SetTypes(addSubtypes = subtypes, replaceSubtypes = true),
                Mechanic.SetPowerToughness(Value.Fixed(m.groupValues[5].toInt()), Value.Fixed(m.groupValues[6].toInt())))
            if (m.groupValues[7] == " and protection from each of your opponents")
                mechanics += Mechanic.GainAbilities(listOf(arcanum.api.Keyword.Protection(ObjectFilter.ControlledBy(PlayerFilter.Opponent))))
            // mkm chunk 03: "… and gains vigilance." (layer 6)
            else if (m.groupValues[7].isNotEmpty())
                mechanics += Mechanic.GainAbilities(m.groupValues[7].removePrefix(" and gains ").split(LazyRegexes.AND_LIST).map { OracleParser.keyword(it) ?: return@let })
            val becomes = Step.Do(Effect.ApplyMechanics(mechanics, Affected.Objects(Objects.Self), arcanum.api.Duration.Indefinitely))
            if (m.groupValues[1].isEmpty()) return listOf(becomes)
            val type = m.groupValues[2].takeIf { it in RulesWords.subtypes } ?: return@let
            return listOf(Step.If(arcanum.api.Condition.ObjectMatches(Objects.Self, ObjectFilter.Sub(Subtype(type))), then = listOf(becomes)))
        }
        // ecl chunk 13: "Create a token that's a copy of target creature you control, except it has haste and "At the beginning of the end step,
        // sacrifice this token."" (CR 707.9b)
        Ecl.CREATE_COPY_OF_TARGET_EXCEPT.matchEntire(sentence)?.let { m ->
            val target = context.target(Filters.slotName(m.groupValues[1]), Filters.noun(m.groupValues[1]) ?: return null)
            val except = eclCopyExceptions(m.groupValues[2]) ?: return null
            return listOf(Step.Do(Effect.CreateToken(arcanum.api.TokenSpec.CopyOf(target, except), Value.Fixed(1), Players.You)))
        }
        // ecl chunk 07: "create a tapped and attacking token that's a copy of the blighted creature, except it has "…"" (CR 701.68c, 508.4)
        Ecl.CREATE_TAPPED_ATTACKING_COPY_OF_BLIGHTED.matchEntire(sentence)?.let { m ->
            val except = eclCopyExceptions(m.groupValues[1]) ?: return null
            return listOf(Step.Do(Effect.CreateToken(arcanum.api.TokenSpec.CopyOf(Objects.Bound("blighted"), except), Value.Fixed(1), Players.You,
                tapped = true, attacking = arcanum.api.AttackTarget.Chosen)))
        }
        // ecl chunk 13: "you may cast a spell from among cards you own in exile with dream counters on them without paying its mana cost."
        Ecl.MAY_CAST_FROM_EXILE_WITH_COUNTERS.matchEntire(sentence)?.let { m ->
            val kind = Counters.kind(m.groupValues[1]) ?: return null
            val cards = Filters.all(ObjectFilter.InZone(Zone.Exile), ObjectFilter.OwnedBy(PlayerFilter.You), ObjectFilter.HasCounter(kind, atLeast = 1))
            return listOf(Step.Choose(arcanum.api.Choice.Objects(cards, Value.Fixed(0), Value.Fixed(1)), bind = "chosen", chooser = Players.You),
                Step.Do(Effect.Cast(Objects.Bound("chosen"), PlayKind.Cast, withoutPaying = true, caster = Players.You)))
        }
        return null
    }

    private fun eclWhole3(text: String, context: Context): List<Step>? {
        // ecl chunk 06: "Choose a creature type. Return all creature cards of the chosen type from your graveyard to the battlefield." (the type chosen
        // now, not one kept by the card)
        Ecl.CHOOSE_A_CREATURE_TYPE_THEN.matchEntire(text)?.takeIf { it.groupValues[1].contains("the chosen type") }?.let { m ->
            val rest = mutableListOf<Step>()
            for (sentence in sentences(m.groupValues[1])) rest += effect(sentence, context) ?: return null
            val json = kotlinx.serialization.json.Json
            val serializer = kotlinx.serialization.builtins.ListSerializer(Step.serializer())
            val remembered = json.encodeToString(arcanum.api.SubtypeRef.serializer(), arcanum.api.SubtypeRef.Remembered("type"))
            val chosen = json.encodeToString(arcanum.api.SubtypeRef.serializer(), arcanum.api.SubtypeRef.Chosen("type"))
            val steps = json.decodeFromString(serializer, json.encodeToString(serializer, rest).replace(remembered, chosen))
            return listOf(Step.Choose(arcanum.api.Choice.CreatureType, bind = "type", chooser = Players.You)) + steps
        }
        // ecl chunk 15: "Exile cards from the top of your library until you exile a nonland card. You may cast that card without paying its mana cost
        // if the spell's mana value is less than or equal to the amount of life you gained this turn. Otherwise, put it into your hand."
        if (Ecl.EXILE_UNTIL_NONLAND_CAST_IF_LIFE.matches(text)) {
            val found = Objects.Bound("found")
            val gained = Value.EventsThisTurn(EventPattern.GainLife(PlayerFilter.You), arcanum.api.Measure.Amount)
            return listOf(Step.Do(Effect.RevealUntil(ObjectFilter.Not(ObjectFilter.Type(CardType.Land)), Players.You, Value.Fixed(1), reveal = true, into = Zone.Exile,
                    foundBind = "found")),
                Step.Pay(steps = listOf(Step.Do(Effect.Cast(found, PlayKind.Cast, withoutPaying = true, caster = Players.You,
                    resultingSpell = ObjectFilter.ManaValue(arcanum.api.Comparison.AtMost, gained)))), payer = Players.You, bind = "cast"),
                Step.If(arcanum.api.Condition.Not(arcanum.api.Condition.Did("cast")), then = listOf(Step.Do(Effect.Move(found, Destination(Zone.Hand))))))
        }
        // ecl chunk 16: "Add one mana of any color. This creature becomes that color until end of turn." (the colour chosen for the mana)
        Ecl.ADD_ANY_COLOR_BECOMES_THAT_COLOR.matchEntire(text)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            val color = listOf(ColorRef.Chosen("color"))
            return listOf(Step.Choose(arcanum.api.Choice.Color(), bind = "color", chooser = Players.You),
                Step.Do(Effect.AddMana(ManaProduction(ManaKind.Choose(Value.Fixed(1), color)), Players.You)),
                eclUntilEndOfTurn(Objects.Self, Mechanic.SetColors(color)))
        }
        // ecl chunk 15: "Each opponent exiles cards from the top of their library until they have exiled cards with total mana value 5 or greater this
        // way. Until end of turn, you may cast cards exiled this way without paying their mana costs." (one card at a time, CR 608.2c)
        Ecl.OPPONENTS_EXILE_UNTIL_TOTAL_MV.matchEntire(text)?.let { m ->
            val n = m.groupValues[1].toInt()
            val theirs = ObjectFilter.OwnedBy(PlayerFilter.Is(Players.Bound("opponent")))
            val exiledByThem = Objects.Where(Objects.Remembered(ECL_HARVESTED), theirs)
            val more = arcanum.api.Condition.And(listOf(
                arcanum.api.Condition.Compare(Value.Of(arcanum.api.NumericProperty.ManaValue, exiledByThem, arcanum.api.Combine.Total), arcanum.api.Comparison.Less, Value.Fixed(n)),
                arcanum.api.Condition.Exists(Filters.all(ObjectFilter.InZone(Zone.Library), theirs), atLeast = 1)))
            return listOf(Step.ForEach(arcanum.api.Each.Players(Players.Each(PlayerFilter.Opponent)), "opponent", together = true, steps = listOf(
                    Step.RepeatWhile(listOf(
                        Step.Do(Effect.Move(Objects.LibraryCards(Players.Bound("opponent"), Value.Fixed(1), fromTop = true), Destination(Zone.Exile), postBind = "exiled")),
                        Step.Do(Effect.Remember(ECL_HARVESTED, Objects.Bound("exiled")))), more))),
                Step.Do(Effect.ApplyMechanics(listOf(Mechanic.MayPlay(Zone.Exile, PlayKind.Cast, withoutPaying = true, holder = PlayerFilter.You)),
                    Affected.Objects(Objects.Remembered(ECL_HARVESTED)), arcanum.api.Duration.EndOfTurn)))
        }
        // ecl chunk 15: "Reveal cards from the top of your library until you reveal X nonland cards. For each of those colors, you may exile a card of
        // that color from among the revealed cards. Then shuffle. You may cast the exiled cards this turn." (those colors: among permanents you control)
        if (Ecl.REVEAL_UNTIL_X_NONLAND_EXILE_EACH_COLOR.matches(text)) {
            val revealed = Objects.Union(listOf(Objects.Bound("found"), Objects.Bound("rest")))
            val permanents = Objects.Each(Filters.all(ObjectFilter.Category(arcanum.api.ObjectCategory.Permanent), ObjectFilter.ControlledBy(PlayerFilter.You)))
            return listOf(Step.Do(Effect.RevealUntil(ObjectFilter.Not(ObjectFilter.Type(CardType.Land)), Players.You, Value.Announced(name = "X"), reveal = true,
                    foundBind = "found", restBind = "rest")),
                Step.Choose(arcanum.api.Choice.Objects(ObjectFilter.Shares(arcanum.api.SharedQuality.Color, permanents), Value.Fixed(0), null, from = revealed,
                    onePer = arcanum.api.SharedQuality.Color), bind = "chosen", chooser = Players.You),
                Step.Do(Effect.Move(Objects.Bound("chosen"), Destination(Zone.Exile), postBind = "exiled")),
                Step.Do(Effect.Shuffle(Players.You)),
                Step.Do(Effect.ApplyMechanics(listOf(Mechanic.MayPlay(Zone.Exile, PlayKind.Cast, holder = PlayerFilter.You)), Affected.Objects(Objects.Bound("exiled")),
                    arcanum.api.Duration.EndOfTurn)))
        }
        return null
    }

    private fun eclStatic3(line: String): Ability? {
        // ecl chunk 06: "As this artifact enters, choose Elemental, Elf, Faerie, Giant, Goblin, Kithkin, Merfolk, or Treefolk." (a creature type of
        // those, kept as the chosen type, CR 614.12, 607.2d)
        Ecl.AS_ENTERS_CHOOSE_TYPE_AMONG.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val types = m.groupValues[2].split(LazyRegexes.OR_LIST).map { it.takeIf { t -> t in RulesWords.subtypes } ?: return@let }
            return Ability.Static(listOf(Mechanic.Replacement(EventPattern.ZoneChange(ObjectFilter.Is(Objects.Self), to = Zone.Battlefield), modify = listOf(
                Modification.AsEnters(listOf(Step.Choose(arcanum.api.Choice.CreatureTypeAmong(types.map { Subtype(it) }), bind = "type", chooser = Players.You,
                    remember = true)))))), affects = eclSelfOnly)
        }
        // ecl chunk 06: "You may have this creature enter as a copy of any creature on the battlefield, except it has changeling." (CR 707.9b, 614.1c)
        Ecl.MAY_ENTER_AS_COPY_EXCEPT.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val except = eclCopyExceptions(m.groupValues[2]) ?: return null
            return Ability.Static(listOf(Mechanic.Replacement(EventPattern.ZoneChange(ObjectFilter.Is(Objects.Self), to = Zone.Battlefield),
                modify = listOf(Modification.EntersAsCopy(ObjectFilter.Type(CardType.Creature), except, optional = true)))), affects = eclSelfOnly)
        }
        return null
    }

    private fun eclStatic2(line: String): Ability? {
        // ecl chunk 10: "Creatures you control get +X/+X, where X is the number of creatures that entered the battlefield under your control this turn."
        Ecl.GET_X_X_WHERE.matchEntire(line)?.let { m ->
            val filter = Filters.noun(m.groupValues[1]) ?: Filters.noun(m.groupValues[1].replaceFirstChar { it.lowercase() }) ?: return@let
            val x = Values.value(m.groupValues[2]) ?: return@let
            return Ability.Static(listOf(Mechanic.ModifyPowerToughness(x, x)), affects = Affected.Objects(Objects.Each(filter)))
        }
        // ecl chunk 14: "This creature gets +1/+1 for each creature you control and each creature card in your graveyard."
        Ecl.GETS_FOR_EACH_AND_EACH.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val a = Filters.noun(m.groupValues[2]) ?: return null
            val b = Filters.noun(m.groupValues[3]) ?: return null
            val count = Value.Sum(listOf(Value.Count(Objects.Each(a)), Value.Count(Objects.Each(b))))
            return Ability.Static(listOf(Mechanic.ModifyPowerToughness(count, count)), affects = eclSelfOnly)
        }
        // ecl chunk 13: "Double all damage that sources you control of the chosen type would deal." (CR 614.1a)
        if (line == "Double all damage that sources you control of the chosen type would deal.")
            return Ability.Static(listOf(Mechanic.Replacement(EventPattern.Damage(Filters.all(ObjectFilter.ControlledBy(PlayerFilter.You),
                ObjectFilter.Sub(arcanum.api.SubtypeRef.Remembered("type"))), RecipientFilter()), modify = listOf(Modification.MultiplyAmount(2)))), affects = eclSelfOnly)
        // ecl chunk 16: "Spells you cast of the chosen type cost {1} less to cast." (CR 601.2f)
        Ecl.SPELLS_OF_CHOSEN_TYPE_COST_LESS.matchEntire(line)?.let { m ->
            val spells = Filters.all(ObjectFilter.Category(arcanum.api.ObjectCategory.Spell), ObjectFilter.ControlledBy(PlayerFilter.You),
                ObjectFilter.Sub(arcanum.api.SubtypeRef.Remembered("type")))
            return Ability.Static(listOf(Mechanic.CostChange(spells, arcanum.api.CostChange.Less(ManaCost.parse(m.groupValues[1]) ?: return null, Value.Fixed(1)))),
                affects = eclSelfOnly)
        }
        // ecl chunk 15: "Each creature spell you cast with toughness greater than its power costs {1} less to cast."
        Ecl.CREATURE_SPELL_TOUGHNESS_GREATER_COSTS_LESS.matchEntire(line)?.let { m ->
            val spells = Filters.all(ObjectFilter.Category(arcanum.api.ObjectCategory.Spell), ObjectFilter.Type(CardType.Creature), ObjectFilter.ControlledBy(PlayerFilter.You),
                ObjectFilter.Toughness(arcanum.api.Comparison.Greater, Value.Of(arcanum.api.NumericProperty.Power, Objects.Tested, arcanum.api.Combine.Single)))
            return Ability.Static(listOf(Mechanic.CostChange(spells, arcanum.api.CostChange.Less(ManaCost.parse(m.groupValues[1]) ?: return null, Value.Fixed(1)))),
                affects = eclSelfOnly)
        }
        // ecl chunk 15: "Each noncreature spell you cast has conspire." (CR 702.78a: it has conspire while on the Stack)
        Ecl.EACH_SPELL_YOU_CAST_HAS.matchEntire(line)?.let { m ->
            val kind = Filters.noun(m.groupValues[1] + " spell") ?: return null
            val keyword = OracleParser.keyword(m.groupValues[2].replaceFirstChar { it.uppercase() }) ?: return null
            return Ability.Static(listOf(Mechanic.GainAbilities(listOf(keyword))), affects = Affected.Objects(Objects.Each(Filters.all(kind, ObjectFilter.ControlledBy(PlayerFilter.You)))))
        }
        // ecl chunk 15: "Each other creature you control has hexproof from each of its colors." (CR 702.11d, 105.2)
        Ecl.HEXPROOF_FROM_EACH_OF_ITS_COLORS.matchEntire(line)?.let { m ->
            val filter = Filters.noun(m.groupValues[1]) ?: return null
            return Ability.Static(listOf(Mechanic.GainAbilities(listOf(arcanum.api.Keyword.HexproofFrom(ObjectFilter.Shares(arcanum.api.SharedQuality.Color, Objects.Self))))),
                affects = Affected.Objects(Objects.Each(filter)))
        }
        // ecl chunk 15: "If a triggered ability of another Elemental you control triggers, it triggers an additional time." (CR 603.2d)
        Ecl.TRIGGERS_ADDITIONAL_TIME.matchEntire(line)?.let { m ->
            val sources = Filters.noun(m.groupValues[1]) ?: return null
            return Ability.Static(listOf(Mechanic.TriggersAdditionalTime(null, sources)), affects = eclSelfOnly)
        }
        // ecl chunk 14: "Enchanted land is the chosen color." (layer 5)
        if (line == "Enchanted land is the chosen color.")
            return Ability.Static(listOf(Mechanic.SetColors(listOf(ColorRef.Remembered(CHOSEN_COLOR)))), affects = Affected.Objects(Objects.AttachedTo(Objects.Self)))
        // ecl chunk 16: "Equipped creature gets +1/+1 and is all creature types."
        Ecl.EQUIPPED_GETS_AND_ALL_TYPES.matchEntire(line)?.let { m ->
            return Ability.Static(listOf(eclPt(m.groupValues[1].toInt(), m.groupValues[2].toInt()), Mechanic.AllCreatureTypes),
                affects = Affected.Objects(Objects.AttachedTo(Objects.Self)))
        }
        // ecl chunk 16: "As long as this Equipment is attached to a creature, the first time you would create one or more tokens each turn, you may
        // instead create that many tokens that are copies of equipped creature." (CR 614.1a; first each turn: no token created yet this turn)
        Ecl.FIRST_TIME_TOKENS_COPIES_OF_EQUIPPED.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            val yours = Filters.all(ObjectFilter.Category(arcanum.api.ObjectCategory.Token), ObjectFilter.OwnedBy(PlayerFilter.You))
            return Ability.Static(listOf(Mechanic.Replacement(EventPattern.CreateToken(yours), modify = listOf(
                Modification.CreateInstead(arcanum.api.TokenSpec.CopyOf(Objects.AttachedTo(Objects.Self)))), optional = true)), affects = eclSelfOnly,
                condition = arcanum.api.Condition.And(listOf(
                    arcanum.api.Condition.ObjectMatches(Objects.AttachedTo(Objects.Self), ObjectFilter.Type(CardType.Creature)),
                    arcanum.api.Condition.Not(arcanum.api.Condition.HappenedThisTurn(EventPattern.CreateToken(yours), atLeast = 1, measure = arcanum.api.Measure.Events)))))
        }
        // ecl chunk 15: "Once each turn, you may cast a spell with mana value less than or equal to the number of Elves and Faeries you control from
        // among cards exiled with Maralen this turn without paying its mana cost." (CR 601.2a)
        Ecl.ONCE_EACH_TURN_CAST_EXILED_WITH.matchEntire(line)?.takeIf { isSelf(it.groupValues[2]) }?.let { m ->
            val count = Value.Count(Objects.Each(Filters.noun(m.groupValues[1].replace(" and ", " or ") + " you control") ?: return null))
            val cards = Filters.all(ObjectFilter.Is(Objects.Remembered(EXILED_WITH)), ObjectFilter.InZone(Zone.Exile),
                ObjectFilter.ThisTurn(EventPattern.ZoneChange(ObjectFilter.Any, to = Zone.Exile), role = EventRole.After))
            return Ability.Static(listOf(Mechanic.MayPlay(Zone.Exile, PlayKind.Cast, withoutPaying = true, perTurn = 1, holder = PlayerFilter.You,
                resultingSpell = ObjectFilter.ManaValue(arcanum.api.Comparison.AtMost, count))), affects = Affected.Objects(Objects.Each(cards)))
        }
        return null
    }

    private fun eclEffect2(sentence: String, context: Context): List<Step>? {
        // ecl chunk 10: "exile up to one target nonland permanent an opponent controls until this enchantment leaves the battlefield" (CR 610.3)
        Ecl.EXILE_UP_TO_ONE_UNTIL_LEAVES.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[2]) }?.let { m ->
            val noun = m.groupValues[1]
            val name = eclNewSlotName(context, Filters.slotName(noun))
            context.targets += eclSlot(name, Filters.noun(noun) ?: return null, min = 0)
            return listOf(Step.Do(Effect.Move(Objects.Target(name), Destination(Zone.Exile), untilLeaves = Objects.Self)))
        }
        // ecl chunk 10: "Exile enchanted creature."
        if (sentence == "Exile enchanted creature.") return listOf(Step.Do(Effect.Move(Objects.AttachedTo(Objects.Self), Destination(Zone.Exile))))
        // ecl chunk 11: "Up to one target creature gains all creature types." (indefinitely, layer 4)
        Ecl.GAINS_ALL_CREATURE_TYPES.matchEntire(sentence)?.let { m ->
            val name = eclNewSlotName(context, "creature")
            context.targets += eclSlot(name, ObjectFilter.Type(CardType.Creature), min = if (m.groupValues[1].startsWith("Up to")) 0 else 1)
            return listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.AllCreatureTypes), Affected.Objects(Objects.Target(name)), arcanum.api.Duration.Indefinitely)))
        }
        // ecl chunk 11: "Target creature gets -2/-0 until your next turn."
        Ecl.GETS_UNTIL_YOUR_NEXT_TURN.matchEntire(sentence)?.let { m ->
            val target = context.target("creature", ObjectFilter.Type(CardType.Creature))
            return listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.ModifyPowerToughness(ptChange(m.groupValues[1]) ?: return null, ptChange(m.groupValues[2]) ?: return null)),
                Affected.Objects(target), arcanum.api.Duration.UntilYourNextTurn)))
        }
        // ecl chunk 11: "Each nonland permanent you control becomes a copy of target non-Aura permanent." (layer 1, indefinitely)
        Ecl.EACH_BECOMES_COPY_OF_TARGET.matchEntire(sentence)?.let { m ->
            val each = Filters.noun(m.groupValues[1]) ?: return null
            val target = context.target(Filters.slotName(m.groupValues[2]), Filters.noun(m.groupValues[2]) ?: return null)
            return listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.CopyOf(target)), Affected.Objects(Objects.Each(each)), arcanum.api.Duration.Indefinitely)))
        }
        // ecl chunk 11: "The owner of target spell or creature puts it on their choice of the top or bottom of their library." (CR 401.4)
        Ecl.OWNER_PUTS_TOP_OR_BOTTOM.matchEntire(sentence)?.let { m ->
            val target = context.target(Filters.slotName(m.groupValues[1]), Filters.noun(m.groupValues[1]) ?: return null)
            return eclOwnerChoosesPosition(target, "top", 0, "bottom", -1)
        }
        Ecl.OWNER_PUTS_SECOND_OR_BOTTOM.matchEntire(sentence)?.let { m ->
            val target = context.target(Filters.slotName(m.groupValues[1]), Filters.noun(m.groupValues[1]) ?: return null)
            return eclOwnerChoosesPosition(target, "second from the top", 1, "bottom", -1)
        }
        // ecl chunk 11: 'target creature gains "Whenever this creature deals combat damage to a player or planeswalker, draw a card" until end of turn.'
        Ecl.TARGET_GAINS_QUOTED.matchEntire(sentence)?.let { m ->
            val granted = eclKeywordsAndQuoted("\"${m.groupValues[1]}\"", setOf("this creature")) ?: return null
            val target = context.target("creature", ObjectFilter.Type(CardType.Creature))
            return listOf(eclUntilEndOfTurn(target, Mechanic.GainAbilities(granted)))
        }
        // ecl chunk 07: "target creature you control gains protection from each color until your next turn." (from every coloured object)
        if (Ecl.GAINS_PROTECTION_EACH_COLOR_UNTIL_NEXT_TURN.matches(sentence)) {
            val target = context.target("creature", Filters.noun("creature you control")!!)
            return listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.GainAbilities(listOf(arcanum.api.Keyword.Protection(ObjectFilter.Not(ObjectFilter.Colorless))))),
                Affected.Objects(target), arcanum.api.Duration.UntilYourNextTurn)))
        }
        // ecl chunk 12: "Target creature gets +3/-3 and loses all creature types until end of turn."
        Ecl.GETS_AND_LOSES_ALL_TYPES.matchEntire(sentence)?.let { m ->
            val target = context.target("creature", ObjectFilter.Type(CardType.Creature))
            return listOf(eclUntilEndOfTurn(target, Mechanic.ModifyPowerToughness(ptChange(m.groupValues[1]) ?: return null, ptChange(m.groupValues[2]) ?: return null),
                Mechanic.LoseAllCreatureTypes))
        }
        // ecl chunk 12: "Target opponent exiles two cards from their hand." (they choose, CR 701.13)
        Ecl.TARGET_OPPONENT_EXILES_FROM_HAND.matchEntire(sentence)?.let { m ->
            val n = eclN(m.groupValues[1]) ?: return null
            val opponent = context.targetOpponent()
            return listOf(Step.Choose(arcanum.api.Choice.Objects(handOf(opponent), Value.Fixed(n), Value.Fixed(n)), bind = "chosen", chooser = opponent),
                Step.Do(Effect.Move(Objects.Bound("chosen"), Destination(Zone.Exile))))
        }
        // ecl chunk 12: "Return two target creature cards that share a creature type from your graveyard to your hand."
        Ecl.RETURN_TWO_SHARING_TYPE.matchEntire(sentence)?.let { m ->
            val filter = Filters.all(Filters.noun(m.groupValues[1]) ?: return null, ObjectFilter.InZone(Zone.Graveyard), ObjectFilter.OwnedBy(PlayerFilter.You))
            val name = eclNewSlotName(context, "creature cards")
            context.targets += TargetSlot(name, TargetKind.Objects(filter), min = Value.Fixed(2), max = Value.Fixed(2), sharing = arcanum.api.SharedQuality.CreatureType)
            return listOf(Step.Do(Effect.Move(Objects.Target(name), Destination(Zone.Hand))))
        }
        // ecl chunk 13: "Boulder Dash deals 2 damage to any target and 1 damage to any other target." (CR 115.3: two different targets)
        Ecl.DEALS_TO_ANY_AND_ANY_OTHER.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            context.anyTarget()
            val any = ObjectFilter.Or(listOf(ObjectFilter.Type(CardType.Creature), ObjectFilter.Type(CardType.Planeswalker), ObjectFilter.Type(CardType.Battle)))
            // fdn chunk 09: "… and 3 damage to each of up to two other targets" (CR 115.3: each target is a different one)
            val upTo = m.groupValues[4].takeIf { it.isNotEmpty() }?.let { Numbers.count(it) ?: return null }
            context.targets += TargetSlot("other", TargetKind.Either(any, PlayerFilter.Any), min = Value.Fixed(if (upTo == null) 1 else 0), max = Value.Fixed(upTo ?: 1), distinctFrom = listOf("any"))
            return listOf(Step.Do(Effect.DealDamage(Recipients(target = "any"), Value.Fixed(m.groupValues[2].toInt()), Objects.Self)),
                Step.Do(Effect.DealDamage(Recipients(target = "other"), Value.Fixed(m.groupValues[3].toInt()), Objects.Self)))
        }
        // ecl chunk 13: "Soul Immolation deals X damage to each opponent and each creature they control."
        Ecl.DEALS_X_TO_EACH_OPPONENT_AND_THEIR_CREATURES.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            return listOf(Step.Do(Effect.DealDamage(Recipients(players = Players.Each(PlayerFilter.Opponent),
                objects = Objects.Each(Filters.all(ObjectFilter.Type(CardType.Creature), ObjectFilter.ControlledBy(PlayerFilter.Opponent)))),
                Value.Announced(name = "X"), Objects.Self)))
        }
        // ecl chunk 14: "It deals damage equal to its power to up to one target creature an opponent controls." (the creature named before)
        Ecl.IT_DEALS_POWER_TO_UP_TO_ONE.matchEntire(sentence)?.let { m ->
            val it = context.targets.lastOrNull { it.what is TargetKind.Objects }?.let { Objects.Target(it.name) } ?: return null
            val name = eclNewSlotName(context, Filters.slotName(m.groupValues[1]))
            context.targets += eclSlot(name, Filters.noun(m.groupValues[1]) ?: return null, min = 0)
            return listOf(Step.Do(Effect.DealDamage(Recipients(objects = Objects.Target(name)), Value.Of(arcanum.api.NumericProperty.Power, it, arcanum.api.Combine.Single), it)))
        }
        // ecl chunk 14: "you gain life equal to the number of colors among permanents you control."
        Ecl.GAIN_LIFE_EQUAL_TO.matchEntire(sentence)?.let { m ->
            return listOf(Step.Do(Effect.GainLife(Players.You, Values.value(m.groupValues[1]) ?: return null)))
        }
        // ecl chunk 14: "enchanted creature fights up to one target creature an opponent controls." (CR 701.14)
        Ecl.ENCHANTED_FIGHTS_UP_TO_ONE.matchEntire(sentence)?.let { m ->
            val name = eclNewSlotName(context, Filters.slotName(m.groupValues[1]))
            context.targets += eclSlot(name, Filters.noun(m.groupValues[1]) ?: return null, min = 0)
            return listOf(Step.Do(Effect.Fight(Objects.AttachedTo(Objects.Self), Objects.Target(name))))
        }
        // ecl chunk 14: "up to X target creatures you control get +X/+X until end of turn"
        Ecl.UP_TO_X_TARGETS_GET_X.matchEntire(sentence)?.let { m ->
            val name = eclNewSlotName(context, "creatures")
            context.targets += TargetSlot(name, TargetKind.Objects(Filters.noun(m.groupValues[1].removeSuffix("s").replace("creatures", "creature")) ?: return null),
                min = Value.Fixed(0), max = Value.Announced(name = "X"))
            val x = Value.Announced(name = "X")
            return listOf(eclUntilEndOfTurn(Objects.Target(name), Mechanic.ModifyPowerToughness(x, x)))
        }
        // ecl chunk 14: "create a tapped Mutavault token." (a land token named Mutavault; its abilities as its reminder text gives them: "{T}: Add
        // {C}" and "{1}: This token becomes a 2/2 creature with all creature types until end of turn. It's still a land.", layers 4 and 7b)
        Ecl.CREATE_MUTAVAULT.matchEntire(sentence)?.let { m ->
            val inner = Sentences(setOf("this token"))
            val becomes = Ability.Activated(Cost.mana(ManaCost.parse("{1}")!!), Instructions(steps = listOf(eclUntilEndOfTurn(Objects.Self,
                Mechanic.SetTypes(add = listOf(CardType.Creature)), Mechanic.AllCreatureTypes, Mechanic.SetPowerToughness(Value.Fixed(2), Value.Fixed(2))))),
                arcanum.api.ActivationRules(timing = arcanum.api.Timing.Any, activatedBy = PlayerFilter.You),
                text = "{1}: This token becomes a 2/2 creature with all creature types until end of turn. It's still a land.")
            val face = arcanum.api.FaceDefinition("Mutavault", colorIndicator = emptyList(), types = listOf(CardType.Land), abilities = listOf(
                (inner.line("{T}: Add {C}.") as? Ability.Activated)?.copy(text = "{T}: Add {C}.") ?: return null, becomes))
            return listOf(Step.Do(Effect.CreateToken(arcanum.api.TokenSpec.Defined(face), Value.Fixed(1), Players.You, tapped = m.groupValues[1].isNotEmpty())))
        }
        // ecl chunk 15: "up to one other target creature loses all abilities." (indefinitely)
        Ecl.UP_TO_ONE_OTHER_LOSES_ALL.matchEntire(sentence)?.let { m ->
            val name = eclNewSlotName(context, "creature")
            context.targets += eclSlot(name, Filters.all(ObjectFilter.Not(ObjectFilter.Is(Objects.Self)), ObjectFilter.Type(CardType.Creature)), min = 0)
            return listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.LoseAbilities()), Affected.Objects(Objects.Target(name)), arcanum.api.Duration.Indefinitely)))
        }
        // ecl chunk 15: "Put a flying counter, a first strike counter, and a lifelink counter on that creature." (keyword counters, CR 122.1b)
        Ecl.PUT_KEYWORD_COUNTERS_ON.matchEntire(sentence)?.let { m ->
            val on = when (m.groupValues[2]) {
                "that creature", "it" -> context.targets.lastOrNull { it.what is TargetKind.Objects }?.let { Objects.Target(it.name) } ?: return null
                else -> return null
            }
            val kinds = m.groupValues[1].split(LazyRegexes.AND_LIST).map { Counters.kind(it.removePrefix("a ").removePrefix("an ").removeSuffix(" counter")) ?: return null }
            return kinds.map { Step.Do(Effect.PutCounters(on, it, Value.Fixed(1))) }
        }
        // ecl chunk 08: "Ashling's Command deals 2 damage to each creature target player controls."
        // inr chunk 05: "… to each creature target opponent controls."
        Ecl.DEALS_TO_EACH_CREATURE_TARGET_PLAYER_CONTROLS.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val player = if (m.groupValues[3] == "opponent") context.targetOpponent() else context.targetPlayer()
            return listOf(Step.Do(Effect.DealDamage(Recipients(objects = Objects.Each(Filters.all(ObjectFilter.Type(CardType.Creature),
                ObjectFilter.ControlledBy(PlayerFilter.Is(player))))), Value.Fixed(m.groupValues[2].toInt()), Objects.Self)))
        }
        // ecl chunk 08: "Creatures target player controls get +1/+1 and gain haste until end of turn.", "… gain lifelink until end of turn."
        Ecl.CREATURES_TARGET_PLAYER_CONTROLS_GET_GAIN.matchEntire(sentence)?.let { m ->
            val player = context.targetPlayer()
            val mechanics = mutableListOf<Mechanic>()
            if (m.groupValues[1].isNotEmpty()) mechanics += Mechanic.ModifyPowerToughness(ptChange(m.groupValues[1]) ?: return null, ptChange(m.groupValues[2]) ?: return null)
            if (m.groupValues[3].isNotEmpty()) mechanics += Mechanic.GainAbilities(keywords(m.groupValues[3]) ?: return null)
            return listOf(eclUntilEndOfTurn(Objects.Each(Filters.all(ObjectFilter.Type(CardType.Creature), ObjectFilter.ControlledBy(PlayerFilter.Is(player)))),
                *mechanics.toTypedArray()))
        }
        // ecl chunk 08: "Target player mills five cards, then puts each Goblin card milled this way into their hand."
        Ecl.MILLS_THEN_PUTS_EACH_INTO_HAND.matchEntire(sentence)?.let { m ->
            val player = context.targetPlayer()
            val filter = Filters.noun(m.groupValues[2]) ?: return null
            return listOf(Step.Do(Effect.Mill(player, Value.Fixed(eclN(m.groupValues[1]) ?: return null), postBind = "milled")),
                Step.Do(Effect.Move(Objects.Where(Objects.Bound("milled"), filter), Destination(Zone.Hand))))
        }
        // ecl chunk 08: "Return one or two target permanent cards from your graveyard to your hand."
        Ecl.RETURN_ONE_OR_TWO_FROM_GRAVEYARD.matchEntire(sentence)?.let { m ->
            val filter = Filters.all(Filters.noun(m.groupValues[1]) ?: return null, ObjectFilter.InZone(Zone.Graveyard), ObjectFilter.OwnedBy(PlayerFilter.You))
            val name = eclNewSlotName(context, m.groupValues[1])
            context.targets += eclSlot(name, filter, min = 1, max = 2)
            return listOf(Step.Do(Effect.Move(Objects.Target(name), Destination(Zone.Hand))))
        }
        // ecl chunk 15: "Create a 1/1 black and green Worm creature token for each land card in your graveyard."
        Ecl.CREATE_FOR_EACH.matchEntire(sentence)?.let { m ->
            val (one, token) = Tokens.spec(m.groupValues[1]) ?: return@let
            if (one != 1) return@let
            val count = Value.Count(Objects.Each(Filters.noun(m.groupValues[2]) ?: return@let))
            return listOf(Step.Do(Effect.CreateToken(token, count, Players.You)))
        }
        // ecl chunk 15: "exile the top two cards of target opponent's library." (kept as the cards exiled with this creature)
        Ecl.EXILE_TOP_OF_TARGET_OPPONENTS_LIBRARY.matchEntire(sentence)?.let { m ->
            val opponent = context.targetOpponent()
            val n = eclN(m.groupValues[1]) ?: return null
            val exile = Step.Do(Effect.Move(Objects.LibraryCards(opponent, Value.Fixed(n), fromTop = true), Destination(Zone.Exile), postBind = "exiled"))
            return if (linkedExile) listOf(exile, Step.Do(Effect.Remember(EXILED_WITH, Objects.Bound("exiled")))) else listOf(exile)
        }
        // ecl chunk 15: "Target creature you control becomes all colors until end of turn." (layer 5)
        Ecl.BECOMES_ALL_COLORS.matchEntire(sentence)?.let { m ->
            val target = context.target(Filters.slotName(m.groupValues[1]), Filters.noun(m.groupValues[1]) ?: return null)
            return listOf(eclUntilEndOfTurn(target, Mechanic.SetColors(arcanum.api.Color.all.map { ColorRef.Literal(it) })))
        }
        // ecl chunk 16: "This artifact becomes the chosen color." (for good, layer 5)
        Ecl.BECOMES_THE_CHOSEN_COLOR.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            return listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.SetColors(listOf(ColorRef.Chosen("color")))), Affected.Objects(Objects.Self),
                arcanum.api.Duration.Indefinitely)))
        }
        // ecl chunk 14: "its controller adds an additional one mana of the chosen color." (a triggered mana ability, CR 605.1b)
        if (sentence == "Its controller adds an additional one mana of the chosen color.") {
            val of = context.it ?: return null
            return listOf(Step.Do(Effect.AddMana(ManaProduction(ManaKind.Choose(Value.Fixed(1), listOf(ColorRef.Remembered(CHOSEN_COLOR)))), Players.ControllerOf(of))))
        }
        // ecl chunk 07: "Add X {G} or X {W}." (X of one of the two colours, CR 106.1)
        Ecl.ADD_X_OR_X.matchEntire(sentence)?.let { m ->
            val colors = listOf(m.groupValues[1], m.groupValues[2]).map { ColorRef.Literal(arcanum.api.Color.of(it[0]) ?: return null) }
            return listOf(Step.Do(Effect.AddMana(ManaProduction(ManaKind.Choose(Value.Announced(name = "X"), colors)), Players.You)))
        }
        // ecl chunk 12: "Exile that many cards from the top of your library." (as many as the counters on the creature that died, CR 603.10a)
        if (sentence == "Exile that many cards from the top of your library.") {
            val event = context.event as? EventPattern.ZoneChange ?: return null
            if (event.to != Zone.Graveyard) return null
            context.it = Objects.Bound("exiled")
            return listOf(Step.Do(Effect.Move(Objects.LibraryCards(Players.You, Value.Of(arcanum.api.NumericProperty.Counters(null), Objects.EventObject(EventRole.Before),
                arcanum.api.Combine.Single), fromTop = true), Destination(Zone.Exile), postBind = "exiled")))
        }
        return null
    }

    /** ecl chunk 11: "The owner of target … puts it on their choice of …": the owner chooses where it goes (CR 401.4). */
    private fun eclOwnerChoosesPosition(target: Objects, first: String, firstPosition: Int, second: String, secondPosition: Int): List<Step> {
        val owner = Players.OwnerOf(target)
        return listOf(Step.Choose(arcanum.api.Choice.Option(listOf(first, second)), bind = "position", chooser = owner),
            Step.If(arcanum.api.Condition.Chose("position", first),
                then = listOf(Step.Do(Effect.Move(target, Destination(Zone.Library, libraryPosition = firstPosition)))),
                otherwise = listOf(Step.Do(Effect.Move(target, Destination(Zone.Library, libraryPosition = secondPosition))))))
    }

    private fun eclWhole2(text: String, context: Context): List<Step>? {
        // ecl chunk 10: "Look at the top X cards of your library. You may put any number of … from among them onto the battlefield. Then shuffle."
        Ecl.LOOK_TOP_X_PUT_ANY_NUMBER.matchEntire(text)?.let { m ->
            val filter = Filters.noun(m.groupValues[1]) ?: return null
            return listOf(Step.Do(Effect.LookAt(Objects.LibraryCards(Players.You, Value.Announced(name = "X"), fromTop = true), Players.You, bind = "seen")),
                Step.Choose(arcanum.api.Choice.Objects(filter, Value.Fixed(0), null, from = Objects.Bound("seen")), bind = "chosen", chooser = Players.You),
                Step.Do(Effect.Move(Objects.Bound("chosen"), Destination(Zone.Battlefield))),
                Step.Do(Effect.Shuffle(Players.You)))
        }
        // ecl chunk 12: "You may blight 2. If you don't, you lose 3 life." (CR 118.12)
        Ecl.MAY_BLIGHT_IF_YOU_DONT.matchEntire(text)?.let { m ->
            val then = effect(eclCap(m.groupValues[2]), context) ?: return null
            return listOf(Step.Pay(Cost(listOf(eclBlightCost(Value.Fixed(m.groupValues[1].toInt())))), payer = Players.You, bind = "paid"),
                Step.If(arcanum.api.Condition.Not(arcanum.api.Condition.Did("paid")), then = then))
        }
        // ecl chunk 15: "You may pay {2}. If you don't, blight 2."
        Ecl.MAY_PAY_IF_YOU_DONT_BLIGHT.matchEntire(text)?.let { m ->
            val cost = ManaCost.parse(m.groupValues[1]) ?: return null
            return listOf(Step.Pay(Cost.mana(cost), payer = Players.You, bind = "paid"),
                Step.If(arcanum.api.Condition.Not(arcanum.api.Condition.Did("paid")),
                    then = listOf(Step.Do(Effect.Action(eclBlight(Players.You, Value.Fixed(m.groupValues[2].toInt())), bind = "blighted")))))
        }
        // ecl chunk 11: "Choose up to one other target creature. Until end of turn, that creature has base power and toughness 4/4 and gains all
        // creature types." (layers 7b and 4)
        Ecl.CHOOSE_UP_TO_ONE_OTHER_BASE_PT_ALL_TYPES.matchEntire(text)?.let { m ->
            val name = eclNewSlotName(context, "creature")
            context.targets += eclSlot(name, Filters.all(ObjectFilter.Not(ObjectFilter.Is(Objects.Self)), ObjectFilter.Type(CardType.Creature)), min = 0)
            return listOf(eclUntilEndOfTurn(Objects.Target(name), Mechanic.SetPowerToughness(Value.Fixed(m.groupValues[1].toInt()), Value.Fixed(m.groupValues[2].toInt())),
                Mechanic.AllCreatureTypes))
        }
        // ecl chunk 11: "Counter all spells your opponents control and all abilities your opponents control. Create a 1/1 … token with flying for
        // each spell and ability countered this way." (those still on the Stack weren't countered)
        Ecl.COUNTER_ALL_OPPONENTS_CREATE_FOR_EACH.matchEntire(text)?.let { m ->
            val (one, token) = Tokens.spec(m.groupValues[1]) ?: return null
            if (one != 1) return null
            val theirs = Filters.all(ObjectFilter.Or(listOf(ObjectFilter.Category(arcanum.api.ObjectCategory.Spell), ObjectFilter.Category(arcanum.api.ObjectCategory.StackAbility))),
                ObjectFilter.ControlledBy(PlayerFilter.Opponent))
            val countered = Value.Difference(Value.Count(Objects.Bound("countered")),
                Value.Count(Objects.Where(Objects.Bound("countered"), ObjectFilter.InZone(Zone.Stack))))
            return listOf(Step.Bind(Objects.Each(theirs), "countered"), Step.Do(Effect.Counter(Objects.Bound("countered"))),
                Step.Do(Effect.CreateToken(token, countered, Players.You)))
        }
        // ecl chunk 06: "Choose a creature type. Draw a card for each permanent you control of that type."
        Ecl.CHOOSE_TYPE_DRAW_FOR_EACH.matchEntire(text)?.let { m ->
            val filter = Filters.all(Filters.noun(m.groupValues[1]) ?: return null, ObjectFilter.Sub(arcanum.api.SubtypeRef.Chosen("type")))
            return listOf(Step.Choose(arcanum.api.Choice.CreatureType, bind = "type", chooser = Players.You),
                Step.Do(Effect.Draw(Players.You, Value.Count(Objects.Each(filter)))))
        }
        // ecl chunk 11: "Tap up to two target creatures. Put a stun counter on each of them."
        Ecl.TAP_UP_TO_TWO_STUN_EACH.matchEntire(text)?.let { m ->
            val n = eclN(m.groupValues[1]) ?: return null
            val name = eclNewSlotName(context, "creatures")
            context.targets += eclSlot(name, ObjectFilter.Type(CardType.Creature), min = 0, max = n)
            return listOf(Step.Do(Effect.Tap(Objects.Target(name))), Step.Do(Effect.PutCounters(Objects.Target(name), arcanum.api.CounterKind.Stun, Value.Fixed(1))))
        }
        // ecl chunk 11: "When you next cast an instant or sorcery spell this turn, copy it. You may choose new targets for the copy." (CR 603.7c)
        if (Ecl.NEXT_INSTANT_SORCERY_COPY.matches(text)) {
            val spells = Filters.noun("instant or sorcery spell") ?: return null
            return listOf(Step.Do(Effect.CreateDelayedTrigger(arcanum.api.Trigger.On(EventPattern.Cast(spells, PlayerFilter.You)), Instructions(steps = listOf(
                Step.Do(Effect.CopySpell(Objects.EventObject(EventRole.Object), Players.You, newTargets = true)))), duration = arcanum.api.Duration.EndOfTurn)))
        }
        // ecl chunk 11: "Return one or two target nonland permanents to their owners' hands. Then if you control a Merfolk, create a 1/1 … token for
        // each permanent returned to its owner's hand this way."
        Ecl.RETURN_ONE_OR_TWO_THEN_IF_CREATE_FOR_EACH.matchEntire(text)?.let { m ->
            val name = eclNewSlotName(context, "permanents")
            context.targets += eclSlot(name, Filters.noun(m.groupValues[1].removeSuffix("s")) ?: return null, min = 1, max = 2)
            val (one, token) = Tokens.spec(m.groupValues[3]) ?: return null
            if (one != 1) return null
            val condition = Conditions.condition("you control a ${m.groupValues[2]}", self) ?: return null
            return listOf(Step.Do(Effect.Move(Objects.Target(name), Destination(Zone.Hand), postBind = "returned")),
                Step.If(condition, then = listOf(Step.Do(Effect.CreateToken(token, Value.Count(Objects.Where(Objects.Bound("returned"), ObjectFilter.InZone(Zone.Hand))), Players.You)))))
        }
        // ecl chunk 12: "Target opponent reveals X cards from their hand, where X is …. You choose one of those cards. That player exiles it. If an instant
        // or sorcery card is exiled this way, you may cast it for as long as you control this creature, and mana of any type can be spent …"
        Ecl.REVEALS_X_YOU_CHOOSE_EXILES_BODY.matchEntire(text)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            val opponent = context.targetOpponent()
            val x = Value.Announced(name = "X")
            return listOf(Step.Choose(arcanum.api.Choice.Objects(handOf(opponent), x, x), bind = "revealed", chooser = opponent),
                Step.Do(Effect.Reveal(Objects.Bound("revealed"))),
                Step.Choose(arcanum.api.Choice.Objects(ObjectFilter.Any, Value.Fixed(1), Value.Fixed(1), from = Objects.Bound("revealed")), bind = "chosen", chooser = Players.You),
                Step.Do(Effect.Move(Objects.Bound("chosen"), Destination(Zone.Exile), postBind = "exiled")),
                Step.If(arcanum.api.Condition.ObjectMatches(Objects.Bound("exiled"), Filters.noun("instant or sorcery card")!!), then = listOf(
                    Step.Do(Effect.ApplyMechanics(listOf(Mechanic.MayPlay(Zone.Exile, PlayKind.Cast, holder = PlayerFilter.You, manaAsAnyColor = true)),
                        Affected.Objects(Objects.Bound("exiled")),
                        arcanum.api.Duration.AsLongAs(arcanum.api.Condition.ObjectMatches(Objects.Self, ObjectFilter.ControlledBy(PlayerFilter.You))))))))
        }
        // ecl chunk 12: "When that creature dies this turn, …" (a delayed trigger on the creature named before, CR 603.7)
        Ecl.WHEN_THAT_CREATURE_DIES_THIS_TURN.matchEntire(text)?.let { m ->
            val first = text.substring(0, m.range.first + m.groupValues[1].length).trim()
            val firstSteps = mutableListOf<Step>()
            for (sentence in sentences(first)) firstSteps += effect(sentence, context) ?: return null
            val creature = context.targets.lastOrNull { it.what is TargetKind.Objects }?.let { Objects.Target(it.name) } ?: return null
            val dies = EventPattern.ZoneChange(ObjectFilter.Is(creature), from = Zone.Battlefield, to = Zone.Graveyard)
            val delayed = eclDiesThisTurnInstructions(m.groupValues[2], dies) ?: return null
            return firstSteps + Step.Do(Effect.CreateDelayedTrigger(arcanum.api.Trigger.On(dies), delayed, duration = arcanum.api.Duration.EndOfTurn))
        }
        // ecl chunk 13: "Discard a card. If you do, draw a card." (a mandatory cost paid on resolution, CR 118.12)
        Ecl.DISCARD_IF_YOU_DO.matchEntire(text)?.let { m ->
            val then = effect(eclCap(m.groupValues[1]), context) ?: return null
            return listOf(Step.Pay(Cost(listOf(CostPart.Discard(CostObjects.Choose(ObjectFilter.Category(arcanum.api.ObjectCategory.Card), count = Value.Fixed(1))))),
                payer = Players.You, mandatory = true, bind = "paid"), Step.If(arcanum.api.Condition.Did("paid"), then = then))
        }
        // ecl chunk 13: "You may put a creature card with total power and toughness 5 or less from your hand onto the battlefield. That creature
        // gains haste. At the beginning of the next end step, sacrifice that creature."
        Ecl.MAY_PUT_TOTAL_PT_HASTE_SACRIFICE.matchEntire(text)?.let { m ->
            // inr chunk 08: Through the Breach, any creature card
            val total = m.groupValues[1].takeIf { it.isNotEmpty() }?.let { n -> ObjectFilter.Where(arcanum.api.Condition.Compare(Value.Sum(listOf(
                Value.Of(arcanum.api.NumericProperty.Power, Objects.Tested, arcanum.api.Combine.Single),
                Value.Of(arcanum.api.NumericProperty.Toughness, Objects.Tested, arcanum.api.Combine.Single))), arcanum.api.Comparison.AtMost, Value.Fixed(n.toInt()))) }
            val cards = Filters.all(*listOfNotNull(ObjectFilter.Type(CardType.Creature), total, ObjectFilter.InZone(Zone.Hand), ObjectFilter.OwnedBy(PlayerFilter.You)).toTypedArray())
            return listOf(Step.Choose(arcanum.api.Choice.Objects(cards, Value.Fixed(0), Value.Fixed(1)), bind = "chosen", chooser = Players.You),
                Step.Do(Effect.Move(Objects.Bound("chosen"), Destination(Zone.Battlefield), postBind = "put")),
                Step.Do(Effect.ApplyMechanics(listOf(Mechanic.GainAbilities(listOf(arcanum.api.Keyword.Haste))), Affected.Objects(Objects.Bound("put")), arcanum.api.Duration.Indefinitely)),
                Step.Do(Effect.CreateDelayedTrigger(arcanum.api.Trigger.On(EventPattern.StepBegins(arcanum.api.TurnStep.End, PlayerFilter.Any)),
                    Instructions(steps = listOf(Step.Do(Effect.Sacrifice(Objects.Bound("put"))))))))
        }
        // ecl chunk 13: "Exile the top two cards of your library. If this spell's additional cost was paid, exile the top three cards instead. Until the
        // end of your next turn, you may play those cards."
        Ecl.EXILE_TOP_INSTEAD_IF.matchEntire(text)?.let { m ->
            val condition = Conditions.condition(m.groupValues[2], self) ?: return null
            val usual = effect("Exile the top ${m.groupValues[1]} cards of your library.", context) ?: return null
            val instead = effect("Exile the top ${m.groupValues[3]} cards of your library.", context) ?: return null
            val rest = effect(m.groupValues[4], context) ?: return null
            return listOf(Step.If(condition, then = instead, otherwise = usual)) + rest
        }
        // ecl chunk 13: "Whenever you cast …, you may copy it. If you do, those spells gain wither. You may choose new targets for the copy."
        Ecl.MAY_COPY_IT_THOSE_GAIN.matchEntire(text)?.let { m ->
            val keyword = OracleParser.keyword(m.groupValues[1].replaceFirstChar { it.uppercase() }) ?: return null
            val spell = Objects.EventObject(EventRole.Object)
            return listOf(Step.Pay(steps = listOf(Step.Do(Effect.CopySpell(spell, Players.You, newTargets = true, bind = "copy"))), payer = Players.You, bind = "paid"),
                Step.If(arcanum.api.Condition.Did("paid"), then = listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.GainAbilities(listOf(keyword))),
                    Affected.Objects(Objects.Union(listOf(spell, Objects.Bound("copy")))), arcanum.api.Duration.Indefinitely)))))
        }
        // ecl chunk 14: "Reveal cards from the top of your library until you reveal X permanent cards. Put any number of those permanent cards onto the
        // battlefield, then put the rest of the revealed cards on the bottom of your library in a random order."
        Ecl.REVEAL_UNTIL_X_PUT_ANY_NUMBER.matchEntire(text)?.let { m ->
            val filter = Filters.noun(m.groupValues[1].removeSuffix("s")) ?: return null
            return listOf(Step.Do(Effect.RevealUntil(filter, Players.You, Value.Announced(name = "X"), reveal = true, foundBind = "found", restBind = "rest")),
                Step.Choose(arcanum.api.Choice.Objects(ObjectFilter.Any, Value.Fixed(0), null, from = Objects.Bound("found")), bind = "chosen", chooser = Players.You),
                Step.Do(Effect.Move(Objects.Bound("chosen"), Destination(Zone.Battlefield))),
                Step.Do(Effect.Move(Objects.Except(Objects.Union(listOf(Objects.Bound("found"), Objects.Bound("rest"))), Objects.Bound("chosen")),
                    Destination(Zone.Library, libraryPosition = -1, randomOrder = true))))
        }
        // ecl chunk 14: "Search your library for a creature card with mana value X or less, reveal it, put it into your hand, then shuffle. If this
        // spell's additional cost was paid and the revealed card is the chosen type, put that card onto the battlefield instead of putting it into
        // your hand."
        Ecl.SEARCH_HAND_INSTEAD_BATTLEFIELD_IF.matchEntire(text)?.let { m ->
            val filter = Filters.noun(m.groupValues[1]) ?: return null
            val condition = arcanum.api.Condition.And(listOf(Conditions.condition(m.groupValues[2], self) ?: return null,
                arcanum.api.Condition.ObjectMatches(Objects.Bound("found"), ObjectFilter.Sub(arcanum.api.SubtypeRef.Chosen("type")))))
            return listOf(Step.Do(Effect.Search(Players.You, filter, max = Value.Fixed(1), reveal = true, zones = listOf(Zone.Library), bind = "found", searcher = Players.You)),
                Step.If(condition, then = listOf(Step.Do(Effect.Move(Objects.Bound("found"), Destination(Zone.Battlefield)))),
                    otherwise = listOf(Step.Do(Effect.Move(Objects.Bound("found"), Destination(Zone.Hand))))),
                Step.Do(Effect.Shuffle(Players.You)))
        }
        // ecl chunk 14: "Mill four cards, then you may return a permanent card from among them to your hand.", "… put a creature or land card from among
        // the milled cards on top of your library."
        Ecl.MILL_THEN_MAY_PUT_FROM_AMONG.matchEntire(text)?.let { m ->
            val filter = Filters.noun(m.groupValues[2]) ?: return null
            val to = if (m.groupValues[3] == "to your hand") Destination(Zone.Hand) else Destination(Zone.Library, libraryPosition = 0)
            return listOf(Step.Do(Effect.Mill(Players.You, Value.Fixed(eclN(m.groupValues[1]) ?: return null), postBind = "milled")),
                Step.Choose(arcanum.api.Choice.Objects(filter, Value.Fixed(0), Value.Fixed(1), from = Objects.Bound("milled")), bind = "chosen", chooser = Players.You),
                Step.Do(Effect.Move(Objects.Bound("chosen"), to)))
        }
        // ecl chunk 14: "Search your library for up to X basic land cards. Reveal those cards, put them into your hand, then shuffle."
        Ecl.SEARCH_UP_TO_X_REVEAL_HAND.matchEntire(text)?.let { m ->
            val filter = Filters.noun(m.groupValues[1].removeSuffix("s")) ?: return null
            return listOf(Step.Do(Effect.Search(Players.You, filter, max = Value.Announced(name = "X"), reveal = true, zones = listOf(Zone.Library), bind = "found", searcher = Players.You)),
                Step.Do(Effect.Move(Objects.Bound("found"), Destination(Zone.Hand))), Step.Do(Effect.Shuffle(Players.You)))
        }
        // ecl chunk 06: "Choose a creature type. Other permanents you control of that type gain hexproof and indestructible until end of turn."
        Ecl.CHOOSE_TYPE_THOSE_GAIN.matchEntire(text)?.let { m ->
            val filter = Filters.all(Filters.noun(m.groupValues[1].replaceFirstChar { it.lowercase() }) ?: return null, ObjectFilter.Sub(arcanum.api.SubtypeRef.Chosen("type")))
            return listOf(Step.Choose(arcanum.api.Choice.CreatureType, bind = "type", chooser = Players.You),
                eclUntilEndOfTurn(Objects.Each(filter), Mechanic.GainAbilities(keywords(m.groupValues[2]) ?: return null)))
        }
        // ecl chunk 14: "Choose exactly two creatures you control. You draw X cards and the chosen creatures get +X/+X and gain trample until end of
        // turn, where X is the difference between the chosen creatures' powers."
        Ecl.CHOOSE_TWO_DRAW_X_GET_X.matchEntire(text)?.let { m ->
            val filter = Filters.noun(m.groupValues[1]) ?: return null
            val chosen = Objects.Bound("chosen")
            val powers = listOf(arcanum.api.Combine.Greatest, arcanum.api.Combine.Least).map { Value.Of(arcanum.api.NumericProperty.Power, chosen, it) }
            val x = Value.Difference(powers[0], powers[1])
            return listOf(Step.Choose(arcanum.api.Choice.Objects(filter, Value.Fixed(2), Value.Fixed(2)), bind = "chosen", chooser = Players.You),
                Step.Do(Effect.Draw(Players.You, x)),
                eclUntilEndOfTurn(chosen, Mechanic.ModifyPowerToughness(x, x), Mechanic.GainAbilities(keywords(m.groupValues[2]) ?: return null)))
        }
        // ecl chunk 07: "Mill three cards, then you may exile an Elf card from your graveyard. If you do, each opponent loses 2 life."
        Ecl.THEN_YOU_MAY_IF_YOU_DO.matchEntire(text)?.let { m ->
            val first = effect(eclCap(m.groupValues[1]) + ".", context) ?: return null
            val then = effect("You may ${m.groupValues[2]}. If you do, ${m.groupValues[3]}", context) ?: return null
            return first + then
        }
        // ecl chunk 15: "Copy target triggered ability you control. You may choose new targets for the copy." (CR 707.10)
        if (text == "Copy target triggered ability you control. You may choose new targets for the copy.") {
            val ability = Filters.all(ObjectFilter.Category(arcanum.api.ObjectCategory.StackAbility), ObjectFilter.AbilityOf(kind = arcanum.api.AbilityKind.Triggered),
                ObjectFilter.ControlledBy(PlayerFilter.You))
            val target = context.target("ability", ability)
            return listOf(Step.Do(Effect.CopySpell(target, Players.You, newTargets = true)))
        }
        // ecl chunk 16: "Look at the top card of your library. If it's a card of the chosen type, you may reveal it and put it into your hand. If you
        // don't put the card into your hand, you may put it into your graveyard."
        if (text == "Look at the top card of your library. If it's a card of the chosen type, you may reveal it and put it into your hand. If you don't put the card into your hand, you may put it into your graveyard.") {
            val seen = Objects.Bound("seen")
            return listOf(Step.Do(Effect.LookAt(Objects.LibraryCards(Players.You, Value.Fixed(1), fromTop = true), Players.You, bind = "seen")),
                Step.If(arcanum.api.Condition.ObjectMatches(seen, ObjectFilter.Sub(arcanum.api.SubtypeRef.Remembered("type"))), then = listOf(
                    Step.Pay(steps = listOf(Step.Do(Effect.Reveal(seen)), Step.Do(Effect.Move(seen, Destination(Zone.Hand)))), payer = Players.You, bind = "put"))),
                Step.If(arcanum.api.Condition.Not(arcanum.api.Condition.Did("put")), then = listOf(
                    Step.May(listOf(Step.Do(Effect.Move(seen, Destination(Zone.Graveyard)))), player = Players.You))))
        }
        return null
    }

    /** ecl chunk 12: what a delayed "when that creature dies this turn" trigger does; "its power" is the creature's as it last existed. */
    private fun eclDiesThisTurnInstructions(text: String, dies: EventPattern): Instructions? {
        Ecl.EXILE_EQUAL_TO_ITS_POWER_CHOOSE_PLAY.matchEntire(text)?.let {
            val power = Value.Of(arcanum.api.NumericProperty.Power, Objects.EventObject(EventRole.Before), arcanum.api.Combine.Single)
            return Instructions(steps = listOf(
                Step.Do(Effect.Move(Objects.LibraryCards(Players.You, power, fromTop = true), Destination(Zone.Exile), postBind = "exiled")),
                Step.Choose(arcanum.api.Choice.Objects(ObjectFilter.Any, Value.Fixed(1), Value.Fixed(1), from = Objects.Bound("exiled")), bind = "chosen", chooser = Players.You),
                Step.Do(Effect.ApplyMechanics(listOf(Mechanic.MayPlay(Zone.Exile, PlayKind.Play, holder = PlayerFilter.You)), Affected.Objects(Objects.Bound("chosen")),
                    arcanum.api.Duration.UntilEndOfYourNextTurn))))
        }
        return instructions(eclCap(text), event = dies)
    }

    // ---- fin: Final Fantasy wordings (the set's parser tests, sets/fin/FinChunk*Test.kt); regexes in [Fin], phrases in [FinPhrases]

    /** fin chunk 05: the card has "When the chosen creature leaves the battlefield": its "choose a creature" is remembered (CR 607.2a). */
    var finChosenCreatureLinked = false

    /** fin: a tiered spell's modes "[name] — [cost] — [effect]" (CR 702.183a), the name a flavor word (CR 207.2d); with [body], a paragraph each
     * mode completes ("… has the chosen base power and toughness." and "• Galian Beast — {0} — 3/2."). */
    fun finTiered(body: String?, modeLines: List<String>): Ability.Spell? {
        if (modeLines.isEmpty()) return null
        val options = modeLines.map { modeLine ->
            val m = Fin.TIERED_MODE.matchEntire(modeLine) ?: return null
            val cost = arcanum.api.ManaCost.parse(m.groupValues[2]) ?: return null
            val effect = if (body == null) m.groupValues[3] else {
                val pt = Fin.PT_MODE.matchEntire(m.groupValues[3]) ?: return null
                if (!body.contains(" the chosen base power and toughness")) return null
                body.replace(" the chosen base power and toughness", " base power and toughness ${pt.groupValues[1]}")
            }
            arcanum.api.Mode(instructions(effect) ?: return null, extraCost = arcanum.api.Cost.mana(cost), text = modeLine)
        }
        return Ability.Spell(Instructions(modes = arcanum.api.Modes(options, min = 1, max = 1, chooser = Players.You)))
    }

    /** fin: lines that are more than one ability, tried when nothing else reads the line. */
    fun finMulti(line: String): List<Ability>? {
        // fin chunk 01: "Whenever [A] and whenever [B], [effect]": two trigger conditions, written as two abilities with one effect (as dgm's
        // "… and when this creature dies")
        Fin.WHENEVER_AND_WHENEVER.matchEntire(line)?.let { m ->
            val first = triggered("Whenever ${m.groupValues[1]}, ${m.groupValues[3]}") ?: return null
            val second = triggered("Whenever ${m.groupValues[2]}, ${m.groupValues[3]}") ?: return null
            return listOf(first, second)
        }
        // fin chunk 13: "You may play lands and cast Bird spells from the top of your library." (two permissions, CR 305.1, 601.2a)
        // mkm chunk 06: "… and cast creature and enchantment spells from the top of your library" (any spell noun)
        Fin.PLAY_LANDS_AND_CAST_SUBTYPE_FROM_TOP.matchEntire(line)?.let { m ->
            val spells = Filters.noun(m.groupValues[1].replace(" and ", " or ")) ?: return null
            fun top(cards: ObjectFilter, how: PlayKind) = Ability.Static(listOf(Mechanic.MayPlay(Zone.Library, how, topOnly = true, holder = PlayerFilter.You)),
                affects = arcanum.api.Affected.Objects(Objects.Each(Filters.all(cards, ObjectFilter.InZone(Zone.Library), ObjectFilter.OwnedBy(PlayerFilter.You)))))
            return listOf(top(ObjectFilter.Type(arcanum.api.CardType.Land), PlayKind.Play), top(spells, PlayKind.Cast))
        }
        // fin-multi-end
        return null
    }

    /** fin: whole lines no other rule reads, tried last by [line]. */
    private fun finLate(line: String): Ability? {
        // fin chunk 01: "Equipped creature gets +1/+1, has "[ability]," and is a Cleric in addition to its other types.": each clause read as a
        // sentence of its own about the same objects, their mechanics one static ability
        Fin.ATTACHED_CLAUSES.matchEntire(line)?.let { m ->
            val subject = m.groupValues[1]
            val clauses = finClauses(m.groupValues[2]) ?: return null
            if (clauses.size < 2) return null
            var affects: arcanum.api.Affected? = null
            val mechanics = clauses.flatMap { clause ->
                val quote = Fin.HAS_QUOTE.matchEntire(clause)
                val isA = Fin.IS_A_IN_ADDITION.matchEntire(clause)
                val ability = if (isA != null) {
                    val types = isA.groupValues[1].split(' ')
                    if (types.any { it !in RulesWords.subtypes }) return null
                    Ability.Static(listOf(Mechanic.SetTypes(addSubtypes = types.map { arcanum.api.SubtypeRef.Literal(arcanum.api.Subtype(it)) })),
                        affects = affects ?: arcanum.api.Affected.Objects(Objects.AttachedTo(Objects.Self)))
                } else if (quote != null) {
                    val text = quote.groupValues[1].trimEnd(',', '.') + "."
                    val granted = Sentences(setOf("this creature", "This creature")).let { it.multi(text) ?: it.line(text)?.let(::listOf) ?: it.finMulti(text) ?: return null }
                    Ability.Static(listOf(Mechanic.GainAbilities(granted)), affects = affects ?: arcanum.api.Affected.Objects(Objects.AttachedTo(Objects.Self)))
                } else static("$subject $clause.") as? Ability.Static ?: return null
                if (affects != null && ability.affects != affects) return null
                if (ability.condition != null) return null
                affects = ability.affects
                ability.mechanics
            }
            return Ability.Static(mechanics, affects = affects ?: return null)
        }
        // fin chunk 04: "During your turn, Aurel and other Knights you control have flying." (layer 6, only during your turn)
        Fin.DURING_YOUR_TURN_SELF_AND_OTHERS_HAVE.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val others = Filters.noun(m.groupValues[2]) ?: return null
            val granted = keywords(m.groupValues[3]) ?: return null
            return Ability.Static(listOf(Mechanic.GainAbilities(granted)), affects = arcanum.api.Affected.Objects(Objects.Union(listOf(Objects.Self,
                Objects.Each(Filters.all(ObjectFilter.Not(ObjectFilter.Is(Objects.Self)), others))))), condition = arcanum.api.Condition.YourTurn)
        }
        // fin chunk 05: "If a Wizard you control would deal damage to a permanent or player, it deals double that damage instead." (CR 614.1a)
        Fin.WOULD_DEAL_DAMAGE_DOUBLE.matchEntire(line)?.let { m ->
            val sources = Filters.noun(m.groupValues[1]) ?: return null
            return Ability.Static(listOf(Mechanic.Replacement(EventPattern.Damage(sources, RecipientFilter(objects = ObjectFilter.Category(arcanum.api.ObjectCategory.Permanent),
                players = PlayerFilter.Any)), modify = listOf(Modification.MultiplyAmount(2)))), affects = arcanum.api.Affected.Objects(Objects.Self))
        }
        // fin chunk 05: "When the chosen creature leaves the battlefield, transform Zerand." (the creature its enters ability chose, CR 607.2a)
        Fin.WHEN_CHOSEN_LEAVES.matchEntire(line)?.let { m ->
            val steps = instructions(m.groupValues[1].replaceFirstChar { it.uppercase() })?.takeIf { it.targets.isEmpty() }?.steps ?: return null
            return Ability.Triggered(arcanum.api.Trigger.On(EventPattern.ZoneChange(ObjectFilter.Is(Objects.Remembered("chosen")), from = Zone.Battlefield)),
                Instructions(steps = steps))
        }
        // fin chunk 05: "When the chosen player loses the game, you win the game." (the player chosen as it transformed)
        if (line == "When the chosen player loses the game, you win the game.") {
            return Ability.Triggered(arcanum.api.Trigger.On(EventPattern.LoseGame(PlayerFilter.Is(Players.Remembered("chosen player")))),
                Instructions(steps = listOf(Step.Do(Effect.WinGame(Players.You)))))
        }
        // fin chunk 05: "As this creature transforms into Shinryu, choose an opponent." (remembered as "the chosen player")
        Fin.AS_TRANSFORMS_CHOOSE_OPPONENT.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) && isSelf(it.groupValues[2]) }?.let { m ->
            val face = self.filter { it.first().isUpperCase() }.maxByOrNull { it.length } ?: return null
            return Ability.Static(listOf(Mechanic.Replacement(EventPattern.Transform(Filters.all(ObjectFilter.Is(Objects.Self), ObjectFilter.Named(face))),
                modify = listOf(Modification.AsTransforms(listOf(Step.Choose(arcanum.api.Choice.Player(PlayerFilter.Opponent), bind = "chosen player",
                    chooser = Players.You, remember = true)))))), affects = arcanum.api.Affected.Objects(Objects.Self))
        }
        // fin chunk 05: "As this creature transforms into [this face], [effect]" (CR 712.20: applied while it transforms, not afterward)
        Fin.AS_TRANSFORMS_INTO.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val face = self.filter { it.first().isUpperCase() }.maxByOrNull { it.length } ?: return null
            val named = self.filter { m.groupValues[2].startsWith("$it, ") }.maxByOrNull { it.length } ?: return null
            val steps = instructions(m.groupValues[2].removePrefix("$named, ").replaceFirstChar { it.uppercase() })?.takeIf { it.targets.isEmpty() }?.steps
                ?: return null
            return Ability.Static(listOf(Mechanic.Replacement(EventPattern.Transform(Filters.all(ObjectFilter.Is(Objects.Self), ObjectFilter.Named(face))),
                modify = listOf(Modification.AsTransforms(steps)))), affects = arcanum.api.Affected.Objects(Objects.Self))
        }
        // fin chunk 07: "If you would gain life, you gain twice that much life instead." (CR 614.1a)
        if (line == "If you would gain life, you gain twice that much life instead.")
            return Ability.Static(listOf(Mechanic.Replacement(EventPattern.GainLife(PlayerFilter.You), modify = listOf(Modification.MultiplyAmount(2)))),
                affects = arcanum.api.Affected.Objects(Objects.Self))
        // fin chunk 07: "As long as Cloud is equipped, if a triggered ability of Cloud or an Equipment attached to it triggers, that ability triggers an
        // additional time." (CR 603.2d)
        Fin.EQUIPPED_TRIGGERS_ADDITIONAL.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) && isSelf(it.groupValues[2]) }?.let {
            val equipment = ObjectFilter.Sub(Subtype("Equipment"))
            return Ability.Static(listOf(Mechanic.TriggersAdditionalTime(null, ObjectFilter.Or(listOf(ObjectFilter.Is(Objects.Self),
                Filters.all(equipment, ObjectFilter.Attached(to = Objects.Self)))))), affects = arcanum.api.Affected.Objects(Objects.Self),
                condition = arcanum.api.Condition.ObjectMatches(Objects.Self, ObjectFilter.Attached(to = null, attachments = equipment)))
        }
        // fin chunk 08: "You have protection from each of your opponents." (CR 702.16i, 702.16k: from everything those players control)
        if (line == "You have protection from each of your opponents.")
            return Ability.Static(listOf(Mechanic.GainAbilities(listOf(arcanum.api.Keyword.Protection(ObjectFilter.ControlledBy(PlayerFilter.Opponent))))),
                affects = arcanum.api.Affected.Players(Players.You))
        // fin chunk 08: "Artifact creatures and Heroes you control get +1/+1 for each Artificer you control and each Artificer card in your graveyard."
        Fin.GET_FOR_EACH_AND_EACH.matchEntire(line)?.let { m ->
            val affected = Filters.noun(m.groupValues[1]) ?: return null
            val p = m.groupValues[2].toInt()
            val t = m.groupValues[3].toInt()
            val first = Filters.noun(m.groupValues[4]) ?: return null
            val second = Filters.noun(m.groupValues[5]) ?: return null
            val per = Value.Sum(listOf(Value.Count(Objects.Each(first)), Value.Count(Objects.Each(second))))
            fun times(n: Int) = if (n == 1) per else Value.Times(per, n)
            return Ability.Static(listOf(Mechanic.ModifyPowerToughness(times(p), times(t))), affects = arcanum.api.Affected.Objects(Objects.Each(affected)))
        }
        // fin chunk 09: "As an additional cost to cast this spell, sacrifice a legendary creature or pay {2}." (one of two costs, CR 601.2b)
        Fin.ADDITIONAL_COST_OR.matchEntire(line)?.let { m ->
            val first = cost(m.groupValues[1].replaceFirstChar { it.uppercase() }) ?: return null
            val second = cost(m.groupValues[2].replaceFirstChar { it.uppercase() }) ?: return null
            return Ability.Static(listOf(Mechanic.AdditionalCost(cost = Cost(listOf(CostPart.OneOf(listOf(first, second)))))), affects = arcanum.api.Affected.Objects(Objects.Self))
        }
        // fin chunk 09: "As long as The Lunar Whale attacked this turn, you may play the top card of your library." (CR 305.1, 601.2a)
        Fin.ATTACKED_THIS_TURN_MAY_PLAY_TOP.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            return Ability.Static(listOf(Mechanic.MayPlay(Zone.Library, PlayKind.Play, topOnly = true, holder = PlayerFilter.You)),
                affects = arcanum.api.Affected.Objects(Objects.Each(Filters.all(ObjectFilter.InZone(Zone.Library), ObjectFilter.OwnedBy(PlayerFilter.You)))),
                condition = arcanum.api.Condition.HappenedThisTurn(EventPattern.Attack(ObjectFilter.Is(Objects.Self)), atLeast = 1, measure = arcanum.api.Measure.Events))
        }
        // fin chunk 09: "If an opponent would mill one or more cards, they mill that many cards plus four instead." (CR 614.1a)
        Fin.WOULD_MILL_PLUS.matchEntire(line)?.let { m ->
            val n = Numbers.count(m.groupValues[1]) ?: return null
            return Ability.Static(listOf(Mechanic.Replacement(EventPattern.Mill(PlayerFilter.Opponent), modify = listOf(Modification.AddAmount(Value.Fixed(n))))),
                affects = arcanum.api.Affected.Objects(Objects.Self))
        }
        // fin chunk 09: "Enchanted permanent doesn't untap during its controller's untap step and its activated abilities can't be activated."
        if (line == "Enchanted permanent doesn't untap during its controller's untap step and its activated abilities can't be activated.")
            return Ability.Static(listOf(Mechanic.DoesntUntap, Mechanic.CantBeActivated(manaAbilities = true)),
                affects = arcanum.api.Affected.Objects(Objects.AttachedTo(Objects.Self)))
        // fin chunk 09: "The first time you flip one or more coins each turn, those coins come up heads and you win those flips." (CR 705.2)
        if (line == "The first time you flip one or more coins each turn, those coins come up heads and you win those flips.") {
            val flip = EventPattern.FlipCoin(PlayerFilter.You)
            return Ability.Static(listOf(Mechanic.Replacement(flip, modify = listOf(Modification.WinFlips))), affects = arcanum.api.Affected.Objects(Objects.Self),
                condition = arcanum.api.Condition.Not(arcanum.api.Condition.HappenedThisTurn(flip, atLeast = 1, measure = arcanum.api.Measure.Events)))
        }
        // fin chunk 09: "{X}{X}, {T}: Copy target activated or triggered ability you control X times. You may choose new targets for the copies. This
        // ability can't be copied and X can't be 0." (CR 707.10, 107.3)
        Fin.COPY_ABILITY_X_TIMES.matchEntire(line)?.let { m ->
            val cost = cost(m.groupValues[1]) ?: return null
            val ability = Filters.all(ObjectFilter.Category(arcanum.api.ObjectCategory.StackAbility), ObjectFilter.Or(listOf(
                ObjectFilter.AbilityOf(kind = arcanum.api.AbilityKind.Activated), ObjectFilter.AbilityOf(kind = arcanum.api.AbilityKind.Triggered))),
                ObjectFilter.ControlledBy(PlayerFilter.You))
            val slot = TargetSlot("ability", TargetKind.Objects(ability), min = Value.Fixed(1), max = Value.Fixed(1))
            return Ability.Activated(cost, Instructions(targets = listOf(slot), steps = listOf(Step.Repeat(Value.Announced("X"),
                listOf(Step.Do(Effect.CopySpell(Objects.Target("ability"), Players.You, newTargets = true))))), announced = listOf("X")),
                arcanum.api.ActivationRules(timing = arcanum.api.Timing.Any, activatedBy = PlayerFilter.You, minimumX = 1, cantBeCopied = true))
        }
        // fin chunk 11: "As long as this creature has a counter on it, it can attack as though it didn't have defender." (CR 702.3b)
        Fin.HAS_A_COUNTER_ATTACK_DESPITE_DEFENDER.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            return Ability.Static(listOf(Mechanic.CanAttackDespiteDefender), affects = arcanum.api.Affected.Objects(Objects.Self),
                condition = arcanum.api.Condition.ObjectMatches(Objects.Self, ObjectFilter.HasCounter(null, atLeast = 1)))
        }
        // fin chunk 11: "If a nontoken creature an opponent controls would die, instead exile it and you gain 2 life." (CR 614.1a; the cards exiled are
        // remembered for "exiled with", CR 607.2a)
        Fin.WOULD_DIE_INSTEAD_EXILE_GAIN.matchEntire(line)?.let { m ->
            val dying = Filters.noun(m.groupValues[1]) ?: return null
            return Ability.Static(listOf(Mechanic.Replacement(EventPattern.ZoneChange(dying, from = Zone.Battlefield, to = Zone.Graveyard), instead = Instructions(steps = listOf(
                Step.Do(Effect.Move(Objects.EventObject(EventRole.Before), Destination(Zone.Exile), postBind = "exiled")),
                Step.Do(Effect.Remember(EXILED_WITH, Objects.Bound("exiled"))),
                Step.Do(Effect.GainLife(Players.You, Value.Fixed(m.groupValues[2].toInt()))))))), affects = arcanum.api.Affected.Objects(Objects.Self))
        }
        // fin chunk 11: "{4}{B}{B}, {T}: Put target creature card exiled with The Darkness Crystal onto the battlefield tapped under your control with two
        // additional +1/+1 counters on it."
        Fin.PUT_TARGET_EXILED_WITH_ONTO_BATTLEFIELD.matchEntire(line)?.takeIf { isSelf(it.groupValues[3]) }?.let { m ->
            val cost = cost(m.groupValues[1]) ?: return null
            val slot = TargetSlot("card", TargetKind.Objects(Filters.all(Filters.noun(m.groupValues[2]) ?: return null,
                ObjectFilter.InZone(Zone.Exile), ObjectFilter.Is(Objects.Remembered(EXILED_WITH)))),
                min = Value.Fixed(1), max = Value.Fixed(1))
            val n = Numbers.count(m.groupValues[4]) ?: return null
            return Ability.Activated(cost, Instructions(targets = listOf(slot), steps = listOf(Step.Do(Effect.Move(Objects.Target("card"), Destination(Zone.Battlefield,
                tapped = true, controller = Players.You, counters = listOf(arcanum.api.CountersToPut(arcanum.api.CounterKind.PowerToughness(1, 1), Value.Fixed(n)))))))),
                arcanum.api.ActivationRules(timing = arcanum.api.Timing.Any, activatedBy = PlayerFilter.You))
        }
        // fin chunk 13: "Damage isn't removed from this creature during cleanup steps." (CR 514.2)
        Fin.DAMAGE_NOT_REMOVED.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            return Ability.Static(listOf(Mechanic.DamageNotRemovedInCleanup), affects = arcanum.api.Affected.Objects(Objects.Self))
        }
        // fin chunk 13: "Prevent all combat damage that would be dealt to Diamond Weapon." (CR 615.1)
        Fin.PREVENT_COMBAT_DAMAGE_TO_SELF.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            return Ability.Static(listOf(Mechanic.Prevention(EventPattern.Damage(ObjectFilter.Any, RecipientFilter(objects = ObjectFilter.Is(Objects.Self)), combat = true))),
                affects = arcanum.api.Affected.Objects(Objects.Self))
        }
        // fin chunk 13: "If one or more +1/+1 counters would be put on a creature you control, twice that many +1/+1 counters are put on that creature
        // instead." (CR 614.1a)
        Fin.COUNTERS_DOUBLED.matchEntire(line)?.let { m ->
            val kind = Counters.kind(m.groupValues[1]) ?: return null
            // "twice that many" of the same kind
            if (m.groupValues[3] != m.groupValues[1]) return null
            val onto = Filters.noun(m.groupValues[2]) ?: return null
            return Ability.Static(listOf(Mechanic.Replacement(EventPattern.CountersPut(onto, kind), modify = listOf(Modification.MultiplyAmount(2)))),
                affects = arcanum.api.Affected.Objects(Objects.Self))
        }
        // fin chunk 13: "If one or more tokens would be created under your control, those tokens plus a 1/1 green Frog creature token are created instead."
        Fin.TOKENS_PLUS_ONE.matchEntire(line)?.let { m ->
            val token = Tokens.defined(m.groupValues[1]) ?: Tokens.defined("a " + m.groupValues[1]) ?: Tokens.spec("a " + m.groupValues[1])?.second ?: return null
            return Ability.Static(listOf(Mechanic.Replacement(EventPattern.CreateToken(ObjectFilter.ControlledBy(PlayerFilter.You)),
                modify = listOf(Modification.AlsoCreate(token, Value.Fixed(1))))), affects = arcanum.api.Affected.Objects(Objects.Self))
        }
        // fin chunk 13: "If a land or Bird you control entering the battlefield causes a triggered ability of a permanent you control to trigger, that
        // ability triggers an additional time." (CR 603.2d)
        Fin.ENTERING_CAUSES_TRIGGER_ADDITIONAL.matchEntire(line)?.let { m ->
            val entering = Filters.noun(m.groupValues[1]) ?: return null
            val sources = Filters.noun(m.groupValues[2]) ?: return null
            return Ability.Static(listOf(Mechanic.TriggersAdditionalTime(EventPattern.ZoneChange(entering, to = Zone.Battlefield), sources)),
                affects = arcanum.api.Affected.Objects(Objects.Self))
        }
        // fin-late-end
        return null
    }

    /** fin chunk 01: the clauses of "gets +1/+1, has "…," and is a Cleric in addition to its other types": split at top-level ", ", ", and "
     * and " and " before "is"/"has"/"gets", never inside quotes. */
    private fun finClauses(text: String): List<String>? {
        val parts = mutableListOf<String>()
        var quoted = false
        var start = 0
        var i = 0
        while (i < text.length) {
            val c = text[i]
            if (c == '"') quoted = !quoted
            if (!quoted) {
                val sep = Fin.CLAUSE_SEPARATOR.matchAt(text, i)
                if (sep != null) {
                    parts += text.substring(start, i).trim()
                    i += sep.value.length
                    start = i
                    continue
                }
            }
            i++
        }
        if (quoted) return null
        parts += text.substring(start).trim()
        return parts.filter { it.isNotEmpty() }
    }

    /** fin: sentences that change the steps before them, tried first by [modify]. */
    private fun finModify(sentence: String, steps: List<Step>, context: Context): List<Step>? {
        // fin chunk 01: "If that card is an enchantment card, it enters tapped and attacking." after putting a chosen card onto the battlefield
        // (CR 508.4: attacking, not declared as an attacker)
        Fin.IF_THAT_CARD_ENTERS_TAPPED_ATTACKING.matchEntire(sentence)?.let { m ->
            val last = steps.lastOrNull() as? Step.Do ?: return null
            val move = last.effect as? Effect.Move ?: return null
            if (move.to.zone != Zone.Battlefield || move.objects !is Objects.Bound) return null
            val filter = Filters.noun(m.groupValues[1]) ?: return null
            return steps.dropLast(1) + Step.If(arcanum.api.Condition.ObjectMatches(move.objects, filter),
                then = listOf(Step.Do(move.copy(to = move.to.copy(tapped = true, attacking = arcanum.api.AttackTarget.Chosen)))), otherwise = listOf(last))
        }
        // fin chunk 01: "That player loses life equal to the discarded card's mana value." after "discard a card" in a trigger on damage to a
        // player: the card discarded this way (CR 608.2h), the player dealt damage
        if (sentence == "That player loses life equal to the discarded card's mana value." && context.event is EventPattern.Damage) {
            val last = steps.lastOrNull() as? Step.Do ?: return null
            val discard = last.effect as? Effect.Discard ?: return null
            return steps.dropLast(1) + Step.Do(discard.copy(postBind = "discarded")) + Step.Do(Effect.LoseLife(Players.EventPlayer,
                Value.Of(arcanum.api.NumericProperty.ManaValue, Objects.Bound("discarded"), arcanum.api.Combine.Single)))
        }
        // fin chunk 02: "Put a stun counter on one of them." after an effect on a target slot of several: one of those targets, chosen now
        Fin.COUNTER_ON_ONE_OF_THEM.matchEntire(sentence)?.let { m ->
            val kind = Counters.kind(m.groupValues[1]) ?: return null
            val slot = context.targets.lastOrNull() ?: return null
            if ((slot.max as? Value.Fixed)?.value == 1) return null
            return steps + Step.Choose(arcanum.api.Choice.Objects(ObjectFilter.Any, Value.Fixed(1), Value.Fixed(1), from = Objects.Target(slot.name)),
                bind = "chosen", chooser = Players.You) + Step.Do(Effect.PutCounters(Objects.Bound("chosen"), kind, Value.Fixed(1)))
        }
        // fin chunk 03: "You may choose new targets for the copies." after "Copy it twice."
        if (sentence == "You may choose new targets for the copies.") {
            val repeat = steps.lastOrNull() as? Step.Repeat ?: return null
            val copy = (repeat.steps.singleOrNull() as? Step.Do)?.effect as? Effect.CopySpell ?: return null
            return steps.dropLast(1) + repeat.copy(steps = listOf(Step.Do(copy.copy(newTargets = true))))
        }
        // fin chunk 03: "Put an indestructible counter on each of them." after an effect on a group: the same objects
        Fin.COUNTER_ON_EACH_OF_THEM.matchEntire(sentence)?.let { m ->
            val kind = Counters.kind(m.groupValues[1]) ?: return null
            val last = (steps.lastOrNull() as? Step.Do)?.effect as? Effect.ApplyMechanics ?: return null
            val objects = (last.affects as? arcanum.api.Affected.Objects)?.objects as? Objects.Each ?: return null
            return steps + Step.Do(Effect.PutCounters(objects, kind, Value.Fixed(1)))
        }
        // fin chunk 03: "During any turn you put a lore counter on this Saga, you may play that card." after exiling a card
        if (sentence == "During any turn you put a lore counter on this Saga, you may play that card.") {
            val move = (steps.lastOrNull() as? Step.Do)?.effect as? Effect.Move ?: return null
            val bind = move.postBind ?: "exiled"
            val loreThisTurn = arcanum.api.Condition.HappenedThisTurn(EventPattern.CountersPut(ObjectFilter.Is(Objects.Self), arcanum.api.CounterKind.Lore),
                atLeast = 1, measure = arcanum.api.Measure.Events)
            return steps.dropLast(1) + Step.Do(move.copy(postBind = bind)) + Step.Do(Effect.ApplyMechanics(listOf(Mechanic.MayPlay(Zone.Exile,
                PlayKind.Play, holder = PlayerFilter.You, condition = loreThisTurn)), arcanum.api.Affected.Objects(Objects.Bound(bind)), arcanum.api.Duration.Indefinitely))
        }
        // fin chunk 04: "Put up to one enchantment card milled this way into your hand." needs the milled cards named
        if (Fin.PUT_UP_TO_ONE_MILLED.matches(sentence)) {
            val mill = (steps.lastOrNull() as? Step.Do)?.effect as? Effect.Mill ?: return null
            val chosen = effect(sentence, context) ?: return null
            return steps.dropLast(1) + Step.Do(mill.copy(postBind = "milled")) + chosen
        }
        // fin chunk 04: "Those creatures gain flying until end of turn." after putting counters on each of a group: the same group
        Fin.THOSE_CREATURES_GAIN.matchEntire(sentence)?.let { m ->
            val lastEffect = (steps.lastOrNull() as? Step.Do)?.effect
            // fdn chunk 09: also after "Draw a card for each creature you control with …": the creatures counted
            val group = (lastEffect as? Effect.PutCounters)?.objects
                ?: ((lastEffect as? Effect.Draw)?.count as? Value.Count)?.objects ?: return null
            if (group !is Objects.Each) return null
            val granted = keywords(m.groupValues[1]) ?: return null
            return steps + Step.Do(Effect.ApplyMechanics(listOf(Mechanic.GainAbilities(granted)), arcanum.api.Affected.Objects(group),
                arcanum.api.Duration.EndOfTurn))
        }
        // fin chunk 05: "If you put a card into your hand this way, [effect]." after "you may reveal it and put it into your hand": the optional
        // action becomes a payment named "put" (CR 118.12)
        Fin.IF_YOU_PUT_A_CARD_INTO_HAND.matchEntire(sentence)?.let { m ->
            val last = steps.lastOrNull() as? Step.If ?: return null
            val may = last.then.singleOrNull() as? Step.May ?: return null
            val then = instructions(m.groupValues[1].replaceFirstChar { it.uppercase() } + ".")?.takeIf { it.targets.isEmpty() } ?: return null
            return steps.dropLast(1) + last.copy(then = listOf(Step.Pay(steps = may.steps, payer = may.player, bind = "put"))) +
                Step.If(arcanum.api.Condition.Did("put"), then = then.steps)
        }
        // fin chunk 07: "If this spell was cast from a graveyard, put that card onto the battlefield instead." after putting a found card into the
        // hand (CR 608.2c)
        if (sentence == "If this spell was cast from a graveyard, put that card onto the battlefield instead.") {
            val last = steps.lastOrNull() as? Step.Do ?: return null
            val move = last.effect as? Effect.Move ?: return null
            if (move.to.zone != Zone.Hand) return null
            return steps.dropLast(1) + Step.If(arcanum.api.Condition.CastFrom(Zone.Graveyard, Objects.Self),
                then = listOf(Step.Do(move.copy(to = Destination(Zone.Battlefield)))), otherwise = listOf(last))
        }
        // fin chunk 09: "Then if this spell was cast from a graveyard, put two +1/+1 counters on that token." after creating a token
        Fin.IF_CAST_FROM_GRAVEYARD_COUNTERS_ON_TOKEN.matchEntire(sentence)?.let { m ->
            val last = steps.lastOrNull() as? Step.Do ?: return null
            val create = last.effect as? Effect.CreateToken ?: return null
            val n = Numbers.count(m.groupValues[1]) ?: return null
            val kind = Counters.kind(m.groupValues[2]) ?: return null
            val bind = create.bind ?: "tokens"
            return steps.dropLast(1) + Step.Do(create.copy(bind = bind)) + Step.If(arcanum.api.Condition.CastFrom(Zone.Graveyard, Objects.Self),
                then = listOf(Step.Do(Effect.PutCounters(Objects.Bound(bind), kind, Value.Fixed(n)))))
        }
        // fin chunk 16: "Choose target creature you control. It deals damage equal to its power to each other creature." ("it" is the chosen target)
        if (sentence == "It deals damage equal to its power to each other creature." && steps.isEmpty() && context.targets.size == 1 && isSpell) {
            val target = Objects.Target(context.targets.single().name)
            return listOf(Step.Do(Effect.DealDamage(Recipients(objects = Objects.Each(Filters.all(ObjectFilter.Not(ObjectFilter.Is(target)),
                ObjectFilter.Type(arcanum.api.CardType.Creature)))), Value.Of(arcanum.api.NumericProperty.Power, target, arcanum.api.Combine.Single), target)))
        }
        // fin chunk 17: "Create a 1/1 colorless Hero creature token. Put a +1/+1 counter on it for each land you control." ("it" is the token)
        Fin.COUNTER_ON_IT_FOR_EACH.matchEntire(sentence)?.let { m ->
            val last = steps.lastOrNull() as? Step.Do ?: return null
            val create = last.effect as? Effect.CreateToken ?: return null
            val kind = Counters.kind(m.groupValues[1]) ?: return null
            val per = Value.Count(Objects.Each(Filters.noun(m.groupValues[2]) ?: return null))
            val bind = create.bind ?: "tokens"
            return steps.dropLast(1) + Step.Do(create.copy(bind = bind)) + Step.Do(Effect.PutCounters(Objects.Bound(bind), kind, per))
        }
        // fin-modify-end
        return null
    }

    /** fin: effect sentences, tried first by [effectRules]; each reads one wording and falls through when it can't. */
    private fun finEffect(sentence: String, context: Context): List<Step>? {
        // fin chunk 02: "Target creature's owner shuffles it into their library." (CR 701.24)
        Fin.TARGETS_OWNER_SHUFFLES.matchEntire(sentence)?.let { m ->
            val noun = m.groupValues[1]
            val target = context.target(Filters.slotName(noun), Filters.noun(noun) ?: return null)
            return listOf(Step.Do(Effect.Move(target, Destination(Zone.Library))), Step.Do(Effect.Shuffle(Players.OwnerOf(target))))
        }
        // fin chunk 02: "Remove a lore counter from target Saga you control." (CR 122.8)
        Fin.REMOVE_COUNTER_FROM_TARGET.matchEntire(sentence)?.let { m ->
            val n = Numbers.count(m.groupValues[1]) ?: return null
            val kind = Counters.kind(m.groupValues[2]) ?: return null
            val noun = m.groupValues[3]
            val target = context.target(Filters.slotName(noun), Filters.noun(noun) ?: return null)
            return listOf(Step.Do(Effect.RemoveCounters(target, kind, Value.Fixed(n))))
        }
        // fin chunk 02: "Triple target creature's power and toughness until end of turn." (+X/+Y, X and Y twice the values, CR 701.11b)
        Fin.TRIPLE_TARGET_PT.matchEntire(sentence)?.let { m ->
            val target = context.target(Filters.slotName(m.groupValues[1]), Filters.noun(m.groupValues[1]) ?: return null)
            val power = Value.Of(arcanum.api.NumericProperty.Power, target, arcanum.api.Combine.Single)
            val toughness = Value.Of(arcanum.api.NumericProperty.Toughness, target, arcanum.api.Combine.Single)
            return listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.ModifyPowerToughness(Value.Times(power, 2), Value.Times(toughness, 2))),
                arcanum.api.Affected.Objects(target), arcanum.api.Duration.EndOfTurn)))
        }
        // fin chunk 02: "Exile up to two target cards from a single graveyard." (one owner, CR 115.1)
        Fin.UP_TO_FROM_SINGLE_GRAVEYARD.matchEntire(sentence)?.let { m ->
            val max = Numbers.count(m.groupValues[2]) ?: return null
            val noun = m.groupValues[3]
            val filter = if (noun == "cards") ObjectFilter.InZone(Zone.Graveyard) else Filters.all(Filters.noun(noun) ?: return null, ObjectFilter.InZone(Zone.Graveyard))
            val name = Filters.slotName(noun)
            context.targets += TargetSlot(name, TargetKind.Objects(filter), min = Value.Fixed(0), max = Value.Fixed(max), sameOwner = true)
            val zone = if (m.groupValues[1] == "Exile") Zone.Exile else return null
            return listOf(Step.Do(Effect.Move(Objects.Target(name), Destination(zone))))
        }
        // fin chunk 02: 'Until end of turn, target creature you control gains "[ability]" and has base power and toughness 3/2.' (layers 6, 7b)
        Fin.GAINS_QUOTE_AND_BASE_PT.matchEntire(sentence)?.let { m ->
            val noun = m.groupValues[1]
            val target = context.target(Filters.slotName(noun), Filters.noun(noun) ?: return null)
            val granted = Sentences(setOf("this creature", "This creature")).line(m.groupValues[2].trimEnd('.') + ".") ?: return null
            if (granted is Ability.Unparsed) return null
            return listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.GainAbilities(listOf(granted)),
                Mechanic.SetPowerToughness(Value.Fixed(m.groupValues[3].toInt()), Value.Fixed(m.groupValues[4].toInt()))),
                arcanum.api.Affected.Objects(target), arcanum.api.Duration.EndOfTurn)))
        }
        // fin chunk 03: "Copy it twice." (CR 707.10), then "You may choose new targets for the copies." (a modifier, [finModify])
        Fin.COPY_IT_TIMES.matchEntire(sentence)?.let { m ->
            val times = when (m.groupValues[1]) { "twice" -> 2; "three times" -> 3; else -> return null }
            val it = context.it ?: return null
            return listOf(Step.Repeat(Value.Fixed(times), listOf(Step.Do(Effect.CopySpell(it, Players.You, newTargets = false)))))
        }
        // fin chunk 03: "Each opponent sacrifices a creature of their choice and loses 3 life." (two effects of one subject)
        Fin.SACRIFICES_AND_LOSES.matchEntire(sentence)?.let { m ->
            val sacrifice = effect("${m.groupValues[1]} sacrifices ${m.groupValues[2]}.", context) ?: return null
            val lose = effect("${m.groupValues[1]} loses ${m.groupValues[3]} life.", context) ?: return null
            return sacrifice + lose
        }
        // fin chunk 03: 'This creature gains "[ability]"' with no duration: for as long as it's on the battlefield (CR 611.2a)
        Fin.SELF_GAINS_QUOTE.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val granted = Sentences(setOf("this creature", "This creature")).line(m.groupValues[2].trimEnd('.') + ".") ?: return null
            if (granted is Ability.Unparsed) return null
            return listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.GainAbilities(listOf(granted))), arcanum.api.Affected.Objects(Objects.Self),
                arcanum.api.Duration.Indefinitely)))
        }
        // fin chunk 03: "Until end of turn, whenever a Kraken … attacks, draw a card." (a delayed trigger that triggers each time, CR 603.7c)
        Fin.UNTIL_EOT_WHENEVER.matchEntire(sentence)?.let { m ->
            val ability = triggered("Whenever ${m.groupValues[1]}") as? Ability.Triggered ?: return null
            return listOf(Step.Do(Effect.CreateDelayedTrigger(ability.trigger, ability.instructions, arcanum.api.Duration.EndOfTurn, repeats = true)))
        }
        // fin chunk 03: "Draw a card if you control the creature with the greatest power or tied for the greatest power."
        if (sentence == "Draw a card if you control the creature with the greatest power or tied for the greatest power.") {
            val greatest = { filter: ObjectFilter -> Value.Of(arcanum.api.NumericProperty.Power, Objects.Each(filter), arcanum.api.Combine.Greatest) }
            val creature = ObjectFilter.Type(arcanum.api.CardType.Creature)
            return listOf(Step.If(arcanum.api.Condition.Compare(greatest(Filters.all(creature, ObjectFilter.ControlledBy(PlayerFilter.You))),
                arcanum.api.Comparison.AtLeast, greatest(creature)), then = listOf(Step.Do(Effect.Draw(Players.You, Value.Fixed(1))))))
        }
        // fin chunk 03: "That creature enters with an additional +1/+1 counter on it [for each Dog and/or Wolf you control]." about a creature spell
        // just cast: the spell gets a replacement of how it enters (CR 614.1c)
        Fin.THAT_CREATURE_ENTERS_WITH_ADDITIONAL.matchEntire(sentence)?.takeIf { context.event is EventPattern.Cast }?.let { m ->
            val kind = Counters.kind(m.groupValues[1]) ?: return null
            val amount = if (m.groupValues[2].isEmpty()) Value.Fixed(1) else Value.Count(Objects.Each(Filters.noun(m.groupValues[2]) ?: return null))
            return listOf(Step.Do(Effect.SpellGets(Objects.EventObject(EventRole.Object), listOf(Mechanic.Replacement(
                EventPattern.ZoneChange(ObjectFilter.Is(Objects.Affected), to = Zone.Battlefield), modify = listOf(Modification.EntersWithCounters(kind, amount)))))))
        }
        // fin chunk 03: "This creature deals damage equal to the total mana value of other permanents you control to each opponent."
        Fin.DEALS_DAMAGE_EQUAL_TOTAL.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val amount = FinPhrases.value(m.groupValues[2]) ?: return null
            return effect("${m.groupValues[1]} deals X damage to ${m.groupValues[3]}.", context)?.map { step ->
                val deal = (step as? Step.Do)?.effect as? Effect.DealDamage ?: return null
                Step.Do(deal.copy(amount = amount))
            }
        }
        // fin chunk 03: "It gains haste until end of turn." about a spell just cast (in a delayed trigger too): the spell and the permanent it
        // becomes, as the cast triggers read it
        if (sentence == "It gains haste until end of turn." && context.event is EventPattern.Cast) {
            return listOf(Step.Do(Effect.SpellGets(Objects.EventObject(EventRole.Object), listOf(Mechanic.GainAbilities(listOf(arcanum.api.Keyword.Haste))),
                arcanum.api.Duration.EndOfTurn)))
        }
        // fin chunk 04: "Tap all creatures your opponents control." (CR 701.26a)
        Fin.TAP_ALL.matchEntire(sentence)?.let { m -> return listOf(Step.Do(Effect.Tap(Objects.Each(Filters.noun(m.groupValues[1]) ?: return null)))) }
        // fin chunk 04: "Exile it, then return it to the battlefield transformed under its owner's control [with a finality counter on it]." about
        // this object (CR 701.27); "put it onto the battlefield" the same; a spell exiling itself as it resolves too (CR 608.2n)
        Fin.EXILE_SELF_THEN_RETURN.matchEntire(sentence)?.let { m ->
            val who = m.groupValues[1]
            if (!(isSelf(who) || (who == "it" && (context.it == Objects.Self || context.it == null)))) return null
            val counters = m.groupValues[4].takeIf { it.isNotEmpty() }?.let { listOf(arcanum.api.CountersToPut(Counters.kind(it) ?: return null, Value.Fixed(1))) }.orEmpty()
            val exiled = Objects.Bound("exiled")
            return listOf(Step.Do(Effect.Move(Objects.Self, Destination(Zone.Exile), postBind = "exiled")),
                Step.Do(Effect.Move(exiled, Destination(Zone.Battlefield, transformed = m.groupValues[2].isNotEmpty(),
                    controller = if (m.groupValues[3].isNotEmpty()) Players.OwnerOf(exiled) else null, counters = counters))))
        }
        // fin chunk 04: "Return this card from your graveyard to the battlefield transformed." (CR 113.6m, 712.14)
        Fin.RETURN_SELF_TRANSFORMED.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            return listOf(Step.Do(Effect.Move(Objects.Self, Destination(Zone.Battlefield, transformed = true))))
        }
        // fin chunk 04: "Return any number of target creature cards with total mana value 6 or less from your graveyard to the battlefield."
        Fin.RETURN_ANY_NUMBER_TOTAL.matchEntire(sentence)?.let { m ->
            val noun = m.groupValues[1]
            val filter = Filters.all(Filters.noun(noun) ?: return null, ObjectFilter.InZone(Zone.Graveyard), ObjectFilter.OwnedBy(PlayerFilter.You))
            val name = Filters.slotName(noun)
            context.targets += TargetSlot(name, TargetKind.Objects(filter), min = Value.Fixed(0), max = null,
                totalAtMost = arcanum.api.Choice.TotalLimit(arcanum.api.NumericProperty.ManaValue, Value.Fixed(m.groupValues[2].toInt())))
            return listOf(Step.Do(Effect.Move(Objects.Target(name), Destination(Zone.Battlefield))))
        }
        // fin chunk 04: "Put up to one enchantment card milled this way into your hand." after milling (CR 701.17)
        Fin.PUT_UP_TO_ONE_MILLED.matchEntire(sentence)?.let { m ->
            val filter = Filters.noun(m.groupValues[1]) ?: return null
            return listOf(Step.Choose(arcanum.api.Choice.Objects(Filters.all(filter, ObjectFilter.InZone(Zone.Graveyard)), Value.Fixed(0), Value.Fixed(1),
                from = Objects.Bound("milled")), bind = "chosen", chooser = Players.You), Step.Do(Effect.Move(Objects.Bound("chosen"), Destination(Zone.Hand))))
        }
        // fin chunk 04: "Put it on the bottom of its owner's library." (in a dies trigger: the card in the graveyard, CR 400.7)
        Fin.PUT_IT_ON_LIBRARY.matchEntire(sentence)?.let { m ->
            val it = context.it ?: return null
            return listOf(Step.Do(Effect.Move(it, Destination(Zone.Library, libraryPosition = if (m.groupValues[1] == "top") 0 else -1))))
        }
        // fin chunk 04: "Until your next turn, it gains indestructible." after an effect on a target: that target (CR 611.2a)
        Fin.UNTIL_NEXT_TURN_IT_GAINS.matchEntire(sentence)?.let { m ->
            val slot = context.targets.lastOrNull() ?: return null
            val granted = keywords(m.groupValues[1]) ?: return null
            return listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.GainAbilities(granted)), arcanum.api.Affected.Objects(Objects.Target(slot.name)),
                arcanum.api.Duration.UntilYourNextTurn)))
        }
        // fin chunk 04: "If that creature is legendary, draw a card." about the target (CR 608.2h: as it is now)
        Fin.IF_THAT_CREATURE_IS.matchEntire(sentence)?.let { m ->
            val slot = context.targets.lastOrNull() ?: return null
            val filter = when (m.groupValues[1]) { "legendary" -> ObjectFilter.Super(Supertype.Legendary); else -> return null }
            val then = effect(m.groupValues[2].replaceFirstChar { it.uppercase() } + ".", context) ?: return null
            return listOf(Step.If(arcanum.api.Condition.ObjectMatches(Objects.Target(slot.name), filter), then = then))
        }
        // fin chunk 04: "Add {W}{W}, {U}{U}, {B}{B}, {R}{R}, and {G}{G}." (all of it, CR 106.3)
        Fin.ADD_MANA_LIST.matchEntire(sentence)?.let { m ->
            val all = LazyRegexes.MANA_SYMBOL.findAll(m.groupValues[1]).joinToString("") { it.value }
            return listOf(Step.Do(Effect.AddMana(ManaProduction(ManaKind.Fixed(ManaCost.parse(all) ?: return null)), Players.You)))
        }
        // fin chunk 05: "Put a number of +1/+1 counters on Vincent equal to that creature's power." (in a dies trigger: as it last existed)
        Fin.COUNTERS_EQUAL_TO_THAT_CREATURES_POWER.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[2]) }?.let { m ->
            val kind = Counters.kind(m.groupValues[1]) ?: return null
            val dying = (context.event as? EventPattern.ZoneChange)?.takeIf { it.from == Zone.Battlefield } ?: return null
            if (dying.objects is ObjectFilter.Is) return null
            return listOf(Step.Do(Effect.PutCounters(Objects.Self, kind, Value.Of(arcanum.api.NumericProperty.Power, Objects.EventObject(EventRole.Before),
                arcanum.api.Combine.Single))))
        }
        // fin chunk 05: "You lose that much life." after damage this object dealt (CR 120.3)
        if (sentence == "You lose that much life." && context.event is EventPattern.Damage) return listOf(Step.Do(Effect.LoseLife(Players.You, Value.EventAmount)))
        // fin chunk 05: "You may sacrifice any number of other creatures. If you do, draw that many cards."
        Fin.MAY_SACRIFICE_ANY_NUMBER_DRAW.matchEntire(sentence)?.let { m ->
            val filter = Filters.noun(m.groupValues[1]) ?: return null
            return listOf(Step.Pay(Cost(listOf(CostPart.Sacrifice(CostObjects.Choose(filter, null), postBind = "sacrificed"))),
                payer = Players.You, bind = "paid"),
                Step.If(arcanum.api.Condition.Did("paid"), then = listOf(Step.Do(Effect.Draw(Players.You, Value.Count(Objects.Bound("sacrificed")))))))
        }
        // fin chunk 05: "If it has three or more +1/+1 counters on it, transform it." in a cast trigger: "it" is this permanent, not the spell
        Fin.IF_IT_HAS_COUNTERS_TRANSFORM_IT.matchEntire(sentence)?.let { m ->
            val n = Numbers.count(m.groupValues[1]) ?: return null
            return listOf(Step.If(arcanum.api.Condition.ObjectMatches(Objects.Self, ObjectFilter.HasCounter(Counters.kind(m.groupValues[2]) ?: return null, atLeast = n)),
                then = listOf(Step.Do(Effect.Transform(Objects.Self)))))
        }
        // fin chunk 05: "Return it to the battlefield tapped." in this object's dies trigger: the card in the graveyard (CR 400.7)
        Fin.RETURN_IT_TO_BATTLEFIELD.matchEntire(sentence)?.let { m ->
            val dies = context.event as? EventPattern.ZoneChange ?: return null
            if (dies.objects != ObjectFilter.Is(Objects.Self) || dies.to != Zone.Graveyard) return null
            // mkm chunk 03: after an earlier step moved it ("you may exile it … If you do, return this card …"), the card where it went (CR 400.7)
            val card = context.it as? Objects.Bound ?: Objects.EventObject(EventRole.After)
            return listOf(Step.Do(Effect.Move(card, Destination(Zone.Battlefield, tapped = m.groupValues[1].isNotEmpty()))))
        }
        // fin chunk 05: "Transform this enchantment, then attach it to a creature you control." (a creature chosen as it happens, CR 701.3)
        Fin.TRANSFORM_THEN_ATTACH.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val filter = Filters.noun(m.groupValues[2]) ?: return null
            return listOf(Step.Do(Effect.Transform(Objects.Self)),
                Step.Choose(arcanum.api.Choice.Objects(filter, Value.Fixed(1), Value.Fixed(1)), bind = "chosen", chooser = Players.You),
                Step.Do(Effect.Attach(Objects.Self, Recipients(objects = Objects.Bound("chosen")))))
        }
        // fin chunk 05: "You draw that many cards." after life lost or damage dealt (the event's amount)
        if (sentence == "You draw that many cards." && (context.event is EventPattern.LoseLife || context.event is EventPattern.Damage))
            return listOf(Step.Do(Effect.Draw(Players.You, Value.EventAmount)))
        // fin chunk 05: "Until end of turn, creatures other than Zerand and the chosen creature get -2/-2."
        Fin.CREATURES_OTHER_THAN_SELF_AND_CHOSEN_GET.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val p = m.groupValues[2].toInt()
            val t = m.groupValues[3].toInt()
            val creature = ObjectFilter.Type(arcanum.api.CardType.Creature)
            val others = Objects.Each(Filters.all(creature, ObjectFilter.Not(ObjectFilter.Is(Objects.Self)), ObjectFilter.Not(ObjectFilter.Is(Objects.Remembered("chosen")))))
            return listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.ModifyPowerToughness(Value.Fixed(p), Value.Fixed(t))), arcanum.api.Affected.Objects(others),
                arcanum.api.Duration.EndOfTurn)))
        }
        // fin chunk 05: "Choose a creature an opponent controls." kept by the card as "the chosen creature" (linked abilities, CR 607.2a)
        if (sentence == "Choose a creature an opponent controls." && finChosenCreatureLinked) {
            return listOf(Step.Choose(arcanum.api.Choice.Objects(Filters.noun("creature an opponent controls") ?: return null, Value.Fixed(1), Value.Fixed(1)),
                bind = "chosen", chooser = Players.You, remember = true))
        }
        // fin chunk 06: "Put a +1/+1 counter on this creature and it can't be blocked this turn." ("it" is this creature, not the spell cast)
        Fin.COUNTER_ON_SELF_AND_IT.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[2]) && it.groupValues[3] == "can't be blocked this turn" }?.let { m ->
            val kind = Counters.kind(m.groupValues[1]) ?: return null
            return listOf(Step.Do(Effect.PutCounters(Objects.Self, kind, Value.Fixed(1))),
                Step.Do(Effect.ApplyMechanics(listOf(Mechanic.CantBeBlocked), arcanum.api.Affected.Objects(Objects.Self), arcanum.api.Duration.EndOfTurn)))
        }
        // fin chunk 06: "Sacrifice Tellah and it deals that much damage to each opponent." in a cast trigger: the mana spent to cast that spell
        Fin.SACRIFICE_SELF_AND_DEALS_THAT_MUCH.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[1]) && context.event is EventPattern.Cast }?.let {
            return listOf(Step.Do(Effect.Sacrifice(Objects.Self)), Step.Do(Effect.DealDamage(Recipients(players = Players.Each(PlayerFilter.Opponent)),
                Value.ManaSpent(of = Objects.EventObject(EventRole.Object)), Objects.Self)))
        }
        // fin chunk 06: "Add X mana in any combination of {U} and/or {R}." (CR 106.1b)
        Fin.ADD_X_ANY_COMBINATION.matchEntire(sentence)?.let { m ->
            val colors = listOf(m.groupValues[2], m.groupValues[3]).map { arcanum.api.ColorRef.Literal(Color.of(it[0]) ?: return null) }
            val amount = if (m.groupValues[1] == "X") Value.Announced("X") else Value.Fixed(Numbers.count(m.groupValues[1]) ?: return null)
            return listOf(Step.Do(Effect.AddMana(ManaProduction(ManaKind.Choose(amount, colors = colors, combination = true)), Players.You)))
        }
        // fin chunk 07: "End the turn." (CR 724.1)
        if (sentence == "End the turn.") return listOf(Step.Do(Effect.EndTurn))
        // fin chunk 07: "You may return another permanent you control to its owner's hand." (chosen as it resolves, not targeted)
        Fin.MAY_RETURN_TO_HAND.matchEntire(sentence)?.let { m ->
            val filter = Filters.noun(m.groupValues[1]) ?: return null
            return listOf(Step.Choose(arcanum.api.Choice.Objects(filter, Value.Fixed(0), Value.Fixed(1)), bind = "chosen", chooser = Players.You),
                Step.Do(Effect.Move(Objects.Bound("chosen"), Destination(Zone.Hand))))
        }
        // fin chunk 07: "You may attach any number of Equipment you control to target creature you control." (CR 701.3)
        Fin.MAY_ATTACH_ANY_NUMBER.matchEntire(sentence)?.let { m ->
            val filter = Filters.noun(m.groupValues[1]) ?: return null
            val target = context.target(Filters.slotName(m.groupValues[2]), Filters.noun(m.groupValues[2]) ?: return null)
            return listOf(Step.Choose(arcanum.api.Choice.Objects(filter, Value.Fixed(0), null), bind = "equipment", chooser = Players.You),
                Step.Do(Effect.Attach(Objects.Bound("equipment"), Recipients(objects = target))))
        }
        // fin chunk 08: "Each opponent mills X cards." (CR 701.17)
        Fin.EACH_OPPONENT_MILLS.matchEntire(sentence)?.let { m ->
            val amount = if (m.groupValues[1] == "X") Value.Announced("X") else Value.Fixed(Numbers.count(m.groupValues[1]) ?: return null)
            return listOf(Step.Do(Effect.Mill(Players.Each(PlayerFilter.Opponent), amount)))
        }
        // fin chunk 09: "If it's the first end step of the turn, there is an additional end step after this step." (CR 500.9)
        if (sentence == "If it's the first end step of the turn, there is an additional end step after this step.") {
            return listOf(Step.If(arcanum.api.Condition.Not(arcanum.api.Condition.HappenedThisTurn(EventPattern.StepBegins(arcanum.api.TurnStep.End, PlayerFilter.Any),
                atLeast = 2, measure = arcanum.api.Measure.Events)), then = listOf(Step.Do(Effect.AdditionalStep(arcanum.api.TurnStep.End)))))
        }
        // fin chunk 09: "Each opponent mills cards equal to the number of cards in your hand."
        if (sentence == "Each opponent mills cards equal to the number of cards in your hand.")
            return listOf(Step.Do(Effect.Mill(Players.Each(PlayerFilter.Opponent), Value.HandSize(Players.You))))
        // fin chunk 11: "Return target creature card from your graveyard to the battlefield with two additional +1/+1 counters on it." (CR 122.6)
        Fin.RETURN_TARGET_WITH_ADDITIONAL_COUNTERS.matchEntire(sentence)?.let { m ->
            val target = context.target(Filters.slotName(m.groupValues[1]), Filters.all(Filters.noun(m.groupValues[1]) ?: return null, ObjectFilter.InZone(Zone.Graveyard),
                ObjectFilter.OwnedBy(PlayerFilter.You)))
            val n = Numbers.count(m.groupValues[2]) ?: return null
            return listOf(Step.Do(Effect.Move(target, Destination(Zone.Battlefield, counters = listOf(arcanum.api.CountersToPut(Counters.kind(m.groupValues[3]) ?: return null,
                Value.Fixed(n)))))))
        }
        // fin chunk 11: "Each opponent discards a card, loses 2 life, and exiles the top three cards of their library."
        Fin.EACH_OPPONENT_DISCARDS_LOSES_EXILES.matchEntire(sentence)?.let { m ->
            val each = Players.Each(PlayerFilter.Opponent)
            return listOf(Step.Do(Effect.Discard(each, Value.Fixed(1), ObjectFilter.Any)), Step.Do(Effect.LoseLife(each, Value.Fixed(m.groupValues[1].toInt()))),
                Step.Do(Effect.Move(Objects.LibraryCards(each, Value.Fixed(Numbers.count(m.groupValues[2]) ?: return null), fromTop = true), Destination(Zone.Exile))))
        }
        // fin chunk 11: "Draw a card for each creature that died this turn."
        if (sentence == "Draw a card for each creature that died this turn.")
            return listOf(Step.Do(Effect.Draw(Players.You, Value.EventsThisTurn(EventPattern.ZoneChange(ObjectFilter.Type(arcanum.api.CardType.Creature),
                from = Zone.Battlefield, to = Zone.Graveyard), arcanum.api.Measure.Objects))))
        // fin chunk 11: "Each player sacrifices half the non-God creatures they control of their choice, rounded down." (CR 107.1a)
        Fin.EACH_PLAYER_SACRIFICES_HALF.matchEntire(sentence)?.let { m ->
            val kind = Filters.noun(m.groupValues[1]) ?: return null
            val theirs = Filters.all(kind, ObjectFilter.ControlledBy(PlayerFilter.Is(Players.Bound("player"))))
            val half = Value.Half(Value.Count(Objects.Each(theirs)), roundUp = m.groupValues[2] == "up")
            return listOf(Step.ForEach(arcanum.api.Each.Players(Players.Each(PlayerFilter.Any)), "player", steps = listOf(
                Step.Choose(arcanum.api.Choice.Objects(theirs, half, half), bind = "sacrificed", chooser = Players.Bound("player")),
                Step.Do(Effect.Sacrifice(Objects.Bound("sacrificed")))), together = true))
        }
        // fin chunk 12: "Add {R}. Spend this mana only to cast an Equipment spell or activate an equip ability." (CR 106.6)
        Fin.ADD_ONLY_EQUIPMENT.matchEntire(sentence)?.let { m ->
            val equipment = ObjectFilter.Sub(Subtype("Equipment"))
            return listOf(Step.Do(Effect.AddMana(ManaProduction(ManaKind.Fixed(ManaCost.parse(m.groupValues[1]) ?: return null), restriction = ObjectFilter.Or(listOf(
                Filters.all(equipment, ObjectFilter.Category(arcanum.api.ObjectCategory.Spell)),
                ObjectFilter.AbilityOf(keyword = arcanum.api.Keyword.Equip.Kind)))), Players.You)))
        }
        // fin chunk 12: "It deals damage equal to the number of equipped creatures you control to defending player." (an attack trigger)
        Fin.DEALS_DAMAGE_EQUAL_TO_DEFENDING.matchEntire(sentence)?.takeIf { it.groupValues[1] == "It" || isSelf(it.groupValues[1]) }?.let { m ->
            val amount = Values.value(m.groupValues[2]) ?: return null
            return listOf(Step.Do(Effect.DealDamage(Recipients(players = Players.DefendingPlayerOf(Objects.Self)), amount, Objects.Self)))
        }
        // fin chunk 12: "Target creature you control deals X damage to any other target and X damage to itself." (X defined by "where X is its power")
        if (sentence == "Target creature you control deals X damage to any other target and X damage to itself.") {
            val creature = context.target("creature", Filters.noun("creature you control") ?: return null)
            context.anyTarget()
            context.targets[context.targets.lastIndex] = context.targets.last().copy(distinctFrom = listOf("creature"))
            // "where X is its power": the target creature's
            val x = Value.Of(arcanum.api.NumericProperty.Power, creature, arcanum.api.Combine.Single)
            return listOf(Step.Do(Effect.DealDamage(Recipients(target = "any"), x, creature)), Step.Do(Effect.DealDamage(Recipients(objects = creature), x, creature)))
        }
        // fin chunk 12: "Return target instant or sorcery card from your graveyard or exiled card with flashback you own to your hand." (CR 702.34a)
        if (sentence == "Return target instant or sorcery card from your graveyard or exiled card with flashback you own to your hand.") {
            val spells = ObjectFilter.Or(listOf(ObjectFilter.Type(arcanum.api.CardType.Instant), ObjectFilter.Type(arcanum.api.CardType.Sorcery)))
            val target = context.target("card", ObjectFilter.Or(listOf(
                Filters.all(spells, ObjectFilter.InZone(Zone.Graveyard), ObjectFilter.OwnedBy(PlayerFilter.You)),
                Filters.all(ObjectFilter.InZone(Zone.Exile), ObjectFilter.HasKeyword(arcanum.api.Keyword.Flashback.Kind), ObjectFilter.OwnedBy(PlayerFilter.You)))))
            return listOf(Step.Do(Effect.Move(target, Destination(Zone.Hand))))
        }
        // fin chunk 12: "[This] deals 5 damage to target creature and X damage to that creature's controller." (X defined by "where X is")
        Fin.DAMAGE_TARGET_AND_X_TO_CONTROLLER.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val target = context.target("creature", ObjectFilter.Type(arcanum.api.CardType.Creature))
            // inr chunk 08: "and 1 damage to its controller"
            val second = if (m.groupValues[3] == "X") Value.Announced("X") else Value.Fixed(m.groupValues[3].toInt())
            return listOf(Step.Do(Effect.DealDamage(Recipients(objects = target), Value.Fixed(m.groupValues[2].toInt()), Objects.Self)),
                Step.Do(Effect.DealDamage(Recipients(players = Players.ControllerOf(target)), second, Objects.Self)))
        }
        // fin chunk 12: "Attach up to one target Equipment you control to target attacking creature." (CR 701.3)
        Fin.ATTACH_UP_TO_ONE_TARGET_TO_TARGET.matchEntire(sentence)?.let { m ->
            val equipmentName = Filters.slotName(m.groupValues[1])
            context.targets += TargetSlot(equipmentName, TargetKind.Objects(Filters.noun(m.groupValues[1]) ?: return null), min = Value.Fixed(0), max = Value.Fixed(1))
            val creature = context.target(Filters.slotName(m.groupValues[2]), Filters.noun(m.groupValues[2]) ?: return null)
            return listOf(Step.Do(Effect.Attach(Objects.Target(equipmentName), Recipients(objects = creature))))
        }
        // fin chunk 13: "When you search your library this way, put a +1/+1 counter on target creature you control." (CR 603.12)
        Fin.WHEN_YOU_SEARCH_THIS_WAY.matchEntire(sentence)?.let { m ->
            val read = instructions(m.groupValues[1].replaceFirstChar { it.uppercase() }) ?: return null
            return listOf(Step.Do(Effect.ReflexiveTrigger(read)))
        }
        // fin chunk 13: "Search your library for up to two basic land cards and/or Town cards with different names, put them onto the battlefield tapped,
        // then shuffle." (CR 701.23)
        Fin.SEARCH_UP_TO_DIFFERENT_NAMES.matchEntire(sentence)?.let { m ->
            val n = Numbers.count(m.groupValues[1]) ?: return null
            val filter = Filters.noun(m.groupValues[2]) ?: return null
            return listOf(Step.Do(Effect.Search(Players.You, filter, max = Value.Fixed(n), reveal = false, zones = listOf(Zone.Library), differentNames = true,
                bind = "found", searcher = Players.You)), Step.Do(Effect.Move(Objects.Bound("found"), Destination(Zone.Battlefield, tapped = true))),
                Step.Do(Effect.Shuffle(Players.You)))
        }
        // fin chunk 13: "This enchantment becomes a 7/7 Beast creature in addition to its other types." (for good, CR 611.2a)
        Fin.SELF_BECOMES_CREATURE.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val subtype = m.groupValues[4].takeIf { it in RulesWords.subtypes } ?: return null
            return listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.SetTypes(add = listOf(arcanum.api.CardType.Creature),
                addSubtypes = listOf(arcanum.api.SubtypeRef.Literal(Subtype(subtype)))), Mechanic.SetPowerToughness(Value.Fixed(m.groupValues[2].toInt()),
                Value.Fixed(m.groupValues[3].toInt()))), arcanum.api.Affected.Objects(Objects.Self), arcanum.api.Duration.Indefinitely)))
        }
        // fin chunk 13: 'Until end of turn, target creature gets +1/+0 and gains "When this creature dies, …"' (layers 6, 7c)
        Fin.UNTIL_EOT_GETS_AND_GAINS_QUOTE.matchEntire(sentence)?.let { m ->
            val target = context.target(Filters.slotName(m.groupValues[1]), Filters.noun(m.groupValues[1]) ?: return null)
            val granted = Sentences(setOf("this creature", "This creature")).line(m.groupValues[4].trimEnd('.') + ".") ?: return null
            if (granted is Ability.Unparsed) return null
            return listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.ModifyPowerToughness(Value.Fixed(m.groupValues[2].toInt()), Value.Fixed(m.groupValues[3].toInt())),
                Mechanic.GainAbilities(listOf(granted))), arcanum.api.Affected.Objects(target), arcanum.api.Duration.EndOfTurn)))
        }
        // fin chunk 13: "Put a number of +1/+1 counters equal to its power on up to one target creature." (in a dies trigger: its last power)
        Fin.COUNTERS_EQUAL_ITS_POWER_ON_UP_TO_ONE.matchEntire(sentence)?.let { m ->
            val dies = (context.event as? EventPattern.ZoneChange)?.takeIf { it.objects == ObjectFilter.Is(Objects.Self) && it.to == Zone.Graveyard } ?: return null
            val kind = Counters.kind(m.groupValues[1]) ?: return null
            val name = Filters.slotName(m.groupValues[2])
            context.targets += TargetSlot(name, TargetKind.Objects(Filters.noun(m.groupValues[2]) ?: return null), min = Value.Fixed(0), max = Value.Fixed(1))
            return listOf(Step.Do(Effect.PutCounters(Objects.Target(name), kind, Value.Of(arcanum.api.NumericProperty.Power, Objects.EventObject(EventRole.Before),
                arcanum.api.Combine.Single))))
        }
        // fin chunk 13: "Until end of turn, this creature gets +1/+1 for each permanent card in your graveyard."
        Fin.UNTIL_EOT_SELF_GETS_FOR_EACH.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val per = Value.Count(Objects.Each(Filters.noun(m.groupValues[2]) ?: return null))
            return listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.ModifyPowerToughness(per, per)), arcanum.api.Affected.Objects(Objects.Self), arcanum.api.Duration.EndOfTurn)))
        }
        // fin chunk 13: "Exile it and create ten tapped Treasure tokens." in this creature's dies trigger (the card in the graveyard, CR 400.7)
        Fin.EXILE_IT_AND.matchEntire(sentence)?.let { m ->
            val it = context.it ?: return null
            val rest = effect(m.groupValues[1].replaceFirstChar { c -> c.uppercase() } + ".", context) ?: return null
            return listOf(Step.Do(Effect.Move(it, Destination(Zone.Exile)))) + rest
        }
        // fin chunk 13: "Create ten tapped Treasure tokens." (CR 111.10a)
        Fin.CREATE_N_TAPPED_PREDEFINED.matchEntire(sentence)?.let { m ->
            val n = Numbers.count(m.groupValues[1]) ?: m.groupValues[1].toIntOrNull() ?: return null
            return listOf(Step.Do(Effect.CreateToken(arcanum.api.TokenSpec.Predefined(m.groupValues[2]), Value.Fixed(n), Players.You, tapped = true)))
        }
        // fin-effect-end
        return null
    }

    /** fin: texts of several sentences read as a whole, tried after every other set's. */
    private fun finWhole(text: String, context: Context): List<Step>? {
        finNextCast(text, context)?.let { return it }
        // fin chunk 04: "Create a token that's a copy of target nonlegendary enchantment you control. It gains haste. If it's a Saga, put up to three
        // lore counters on it. Sacrifice it at the beginning of your next end step." (CR 707.2, 714.3a)
        Fin.COPY_ENCHANTMENT_HASTE_LORE.matchEntire(text)?.let { m ->
            val target = context.target(Filters.slotName(m.groupValues[1]), Filters.noun(m.groupValues[1]) ?: return null)
            val tokens = Objects.Bound("tokens")
            return listOf(
                Step.Do(Effect.CreateToken(arcanum.api.TokenSpec.CopyOf(target), Value.Fixed(1), Players.You, bind = "tokens")),
                Step.Do(Effect.ApplyMechanics(listOf(Mechanic.GainAbilities(listOf(arcanum.api.Keyword.Haste))), arcanum.api.Affected.Objects(tokens),
                    arcanum.api.Duration.Indefinitely)),
                Step.If(arcanum.api.Condition.ObjectMatches(tokens, ObjectFilter.Sub(Subtype("Saga"))), then = listOf(
                    Step.Choose(arcanum.api.Choice.Number(Value.Fixed(0), Value.Fixed(3)), bind = "lore", chooser = Players.You),
                    Step.Do(Effect.PutCounters(tokens, arcanum.api.CounterKind.Lore, Value.Bound("lore"))))),
                Step.Do(Effect.CreateDelayedTrigger(arcanum.api.Trigger.On(EventPattern.StepBegins(arcanum.api.TurnStep.End, PlayerFilter.You)),
                    Instructions(steps = listOf(Step.Do(Effect.Sacrifice(tokens)))))),
            )
        }
        // fin chunk 05: "Each player discards a card. Then you draw a card for each card type among cards discarded this way." (CR 205.2a)
        if (text == "Each player discards a card. Then you draw a card for each card type among cards discarded this way.") {
            return listOf(Step.Do(Effect.Discard(Players.Each(PlayerFilter.Any), Value.Fixed(1), ObjectFilter.Any, postBind = "discarded")),
                Step.Do(Effect.Draw(Players.You, Value.CountDistinct(Objects.Bound("discarded"), arcanum.api.SharedQuality.CardType))))
        }
        // fin chunk 07: "Search your library and/or graveyard for an artifact card with mana value 2 or less, reveal it, and put it into your hand.
        // If you search your library this way, shuffle." (CR 701.23)
        Fin.SEARCH_LIBRARY_AND_OR_GRAVEYARD.matchEntire(text)?.let { m ->
            val filter = Filters.noun(m.groupValues[1]) ?: return null
            return listOf(Step.Do(Effect.Search(Players.You, filter, max = Value.Fixed(1), reveal = true, zones = listOf(Zone.Library, Zone.Graveyard), bind = "found",
                searcher = Players.You)), Step.Do(Effect.Move(Objects.Bound("found"), Destination(Zone.Hand))),
                Step.If(arcanum.api.Condition.Searched("found", Zone.Library), then = listOf(Step.Do(Effect.Shuffle(Players.You)))))
        }
        // fin chunk 07: "Target opponent gains control of another target permanent you control. If they do, you draw a card." (CR 613.1b)
        Fin.OPPONENT_GAINS_CONTROL_IF_THEY_DO.matchEntire(text)?.let { m ->
            context.targets += TargetSlot("opponent", TargetKind.Players(PlayerFilter.Opponent), min = Value.Fixed(1), max = Value.Fixed(1))
            val opponent = Players.Target("opponent")
            val permanent = context.target(Filters.slotName(m.groupValues[1]), Filters.noun("another " + m.groupValues[1]) ?: return null)
            val then = effect(m.groupValues[2].replaceFirstChar { it.uppercase() } + ".", context) ?: return null
            return listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.ControlledBy(opponent)), arcanum.api.Affected.Objects(permanent), arcanum.api.Duration.Indefinitely)),
                Step.If(arcanum.api.Condition.ObjectMatches(permanent, ObjectFilter.ControlledBy(PlayerFilter.Is(opponent))), then = then))
        }
        // fin chunk 07: "Target creature you control gains indestructible until end of turn. Put Zack's counters on that creature and attach an
        // Equipment that was attached to Zack to that creature." (the sacrificed creature as it last existed, CR 608.2h)
        Fin.GAINS_PUT_COUNTERS_ATTACH_EQUIPMENT.matchEntire(text)?.takeIf { isSelf(it.groupValues[3]) && isSelf(it.groupValues[4]) }?.let { m ->
            val target = context.target(Filters.slotName(m.groupValues[1]), Filters.noun(m.groupValues[1]) ?: return null)
            val granted = keywords(m.groupValues[2]) ?: return null
            val equipment = ObjectFilter.Sub(Subtype("Equipment"))
            return listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.GainAbilities(granted)), arcanum.api.Affected.Objects(target), arcanum.api.Duration.EndOfTurn)),
                Step.Do(Effect.PutCountersOf(target, Objects.Self)),
                Step.Choose(arcanum.api.Choice.Objects(equipment, Value.Fixed(1), Value.Fixed(1), from = Objects.AttachmentsOf(Objects.Self, equipment)), bind = "equipment",
                    chooser = Players.You),
                Step.Do(Effect.Attach(Objects.Bound("equipment"), Recipients(objects = target))))
        }
        // fin chunk 09: five revealed cards handed out in turns between you and a chosen opponent
        if (text == "Reveal the top five cards of your library. Put one of them into your hand. Then choose an opponent. They put one on the bottom of your library. Then you put one into your hand. Then they put one on the bottom of your library. Put the other into your hand.") {
            fun rest(vararg taken: String): Objects = if (taken.isEmpty()) Objects.Bound("revealed")
                else Objects.Except(Objects.Bound("revealed"), Objects.Union(taken.map { Objects.Bound(it) }))
            fun pick(into: String, chooser: Players, vararg taken: String) = Step.Choose(arcanum.api.Choice.Objects(ObjectFilter.Any, Value.Fixed(1), Value.Fixed(1),
                from = rest(*taken)), bind = into, chooser = chooser)
            fun to(objects: Objects, zone: Zone, position: Int? = null) = Step.Do(Effect.Move(objects, Destination(zone, libraryPosition = position)))
            val opponent = Players.Bound("opponent")
            return listOf(Step.Do(Effect.Reveal(Objects.LibraryCards(Players.You, Value.Fixed(5), fromTop = true), bind = "revealed")),
                pick("first", Players.You), to(Objects.Bound("first"), Zone.Hand),
                Step.Choose(arcanum.api.Choice.Player(PlayerFilter.Opponent), bind = "opponent", chooser = Players.You),
                pick("second", opponent, "first"), to(Objects.Bound("second"), Zone.Library, -1),
                pick("third", Players.You, "first", "second"), to(Objects.Bound("third"), Zone.Hand),
                pick("fourth", opponent, "first", "second", "third"), to(Objects.Bound("fourth"), Zone.Library, -1),
                to(rest("first", "second", "third", "fourth"), Zone.Hand))
        }
        // fin chunk 09: "Choose target spell. Surveil 2, then counter the chosen spell unless its controller pays {1} for each card in your graveyard."
        Fin.CHOOSE_SPELL_SURVEIL_COUNTER_UNLESS.matchEntire(text)?.let { m ->
            val spell = context.target("spell", ObjectFilter.Category(arcanum.api.ObjectCategory.Spell))
            val n = Numbers.count(m.groupValues[1]) ?: return null
            val graveyard = Value.Count(Objects.Each(Filters.all(ObjectFilter.InZone(Zone.Graveyard), ObjectFilter.OwnedBy(PlayerFilter.You))))
            return listOf(Step.Do(Effect.Surveil(Players.You, Value.Fixed(n)))) + unlessPays(Players.ControllerOf(spell),
                Cost(listOf(CostPart.Mana(ManaCost.parse(m.groupValues[2]) ?: return null, times = graveyard))), listOf(Step.Do(Effect.Counter(spell))))
        }
        // fin chunk 09: "You may cast target instant or sorcery card from a graveyard, and mana of any type can be spent to cast that spell. If that
        // spell would be put into a graveyard, exile it instead." (CR 608.2g, 601.2h)
        Fin.MAY_CAST_TARGET_FROM_GRAVEYARD_ANY_TYPE.matchEntire(text)?.let { m ->
            val target = context.target("card", Filters.all(Filters.noun(m.groupValues[1]) ?: return null, ObjectFilter.InZone(Zone.Graveyard)))
            val spell = Objects.Bound("spell")
            return listOf(Step.May(listOf(Step.Do(Effect.Cast(target, PlayKind.Cast, bind = "spell", caster = Players.You, manaAsAnyType = true))), Players.You),
                Step.Do(Effect.ApplyMechanics(listOf(Mechanic.Replacement(EventPattern.ZoneChange(ObjectFilter.Is(spell), from = Zone.Stack, to = Zone.Graveyard),
                    modify = listOf(Modification.ChangeDestination(Destination(Zone.Exile))))), null, arcanum.api.Duration.Indefinitely)))
