        Tdm.NEXT_TIME_SOURCE_OF_CHOICE_PREVENT_REFLECT.matchEntire(text)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            val source = Objects.Bound("source")
            val reflexive = Instructions(steps = listOf(Step.Do(Effect.ReflexiveTrigger(Instructions(steps = listOf(
                Step.Do(Effect.DealDamage(Recipients(players = Players.ControllerOf(source)), Value.EventAmount, Objects.Self)),
                Step.Do(Effect.Draw(Players.You, Value.EventAmount))))))))
            return listOf(Step.Choose(arcanum.api.Choice.Objects(ObjectFilter.Any, Value.Fixed(1), Value.Fixed(1)), bind = "source", chooser = Players.You),
                Step.Do(Effect.ApplyMechanics(listOf(Mechanic.Prevention(EventPattern.Damage(ObjectFilter.Is(source), RecipientFilter(players = PlayerFilter.You)),
                    additional = reflexive)), null, arcanum.api.Duration.EndOfTurn, uses = 1)))
        }
        return null
    }

    /** tdm: sentences that change the steps before them. */
    private fun tdmModify(sentence: String, steps: List<Step>, context: Context): List<Step>? {
        // tdm chunk 03: "Those creatures gain flying until your next turn." after counters on each of them (the same objects, locked as the effect
        // begins, CR 611.2c)
        Tdm.THOSE_GAIN_UNTIL.matchEntire(sentence)?.let { m ->
            val put = (steps.lastOrNull() as? Step.Do)?.effect as? Effect.PutCounters ?: return@let
            if (put.objects !is Objects.Each) return@let
            val keywords = tdmKeywords(m.groupValues[1]) ?: return null
            val duration = if (m.groupValues[2] == "your next turn") arcanum.api.Duration.UntilYourNextTurn else arcanum.api.Duration.EndOfTurn
            return steps + Step.Do(Effect.ApplyMechanics(listOf(Mechanic.GainAbilities(keywords)), Affected.Objects(put.objects), duration))
        }
        // tdm chunk 05: "When it dies under your control this turn, draw two cards." after a pump of a target (a delayed trigger, CR 603.7)
        Tdm.WHEN_IT_DIES_UNDER_YOUR_CONTROL_THIS_TURN.matchEntire(sentence)?.let { m ->
            val it = context.it ?: context.targets.lastOrNull()?.let { Objects.Target(it.name) } ?: return null
            val then = instructions(m.groupValues[1].replaceFirstChar { c -> c.uppercase() }) ?: return null
            return steps + Step.Do(Effect.CreateDelayedTrigger(arcanum.api.Trigger.On(EventPattern.ZoneChange(Filters.all(ObjectFilter.Is(it),
                ObjectFilter.ControlledBy(PlayerFilter.You)), from = Zone.Battlefield, to = Zone.Graveyard)), then, duration = arcanum.api.Duration.EndOfTurn))
        }
        // tdm chunk 13: "Then if your library has no cards in it, exile this enchantment and put five cards from your graveyard on top of your library in
        // any order." after milling
        Tdm.THEN_IF_LIBRARY_EMPTY_EXILE_AND_PUT.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val n = Numbers.count(m.groupValues[2]) ?: return null
            val library = Objects.Each(Filters.all(ObjectFilter.InZone(Zone.Library), ObjectFilter.OwnedBy(PlayerFilter.You)))
            return steps + Step.If(arcanum.api.Condition.Compare(Value.Count(library), arcanum.api.Comparison.Equal, Value.Fixed(0)), then = listOf(
                Step.Do(Effect.Move(Objects.Self, Destination(Zone.Exile))),
                Step.Choose(arcanum.api.Choice.Objects(tdmInGraveyard(ObjectFilter.Category(arcanum.api.ObjectCategory.Card)), Value.Fixed(n), Value.Fixed(n)), bind = "chosen",
                    chooser = Players.You),
                Step.Do(Effect.Move(Objects.Bound("chosen"), Destination(Zone.Library, libraryPosition = 0)))))
        }
        // tdm chunk 06: "You may attach this Equipment to it." after creating a token: the token (CR 301.5)
        Tdm.MAY_ATTACH_SELF_TO_IT.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            val create = (steps.lastOrNull() as? Step.Do)?.effect as? Effect.CreateToken ?: return@let
            val bind = create.bind ?: "token"
            return steps.dropLast(1) + Step.Do(create.copy(bind = bind)) +
                Step.May(listOf(Step.Do(Effect.Attach(Objects.Self, Recipients(objects = Objects.Bound(bind))))), player = Players.You)
        }
        // tdm chunk 09: "Put a +1/+1 counter on each of those creatures." after returning cards to the battlefield: the permanents they became
        // (CR 400.7)
        Tdm.COUNTER_ON_EACH_OF_THOSE.matchEntire(sentence)?.let { m ->
            val move = (steps.lastOrNull() as? Step.Do)?.effect as? Effect.Move ?: return@let
            if (move.to.zone != Zone.Battlefield) return@let
            val bind = move.postBind ?: "returned"
            return steps.dropLast(1) + Step.Do(move.copy(postBind = bind)) + Step.Do(Effect.PutCounters(Objects.Bound(bind), Counters.kind(m.groupValues[1]) ?: return null, Value.Fixed(1)))
        }
        // tdm chunk 09: "If it was a token, draw a card." after returning a permanent to its hand: the permanent as it last existed (CR 608.2h)
        Tdm.IF_IT_WAS_A_TOKEN.matchEntire(sentence)?.let { m ->
            val move = (steps.lastOrNull() as? Step.Do)?.effect as? Effect.Move ?: return@let
            val bind = move.preBind ?: "returned"
            val then = instructions(m.groupValues[1].replaceFirstChar { it.uppercase() } + ".") ?: return null
            return steps.dropLast(1) + Step.Do(move.copy(preBind = bind)) +
                Step.If(arcanum.api.Condition.ObjectMatches(Objects.Bound(bind), ObjectFilter.Category(arcanum.api.ObjectCategory.Token)), then = then.steps)
        }
        // tdm chunk 11: "It gains lifelink and haste until end of turn." after creating a token
        Tdm.CREATE_IT_GAINS_UNTIL_EOT.matchEntire(sentence)?.let { m ->
            val create = (steps.lastOrNull() as? Step.Do)?.effect as? Effect.CreateToken ?: return@let
            val keywords = tdmKeywords(m.groupValues[1]) ?: return null
            val bind = create.bind ?: "token"
            return steps.dropLast(1) + Step.Do(create.copy(bind = bind)) + tdmUntilEndOfTurn(Objects.Bound(bind), Mechanic.GainAbilities(keywords))
        }
        // tdm chunk 12: "They gain menace and haste until end of turn." after creating tokens
        Tdm.THEY_GAIN_UNTIL_EOT.matchEntire(sentence)?.let { m ->
            val create = (steps.lastOrNull() as? Step.Do)?.effect as? Effect.CreateToken ?: return@let
            val keywords = tdmKeywords(m.groupValues[1]) ?: return null
            val bind = create.bind ?: "tokens"
            return steps.dropLast(1) + Step.Do(create.copy(bind = bind)) + tdmUntilEndOfTurn(Objects.Bound(bind), Mechanic.GainAbilities(keywords))
        }
        // tdm chunk 13: "Each other creature you control becomes a copy of that creature until end of turn." after a counter on a target (CR 707.2)
        Tdm.EACH_OTHER_BECOMES_COPY_UNTIL_EOT.matchEntire(sentence)?.let { m ->
            val target = context.targets.lastOrNull()?.let { Objects.Target(it.name) } ?: return null
            val others = Filters.all(Filters.noun(m.groupValues[1]) ?: return null, ObjectFilter.Not(ObjectFilter.Is(target)))
            return steps + tdmUntilEndOfTurn(Objects.Each(others), Mechanic.CopyOf(target))
        }
        return null
    }

    /** tdm: effect sentences. */
    private fun tdmEffect(sentence: String, context: Context): List<Step>? {
        // tdm chunk 01: "Anafenza endures 2.", "it endures 1", "This creature endures X." (CR 701.63a)
        Tdm.ENDURES.matchEntire(sentence)?.let { m ->
            val objects = tdmObjects(m.groupValues[1], context) ?: return@let
            val count = tdmCount(m.groupValues[2]) ?: return@let
            return listOf(tdmEndure(objects, count))
        }
        // tdm chunk 01: "you lose 1 life and this creature endures 1"
        Tdm.LOSE_LIFE_AND_ENDURES.matchEntire(sentence)?.let { m ->
            val objects = tdmObjects(m.groupValues[2], context) ?: return null
            return listOf(Step.Do(Effect.LoseLife(Players.You, Value.Fixed(m.groupValues[1].toInt()))), tdmEndure(objects, tdmCount(m.groupValues[3]) ?: return null))
        }
        // tdm chunk 03: "Put a flying counter, a deathtouch counter, and a lifelink counter on target creature." (CR 122.1b)
        Tdm.PUT_COUNTER_LIST_ON.matchEntire(sentence)?.let { m ->
            val items = mutableListOf<Pair<Value, arcanum.api.CounterKind>>()
            for (item in Tdm.COUNTER_ITEM.findAll(m.groupValues[1])) items += (tdmCount(item.groupValues[1]) ?: return null) to (Counters.kind(item.groupValues[2]) ?: return null)
            val objects = tdmObjects(m.groupValues[2], context) ?: return null
            return items.map { (n, kind) -> Step.Do(Effect.PutCounters(objects, kind, n)) }
        }
        // tdm chunk 03: "Put a decayed counter on each of X target creatures." (X announced as it is activated, CR 107.3a)
        Tdm.PUT_COUNTER_ON_EACH_OF_X_TARGETS.matchEntire(sentence)?.let { m ->
            val name = Filters.slotName(m.groupValues[2])
            context.targets += TargetSlot(name, TargetKind.Objects(Filters.noun(m.groupValues[2]) ?: return null), min = Value.Announced(name = "X"), max = Value.Announced(name = "X"))
            return listOf(Step.Do(Effect.PutCounters(Objects.Target(name), Counters.kind(m.groupValues[1]) ?: return null, Value.Fixed(1))))
        }
        // tdm chunk 05: "target creature an opponent controls gets -2/-2 until end of turn and target creature you control gets +2/+2 until end of turn"
        Tdm.TWO_TARGETS_GET.matchEntire(sentence)?.let { m ->
            val first = context.target(Filters.slotName(m.groupValues[1]), Filters.noun(m.groupValues[1]) ?: return null)
            val second = context.target(Filters.slotName(m.groupValues[4]), Filters.noun(m.groupValues[4]) ?: return null)
            fun n(i: Int) = Value.Fixed(m.groupValues[i].toInt())
            return listOf(tdmUntilEndOfTurn(first, Mechanic.ModifyPowerToughness(n(2), n(3))), tdmUntilEndOfTurn(second, Mechanic.ModifyPowerToughness(n(5), n(6))))
        }
        // tdm chunk 05: "Target opponent exiles a creature they control and their graveyard."
        Tdm.OPPONENT_EXILES_CREATURE_AND_GRAVEYARD.matchEntire(sentence)?.let { m ->
            val opponent = context.targetOpponent()
            val filter = Filters.all(Filters.noun(m.groupValues[1]) ?: return null, ObjectFilter.ControlledBy(PlayerFilter.Is(opponent)))
            return listOf(Step.Choose(arcanum.api.Choice.Objects(filter, Value.Fixed(1), Value.Fixed(1)), bind = "chosen", chooser = opponent),
                Step.Do(Effect.Move(Objects.Bound("chosen"), Destination(Zone.Exile))),
                Step.Do(Effect.Move(Objects.Each(Filters.all(ObjectFilter.Category(arcanum.api.ObjectCategory.Card), ObjectFilter.InZone(Zone.Graveyard),
                    ObjectFilter.OwnedBy(PlayerFilter.Is(opponent)))), Destination(Zone.Exile))))
        }
        // tdm chunk 05: "Creatures target opponent controls get -1/-1 until end of turn." (locked as it resolves, CR 611.2c)
        Tdm.CREATURES_TARGET_OPPONENT_CONTROLS_GET.matchEntire(sentence)?.let { m ->
            val opponent = context.targetOpponent()
            val filter = Filters.all(Filters.noun(m.groupValues[1].lowercase()) ?: return null, ObjectFilter.ControlledBy(PlayerFilter.Is(opponent)))
            return listOf(tdmUntilEndOfTurn(Objects.Each(filter), Mechanic.ModifyPowerToughness(Value.Fixed(m.groupValues[2].toInt()), Value.Fixed(m.groupValues[3].toInt()))))
        }
        // tdm chunk 06: "exile up to two target cards from a single graveyard" (one owner, CR 115.1)
        Tdm.FROM_A_SINGLE_GRAVEYARD.matchEntire(sentence)?.let { m ->
            context.targets += TargetSlot("card", TargetKind.Objects(Filters.all(ObjectFilter.Category(arcanum.api.ObjectCategory.Card), ObjectFilter.InZone(Zone.Graveyard))),
                min = Value.Fixed(0), max = Value.Fixed(Numbers.count(m.groupValues[1]) ?: return null), sameOwner = true)
            return listOf(Step.Do(Effect.Move(Objects.Target("card"), Destination(Zone.Exile))))
        }
        // tdm chunk 06: "up to one target player mills cards equal to this creature's power"
        Tdm.UP_TO_ONE_TARGET_PLAYER_MILLS_EQUAL.matchEntire(sentence)?.let { m ->
            val amount = selfNumber(m.groupValues[1]) ?: Values.value(m.groupValues[1]) ?: return null
            context.targets += TargetSlot("player", TargetKind.Players(PlayerFilter.Any), min = Value.Fixed(0), max = Value.Fixed(1))
            return listOf(Step.Do(Effect.Mill(Players.Target("player"), amount)))
        }
        // tdm chunk 06: "return up to two other target nonland permanents to their owners' hands"
        Tdm.RETURN_UP_TO_OTHER_TARGETS_TO_HANDS.matchEntire(sentence)?.let { m ->
            val name = Filters.slotName(m.groupValues[2])
            context.targets += tdmSlot(name, Filters.all(ObjectFilter.Not(ObjectFilter.Is(Objects.Self)), Filters.noun(m.groupValues[2]) ?: return null), min = 0,
                max = Numbers.count(m.groupValues[1]) ?: return null)
            return listOf(Step.Do(Effect.Move(Objects.Target(name), Destination(Zone.Hand))))
        }
        // tdm chunk 07: "Up to two target creatures each get +2/+1 until end of turn."
        Tdm.UP_TO_TARGETS_EACH_GET.matchEntire(sentence)?.let { m ->
            val name = Filters.slotName(m.groupValues[2])
            context.targets += tdmSlot(name, Filters.noun(m.groupValues[2]) ?: return null, min = 0, max = Numbers.count(m.groupValues[1]) ?: return null)
            return listOf(tdmUntilEndOfTurn(Objects.Target(name), Mechanic.ModifyPowerToughness(Value.Fixed(m.groupValues[3].toInt()), Value.Fixed(m.groupValues[4].toInt()))))
        }
        // tdm chunk 07: "Until end of turn, Sarkhan becomes a Dragon in addition to his other types and gains flying." (CR 205.1b)
        Tdm.UNTIL_EOT_BECOMES_SUBTYPE_AND_GAINS.matchEntire(sentence)?.let { m ->
            val objects = tdmObjects(m.groupValues[1], context) ?: return null
            val keywords = tdmKeywords(m.groupValues[3]) ?: return null
            return listOf(tdmUntilEndOfTurn(objects, Mechanic.SetTypes(addSubtypes = listOf(arcanum.api.SubtypeRef.Literal(Subtype(m.groupValues[2])))), Mechanic.GainAbilities(keywords)))
        }
        // tdm chunk 07: "this enchantment becomes a 3/3 Monk creature with haste in addition to its other types until end of turn" (CR 205.1b)
        Tdm.BECOMES_PT_CREATURE_WITH_IN_ADDITION.matchEntire(sentence)?.let { m ->
            val objects = tdmObjects(m.groupValues[1], context) ?: return null
            val keywords = if (m.groupValues[5].isEmpty()) emptyList() else tdmKeywords(m.groupValues[5]) ?: return null
            return listOf(tdmUntilEndOfTurn(objects, *listOfNotNull(
                Mechanic.SetTypes(add = listOf(CardType.Creature), addSubtypes = m.groupValues[4].split(' ').map { arcanum.api.SubtypeRef.Literal(Subtype(it)) }),
                Mechanic.SetPowerToughness(Value.Fixed(m.groupValues[2].toInt()), Value.Fixed(m.groupValues[3].toInt())),
                keywords.takeIf { it.isNotEmpty() }?.let { Mechanic.GainAbilities(it) }).toTypedArray()))
        }
        // tdm chunk 08: "Put a +1/+1 counter on target creature you control, then it deals damage equal to its power to target creature an opponent
        // controls."
        Tdm.COUNTER_THEN_DEALS_DAMAGE_EQUAL_POWER.matchEntire(sentence)?.let { m ->
            val first = context.target(Filters.slotName(m.groupValues[2]), Filters.noun(m.groupValues[2]) ?: return null)
            val second = context.target(Filters.slotName(m.groupValues[3]), Filters.noun(m.groupValues[3]) ?: return null)
            return listOf(Step.Do(Effect.PutCounters(first, Counters.kind(m.groupValues[1]) ?: return null, Value.Fixed(1))),
                Step.Do(Effect.DealDamage(Recipients(objects = second), tdmPower(first), first)))
        }
        // tdm chunk 08: "you may mill cards equal to the number of lands you control"
        Tdm.MAY_MILL_EQUAL.matchEntire(sentence)?.let { m ->
            val amount = Values.value(m.groupValues[1]) ?: return null
            return listOf(Step.May(listOf(Step.Do(Effect.Mill(Players.You, amount))), player = Players.You))
        }
        // tdm chunk 09: "distribute three +1/+1 counters among one, two, or three target creatures you control" (CR 601.2d)
        Tdm.DISTRIBUTE_COUNTERS_AMONG.matchEntire(sentence)?.let { m ->
            val n = Numbers.count(m.groupValues[1]) ?: return null
            val name = Filters.slotName(m.groupValues[4])
            context.targets += TargetSlot(name, TargetKind.Objects(Filters.noun(m.groupValues[4]) ?: return null), min = Value.Fixed(1), max = Value.Fixed(3),
                divided = Value.Fixed(n))
            return listOf(Step.Do(Effect.PutCounters(Objects.Target(name), Counters.kind(m.groupValues[2]) ?: return null, Value.DividedShare)))
        }
        // tdm chunk 09: "it deals 3 damage to each creature and each planeswalker"
        Tdm.DEALS_DAMAGE_TO_EACH_AND_EACH.matchEntire(sentence)?.let { m ->
            val source = tdmObjects(m.groupValues[1], context) ?: return@let
            val a = Filters.noun(m.groupValues[3]) ?: return@let
            val b = Filters.noun(m.groupValues[4]) ?: return@let
            return listOf(Step.Do(Effect.DealDamage(Recipients(objects = Objects.Each(ObjectFilter.Or(listOf(a, b)))), Value.Fixed(m.groupValues[2].toInt()), source)))
        }
        // tdm chunk 09: "Double the power and toughness of each creature you control until end of turn." (CR 701.10e)
        Tdm.DOUBLE_PT_OF_EACH.matchEntire(sentence)?.let { m ->
            val filter = Filters.noun(m.groupValues[1]) ?: return null
            return listOf(Step.ForEach(arcanum.api.Each.Objects(Objects.Each(filter)), "creature", listOf(tdmUntilEndOfTurn(Objects.Bound("creature"),
                Mechanic.ModifyPowerToughness(tdmPower(Objects.Bound("creature")), Value.Of(arcanum.api.NumericProperty.Toughness, Objects.Bound("creature"), arcanum.api.Combine.Single))))))
        }
        // tdm chunk 09: "draw a card and put two +1/+1 counters on Eshki Dragonclaw"
        Tdm.DRAW_AND_PUT_COUNTERS.matchEntire(sentence)?.let { m ->
            val objects = tdmObjects(m.groupValues[3], context) ?: return null
            return listOf(Step.Do(Effect.Draw(Players.You, Value.Fixed(1))),
                Step.Do(Effect.PutCounters(objects, Counters.kind(m.groupValues[2]) ?: return null, Value.Fixed(Numbers.count(m.groupValues[1]) ?: return null))))
        }
        // tdm chunk 10: "put up to one target noncreature, nonland card from your graveyard on top of your library"
        Tdm.PUT_UP_TO_ONE_FROM_GRAVEYARD_ON_TOP.matchEntire(sentence)?.let { m ->
            val name = Filters.slotName(m.groupValues[1])
            context.targets += tdmSlot(name, tdmInGraveyard(Filters.noun(m.groupValues[1]) ?: return null), min = 0)
            return listOf(Step.Do(Effect.Move(Objects.Target(name), Destination(Zone.Library, libraryPosition = 0))))
        }
        // tdm chunk 10: "Return target permanent card from your graveyard to the battlefield with a hexproof counter and an indestructible counter on it."
        Tdm.RETURN_WITH_TWO_COUNTERS.matchEntire(sentence)?.let { m ->
            val name = Filters.slotName(m.groupValues[1])
            context.targets += tdmSlot(name, tdmInGraveyard(Filters.noun(m.groupValues[1]) ?: return null))
            return listOf(Step.Do(Effect.Move(Objects.Target(name), Destination(Zone.Battlefield, counters = listOf(
                arcanum.api.CountersToPut(Counters.kind(m.groupValues[2]) ?: return null, Value.Fixed(1)),
                arcanum.api.CountersToPut(Counters.kind(m.groupValues[3]) ?: return null, Value.Fixed(1)))))))
        }
        // tdm chunk 10: "remove all counters from up to one target creature"
        Tdm.REMOVE_ALL_COUNTERS_FROM_UP_TO_ONE.matchEntire(sentence)?.let { m ->
            val name = Filters.slotName(m.groupValues[1])
            context.targets += tdmSlot(name, Filters.noun(m.groupValues[1]) ?: return null, min = 0)
            return listOf(Step.Do(Effect.RemoveCounters(Objects.Target(name), null, Value.Of(arcanum.api.NumericProperty.Counters(null), Objects.Target(name), arcanum.api.Combine.Single))))
        }
        // tdm chunk 11: "you lose life equal to its mana value" (the spell cast)
        Tdm.LOSE_LIFE_EQUAL_ITS_MV.matchEntire(sentence)?.let {
            val it = context.it ?: return null
            return listOf(Step.Do(Effect.LoseLife(Players.You, Value.Of(arcanum.api.NumericProperty.ManaValue, it, arcanum.api.Combine.Single))))
        }
        // tdm chunk 11: "it deals X damage divided as you choose among any number of target creatures and/or planeswalkers your opponents control"
        // (CR 601.2d)
        Tdm.DIVIDED_AMONG_ANY_NUMBER.matchEntire(sentence)?.let { m ->
            val source = tdmObjects(m.groupValues[1], context) ?: return null
            val noun = m.groupValues[3]
            val name = Filters.slotName(noun)
            // mh2 chunk 07: a fixed amount
            val amount = m.groupValues[2].toIntOrNull()?.let { Value.Fixed(it) } ?: Value.Announced(name = "X")
            context.targets += TargetSlot(name, TargetKind.Objects(Filters.noun(noun) ?: return null), min = Value.Fixed(1), max = null, divided = amount)
            return listOf(Step.Do(Effect.DealDamage(Recipients(objects = Objects.Target(name)), Value.DividedShare, source)))
        }
        // tdm chunk 14: "each opponent loses half their life, rounded up" (CR 107.1a)
        Tdm.EACH_OPPONENT_LOSES_HALF.matchEntire(sentence)?.let { m ->
            return listOf(Step.ForEach(arcanum.api.Each.Players(Players.Each(PlayerFilter.Opponent)), "opponent", listOf(Step.Do(Effect.LoseLife(Players.Bound("opponent"),
                Value.Half(Value.LifeOf(Players.Bound("opponent")), roundUp = m.groupValues[1] == "up")))), together = true))
        }
        // tdm chunk 13: "Copy this spell." (CR 707.10)
        Tdm.COPY_THIS_SPELL.matchEntire(sentence)?.let {
            return listOf(Step.Do(Effect.CopySpell(Objects.Self, Players.You, newTargets = true)))
        }
        // tdm chunk 13: "Put its counters on up to one target creature you control." (the creature that died, as it last existed, CR 603.10a)
        Tdm.PUT_ITS_COUNTERS_ON_UP_TO_ONE.matchEntire(sentence)?.takeIf { !context.selfDied() }?.let { m ->
            val name = Filters.slotName(m.groupValues[1])
            context.targets += tdmSlot(name, Filters.noun(m.groupValues[1]) ?: return null, min = 0)
            return listOf(Step.Do(Effect.PutCountersOf(Objects.Target(name), Objects.EventObject(EventRole.Before))))
        }
        return null
    }

    // ---- mh2: Modern Horizons 2 wordings (the set's parser tests, sets/mh2/Mh2Chunk*Test.kt); regexes in [Mh2], phrases in [Mh2Phrases].
    // Each rule is tried first and reads one wording, falling through when it can't.

    private fun mh2Slot(name: String, filter: ObjectFilter, min: Int = 1, max: Int? = 1) =
        TargetSlot(name, TargetKind.Objects(filter), min = Value.Fixed(min), max = max?.let { Value.Fixed(it) })
    private fun mh2UntilEndOfTurn(objects: Objects, vararg mechanics: Mechanic) =
        Step.Do(Effect.ApplyMechanics(mechanics.toList(), Affected.Objects(objects), arcanum.api.Duration.EndOfTurn))
    private fun mh2NewSlotName(context: Context, base: String) = if (context.targets.none { it.name == base }) base else nextTargetName(base, context.targets.map { it.name })
    private fun mh2Color(word: String): ObjectFilter? = Tokens.color(word)?.let { ObjectFilter.OfColor(it) }
    private fun mh2SelfStatic(vararg mechanics: Mechanic) = Ability.Static(mechanics.toList(), affects = Affected.Objects(Objects.Self))

    /** mh2: the objects a phrase names: this object, "each [noun]" / "all [nouns]", "it" (the last object target, else the event's object). */
    private fun mh2Objects(phrase: String, context: Context): Objects? {
        if (isSelf(phrase)) return Objects.Self
        if (phrase == "it") return context.targets.lastOrNull()?.takeIf { it.what is TargetKind.Objects }?.let { Objects.Target(it.name) } ?: context.it
        if (phrase.startsWith("each ")) return Filters.noun(phrase.removePrefix("each "))?.let { Objects.Each(it) }
        if (phrase.startsWith("all ")) return Filters.noun(phrase.removePrefix("all ").removeSuffix("s"))?.let { Objects.Each(it) }
        return null
    }

    /** mh2 chunk 09: "+1/+1 counter on creatures you control": the counters of that kind on all of them. */
    private fun mh2CountersOn(text: String): Value? {
        val m = Mh2.COUNTER_ON_CREATURES.matchEntire(text) ?: return null
        val kind = Counters.kind(m.groupValues[1]) ?: return null
        val objects = Filters.noun(m.groupValues[2].removeSuffix("s").replace("creatures ", "creature ")) ?: return null
        return Value.Of(arcanum.api.NumericProperty.Counters(kind), Objects.Each(objects), arcanum.api.Combine.Total)
    }

    /** mh2 chunk 14: a use of restricted mana: "activate abilities of artifacts" (CR 106.6). */
    private fun mh2SpendUse(use: String): ObjectFilter? = when (use) {
        "activate abilities of artifacts" -> ObjectFilter.AbilityOf(kind = arcanum.api.AbilityKind.Activated, source = ObjectFilter.Type(CardType.Artifact))
        else -> null
    }

    /** mh2: a value "where X is …" defines. */
    private fun mh2Value(text: String): Value? {
        // mh2 chunk 02: "the exiled card's toughness" in a spell that exiled it (the card it moved, as it last was, CR 608.2h)
        Mh2.EXILED_CARDS_NUMBER.matchEntire(text)?.takeIf { isSpell }?.let { m ->
            val property = if (m.groupValues[1] == "power") arcanum.api.NumericProperty.Power else arcanum.api.NumericProperty.Toughness
            return Value.Of(property, Objects.Bound("exiled"), arcanum.api.Combine.Single)
        }
        return null
    }

    /** mh2 chunk 12: "When this creature enters, choose one. If [condition], choose both instead." with its modes (CR 700.2). */
    private fun mh2ModalTrigger(header: String, modeLines: List<String>): Ability? {
        val m = WHENEVER.matchEntire(header) ?: return null
        val choose = Mh2.CHOOSE_ONE_IF_CHOOSE_BOTH_INSTEAD.matchEntire(m.groupValues[3]) ?: return null
        val (trigger, onlyIf) = trigger(m.groupValues[2]) ?: return null
        val condition = Conditions.condition(choose.groupValues[1], self) ?: return null
        val options = modeLines.map { arcanum.api.Mode(instructions(modeBody(it), that = that(trigger)) ?: return null, text = it) }
        if (options.size != 2) return null
        return Ability.Triggered(trigger, Instructions(modes = arcanum.api.Modes(options, min = 1, max = 1, maxIf = condition, maxIfCount = 2,
            chooser = Players.You)), triggersOnlyIf = onlyIf)
    }

    /** mh2: lines of more than one ability. */
    private fun mh2Multi(line: String): List<Ability>? {
        // mh2 chunk 13: "Each creature you control has vigilance if it's white, hexproof if it's blue, …": one rule for each colour
        Mh2.EACH_CREATURE_HAS_KEYWORD_IF_ITS_COLOR.matchEntire(line)?.takeIf { it.groupValues[1].contains(" if it's ") }?.let { m ->
            val parts = m.groupValues[1].split(", ").map { Mh2.KEYWORD_IF_ITS_COLOR.matchEntire(it) ?: return@let }
            return parts.map { p ->
                val keyword = OracleParser.keyword(p.groupValues[1].replaceFirstChar { it.uppercase() }) ?: return@let
                Ability.Static(listOf(Mechanic.GainAbilities(listOf(keyword))), affects = Affected.Objects(Objects.Each(Filters.all(ObjectFilter.Type(CardType.Creature),
                    ObjectFilter.ControlledBy(PlayerFilter.You), mh2Color(p.groupValues[2]) ?: return@let))))
            }
        }
        // mh2 chunk 02: "You and creatures you control have protection from the chosen card type." (you, CR 702.16k, and the creatures)
        Mh2.YOU_AND_HAVE_PROTECTION_FROM_CHOSEN_CARD_TYPE.matchEntire(line)?.let { m ->
            val objects = Filters.objects(m.groupValues[1]) ?: return null
            val protection = Mechanic.GainAbilities(listOf(arcanum.api.Keyword.Protection(ObjectFilter.Type(arcanum.api.CardTypeRef.Remembered(CHOSEN_TYPE)))))
            return listOf(Ability.Static(listOf(protection), affects = Affected.Players(Players.You)), Ability.Static(listOf(protection), affects = Affected.Objects(objects)))
        }
        return null
    }

    /** mh2: whole lines. */
    private fun mh2Line(line: String): Ability? {
        // mh2 chunk 11: "Whenever this creature or another creature you control enters, if that creature entered from a graveyard or you cast it from a
        // graveyard, [effect]": two events, a creature you control entering from a graveyard and one cast from a graveyard (CR 603.2, 601.2a)
        Mh2.THIS_OR_ANOTHER_ENTERS_FROM_GRAVEYARD_OR_CAST_FROM.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val noun = Filters.noun(m.groupValues[2]) ?: return@let
            val instructions = instructions(m.groupValues[3].replaceFirstChar { it.uppercase() }) ?: return@let
            return Ability.Triggered(arcanum.api.Trigger.On(listOf(
                EventPattern.ZoneChange(noun, from = Zone.Graveyard, to = Zone.Battlefield),
                EventPattern.ZoneChange(Filters.all(noun, ObjectFilter.WasCast(from = Zone.Graveyard)), to = Zone.Battlefield))), instructions)
        }
        return null
    }

    /** mh2: static abilities. */
    private fun mh2Static(line: String): Ability? {
        // mh2 chunk 07: "This spell has cascade as long as there are four or more card types among cards in your graveyard." Cascade triggers as the
        // spell is cast (CR 702.85a), so the rule works on the Stack (CR 113.6b)
        Mh2.THIS_SPELL_HAS_CASCADE_AS_LONG_AS.matchEntire(line)?.let { m ->
            val condition = Conditions.condition(m.groupValues[1], self) ?: return@let
            return Ability.Static(listOf(Mechanic.GainAbilities(listOf(arcanum.api.Keyword.Cascade))), affects = Affected.Objects(Objects.Self),
                condition = condition, functionsIn = listOf(Zone.Stack))
        }
        // mh2 chunk 16: "As this creature enters, choose a number." (CR 614.12, 607.2d)
        Mh2.AS_ENTERS_CHOOSE_A_NUMBER.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            return mh2SelfStatic(Mechanic.Replacement(EventPattern.ZoneChange(ObjectFilter.Is(Objects.Self), to = Zone.Battlefield), modify = listOf(Modification.AsEnters(listOf(
                Step.Choose(arcanum.api.Choice.Number(Value.Fixed(0)), bind = "number", chooser = Players.You, remember = true))))))
        }
        // mh2 chunk 16: "Noncreature spells with mana value equal to the chosen number can't be cast." (by any player, CR 101.2)
        Mh2.SPELLS_WITH_MV_EQUAL_TO_CHOSEN_NUMBER_CANT_BE_CAST.matchEntire(line)?.let { m ->
            val noun = Filters.noun(m.groupValues[1].lowercase()) ?: return@let
            return Ability.Static(listOf(Mechanic.CantCast(Filters.all(noun, ObjectFilter.ManaValue(arcanum.api.Comparison.Equal, Value.Remembered("number"))))),
                affects = Affected.Players(Players.Each(PlayerFilter.Any)))
        }
        // mh2 chunk 15: "If an opponent controls an Island and you control a Mountain, you may cast this spell without paying its mana cost." (an
        // alternative cost of nothing, CR 118.9)
        Mh2.IF_MAY_CAST_WITHOUT_PAYING.matchEntire(line)?.let { m ->
            val parts = m.groupValues[1].split(" and ").map { Conditions.condition(it, self) ?: return@let }
            return Ability.Static(listOf(Mechanic.MayPlay(Zone.Hand, PlayKind.Cast, withoutPaying = true, holder = PlayerFilter.You)), affects = Affected.Objects(Objects.Self),
                condition = parts.singleOrNull() ?: arcanum.api.Condition.And(parts))
        }
        // mh2 chunk 15: "Skip your draw step." (CR 614.10)
        Mh2.SKIP_YOUR_STEP.matchEntire(line)?.let { m ->
            val step = mapOf("draw" to arcanum.api.TurnStep.Draw, "untap" to arcanum.api.TurnStep.Untap, "upkeep" to arcanum.api.TurnStep.Upkeep)[m.groupValues[1]] ?: return@let
            return Ability.Static(listOf(Mechanic.SkipStep(step)), affects = Affected.Players(Players.You))
        }
        // mh2 chunk 15: "You have shroud." (CR 702.18: for a player, no spell or ability can target them)
        if (Mh2.YOU_HAVE_SHROUD.matches(line)) return Ability.Static(listOf(Mechanic.CantBeTargeted(by = ObjectFilter.Any)), affects = Affected.Players(Players.You))
        // mh2 chunk 15: "Prevent all damage that would be dealt to you." (CR 615.1)
        if (Mh2.PREVENT_ALL_DAMAGE_TO_YOU.matches(line))
            return mh2SelfStatic(Mechanic.Prevention(EventPattern.Damage(ObjectFilter.Any, arcanum.api.RecipientFilter(players = PlayerFilter.You))))
        // mh2 chunk 14: "Each land is a Forest in addition to its other land types." (layer 4, CR 305.7)
        Mh2.EACH_IS_A_TYPE_IN_ADDITION.matchEntire(line)?.let { m ->
            if (m.groupValues[2] !in RulesWords.subtypes) return@let
            val noun = Filters.noun(m.groupValues[1]) ?: return@let
            return Ability.Static(listOf(Mechanic.SetTypes(addSubtypes = listOf(arcanum.api.SubtypeRef.Literal(Subtype(m.groupValues[2]))))),
                affects = Affected.Objects(Objects.Each(noun)))
        }
        // mh2 chunk 13: "Equipped creature gets +5/+5 and has first strike, trample, indestructible, haste, and "Whenever this creature …"" (layer 6, 7c)
        Mh2.GETS_AND_HAS_KEYWORDS_AND_QUOTED.matchEntire(line)?.takeIf { it.groupValues[1] == "Equipped creature" }?.let { m ->
            val keywords = m.groupValues[4].split(", ").map { OracleParser.keyword(it.trim().replaceFirstChar { c -> c.uppercase() }) ?: return@let }
            val quoted = Sentences(setOf("this creature")).line(m.groupValues[5]) ?: return@let
            return Ability.Static(listOf(Mechanic.ModifyPowerToughness(Value.Fixed(m.groupValues[2].toInt()), Value.Fixed(m.groupValues[3].toInt())),
                Mechanic.GainAbilities(keywords + quoted)), affects = Affected.Objects(Objects.AttachedTo(Objects.Self)))
        }
        // mh2 chunk 13: "Equipped creature gets +2/+2 and has protection from green and from white." (CR 702.16g)
        Mh2.GETS_AND_HAS_PROTECTION_FROM_TWO.matchEntire(line)?.takeIf { it.groupValues[1] == "Equipped creature" }?.let { m ->
            val keywords = listOf(arcanum.api.Keyword.Protection(mh2Color(m.groupValues[4]) ?: return@let), arcanum.api.Keyword.Protection(mh2Color(m.groupValues[5]) ?: return@let))
            return Ability.Static(listOf(Mechanic.ModifyPowerToughness(Value.Fixed(m.groupValues[2].toInt()), Value.Fixed(m.groupValues[3].toInt())),
                Mechanic.GainAbilities(keywords)), affects = Affected.Objects(Objects.AttachedTo(Objects.Self)))
        }
        // mh2 chunk 13: "If you would create a Clue, Food, or Treasure token, instead create one of each." One replacement effect, applied once to
        // an event (CR 614.5): the matching tokens become Clues, and as many Foods and Treasures come with them (CR 614.1a)
        if (Mh2.CREATE_CLUE_FOOD_TREASURE_INSTEAD_ONE_OF_EACH.matches(line)) {
            val kinds = listOf("Clue", "Food", "Treasure")
            return mh2SelfStatic(Mechanic.Replacement(EventPattern.CreateToken(Filters.all(
                ObjectFilter.Or(kinds.map { ObjectFilter.Sub(arcanum.api.SubtypeRef.Literal(Subtype(it))) }), ObjectFilter.ControlledBy(PlayerFilter.You))),
                modify = listOf(Modification.CreateInstead(arcanum.api.TokenSpec.Predefined("Clue"))) +
                    kinds.drop(1).map { Modification.AlsoCreate(arcanum.api.TokenSpec.Predefined(it), Value.EventAmount) }))
        }
        // mh2 chunk 13: "Domain — This spell costs {2} less to cast for each basic land type among lands you control." (CR 601.2f)
        Mh2.SPELL_COSTS_LESS_FOR_EACH_BASIC_LAND_TYPE.matchEntire(line)?.let { m ->
            return mh2SelfStatic(Mechanic.CostChange(ObjectFilter.Is(Objects.Self), arcanum.api.CostChange.Less(ManaCost.parse(m.groupValues[1]) ?: return@let,
                Mh2Phrases.value("the number of basic land types among lands you control", null) ?: return@let)))
        }
        // mh2 chunk 13: "This creature doesn't untap during your untap step if it has a +1/+1 counter on it."
        Mh2.DOESNT_UNTAP_IF_HAS_COUNTER.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            return Ability.Static(listOf(Mechanic.DoesntUntap), affects = Affected.Objects(Objects.Self),
                condition = arcanum.api.Condition.ObjectMatches(Objects.Self, ObjectFilter.HasCounter(Counters.kind(m.groupValues[2]) ?: return@let, atLeast = 1)))
        }
        // mh2 chunk 13: "Imprint — As this Vehicle enters, exile a creature card from a graveyard." (the card kept as this permanent's memory, CR 607.2a)
        Mh2.AS_ENTERS_EXILE_A_CARD_FROM_A_GRAVEYARD.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val noun = Filters.noun(m.groupValues[2]) ?: return@let
            // "a graveyard": any player's, so the owner is named
            val exile = CostPart.Exile(CostObjects.Choose(Filters.all(noun, ObjectFilter.InZone(Zone.Graveyard), ObjectFilter.OwnedBy(arcanum.api.PlayerFilter.Any)), count = Value.Fixed(1)), from = Zone.Graveyard,
                postBind = "exiled", remember = EXILED_WITH)
            return mh2SelfStatic(Mechanic.Replacement(EventPattern.ZoneChange(ObjectFilter.Is(Objects.Self), to = Zone.Battlefield), modify = listOf(Modification.AsEnters(listOf(
                Step.Pay(Cost(listOf(exile)), payer = Players.You, mandatory = true, bind = "paid"))))))
        }
        // mh2 chunk 12: "Territorial Kavu's power and toughness are each equal to the number of basic land types among lands you control." (CR 604.3)
        Mh2.PT_EACH_EQUAL_TO.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            // inr chunk 03: "… equal to the number of A in your graveyard plus the number of B you own in exile" (a sum of counts, CR 604.3)
            val value = Mh2Phrases.value(m.groupValues[2], null) ?: m.groupValues[2].split(" plus the number of ").takeIf { it.size > 1 }?.let { parts ->
                Value.Sum(parts.mapIndexed { i, part ->
                    val noun = if (i == 0) part.removePrefix("the number of ") else part
                    // "cards with flashback you own in exile": the cards cast with flashback end there (CR 702.34a)
                    if (noun == "cards with flashback you own in exile")
                        Value.Count(Objects.Each(Filters.all(ObjectFilter.Category(arcanum.api.ObjectCategory.Card), ObjectFilter.HasKeyword(arcanum.api.Keyword.Flashback.Kind),
                            ObjectFilter.InZone(Zone.Exile), ObjectFilter.OwnedBy(PlayerFilter.You))))
                    else Value.Count(Filters.objects(noun) ?: return@let null)
                })
            } ?: return@let
            return Ability.Static(listOf(Mechanic.SetPowerToughness(value, value)), affects = Affected.Objects(Objects.Self), characteristicDefining = true)
        }
        // mh2 chunk 12: "You can't cast more than one spell each turn." (CR 101.2: none once one was cast this turn)
        if (Mh2.CANT_CAST_MORE_THAN_ONE_SPELL_EACH_TURN.matches(line))
            return Ability.Static(listOf(Mechanic.CantCast(ObjectFilter.Any)), affects = Affected.Players(Players.You),
                condition = arcanum.api.Condition.HappenedThisTurn(EventPattern.Cast(ObjectFilter.Any, PlayerFilter.You), atLeast = 1, measure = arcanum.api.Measure.Events))
        // mh2 chunk 12: "As long as Grist isn't on the battlefield, it's a 1/1 Insect creature in addition to its other types." (works in every other
        // zone, CR 113.6b)
        Mh2.AS_LONG_AS_NOT_ON_BATTLEFIELD_ITS_A_CREATURE.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            if (m.groupValues[4] !in RulesWords.subtypes) return@let
            return Ability.Static(listOf(Mechanic.SetTypes(add = listOf(CardType.Creature), addSubtypes = listOf(arcanum.api.SubtypeRef.Literal(Subtype(m.groupValues[4])))),
                Mechanic.SetPowerToughness(Value.Fixed(m.groupValues[2].toInt()), Value.Fixed(m.groupValues[3].toInt()))), affects = Affected.Objects(Objects.Self),
                condition = arcanum.api.Condition.Not(arcanum.api.Condition.ObjectMatches(Objects.Self, ObjectFilter.InZone(Zone.Battlefield))),
                functionsIn = listOf(Zone.Library, Zone.Hand, Zone.Graveyard, Zone.Exile, Zone.Stack, Zone.Command))
        }
        // mh2 chunk 11: "Planeswalkers' loyalty abilities you activate cost an additional [+1] to activate." (CR 606.4)
        Mh2.LOYALTY_ABILITIES_COST_ADDITIONAL.matchEntire(line)?.let { m ->
            return Ability.Static(listOf(Mechanic.AdditionalLoyaltyCost(m.groupValues[1].toInt())), affects = Affected.Players(Players.You))
        }
        // mh2 chunk 11: "Each spell you cast that's red or green costs {1} less to cast." (CR 601.2f)
        Mh2.EACH_SPELL_YOU_CAST_THATS_COSTS_LESS.matchEntire(line)?.let { m ->
            val colors = ObjectFilter.Or(listOf(mh2Color(m.groupValues[1]) ?: return@let, mh2Color(m.groupValues[2]) ?: return@let))
            return mh2SelfStatic(Mechanic.CostChange(Filters.all(ObjectFilter.Category(arcanum.api.ObjectCategory.Spell), colors, ObjectFilter.ControlledBy(PlayerFilter.You)),
                arcanum.api.CostChange.Less(ManaCost.parse(m.groupValues[3]) ?: return@let, Value.Fixed(1))))
        }
        // mh2 chunk 10: "This spell costs {3} less to cast for each other spell cast this turn." (by any player, CR 601.2f)
        Mh2.COSTS_LESS_FOR_EACH_OTHER_SPELL_CAST_THIS_TURN.matchEntire(line)?.let { m ->
            val per = ManaCost.parse(m.groupValues[1]) ?: return@let
            return mh2SelfStatic(Mechanic.CostChange(ObjectFilter.Is(Objects.Self), arcanum.api.CostChange.Less(per,
                Value.EventsThisTurn(EventPattern.Cast(ObjectFilter.Not(ObjectFilter.Is(Objects.Self)), PlayerFilter.Any), arcanum.api.Measure.Events))))
        }
        // mh2 chunk 10: "Thrasta has hexproof as long as it entered this turn."
        Mh2.HAS_AS_LONG_AS_IT_ENTERED_THIS_TURN.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val keyword = OracleParser.keyword(m.groupValues[2].replaceFirstChar { it.uppercase() }) ?: return@let
            return Ability.Static(listOf(Mechanic.GainAbilities(listOf(keyword))), affects = Affected.Objects(Objects.Self),
                condition = arcanum.api.Condition.ObjectMatches(Objects.Self, ObjectFilter.ThisTurn(EventPattern.ZoneChange(ObjectFilter.Is(Objects.Self), to = Zone.Battlefield))))
        }
        // mh2 chunk 09: "Squirrels you control get +1/+1 for each acorn counter on this artifact." (layer 7c)
        Mh2.GET_PT_FOR_EACH_COUNTER_ON_SELF.matchEntire(line)?.takeIf { isSelf(it.groupValues[5]) }?.let { m ->
            val objects = Filters.objects(m.groupValues[1].replaceFirstChar { it.lowercase() }.let { p -> p.substringBefore(' ').removeSuffix("s") + " " + p.substringAfter(' ') })
                ?: Filters.objects(m.groupValues[1]) ?: return@let
            val kind = Counters.kind(m.groupValues[4]) ?: return@let
            val per = Value.Of(arcanum.api.NumericProperty.Counters(kind), Objects.Self, arcanum.api.Combine.Single)
            fun times(n: Int) = if (n == 1) per else Value.Times(per, n)
            return Ability.Static(listOf(Mechanic.ModifyPowerToughness(times(m.groupValues[2].toInt()), times(m.groupValues[3].toInt()))), affects = Affected.Objects(objects))
        }
        // mh2 chunk 09: "Aeve isn't legendary if it's a token." (CR 205.4)
        Mh2.ISNT_LEGENDARY_IF_TOKEN.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            return Ability.Static(listOf(Mechanic.SetTypes(removeSupertypes = listOf(Supertype.Legendary))), affects = Affected.Objects(Objects.Self),
                condition = arcanum.api.Condition.ObjectMatches(Objects.Self, ObjectFilter.Category(arcanum.api.ObjectCategory.Token)))
        }
        // mh2 chunk 09: "This creature enters with two +1/+1 counters on it for each color of mana spent to cast it." (converge, CR 601.2h)
        Mh2.ENTERS_WITH_N_COUNTERS_FOR_EACH_COLOR_SPENT.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val n = Numbers.count(m.groupValues[2]) ?: return@let
            val kind = Counters.kind(m.groupValues[3]) ?: return@let
            val spent = Value.ManaSpent(distinctColors = true, of = Objects.Self)
            return mh2SelfStatic(Mechanic.Replacement(EventPattern.ZoneChange(ObjectFilter.Is(Objects.Self), to = Zone.Battlefield),
                modify = listOf(Modification.EntersWithCounters(kind, if (n == 1) spent else Value.Times(spent, n)))))
        }
        // mh2 chunk 07: "This creature enters with a +1/+1 counter on it for each time it was kicked." (multikicker, CR 702.33g; CR 614.1c)
        Mh2.ENTERS_WITH_COUNTER_FOR_EACH_TIME_KICKED.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val kind = Counters.kind(m.groupValues[2]) ?: return@let
            return mh2SelfStatic(Mechanic.Replacement(EventPattern.ZoneChange(ObjectFilter.Is(Objects.Self), to = Zone.Battlefield),
                modify = listOf(Modification.EntersWithCounters(kind, Value.TimesPaid(arcanum.api.Keyword.Kicker.Kind, Objects.Self)))))
        }
        // mh2 chunk 06: "This creature escapes with your choice of a +1/+1 counter or a flying counter on it." (only if it escaped, CR 702.138c)
        Mh2.ESCAPES_WITH_CHOICE_OF_COUNTERS.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val first = Counters.kind(m.groupValues[2]) ?: return@let
            val second = Counters.kind(m.groupValues[3]) ?: return@let
            val a = "a ${m.groupValues[2]} counter"
            val b = "a ${m.groupValues[3]} counter"
            return Ability.Static(listOf(Mechanic.Replacement(EventPattern.ZoneChange(ObjectFilter.Is(Objects.Self), to = Zone.Battlefield), modify = listOf(
                Modification.AsEnters(listOf(
                    Step.Choose(arcanum.api.Choice.Option(listOf(a, b)), bind = "counter", chooser = Players.You),
                    Step.If(arcanum.api.Condition.Chose("counter", a), then = listOf(Step.Modify(Modification.EntersWithCounters(first, Value.Fixed(1)))),
                        otherwise = listOf(Step.Modify(Modification.EntersWithCounters(second, Value.Fixed(1)))))))))),
                condition = arcanum.api.Condition.Paid(arcanum.api.Keyword.Escape.Kind, times = 1, of = Objects.Self), affects = Affected.Objects(Objects.Self))
        }
        // mh2 chunk 05: "If a card would be put into an opponent's graveyard from anywhere, instead exile it with a void counter on it." (CR 614.1a,
        // 122.1)
        Mh2.CARD_TO_OPPONENTS_GRAVEYARD_EXILE_WITH_COUNTER.matchEntire(line)?.let { m ->
            val kind = Counters.kind(m.groupValues[1]) ?: return@let
            return mh2SelfStatic(Mechanic.Replacement(EventPattern.ZoneChange(Filters.all(ObjectFilter.Category(arcanum.api.ObjectCategory.Card),
                ObjectFilter.OwnedBy(PlayerFilter.Opponent)), to = Zone.Graveyard),
                modify = listOf(Modification.ChangeDestination(Destination(Zone.Exile, counters = listOf(arcanum.api.CountersToPut(kind, Value.Fixed(1))))))))
        }
        // mh2 chunk 03: "Creatures lose all abilities." (layer 6, CR 613.1f)
        Mh2.LOSE_ALL_ABILITIES.matchEntire(line)?.let { m ->
            val objects = Filters.objects(m.groupValues[1].replaceFirstChar { it.lowercase() }.removeSuffix("s")) ?: return@let
            return Ability.Static(listOf(Mechanic.LoseAbilities()), affects = Affected.Objects(objects))
        }
        // mh2 chunk 03: "This creature enters with a +1/+1 counter on it for each instant and sorcery card exiled with it." (the cards
        // exiled to pay for delve, CR 702.66a; CR 614.1c)
        Mh2.ENTERS_WITH_COUNTER_FOR_EACH_EXILED_WITH_IT.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val kind = Counters.kind(m.groupValues[2]) ?: return@let
            val cards = Filters.noun(m.groupValues[3].replace(" and ", " or ")) ?: return@let
            val exiled = Objects.Where(Objects.PaidWith(arcanum.api.ManaPaymentWay.ExileFromGraveyard, Objects.Self), cards)
            return mh2SelfStatic(Mechanic.Replacement(EventPattern.ZoneChange(ObjectFilter.Is(Objects.Self), to = Zone.Battlefield),
                modify = listOf(Modification.EntersWithCounters(kind, Value.Count(exiled)))))
        }
        // mh2 chunk 02: "If a black or red permanent, spell, or card not on the battlefield would be put into a graveyard, exile it instead." (any
        // object of those colours, CR 614.1a)
        Mh2.TWO_COLORS_WOULD_BE_PUT_INTO_GRAVEYARD_EXILE.matchEntire(line)?.let { m ->
            val colors = ObjectFilter.Or(listOf(mh2Color(m.groupValues[1]) ?: return null, mh2Color(m.groupValues[2]) ?: return null))
            return mh2SelfStatic(Mechanic.Replacement(EventPattern.ZoneChange(colors, to = Zone.Graveyard),
                modify = listOf(Modification.ChangeDestination(Destination(Zone.Exile)))))
        }
        // mh2 chunk 02: "As this creature enters, choose a card type." (CR 614.12, 607.2d)
        Mh2.AS_ENTERS_CHOOSE_CARD_TYPE.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            return mh2SelfStatic(Mechanic.Replacement(EventPattern.ZoneChange(ObjectFilter.Is(Objects.Self), to = Zone.Battlefield), modify = listOf(
                Modification.AsEnters(listOf(Step.Choose(arcanum.api.Choice.CardType(), bind = CHOSEN_TYPE, chooser = Players.You, remember = true))))))
        }
        return null
    }

    /** mh2: trigger events. */
    private fun mh2Trigger(text: String): Pair<arcanum.api.Trigger.On, arcanum.api.Condition?>? {
        // mh2 chunk 13: "this creature deals combat damage to a creature"
        Mh2.DEALS_COMBAT_DAMAGE_TO_A_CREATURE.matchEntire(text)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            return arcanum.api.Trigger.On(EventPattern.Damage(ObjectFilter.Is(Objects.Self), arcanum.api.RecipientFilter(objects = ObjectFilter.Type(CardType.Creature)),
                combat = true)) to null
        }
        // mh2 chunk 11: "Carth enters or a planeswalker you control dies" (one ability, two events, CR 603.2)
        Mh2.SELF_ENTERS_OR_DIES.matchEntire(text)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val noun = Filters.noun(m.groupValues[2].removePrefix("a ").removePrefix("an ")) ?: return@let
            return arcanum.api.Trigger.On(listOf(EventPattern.ZoneChange(ObjectFilter.Is(Objects.Self), to = Zone.Battlefield),
                EventPattern.ZoneChange(noun, from = Zone.Battlefield, to = Zone.Graveyard))) to null
        }
        // mh2 chunk 08: "you win a coin flip" (CR 705.2)
        if (Mh2.YOU_WIN_A_COIN_FLIP.matches(text)) return arcanum.api.Trigger.On(EventPattern.FlipCoin(PlayerFilter.You, won = true)) to null
        // mh2 chunk 07: "you cast a spell other than your first spell each turn" (every spell but the first one that player cast this turn)
        if (Mh2.SPELL_OTHER_THAN_FIRST_EACH_TURN.matches(text))
            return arcanum.api.Trigger.On(EventPattern.Cast(ObjectFilter.Not(ObjectFilter.NthSpellThisTurn(ObjectFilter.Any, 1)), PlayerFilter.You)) to null
        // mh2 chunk 05: "this creature exploits a creature" (CR 702.110b)
        Mh2.EXPLOITS_A_CREATURE.matchEntire(text)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            return arcanum.api.Trigger.On(EventPattern.Exploits(ObjectFilter.Is(Objects.Self))) to null
        }
        // mh2 chunk 03: "this creature becomes the target of a spell or ability" (any spell or ability, CR 115.10)
        Mh2.BECOMES_THE_TARGET_OF_A_SPELL_OR_ABILITY.matchEntire(text)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            return arcanum.api.Trigger.On(EventPattern.BecomesTarget(ObjectFilter.Is(Objects.Self), by = ObjectFilter.Any)) to null
        }
        return null
    }

    /** mh2: cost parts. */
    private fun mh2CostPart(text: String): List<CostPart>? {
        // mh2 chunk 01: "Remove X +1/+1 counters from this creature" (X announced as it is activated, CR 107.3a)
        Mh2.REMOVE_X_COUNTERS_FROM_SELF.matchEntire(text)?.takeIf { isSelf(it.groupValues[2]) }?.let { m ->
            val kind = Counters.kind(m.groupValues[1]) ?: return null
            return listOf(CostPart.RemoveCounters(kind, Value.Announced(name = "X"), from = CostObjects.Self))
        }
        // mh2 chunk 02: "Reveal this card from your hand" (forecast, CR 702.57a)
        Mh2.REVEAL_SELF_FROM_HAND.matchEntire(text)?.takeIf { isSelf(it.groupValues[1]) }?.let { return listOf(CostPart.Reveal(CostObjects.Self)) }
        return null
    }

    /** mh2: instructions of several sentences read as a whole. */
    private fun mh2Whole(text: String, context: Context): List<Step>? {
        // mh2 chunk 11: "Choose a card name that hasn't been chosen from among A, B, …, and F. Create a copy of the card with the chosen name. You may
        // cast the copy." The copy is made in exile from the card the host supplies (CR 707.12), then may be cast, paying its costs
        Mh2.CHOOSE_NAME_UNCHOSEN_COPY_MAY_CAST.matchEntire(text)?.let { m ->
            val names = m.groupValues[1].split(", ") + m.groupValues[2]
            return listOf(
                Step.Choose(arcanum.api.Choice.CardNameAmong(names, unchosen = true), bind = "name", chooser = Players.You),
                Step.Do(Effect.CopyNamedCard("name", Players.You, bind = "copy")),
                Step.May(listOf(Step.Do(Effect.Cast(Objects.Bound("copy"), arcanum.api.PlayKind.Cast, caster = Players.You))), player = Players.You),
            )
        }
        // mh2 chunk 16: "This land becomes a 2/2 Assembly-Worker artifact creature until end of turn. It's still a land." (layer 4, 7b)
        Mh2.BECOMES_PT_SUBTYPE_ARTIFACT_CREATURE_STILL_LAND.matchEntire(text)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val subtypes = m.groupValues[4].split(' ').map { if (it in RulesWords.subtypes) arcanum.api.SubtypeRef.Literal(Subtype(it)) else return null }
            return listOf(mh2UntilEndOfTurn(Objects.Self, Mechanic.SetTypes(add = listOf(CardType.Artifact, CardType.Creature), addSubtypes = subtypes),
                Mechanic.SetPowerToughness(Value.Fixed(m.groupValues[2].toInt()), Value.Fixed(m.groupValues[3].toInt()))))
        }
        // mh2 chunk 15: "Each player chooses a creature type. Each player returns all creature cards of a type chosen this way from their graveyard to
        // the battlefield." (in turn order, CR 101.4; each puts their own cards onto the battlefield)
        Mh2.EACH_PLAYER_CHOOSES_CREATURE_TYPE_RETURNS.matchEntire(text)?.let { m ->
            val noun = Filters.noun(m.groupValues[1]) ?: return null
            val player = Players.Bound("player")
            val everyone = arcanum.api.Each.Players(Players.Each(PlayerFilter.Any))
            return listOf(Step.ForEach(everyone, "player", listOf(Step.Choose(arcanum.api.Choice.CreatureType, bind = "type", chooser = player)), together = true),
                Objects.Each(Filters.all(noun, ObjectFilter.Sub(arcanum.api.SubtypeRef.Chosen("type")), ObjectFilter.InZone(Zone.Graveyard))).let { cards ->
                    Step.Do(Effect.Move(cards, Destination(Zone.Battlefield, controller = Players.OwnerOf(cards)))) })
        }
        // mh2 chunk 13: "exile up to one target creature you own, then search your library for a basic land card. Put both cards onto the battlefield
        // under your control, then shuffle." (one event, CR 608.2c)
        Mh2.EXILE_UP_TO_ONE_YOU_OWN_THEN_SEARCH_PUT_BOTH.matchEntire(text)?.let { m ->
            val noun = Filters.noun(m.groupValues[1]) ?: return null
            val searched = Filters.noun(m.groupValues[2]) ?: return null
            val name = mh2NewSlotName(context, Filters.slotName(m.groupValues[1]))
            context.targets += mh2Slot(name, Filters.all(noun, ObjectFilter.OwnedBy(PlayerFilter.You)), min = 0)
            return listOf(Step.Do(Effect.Move(Objects.Target(name), Destination(Zone.Exile), postBind = "exiled")),
                Step.Do(Effect.Search(Players.You, searched, max = Value.Fixed(1), zones = listOf(Zone.Library), bind = "found", searcher = Players.You)),
                Step.Do(Effect.Move(Objects.Union(listOf(Objects.Bound("exiled"), Objects.Bound("found"))), Destination(Zone.Battlefield, controller = Players.You))),
                Step.Do(Effect.Shuffle(Players.You)))
        }
        // mh2 chunk 12: "Look at the top four cards of your library. Put one of them into your hand and the rest on the bottom of your library in a
        // random order."
        Mh2.LOOK_TOP_ONE_HAND_REST_BOTTOM.matchEntire(text)?.let { m ->
            val count = Numbers.count(m.groupValues[1]) ?: return null
            return listOf(Step.Do(Effect.LookAt(Objects.LibraryCards(Players.You, Value.Fixed(count), fromTop = true), Players.You, bind = "seen")),
                Step.Choose(arcanum.api.Choice.Objects(ObjectFilter.Any, Value.Fixed(1), Value.Fixed(1), from = Objects.Bound("seen")), bind = "kept", chooser = Players.You),
                Step.Do(Effect.Move(Objects.Bound("kept"), Destination(Zone.Hand))),
                Step.Do(Effect.Move(Objects.Except(Objects.Bound("seen"), Objects.Bound("kept")), Destination(Zone.Library, libraryPosition = -1, randomOrder = true))))
        }
        // mh2 chunk 12: "Create a 1/1 black and green Insect creature token, then mill a card. If an Insect card was milled this way, put a loyalty
        // counter on Grist and repeat this process." (CR 608.2c)
        Mh2.CREATE_THEN_MILL_IF_MILLED_COUNTER_REPEAT.matchEntire(text)?.takeIf { isSelf(it.groupValues[4]) }?.let { m ->
            val created = effect("Create ${m.groupValues[1]}.", context) ?: return null
            val kind = Counters.kind(m.groupValues[3]) ?: return null
            if (m.groupValues[2] !in RulesWords.subtypes) return null
            // the milled card, wherever it went
            val milledOne = arcanum.api.Condition.ObjectMatches(Objects.Bound("milled"), ObjectFilter.Sub(arcanum.api.SubtypeRef.Literal(Subtype(m.groupValues[2]))))
            return listOf(Step.RepeatWhile(created + listOf(Step.Do(Effect.Mill(Players.You, Value.Fixed(1), postBind = "milled")),
                Step.If(milledOne, then = listOf(Step.Do(Effect.PutCounters(Objects.Self, kind, Value.Fixed(1)))))), milledOne))
        }
        // mh2 chunk 12: "Choose a number between 1 and 5. Flip that many coins. For each flip you win, draw a card. For each flip you lose, Yusri deals
        // 2 damage to you. If you won five flips this way, you may cast spells from your hand this turn without paying their mana costs." (CR 705)
        Mh2.CHOOSE_NUMBER_FLIP_THAT_MANY.matchEntire(text)?.takeIf { isSelf(it.groupValues[3]) }?.let { m ->
            val flips = "flips"
            val all = Numbers.count(m.groupValues[5]) ?: return null
            return listOf(Step.Choose(arcanum.api.Choice.Number(Value.Fixed(m.groupValues[1].toInt()), Value.Fixed(m.groupValues[2].toInt())), bind = "number", chooser = Players.You),
                Step.Do(Effect.FlipCoin(Players.You, bind = flips, count = Value.Bound("number"))),
                Step.Do(Effect.Draw(Players.You, Value.FlipsWon(flips))),
                Step.Do(Effect.DealDamage(Recipients(players = Players.You), Value.Times(Value.FlipsLost(flips), m.groupValues[4].toInt()), Objects.Self)),
                Step.If(arcanum.api.Condition.Compare(Value.FlipsWon(flips), arcanum.api.Comparison.AtLeast, Value.Fixed(all)), then = listOf(
                    Step.Do(Effect.ApplyMechanics(listOf(Mechanic.MayPlay(Zone.Hand, PlayKind.Cast, withoutPaying = true, holder = PlayerFilter.You)),
                        Affected.Objects(Objects.Each(Filters.all(ObjectFilter.InZone(Zone.Hand), ObjectFilter.OwnedBy(PlayerFilter.You)))), arcanum.api.Duration.EndOfTurn)))))
        }
        // mh2 chunk 11: "Look at the top seven cards of your library. You may reveal a planeswalker card from among them and put it into your hand. Put
        // the rest on the bottom of your library in a random order."
        Mh2.LOOK_TOP_MAY_REVEAL_PUT_INTO_HAND_REST_BOTTOM.matchEntire(text)?.let { m ->
            val count = Numbers.count(m.groupValues[1]) ?: return null
            val noun = Filters.noun(m.groupValues[2] + " card") ?: return null
            val seen = Objects.Bound("seen")
            val chosen = Objects.Bound("chosen")
            return listOf(Step.Do(Effect.LookAt(Objects.LibraryCards(Players.You, Value.Fixed(count), fromTop = true), Players.You, bind = "seen")),
                Step.Choose(arcanum.api.Choice.Objects(noun, Value.Fixed(0), Value.Fixed(1), from = seen), bind = "chosen", chooser = Players.You),
                Step.Do(Effect.Reveal(chosen)),
                Step.Do(Effect.Move(chosen, Destination(Zone.Hand))),
                Step.Do(Effect.Move(Objects.Except(seen, chosen), Destination(Zone.Library, libraryPosition = -1, randomOrder = true))))
        }
        // mh2 chunk 11: "Reveal the top two cards of your library. Put one of them into your hand and the other into your graveyard. If you put an
        // artifact card into your hand this way, you gain 3 life."
        Mh2.REVEAL_TOP_TWO_ONE_HAND_OTHER_GRAVEYARD_IF.matchEntire(text)?.let { m ->
            val noun = Filters.noun(m.groupValues[1]) ?: return null
            val then = effect(m.groupValues[2].replaceFirstChar { it.uppercase() }, context) ?: return null
            val revealed = Objects.Bound("revealed")
            val kept = Objects.Bound("kept")
            return listOf(Step.Do(Effect.Reveal(Objects.LibraryCards(Players.You, Value.Fixed(2), fromTop = true), bind = "revealed")),
                Step.Choose(arcanum.api.Choice.Objects(ObjectFilter.Any, Value.Fixed(1), Value.Fixed(1), from = revealed), bind = "kept", chooser = Players.You),
                Step.Do(Effect.Move(kept, Destination(Zone.Hand))),
                Step.Do(Effect.Move(Objects.Except(revealed, kept), Destination(Zone.Graveyard))),
                Step.If(arcanum.api.Condition.ObjectMatches(kept, noun), then = then))
        }
        // mh2 chunk 09: "Choose land or nonland. Reveal cards from the top of your library until you reveal a card of the chosen kind. Put that card
        // into your hand and the rest on the bottom of your library in a random order." (CR 701.20a)
        if (Mh2.CHOOSE_LAND_OR_NONLAND_REVEAL_UNTIL.matches(text)) {
            val land = ObjectFilter.Type(CardType.Land)
            fun until(filter: ObjectFilter) = Step.Do(Effect.RevealUntil(filter, Players.You, Value.Fixed(1), reveal = true, foundBind = "found", restBind = "rest"))
            return listOf(Step.Choose(arcanum.api.Choice.Option(listOf("land", "nonland")), bind = "kind", chooser = Players.You),
                Step.If(arcanum.api.Condition.Chose("kind", "land"), then = listOf(until(land)), otherwise = listOf(until(ObjectFilter.Not(land)))),
                Step.Do(Effect.Move(Objects.Bound("found"), Destination(Zone.Hand))),
                Step.Do(Effect.Move(Objects.Bound("rest"), Destination(Zone.Library, libraryPosition = -1, randomOrder = true))))
        }
        // mh2 chunk 08: "You may discard a card. When you do, [effect]" when the effect reads the discarded card (directly or by an X "where X is"
        // defines from it): a reflexive trigger, CR 603.12
        Mh2.MAY_DISCARD_WHEN_YOU_DO.matchEntire(text)?.takeIf { it.groupValues[1].contains("the discarded card") || it.groupValues[1].contains(" X ") }?.let { m ->
            val reflexive = instructions(m.groupValues[1].replaceFirstChar { it.uppercase() }) ?: return null
            return listOf(Step.Pay(Cost(listOf(CostPart.Discard(CostObjects.Choose(ObjectFilter.Category(arcanum.api.ObjectCategory.Card), count = Value.Fixed(1)),
                preBind = "discarded"))), payer = Players.You, bind = "paid"),
                Step.If(arcanum.api.Condition.Did("paid"), then = listOf(Step.Do(Effect.ReflexiveTrigger(reflexive)))))
        }
        // mh2 chunk 08: "Create a Treasure token and exile the top card of that player's library. Until end of turn, you may cast that card." (that
        // player: the one dealt combat damage)
        if (Mh2.TREASURE_AND_EXILE_TOP_OF_THAT_PLAYERS_LIBRARY_MAY_CAST.matches(text))
            return listOf(Step.Do(Effect.CreateToken(arcanum.api.TokenSpec.Predefined("Treasure"), Value.Fixed(1), Players.You)),
                Step.Do(Effect.Move(Objects.LibraryCards(Players.EventPlayer, Value.Fixed(1), fromTop = true), Destination(Zone.Exile), postBind = "exiled")),
                Step.Do(Effect.ApplyMechanics(listOf(Mechanic.MayPlay(Zone.Exile, PlayKind.Cast, holder = PlayerFilter.You)),
                    Affected.Objects(Objects.Bound("exiled")), arcanum.api.Duration.EndOfTurn)))
        // mh2 chunk 08: "Flip three coins. For each flip you win, create a 1/1 red Goblin creature token that's tapped and attacking." (CR 705, 508.4)
        Mh2.FLIP_COINS_FOR_EACH_WIN_CREATE.matchEntire(text)?.let { m ->
            val count = Numbers.count(m.groupValues[1]) ?: return null
            val created = effect("Create ${m.groupValues[2]}.", context) ?: return null
            val create = (created.singleOrNull() as? Step.Do)?.effect as? Effect.CreateToken ?: return null
            return listOf(Step.Repeat(Value.Fixed(count), listOf(Step.Do(Effect.FlipCoin(Players.You, bind = "flip")),
                Step.If(arcanum.api.Condition.WonFlip("flip"), then = listOf(Step.Do(create.copy(tapped = true, attacking = arcanum.api.AttackTarget.Chosen)))))))
        }
        // mh2 chunk 08: "Shuffle all permanents you own into your library, then reveal that many cards …" (CR 701.24a; Auras put onto the battlefield
        // are attached as they enter, CR 303.4f)
        if (Mh2.SHUFFLE_PERMANENTS_REVEAL_THAT_MANY_PUT_NON_AURA_THEN_AURA.matches(text)) {
            val revealed = Objects.Bound("revealed")
            val aura = ObjectFilter.Sub(arcanum.api.SubtypeRef.Literal(Subtype("Aura")))
            val permanentCard = Filters.noun("permanent card") ?: return null
            return listOf(Step.Do(Effect.Move(Objects.Each(Filters.all(ObjectFilter.Category(arcanum.api.ObjectCategory.Permanent), ObjectFilter.OwnedBy(PlayerFilter.You))),
                Destination(Zone.Library), postBind = "shuffled")),
                Step.Do(Effect.Shuffle(Players.You)),
                Step.Do(Effect.Reveal(Objects.LibraryCards(Players.You, Value.Count(Objects.Bound("shuffled")), fromTop = true), bind = "revealed")),
                Step.Do(Effect.Move(Objects.Where(revealed, Filters.all(permanentCard, ObjectFilter.Not(aura))), Destination(Zone.Battlefield))),
                Step.Do(Effect.Move(Objects.Where(revealed, aura), Destination(Zone.Battlefield))),
                Step.Do(Effect.Move(Objects.Where(revealed, ObjectFilter.InZone(Zone.Library)), Destination(Zone.Library, libraryPosition = -1, randomOrder = true))))
        }
        // mh2 chunk 07: "Exile the top card of your library. During your next turn, you may play that card." (the permission begins with your next
        // turn: a delayed trigger at its upkeep, CR 603.7)
        if (Mh2.EXILE_TOP_DURING_YOUR_NEXT_TURN_MAY_PLAY.matches(text))
            return listOf(Step.Do(Effect.Move(Objects.LibraryCards(Players.You, Value.Fixed(1), fromTop = true), Destination(Zone.Exile), postBind = "exiled")),
                Step.Do(Effect.CreateDelayedTrigger(arcanum.api.Trigger.On(EventPattern.StepBegins(arcanum.api.TurnStep.Upkeep, PlayerFilter.You)),
                    Instructions(steps = listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.MayPlay(Zone.Exile, PlayKind.Play, holder = PlayerFilter.You)),
                        Affected.Objects(Objects.Bound("exiled")), arcanum.api.Duration.EndOfTurn)))), laterTurn = true)))
        // mh2 chunk 07: "Gain control of target spell that targets only a single permanent or player. Copy it, then reselect the targets at random for
        // the spell and the copy. The new targets can't be you or a permanent you control." (CR 115.7)
        Mh2.GAIN_CONTROL_OF_SPELL_COPY_RESELECT_AT_RANDOM.matchEntire(text)?.let { m ->
            val noun = Filters.noun(m.groupValues[1]) ?: return null
            val name = mh2NewSlotName(context, "spell")
            context.targets += mh2Slot(name, noun)
            val spell = Objects.Target(name)
            return listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.ControlledBy(Players.You)), Affected.Objects(spell), arcanum.api.Duration.Indefinitely)),
                Step.Do(Effect.CopySpell(spell, Players.You, newTargets = false, bind = "copy")),
                Step.Do(Effect.ChangeTargets(Objects.Union(listOf(spell, Objects.Bound("copy"))), Players.You, optional = false, atRandom = true,
                    notTo = arcanum.api.RecipientFilter(objects = Filters.all(ObjectFilter.Category(arcanum.api.ObjectCategory.Permanent), ObjectFilter.ControlledBy(PlayerFilter.You)),
                        players = PlayerFilter.You))))
        }
        // mh2 chunk 07: "Reveal cards from the top of your library until you reveal a nonland card. Put the revealed cards on the bottom of your
        // library in a random order. When you reveal a nonland card this way, … deals damage equal to that card's mana value to any target."
        // (a reflexive trigger, CR 603.12)
        Mh2.REVEAL_UNTIL_NONLAND_BOTTOM_WHEN_YOU_REVEAL_DEALS_MV.matchEntire(text)?.takeIf { isSelf(it.groupValues[2]) }?.let { m ->
            val noun = Filters.noun(m.groupValues[1]) ?: return null
            val any = TargetSlot("any", TargetKind.Either(ObjectFilter.Or(listOf(ObjectFilter.Type(CardType.Creature), ObjectFilter.Type(CardType.Planeswalker),
                ObjectFilter.Type(CardType.Battle))), PlayerFilter.Any), min = Value.Fixed(1), max = Value.Fixed(1))
            return listOf(Step.Do(Effect.RevealUntil(noun, Players.You, Value.Fixed(1), reveal = true, foundBind = "found", restBind = "rest")),
                Step.Do(Effect.Move(Objects.Union(listOf(Objects.Bound("found"), Objects.Bound("rest"))), Destination(Zone.Library, libraryPosition = -1, randomOrder = true))),
                Step.If(arcanum.api.Condition.NonEmpty("found"), then = listOf(Step.Do(Effect.ReflexiveTrigger(Instructions(targets = listOf(any), steps = listOf(
                    Step.Do(Effect.DealDamage(Recipients(target = "any"), Value.Of(arcanum.api.NumericProperty.ManaValue, Objects.Bound("found"), arcanum.api.Combine.Single),
                        Objects.Self)))))))))
        }
        // mh2 chunk 06: "Target opponent reveals their hand. You choose a card from it. That player discards that card, then discards a card at random."
        if (Mh2.REVEALS_HAND_CHOOSE_CARD_DISCARDS_THEN_AT_RANDOM.matches(text)) {
            context.targets += TargetSlot("opponent", TargetKind.Players(PlayerFilter.Opponent), min = Value.Fixed(1), max = Value.Fixed(1))
            val opponent = Players.Target("opponent")
            return listOf(Step.Do(Effect.Reveal(Objects.Each(Filters.all(ObjectFilter.InZone(Zone.Hand), ObjectFilter.OwnedBy(PlayerFilter.Is(opponent)))), bind = "revealed")),
                Step.Choose(arcanum.api.Choice.Objects(ObjectFilter.Any, Value.Fixed(1), Value.Fixed(1), from = Objects.Bound("revealed")), bind = "chosen", chooser = Players.You),
                Step.Do(Effect.Discard(opponent, Value.Fixed(1), ObjectFilter.Any, objects = Objects.Bound("chosen"))),
                Step.Do(Effect.Discard(opponent, Value.Fixed(1), ObjectFilter.Any, random = true)))
        }
        // mh2 chunk 05: "target opponent sacrifices a creature or planeswalker of their choice, discards a card, and loses 3 life. You draw a card
        // and gain 3 life." (in the order written, CR 608.2c)
        Mh2.OPPONENT_SACRIFICES_DISCARDS_LOSES_YOU_DRAW_GAIN.matchEntire(text)?.let { m ->
            val noun = Filters.noun(m.groupValues[1]) ?: return null
            context.targets += TargetSlot("opponent", TargetKind.Players(PlayerFilter.Opponent), min = Value.Fixed(1), max = Value.Fixed(1))
            val opponent = Players.Target("opponent")
            return listOf(
                Step.Choose(arcanum.api.Choice.Objects(Filters.all(noun, ObjectFilter.ControlledBy(PlayerFilter.Is(opponent))), Value.Fixed(1), Value.Fixed(1)),
                    bind = "sacrificed", chooser = opponent),
                Step.Do(Effect.Sacrifice(Objects.Bound("sacrificed"))),
                Step.Do(Effect.Discard(opponent, Value.Fixed(1), ObjectFilter.Any)),
                Step.Do(Effect.LoseLife(opponent, Value.Fixed(m.groupValues[2].toInt()))),
                Step.Do(Effect.Draw(Players.You, Value.Fixed(1))),
                Step.Do(Effect.GainLife(Players.You, Value.Fixed(m.groupValues[3].toInt()))))
        }
        // mh2 chunk 05: "Look at the top four cards of your library. Put one of them into your hand and the rest into your graveyard. You gain life
        // equal to the greatest power among creature cards put into your graveyard this way." (as they are there, CR 608.2h)
        Mh2.LOOK_TOP_ONE_HAND_REST_GRAVEYARD_GAIN_GREATEST_POWER.matchEntire(text)?.let { m ->
            val count = Numbers.count(m.groupValues[1]) ?: return null
            return listOf(Step.Do(Effect.LookAt(Objects.LibraryCards(Players.You, Value.Fixed(count), fromTop = true), Players.You, bind = "seen")),
                Step.Choose(arcanum.api.Choice.Objects(ObjectFilter.Any, Value.Fixed(1), Value.Fixed(1), from = Objects.Bound("seen")), bind = "kept", chooser = Players.You),
                Step.Do(Effect.Move(Objects.Bound("kept"), Destination(Zone.Hand))),
                Step.Do(Effect.Move(Objects.Except(Objects.Bound("seen"), Objects.Bound("kept")), Destination(Zone.Graveyard), postBind = "milled")),
                Step.Do(Effect.GainLife(Players.You, Value.Of(arcanum.api.NumericProperty.Power,
                    Objects.Where(Objects.Bound("milled"), ObjectFilter.Type(CardType.Creature)), arcanum.api.Combine.Greatest))))
        }
        // mh2 chunk 05: "Choose an exiled card an opponent owns with a void counter on it. You may play it this turn without paying its mana cost."
        // (CR 601.2a, 305.1)
        Mh2.CHOOSE_EXILED_CARD_OPPONENT_OWNS_WITH_COUNTER_MAY_PLAY_FREE.matchEntire(text)?.let { m ->
            val kind = Counters.kind(m.groupValues[1]) ?: return null
            return listOf(Step.Choose(arcanum.api.Choice.Objects(Filters.all(ObjectFilter.Category(arcanum.api.ObjectCategory.Card), ObjectFilter.InZone(Zone.Exile),
                ObjectFilter.OwnedBy(PlayerFilter.Opponent), ObjectFilter.HasCounter(kind, atLeast = 1)), Value.Fixed(1), Value.Fixed(1)), bind = "chosen", chooser = Players.You),
                Step.Do(Effect.ApplyMechanics(listOf(Mechanic.MayPlay(Zone.Exile, PlayKind.Play, withoutPaying = true, holder = PlayerFilter.You)),
                    Affected.Objects(Objects.Bound("chosen")), arcanum.api.Duration.EndOfTurn)))
        }
        // mh2 chunk 04: "Choose up to one target creature spell or planeswalker spell. Its owner puts it on their choice of the top or bottom of their
        // library." (CR 401.4)
        Mh2.CHOOSE_TARGET_OWNER_PUTS_TOP_OR_BOTTOM.matchEntire(text)?.let { m ->
            val noun = Filters.noun(m.groupValues[1]) ?: return null
            val name = mh2NewSlotName(context, Filters.slotName(m.groupValues[1]))
            context.targets += mh2Slot(name, noun, min = 0)
            val it = Objects.Target(name)
            return listOf(Step.Choose(arcanum.api.Choice.Option(listOf("top", "bottom")), bind = "position", chooser = Players.OwnerOf(it)),
                Step.If(arcanum.api.Condition.Chose("position", "top"), then = listOf(Step.Do(Effect.Move(it, Destination(Zone.Library, libraryPosition = 0)))),
                    otherwise = listOf(Step.Do(Effect.Move(it, Destination(Zone.Library, libraryPosition = -1))))))
        }
        // mh2 chunk 04: "Target noncreature artifact you control becomes a 0/0 artifact creature. Put four +1/+1 counters on each artifact that became a
        // creature this way." (and its overloaded "Each …"; the affected artifacts are fixed as it resolves, CR 611.2c)
        Mh2.BECOMES_ARTIFACT_CREATURE_PUT_COUNTERS_ON_EACH_THAT_BECAME.matchEntire(text)?.let { m ->
            val noun = Filters.noun(m.groupValues[2]) ?: return null
            val kind = Counters.kind(m.groupValues[6]) ?: return null
            val amount = Numbers.count(m.groupValues[5]) ?: return null
            val objects = if (m.groupValues[1] == "Each") Objects.Each(noun) else {
                val name = mh2NewSlotName(context, Filters.slotName(m.groupValues[2]))
                context.targets += mh2Slot(name, noun)
                Objects.Target(name)
            }
            val became = Objects.Bound("became")
            return listOf(Step.Bind(objects, "became"),
                Step.Do(Effect.ApplyMechanics(listOf(Mechanic.SetTypes(add = listOf(CardType.Artifact, CardType.Creature)),
                    Mechanic.SetPowerToughness(Value.Fixed(m.groupValues[3].toInt()), Value.Fixed(m.groupValues[4].toInt()))),
                    Affected.Objects(became), arcanum.api.Duration.Indefinitely)),
                Step.Do(Effect.PutCounters(became, kind, Value.Fixed(amount))))
        }
        // mh2 chunk 04: "Exile target creature and put two time counters on it. If it doesn't have suspend, it gains suspend." (CR 702.62b: a
        // suspend gained this way has no cost and no number; only its abilities in exile matter)
        Mh2.EXILE_TARGET_PUT_TIME_COUNTERS_GAINS_SUSPEND.matchEntire(text)?.let { m ->
            val noun = Filters.noun(m.groupValues[1]) ?: return null
            val count = Numbers.count(m.groupValues[2]) ?: return null
            val name = mh2NewSlotName(context, Filters.slotName(m.groupValues[1]))
            context.targets += mh2Slot(name, noun)
            val exiled = Objects.Bound("exiled")
            return listOf(Step.Do(Effect.Move(Objects.Target(name), Destination(Zone.Exile), postBind = "exiled")),
                Step.Do(Effect.PutCounters(exiled, arcanum.api.CounterKind.Time, Value.Fixed(count))),
                Step.If(arcanum.api.Condition.Not(arcanum.api.Condition.ObjectMatches(exiled, ObjectFilter.HasKeyword(arcanum.api.Keyword.Suspend.Kind))), then = listOf(
                    Step.Do(Effect.ApplyMechanics(listOf(Mechanic.GainAbilities(listOf(arcanum.api.Keyword.Suspend(0, Cost(emptyList()))))),
                        Affected.Objects(exiled), arcanum.api.Duration.Indefinitely)))))
        }
        // mh2 chunk 03: "Search target opponent's library for a creature card and put that card onto the battlefield under your control. Then
        // that player shuffles." (CR 701.23a)
        Mh2.SEARCH_OPPONENTS_LIBRARY_PUT_UNDER_YOUR_CONTROL.matchEntire(text)?.let { m ->
            val cards = Filters.noun(m.groupValues[1]) ?: return null
            context.targets += TargetSlot("opponent", TargetKind.Players(PlayerFilter.Opponent), min = Value.Fixed(1), max = Value.Fixed(1))
            val opponent = Players.Target("opponent")
            return listOf(Step.Do(Effect.Search(opponent, cards, max = Value.Fixed(1), zones = listOf(Zone.Library), bind = "found", searcher = Players.You)),
                Step.Do(Effect.Move(Objects.Bound("found"), Destination(Zone.Battlefield, controller = Players.You))),
                Step.Do(Effect.Shuffle(opponent)))
        }
        // mh2 chunk 02: "Untap all creatures, then those creatures phase out until this enchantment leaves the battlefield. Put a time counter on
        // this enchantment for each creature that phased out this way." (CR 702.26, 610.3)
        Mh2.UNTAP_ALL_THEN_PHASE_OUT_COUNTER_EACH.matchEntire(text)?.takeIf { isSelf(it.groupValues[2]) && isSelf(it.groupValues[4]) }?.let { m ->
            val noun = Filters.noun(m.groupValues[1].removeSuffix("s")) ?: return null
            val kind = Counters.kind(m.groupValues[3]) ?: return null
            val those = Objects.Bound(m.groupValues[1])
            return listOf(Step.Bind(Objects.Each(noun), m.groupValues[1]), Step.Do(Effect.Untap(those)),
                Step.Do(Effect.PhaseOut(those, untilLeaves = Objects.Self, bind = "phased")),
                Step.Do(Effect.PutCounters(Objects.Self, kind, Value.Count(Objects.Bound("phased")))))
        }
        return null
    }

    /** mh2: sentences that change the steps before them. */
    private fun mh2Modify(sentence: String, steps: List<Step>, context: Context): List<Step>? {
        // mh2 chunk 04: "Those creatures don't untap during their controller's next untap step." after tapping targets
        Mh2.THOSE_DONT_UNTAP_DURING_NEXT.matchEntire(sentence)?.let { m ->
            val tapped = ((steps.lastOrNull() as? Step.Do)?.effect as? Effect.Tap)?.objects ?: return@let
            return steps + Step.Do(Effect.ApplyMechanics(listOf(Mechanic.DoesntUntap), Affected.Objects(tapped),
                arcanum.api.Duration.ThroughNextStep(arcanum.api.TurnStep.Untap, Players.ControllerOf(tapped))))
        }
        // mh2 chunk 01: "If it's an artifact creature, it gets +2/+2 until end of turn." after an effect on a target: whether the target is one
        // as the spell resolves (CR 608.2h)
        Mh2.IF_ITS_A_THEN.matchEntire(sentence)?.let { m ->
            val slot = context.targets.lastOrNull()?.takeIf { it.what is TargetKind.Objects } ?: return@let
            val noun = Filters.noun(m.groupValues[1]) ?: return@let
            val target = Objects.Target(slot.name)
            val outerIt = context.it
            context.it = target
            val then = try { effect(m.groupValues[2].replaceFirstChar { it.uppercase() }, context) } finally { context.it = outerIt } ?: return@let
            return steps + Step.If(arcanum.api.Condition.ObjectMatches(target, noun), then = then)
        }
        return null
    }

    /** mh2: effect sentences. */
    private fun mh2Effect(sentence: String, context: Context): List<Step>? {
        // mh2 chunk 05: "You gain life equal to the number of counters on it." (the last target, as it last existed, CR 608.2h)
        if (Mh2.GAIN_LIFE_EQUAL_TO_COUNTERS_ON_IT.matches(sentence)) {
            val it = context.targets.lastOrNull()?.takeIf { it.what is TargetKind.Objects }?.let { Objects.Target(it.name) } ?: return null
            return listOf(Step.Do(Effect.GainLife(Players.You, Value.Of(arcanum.api.NumericProperty.Counters(null), it, arcanum.api.Combine.Single))))
        }
        // mh2 chunk 05: "Return target creature card and all other cards with the same name as that card from your graveyard to your hand."
        Mh2.RETURN_TARGET_AND_ALL_SAME_NAME.matchEntire(sentence)?.let { m ->
            val noun = Filters.noun(m.groupValues[1]) ?: return@let
            val inYourGraveyard = listOf(ObjectFilter.InZone(Zone.Graveyard), ObjectFilter.OwnedBy(PlayerFilter.You))
            val name = mh2NewSlotName(context, "card")
            context.targets += mh2Slot(name, Filters.all(noun, *inYourGraveyard.toTypedArray()))
            val target = Objects.Target(name)
            val others = Objects.Each(Filters.all(ObjectFilter.Category(arcanum.api.ObjectCategory.Card), ObjectFilter.Not(ObjectFilter.Is(target)),
                ObjectFilter.SameNameAs(target), *inYourGraveyard.toTypedArray()))
            return listOf(Step.Do(Effect.Move(Objects.Union(listOf(target, others)), Destination(Zone.Hand))))
        }
        // mh2 chunk 06: "target opponent discards two cards at random." (CR 701.9b)
        Mh2.TARGET_OPPONENT_DISCARDS_AT_RANDOM.matchEntire(sentence)?.let { m ->
            val count = Numbers.count(m.groupValues[1]) ?: (if (m.groupValues[1] == "a") 1 else return@let)
            val name = mh2NewSlotName(context, "opponent")
            context.targets += TargetSlot(name, TargetKind.Players(PlayerFilter.Opponent), min = Value.Fixed(1), max = Value.Fixed(1))
            return listOf(Step.Do(Effect.Discard(Players.Target(name), Value.Fixed(count), ObjectFilter.Any, random = true)))
        }
        // mh2 chunk 06: "that player discards a card." at the beginning of each player's upkeep: the player whose step it is
        if (Mh2.THAT_PLAYER_DISCARDS_A_CARD.matches(sentence) && context.event is EventPattern.StepBegins)
            return listOf(Step.Do(Effect.Discard(Players.Active, Value.Fixed(1), ObjectFilter.Any)))
        // mh2 chunk 06: "create a number of 1/1 green Squirrel creature tokens equal to your devotion to black." (CR 700.5)
        Mh2.CREATE_NUMBER_EQUAL_TO_DEVOTION.matchEntire(sentence)?.let { m ->
            val color = Tokens.color(m.groupValues[2]) ?: return@let
            val token = m.groupValues[1].replace(" tokens", " token")
            val created = effect("Create a $token.", context) ?: return@let
            val create = (created.singleOrNull() as? Step.Do)?.effect as? Effect.CreateToken ?: return@let
            return listOf(Step.Do(create.copy(count = Value.Devotion(listOf(color), Players.You))))
        }
        // mh2 chunk 09: "Target player shuffles their graveyard into their library." (CR 701.24a)
        if (Mh2.TARGET_PLAYER_SHUFFLES_GRAVEYARD_INTO_LIBRARY.matches(sentence)) {
            val name = mh2NewSlotName(context, "player")
            context.targets += TargetSlot(name, TargetKind.Players(PlayerFilter.Any), min = Value.Fixed(1), max = Value.Fixed(1))
            val player = Players.Target(name)
            return listOf(Step.Do(Effect.Move(Objects.Each(Filters.all(ObjectFilter.InZone(Zone.Graveyard), ObjectFilter.OwnedBy(PlayerFilter.Is(player)))), Destination(Zone.Library))),
                Step.Do(Effect.Shuffle(player)))
        }
        // mh2 chunk 09: "Prevent all combat damage that would be dealt this turn." (CR 615.1)
        if (Mh2.PREVENT_ALL_COMBAT_DAMAGE_THIS_TURN.matches(sentence))
            return listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.Prevention(EventPattern.Damage(ObjectFilter.Any, arcanum.api.RecipientFilter(), combat = true))),
                null, arcanum.api.Duration.EndOfTurn)))
        // mh2 chunk 10: "Target player creates two tapped 1/1 green Squirrel creature tokens."
        Mh2.TARGET_PLAYER_CREATES_TOKENS.matchEntire(sentence)?.let { m ->
            val count = Numbers.count(m.groupValues[1]) ?: (if (m.groupValues[1] == "a" || m.groupValues[1] == "an") 1 else return@let)
            val created = effect("Create a ${m.groupValues[3].removeSuffix("s")}.", context) ?: return@let
            val create = (created.singleOrNull() as? Step.Do)?.effect as? Effect.CreateToken ?: return@let
            val name = mh2NewSlotName(context, "player")
            context.targets += TargetSlot(name, TargetKind.Players(PlayerFilter.Any), min = Value.Fixed(1), max = Value.Fixed(1))
            return listOf(Step.Do(create.copy(count = Value.Fixed(count), controller = Players.Target(name), tapped = m.groupValues[2].isNotEmpty())))
        }
        // mh2 chunk 10: "Counter target loyalty ability of a planeswalker." (CR 606)
        if (Mh2.COUNTER_TARGET_LOYALTY_ABILITY.matches(sentence)) {
            val name = mh2NewSlotName(context, "ability")
            context.targets += mh2Slot(name, ObjectFilter.AbilityOf(kind = arcanum.api.AbilityKind.Loyalty))
            return listOf(Step.Do(Effect.Counter(Objects.Target(name))))
        }
        // mh2 chunk 11: "Gain control of each permanent with a corruption counter on it." (no duration: for good, CR 611.2a)
        Mh2.GAIN_CONTROL_OF_EACH.matchEntire(sentence)?.let { m ->
            val objects = Filters.objects(m.groupValues[1]) ?: return@let
            return listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.ControlledBy(Players.You)), Affected.Objects(objects), arcanum.api.Duration.Indefinitely)))
        }
        // mh2 chunk 11: "You gain life equal to the number of cards you've discarded this turn."
        if (Mh2.GAIN_LIFE_EQUAL_TO_CARDS_DISCARDED_THIS_TURN.matches(sentence))
            return listOf(Step.Do(Effect.GainLife(Players.You, Value.EventsThisTurn(EventPattern.Discard(ObjectFilter.Any, PlayerFilter.You), arcanum.api.Measure.Objects))))
        // mh2 chunk 12: "investigate twice." (CR 701.16a)
        if (Mh2.INVESTIGATE_TWICE.matches(sentence)) return listOf(Step.Do(Effect.Action(arcanum.api.KeywordAction.Investigate(Value.Fixed(2)))))
        // fdn chunk 10b: "Each opponent loses life equal to the number of soul counters on this artifact."
        Fdn.LOSES_LIFE_EQUAL_TO_COUNTERS_ON_SELF.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[3]) }?.let { m ->
            val kind = Counters.kind(m.groupValues[2]) ?: return@let
            return listOf(Step.Do(Effect.LoseLife(Filters.players(m.groupValues[1].replaceFirstChar { it.lowercase() }) ?: return@let,
                Value.Of(arcanum.api.NumericProperty.Counters(kind), Objects.Self, arcanum.api.Combine.Single))))
        }
        // mh2 chunk 12: "Each opponent loses life equal to the number of creature cards in your graveyard."
        Mh2.EACH_OPPONENT_LOSES_LIFE_EQUAL_TO.matchEntire(sentence)?.let { m ->
            val amount = Values.value(m.groupValues[1]) ?: return@let
            return listOf(Step.Do(Effect.LoseLife(Players.Each(PlayerFilter.Opponent), amount)))
        }
        // mh2 chunk 14: "Create a 0/0 colorless Construct artifact creature token with 'This token gets +1/+1 for each artifact you control.'" (a
        // quoted ability inside a quoted ability uses single quotes)
        Mh2.TOKEN_WITH_SINGLE_QUOTED.matchEntire(sentence)?.let { m ->
            return effect("${m.groupValues[1]} with \"${m.groupValues[2]}\".", context)
        }
        // mh2 chunk 15: "that player sacrifices an artifact, creature, or land of their choice." at the beginning of each player's upkeep
        Mh2.THAT_PLAYER_SACRIFICES_OF_THEIR_CHOICE.matchEntire(sentence)?.takeIf { context.event is EventPattern.StepBegins }?.let { m ->
            val noun = Filters.noun(m.groupValues[1]) ?: return@let
            return listOf(Step.Choose(arcanum.api.Choice.Objects(Filters.all(noun, ObjectFilter.ControlledBy(PlayerFilter.Is(Players.Active))), Value.Fixed(1), Value.Fixed(1)),
                bind = "sacrificed", chooser = Players.Active), Step.Do(Effect.Sacrifice(Objects.Bound("sacrificed"))))
        }
        // mh2 chunk 16: "You may cast a creature spell from your graveyard this turn." (one spell, CR 601.2a)
        Mh2.MAY_CAST_A_SPELL_FROM_YOUR_GRAVEYARD_THIS_TURN.matchEntire(sentence)?.let { m ->
            val noun = Filters.noun(m.groupValues[1]) ?: return@let
            return listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.MayPlay(Zone.Graveyard, PlayKind.Cast, perTurn = 1, holder = PlayerFilter.You)),
                Affected.Objects(Objects.Each(Filters.all(noun, ObjectFilter.InZone(Zone.Graveyard), ObjectFilter.OwnedBy(PlayerFilter.You)))), arcanum.api.Duration.EndOfTurn)))
        }
        // mh2 chunk 16: "it gains haste until your next turn." in an enters trigger of another creature: that creature
        Mh2.IT_GAINS_UNTIL_YOUR_NEXT_TURN.matchEntire(sentence)?.takeIf { (context.event as? EventPattern.ZoneChange)?.to == Zone.Battlefield }?.let { m ->
            val keyword = OracleParser.keyword(m.groupValues[1].replaceFirstChar { it.uppercase() }) ?: return@let
            return listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.GainAbilities(listOf(keyword))), Affected.Objects(Objects.EventObject(EventRole.After)),
                arcanum.api.Duration.UntilYourNextTurn)))
        }
        // mh2 chunk 16: "Destroy all artifacts, creatures, and enchantments."
        Mh2.DESTROY_ALL_THREE_KINDS.matchEntire(sentence)?.let { m ->
            val kinds = (1..3).map { Filters.noun(m.groupValues[it]) ?: return@let }
            return listOf(Step.Do(Effect.Destroy(Objects.Each(ObjectFilter.Or(kinds)))))
        }
        // mh2 chunk 16: "add one mana of any type that land produced." (CR 106.12)
        if (Mh2.ADD_ONE_MANA_OF_ANY_TYPE_THAT_LAND_PRODUCED.matches(sentence) && (context.event as? EventPattern.Tap)?.forMana == true)
            return listOf(Step.Do(Effect.AddMana(ManaProduction(ManaKind.SameAsProduced(Value.Fixed(1))), Players.You)))
        // mh2 chunk 13: "exile that creature." after damage to it; "counter that spell." after it was cast (the event's object)
        if (sentence == "Exile that creature." && context.event is EventPattern.Damage)
            return listOf(Step.Do(Effect.Move(Objects.EventObject(EventRole.Object), Destination(Zone.Exile))))
        if (sentence == "Counter that spell." && context.event is EventPattern.Cast)
            return listOf(Step.Do(Effect.Counter(Objects.EventObject(EventRole.Object))))
        // mh2 chunk 13: "Target nonland permanent becomes an artifact in addition to its other types until end of turn." (layer 4)
        Mh2.TARGET_BECOMES_TYPE_IN_ADDITION_UNTIL_EOT.matchEntire(sentence)?.let { m ->
            val type = mapOf("artifact" to CardType.Artifact, "creature" to CardType.Creature, "enchantment" to CardType.Enchantment)[m.groupValues[2]] ?: return@let
            val noun = Filters.noun(m.groupValues[1]) ?: return@let
            val name = mh2NewSlotName(context, Filters.slotName(m.groupValues[1]))
            context.targets += mh2Slot(name, noun)
            return listOf(mh2UntilEndOfTurn(Objects.Target(name), Mechanic.SetTypes(add = listOf(type))))
        }
        // mh2 chunk 13: "Until end of turn, this Vehicle becomes a copy of the exiled card, except it's a Vehicle artifact in addition to its other
        // types." (CR 707.9b)
        Mh2.UNTIL_EOT_BECOMES_COPY_OF_EXILED_EXCEPT.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val exiled = exiledCard ?: return@let
            val type = mapOf("artifact" to CardType.Artifact, "creature" to CardType.Creature)[m.groupValues[3]] ?: return@let
            if (m.groupValues[2] !in RulesWords.subtypes) return@let
            return listOf(mh2UntilEndOfTurn(Objects.Self, Mechanic.CopyOf(exiled, except = listOf(arcanum.api.CopyException.Types(add = listOf(type),
                addSubtypes = listOf(arcanum.api.SubtypeRef.Literal(Subtype(m.groupValues[2]))))))))
        }
        // mh2 chunk 04: "Put enchanted creature into its owner's library third from the top." (CR 401.4: from 0 at the top)
        Mh2.PUT_INTO_OWNERS_LIBRARY_NTH_FROM_TOP.matchEntire(sentence)?.let { m ->
            val objects = if (m.groupValues[1] == "enchanted creature") Objects.AttachedTo(Objects.Self) else mh2Objects(m.groupValues[1], context) ?: return@let
            val position = mapOf("second" to 1, "third" to 2, "fourth" to 3, "fifth" to 4 /* ltr chunk 02 */)[m.groupValues[2]] ?: return@let
            return listOf(Step.Do(Effect.Move(objects, Destination(Zone.Library, libraryPosition = position))))
        }
        // mh2 chunk 04: "Return two target creatures to their owners' hands."
        Mh2.RETURN_N_TARGETS_TO_OWNERS_HANDS.matchEntire(sentence)?.let { m ->
            val count = Numbers.count(m.groupValues[1]) ?: return@let
            val singular = m.groupValues[2].substringBefore(' ').removeSuffix("s") + m.groupValues[2].removePrefix(m.groupValues[2].substringBefore(' '))
            val noun = Filters.noun(singular) ?: return@let
            val name = mh2NewSlotName(context, Filters.slotName(singular) + "s")
            context.targets += mh2Slot(name, noun, min = count, max = count)
            return listOf(Step.Do(Effect.Move(Objects.Target(name), Destination(Zone.Hand))))
        }
        // mh2 chunk 04: "Create a 1/1 colorless Thopter artifact creature token with flying for each color of mana spent to cast this spell."
        // (converge, CR 601.2h)
        Mh2.CREATE_FOR_EACH_COLOR_SPENT.matchEntire(sentence)?.let { m ->
            val created = effect("Create ${m.groupValues[1]}.", context) ?: return@let
            val create = (created.singleOrNull() as? Step.Do)?.effect as? Effect.CreateToken ?: return@let
            return listOf(Step.Do(create.copy(count = Value.ManaSpent(distinctColors = true, of = Objects.Self))))
        }
        // mh2 chunk 04: "target land becomes an Island for as long as this creature remains on the battlefield." (CR 305.7, 611.2b)
        Mh2.TARGET_BECOMES_LAND_TYPE_AS_LONG_AS_REMAINS.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[3]) }?.let { m ->
            if (m.groupValues[2] !in RulesWords.subtypes) return@let
            val noun = Filters.noun(m.groupValues[1]) ?: return@let
            val name = mh2NewSlotName(context, m.groupValues[1])
            context.targets += mh2Slot(name, noun)
            return listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.SetTypes(addSubtypes = listOf(arcanum.api.SubtypeRef.Literal(Subtype(m.groupValues[2]))),
                replaceSubtypes = true)), Affected.Objects(Objects.Target(name)), arcanum.api.Duration.UntilLeaves(Objects.Self))))
        }
        // mh2 chunk 03: "X target creatures gain flying until end of turn." (X announced, CR 107.3a)
        Mh2.X_TARGET_GAIN_UNTIL_EOT.matchEntire(sentence)?.takeIf { announcedX }?.let { m ->
            val noun = Filters.noun(m.groupValues[1].removeSuffix("s")) ?: return@let
            val keywords = m.groupValues[2].split(LazyRegexes.AND_LIST).map { OracleParser.keyword(it.trim().replaceFirstChar { c -> c.uppercase() }) ?: return@let }
            val name = mh2NewSlotName(context, Filters.slotName(m.groupValues[1].removeSuffix("s")) + "s")
            context.targets += TargetSlot(name, TargetKind.Objects(noun), min = Value.Announced(name = "X"), max = Value.Announced(name = "X"))
            return listOf(mh2UntilEndOfTurn(Objects.Target(name), Mechanic.GainAbilities(keywords)))
        }
        // mh2 chunk 03: "sacrifice it." when this permanent becomes the target of a spell or ability: this permanent
        if (sentence == "Sacrifice it." && (context.event as? EventPattern.BecomesTarget)?.objects == ObjectFilter.Is(Objects.Self))
            return listOf(Step.Do(Effect.Sacrifice(Objects.Self)))
        // mh2 chunk 03: "Switch this creature's power and toughness until end of turn." (layer 7d, CR 613.4d)
        Mh2.SWITCH_PT_UNTIL_EOT.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            return listOf(mh2UntilEndOfTurn(Objects.Self, Mechanic.SwitchPowerToughness))
        }
        // mh2 chunk 01: "create a 1/1 colorless Thopter artifact creature token with flying, then attach this Equipment to it." (CR 701.3a)
        Mh2.THEN_ATTACH_SELF_TO_IT.matchEntire(sentence)?.takeIf { isSelf(it.groupValues[2]) }?.let { m ->
            val first = effect(m.groupValues[1].replaceFirstChar { it.uppercase() } + ".", context) ?: return@let
            val create = (first.singleOrNull() as? Step.Do)?.effect as? Effect.CreateToken ?: return@let
            return listOf(Step.Do(create.copy(bind = "token")), Step.Do(Effect.Attach(Objects.Self, Recipients(objects = Objects.Bound("token")))))
        }
        // mh2 chunk 02: "exile all cards that are black or red from all graveyards."
        Mh2.EXILE_ALL_CARDS_OF_TWO_COLORS_FROM_ALL_GRAVEYARDS.matchEntire(sentence)?.let { m ->
            val colors = ObjectFilter.Or(listOf(mh2Color(m.groupValues[1]) ?: return null, mh2Color(m.groupValues[2]) ?: return null))
            return listOf(Step.Do(Effect.Move(Objects.Each(Filters.all(ObjectFilter.Category(arcanum.api.ObjectCategory.Card), colors, ObjectFilter.InZone(Zone.Graveyard))),
                Destination(Zone.Exile))))
        }
        // mh2 chunk 02: "Exile target creature card from your graveyard." (the exiled card is named for what follows)
        Mh2.EXILE_TARGET_FROM_YOUR_GRAVEYARD.matchEntire(sentence)?.let { m ->
            val noun = Filters.noun(m.groupValues[1]) ?: return@let
            val name = mh2NewSlotName(context, "card")
            context.targets += mh2Slot(name, Filters.all(noun, ObjectFilter.InZone(Zone.Graveyard), ObjectFilter.OwnedBy(PlayerFilter.You)))
            context.it = Objects.Bound("exiled") // inr chunk 07: "that card" is the exiled card (CR 608.2c)
            return listOf(Step.Do(Effect.Move(Objects.Target(name), Destination(Zone.Exile), postBind = "exiled")))
        }
        // mh2 chunk 02: "you may put that many +1/+1 counters on each creature you control." (the event's amount: the life gained)
        Mh2.PUT_THAT_MANY_COUNTERS_ON.matchEntire(sentence)?.let { m ->
            val amount = context.thatMuch ?: Value.EventAmount.takeIf { context.event is EventPattern.GainLife } ?: return@let
            val kind = Counters.kind(m.groupValues[2]) ?: return@let
            val objects = mh2Objects(m.groupValues[3], context) ?: return@let
            val put = Step.Do(Effect.PutCounters(objects, kind, amount))
            return listOf(if (m.groupValues[1].isEmpty()) put else Step.May(listOf(put), Players.You))
        }
        // mh2 chunk 01: "You gain hexproof until your next turn." (CR 702.11c: hexproof for a player)
        if (Mh2.YOU_GAIN_HEXPROOF_UNTIL_YOUR_NEXT_TURN.matches(sentence))
            return listOf(Step.Do(Effect.ApplyMechanics(listOf(Mechanic.CantBeTargeted(by = ObjectFilter.ControlledBy(PlayerFilter.Opponent))),
                Affected.Players(Players.You), arcanum.api.Duration.UntilYourNextTurn)))
        // mh2 chunk 01: "put target card from an opponent's graveyard on the bottom of their library." (its owner's library, CR 401.4)
        if (Mh2.PUT_TARGET_CARD_FROM_OPPONENTS_GRAVEYARD_ON_BOTTOM.matches(sentence)) {
            val name = mh2NewSlotName(context, "card")
            context.targets += mh2Slot(name, Filters.all(ObjectFilter.Category(arcanum.api.ObjectCategory.Card), ObjectFilter.InZone(Zone.Graveyard),
                ObjectFilter.OwnedBy(PlayerFilter.Opponent)))
            return listOf(Step.Do(Effect.Move(Objects.Target(name), Destination(Zone.Library, libraryPosition = -1))))
        }
        return null
    }
    // ---- mh2 end

    // ---- ltr: The Lord of the Rings: Tales of Middle-earth wordings (the set's parser tests, sets/ltr/LtrChunk*Test.kt); regexes in [Ltr].

    private fun ltrNewSlotName(context: Context, base: String) = if (context.targets.none { it.name == base }) base else nextTargetName(base, context.targets.map { it.name })
    private fun ltrUntilEndOfTurn(objects: Objects, vararg mechanics: Mechanic) =
        Step.Do(Effect.ApplyMechanics(mechanics.toList(), Affected.Objects(objects), arcanum.api.Duration.EndOfTurn))
    private fun ltrSelfStatic(vararg mechanics: Mechanic) = Ability.Static(mechanics.toList(), affects = Affected.Objects(Objects.Self))
    private val ltrEquipAbilities get() = ObjectFilter.AbilityOf(keyword = arcanum.api.Keyword.Equip.Kind)

    /** ltr: the objects a subject names: a target phrase (its slot added to [context]), "it", this object, "enchanted creature". */
    private fun ltrObjects(subject: String, context: Context): Objects? =
        ltrTarget(subject.replaceFirstChar { it.lowercase() }, context) ?: mshObjects(subject, context)

    /** ltr: a target phrase ("up to one target creature you own", "another target creature you control"): its slot added to [context], named
     * after its noun without "you own" / "you control". */
    private fun ltrTarget(phrase: String, context: Context): Objects? {
        val m = Tla.TARGET_PHRASE.matchEntire(phrase) ?: return null
        val (min, max) = when (m.groupValues[1].trim()) {
            "" -> 1 to 1; "up to one" -> 0 to 1; "up to two" -> 0 to 2; "any number of" -> 0 to null; "one or two" -> 1 to 2; else -> return null
        }
        val noun = m.groupValues[3]
        val base = Filters.noun(noun) ?: return null
        val filter = if (m.groupValues[2].isNotEmpty()) Filters.all(ObjectFilter.Not(ObjectFilter.Is(Objects.Self)), base) else base
        val name = ltrNewSlotName(context, Filters.slotName(noun.substringBefore(" from ").substringBefore(" in your ").substringBefore(" that ")
            .removeSuffix(" you own").removeSuffix(" you control")))
        context.targets += tlaSlot(name, filter, min, max)
        return Objects.Target(name)
    }

    /** ltr: "a Goblin or Orc", "a legendary permanent or an artifact": each noun of an "or" list. */
    private fun ltrNouns(phrase: String): ObjectFilter? {
        Filters.noun(phrase)?.let { return it }
        val parts = phrase.split(" or ").map { it.removePrefix("a ").removePrefix("an ") }
        if (parts.size < 2) return null
        return ObjectFilter.Or(parts.map { Filters.noun(it) ?: return null })
    }

    /** ltr: the creature an event names as "it": the one that dealt the damage, else the event's object. */
    private fun ltrIt(trigger: arcanum.api.Trigger.On): Objects = itOf(trigger.events)?.first
        ?: if (trigger.events.singleOrNull() is EventPattern.Damage) Objects.EventObject(EventRole.Source) else Objects.EventObject(EventRole.Object)

    /** ltr: modal triggered abilities. */
    private fun ltrModalTrigger(header: String, modeLines: List<String>): Ability? {
        // ltr chunk 09: "Whenever you scry, choose one and Erestor gets +1/+1 until end of turn." (the pump in each mode, CR 700.2)
        Ltr.CHOOSE_ONE_AND_GETS.matchEntire(header)?.takeIf { isSelf(it.groupValues[2]) }?.let { m ->
            val w = WHENEVER.matchEntire("${m.groupValues[1]}, draw a card.") ?: return@let
            val (trigger, onlyIf) = trigger(w.groupValues[2]) ?: return@let
            val pump = ltrUntilEndOfTurn(Objects.Self, Mechanic.ModifyPowerToughness(Value.Fixed(m.groupValues[3].toInt()), Value.Fixed(m.groupValues[4].toInt())))
            val options = modeLines.map { line ->
                val i = instructions(modeBody(line)) ?: return@let
                arcanum.api.Mode(i.copy(steps = listOf(pump) + i.steps), text = line)
            }
            return Ability.Triggered(trigger, Instructions(modes = arcanum.api.Modes(options, min = 1, max = 1, chooser = Players.You)), triggersOnlyIf = onlyIf)
        }
        // ltr chunk 05: "Whenever a Goblin or Orc you control deals combat damage to a player, you may sacrifice it. When you do, choose one —"
        // (a cost paid on resolution, CR 118.12; the reflexive trigger's modes chosen as it is put on the Stack, CR 603.12)
        Ltr.MAY_SACRIFICE_IT_WHEN_YOU_DO.matchEntire(header)?.let { m ->
            val w = WHENEVER.matchEntire("${m.groupValues[1]}, draw a card.") ?: return@let
            val (trigger, onlyIf) = trigger(w.groupValues[2]) ?: return@let
            val choose = CHOOSE_MODES.matchEntire(m.groupValues[2]) ?: return@let
            val n = Numbers.count(choose.groupValues[1]) ?: return@let
            val options = modeLines.map { arcanum.api.Mode(instructions(modeBody(it)) ?: return@let, text = it) }
            return Ability.Triggered(trigger, Instructions(steps = listOf(
                Step.Pay(Cost(listOf(CostPart.Sacrifice(CostObjects.These(ltrIt(trigger))))), payer = Players.You, bind = "paid"),
                Step.If(arcanum.api.Condition.Did("paid"), then = listOf(Step.Do(Effect.ReflexiveTrigger(Instructions(
                    modes = arcanum.api.Modes(options, min = n, max = n, chooser = Players.You)))))))), triggersOnlyIf = onlyIf)
        }
        return null
    }

    /** ltr: whole lines read before the other rules. */
    private fun ltrLine(line: String): Ability? {
        // ltr chunk 14: "Whenever equipped creature blocks or becomes blocked by a creature, that creature loses all abilities until end of turn."
        // (once for each creature it blocks or that blocks it, CR 509.3a, 509.3d; that creature: the other combatant)
        Ltr.BLOCKS_OR_BECOMES_BLOCKED_THAT_CREATURE_LOSES.matchEntire(line)?.let { m ->
            val subject = Events.subjectOf(m.groupValues[1], self) ?: return@let
            val other = Filters.noun(m.groupValues[2]) ?: return@let
            return Ability.Triggered(arcanum.api.Trigger.On(listOf(EventPattern.Block(subject, other, perAttacker = true), EventPattern.BecomesBlocked(subject, other, perBlocker = true))),
                Instructions(steps = listOf(ltrUntilEndOfTurn(Objects.EventObject(EventRole.OtherCombatant), Mechanic.LoseAbilities()))))
        }
        // ltr chunk 14: "If you would draw a card while you have no cards in hand, draw two cards instead." (CR 614.1a: a replacement applying only
        // while the condition holds)
        Ltr.WOULD_WHILE_YOU_HAVE.matchEntire(line)?.let { m ->
            val inner = line("If you would ${m.groupValues[1]}, ${m.groupValues[3]}.") as? Ability.Static ?: return@let
            if (inner.condition != null) return@let
            return inner.copy(condition = Conditions.condition(m.groupValues[2], self) ?: return@let)
        }
        // ltr chunk 13: "Whenever another creature dealt damage this turn by a Spider you controlled dies, create a token that's a copy of that creature,
        // except it's a Food artifact with "…," and it loses all other card types." (CR 707.9b, 603.10a)
        Ltr.COPY_THAT_DIED_EXCEPT_FOOD.matchEntire(line)?.let { m ->
            val dying = Filters.noun(m.groupValues[1]) ?: return@let
            val by = Filters.noun("${m.groupValues[2]} you control") ?: return@let
            val quoted = Sentences(setOf("this token")).line(m.groupValues[4] + ".") ?: return@let
            return Ability.Triggered(arcanum.api.Trigger.On(EventPattern.ZoneChange(Filters.all(dying, ObjectFilter.ThisTurn(EventPattern.Damage(by, RecipientFilter()), role = EventRole.Object)),
                from = Zone.Battlefield, to = Zone.Graveyard)), Instructions(steps = listOf(Step.Do(Effect.CreateToken(arcanum.api.TokenSpec.CopyOf(Objects.EventObject(EventRole.Before), listOf(
                    arcanum.api.CopyException.Types(add = listOf(CardType.Artifact), addSubtypes = listOf(arcanum.api.SubtypeRef.Literal(Subtype(m.groupValues[3]))), replaceTypes = true),
                    arcanum.api.CopyException.AddAbilities(listOf(quoted)))), Value.Fixed(1), Players.You)))))
        }
        // ltr chunk 12: "Whenever King of the Forsworn or another Spirit you control becomes the target of a spell, it phases out." (CR 702.26)
        Ltr.BECOMES_TARGET_OF_A_SPELL_PHASES_OUT.matchEntire(line)?.let { m ->
            val subject = m.groupValues[1].removePrefix("Whenever ")
            val objects = ltrSelfOrAnother(subject) ?: return@let
            return Ability.Triggered(arcanum.api.Trigger.On(EventPattern.BecomesTarget(objects, ObjectFilter.Category(arcanum.api.ObjectCategory.Spell))),
                Instructions(steps = listOf(Step.Do(Effect.PhaseOut(Objects.EventObject(EventRole.Object))))))
        }
        // fdn chunk 11c: "{T}: Add {R}. When that mana is spent to cast a red instant or sorcery spell, copy that spell and you may choose new targets
        // for the copy." (a delayed trigger for the mana, CR 106.6, 603.7a): the copy step runs only if the spell is of that kind
        Fdn.ADD_WHEN_THAT_MANA_SPENT.matchEntire(line)?.let { m ->
            val inner = line(m.groupValues[1]) as? Ability.Activated ?: return@let
            val add = (inner.instructions.steps.singleOrNull() as? Step.Do)?.effect as? Effect.AddMana ?: return@let
            val spell = Filters.noun(m.groupValues[2]) ?: return@let
            if (m.groupValues[3] != "copy that spell and you may choose new targets for the copy") return@let
            val copy = Step.Do(Effect.CopySpell(Objects.EventObject(EventRole.Object), controller = Players.You, newTargets = true))
            val then = Instructions(steps = listOf(Step.If(arcanum.api.Condition.ObjectMatches(Objects.EventObject(EventRole.Object), spell), listOf(copy))))
            return inner.copy(instructions = inner.instructions.copy(steps = listOf(Step.Do(add.copy(mana = add.mana.copy(whenSpent = then))))))
        }
        // fdn: "{T}: Add {R}. If that mana is spent on a Dragon creature spell, it gains haste until end of turn." (the spell, and the permanent it
        // becomes, get it only if it is of that kind, CR 106.6a)
        Fdn.ADD_SPELL_GAINS_KEYWORD_UNTIL_EOT.matchEntire(line)?.let { m ->
            val inner = line(m.groupValues[1]) as? Ability.Activated ?: return@let
            val add = (inner.instructions.steps.singleOrNull() as? Step.Do)?.effect as? Effect.AddMana ?: return@let
            val spell = Filters.noun(m.groupValues[2]) ?: return@let
            val keyword = OracleParser.keyword(m.groupValues[3]) ?: return@let
            return inner.copy(instructions = inner.instructions.copy(steps = listOf(Step.Do(add.copy(mana = add.mana.copy(
                spellGets = listOf(Mechanic.GainAbilities(listOf(keyword))), spellGetsIf = spell, spellGetsUntil = arcanum.api.Duration.EndOfTurn))))))
        }
        // ltr chunk 09: "{T}: Add one mana of any color. Spend this mana only to cast a legendary spell, and that spell can't be countered." (CR 106.6)
        Ltr.SPEND_ONLY_AND_CANT_BE_COUNTERED.matchEntire(line)?.let { m ->
            val inner = line("${m.groupValues[1]} Spend this mana only to cast ${m.groupValues[2].let { if (it.first() in "aeiou") "an" else "a" }} ${m.groupValues[2]} spell.")
                as? Ability.Activated ?: return@let
            val step = inner.instructions.steps.singleOrNull() as? Step.Do ?: return@let
            val add = step.effect as? Effect.AddMana ?: return@let
            return inner.copy(instructions = inner.instructions.copy(steps = listOf(Step.Do(add.copy(mana = add.mana.copy(spellGets = listOf(Mechanic.CantBeCountered)))))))
        }
        // ltr chunk 06: "When this creature enters and whenever an opponent draws a card except the first one …, [effect]" (one ability, two events)
        Ltr.WHEN_ENTERS_AND_WHENEVER.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) && it.groupValues[2].startsWith("an opponent ") }?.let { m ->
            val other = triggered("Whenever ${m.groupValues[2]}, ${m.groupValues[3]}") as? Ability.Triggered ?: return@let
            val on = other.trigger as? arcanum.api.Trigger.On ?: return@let
            if (on.events.size != 1 || other.interveningIf != null || other.triggersOnlyIf != null) return@let
            return other.copy(trigger = on.copy(events = listOf(EventPattern.ZoneChange(ObjectFilter.Is(Objects.Self), to = Zone.Battlefield)) + on.events))
        }
        // ltr chunk 06: "Whenever one or more creatures deal combat damage to you, each opponent sacrifices a creature of their choice that dealt combat
        // damage to you this turn. The Ring tempts you." (CR 510.1)
        Ltr.CREATURES_DEAL_COMBAT_DAMAGE_TO_YOU_SACRIFICE.matchEntire(line)?.let { m ->
            val rest = mutableListOf<Step>()
            val context = Context()
            for (r in sentences(m.groupValues[1])) rest += effect(r, context) ?: return@let
            val toYou = arcanum.api.RecipientFilter(players = PlayerFilter.You)
            val creature = ObjectFilter.Type(CardType.Creature)
            return Ability.Triggered(arcanum.api.Trigger.On(listOf(EventPattern.Damage(creature, toYou, combat = true)), oneOrMore = true), Instructions(steps = listOf(
                Step.ForEach(arcanum.api.Each.Players(Players.Each(PlayerFilter.Opponent)), "player", listOf(
                    Step.Choose(arcanum.api.Choice.Objects(Filters.all(creature, ObjectFilter.ControlledBy(PlayerFilter.Is(Players.Bound("player"))),
                        ObjectFilter.ThisTurn(EventPattern.Damage(ObjectFilter.Any, toYou, combat = true), role = EventRole.Source)), Value.Fixed(1), Value.Fixed(1)),
                        bind = "sacrificed", chooser = Players.Bound("player")),
                    Step.Do(Effect.Sacrifice(Objects.Bound("sacrificed")))), together = true)) + rest))
        }
        // ltr chunk 03: "Whenever you scry, if you control an Island, you may exile this card from your graveyard. If you do, draw a card." (works in
        // the graveyard, CR 113.6; the exile a cost paid on resolution, CR 118.12)
        Ltr.IF_MAY_EXILE_THIS_FROM_GRAVEYARD.matchEntire(line)?.let { m ->
            val inner = triggered("${m.groupValues[1]}, ${m.groupValues[3]}") as? Ability.Triggered ?: return@let
            val condition = Conditions.condition(m.groupValues[2], self) ?: return@let
            return inner.copy(interveningIf = condition, functionsIn = listOf(Zone.Graveyard), instructions = inner.instructions.copy(steps = listOf(
                Step.Pay(Cost(listOf(CostPart.Exile(CostObjects.Self, from = Zone.Graveyard))), payer = Players.You, bind = "paid"),
                Step.If(arcanum.api.Condition.Did("paid"), then = inner.instructions.steps))))
        }
        // ltr chunk 01: "Whenever an opponent casts a spell, if no mana was spent to cast it, counter that spell." (CR 601.2h, 603.4)
        Ltr.WHENEVER_IF_NO_MANA_SPENT.matchEntire(line)?.let { m ->
            val inner = triggered("${m.groupValues[1]}, ${m.groupValues[2]}") as? Ability.Triggered ?: return@let
            if ((inner.trigger as? arcanum.api.Trigger.On)?.events?.singleOrNull() !is EventPattern.Cast || inner.interveningIf != null) return@let
            return inner.copy(interveningIf = arcanum.api.Condition.Compare(Value.ManaSpent(of = Objects.EventObject(EventRole.Object)),
                arcanum.api.Comparison.Equal, Value.Fixed(0)))
        }
        return null
    }

    /** ltr: static abilities. */
    private fun ltrStatic(line: String): Ability? {
        // ltr chunk 14: "Equipped creature has first strike as long as it's blocking or blocked by a Goblin or Orc." (CR 509.1h)
        Ltr.HAS_AS_LONG_AS_BLOCKING_OR_BLOCKED_BY.matchEntire(line)?.let { m ->
            val keywords = keywords(m.groupValues[1]) ?: return@let
            val other = Objects.Each(ltrNouns(m.groupValues[2]) ?: return@let)
            val equipped = Objects.AttachedTo(Objects.Self)
            return Ability.Static(listOf(Mechanic.GainAbilities(keywords)), affects = Affected.Objects(equipped),
                condition = arcanum.api.Condition.ObjectMatches(equipped, ObjectFilter.Or(listOf(ObjectFilter.Blocking(other), ObjectFilter.BlockedBy(other)))))
        }
        // ltr chunk 13: "Activated abilities of lands your opponents control can't be activated unless they're mana abilities." (CR 605)
        Ltr.LANDS_ABILITIES_CANT_BE_ACTIVATED_UNLESS_MANA.matchEntire(line)?.let { m ->
            val objects = Filters.objects(m.groupValues[1]) ?: return@let
            return Ability.Static(listOf(Mechanic.CantBeActivated(manaAbilities = false)), affects = Affected.Objects(objects))
        }
        // ltr chunk 13: "Sandyman has all activated abilities of lands your opponents control except mana abilities." (CR 613.1f)
        Ltr.HAS_ALL_ACTIVATED_ABILITIES_EXCEPT_MANA.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val objects = Filters.objects(m.groupValues[2]) ?: return@let
            return ltrSelfStatic(Mechanic.GainAbilitiesOf(objects, exceptMana = true))
        }
        // ltr chunk 13: "Mana of any type can be spent to activate Sandyman's abilities."
        Ltr.MANA_OF_ANY_TYPE_TO_ACTIVATE_SELFS.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            return Ability.Static(listOf(Mechanic.SpendManaAsAnyColor(onlyFor = ObjectFilter.AbilityOf(source = ObjectFilter.Is(Objects.Self)))), affects = Affected.Players(Players.You))
        }
        // ltr chunk 11: "This spell costs {1} less to cast for each permanent sacrificed this turn." (by any player, CR 601.2f)
        Ltr.COSTS_LESS_FOR_EACH_SACRIFICED_THIS_TURN.matchEntire(line)?.let { m ->
            val noun = Filters.noun(m.groupValues[2]) ?: return@let
            return ltrSelfStatic(Mechanic.CostChange(ObjectFilter.Is(Objects.Self), arcanum.api.CostChange.Less(ManaCost.parse(m.groupValues[1]) ?: return@let,
                Value.EventsThisTurn(EventPattern.Sacrifice(noun), arcanum.api.Measure.Objects))))
        }
        // ltr chunk 10: "If one or more tokens would be created under your control, those tokens plus an additional Food token are created instead."
        // (CR 614.1a)
        Ltr.TOKENS_PLUS_ADDITIONAL.matchEntire(line)?.let { m ->
            val token = (((effect("Create a ${m.groupValues[1]} token.", Context())?.singleOrNull() as? Step.Do)?.effect) as? Effect.CreateToken)?.token ?: return@let
            return ltrSelfStatic(Mechanic.Replacement(EventPattern.CreateToken(ObjectFilter.ControlledBy(PlayerFilter.You)),
                modify = listOf(Modification.AlsoCreate(token, Value.Fixed(1)))))
        }
        // ltr chunk 07: "As long as equipped creature is legendary, it has menace."
        Ltr.AS_LONG_AS_EQUIPPED_IS_IT_HAS.matchEntire(line)?.let { m ->
            val filter = if (m.groupValues[1] == "legendary") ObjectFilter.Super(Supertype.Legendary) else Filters.noun(m.groupValues[1].removeArticle()) ?: return@let
            val keywords = keywords(m.groupValues[2]) ?: return@let
            return Ability.Static(listOf(Mechanic.GainAbilities(keywords)), affects = Affected.Objects(Objects.AttachedTo(Objects.Self)),
                condition = arcanum.api.Condition.ObjectMatches(Objects.AttachedTo(Objects.Self), filter))
        }
        // ltr chunk 08: "This creature can't block unless you control a Goblin or Orc." (CR 509.1c)
        Ltr.CANT_BLOCK_UNLESS_YOU_CONTROL.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val noun = ltrNouns(m.groupValues[2].removeArticle()) ?: return@let
            return Ability.Static(listOf(Mechanic.CantBlock(attackers = ObjectFilter.Any)), affects = Affected.Objects(Objects.Self),
                condition = arcanum.api.Condition.Not(arcanum.api.Condition.Exists(Filters.all(noun, ObjectFilter.ControlledBy(PlayerFilter.You)), atLeast = 1)))
        }
        // ltr chunk 06: "A deck can have up to nine cards named Ringwight." (CR 100.2a)
        Ltr.UP_TO_N_IN_DECK.matchEntire(line)?.takeIf { isSelf(it.groupValues[2]) }?.let { m ->
            return ltrSelfStatic(Mechanic.UpToInDeck(Numbers.count(m.groupValues[1]) ?: return@let))
        }
        // ltr chunk 05: "This spell costs {3} less to cast if it targets a creature that was dealt damage this turn." (CR 601.2f, 120.3)
        Ltr.COSTS_LESS_IF_TARGETS_DEALT_DAMAGE.matchEntire(line)?.let { m ->
            return ltrSelfStatic(Mechanic.CostChange(ObjectFilter.Is(Objects.Self), arcanum.api.CostChange.Less(ManaCost.parse(m.groupValues[1]) ?: return@let, Value.Fixed(1))))
                .copy(condition = arcanum.api.Condition.ObjectMatches(Objects.Target(Filters.slotName(m.groupValues[2])),
                    ObjectFilter.ThisTurn(EventPattern.Damage(ObjectFilter.Any, RecipientFilter()), role = EventRole.Object)))
        }
        // ltr chunk 05: "Your opponents can't gain life." (CR 119.7)
        if (Ltr.YOUR_OPPONENTS_CANT_GAIN_LIFE.matches(line))
            return Ability.Static(listOf(Mechanic.CantGainLife), affects = Affected.Players(Players.Each(PlayerFilter.Opponent)))
        // ltr chunk 05: "As long as it's your turn and you control an Army, Grundor is an artifact creature." (CR 301.7)
        Ltr.AS_LONG_AS_YOUR_TURN_AND_IS_ARTIFACT_CREATURE.matchEntire(line)?.takeIf { isSelf(it.groupValues[2]) }?.let { m ->
            val other = Conditions.condition(m.groupValues[1], self) ?: return@let
            return Ability.Static(listOf(Mechanic.SetTypes(add = listOf(CardType.Artifact, CardType.Creature))), affects = Affected.Objects(Objects.Self),
                condition = arcanum.api.Condition.And(listOf(arcanum.api.Condition.YourTurn, other)))
        }
        // ltr chunk 03: "If this creature would untap during your untap step, remove a +1/+1 counter from it instead. If you do, untap it."
        Ltr.UNTAP_REPLACED_BY_REMOVING_COUNTER.matchEntire(line)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            return ltrSelfStatic(Mechanic.UntapReplacedByRemovingCounter(Counters.kind(m.groupValues[2]) ?: return@let))
        }
        // ltr chunk 01: "Enchanted creature is a Spirit and can't attack or block." (a new creature type replaces the others, CR 205.1b)
        Ltr.IS_A_SUBTYPE_AND.matchEntire(line)?.let { m ->
            if (m.groupValues[2] !in RulesWords.subtypes) return@let
            val rest = static("${m.groupValues[1]} ${m.groupValues[3]}.") as? Ability.Static ?: return@let
            return Ability.Static(listOf(Mechanic.SetTypes(addSubtypes = listOf(arcanum.api.SubtypeRef.Literal(Subtype(m.groupValues[2]))), replaceSubtypes = true)) +
                rest.mechanics, affects = rest.affects)
        }
        // ltr chunk 01: "Equip abilities you activate cost {1} less to activate." (CR 601.2f, 602.2b)
        Ltr.EQUIP_ABILITIES_COST_LESS.matchEntire(line)?.let { m ->
            return ltrSelfStatic(Mechanic.CostChange(Filters.all(ltrEquipAbilities, ObjectFilter.ControlledBy(PlayerFilter.You)),
                arcanum.api.CostChange.Less(ManaCost.parse(m.groupValues[1]) ?: return@let, Value.Fixed(1))))
        }
        // ltr chunk 01: "During your turn, you may activate equip abilities any time you could cast an instant." (CR 602.5d)
        Ltr.DURING_YOUR_TURN_ACTIVATE_AT_INSTANT_SPEED.matchEntire(line)?.takeIf { it.groupValues[1] == "equip" }?.let {
            return Ability.Static(listOf(Mechanic.ActivateAtInstantSpeed(ltrEquipAbilities)), affects = Affected.Players(Players.You),
                condition = arcanum.api.Condition.YourTurn)
        }
        // ltr chunk 01: "If a legendary permanent or an artifact entering or leaving the battlefield causes a triggered ability of a permanent you
        // control to trigger, that ability triggers an additional time." (CR 603.2d: either event)
        Ltr.ENTERING_OR_LEAVING_TRIGGERS_ADDITIONAL.matchEntire(line)?.let { m ->
            val objects = ltrNouns(m.groupValues[1]) ?: return@let
            val sources = Filters.noun(m.groupValues[2].removePrefix("a ").removePrefix("an ")) ?: return@let
            return ltrSelfStatic(
                Mechanic.TriggersAdditionalTime(EventPattern.ZoneChange(objects, to = Zone.Battlefield), sources),
                Mechanic.TriggersAdditionalTime(EventPattern.ZoneChange(objects, from = Zone.Battlefield), sources))
        }
        return null
    }

    /** ltr chunk 04: "the amassed Army" (CR 701.47c) names the Army the amass instruction chose: the amass step binds it. */
    private fun ltrBindAmassedArmy(text: String, instructions: Instructions): Instructions {
        if (!text.contains("the amassed Army")) return instructions
        fun bind(step: Step): Step = when {
            step is Step.Do && step.effect is Effect.Action && (step.effect as Effect.Action).action is arcanum.api.KeywordAction.Amass &&
                (step.effect as Effect.Action).bind == null -> Step.Do((step.effect as Effect.Action).copy(bind = LtrPhrases.AMASSED_ARMY))
            step is Step.ForEach -> step.copy(steps = step.steps.map(::bind))
            else -> step
        }
        return instructions.copy(steps = instructions.steps.map(::bind))
    }

    /** ltr: trigger events, with a condition for the trigger to happen when the wording has one. */
    private fun ltrTrigger(events: String): Pair<arcanum.api.Trigger.On, arcanum.api.Condition?>? {
        // ltr chunk 12: "Whenever you attack with Berilac and another legendary creature" (both declared as attackers, CR 508.1)
        Ltr.ATTACK_WITH_SELF_AND_ANOTHER.matchEntire(events)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val other = Filters.noun(m.groupValues[2]) ?: return@let
            return arcanum.api.Trigger.On(EventPattern.Attack(ObjectFilter.Is(Objects.Self))) to arcanum.api.Condition.Exists(Filters.all(
                ObjectFilter.Not(ObjectFilter.Is(Objects.Self)), other, ObjectFilter.HasStatus(arcanum.api.Status.Attacking)), atLeast = 1)
        }
        // ltr chunk 04: "Whenever you draw a card during an opponent's turn"
        if (Ltr.DRAW_DURING_OPPONENTS_TURN.matches(events))
            return arcanum.api.Trigger.On(EventPattern.Draw(PlayerFilter.You)) to arcanum.api.Condition.PlayerMatches(Players.Active, PlayerFilter.Opponent)
        return ltrTriggerEvents(events)?.let { it to null }
    }

    private fun ltrTriggerEvents(events: String): arcanum.api.Trigger.On? {
        // ltr chunk 13: "the final chapter ability of a Saga you control resolves" (CR 714.2c)
        Ltr.FINAL_CHAPTER_OF_A_SAGA_RESOLVES.matchEntire(events)?.let { m ->
            return arcanum.api.Trigger.On(EventPattern.FinalChapterResolves(Filters.noun(m.groupValues[1]) ?: return@let))
        }
        // ltr chunk 12: "King of the Forsworn or another Spirit you control phases in" (CR 702.26c)
        Ltr.PHASES_IN.matchEntire(events)?.let { m -> return arcanum.api.Trigger.On(EventPattern.PhaseIn(ltrSelfOrAnother(m.groupValues[1]) ?: return@let)) }
        // ltr chunk 11: "you put one or more counters on Arathorn" (put by your spells and abilities, one batch, CR 603.2c)
        Ltr.YOU_PUT_COUNTERS_ON.matchEntire(events)?.takeIf { isSelf(it.groupValues[1]) }?.let {
            return arcanum.api.Trigger.On(listOf(EventPattern.CountersPut(ObjectFilter.Is(Objects.Self), causedBy = ObjectFilter.ControlledBy(PlayerFilter.You))), oneOrMore = true)
        }
        // ltr chunk 07: "a creature an opponent controls is dealt excess noncombat damage" (CR 120.4a); the amount is the excess
        Ltr.IS_DEALT_EXCESS_NONCOMBAT_DAMAGE.matchEntire(events)?.let { m ->
            val noun = Filters.noun(m.groupValues[1]) ?: return@let
            return arcanum.api.Trigger.On(EventPattern.Damage(ObjectFilter.Any, RecipientFilter(objects = noun), combat = false, excess = true))
        }
        // ltr chunk 09: "you cast a spell that targets Haldir", "… that targets a creature you don't control" (CR 601.2c)
        Ltr.YOU_CAST_A_SPELL_THAT_TARGETS.matchEntire(events)?.let { m ->
            val objects = if (isSelf(m.groupValues[1])) Objects.Self else Filters.noun(m.groupValues[1].removeArticle())?.let { Objects.Each(it) } ?: return@let
            return arcanum.api.Trigger.On(EventPattern.Cast(ObjectFilter.Targets(objects = objects), PlayerFilter.You))
        }
        // ltr chunk 06: "an opponent draws a card except the first one they draw in each of their draw steps" (CR 504.1)
        if (events == "an opponent draws a card except the first one they draw in each of their draw steps")
            return arcanum.api.Trigger.On(EventPattern.Draw(PlayerFilter.Opponent, exceptFirstIn = arcanum.api.TurnStep.Draw))
        // ltr chunk 05: "Whenever you create or sacrifice a token" (CR 111.1, 701.21)
        if (Ltr.YOU_CREATE_OR_SACRIFICE_A_TOKEN.matches(events)) {
            val yours = ObjectFilter.ControlledBy(PlayerFilter.You)
            return arcanum.api.Trigger.On(listOf(EventPattern.CreateToken(yours),
                EventPattern.Sacrifice(Filters.all(ObjectFilter.Category(arcanum.api.ObjectCategory.Token), yours))))
        }
        // ltr chunk 02: "Whenever you create a token" (each token created, CR 111.1, 603.2)
        if (Ltr.YOU_CREATE_A_TOKEN.matches(events)) return arcanum.api.Trigger.On(EventPattern.CreateToken(ObjectFilter.ControlledBy(PlayerFilter.You)))
        // ltr chunk 01: "Whenever two or more creatures you control attack a player" (once for each player attacked by that many, CR 508.1)
        Ltr.N_OR_MORE_ATTACK_A_PLAYER.matchEntire(events)?.let { m ->
            val attackers = Filters.noun(m.groupValues[2]) ?: return@let
            return arcanum.api.Trigger.On(listOf(EventPattern.Attack(attackers, target = RecipientFilter(players = PlayerFilter.Any))),
                oneOrMore = true, atLeast = Numbers.count(m.groupValues[1]) ?: return@let, batchPerPlayer = true)
        }
        return null
    }

    /** ltr: "[this] or another [noun]": this object or another matching one. */
    private fun ltrSelfOrAnother(subject: String): ObjectFilter? {
        val parts = subject.split(" or another ")
        if (parts.size != 2 || !isSelf(parts[0])) return null
        return ObjectFilter.Or(listOf(ObjectFilter.Is(Objects.Self), Filters.all(ObjectFilter.Not(ObjectFilter.Is(Objects.Self)), Filters.noun(parts[1]) ?: return null)))
    }

    /** ltr: an ability's whole text, read before its sentences. */
    private fun ltrWhole(body: String, context: Context): List<Step>? {
        // ltr chunk 14: "Create two tapped 1/1 white Spirit creature tokens with flying. If that creature is legendary, instead create two of those
        // tokens that are tapped and attacking." (attacking whom their controller chooses, CR 508.4)
        Ltr.CREATE_IF_THAT_CREATURE_INSTEAD_ATTACKING.matchEntire(body)?.let { m ->
            val create = ((effect("${m.groupValues[1]}.", context)?.singleOrNull() as? Step.Do)?.effect as? Effect.CreateToken) ?: return@let
            val creature = ((context.event as? EventPattern.Attack)?.attacker as? ObjectFilter.Is)?.objects ?: context.it ?: return@let
            val quality = if (m.groupValues[2] == "legendary") ObjectFilter.Super(arcanum.api.Supertype.Legendary) else Filters.noun(m.groupValues[2]) ?: return@let
            val n = Numbers.count(m.groupValues[3]) ?: return@let
            return listOf(Step.If(arcanum.api.Condition.ObjectMatches(creature, quality),
                then = listOf(Step.Do(create.copy(count = Value.Fixed(n), tapped = true, attacking = arcanum.api.AttackTarget.Chosen))),
                otherwise = listOf(Step.Do(create))))
        }
        // ltr chunk 14: "… Then target opponent may have you draw a card. If that player doesn't, you mill X cards, where X is the number of influence
        // counters on Palantír, and that player loses life equal to the total mana value of those cards." (the opponent chooses, CR 101.4)
        Ltr.OPPONENT_MAY_HAVE_YOU_DRAW_ELSE_MILL.matchEntire(body)?.takeIf { isSelf(it.groupValues[3]) }?.let { m ->
            val first = mutableListOf<Step>()
            for (s in sentences(m.groupValues[1])) first += effect(s, context) ?: return@let
            val opponent = context.targetOpponent()
            val kind = Counters.kind(m.groupValues[2]) ?: return@let
            return first + listOf(Step.Pay(steps = listOf(Step.Do(Effect.Draw(Players.You, Value.Fixed(1)))), payer = opponent, bind = "paid"),
                Step.If(arcanum.api.Condition.Not(arcanum.api.Condition.Did("paid")), then = listOf(
                    Step.Do(Effect.Mill(Players.You, Value.Of(arcanum.api.NumericProperty.Counters(kind), Objects.Self, arcanum.api.Combine.Single), postBind = "milled")),
                    Step.Do(Effect.LoseLife(opponent, Value.Of(arcanum.api.NumericProperty.ManaValue, Objects.Bound("milled"), arcanum.api.Combine.Total))))))
        }
        // ltr chunk 13: "Attach up to one target Equipment to it. Then amass Orcs X, where X is the number of Equipment attached to Muzgash."
        Ltr.ATTACH_UP_TO_ONE_THEN_AMASS_ATTACHED.matchEntire(body)?.takeIf { it.groupValues[3].isEmpty() || isSelf(it.groupValues[3]) }?.let { m ->
            val equipment = ltrObjects(m.groupValues[1], context) ?: return@let
            val amass = (effect("Amass ${m.groupValues[2]} 1.", context)?.singleOrNull() as? Step.Do)?.effect as? Effect.Action ?: return@let
            val action = amass.action as? arcanum.api.KeywordAction.Amass ?: return@let
            val attached = Value.Count(Objects.AttachmentsOf(Objects.Self, ObjectFilter.Sub(Subtype("Equipment"))))
            return listOf(Step.Do(Effect.Attach(equipment, Recipients(objects = Objects.Self))), Step.Do(amass.copy(action = action.copy(count = attached))))
        }
        // ltr chunk 13: "Choose an opponent. They look at the top four cards of your library and separate them into a face-down pile and a face-up pile.
        // Put one pile into your hand and the other into your graveyard." (CR 700.3)
        Ltr.OPPONENT_SEPARATES_PILES.matchEntire(body)?.let { m ->
            val n = Numbers.count(m.groupValues[1]) ?: return@let
            val rest = mutableListOf<Step>()
            if (m.groupValues[2].isNotEmpty()) for (r in sentences(m.groupValues[2])) rest += effect(r, context) ?: return@let
            return listOf(Step.Choose(arcanum.api.Choice.Player(PlayerFilter.Opponent), bind = "opponent", chooser = Players.You),
                Step.Do(Effect.SeparatePiles(Objects.LibraryCards(Players.You, Value.Fixed(n), fromTop = true), separator = Players.Bound("opponent"), chooser = Players.You,
                    chosenBind = "chosen", otherBind = "other", faceDownPile = true)),
                Step.Do(Effect.Move(Objects.Bound("chosen"), Destination(Zone.Hand))), Step.Do(Effect.Move(Objects.Bound("other"), Destination(Zone.Graveyard)))) + rest
        }
        // ltr chunk 13: "Target opponent reveals cards from the top of their library until they reveal a land card. Put that card onto the battlefield
        // tapped under your control and the rest into their graveyard." (CR 701.20)
        Ltr.TARGET_OPPONENT_REVEALS_UNTIL_UNDER_YOUR_CONTROL.matchEntire(body)?.let { m ->
            val noun = Filters.noun(m.groupValues[1]) ?: return@let
            val opponent = ltrNewSlotName(context, "opponent")
            context.targets += TargetSlot(opponent, TargetKind.Players(PlayerFilter.Opponent), min = Value.Fixed(1), max = Value.Fixed(1))
            return listOf(Step.Do(Effect.RevealUntil(noun, Players.Target(opponent), Value.Fixed(1), reveal = true, foundBind = "found", restBind = "rest")),
                Step.Do(Effect.Move(Objects.Bound("found"), Destination(Zone.Battlefield, tapped = true, controller = Players.You))),
                Step.Do(Effect.Move(Objects.Bound("rest"), Destination(Zone.Graveyard))))
        }
        // ltr chunk 13: "Reveal cards from the top of your library until you reveal a Saga card. Put that card onto the battlefield and the rest on the bottom
        // of your library in a random order."
        Ltr.REVEAL_UNTIL_PUT_ONTO_BATTLEFIELD_REST_BOTTOM.matchEntire(body)?.let { m ->
            val noun = Filters.noun(m.groupValues[1]) ?: return@let
            return listOf(Step.Do(Effect.RevealUntil(noun, Players.You, Value.Fixed(1), reveal = true, foundBind = "found", restBind = "rest")),
                Step.Do(Effect.Move(Objects.Bound("found"), Destination(Zone.Battlefield))),
                Step.Do(Effect.Move(Objects.Bound("rest"), Destination(Zone.Library, libraryPosition = -1, randomOrder = true))))
        }
        // ltr chunk 13: "Each opponent mills two cards. When one or more cards are milled this way, exile target … card with equal or lesser mana value than
        // that spell from an opponent's graveyard. Copy the exiled card. You may cast the copy without paying its mana cost." (CR 603.12, 707.12)
        Ltr.OPPONENTS_MILL_WHEN_MILLED_EXILE_COPY_CAST.matchEntire(body)?.let { m ->
            val n = Numbers.count(m.groupValues[1]) ?: return@let
            val inner = Context()
            val card = ltrObjects(m.groupValues[2], inner) ?: return@let
            val slot = inner.targets.single()
            val kind = (slot.what as? TargetKind.Objects)?.filter ?: return@let
            val restricted = slot.copy(what = TargetKind.Objects(Filters.all(kind, ObjectFilter.InZone(Zone.Graveyard), ObjectFilter.OwnedBy(PlayerFilter.Opponent),
                ObjectFilter.ManaValue(arcanum.api.Comparison.AtMost, Value.Of(arcanum.api.NumericProperty.ManaValue, Objects.EventObject(EventRole.Object), arcanum.api.Combine.Single)))))
            return listOf(Step.Do(Effect.Mill(Players.Each(PlayerFilter.Opponent), Value.Fixed(n), postBind = "milled")),
                Step.If(arcanum.api.Condition.Compare(Value.Count(Objects.Bound("milled")), arcanum.api.Comparison.AtLeast, Value.Fixed(1)), then = listOf(
                    Step.Do(Effect.ReflexiveTrigger(Instructions(targets = listOf(restricted), steps = listOf(
                        Step.Do(Effect.Move(card, Destination(Zone.Exile), postBind = "exiled")),
                        Step.Do(Effect.CopyCard(Objects.Bound("exiled"), Players.You, "copy")),
                        Step.May(listOf(Step.Do(Effect.Cast(Objects.Bound("copy"), PlayKind.Cast, withoutPaying = true, caster = Players.You))), Players.You))))))))
        }
        // ltr chunk 12: "Each player sacrifices a creature of their choice. If you sacrificed a creature this way, you may return another permanent card
        // from your graveyard to the battlefield."; fdn chunk 07: "… a creature or planeswalker … If you sacrificed a permanent this way, … to your hand."
        Ltr.EACH_PLAYER_SACRIFICES_IF_YOU_DID_RETURN.matchEntire(body)?.let { m ->
            // whatever was sacrificed was a permanent, so "a permanent" is as sure as the same noun again
            if (m.groupValues[2] != m.groupValues[1] && m.groupValues[2] != "permanent") return@let
            val noun = Filters.noun(m.groupValues[1]) ?: return@let
            val card = Filters.noun(m.groupValues[3]) ?: return@let
            val to = if (m.groupValues[4] == "your hand") Zone.Hand else Zone.Battlefield
            // the creatures are chosen in APNAP order and sacrificed at once (CR 101.4); Alice's own is named to know whether she sacrificed one
            val yours = Objects.Bound("yours")
            return listOf(Step.Choose(arcanum.api.Choice.Objects(Filters.all(noun, ObjectFilter.ControlledBy(PlayerFilter.You)), Value.Fixed(1), Value.Fixed(1)),
                bind = "yours", chooser = Players.You),
                Step.Do(Effect.Sacrifice(yours, postBind = "your card")),
                Step.ForEach(arcanum.api.Each.Players(Players.Each(PlayerFilter.Opponent)), "player", listOf(
                    Step.Choose(arcanum.api.Choice.Objects(Filters.all(noun, ObjectFilter.ControlledBy(PlayerFilter.Is(Players.Bound("player")))), Value.Fixed(1), Value.Fixed(1)),
                        bind = "theirs", chooser = Players.Bound("player")), Step.Do(Effect.Sacrifice(Objects.Bound("theirs")))), together = true),
                Step.If(arcanum.api.Condition.NonEmpty("yours"), then = listOf(
                    Step.Choose(arcanum.api.Choice.Objects(Filters.all(card, ObjectFilter.InZone(Zone.Graveyard), ObjectFilter.OwnedBy(PlayerFilter.You),
                        ObjectFilter.Not(ObjectFilter.Is(Objects.Bound("your card")))), Value.Fixed(0), Value.Fixed(1)), bind = "returned", chooser = Players.You),
                    Step.Do(Effect.Move(Objects.Bound("returned"), Destination(to))))))
        }
        // ltr chunk 12: "Target player mills three cards. Then amass Orcs X, where X is the number of instant and sorcery cards in that player's graveyard."
        Ltr.TARGET_PLAYER_MILLS_THEN_AMASS_X.matchEntire(body)?.takeIf { it.groupValues[3].isNotEmpty() }?.let { m ->
            val n = Numbers.count(m.groupValues[1]) ?: return@let
            val cards = LtrPhrases.noun(m.groupValues[3]) ?: Filters.noun(m.groupValues[3].replace(" and ", " or ")) ?: return@let
            val player = ltrNewSlotName(context, "player")
            context.targets += TargetSlot(player, TargetKind.Players(PlayerFilter.Any), min = Value.Fixed(1), max = Value.Fixed(1))
            val amass = (effect("Amass ${m.groupValues[2]} 1.", context)?.singleOrNull() as? Step.Do)?.effect as? Effect.Action ?: return@let
            val action = amass.action as? arcanum.api.KeywordAction.Amass ?: return@let
            return listOf(Step.Do(Effect.Mill(Players.Target(player), Value.Fixed(n))),
                Step.Do(amass.copy(action = action.copy(count = Value.Count(Objects.Each(Filters.all(cards, ObjectFilter.InZone(Zone.Graveyard),
                    ObjectFilter.OwnedBy(PlayerFilter.Is(Players.Target(player))))))))))
        }
        // ltr chunk 12: "[This] deals X damage to target creature, where X is …. Excess damage is dealt to that creature's controller instead." (CR 120.4a)
        Ltr.DEALS_X_EXCESS_TO_CONTROLLER.matchEntire(body)?.takeIf { isSelf(it.groupValues[1]) }?.let { m ->
            val objects = ltrObjects(m.groupValues[2], context) ?: return@let
            val x = if (m.groupValues[3].isEmpty()) Value.Announced(name = "X") else Values.value(m.groupValues[3]) ?: return@let
            return listOf(Step.Do(Effect.DealDamage(Recipients(objects = objects), x, Objects.Self, bind = "damage")),
                Step.Do(Effect.DealDamage(Recipients(players = Players.ControllerOf(objects)), Value.Excess("damage"), Objects.Self)))
        }
        // ltr chunk 11: "You may reveal the top card of your library. If a land card is revealed this way, put it onto the battlefield tapped."
        Ltr.MAY_REVEAL_TOP_IF_REVEALED.matchEntire(body)?.let { m ->
            val filter = Filters.noun(m.groupValues[2]) ?: return@let
            val outer = context.it
            context.it = Objects.Bound("revealed")
            val then = effect(m.groupValues[3].replaceFirstChar { it.uppercase() }, context)
            context.it = outer
            // inr chunk 01: Delver looks first (CR 701.20b: only the player sees it), then may reveal that same card
            val look = if (m.groupValues[1].isEmpty()) emptyList()
                else listOf(Step.Do(Effect.LookAt(Objects.LibraryCards(Players.You, Value.Fixed(1), fromTop = true), players = Players.You)))
            return look + listOf(Step.May(listOf(Step.Do(Effect.Reveal(Objects.LibraryCards(Players.You, Value.Fixed(1), fromTop = true), bind = "revealed"))), Players.You),
                Step.If(arcanum.api.Condition.ObjectMatches(Objects.Bound("revealed"), filter), then = then ?: return@let))
        }
        // ltr chunk 11: Gates of the Dwarf Lord: a revealed creature put onto the battlefield tapped and attacking (CR 508.4), keywords by conditions
        Ltr.SCRY_REVEAL_ATTACKING_UNTIL_NEXT_TURN.matchEntire(body)?.let { m ->
            val n = Numbers.count(m.groupValues[1]) ?: return@let
            val filter = Filters.noun(m.groupValues[2]) ?: return@let
            fun keyword(word: String, type: String): Step? {
                val k = OracleParser.keyword(word.replaceFirstChar { it.uppercase() }) ?: return null
                if (type !in RulesWords.subtypes) return null
                return Step.If(arcanum.api.Condition.Exists(Filters.all(ObjectFilter.Sub(Subtype(type)), ObjectFilter.ControlledBy(PlayerFilter.You)), atLeast = 1), then = listOf(
                    Step.Do(Effect.ApplyMechanics(listOf(Mechanic.GainAbilities(listOf(k))), Affected.Objects(Objects.Bound("put")), arcanum.api.Duration.UntilYourNextTurn))))
            }
            return listOf(Step.Do(Effect.Scry(Players.You, Value.Fixed(n))),
                Step.May(listOf(Step.Do(Effect.Reveal(Objects.LibraryCards(Players.You, Value.Fixed(1), fromTop = true), bind = "revealed"))), Players.You),
                Step.If(arcanum.api.Condition.ObjectMatches(Objects.Bound("revealed"), filter), then = listOf(
                    Step.Do(Effect.Move(Objects.Bound("revealed"), Destination(Zone.Battlefield, tapped = true, attacking = arcanum.api.AttackTarget.Chosen), postBind = "put")),
                    keyword(m.groupValues[3], m.groupValues[4]) ?: return@let, keyword(m.groupValues[5], m.groupValues[6]) ?: return@let)))
        }
        // ltr chunk 11: "Target creature you control and up to one other target legendary creature you control each deal damage equal to their power to
        // target creature you don't control." (CR 120.3: each a source)
        Ltr.EACH_DEAL_DAMAGE_EQUAL_TO_THEIR_POWER.matchEntire(body)?.let { m ->
            val first = ltrObjects(m.groupValues[1], context) ?: return@let
            val second = ltrObjects(m.groupValues[2], context) ?: return@let
            val third = ltrObjects(m.groupValues[3], context) ?: return@let
            fun power(o: Objects) = Value.Of(arcanum.api.NumericProperty.Power, o, arcanum.api.Combine.Single)
            return listOf(Step.Do(Effect.DealDamage(Recipients(objects = third), power(first), first)), Step.Do(Effect.DealDamage(Recipients(objects = third), power(second), second)))
        }
        // ltr chunk 11: "Choose an opponent. At the beginning of that player's next end step, you draw a card if they didn't attack you that turn.
        // Otherwise, create three 1/1 white Human Soldier creature tokens." (CR 603.7)
        Ltr.CHOOSE_OPPONENT_NEXT_END_STEP.matchEntire(body)?.let { m ->
            val then = effect("${m.groupValues[1].replaceFirstChar { it.uppercase() }}.".replace("You draw a card.", "Draw a card."), context) ?: return@let
            val otherwise = effect(m.groupValues[2].replaceFirstChar { it.uppercase() }, context) ?: return@let
            return listOf(Step.Choose(arcanum.api.Choice.Player(PlayerFilter.Opponent), bind = "opponent", chooser = Players.You),
                Step.Do(Effect.CreateDelayedTrigger(arcanum.api.Trigger.On(EventPattern.StepBegins(arcanum.api.TurnStep.End, PlayerFilter.Is(Players.Bound("opponent")))),
                    Instructions(steps = listOf(Step.If(arcanum.api.Condition.Not(arcanum.api.Condition.HappenedThisTurn(EventPattern.Attack(ObjectFilter.Any,
                        target = RecipientFilter(players = PlayerFilter.You)), atLeast = 1, measure = arcanum.api.Measure.Events)), then = then, otherwise = otherwise))),
                    laterTurn = true)))
        }
        // ltr chunk 10: "Look at the top X cards of your library, where X is that creature's mana value. You may reveal a creature card that doesn't share
        // a creature type with a creature you control from among those cards and put it into your hand. Put the rest on the bottom …" (CR 700.8)
        Ltr.LOOK_TOP_X_MANA_VALUE_REVEAL_NOT_SHARING.matchEntire(body)?.let { m ->
            val noun = Filters.noun(m.groupValues[1]) ?: return@let
            val looked = Objects.LibraryCards(Players.You, Value.Of(arcanum.api.NumericProperty.ManaValue, Objects.EventObject(EventRole.After), arcanum.api.Combine.Single), fromTop = true)
            val yours = Filters.all(ObjectFilter.Type(CardType.Creature), ObjectFilter.ControlledBy(PlayerFilter.You))
            return listOf(Step.Do(Effect.LookAt(looked, Players.You, bind = "looked")),
